-- ============================================================
-- 圣经全文（新译本，神名已按公开发布本还原为「耶和华」）· 数据文件 2/6
-- 第二版：可覆盖第一版（冲突时更新经文）。已运行过第一版的直接运行本版即可。
-- 本文件 5200 节。
-- ============================================================
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '申命记', 5, 10, 14, '看哪，天和天上的天，地和地上的一切都是属于耶和华你的神的。'),
('CNV', '申命记', 5, 10, 15, '但耶和华只喜悦你的列祖，爱他们；他从万民中拣选了他们的后裔，就是你们，像今日一样。'),
('CNV', '申命记', 5, 10, 16, '所以你们要给你们的心行割礼，不可再顽固。'),
('CNV', '申命记', 5, 10, 17, '因为耶和华你们的神，他是万神之神、万主之主、伟大有力和可畏的神；他不徇情面，也不受贿赂。'),
('CNV', '申命记', 5, 10, 18, '他为孤儿寡妇伸张正义，又把衣食给寄居的人。'),
('CNV', '申命记', 5, 10, 19, '所以你们要爱寄居的人，因为你们在埃及地也作过寄居的人。'),
('CNV', '申命记', 5, 10, 20, '你要敬畏耶和华你的神，事奉他，依靠他，奉他的名起誓。'),
('CNV', '申命记', 5, 10, 21, '他是你当颂赞的；他是你的神，他为你作了那些大而可畏的事，就是你亲眼见过的。'),
('CNV', '申命记', 5, 10, 22, '你的列祖下到埃及的时候，一共不过七十人，现在耶和华你的神却使你的人数像天上的星那么多了。”'),
('CNV', '申命记', 5, 11, 1, '“所以你要爱耶和华你的神，常常遵守他的吩咐、律例、典章和诫命。'),
('CNV', '申命记', 5, 11, 2, '今日你们要知道，我并不是与你们的儿女说话，因为他们不知道，也没有见过耶和华你们的神的管教、伟大有力的手和伸出来的膀臂，'),
('CNV', '申命记', 5, 11, 3, '以及他在埃及向埃及王法老和法老的全国所行的神迹和作为；'),
('CNV', '申命记', 5, 11, 4, '他们也没有见过他怎样对待埃及的军队、马匹和车辆；他们追赶你们的时候，耶和华怎样使红海的水淹没了他们，把他们灭绝，这事一直传到今日；'),
('CNV', '申命记', 5, 11, 5, '并且耶和华在旷野怎样待你们，直到你们来到了这个地方；'),
('CNV', '申命记', 5, 11, 6, '也没有见过他怎样对待流本的子孙以利押的儿子大坍、亚比兰；大地怎样在全体以色列人中间裂开了，把他们和他们的家人、帐棚，以及与他们在一起一切有生命之物都吞下去；'),
('CNV', '申命记', 5, 11, 7, '只有你们亲眼看见了耶和华所作的一切伟大的作为。'),
('CNV', '申命记', 5, 11, 8, '“所以你们要遵守我今日吩咐你的一切诫命，使你们坚强起来，可以进去得着你们将要过去得的那地，'),
('CNV', '申命记', 5, 11, 9, '又使你们在耶和华向你们的列祖起誓应许赐给他们和他们后裔的地上，就是流奶与蜜的地，可以长久居住。'),
('CNV', '申命记', 5, 11, 10, '因为你要进去得的那地，并不像你出来的埃及地；在那里你撒了种，还要用脚灌溉，像菜园一样。'),
('CNV', '申命记', 5, 11, 11, '但你们要过去得为业的地，却是一个有山有谷的地，有天上雨水滋润的地，'),
('CNV', '申命记', 5, 11, 12, '就是耶和华你的神眷顾的地；从岁首到年终，耶和华你的神的眼目常常眷顾这地。'),
('CNV', '申命记', 5, 11, 13, '“如果你们留心听我今日吩咐你们的诫命，爱耶和华你们的神，一心一意事奉他，'),
('CNV', '申命记', 5, 11, 14, '他（按照《马索拉文本》，“他”作“我”﹔现参照其他抄本及古译本翻译﹔15节同）必按时降雨在你们的地上，就是降秋雨和春雨，使你们可以丰收五谷、新酒和新油。'),
('CNV', '申命记', 5, 11, 15, '他也必使田野为你的牲畜长出青草来，你也可以吃得饱足。'),
('CNV', '申命记', 5, 11, 16, '你们要谨慎，免得你们的心受迷惑，你们就偏离了我，去事奉别的神，并且敬拜它们；'),
('CNV', '申命记', 5, 11, 17, '叫耶和华的怒气向你发作，就把天封闭，不降下雨水，地也不生出土产，使你们从耶和华赐给你们的美地上，快快地灭亡。'),
('CNV', '申命记', 5, 11, 18, '“所以你们要把我这些话放在心里，存在意念中；要系在手上作记号，戴在额上作头带。'),
('CNV', '申命记', 5, 11, 19, '你们也要把这些话教训你们的儿女，无论你是坐在家里，行在路上，躺下，或是起来，都要讲论。'),
('CNV', '申命记', 5, 11, 20, '你要把这些话写在你房屋的门柱上和城门上，'),
('CNV', '申命记', 5, 11, 21, '为要叫你们和你们的子孙的日子，在耶和华向你们列祖起誓应许给他们的地上，可以增多，像天覆地的年日那样多。'),
('CNV', '申命记', 5, 11, 22, '如果你们殷勤谨守遵行我吩咐你们的这一切诫命，爱耶和华你们的神，行他的一切道路，又紧紧地依靠他，'),
('CNV', '申命记', 5, 11, 23, '耶和华就必从你们面前把这些国民都赶出去，你们就必占领比你们大比你们强的国民的地。'),
('CNV', '申命记', 5, 11, 24, '你们脚掌所踏的地，都必属于你们；从旷野到黎巴嫩，从幼发拉底河直到西海，都要作你们的境界。'),
('CNV', '申命记', 5, 11, 25, '必没有一人能在你们面前站立得住；耶和华你们的神，必照着他对你们所说的，使害怕和惊惧你们的心临到你们将要踏足之地的居民。'),
('CNV', '申命记', 5, 11, 26, '“看哪，我今日把祝福和咒诅都摆在你们面前。'),
('CNV', '申命记', 5, 11, 27, '如果你们听从耶和华你们的神的诫命，就是我今日吩咐你们的，你们就必蒙赐福；'),
('CNV', '申命记', 5, 11, 28, '如果你们不听从耶和华你们的神的诫命，偏离了我今日吩咐你们要走的道路，去随从你们素来不认识的别神，你们就必受咒诅。'),
('CNV', '申命记', 5, 11, 29, '耶和华你的神领你进入你要占领为业之地以后，你就要把祝福摆在基利心山上，把咒诅摆在以巴路山上。'),
('CNV', '申命记', 5, 11, 30, '这两座山不是在约旦河西、日落的地方，在住亚拉巴的迦南人之地，与吉甲相对，靠近摩利橡树那里吗？'),
('CNV', '申命记', 5, 11, 31, '现在你们快要过约旦河，进去得耶和华你们的神要赐给你们为业之地；你们取得了那地，就住在那里。'),
('CNV', '申命记', 5, 11, 32, '你们要谨守遵行我今日在你们的面前颁布的一切律例和典章。”'),
('CNV', '申命记', 5, 12, 1, '“你们活在地上的一切日子，在耶和华你列祖的神赐给你作产业的地上，要谨守遵行的律例和典章，就是这些：'),
('CNV', '申命记', 5, 12, 2, '你们要把你们赶走的列国的人事奉神的地方，无论是在高山上，在山冈上，或是在各青翠树下，都要完全毁坏；'),
('CNV', '申命记', 5, 12, 3, '也要拆毁他们的祭坛，打碎他们的神柱；用火焚烧他们的亚舍拉，砍倒他们的神的雕像，并且把他们的名字从这地方除灭。'),
('CNV', '申命记', 5, 12, 4, '你们不可像他们那样事奉耶和华你的神。'),
('CNV', '申命记', 5, 12, 5, '耶和华你们的神从你们各支派中，选择了什么地方作立他名的居所，你们就当到那里求问他；'),
('CNV', '申命记', 5, 12, 6, '把你们的燔祭和其他的祭物、十分之一的礼物和手中的贡献、还愿祭和甘心祭，以及牛群羊群中头生的，都要带到那里去；'),
('CNV', '申命记', 5, 12, 7, '在那里，就是在耶和华你们的神面前，你们和你们的家人都可以吃；并且要因你们手所作的一切事，都蒙耶和华你的神赐福而欢乐。'),
('CNV', '申命记', 5, 12, 8, '我们今日在这里所行的，是行各人看为正的事，你们将来不可以这样行；'),
('CNV', '申命记', 5, 12, 9, '因为你们现在还没有到耶和华你的神赐给你的安息地和产业。'),
('CNV', '申命记', 5, 12, 10, '但是你们过了约旦河，住在耶和华你们的神使你们承受为业的地，又使你们太平，脱离你们周围的所有仇敌，安居乐业，'),
('CNV', '申命记', 5, 12, 11, '那时，你要把我吩咐你们的燔祭和其他的祭物、十分之一的礼物和手中的贡献，以及你们向耶和华许愿要献的最美的一切还愿祭，都要带到耶和华你们的神选择作为立他名的地方。'),
('CNV', '申命记', 5, 12, 12, '你们和你们的儿女、仆婢，以及住在你们城里的利未人，都要在耶和华你们的神面前欢乐，因为利未人在你们中间无分无业。'),
('CNV', '申命记', 5, 12, 13, '你要自己谨慎，不可在你看见的任何地方献上你的燔祭；'),
('CNV', '申命记', 5, 12, 14, '只要在耶和华从你的一个支派中拣选的地方，在那里献上你的燔祭，在那里行我吩咐你的一切事。'),
('CNV', '申命记', 5, 12, 15, '“不过在你的各城里，你都可以照着耶和华你的神赐给你的福分，随意杀牲吃肉。不洁净的人和洁净的人都可以吃，像吃羚羊和鹿的肉一样。'),
('CNV', '申命记', 5, 12, 16, '只有血，你们不可吃；要倒在地上，像倒水一样。'),
('CNV', '申命记', 5, 12, 17, '你的五谷、新酒和新油的十分之一，你牛群羊群中头生的和你所许一切还愿的祭、你甘心献的祭和你手中的贡献，都不可在你的城里吃；'),
('CNV', '申命记', 5, 12, 18, '你只要在耶和华你的神面前，和在耶和华你的神选择的地方吃，你和你的儿女、仆婢，以及在你城里的利未人，都可以吃；你也要因你手所作的一切事在耶和华你的神面前欢乐。'),
('CNV', '申命记', 5, 12, 19, '你要自己谨慎，你在你那地上的日子，永不可丢弃利未人。'),
('CNV', '申命记', 5, 12, 20, '“耶和华你的神，照着他应许你的，扩张了你的境界的时候，如果你因心里渴想吃肉，说：‘我想吃肉。’那么，你就可以随意吃肉。'),
('CNV', '申命记', 5, 12, 21, '耶和华你的神选择作立他名的地方，如果离开你太远，你就可以照着我吩咐你的，把耶和华赐给你的牛羊取些宰杀了，可以在你的城里随意地吃。'),
('CNV', '申命记', 5, 12, 22, '你吃那肉，好像人吃羚羊和鹿的肉一样；不洁净的人和洁净的人都可以一起吃。'),
('CNV', '申命记', 5, 12, 23, '只是你要心意坚定，不可吃血，因为血就是生命；你不可把生命和肉一起吃。'),
('CNV', '申命记', 5, 12, 24, '你不可吃血，要倒在地上，像倒水一样。'),
('CNV', '申命记', 5, 12, 25, '你不可吃血，好使你和你的子子孙孙得享福乐，因为你行了耶和华看为正的事。'),
('CNV', '申命记', 5, 12, 26, '只是你要把你应有的圣物和你的还愿祭，都带到耶和华选择的地方去，'),
('CNV', '申命记', 5, 12, 27, '把你的燔祭、肉和血，都献在耶和华你的神的祭坛上；其他的祭的血，要倒在耶和华你的神的祭坛上；至于那肉，你却可以吃。'),
('CNV', '申命记', 5, 12, 28, '你要谨慎听从我吩咐你的这一切话，好使你和你的子子孙孙永远得享福乐，因为你行了耶和华看为好为正的事。'),
('CNV', '申命记', 5, 12, 29, '“耶和华你的神把你将要进去赶走的列国的民，从你的面前除灭以后，你就得着他们的地，住在那里。'),
('CNV', '申命记', 5, 12, 30, '那时，你要自己谨慎，不可在他们从你的面前被消灭以后，随从他们的恶俗而陷入网罗，也不可求问他们的神，说：‘这些国的人怎样事奉他们的神，我也要这样行。’'),
('CNV', '申命记', 5, 12, 31, '你不可向耶和华你的神这样行，因为耶和华恨恶的一切可厌恶的事，他们都向他们的神行了，甚至把自己的儿女用火焚烧，献给他们的神。'),
('CNV', '申命记', 5, 12, 32, '“我吩咐你们的一切话，你们都要谨守遵行，不可加添，也不可减少。”（本节在《马索拉文本》为13:1）'),
('CNV', '申命记', 5, 13, 1, '“你们中间如果有先知，或作梦的人兴起来，给你显示神迹或奇事；（本节在《马索拉文本》为13:2）'),
('CNV', '申命记', 5, 13, 2, '他告诉你的神迹和奇事应验了，以致他对你说：‘我们去随从别的、你不认识的神，事奉他们吧。’'),
('CNV', '申命记', 5, 13, 3, '你不可听从那先知或作梦的人的话；因为耶和华你们的神试验你们，要知道你们是不是一心一意爱耶和华你们的神。'),
('CNV', '申命记', 5, 13, 4, '你们要顺从耶和华你们的神，敬畏他，遵守他的诫命，听从他的话，事奉他，紧靠他。'),
('CNV', '申命记', 5, 13, 5, '至于那先知，或作梦的人，你们要把他处死，因为他说了叛逆的话，叛逆了那领你们出埃及地，救赎你脱离为奴之家的耶和华你们的神，要你离弃耶和华你的神吩咐你走的道路。这样你就把那恶从你们中间除掉了。'),
('CNV', '申命记', 5, 13, 6, '“你的同母兄弟或你的儿女，你怀中的妻子或视你如自己性命的朋友，如果暗中引诱你，说：‘我们去事奉别的神吧。’就是你和你的列祖向来不认识的，'),
('CNV', '申命记', 5, 13, 7, '是你们周围各族的神，无论是离你近的，或是离你远的神；从地这边直到地那边的神，'),
('CNV', '申命记', 5, 13, 8, '你都不可依从他，也不可听从他；你的眼不可顾惜他，你不可怜悯他，也不可袒护他；'),
('CNV', '申命记', 5, 13, 9, '总要把他杀死，你要先向他动手，然后全民才动手打死他。'),
('CNV', '申命记', 5, 13, 10, '你要用石头打死他，因为他要使你离弃那领你出埃及地，脱离为奴之家的耶和华你的神。'),
('CNV', '申命记', 5, 13, 11, '这样，全以色列听见了，必然害怕，就不会再在你们中间行这样的恶了。'),
('CNV', '申命记', 5, 13, 12, '“在耶和华你的神赐给你居住的一座城中，如果你听说'),
('CNV', '申命记', 5, 13, 13, '有些匪徒从你中间出来，把本城的居民引离，说：‘我们去事奉别的神吧。’那些神是你们素来不认识的；'),
('CNV', '申命记', 5, 13, 14, '你就要调查、研究，仔细访问，如果的确有这可厌恶的事行在你们中间，'),
('CNV', '申命记', 5, 13, 15, '你就要用刀剑把那城里的居民杀掉，把那城和城里的一切，以及牲畜，都用刀剑完全毁灭。'),
('CNV', '申命记', 5, 13, 16, '并且把从城里掠夺的一切战利品，都要收集在那城的广场上，用火把城和在城里掠夺的一切战利品焚烧，献给耶和华你的神；那城就要永远成为废墟，不可再建造。'),
('CNV', '申命记', 5, 13, 17, '那当毁灭的物，一点也不可留在你手中，好使耶和华转意不发烈怒，反而向你施恩，怜悯你，照着他向你的列祖所起的誓，使你的人数增多；'),
('CNV', '申命记', 5, 13, 18, '只要你听从耶和华你的神的话，遵守我今日吩咐你的一切诫命，实行耶和华你的神看为正的事，就必这样。”'),
('CNV', '申命记', 5, 14, 1, '“你们是耶和华你们的神的儿女，不可为了死人割伤自己的身体，也不可使你们的额上光秃；'),
('CNV', '申命记', 5, 14, 2, '因为你是属于耶和华你的神的圣洁子民；耶和华从地上的万民中拣选了你们，特作他自己的子民。'),
('CNV', '申命记', 5, 14, 3, '“可厌恶之物，你都不可吃。'),
('CNV', '申命记', 5, 14, 4, '你们可以吃的牲畜是以下这些：牛、绵羊、山羊、'),
('CNV', '申命记', 5, 14, 5, '鹿、羚羊、赤鹿、野山羊、麋鹿、野羊、野鹿。'),
('CNV', '申命记', 5, 14, 6, '在走兽中，分蹄成两蹄趾，又反刍的走兽，你们都可以吃。'),
('CNV', '申命记', 5, 14, 7, '但是那些反刍或分蹄的走兽中，你们不可吃的有：骆驼、兔子和石獾，因为它们反刍却不分蹄，就对你们不洁净。'),
('CNV', '申命记', 5, 14, 8, '至于猪，因为它分蹄却不反刍，就对你们不洁净。它们的肉，你们不可吃；它们的尸体，你们不可触摸。'),
('CNV', '申命记', 5, 14, 9, '“在水中，你们可以吃的，有以下这些：有鳍有鳞的，你们都可以吃。'),
('CNV', '申命记', 5, 14, 10, '没有鳍没有鳞的，你们都不可吃；这是对你们不洁净的。'),
('CNV', '申命记', 5, 14, 11, '“洁净的鸟类，你们都可以吃。'),
('CNV', '申命记', 5, 14, 12, '你们不可吃的鸟类有以下这些：鹰、狗头鹰、红头鹰、'),
('CNV', '申命记', 5, 14, 13, '鸢、隼、黑隼，以及这一类的鸟；'),
('CNV', '申命记', 5, 14, 14, '乌鸦和这一类的鸟；'),
('CNV', '申命记', 5, 14, 15, '驼鸟、夜鹰、海鹰、雀鹰，以及这一类的鸟；'),
('CNV', '申命记', 5, 14, 16, '小猫头鹰、猫头鹰、角鸱、'),
('CNV', '申命记', 5, 14, 17, '小枭、秃鵰、鱼鹰、'),
('CNV', '申命记', 5, 14, 18, '鹳、鹭，以及这一类的鸟；戴胜和蝙蝠。'),
('CNV', '申命记', 5, 14, 19, '有翅膀的昆虫，对你们都不洁净，你们都不可吃。'),
('CNV', '申命记', 5, 14, 20, '洁净的鸟类，你们都可以吃。'),
('CNV', '申命记', 5, 14, 21, '“自死的动物，你们都不可吃；可以送给你城里的寄居者吃，或是卖给外族人吃，因为你是归耶和华为圣的子民；不可用山羊羔母的奶煮山羊羔。'),
('CNV', '申命记', 5, 14, 22, '“你要把你撒种所产的，就是田地每年所出的，献上十分之一。'),
('CNV', '申命记', 5, 14, 23, '又要把你的五谷、新酒和新油的十分之一，以及你牛群羊群中头生的，在耶和华你的神面前吃，就是在他选择作他名的居所的地方吃，好使你可以学习常常敬畏耶和华你的神。'),
('CNV', '申命记', 5, 14, 24, '耶和华你的神赐福与你的时候，耶和华你的神选择要立为他名的地方，如果离你太远，那路又太长，使你不能把供物带到那里去；'),
('CNV', '申命记', 5, 14, 25, '你就可以换成银子，把银子拿在手里，到耶和华你的神选择的地方去，'),
('CNV', '申命记', 5, 14, 26, '你可以用这银子随意买牛羊、清酒和烈酒；你心想要的，都可以买；在那里，你和你的家人，都要在耶和华你的神面前吃喝欢乐。'),
('CNV', '申命记', 5, 14, 27, '住在你城里的利未人，你不可丢弃他，因为他在你们中间无分无业。'),
('CNV', '申命记', 5, 14, 28, '“每三年之末，你要把那一年的全部出产的十分之一取出来，积存在你的城里；'),
('CNV', '申命记', 5, 14, 29, '这样，利未人（因为他在你们中间无分无业），以及在你城里的寄居者和孤儿寡妇，就可以来，吃得饱足；好叫耶和华你的神在你手所作的一切事上，赐福给你。”'),
('CNV', '申命记', 5, 15, 1, '“每七年的最后一年，你要施行豁免。'),
('CNV', '申命记', 5, 15, 2, '豁免的方式是这样：债主都要把借给邻舍的一切豁免了，不可向邻舍和兄弟追讨，因为耶和华的豁免年已经宣告了。'),
('CNV', '申命记', 5, 15, 3, '如果借给外族人，你可以向他追讨，但借给你的兄弟，无论你借的是什么，你都要豁免。'),
('CNV', '申命记', 5, 15, 4, '在你中间必没有穷人，因为在耶和华你的神赐给你作产业的地上，耶和华必大大赐福给你。'),
('CNV', '申命记', 5, 15, 5, '只要你留心听从耶和华你的神的话，谨守遵行我今日吩咐你的一切诫命。'),
('CNV', '申命记', 5, 15, 6, '因为耶和华你的神，必照着他应许你的，赐福给你；你必借贷给许多国的民，却不会向他们借贷；你必统治许多国的民，他们却不会统治你。'),
('CNV', '申命记', 5, 15, 7, '“但是在耶和华你的神赐给你的地上，无论哪一座城里，在你中间如果有一个穷人，又是你的兄弟，你对这穷苦的兄弟不可硬着心肠，也不可袖手不理。'),
('CNV', '申命记', 5, 15, 8, '你一定要向他伸手，照着他缺乏的借给他，补足他的缺乏。'),
('CNV', '申命记', 5, 15, 9, '你要自己谨慎，不可心里起恶念，说：‘第七年的豁免年近了’，你就冷眼对待你穷苦的兄弟，什么都不给他，以致他因你求告耶和华，你就有罪了。'),
('CNV', '申命记', 5, 15, 10, '你必须给他，给他的时候，你不要心里难受，因为为了这事，耶和华你的神必在你一切工作上，和你所办的一切事上，赐福给你。'),
('CNV', '申命记', 5, 15, 11, '既然在地上必有穷人存在，所以我吩咐你说：‘你总要向你地上的困苦和贫穷的兄弟大伸援助之手。’'),
('CNV', '申命记', 5, 15, 12, '“你的兄弟，无论是希伯来男人，或是希伯来女人，如果卖身给你，要服事你六年；到第七年，就要让他离开你得自由。'),
('CNV', '申命记', 5, 15, 13, '你使他自由离开的时候，不可让他空手而去；'),
('CNV', '申命记', 5, 15, 14, '要从你的羊群、禾场、榨酒池中，多多地供给他；耶和华你的神怎样赐福给你，你也要怎样分给他。'),
('CNV', '申命记', 5, 15, 15, '你要记得你在埃及地作过奴仆，耶和华你的神救赎了你；因此我今日吩咐你这件事。'),
('CNV', '申命记', 5, 15, 16, '如果他对你说：‘我不愿离开你。’他说这话是因为他爱你和你的家，又因为他喜欢和你相处，'),
('CNV', '申命记', 5, 15, 17, '那么，你就要拿锥子，把他的耳朵在门上刺透，他就永远作你的奴仆；对待你的婢女，你也要这样行。'),
('CNV', '申命记', 5, 15, 18, '你使他自由离开你的时候，不要为难，因为他服事了你六年，应得雇工双倍的工资；这样，耶和华你的神必在你所作的一切事上，赐福给你。'),
('CNV', '申命记', 5, 15, 19, '“你的牛群羊群中所生，是头生雄性的，你都要把它分别为圣归给耶和华你的神。你的牛群中头生的，你不可用它去耕田；你的羊群中头生的，你不可给它剪毛。'),
('CNV', '申命记', 5, 15, 20, '你和你的家人，年年要在耶和华选择的地方，在耶和华你的神面前，吃这头生的牲畜。'),
('CNV', '申命记', 5, 15, 21, '这头生的，如果有什么残疾，像瘸腿或是瞎眼，无论有任何严重的残疾，你都不可献给耶和华你的神。'),
('CNV', '申命记', 5, 15, 22, '你可以在家里吃，不洁净的人和洁净的人都一样可以吃，像吃羚羊和鹿一样。'),
('CNV', '申命记', 5, 15, 23, '只是不可吃它的血；要把血倒在地上，像倒水一样。”'),
('CNV', '申命记', 5, 16, 1, '“你要守亚笔月，向耶和华你的神守逾越节，因为耶和华你的神在亚笔月的一个晚上，把你从埃及地领出来。'),
('CNV', '申命记', 5, 16, 2, '你要在耶和华选择立为他名的居所的地方，把羊和牛作逾越节的祭牲献给耶和华你的神。'),
('CNV', '申命记', 5, 16, 3, '你吃这祭的时候，不可和有酵的饼一同吃；七日之内，你要吃无酵饼，就是困苦饼，因为你是急急忙忙从埃及地出来的，好使你一生的年日都可以记念你从埃及地出来的日子。'),
('CNV', '申命记', 5, 16, 4, '七天之内，在你的全境不可见有酵。第一天晚上你献的祭肉，一点也不可剩下，留到早晨。'),
('CNV', '申命记', 5, 16, 5, '你不能在耶和华你的神赐给你的任何一座城里，宰杀逾越节的祭牲；'),
('CNV', '申命记', 5, 16, 6, '只能在耶和华你的神选择作他名的居所的地方，晚上日落的时候，就是你出埃及的时刻，宰杀逾越节的祭牲；'),
('CNV', '申命记', 5, 16, 7, '你要在耶和华你的神选择的地方，把祭肉煮了吃；到了早晨，你才可以回到家里去。'),
('CNV', '申命记', 5, 16, 8, '六日之内你要吃无酵饼；到了第七日，要向耶和华你的神守圣会；什么工都不可作。'),
('CNV', '申命记', 5, 16, 9, '“你要计算七个七日，从开镰收割禾稼的时候算起，共计七个七日。'),
('CNV', '申命记', 5, 16, 10, '你要向耶和华你的神举行七七节，照着耶和华你的神赐福你的，尽你所能的献上你手里的甘心祭。'),
('CNV', '申命记', 5, 16, 11, '你和你的儿女、仆婢，以及在你城里的利未人、在你们中间的寄居者、孤儿和寡妇，都要在耶和华你的神选择作他名的居所的地方欢乐。'),
('CNV', '申命记', 5, 16, 12, '你也要记得你在埃及作过奴仆；你要谨守遵行这些律例。'),
('CNV', '申命记', 5, 16, 13, '“你从禾场上和榨酒池里收藏了出产以后，就要举行住棚节七日。'),
('CNV', '申命记', 5, 16, 14, '在这节期以内，你和你的儿女、仆婢，以及住在你城里的利未人、寄居者、孤儿和寡妇，都要欢乐。'),
('CNV', '申命记', 5, 16, 15, '你要在耶和华选择的地方，向耶和华你的神守节七日，因为耶和华你的神，要在你一切土产上，和你手所作的一切事上，赐福给你，你就满有欢乐。'),
('CNV', '申命记', 5, 16, 16, '每年三次，就是在除酵节、七七节、住棚节，你所有的男丁都要在耶和华选择的地方，朝见耶和华你的神；但不可空手朝见耶和华。'),
('CNV', '申命记', 5, 16, 17, '各人要按手中的力量，照着耶和华你的神赐你的福，奉献礼物。'),
('CNV', '申命记', 5, 16, 18, '“在耶和华你的神赐给你的各城里，你要按着各支派设立审判官和官长；他们要按着公义的判断审判人民。'),
('CNV', '申命记', 5, 16, 19, '不可屈枉正直，不可徇人的情面，不可收受贿赂，因为贿赂能使智慧人的眼变瞎，也能使义人的话颠倒过来。'),
('CNV', '申命记', 5, 16, 20, '你要追求公正公义，好使你能存活，并且能承受耶和华你的神赐给你的地作产业。'),
('CNV', '申命记', 5, 16, 21, '“在你为耶和华你的神筑的祭坛旁边，不可栽种什么树木，作亚舍拉。'),
('CNV', '申命记', 5, 16, 22, '也不可为自己竖立神柱，这是耶和华你的神所恨恶的。”'),
('CNV', '申命记', 5, 17, 1, '“有残疾，或有什么缺点的牛羊，都不可献给耶和华你的神，因为这是耶和华你的神所憎恶的。'),
('CNV', '申命记', 5, 17, 2, '“在你中间，就是耶和华你的神赐给你的任何一座城里，如果发现有人，无论是男是女，行耶和华你的神眼中看为恶的事，违犯了他的约，'),
('CNV', '申命记', 5, 17, 3, '去事奉别的神，并且敬拜它们，敬拜太阳或月亮，或任何天象，是我耶和华没有吩咐的；'),
('CNV', '申命记', 5, 17, 4, '有人告诉你，你也听见了，就要好好调查；如果确有这些事，真的在以色列中行了这可憎可厌的事；'),
('CNV', '申命记', 5, 17, 5, '你就要把那个行了这恶事的男人或女人带出来，到城门那里去，用石头把他们打死。'),
('CNV', '申命记', 5, 17, 6, '凭着两个或三个见证人的口供，就可以把那该死的人处死；只是凭着一个见证人的口供，却不可以把人处死。'),
('CNV', '申命记', 5, 17, 7, '见证人要先下手，然后众民也下手，把他处死。这样，你就把那恶从你中间除掉。'),
('CNV', '申命记', 5, 17, 8, '“在你的城里如果有什么争讼的事：或是流血，或是诉讼，或是殴打，是你很难处决的案件，你就要起来，上到耶和华你的神选择的地方，'),
('CNV', '申命记', 5, 17, 9, '去见利未支派的祭司和当时的审判官，询问他们，他们就必指示你们怎样判断这案件。'),
('CNV', '申命记', 5, 17, 10, '你要照着他们从耶和华选择的那地方，向你指示的话去行；他们指教你的，你都要谨守遵行。'),
('CNV', '申命记', 5, 17, 11, '你要按着他们指教你的律法，和照着他们告诉你的判断去行；他们告诉你的话，你不可偏左或偏右。'),
('CNV', '申命记', 5, 17, 12, '如果有人擅自行事，不听从祭司，就是侍立在那里事奉耶和华你的神的，或是不听从审判官，那人就必须处死；这样，你就可以把这恶从以色列中肃清了。'),
('CNV', '申命记', 5, 17, 13, '众民都会听见，而且惧怕，也不再擅自行事了。'),
('CNV', '申命记', 5, 17, 14, '“你进了耶和华你的神赐给你的地，占领了那地，居住在那里的时候，如果你说：‘我要立一位君王治理我，像我四围的列国一样。’'),
('CNV', '申命记', 5, 17, 15, '你总要立耶和华你的神拣选的人作君王管理你；你要从你的兄弟中立一位作你的君王；不可立你的兄弟以外的人作王管理你。'),
('CNV', '申命记', 5, 17, 16, '只是君王不可为自己加添马匹，也不可使人民回埃及去，为要加添马匹，因为耶和华曾经对你们说过：‘你们不可再回到那条路去。’'),
('CNV', '申命记', 5, 17, 17, '他也不可为自己加添妃嫔，恐怕他的心偏离了耶和华；也不可为自己积蓄极多的金钱。'),
('CNV', '申命记', 5, 17, 18, '“他登上了国位的时候，就要把利未支派的祭司面前的律法书，为自己抄录一份副本。'),
('CNV', '申命记', 5, 17, 19, '那份副本要常在他身边，他一生的年日都要诵读，好学习敬畏耶和华他的神，谨守遵行这律法书上的一切话和这些律例。'),
('CNV', '申命记', 5, 17, 20, '这样，他的心就不会高傲，轻看自己的兄弟，也不会偏左偏右，离了这诫命；好使他和他的子孙在以色列中，在他的国位上，可以日子长久。”'),
('CNV', '申命记', 5, 18, 1, '“利未支派的祭司和利未整个支派，在以色列中，必无分无业；他们所吃的，是献给耶和华的火祭和他们应得的一份（“他们应得的一份”直译是“它的份”，即利未支派的份）。'),
('CNV', '申命记', 5, 18, 2, '利未人在兄弟中必没有产业，耶和华就是他们的产业，正如耶和华应许他们的。'),
('CNV', '申命记', 5, 18, 3, '“祭司从人民应得的分是这样：人无论是献牛或是献羊，要把前腿、两腮和胃给祭司。'),
('CNV', '申命记', 5, 18, 4, '你也要把初熟的五谷、新酒、新油和初剪的羊毛给他。'),
('CNV', '申命记', 5, 18, 5, '因为耶和华你的神从你的各支派中把他拣选出来，使他和他的子孙，可以常常奉耶和华的名侍立供祭司的职。'),
('CNV', '申命记', 5, 18, 6, '“如果有住在以色列中任何一座城里的利未人，离开了那里，一心一意到耶和华选择的地方去，'),
('CNV', '申命记', 5, 18, 7, '他就可以奉耶和华他的神的名供职，像他的众兄弟利未人在那里侍立在耶和华面前一样。'),
('CNV', '申命记', 5, 18, 8, '除了他从父家承受的产业以外，他还可以得着和他的兄弟相等分量的祭物。'),
('CNV', '申命记', 5, 18, 9, '“你到了耶和华你的神要赐给你的那地的时候，那些外族人可厌可恶的事，你不可学习去行。'),
('CNV', '申命记', 5, 18, 10, '在你中间不可有人把自己的儿女献作火祭（“把自己的儿女献作火祭”直译是“使自己的儿女经过进入火中”），也不可有占卜的、算命的、用法术的、行邪术的、'),
('CNV', '申命记', 5, 18, 11, '念咒的、问鬼的、行巫术的、过阴的。'),
('CNV', '申命记', 5, 18, 12, '因为行这些事的，都是耶和华厌恶的；就是因为这些可厌可恶的事的缘故，耶和华你的神才把他们从你的面前赶走。'),
('CNV', '申命记', 5, 18, 13, '你要在耶和华你的神面前作完全人。'),
('CNV', '申命记', 5, 18, 14, '“因为你要赶走的那些民族，都听从算命的和占卜的；至于你，耶和华你的神却不容许你这样行。'),
('CNV', '申命记', 5, 18, 15, '“耶和华你的神要从你中间，就是从你的众兄弟中间，给你兴起一位先知来，像我一样；你们要听从他。'),
('CNV', '申命记', 5, 18, 16, '这正是你在何烈山开大会的日子，求耶和华你的神的一切话，说：‘不要让我再听见耶和华我的神的声音了；也不要让我再看见这大火了，免得我死亡。’'),
('CNV', '申命记', 5, 18, 17, '耶和华对我说：‘他们所说的都很好。'),
('CNV', '申命记', 5, 18, 18, '我要从他们的兄弟中间，给他们兴起一位先知，像你一样；我要把我的话放在他口里，他必把我吩咐他们的一切话都对他们说。'),
('CNV', '申命记', 5, 18, 19, '如果有人不听从他奉我的名所说的话，我必亲自追讨那人的罪。'),
('CNV', '申命记', 5, 18, 20, '“‘不过，如果有先知擅自奉我的名，说我没有吩咐他说的话，或是奉别神的名说话，那先知就必须处死。’'),
('CNV', '申命记', 5, 18, 21, '如果你心里说：‘耶和华没有说过的话，我们怎能知道呢？’'),
('CNV', '申命记', 5, 18, 22, '一位先知奉耶和华的名说话，如果那话不成就，也不应验，这话就不是耶和华说的；是那先知擅自说的，你不要怕他。”'),
('CNV', '申命记', 5, 19, 1, '“耶和华你的神把列国的民剪除了，耶和华你的神把他们的地赐给了你，你赶走了那些国民，住在他们的城市和房屋以后，'),
('CNV', '申命记', 5, 19, 2, '你就要在耶和华你的神赐给你得为业的地上，为自己分别三座城。'),
('CNV', '申命记', 5, 19, 3, '你要为自己预备道路，又要把耶和华你的神给你作产业的地分为三区，使误杀人的可以逃到那里去。'),
('CNV', '申命记', 5, 19, 4, '“误杀人的逃到那里，就可以存活，规例是这样：无意杀了人，彼此又素无仇恨的，'),
('CNV', '申命记', 5, 19, 5, '譬如他和邻舍同进森林砍伐树木，他手里挥着斧子砍伐树木的时候，斧头竟脱了把，落在邻舍身上，以致那人死了，他就可以逃到这些城中的一座去，这样他就可以活命，'),
('CNV', '申命记', 5, 19, 6, '免得报血仇的，心中怒火如焚的时候，追赶那误杀人的，因为路途长远，就追上了他，把他杀死；其实他没有该死的罪，因为他和那人素无仇恨。'),
('CNV', '申命记', 5, 19, 7, '因此我吩咐你：‘你要为自己分别三座城。’'),
('CNV', '申命记', 5, 19, 8, '如果耶和华你的神照着他向你列祖起过的誓，扩张你的境界，把他应许赐给你列祖的全地，都赐给了你，'),
('CNV', '申命记', 5, 19, 9, '如果你谨守遵行我今日吩咐你的这一切诫命，爱耶和华你的神，常常行他的道路，你就要在这三座城以外，再加添三座城；'),
('CNV', '申命记', 5, 19, 10, '免得无辜人的血，流在耶和华你的神要赐给你作产业的地上，以致流人血的罪归在你身上。'),
('CNV', '申命记', 5, 19, 11, '“但是，如果有人恨他的邻舍，埋伏着等他，起来攻击他，把他杀死了，然后逃到这些城中的一座；'),
('CNV', '申命记', 5, 19, 12, '他本城的长老要派人去，把他从那里带出来，交在报血仇的人手中，好把他处死。'),
('CNV', '申命记', 5, 19, 13, '你的眼睛不可顾惜他，却要把流无辜人的血的罪从以色列中除掉，好使你平安无事。'),
('CNV', '申命记', 5, 19, 14, '“在耶和华你的神要赐给你承受为业的地上，不可挪移你邻舍的地界，因为那是先人立定的。'),
('CNV', '申命记', 5, 19, 15, '“人无论有什么过错，或是犯了什么罪恶，不可凭着一个见证人的指证，总要凭着两个见证人的口供，或是三个见证人的口供，才可以确定。'),
('CNV', '申命记', 5, 19, 16, '如果有强横的见证人起来，指证某人作恶，'),
('CNV', '申命记', 5, 19, 17, '那么，两个彼此争讼的人，就要站在耶和华面前，和当时在职的祭司与审判官面前。'),
('CNV', '申命记', 5, 19, 18, '审判官要仔细查问；如果见证人是个假证人，作假见证陷害自己的兄弟，'),
('CNV', '申命记', 5, 19, 19, '你们就要像他想怎样对待自己的兄弟一样对待他，这样，你就把那恶从你们中间除掉。'),
('CNV', '申命记', 5, 19, 20, '其余的人听见了，就必害怕，不敢再在你中间行这样的恶事了。'),
('CNV', '申命记', 5, 19, 21, '你的眼睛不可顾惜，要以命偿命，以眼还眼，以牙还牙，以手还手，以脚还脚。”'),
('CNV', '申命记', 5, 20, 1, '“你出去和你的仇敌作战的时候，看见马匹、车辆和比你多的人群，你不要怕他们，因为那把你们从埃及地领上来的耶和华你的神，与你同在。'),
('CNV', '申命记', 5, 20, 2, '你们快要上战场的时候，祭司要上前来，对人民说话，'),
('CNV', '申命记', 5, 20, 3, '对他们说：‘以色列人哪，你们要听，你们今日快要和仇敌作战，你们不要胆怯，不要惧怕，不要惊慌，不要因他们的缘故战兢；'),
('CNV', '申命记', 5, 20, 4, '因为耶和华你们的神和你们同去，要为你们攻打你们的仇敌，要拯救你们。’'),
('CNV', '申命记', 5, 20, 5, '官长也要对人民宣告：‘谁建造了新房屋，还没有行过奉献礼的，他可以回家去，恐怕他死在战场上，别人去为他的房屋行奉献礼。'),
('CNV', '申命记', 5, 20, 6, '谁栽种了葡萄园，还没有享用过它的果子的，他可以回家去，恐怕他死在战场上，别人去享用它的果子。'),
('CNV', '申命记', 5, 20, 7, '谁与女子订了婚，还没有迎娶的，他可以回家去，恐怕他死在战场上，别人去娶了她。’'),
('CNV', '申命记', 5, 20, 8, '官长又要对人民宣告：‘谁是惧怕、胆怯的，他可以回家去，恐怕他使他兄弟的心融化，像他的心一样。’'),
('CNV', '申命记', 5, 20, 9, '官长对人民讲完了话，就要指派军官统率他们。'),
('CNV', '申命记', 5, 20, 10, '“你临近一座城，要攻打那城的时候，要先向那城提和议。'),
('CNV', '申命记', 5, 20, 11, '如果那城以和平的话回答你，给你开门，城里所有的人都要给你作苦工，服事你。'),
('CNV', '申命记', 5, 20, 12, '如果那城不肯与你言和，却要与你作战，你就要围困那城。'),
('CNV', '申命记', 5, 20, 13, '耶和华你的神把城交在你手里的时候，你要用利刃杀尽城里所有的男丁。'),
('CNV', '申命记', 5, 20, 14, '只有妇人、小孩子、牲畜和城里所有的一切，就是一切战利品，你都可以据为己有，你的仇敌的战利品，你都可以吃用，因为这是耶和华你的神赐给你的。'),
('CNV', '申命记', 5, 20, 15, '离开你很远的各城，不是属于这些国民的城，你都要这样对待他们。'),
('CNV', '申命记', 5, 20, 16, '只是在耶和华你的神赐给你作产业的这些国民的城市里，凡有气息的，连一个你也不可让他活着；'),
('CNV', '申命记', 5, 20, 17, '只要照着耶和华你的神吩咐你的，把赫人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人，完全灭绝；'),
('CNV', '申命记', 5, 20, 18, '免得他们教导你们学习一切可憎的事，就是他们对自己的神所行的事，以致你们得罪耶和华你们的神。'),
('CNV', '申命记', 5, 20, 19, '“如果你围困一座城，很久才能攻取占领它，你就不可挥斧破坏那里的树木；因为你可以吃树上的果子，却不可以砍伐树木。难道田间的树木是人，可以被你围困的吗？'),
('CNV', '申命记', 5, 20, 20, '只有你知道不结果子的树木，你才可以毁坏砍伐，用来建造围城的设备，攻击那与你作战的城，直到把它攻下为止。”'),
('CNV', '申命记', 5, 21, 1, '“在耶和华你的神赐给你作产业的地上，如果发现有被杀的人，倒卧在田野，又不知道是谁杀死他的，'),
('CNV', '申命记', 5, 21, 2, '这样，你的长老和审判官就要出去，量一下从被杀的人那里到四周城市的距离。'),
('CNV', '申命记', 5, 21, 3, '看看哪一座城离那被杀的人最近，那城的长老就要从牛群中取一只母牛犊，就是还没有耕过地、没有负过轭的。'),
('CNV', '申命记', 5, 21, 4, '那城的长老要把母牛犊牵下去，到一个有活水长流的山谷，就是未曾耕种过、未曾撒过种的地方，在那里要打折母牛犊的颈项。'),
('CNV', '申命记', 5, 21, 5, '利未支派的祭司的子孙要上前来，因为耶和华你的神拣选了他们事奉他，奉耶和华的名祝福。一切争讼和一切殴打的事，都要凭他们的话决定。'),
('CNV', '申命记', 5, 21, 6, '那城所有的长老，就是离那被杀的人最近的，都要在山谷中，在被折断颈项的母牛犊以上洗手。'),
('CNV', '申命记', 5, 21, 7, '他们要声明，说：‘我们的手未曾流过这人的血，我们的眼也未曾看见这事。'),
('CNV', '申命记', 5, 21, 8, '耶和华啊，求你赦免你的子民以色列，就是你救赎的，不要使流无辜人的血的罪归在你的子民以色列中间。’这样，他们流人血的罪就得到赦免了。'),
('CNV', '申命记', 5, 21, 9, '如果你行耶和华看为正的事，就可以从你中间除掉流无辜人的血的罪了。'),
('CNV', '申命记', 5, 21, 10, '“你出去和仇敌作战的时候，耶和华你的神把他们交在你手里，你就把他们掳了去。'),
('CNV', '申命记', 5, 21, 11, '如果你在被掳的人中看见了容貌美好的女子，就恋慕她，要娶她作妻子，'),
('CNV', '申命记', 5, 21, 12, '那么，你可以把她带进你的家里；她要剃头修甲，'),
('CNV', '申命记', 5, 21, 13, '脱去被掳时所穿的衣服，住在你家里，为自己的父母哀哭一个月，然后你才可以亲近她；你作她的丈夫，她作你的妻子。'),
('CNV', '申命记', 5, 21, 14, '如果将来你不喜欢她，就要让她随意离去，决不可为了钱把她出卖，也不可以她为奴，因为你已经污辱了她。'),
('CNV', '申命记', 5, 21, 15, '“如果人有两个妻子，一个是他喜爱的，一个是他不喜爱的，两个都给他生了儿子；但长子是他不喜爱的妻子生的；'),
('CNV', '申命记', 5, 21, 16, '到了他把所有的产业分给儿子承受的日子，他不可把他喜爱的妻子的儿子立为长子，排在他不喜爱的妻子的儿子以上，他才是长子；'),
('CNV', '申命记', 5, 21, 17, '却要承认他不喜爱的妻子的儿子为长子，把所有的产业分两份给他，因为这儿子是他强壮有力的时候所生的头生子，长子的权利本是属于他的。'),
('CNV', '申命记', 5, 21, 18, '“如果人有忤逆倔强的儿子，不听从父母的话；父母管教他以后，他还是不听从；'),
('CNV', '申命记', 5, 21, 19, '他的父母就要捉住他，把他带到当地的城门，去见本城的长老，'),
('CNV', '申命记', 5, 21, 20, '对本城的长老说：‘我们这个儿子忤逆倔强，不听从我们的话，是个贪食好酒的人。’'),
('CNV', '申命记', 5, 21, 21, '全城的人就要用石头打死他；这样，你就把那恶从你们中间除掉。以色列众人听见了，就都惧怕。'),
('CNV', '申命记', 5, 21, 22, '“如果人犯了该死的罪，被处死以后，你就把他挂在木头上；'),
('CNV', '申命记', 5, 21, 23, '他的尸体不可留在树上过夜，必须在当日把他埋葬，因为被挂在木头上的，是受神咒诅的；这样，你就不至于玷污耶和华你的神赐给你作产业的地了。”'),
('CNV', '申命记', 5, 22, 1, '“如果你看见你兄弟的牛或羊走迷了，你不可不理，总要把它们牵回你的兄弟那里。'),
('CNV', '申命记', 5, 22, 2, '如果你的兄弟离你很远，或是你不认识他，你就要把它牵到你家中，留在你那里，等到你的兄弟来寻找它，你就还给他。'),
('CNV', '申命记', 5, 22, 3, '对他的驴，你要这样行；对你的兄弟失去而被你找到的任何东西，你都要这样行，不可不理。'),
('CNV', '申命记', 5, 22, 4, '如果你看见你兄弟的驴或牛跌倒在路上，你不可不理，总要帮助他把它们拉起来。'),
('CNV', '申命记', 5, 22, 5, '“妇女不可穿男子的服装；男子也不可穿妇人的衣服；因为这样作的人，都是耶和华你的神厌恶的。'),
('CNV', '申命记', 5, 22, 6, '“如果你在路上遇见鸟窝，或是在树上，或是在地上；里面有雏鸟，或是有蛋；母鸟伏在雏鸟身上，或在蛋上；你不可连母带子一起取去；'),
('CNV', '申命记', 5, 22, 7, '总要让母鸟飞去，只可以取子；这样你就可以得着好处，得享长寿。'),
('CNV', '申命记', 5, 22, 8, '“如果你建造新房屋，要在屋顶上作栏杆；免得有人从那里跌下来，流血的罪就归到你家。'),
('CNV', '申命记', 5, 22, 9, '“不可把两样的种子撒在你的葡萄园里，免得你所种的全部收成和葡萄园的出产，都要被充公归与圣所（“要被充公归与圣所”或译：“受到玷污”）。'),
('CNV', '申命记', 5, 22, 10, '你不可用牛和驴一同耕地。'),
('CNV', '申命记', 5, 22, 11, '不可穿羊毛和细麻混合织成的布料。'),
('CNV', '申命记', 5, 22, 12, '“你要在所披的外衣上，四边做繸子。'),
('CNV', '申命记', 5, 22, 13, '“如果人娶妻，和她同房之后，就恨她，'),
('CNV', '申命记', 5, 22, 14, '捏造可耻的事毁谤她，破坏她的名誉，说：‘我娶了这个女子，和她亲近的时候，发现她没有贞洁的凭据。’'),
('CNV', '申命记', 5, 22, 15, '那少女的父母就要把那少女的贞洁凭据拿出来，带到城门去见本城的长老。'),
('CNV', '申命记', 5, 22, 16, '少女的父亲要对长老说：‘我把我的女儿给这人作妻子，他却恨她，'),
('CNV', '申命记', 5, 22, 17, '捏造可耻的事毁谤她，说：“我发现你的女儿没有贞洁的凭据。”其实这就是我女儿的凭据。’于是，他们就把衣服铺在那城的长老面前。'),
('CNV', '申命记', 5, 22, 18, '那城的长老要把那人捉住，惩罚他，'),
('CNV', '申命记', 5, 22, 19, '罚他一千一百四十克银子，交给那少女的父亲，因为他破坏了一个以色列处女的名誉；那少女仍要作他的妻子，终生不能休她。'),
('CNV', '申命记', 5, 22, 20, '但如果这事是真的，少女没有贞洁的凭据，'),
('CNV', '申命记', 5, 22, 21, '就要把那少女带到她父家的门口，本城的人要用石头把她打死，因为她在以色列中作了丑事，在她父家行了淫乱；这样，你就把那恶从你们中间除去。'),
('CNV', '申命记', 5, 22, 22, '“如果发现有人和有夫之妇同寝，就要把奸夫淫妇二人都处死；这样，你就把那恶从以色列中除掉了。'),
('CNV', '申命记', 5, 22, 23, '“如果有个少女，本来是处女，已经许配了人，有人在城里遇见了她，和她同寝，'),
('CNV', '申命记', 5, 22, 24, '你们就要把他们二人带到当地的城门口，用石头打死他们。那少女该死，是因为她虽在城里，却没有呼叫；那男人该死，是因为他玷污了邻舍的妻子；这样，你就把那恶从你们中间除掉。'),
('CNV', '申命记', 5, 22, 25, '如果有人在田间遇见了已经许配人的少女，拉住她，和她同寝，只要把那和她同寝的人处死。'),
('CNV', '申命记', 5, 22, 26, '但你不可对付那少女，她并没有该死的罪。这件事就像一个人忽然起来攻击自己的邻舍，你把他杀了一样。'),
('CNV', '申命记', 5, 22, 27, '因为那人在田间遇见那少女，那已经许配人的少女呼叫了，却没有人救她。'),
('CNV', '申命记', 5, 22, 28, '“如果有人遇见一个少女，原是处女，还没有许配过人，就抓住她，和她同寝，又被人发现，'),
('CNV', '申命记', 5, 22, 29, '那和她同寝的人就要把五百七十克银子给那少女的父亲，那少女要归作他的妻子，因为他玷污了她；他终生不能休她。'),
('CNV', '申命记', 5, 22, 30, '“人不可娶父亲的妻子，也不可揭开父亲的衣襟。”（本节在《马索拉文本》为23:1）'),
('CNV', '申命记', 5, 23, 1, '“睾丸受伤的，或生殖器被割除的，不可进耶和华的会。（本节在《马索拉文本》为23:2）'),
('CNV', '申命记', 5, 23, 2, '私生子不可进耶和华的会；他的后代直到第十代，也不可进耶和华的会。'),
('CNV', '申命记', 5, 23, 3, '亚扪人或摩押人不可进耶和华的会；他们的后代直到第十代，也永远不可进耶和华的会。'),
('CNV', '申命记', 5, 23, 4, '因为你们出埃及的时候，他们没有拿食物和水在路上迎接你们，又因为他们从两河之间的亚兰的毗夺雇了比珥的儿子巴兰，来攻击你，咒诅你。'),
('CNV', '申命记', 5, 23, 5, '但耶和华你的神不愿听从巴兰；耶和华你的神使咒诅的话变为你的祝福，因为耶和华你的神爱你。'),
('CNV', '申命记', 5, 23, 6, '你一生一世永不可寻求他们的平安和他们的福乐。'),
('CNV', '申命记', 5, 23, 7, '“你不可厌恶以东人，因为他是你的兄弟；不可厌恶埃及人，因为你在他的地上作过寄居的。'),
('CNV', '申命记', 5, 23, 8, '他们所生的子孙到了第三代，就可以进耶和华的会。'),
('CNV', '申命记', 5, 23, 9, '“你出兵安营攻打仇敌的时候，要谨守自己，远避一切恶事。'),
('CNV', '申命记', 5, 23, 10, '“如果你们中间有人因为夜间偶然梦遗而不洁净，就要出到营外去，不可进入营中。'),
('CNV', '申命记', 5, 23, 11, '到了黄昏的时候，他要用水洗澡；日落了，他才可以进入营中。'),
('CNV', '申命记', 5, 23, 12, '你在营外要有厕所，你可以出到那里去便溺。'),
('CNV', '申命记', 5, 23, 13, '在你的器械中，要有一把锹；你在外面便溺以后，可以用来铲土，转身把粪便掩盖。'),
('CNV', '申命记', 5, 23, 14, '因为耶和华你的神常在你的营中行走，要拯救你，要把你的仇敌交在你的面前；所以你的营要圣洁，免得他看见你那里有污秽的东西，就离开你。'),
('CNV', '申命记', 5, 23, 15, '“如果一个奴仆离开了他的主人，逃到你那里来，你不可把他送交他的主人。'),
('CNV', '申命记', 5, 23, 16, '他要在你中间和你同住，住在他自己选择的地方，住在他喜欢的城市，你不可欺负他。'),
('CNV', '申命记', 5, 23, 17, '“以色列的女子中不可有庙妓，以色列的男子中不可有男庙妓。'),
('CNV', '申命记', 5, 23, 18, '妓女所得的酬金，或男妓所得的代价，你不可带入耶和华你的神的殿里还任何的愿，因为这两样都是耶和华你的神厌恶的。'),
('CNV', '申命记', 5, 23, 19, '你借给你兄弟的银钱、食物，或是任何可以生利的东西，都不可取利。'),
('CNV', '申命记', 5, 23, 20, '借给外族人，你倒可以取利；只是借给你的兄弟，你就不可取利；好使耶和华你的神，在你要去得为业的地上，和你手里所办的一切事上，赐福给你。'),
('CNV', '申命记', 5, 23, 21, '“如果你向耶和华你的神许了愿，就不可迟延还愿，因为耶和华你的神必向你追讨，那时你就有罪了。'),
('CNV', '申命记', 5, 23, 22, '如果你不许愿，你倒没有罪。'),
('CNV', '申命记', 5, 23, 23, '你嘴里说出来的，你要谨守；你亲口应许的甘心祭，就是你向耶和华你的神许的愿，你要实行。'),
('CNV', '申命记', 5, 23, 24, '“你进了你邻舍的葡萄园，你可以随意吃饱葡萄，只是不可装在你的器皿里。'),
('CNV', '申命记', 5, 23, 25, '你进了你邻舍的麦田，你可以用手摘麦穗，只是不可在你邻舍的麦田里挥动镰刀。”'),
('CNV', '申命记', 5, 24, 1, '“人娶了妻子，得着她以后，如果发现她有丑事，以致不喜悦她，他就可以给她写休书，交在她手里，叫她离开夫家；'),
('CNV', '申命记', 5, 24, 2, '她离开夫家以后，就可以去再嫁别人。'),
('CNV', '申命记', 5, 24, 3, '如果后夫又恨她，也给她写休书，交在她手里，叫她离开他的家；或者娶她为妻的后夫死了；'),
('CNV', '申命记', 5, 24, 4, '那么，叫她离开的前夫，不可在她受了污辱以后，再娶她为妻，因为这在耶和华面前是可厌可恶的事；你不可使耶和华你的神赐给你作产业的土地蒙受罪污。'),
('CNV', '申命记', 5, 24, 5, '“如果人娶了新妇，不可从军出征，也不可派他担任什么公务，他可以在家赋闲一年，使他所娶的妻子快乐。'),
('CNV', '申命记', 5, 24, 6, '“不可拿人的磨，或是上磨石作抵押，因为这等于拿人的生命作抵押。'),
('CNV', '申命记', 5, 24, 7, '“如果发现有人拐带了以色列人的一个兄弟，把他当作奴隶看待，或是把他卖了，那拐带人的就要处死；这样，你就把那恶从你中间除掉。'),
('CNV', '申命记', 5, 24, 8, '“在大痲风的灾病上，你要谨慎自己，照利未支派的祭司指教你们的一切，认真地谨守遵行；我怎样吩咐了他们，你们就要怎样谨守遵行。'),
('CNV', '申命记', 5, 24, 9, '你当记得你们出了埃及，在路上的时候，耶和华你的神向米利暗所行的事。'),
('CNV', '申命记', 5, 24, 10, '“如果你借东西给你的邻舍，不论所借的是什么，总不可走进他的家里去拿抵押。'),
('CNV', '申命记', 5, 24, 11, '你要站在外面，等那向你借贷的人把抵押拿出来给你。'),
('CNV', '申命记', 5, 24, 12, '他若是个穷人，你不可留他的抵押过夜。'),
('CNV', '申命记', 5, 24, 13, '到了日落的时候，你要把抵押品还给他，好使他可以用自己的衣服盖着睡觉，他就给你祝福，这在耶和华你的神面前，就算是你的义了。'),
('CNV', '申命记', 5, 24, 14, '“困苦贫穷的雇工，无论是你的兄弟，或是寄居在你的地上你的城里的，你都不可欺压他。'),
('CNV', '申命记', 5, 24, 15, '你要当日给他工钱，不可等到日落，因为他贫穷，把心放在工钱上，免得他对你不满而呼求耶和华，你就有罪了。'),
('CNV', '申命记', 5, 24, 16, '“不可因儿子的罪处死父亲，也不可因父亲的罪处死儿子；各人要因自己的罪被处死。'),
('CNV', '申命记', 5, 24, 17, '“你不可向寄居的和孤儿屈枉正直，也不可拿寡妇的衣服作抵押。'),
('CNV', '申命记', 5, 24, 18, '你要记住你在埃及作过奴仆，耶和华你的神把你从那里救赎出来；所以我吩咐你要遵行这话。'),
('CNV', '申命记', 5, 24, 19, '“你在田间收割庄稼的时候，如果遗留一捆在田里，就不可再回去拾取，要留给寄居的、孤儿和寡妇；好使耶和华你的神，在你手里所办的一切事上，赐福给你。'),
('CNV', '申命记', 5, 24, 20, '你打橄榄树以后，枝上剩下的不可再打，要留给寄居的、孤儿和寡妇。'),
('CNV', '申命记', 5, 24, 21, '你收取葡萄园的葡萄以后，剩下的不可再摘，要留给寄居的、孤儿和寡妇。'),
('CNV', '申命记', 5, 24, 22, '你要记住你在埃及作过奴仆，所以我吩咐你遵行这话。”'),
('CNV', '申命记', 5, 25, 1, '“如果人与人之间有争讼的事，就上法庭去；审判官审判他们的时候，要定义人有理，定恶人有罪；'),
('CNV', '申命记', 5, 25, 2, '如果有罪的人应受责打，审判官就要叫他伏下，当面按着他的罪，照着数目责打他。'),
('CNV', '申命记', 5, 25, 3, '只可打他四十下，不可再多；恐怕你多打了他，过了这数目，你的兄弟就在你眼前受辱了。'),
('CNV', '申命记', 5, 25, 4, '“牛在踹谷的时候，不可笼住它的嘴。'),
('CNV', '申命记', 5, 25, 5, '“兄弟住在一起，他们中间如果有一个死了，没有留下儿子，死者的妻子就不可出嫁外人；她丈夫的兄弟要向她尽兄弟的本分，娶她为妻，和她同房。'),
('CNV', '申命记', 5, 25, 6, '她所生的长子要归亡兄的名下，免得他的名字从以色列中被涂抹了。'),
('CNV', '申命记', 5, 25, 7, '那人如果不喜欢娶他兄弟的妻子，他兄弟的妻子就要到城门去见长老，说：‘我丈夫的兄弟不肯在以色列中为自己的哥哥立名，不肯对我尽兄弟的本分。’'),
('CNV', '申命记', 5, 25, 8, '本城的长老就要把那人叫来，对他说明；如果他坚持说：‘我不乐意娶她’，'),
('CNV', '申命记', 5, 25, 9, '他哥哥的妻子就要当着长老的面前，走到那人跟前，脱去他脚上的鞋子，吐唾沫在他的脸上，说：‘那不为自己哥哥建立家室的，人人都要这样对待他。’'),
('CNV', '申命记', 5, 25, 10, '从此，在以色列中他的名字（“他的名字”或译：“他的家的名字”）必称为‘脱鞋者之家’。'),
('CNV', '申命记', 5, 25, 11, '“有两个人在一起打斗，如果其中一人的妻子走前来，要救她的丈夫脱离那打她丈夫的人的手，就伸手抓住那人的下体，'),
('CNV', '申命记', 5, 25, 12, '你就要砍掉那妇人的手；你的眼不可顾惜。'),
('CNV', '申命记', 5, 25, 13, '“你袋里不可有两样不同的法码，一大一小；'),
('CNV', '申命记', 5, 25, 14, '你家里不可有两样不同的升斗，一大一小。'),
('CNV', '申命记', 5, 25, 15, '你要有准确公正的法码，你要有准确公正的升斗，好使你在耶和华你的神赐给你的地上，得享长寿。'),
('CNV', '申命记', 5, 25, 16, '因为所有行这些事的，就是行不义的事的，都是耶和华你的神厌恶的。'),
('CNV', '申命记', 5, 25, 17, '“你要记住你们出了埃及以后，亚玛力人在路上怎样对待你；'),
('CNV', '申命记', 5, 25, 18, '怎样在路上遇见了你，趁你疲倦困乏的时候，攻击你后方所有软弱无力的人，并不敬畏神。'),
('CNV', '申命记', 5, 25, 19, '所以耶和华你的神使你脱离四围所有的仇敌，在耶和华你的神赐给你作产业的地上，得享太平的时候，你务要把亚玛力这名号从天下涂抹，不可忘记。”'),
('CNV', '申命记', 5, 26, 1, '“将来，你进了耶和华你的神赐给你作产业的地，占领那地，并且住在那里以后，'),
('CNV', '申命记', 5, 26, 2, '就要从耶和华你的神赐给你的地上，把地上各种初熟果子取些来，放在篮子里，到耶和华你的神选择立为他名的居所的地方，'),
('CNV', '申命记', 5, 26, 3, '去见当时作祭司的，对他说：‘我今日向耶和华你的神表明，我已经来到了耶和华向我们的列祖起誓应许要赐给我们的地。’'),
('CNV', '申命记', 5, 26, 4, '祭司就要从你手里接过篮子，放在耶和华你的神的祭坛前面。'),
('CNV', '申命记', 5, 26, 5, '然后你要在耶和华你的神面前说：‘我的祖先原是个飘泊流亡的亚兰人；他下到埃及，在那里寄居；他人数稀少，在那里却成了又大又强、人数又多的国。'),
('CNV', '申命记', 5, 26, 6, '埃及人恶待我们，苦害我们，把苦工加在我们身上。'),
('CNV', '申命记', 5, 26, 7, '于是我们向耶和华我们列祖的神呼求，耶和华听见了我们的声音，看见了我们所受的困苦、劳碌和压迫，'),
('CNV', '申命记', 5, 26, 8, '耶和华就用大能的手和伸出来的膀臂，以及大而可畏的事、神迹和奇事，把我们从埃及领出来。'),
('CNV', '申命记', 5, 26, 9, '把我们领进这地方，把这地赐给我们，就是流奶与蜜的地。'),
('CNV', '申命记', 5, 26, 10, '耶和华啊，现在你看，我把你赐给我的土地的初熟果子带了来。’随后你要把篮子放在耶和华你的神面前，在耶和华你的神面前下拜。'),
('CNV', '申命记', 5, 26, 11, '你和利未人，以及住在你们中间的外族人，都要因耶和华你的神赐给你和你的家的一切好处而欢乐。'),
('CNV', '申命记', 5, 26, 12, '“每逢第三年，就是十分献一之年，你把一切出产的十分之一完全取出，分给利未人、寄居的和孤儿寡妇，使他们在你的城中吃饱了以后，'),
('CNV', '申命记', 5, 26, 13, '你就要在耶和华你的神面前说：‘我已经把圣物从家里除去了，也分给了利未人、寄居的和孤儿寡妇，都照着你吩咐我的一切诫命；你的命令我都没有违背，也没有忘记。'),
('CNV', '申命记', 5, 26, 14, '我守丧的时候，没有吃这圣物；我不洁的时候，没有把它除去，也没有把它送给死人；我听从了耶和华我的神的话，都照着你吩咐我的一切行了。'),
('CNV', '申命记', 5, 26, 15, '求你从天上你圣洁的居所垂看，赐福给你的子民以色列，和你赐给我们的土地，就是你向我们的列祖起誓应许的那流奶与蜜的地。’'),
('CNV', '申命记', 5, 26, 16, '“耶和华你的神今日吩咐你遵行这些律例和典章，所以你要一心一意谨守遵行。'),
('CNV', '申命记', 5, 26, 17, '你今日承认了耶和华是你的神，要遵行他的道，谨守他的律例、诫命和典章，听从他的话。'),
('CNV', '申命记', 5, 26, 18, '耶和华今日照着他应许你的，也承认了你是他珍贵的子民，使你谨守他的一切诫命；'),
('CNV', '申命记', 5, 26, 19, '他又使你得称赞、名誉和尊贵，超过他所造的列国之上，并且照着他说过的使你作圣洁的子民，归于耶和华你的神。”'),
('CNV', '申命记', 5, 27, 1, '摩西和以色列的长老吩咐人民：“你们要遵守我今日吩咐你们的一切诫命。'),
('CNV', '申命记', 5, 27, 2, '将来你们过约旦河，到了耶和华你的神赐给你的土地的那一天，你要立起几块大石头，墁上石灰。'),
('CNV', '申命记', 5, 27, 3, '你过河以后，要把这律法的一切话都写在石头上面，使你可以进入耶和华你的神赐给你的土地，就是流奶与蜜的地，正如耶和华你列祖的神应许你的。'),
('CNV', '申命记', 5, 27, 4, '所以，将来你们过了约旦河，就要在以巴路山上，照着我今日吩咐你们的，把这些石头立起来，墁上石灰。'),
('CNV', '申命记', 5, 27, 5, '在那里你要为耶和华你的神筑一座石坛，在石头上你不可动铁器。'),
('CNV', '申命记', 5, 27, 6, '你要用没有凿过的整块石头筑耶和华你的神的坛；在坛上你要献上燔祭给耶和华你的神；'),
('CNV', '申命记', 5, 27, 7, '又要献上平安祭，并且在那里吃喝；也要在耶和华你的神面前欢乐。'),
('CNV', '申命记', 5, 27, 8, '你要把这律法的一切话，都清清楚楚写在石头上。”'),
('CNV', '申命记', 5, 27, 9, '摩西和利未支派的祭司对以色列众人说：“以色列啊，要默默静听；今日你已经成为耶和华你的神的子民了。'),
('CNV', '申命记', 5, 27, 10, '所以你要听从耶和华你的神的话，遵行他的诫命和律例，就是我今日吩咐你的。”'),
('CNV', '申命记', 5, 27, 11, '那天摩西又吩咐人民：'),
('CNV', '申命记', 5, 27, 12, '“你们过了约旦河以后，西缅、利未、犹大、以萨迦、约瑟、便雅悯等支派的人，要站在基利心山上为人民祝福；'),
('CNV', '申命记', 5, 27, 13, '流本、迦得、亚设、西布伦、但、拿弗他利等支派的人，要站在以巴路山上宣布咒诅的话。'),
('CNV', '申命记', 5, 27, 14, '利未人要向以色列众人大声说：'),
('CNV', '申命记', 5, 27, 15, '“‘制造耶和华厌恶的雕像或铸像，工人手中做的，并且在暗处设立的，那人必受咒诅。’众民都要应声说：‘阿们。’'),
('CNV', '申命记', 5, 27, 16, '“‘轻慢父母的，必受咒诅。’众民都要说：‘阿们。’'),
('CNV', '申命记', 5, 27, 17, '“‘移动邻舍地界的，必受咒诅。’众民都要说：‘阿们。’'),
('CNV', '申命记', 5, 27, 18, '“‘使瞎子走错路的，必受咒诅。’众民都要说：‘阿们。’'),
('CNV', '申命记', 5, 27, 19, '“‘对寄居的和孤儿寡妇屈枉正直的，必受咒诅。’众民都要说：‘阿们。’'),
('CNV', '申命记', 5, 27, 20, '“‘和父亲的妻子同寝的，必受咒诅，因为他揭开了他父亲的衣襟。’众民都要说：‘阿们。’'),
('CNV', '申命记', 5, 27, 21, '“‘和任何野兽同寝的，必受咒诅。’众民都要说：‘阿们。’'),
('CNV', '申命记', 5, 27, 22, '“‘和同父异母，或是同母异父的姊妹同寝的，必受咒诅。’众民都要说：‘阿们。’'),
('CNV', '申命记', 5, 27, 23, '“‘和岳母同寝的，必受咒诅。’众民都要说：‘阿们。’'),
('CNV', '申命记', 5, 27, 24, '“‘暗中杀害邻舍的，必受咒诅。’众民都要说：‘阿们。’'),
('CNV', '申命记', 5, 27, 25, '“‘接受贿赂杀人，流无辜人的血的，必受咒诅。’众民都要说：‘阿们。’'),
('CNV', '申命记', 5, 27, 26, '“‘不坚守这律法的话去遵行的，必受咒诅。’众民都要说：‘阿们。’”'),
('CNV', '申命记', 5, 28, 1, '“如果你实在听从耶和华你的神的话，谨守遵行他的一切诫命，就是我今日吩咐你的，耶和华你的神必使你超过地上所有的民族。'),
('CNV', '申命记', 5, 28, 2, '如果你听从耶和华你的神的话，以下这一切福气必临到你身上，必把你追上。'),
('CNV', '申命记', 5, 28, 3, '你在城里必蒙福，在田间也必蒙福。'),
('CNV', '申命记', 5, 28, 4, '你身所生的、土地所出的、牲畜所出的、牛生殖的和羊所产的，都必蒙福。'),
('CNV', '申命记', 5, 28, 5, '你的篮子和你的抟面盆，都必蒙福。'),
('CNV', '申命记', 5, 28, 6, '你出必蒙福，你入也必蒙福。'),
('CNV', '申命记', 5, 28, 7, '“那起来攻击你的仇敌，耶和华必使他们在你面前被击败；他们从一条路出来攻击你，必在你面前从七条路逃跑。'),
('CNV', '申命记', 5, 28, 8, '在你的仓房里和你手所办的一切事上，耶和华必吩咐福气临到你；在耶和华你的神赐给你的地上，他必赐福给你。'),
('CNV', '申命记', 5, 28, 9, '如果你谨守耶和华你的神的诫命，遵守他的道路，耶和华就必照着他向你起过的誓，立你作他自己的圣民。'),
('CNV', '申命记', 5, 28, 10, '地上万民见你被称为耶和华名下的人，就必惧怕你。'),
('CNV', '申命记', 5, 28, 11, '在耶和华向你列祖起誓应许要赐给你的土地上，他必使你身上所生的、牲畜所产的、土地所出的，都丰富有余。'),
('CNV', '申命记', 5, 28, 12, '耶和华必为你打开他天上的宝库，按时降雨在你的地上，在你手里所作的一切事上赐福给你；你要借贷给许多国的民，却不会向人借贷。'),
('CNV', '申命记', 5, 28, 13, '耶和华必使你作头不作尾，居上不居下，只要你听从耶和华你的神的诫命，就是我今日吩咐你的，谨守遵行；'),
('CNV', '申命记', 5, 28, 14, '不可偏离我今日吩咐你的一切话，不偏左也不偏右，以致去随从和事奉别的神。'),
('CNV', '申命记', 5, 28, 15, '“但是，如果你不听从耶和华你神的话，不谨守遵行我今日吩咐你的一切诫命和律例，以下这一切咒诅就必临到你身上，把你赶上。'),
('CNV', '申命记', 5, 28, 16, '你在城里必受咒诅，在田间也必受咒诅。'),
('CNV', '申命记', 5, 28, 17, '你的篮子和抟面盆都必受咒诅。'),
('CNV', '申命记', 5, 28, 18, '你身所生的、土地所出的、牛生殖的和羊所产的，都必受咒诅。'),
('CNV', '申命记', 5, 28, 19, '你出必受咒诅，你入也必受咒诅。'),
('CNV', '申命记', 5, 28, 20, '“耶和华必在你手所作的一切事上，使咒诅、纷乱和责备临到你身上，直到你被消灭，速速地灭亡，因为你行恶，离弃了我的缘故。'),
('CNV', '申命记', 5, 28, 21, '耶和华必使瘟疫随着你，直到他把你从你进去得为业的地上灭绝了。'),
('CNV', '申命记', 5, 28, 22, '耶和华必用痨病、热病、炎症、疟疾、干旱、旱风和霉烂打击你；它们必追赶你，直到你灭亡。'),
('CNV', '申命记', 5, 28, 23, '你头上的天必变成铜，你脚下的地必变成铁。'),
('CNV', '申命记', 5, 28, 24, '耶和华必使你地上的雨水变为飞沙尘土，从天上下到你身上，直到你被消灭。'),
('CNV', '申命记', 5, 28, 25, '耶和华必使你在仇敌面前被击败；你从一条路出去攻击他们，必在他们面前从七条路逃跑；你必成为天下万国惊骇的对象。'),
('CNV', '申命记', 5, 28, 26, '你的尸体必成为空中的飞鸟和地上的走兽的食物；必没有人来把它们吓走。'),
('CNV', '申命记', 5, 28, 27, '“耶和华必用埃及人的疮、痔漏、牛皮癣、红疹打击你，这是你不能医治的。'),
('CNV', '申命记', 5, 28, 28, '耶和华必用癫狂、眼瞎、心乱打击你；'),
('CNV', '申命记', 5, 28, 29, '你必在中午的时候摸索，好像瞎子在黑暗中摸索一样；你的道路必不亨通；你必日日受欺压、被抢夺，没有人拯救你。'),
('CNV', '申命记', 5, 28, 30, '你和女子订了婚，别人必和她同寝；你建造房屋，必不得住在里面；你栽种葡萄园，必不得享用它的果子。'),
('CNV', '申命记', 5, 28, 31, '你的牛在你眼前被宰了，你必不得吃它的肉；你的驴从你面前被抢夺了，必不归还给你；你的羊群交给了你的仇敌，必没有人拯救。'),
('CNV', '申命记', 5, 28, 32, '你的儿女必被交给别国的民，你必亲眼看见，日日为他们焦虑；你必无能为力。'),
('CNV', '申命记', 5, 28, 33, '你土地的出产和你劳碌得来的一切，都必被你不认识的民族吃尽；你必常常受压迫和压制；'),
('CNV', '申命记', 5, 28, 34, '你因亲眼看见的，必要疯狂。'),
('CNV', '申命记', 5, 28, 35, '耶和华必用毒疮打击你的双膝和双腿，由踵至顶，使你无法医治。'),
('CNV', '申命记', 5, 28, 36, '耶和华必把你和你所立统治你的君王，领到你和你的列祖都不认识的国那里去；在那里你必事奉别的神，就是木头石头所做的神。'),
('CNV', '申命记', 5, 28, 37, '在耶和华要领你去的各民族中，你必成为使人惊骇、使人嘲笑和讽刺的对象。'),
('CNV', '申命记', 5, 28, 38, '“你带到田间的种子虽然很多，但收进来的却很少，因为蝗虫把它吞吃了。'),
('CNV', '申命记', 5, 28, 39, '你栽种修理葡萄园，必不得收葡萄，也不得喝葡萄酒，因为虫子把它吃尽了。'),
('CNV', '申命记', 5, 28, 40, '你全境必有橄榄树，却没有油抹身，因为你的橄榄还未成熟就脱落了。'),
('CNV', '申命记', 5, 28, 41, '你必生儿养女，却不是属你的，因为他们都要被掳去。'),
('CNV', '申命记', 5, 28, 42, '你所有的树木和你土地的出产，都必被害虫吃光。'),
('CNV', '申命记', 5, 28, 43, '住在你中间的寄居者必渐渐高升，比你高而又高；你必渐渐下降，低而又低。'),
('CNV', '申命记', 5, 28, 44, '他要借给你，你却不能借给他；他必作头，你必作尾。'),
('CNV', '申命记', 5, 28, 45, '这一切咒诅必临到你，必追赶你，必把你追上，直到你被消灭，因为你不听从耶和华你的神的话，没有遵守他吩咐你的诫命和律例。'),
('CNV', '申命记', 5, 28, 46, '这些咒诅必在你和你的后裔身上成为异迹和奇事，直到永远。'),
('CNV', '申命记', 5, 28, 47, '因为你在这样富足的时候，没有以欢乐和高兴的心来事奉耶和华你的神，'),
('CNV', '申命记', 5, 28, 48, '所以你必在饥饿、干渴、赤身露体和缺乏之中，去事奉耶和华派来攻击你的仇敌；他必把铁轭放在你的颈项上，直到把你消灭。'),
('CNV', '申命记', 5, 28, 49, '“耶和华必从远方，从地极把一国的民带来，像鹰一般飞来攻击你；这民的语言你不会听；'),
('CNV', '申命记', 5, 28, 50, '这民脸无羞耻，不顾老年人的情面，也不恩待青年人。'),
('CNV', '申命记', 5, 28, 51, '他们必吞吃你牲畜所生的和你土地所产的，直到把你消灭；必不给你留下五谷、新酒和油、幼小的牛，以及肥嫩的羊，直到使你灭亡为止。'),
('CNV', '申命记', 5, 28, 52, '他们必把你围困在你的各城里，直到在你的全境内你所倚靠高大和坚固的城墙都被攻陷；他们必把你围困在耶和华你的神赐给你的全地的各城里。'),
('CNV', '申命记', 5, 28, 53, '你在仇敌围困和窘迫你的时候，要吃你身所生的，就是吃耶和华你的神赐给你的儿女的肉。'),
('CNV', '申命记', 5, 28, 54, '你们中间温柔嫩弱的男人，必敌视自己的兄弟、怀中的妻子和余剩的儿女；'),
('CNV', '申命记', 5, 28, 55, '甚至在你的仇敌围困和窘迫你在各城里的时候，他要吃自己儿女的肉，却不肯分给他们任何人，因为他没有什么剩下的。'),
('CNV', '申命记', 5, 28, 56, '你们中间温柔娇嫩的妇人，素来因为温柔娇嫩不肯把脚掌踏在地上，现在必敌视自己怀中的丈夫和自己的儿女。'),
('CNV', '申命记', 5, 28, 57, '她暗中把自己两腿之间出来的胞衣，和自己生的儿女吃掉，因为在你的仇敌围困和窘迫你在各城里的时候，她什么都没有了。'),
('CNV', '申命记', 5, 28, 58, '“如果你不谨守遵行写在这书上的这律法的一切话，不敬畏这荣耀和可畏的名，就是耶和华你的神，'),
('CNV', '申命记', 5, 28, 59, '耶和华就必使你和你的后裔遭受奇灾，就是大而长久的灾，毒而长久的病。'),
('CNV', '申命记', 5, 28, 60, '他必使你惧怕的埃及人的各种疾病都临到你身上，紧紧地缠着你。'),
('CNV', '申命记', 5, 28, 61, '又把这律法书上没有记载的各样灾病，都降在你身上，直到你被消灭。'),
('CNV', '申命记', 5, 28, 62, '你们以前虽然像天上的星那么多，现在剩下的人数却寥寥可数，因为你不听从耶和华你的神的话。'),
('CNV', '申命记', 5, 28, 63, '先前耶和华怎样喜欢使你们得好处，使你们人数众多，将来也必怎样喜欢把你们灭亡，把你们消灭；你们必从要进去得为业的地上被拔除。'),
('CNV', '申命记', 5, 28, 64, '耶和华必使你分散在万民中，从地的这边到地的那边；在那里你要事奉你和你的列祖不认识的别的神，就是木头和石头做的神。'),
('CNV', '申命记', 5, 28, 65, '在那些国中，你必不得安息，也没有脚掌歇息的地方；耶和华却必使你在那里心中发颤，眼目憔悴，精神颓废。'),
('CNV', '申命记', 5, 28, 66, '你未来的生命必悬而不定；你必昼夜恐惧，生命难保。'),
('CNV', '申命记', 5, 28, 67, '因你心里的惧怕惊恐和你眼中看见的景象，早晨你必说：‘但愿现在是晚上！’晚上你必说：‘但愿现在是早晨！’'),
('CNV', '申命记', 5, 28, 68, '耶和华必用船把你送回埃及去，走我曾经告诉你，你不得再见的那条路；在那里你们必卖身给你的仇敌作奴仆和作婢女，却没有人买。”'),
('CNV', '申命记', 5, 29, 1, '这些是耶和华在摩押地，吩咐摩西与以色列人所立的约的话，是耶和华和他们在何烈山所立的约以外的。（本节在《马索拉文本》为28:69）'),
('CNV', '申命记', 5, 29, 2, '摩西把以色列众人召了来，对他们说：“耶和华在埃及地，在你们面前，向法老和他的众臣仆，以及他的全国所行的一切，你们都看见了，（本节在《马索拉文本》为29:1）'),
('CNV', '申命记', 5, 29, 3, '就是你亲眼见过的大试验和神迹，以及那些大奇事；'),
('CNV', '申命记', 5, 29, 4, '但是直到今日，耶和华还没有给你们一颗能明白的心，能看见的眼睛，能听见的耳朵。'),
('CNV', '申命记', 5, 29, 5, '我在旷野四十年之久领导你们；你们身上的衣服没有穿破，脚上的鞋也没有穿坏。'),
('CNV', '申命记', 5, 29, 6, '饭你们没有吃，清酒或烈酒你们没有喝，这是要使你们知道耶和华是你们的神。'),
('CNV', '申命记', 5, 29, 7, '你们来到了这地方，希实本王西宏和巴珊王噩就出来，与我们交战，我们击败了他们。'),
('CNV', '申命记', 5, 29, 8, '夺取了他们的地，分给流本人、迦得人和玛拿西半个支派作产业。'),
('CNV', '申命记', 5, 29, 9, '所以你们要谨守这约的话，并且遵行，好使你们在所行的一切事上都亨通。'),
('CNV', '申命记', 5, 29, 10, '“今日你们全都站在耶和华你们的神面前；你们的首领、族长、长老、官长和以色列所有的男子，'),
('CNV', '申命记', 5, 29, 11, '你们的小孩、妻子和在你营中的寄居者，以及为你们劈柴挑水的人，都站在耶和华你们的神面前，'),
('CNV', '申命记', 5, 29, 12, '为要叫你遵守耶和华你的神今日与你所立的约，和他向你所起的誓；'),
('CNV', '申命记', 5, 29, 13, '这样，他今日可以立你作他的子民，他可以作你的神，正如他曾经对你说过的，又对你的列祖亚伯拉罕、以撒、雅各起过誓的。'),
('CNV', '申命记', 5, 29, 14, '“我不但与你们立这约，起这誓；'),
('CNV', '申命记', 5, 29, 15, '而且也与那些今日和我们在这里，一同站在耶和华我们的神面前的人，以及那些今日不与我们同在这里的人立这约，起这誓。'),
('CNV', '申命记', 5, 29, 16, '你们清楚知道我们怎样在埃及地住过，怎样从列国中经过；'),
('CNV', '申命记', 5, 29, 17, '你们也见过他们的可憎之物，和他们那里那些木、石、金、银的偶像。'),
('CNV', '申命记', 5, 29, 18, '恐怕你们中间有男人或女人，家族或支派，今日心里偏离了耶和华我们的神，去事奉那些国的神，又恐怕你们中间有恶根，生出毒草和苦堇来；'),
('CNV', '申命记', 5, 29, 19, '如果人听了这咒诅的话，心里仍然自夸说：‘我虽然照着顽梗的心而行，使好人和恶人一起灭亡，我还有平安。’'),
('CNV', '申命记', 5, 29, 20, '耶和华必不肯饶恕他；耶和华的怒气和愤恨必向这人发作，这书上所写的一切咒诅都要降在那人身上，耶和华也必从天下涂抹他的名。'),
('CNV', '申命记', 5, 29, 21, '耶和华必照着写在这律法书上的约的一切咒诅，把他从以色列众支派中分别出来，使他遭受灾祸。'),
('CNV', '申命记', 5, 29, 22, '“后代的人，就是你们以后兴起来的子孙，和从远方来的外族人，看见了这地的灾难和耶和华降与这地的疾病，'),
('CNV', '申命记', 5, 29, 23, '又看见了遍地有硫磺，有盐卤，有火烧，没有播种，没有出产，寸草不生，好像耶和华在烈怒和怒火中毁灭的所多玛、蛾摩拉、押玛、洗扁一样，'),
('CNV', '申命记', 5, 29, 24, '看见了这些的人和万国的人都要问：‘耶和华为什么向这地这样行呢？为什么大发烈怒呢？’'),
('CNV', '申命记', 5, 29, 25, '人就必回答：‘是因为他们离弃了耶和华他们列祖的神的约，就是耶和华把他们从埃及地领出来的时候，与他们所立的；'),
('CNV', '申命记', 5, 29, 26, '去事奉别的神，向他们叩拜，就是他们不认识的神，也是耶和华没有给他们指定要拜的神；'),
('CNV', '申命记', 5, 29, 27, '所以耶和华向这地大发烈怒，把这书上所写的一切咒诅都降在这地上；'),
('CNV', '申命记', 5, 29, 28, '于是耶和华在烈怒、忿怒和大怒中，把他们从他们的地土拔出来，丢在别的地方，像今天一样。’'),
('CNV', '申命记', 5, 29, 29, '“奥秘的事，是属于耶和华我们的神的，只有显露的事，是永远属于我们和我们子孙的，好叫我们遵行这律法上的一切话。”'),
('CNV', '申命记', 5, 30, 1, '“当这一切事，就是我摆在你面前的祝福和咒诅，都临到你身上的时候，你在耶和华你的神赶逐你去的万国中，你心里必回想这些话，'),
('CNV', '申命记', 5, 30, 2, '你和你的子孙必一心一意归向耶和华你的神，照着我今日吩咐你的一切听从他的话。'),
('CNV', '申命记', 5, 30, 3, '那时，耶和华你的神就必使你这被掳的人回归，他必怜悯你；耶和华你的神必从你被分散到的万民中，把你再召集回来。'),
('CNV', '申命记', 5, 30, 4, '你被赶逐的人，就是在天涯海角，耶和华你的神也必从那里把你召集回来，从那里把你带回。'),
('CNV', '申命记', 5, 30, 5, '耶和华你的神必领你进入你列祖所得之地，使你可以得着这地；他必善待你，他也必使你的人数增多，胜过你的列祖。'),
('CNV', '申命记', 5, 30, 6, '耶和华你的神必把你心里和你后裔心里的污秽除掉，要你一心一意爱耶和华你的神，使你可以存活。'),
('CNV', '申命记', 5, 30, 7, '耶和华你的神必把这一切咒诅，加在你的仇敌和恨恶你、逼迫你的人身上。'),
('CNV', '申命记', 5, 30, 8, '你却要再听从耶和华的话，遵行他的一切诫命，就是我今日吩咐你的。'),
('CNV', '申命记', 5, 30, 9, '耶和华你的神必使你手里所办的一切事、你身所生的、牲畜所出的、地土所产的，都丰盛有余，因为耶和华必再喜悦你，使你得福，像从前喜悦你的列祖一样；'),
('CNV', '申命记', 5, 30, 10, '只要你听从耶和华你的神的话，谨守这律法书上所写的诫命和律例；只要你一心一意回转归向耶和华你的神。'),
('CNV', '申命记', 5, 30, 11, '“其实我今日吩咐你的这诫命，对你并不太难，离你也不太远。'),
('CNV', '申命记', 5, 30, 12, '这诫命不是在天上，以致你说：‘谁替我们上到天上去，为我们取下来，使我们听见，就可以遵行呢？’'),
('CNV', '申命记', 5, 30, 13, '也不是在海外，以致你说：‘谁替我们过海去，为我们取回来，使我们听见，就可以遵行呢？’'),
('CNV', '申命记', 5, 30, 14, '其实这话离你很近，就在你口里，也在你心里，使你可以遵行。'),
('CNV', '申命记', 5, 30, 15, '“你看，我今日把生命和福乐，死亡与灾祸，都摆在你的面前了。'),
('CNV', '申命记', 5, 30, 16, '因此我今日吩咐你要爱耶和华你的神，行他的道路，谨守他的诫命、律例、典章，使你可以存活，人数增多，耶和华你的神就必在你要进去得为业的地上赐福给你。'),
('CNV', '申命记', 5, 30, 17, '但是，如果你的心偏离了，不肯听从，却被人勾引，去敬拜和事奉别的神；'),
('CNV', '申命记', 5, 30, 18, '我今日郑重地告诉你们，你们必要灭亡；在你过约旦河，进去得为业的地上，你的年日必不长久。'),
('CNV', '申命记', 5, 30, 19, '我今日呼天唤地向你们作证，我把生与死，福与祸，都摆在你面前了；所以你要选择生命，好让你和你的后裔都可以活着，'),
('CNV', '申命记', 5, 30, 20, '爱耶和华你的神，听从他的话，紧靠他，因为那就是你的生命，你的长寿；这样，你才能在耶和华向你的列祖亚伯拉罕、以撒、雅各起誓应许要赐给他们的地上居住。”'),
('CNV', '申命记', 5, 31, 1, '摩西又把这些话告诉以色列众人，'),
('CNV', '申命记', 5, 31, 2, '对他们说：“我现今一百二十岁，不能再照常出入了；耶和华也曾对我说：你必不得过这约旦河。'),
('CNV', '申命记', 5, 31, 3, '耶和华你的神要亲自领你们过去，从你们面前消灭这些国的民，使你们得着他们的地，照着耶和华说过的，约书亚要亲自领你们过去。'),
('CNV', '申命记', 5, 31, 4, '耶和华对待他们，必好像从前对待他消灭的亚摩利人的两个王西宏和噩，以及他们的国一样。'),
('CNV', '申命记', 5, 31, 5, '耶和华必把他们交给你们，你们照着我吩咐你们的一切命令对待他们。'),
('CNV', '申命记', 5, 31, 6, '你们要坚强勇敢；不要害怕，也不要因他们畏惧，因为耶和华你的神与你同去；他决不撇下你，也不离弃你。”'),
('CNV', '申命记', 5, 31, 7, '摩西把约书亚召了来，在以色列众人面前对他说：“你要坚强勇敢，因为你要和这人民一同进入耶和华向他们的列祖起誓，应许要赐给他们的地；你也要使他们得着那地为业。'),
('CNV', '申命记', 5, 31, 8, '耶和华亲自在你前头行，与你同在；他决不撇下你，也不离弃你；你不要害怕，也不要惊慌。”'),
('CNV', '申命记', 5, 31, 9, '摩西把这律法写好了，就交给抬耶和华约柜的利未支派的祭司子孙，和以色列的众长老。'),
('CNV', '申命记', 5, 31, 10, '摩西吩咐他们：“每逢七年的最后一年，就是在豁免年的定期，住棚节期间，'),
('CNV', '申命记', 5, 31, 11, '以色列众人来到耶和华你的神选择的地方朝见他的时候，你要在以色列众人面前把这律法宣读给他们听。'),
('CNV', '申命记', 5, 31, 12, '你要召集人民、男人、女人、孩子，以及你城里的寄居者，叫他们可以听见，叫他们可以学习，好敬畏耶和华你们的神，谨守遵行这律法的一切话，'),
('CNV', '申命记', 5, 31, 13, '也叫他们还不认识这律法的儿女可以听见，使他们在你们过约旦河去得为业的地上生活的时候，一生学习敬畏耶和华你们的神。”'),
('CNV', '申命记', 5, 31, 14, '耶和华对摩西说：“看哪，你的死期临近了；你要把约书亚召来，你们二人要站在会幕里，我好吩咐他。”于是摩西和约书亚前去，一同站在会幕里。'),
('CNV', '申命记', 5, 31, 15, '耶和华在会幕里，在云柱中显现，这云柱停在会幕的门口上面。'),
('CNV', '申命记', 5, 31, 16, '耶和华对摩西说：“看哪，你快要和你的列祖长眠了；这人民要起来，在他们所要去的地方，在那地的人中，与外族人的神行邪淫，离弃我，破坏我与他们所立的约。'),
('CNV', '申命记', 5, 31, 17, '到了那日，我必向他们大发烈怒，离弃他们，掩面不顾他们，他们就必被吞灭，并且遭遇很多灾祸和患难。到了那日，他们必说：‘我们遭遇这些灾祸，不是因为我们的神不在我们中间吗？’'),
('CNV', '申命记', 5, 31, 18, '到了那日，因为他们偏向了别的神，和所作的一切恶事，我必掩面不顾他们。'),
('CNV', '申命记', 5, 31, 19, '所以，现在你们要为自己写下这首诗歌来，教导以色列人，放在他们口中，使这首诗歌成为我反对他们的见证。'),
('CNV', '申命记', 5, 31, 20, '因为我把他们领进了我向他们的列祖起誓应许的地，就是流奶与蜜的地，他们在那里吃饱了，发胖了，就必偏向别的神，事奉他们，藐视我，破坏我的约。'),
('CNV', '申命记', 5, 31, 21, '他们遭遇许多灾祸和患难的时候，这首诗歌就必在他们面前作证，因为这首诗歌必不会从他们后裔的口中忘记。其实，我还未领他们进入我起誓应许之地以先，他们今日心里所怀的意念，我都知道了。”'),
('CNV', '申命记', 5, 31, 22, '摩西就在那一天写下了这首诗歌，教导以色列人。'),
('CNV', '申命记', 5, 31, 23, '耶和华吩咐嫩的儿子约书亚，说：“你当坚强勇敢，因为你要领以色列人进我向他们起誓应许的地，我必与你同在。”'),
('CNV', '申命记', 5, 31, 24, '摩西把这律法的话写在书上，直到写完了，'),
('CNV', '申命记', 5, 31, 25, '摩西就吩咐抬耶和华约柜的利未人说：'),
('CNV', '申命记', 5, 31, 26, '“你们要把这律法书，放在耶和华你们的神的约柜旁，可以在那里作反对你们的见证，'),
('CNV', '申命记', 5, 31, 27, '因为我知道你们的悖逆和顽固。看哪，我今日还活着与你们同在的时候，你们尚且悖逆耶和华，何况我死了以后呢？'),
('CNV', '申命记', 5, 31, 28, '你们要把你们各支派的众长老和官长都召集到我这里来，我好把这些话说给他们听，并且呼天唤地对他们作证。'),
('CNV', '申命记', 5, 31, 29, '因为我知道我死了以后，你们必完全败坏，偏离我吩咐你们的道路；在末后的日子必有灾祸临到你们身上，因为你们必行耶和华看为恶的事，以你们手所作的事，惹他发怒。”'),
('CNV', '申命记', 5, 31, 30, '于是摩西把这首诗歌的话，都说给以色列的全体会众听，直到说完了。'),
('CNV', '申命记', 5, 32, 1, '“天哪，留心吧，我要说话；地啊，聆听我口中的言语。'),
('CNV', '申命记', 5, 32, 2, '我的教训下降如雨，我的言语滴落如露，像细雨落在青草上，像甘霖降在蔬菜上。'),
('CNV', '申命记', 5, 32, 3, '因为我要宣告耶和华的名；你们要尊崇我们的神的伟大。'),
('CNV', '申命记', 5, 32, 4, '他是磐石，他的作为完全，因为他一切所行的全都公平；他是诚实无伪的神，又公义，又正直。'),
('CNV', '申命记', 5, 32, 5, '这世代向他行事败坏，就不是他的儿女，满有弊病，这实在是个乖僻弯曲的世代。'),
('CNV', '申命记', 5, 32, 6, '愚昧无知的人民哪，你们这样报答耶和华吗？他不是你的父，不是把你买回来的吗？他造了你，建立了你。'),
('CNV', '申命记', 5, 32, 7, '你要回想古时的日子，思念历代以来的年月；问你的父亲，他必告诉你；问你的长者，他们必对你说。'),
('CNV', '申命记', 5, 32, 8, '至高者把地业赐给列国的时候，把人类分开的时候，就照着以色列子孙的数目，立定了万民的境界。'),
('CNV', '申命记', 5, 32, 9, '但耶和华的分就是他的子民，他的产业就是雅各。'),
('CNV', '申命记', 5, 32, 10, '耶和华在旷野之地遇见了他，在荒凉之地和野兽吼叫的荒野，遇见了他，就环绕他，看顾他，保护他，好像保护自己眼中的瞳人一样。'),
('CNV', '申命记', 5, 32, 11, '又像老鹰搅动巢窝，飞翔在雏鹰之上，搧展翅膀，接取雏鹰，背在自己的两翼之上。'),
('CNV', '申命记', 5, 32, 12, '耶和华独自领导了他，并没有外族人的神与他同在。'),
('CNV', '申命记', 5, 32, 13, '耶和华使他乘驾地的高处，得吃田间的土产；又使他从岩石中吸蜜，从坚固的磐石中取油。'),
('CNV', '申命记', 5, 32, 14, '也吃牛酪和羊乳，羊羔的脂肪，巴珊的公牛和公山羊，以及上好的麦子；也喝了葡萄汁酿成的酒。'),
('CNV', '申命记', 5, 32, 15, '但耶书仑肥胖了，就踢跳，‘你肥胖了，你粗壮了，你饱满了，’他离弃了造他的神，轻看了救他的磐石。'),
('CNV', '申命记', 5, 32, 16, '他们以外族人的神激动了神的愤恨，以可憎之事惹起了他的怒气。'),
('CNV', '申命记', 5, 32, 17, '他们献祭给鬼魔（他们不是神），就是他们从来不认识的神，是近来新兴的，是你们的列祖所不惧怕的。'),
('CNV', '申命记', 5, 32, 18, '你轻忽了生你的磐石，你忘记了产你的神。'),
('CNV', '申命记', 5, 32, 19, '因为他的儿女激怒了神，耶和华看见了，就弃绝了他们，'),
('CNV', '申命记', 5, 32, 20, '说：‘我必掩面不顾他们，要看看他们的结局怎样；因为他们是乖曲的一代，心里没有信实的人。'),
('CNV', '申命记', 5, 32, 21, '他们以不是神的神激动了我的愤恨，以虚无之物惹动了我的怒气；我也以不是子民的人激动他们的愤恨，以愚昧的国民惹动他们的怒气。'),
('CNV', '申命记', 5, 32, 22, '因为在我的怒中有火燃烧起来，烧到阴间的深处，把大地和地的出产尽都吞灭，连山的根基也烧着了。'),
('CNV', '申命记', 5, 32, 23, '我要把灾祸加在他们身上，把我的箭向他们射尽。'),
('CNV', '申命记', 5, 32, 24, '他们必因饥荒消瘦，被热病和毒症消灭；我也要打发野兽用牙齿咬他们，和土中的蛇类用毒液害他们。'),
('CNV', '申命记', 5, 32, 25, '外有刀剑，内有惊恐，使人丧亡，使少男少女，婴孩和白发老人，尽都丧亡。'),
('CNV', '申命记', 5, 32, 26, '我原想：“我要把他们分散到各处，把他们的名号都从人间除灭。”'),
('CNV', '申命记', 5, 32, 27, '但我惧怕仇人激动我，恐怕敌人误会了，又恐怕他们说：“是我们的手高举了，并不是耶和华作了这一切事。”’'),
('CNV', '申命记', 5, 32, 28, '因为他们是缺乏计谋的国，他们心中没有见识。'),
('CNV', '申命记', 5, 32, 29, '如果你们有智慧，就可以明白这事，认清自己将来的结局了。'),
('CNV', '申命记', 5, 32, 30, '如果不是他们的磐石把他们出卖了，如果不是耶和华把他们交出来，一人怎能追赶一千人，二人怎能使万人逃跑呢？'),
('CNV', '申命记', 5, 32, 31, '连我们的仇敌也自己断定，他们的磐石不像我们的磐石。'),
('CNV', '申命记', 5, 32, 32, '因为他们的葡萄树，是所多玛的葡萄树所出的，是蛾摩拉的田地所生的；他们的葡萄是毒葡萄，每一挂都是苦的。'),
('CNV', '申命记', 5, 32, 33, '他们的酒是大蛇的毒液，是虺蛇的剧毒。'),
('CNV', '申命记', 5, 32, 34, '这不是贮藏在我这里，封闭在我的宝库中吗？'),
('CNV', '申命记', 5, 32, 35, '等到他们失足的时候，我要伸冤报应；因为他们遭遇灾难的日子近了，那预备要临到他们身上的事，必快快临到。'),
('CNV', '申命记', 5, 32, 36, '耶和华要为自己的子民伸冤，为自己的仆人难过，因为耶和华看见他们的能力已经消逝，为奴的或自由的都没有剩下一人。'),
('CNV', '申命记', 5, 32, 37, '他必说：‘他们的神在哪里呢？他们投靠的磐石在哪里呢？'),
('CNV', '申命记', 5, 32, 38, '就是向来吃他们祭牲脂肪的，喝他们奠祭之酒的神在哪里呢？让他们兴起来帮助你们吧，愿他们保护你们吧！'),
('CNV', '申命记', 5, 32, 39, '现在你们要知道，只有我是那一位，除我以外，并没有别的神；我使人死，也使人活；我打伤，我也医治；没有人可以从我的手里抢救出去。'),
('CNV', '申命记', 5, 32, 40, '我向天举手说：我活到永永远远；'),
('CNV', '申命记', 5, 32, 41, '如果我磨亮了我的刀剑，如果我掌握了审判权，就必向我的仇敌伸冤，必向恨我的人报应。'),
('CNV', '申命记', 5, 32, 42, '我要使我的箭饮血饮醉，就是被杀的人和被掳的人的血；我的刀剑要吃肉，就是吃仇敌长发首领的肉。’'),
('CNV', '申命记', 5, 32, 43, '列国啊，你们当与耶和华的子民一同欢呼，因为他要伸他仆人流血的冤，他要向他的仇人报复，他要救赎他的地和他的子民。”'),
('CNV', '申命记', 5, 32, 44, '摩西和嫩的儿子约书亚前来，把这首诗歌的一切话都说给人民听。'),
('CNV', '申命记', 5, 32, 45, '摩西向以色列众人说完了这一切话，'),
('CNV', '申命记', 5, 32, 46, '就对他们说：“我今日警告你们的一切话，你们都要放在心上，好吩咐你们的子孙谨守遵行这律法上的一切话。'),
('CNV', '申命记', 5, 32, 47, '因为这不是空洞、与你们无关重要的事，而是你们的生命；藉着这事，你们在过约旦河去得为业的地上，才可以日子长久。”'),
('CNV', '申命记', 5, 32, 48, '就在那一天，耶和华对摩西说：'),
('CNV', '申命记', 5, 32, 49, '“你要上这亚巴琳山去，就是尼波山，在耶利哥对面的摩押地，观看我赐给以色列人为业的迦南地。'),
('CNV', '申命记', 5, 32, 50, '你必死在你登上的山上，归到你的族人那里去，像你的哥哥亚伦死在何珥山上，归到他的族人那里去一样。'),
('CNV', '申命记', 5, 32, 51, '因为你们在寻的旷野，在加低斯米利巴水边，在以色列人中间悖逆我，在以色列人中间没有尊我为圣。'),
('CNV', '申命记', 5, 32, 52, '我赐给以色列人的地，你可以从对面观看，却不得进去。”'),
('CNV', '申命记', 5, 33, 1, '这是神人摩西，在死前给以色列人所祝的福。'),
('CNV', '申命记', 5, 33, 2, '他说：“耶和华从西奈而来，从西珥光照他们，从巴兰山射出光辉，在千万圣者中来临，在他的右手有烈火的律法。'),
('CNV', '申命记', 5, 33, 3, '他实在爱人民，他的众圣者都在你的手里；他们坐在你的脚前，各自领受你的话。'),
('CNV', '申命记', 5, 33, 4, '摩西把律法吩咐我们，作为雅各会众的基业。'),
('CNV', '申命记', 5, 33, 5, '人民的众首领，以色列的各支派，一同会合的时候，耶和华就在耶书仑作王了。'),
('CNV', '申命记', 5, 33, 6, '愿流本生存，不致死亡，愿他的人数不致稀少。”'),
('CNV', '申命记', 5, 33, 7, '论到犹大，他这样说：“耶和华啊，求你垂听犹大的声音，领他归回自己的族人那里；他曾用手为自己奋斗，愿你帮助他抵挡仇敌。”'),
('CNV', '申命记', 5, 33, 8, '论到利未，他说：“耶和华啊，愿你的土明和乌陵属于对你忠心的人（原文无“耶和华啊”，但因为代名词“你”是指耶和华而不是利未，所以按文理补上，以免误导），就是你在玛撒试验过的，在米利巴水边与他们争论过的。'),
('CNV', '申命记', 5, 33, 9, '利未人论到自己的父母说：‘我没有看顾他们’；他不承认自己的兄弟，也不认识自己的儿女；因为他们谨守你的话，持守你的约。'),
('CNV', '申命记', 5, 33, 10, '他们要把你的典章教训雅各，把你的律法教训以色列；他们要把香焚在你面前，把全牲的燔祭献在你的祭坛上。'),
('CNV', '申命记', 5, 33, 11, '耶和华啊，求你赐福他的能力，悦纳他手中的作为；那些起来攻击他和恨他的人，愿你刺透他们的腰，使他们不能再起来。”'),
('CNV', '申命记', 5, 33, 12, '论到便雅悯，他说：“耶和华所爱的，必在耶和华身边安然居住；耶和华终日庇护他，也必住在他的两肩之间。”'),
('CNV', '申命记', 5, 33, 13, '论到约瑟，他说：“愿他的地蒙耶和华赐福，得着从天上而来的上好甘露，以及蕴藏在地里的泉水；'),
('CNV', '申命记', 5, 33, 14, '得着从太阳而来的上好之物，每月所产的佳果；'),
('CNV', '申命记', 5, 33, 15, '得着从太古之山而来的上品，从永远之岭而来的上好之物；'),
('CNV', '申命记', 5, 33, 16, '得着从地所出的上好之物，和其中所充满的；得着那住在荆棘中的耶和华的恩宠；愿这些都临到约瑟的头上，就是临到那在兄弟中作王子的人的头上。'),
('CNV', '申命记', 5, 33, 17, '他头生的公牛大有威严；他的两角是野牛的角，用来抵触万民，直到地极；这角是以法莲的万万，那角是玛拿西的千千。”'),
('CNV', '申命记', 5, 33, 18, '论到西布伦，他说：“西布伦啊，你出外的时候，要喜乐；以萨迦啊，你在帐棚里的时候，也要喜乐。'),
('CNV', '申命记', 5, 33, 19, '他们要把万民召到山上来，在那里要献上公义的祭；因为他们要吸取海洋的丰富，沙土中埋藏着的宝藏。”'),
('CNV', '申命记', 5, 33, 20, '论到迦得，他说：“那使迦得扩张的，是应该称颂的，迦得蹲下如母狮，他撕裂膀臂，连头顶也撕裂。'),
('CNV', '申命记', 5, 33, 21, '他为自己选择了头一份，因为在那里有指挥者的分存留着；他与人民的众首领一同来，他施行耶和华的公义，以及与以色列有关的典章。”'),
('CNV', '申命记', 5, 33, 22, '论到但，他说：“但是只幼狮，从巴珊跳出来。”'),
('CNV', '申命记', 5, 33, 23, '论到拿弗他利，他说：“拿弗他利啊，你饱受恩宠，满得耶和华的福，可以取得西方和南方为业。”'),
('CNV', '申命记', 5, 33, 24, '论到亚设，他说：“愿亚设蒙福，胜过众子，愿他得兄弟的喜悦；愿他把脚蘸在油中。'),
('CNV', '申命记', 5, 33, 25, '你的门闩是铜的，是铁的，你的日子怎样，你的力量也必怎样。'),
('CNV', '申命记', 5, 33, 26, '没有人像耶书仑的神，为了帮助你，他乘驾诸天，在他的威严中，他腾空行云。'),
('CNV', '申命记', 5, 33, 27, '亘古的神是你的居所；他永久的膀臂在你以下。他把仇敌从你面前赶出去，他发令说：‘毁灭吧！’'),
('CNV', '申命记', 5, 33, 28, '所以以色列可以安然居住，雅各的本源，独处在产五谷新酒之地；他的天也滴下甘露。'),
('CNV', '申命记', 5, 33, 29, '以色列啊，你是有福的；有谁像你呢？你这蒙耶和华拯救的子民，他是帮助你的盾牌，他是你威严的刀剑。你的仇敌必向你屈服；你必践踏他们的背脊。”'),
('CNV', '申命记', 5, 34, 1, '摩西从摩押平原上了尼波山，就是上了耶利哥对面的毗斯迦山顶。耶和华把全地指给他看，就是把基列直到但，'),
('CNV', '申命记', 5, 34, 2, '拿弗他利全地，以法莲和玛拿西之地，犹大全地，直到西海，'),
('CNV', '申命记', 5, 34, 3, '南地和那平原，就是棕树城耶利哥的盆地，直到琐珥，都指给他看。'),
('CNV', '申命记', 5, 34, 4, '耶和华对他说：“这就是我曾经向亚伯拉罕、以撒、雅各起誓应许之地，说：‘我要把这地赐给你的后裔。’现在我让你亲眼看见了，可是你不能过到那边去。”'),
('CNV', '申命记', 5, 34, 5, '于是耶和华的仆人摩西，照着耶和华所说的，死在摩押地。'),
('CNV', '申命记', 5, 34, 6, '耶和华把他埋葬在摩押地，伯．毗珥对面的山谷里，只是直到今日还没有人知道埋葬他的地方。'),
('CNV', '申命记', 5, 34, 7, '摩西死的时候，已经一百二十岁；他的眼睛没有昏花，他的精力也没有衰退。'),
('CNV', '申命记', 5, 34, 8, '以色列人在摩押平原为摩西哀哭了三十日；然后为摩西守丧哀哭的日子就满了。'),
('CNV', '申命记', 5, 34, 9, '嫩的儿子约书亚，因为摩西曾经按手在他身上，就充满了智慧的灵；以色列人就听从他，照着耶和华吩咐摩西的去行了。'),
('CNV', '申命记', 5, 34, 10, '以后在以色列中，再没有兴起一位先知像摩西一样的；他是耶和华面对面所认识的。'),
('CNV', '申命记', 5, 34, 11, '耶和华差遣他在埃及地，向法老和他的一切臣仆，以及他的全地行了一切神迹和奇事。'),
('CNV', '申命记', 5, 34, 12, '摩西又在以色列众人眼前行了一切大能的事，和一切大而可畏的事。'),
('CNV', '约书亚记', 6, 1, 1, '耶和华的仆人摩西死了以后，耶和华吩咐摩西的侍从，嫩的儿子约书亚，说：'),
('CNV', '约书亚记', 6, 1, 2, '“我的仆人摩西死了；现在你要起来，和全体人民过这约旦河，到我现在要赐给他们以色列人的地去。'),
('CNV', '约书亚记', 6, 1, 3, '你们脚掌踏过的每一处地方，我都照着我应许摩西的赐给你们了。'),
('CNV', '约书亚记', 6, 1, 4, '从旷野和这黎巴嫩，直到大河，就是幼发拉底河，赫人的全地，以至大海日落的地方，就是你们的疆界。'),
('CNV', '约书亚记', 6, 1, 5, '你一生的日子必没有一人能在你面前立得住；我怎样与摩西同在，也必照样与你同在；我决不离开你，也不离弃你。'),
('CNV', '约书亚记', 6, 1, 6, '你要坚强勇敢，因为你必使这人民得着我曾经向他们列祖起誓，要赐给他们的那地作产业。'),
('CNV', '约书亚记', 6, 1, 7, '你只要坚强，十分勇敢，谨守遵行我仆人摩西吩咐你的一切律法，不可偏离左右，好使你无论到哪里去，都可以亨通。'),
('CNV', '约书亚记', 6, 1, 8, '这律法书不可离开你的口，要昼夜默诵，好使你谨守遵行书中所记的一切；这样，你的道路就必顺利，你必一路亨通。'),
('CNV', '约书亚记', 6, 1, 9, '我不是吩咐过你要坚强勇敢吗？所以，你不要惧怕，也不要惊慌；因为你无论到哪里去，耶和华你的神必与你同在。”'),
('CNV', '约书亚记', 6, 1, 10, '于是约书亚吩咐人民的官长说：'),
('CNV', '约书亚记', 6, 1, 11, '“你们要走遍营中，吩咐人民说：‘你们要预备粮食，因为三天之内，你们要过这约旦河，进去得耶和华你们的神要赐给你们作产业的地。’”'),
('CNV', '约书亚记', 6, 1, 12, '约书亚又对流本人、迦得人和玛拿西半个支派的人说：'),
('CNV', '约书亚记', 6, 1, 13, '“你们要记住耶和华的仆人摩西吩咐你们的话：‘耶和华你们的神赐你们安息，他必把这地赐给你们。’'),
('CNV', '约书亚记', 6, 1, 14, '你们的妻子、孩子和牲畜，都可以留在约旦河东边、摩西赐给你们的地上；但你们所有英勇的战士，都要拿起武器，在你们的兄弟前面过河去，帮助他们；'),
('CNV', '约书亚记', 6, 1, 15, '等到耶和华使你们的兄弟可以和你们一样安居，同样得着耶和华你们的神要赐给他们作产业的地，你们才可以回到你们所得的地，以它作你们的产业，就是耶和华的仆人摩西在约旦河东边日出之地赐给你们的地方。”'),
('CNV', '约书亚记', 6, 1, 16, '他们回答约书亚，说：“你吩咐我们的一切，我们都必遵行；无论你差派我们到哪里去，我们都一定去。'),
('CNV', '约书亚记', 6, 1, 17, '我们从前怎样凡事听从摩西，现在也必照样听从你；唯愿耶和华你的神与你同在，像与摩西同在一样。'),
('CNV', '约书亚记', 6, 1, 18, '无论谁违背你的话，不听从你吩咐他的一切命令，那人必要处死。你只管坚强勇敢。”'),
('CNV', '约书亚记', 6, 2, 1, '于是，嫩的儿子约书亚从什亭秘密地差派两个探子，对他们说：“你们去窥探那地，尤其是耶利哥。”二人去了，来到一个名叫喇合的妓女家中，就在那里住宿。'),
('CNV', '约书亚记', 6, 2, 2, '有人向耶利哥王报告：“今夜从以色列人那里有人进来，要窥探这地。”'),
('CNV', '约书亚记', 6, 2, 3, '耶利哥王派人到喇合那里，说：“把那些来到你这里，进了你家中的人带出来，因为他们来是要窥探全地的。”'),
('CNV', '约书亚记', 6, 2, 4, '但那女人已把那两个人藏起来，还这样回答王：“不错，那些人到过我这里来，但是，我不知道他们是从哪里来的。'),
('CNV', '约书亚记', 6, 2, 5, '天黑、城门快要关的时候，那些人出去了；我不知道他们到哪里去。你们快去追赶，必可以追上他们。”'),
('CNV', '约书亚记', 6, 2, 6, '其实她领他们上了屋顶，把他们藏在堆放在屋顶的麻秸里面。'),
('CNV', '约书亚记', 6, 2, 7, '那些人就沿着往约旦河的路上追赶他们，直到渡口；追赶的人一出城，城门就关上了。'),
('CNV', '约书亚记', 6, 2, 8, '两个探子还没有躺下睡觉，那女人就上屋顶到他们那里去，'),
('CNV', '约书亚记', 6, 2, 9, '对他们二人说：“我知道耶和华已经把这地赐给你们了，你们使我们十分害怕，这地所有的居民都在你们面前胆战心惊。'),
('CNV', '约书亚记', 6, 2, 10, '因为我们听见你们从埃及出来的时候，耶和华怎样使红海的水在你们面前干了，以及你们怎样对待约旦河东亚摩利人的两个王西宏和噩，把他们完全消灭。'),
('CNV', '约书亚记', 6, 2, 11, '我们听见了，就都心里惊怕；没有一人再有勇气在你们面前站立；因为耶和华你们的神是天上、也是地上的神。'),
('CNV', '约书亚记', 6, 2, 12, '现在求你们指着耶和华向我起誓：我既然恩待了你们，你们也要恩待我的父家，并且给我一个确实的凭据，'),
('CNV', '约书亚记', 6, 2, 13, '放过我的父母、兄弟姊妹和他们所有的一切，救我们的命不致死亡。”'),
('CNV', '约书亚记', 6, 2, 14, '两个探子就对她说：“如果你不泄漏我们这次行动，我们愿以性命作你们的保证；耶和华把这地赐给我们的时候，我们必定以慈爱和诚实待你们。”'),
('CNV', '约书亚记', 6, 2, 15, '于是，那女人用绳子把二人从窗户缒下去，因为她的房屋是在城墙上，她就住在城墙上。'),
('CNV', '约书亚记', 6, 2, 16, '她对他们二人说：“你们要到山上去，免得追赶的人遇上你们；你们要在那里躲藏三天，等追赶的人回城，然后你们才可以走你们的路。”'),
('CNV', '约书亚记', 6, 2, 17, '他们二人对她说：“如果你不遵照我们的话行，你叫我们起的誓就与我们无关了。'),
('CNV', '约书亚记', 6, 2, 18, '你要留意，我们再到这地方的时候，你要把这条朱红色线系在你缒我们下去的窗户上；你也要把你的父母、兄弟和你父的全家，都聚集在你的屋里。'),
('CNV', '约书亚记', 6, 2, 19, '任何人走出你家门，到外面去的，他的血就必归到他自己的头上，与我们无关；任何人同你在屋里的，如果有人下手加害他，他的血就归到我们头上。'),
('CNV', '约书亚记', 6, 2, 20, '如果你泄漏了我们这次的行动，那么，你叫我们起的誓就与我们无关了。”'),
('CNV', '约书亚记', 6, 2, 21, '那女人回答：“照你们的话，就这样吧。”于是打发他们二人走了。他们走了以后，她就把朱红色线系在窗户上。'),
('CNV', '约书亚记', 6, 2, 22, '二人离去，上到山上，在那里住了三天，等追赶的人回城去了；追赶的人一路搜寻他们，却找不着。'),
('CNV', '约书亚记', 6, 2, 23, '二人于是下山回去，过了约旦河，回到嫩的儿子约书亚那里，把他们遭遇的一切事向他报告。'),
('CNV', '约书亚记', 6, 2, 24, '他们又对约书亚说：“耶和华真的把那地全交在我们手里了；那地所有的居民都在我们面前胆战心惊。”'),
('CNV', '约书亚记', 6, 3, 1, '约书亚清早起来，和全体以色列人从什亭出发，来到约旦河，在那里住宿，等候过河。'),
('CNV', '约书亚记', 6, 3, 2, '过了三天，官长走遍营中，'),
('CNV', '约书亚记', 6, 3, 3, '吩咐人民说：“你们看见耶和华你们的神的约柜，又看见抬约柜的利未支派的祭司的时候，就要从你们所住的地方出发，跟在约柜后面走。'),
('CNV', '约书亚记', 6, 3, 4, '只是你们和约柜之间应有一段距离，相隔约一公里，不可走近约柜，好使你们知道你们应走的路，因为这条路你们以前没有走过。”'),
('CNV', '约书亚记', 6, 3, 5, '约书亚对人民说：“你们要自洁，因为明天耶和华要在你们中间行奇事。”'),
('CNV', '约书亚记', 6, 3, 6, '约书亚又吩咐祭司说：“你们要抬起约柜，在人民前面过河去。”于是他们抬起约柜，走在人民的前面。'),
('CNV', '约书亚记', 6, 3, 7, '耶和华对约书亚说：“今天起，我要使你在以色列众人眼中成为尊大，这样他们就知道我怎样与摩西同在，也必照样与你同在。'),
('CNV', '约书亚记', 6, 3, 8, '你要吩咐抬着约柜的祭司说：‘你们到了约旦河水边的时候，要站在约旦河中。’”'),
('CNV', '约书亚记', 6, 3, 9, '约书亚对以色列人说：“你们走近这里来，聆听耶和华你们的神的话。'),
('CNV', '约书亚记', 6, 3, 10, '约书亚说：“看哪，全地之主的约柜（“全地之主的约柜”或译：“约柜，全地之主”）必在你们前面过约旦河，你们因此就知道永活的神是在你们中间，他必把迦南人、赫人、希未人、比利洗人、革迦撒人、亚摩利人和耶布斯人，从你们面前驱逐出去。'),
('CNV', '约书亚记', 6, 3, 12, '现在你们要从以色列众支派中选十二个人，每支派一人。'),
('CNV', '约书亚记', 6, 3, 13, '抬全地之主耶和华约柜的祭司的脚掌一踏进约旦河水里，约旦河的水必被截断，那从上游流下来的水必立起成垒。”'),
('CNV', '约书亚记', 6, 3, 14, '人民离开帐棚出发，要过约旦河的时候，抬约柜的祭司在人民的前面。'),
('CNV', '约书亚记', 6, 3, 15, '抬约柜的祭司来到约旦河，他们的脚碰到水边的时候（原来约旦河水在收割的日子，常是涨过两岸的），'),
('CNV', '约书亚记', 6, 3, 16, '水就停住了，那从上游流下来的水立起成垒，在很远的地方，就是在撒拉但旁边的亚当城那里停住；那往下流入亚拉巴海，就是盐海的水完全被截断；于是人民就在耶利哥的对面过了河。'),
('CNV', '约书亚记', 6, 3, 17, '抬耶和华约柜的祭司在约旦河中间的干地上站住，等以色列众人都在干地上走过去，直到全国的人都完全走过了约旦河为止。'),
('CNV', '约书亚记', 6, 4, 1, '全国的人都完全过了约旦河以后，耶和华就吩咐约书亚说：'),
('CNV', '约书亚记', 6, 4, 2, '“你要从人民中选十二个人，每支派一人，'),
('CNV', '约书亚记', 6, 4, 3, '吩咐他们说：‘你们要从这里，就是约旦河中间，祭司的脚所站的地方，取十二块石头，把它们带过来，放在你们今夜要住宿的地方。’”'),
('CNV', '约书亚记', 6, 4, 4, '于是，约书亚把他从以色列人中挑选的十二个人，每支派一人，都召了来。'),
('CNV', '约书亚记', 6, 4, 5, '约书亚对他们说：“你们走到约旦河中间，在耶和华你们的神的约柜前面，按着以色列十二支派的数目，每人拿起一块石头，扛在自己的肩上；'),
('CNV', '约书亚记', 6, 4, 6, '这可以在你们中间作记号；如果日后你们的子孙问你们，说：‘这些石头对你们有什么意思？’'),
('CNV', '约书亚记', 6, 4, 7, '你们就可以告诉他们：‘这是因为约旦河的水在耶和华的约柜前被截断了；约柜过约旦河的时候，约旦河的水被截断了。所以这些石头要给以色列人作记念，直到永远。’”'),
('CNV', '约书亚记', 6, 4, 8, '以色列人就照着约书亚吩咐的行了；他们照着耶和华吩咐约书亚的，按着以色列十二支派的数目，从约旦河中间取了十二块石头，把它们带过去，到他们住宿的地方，就放在那里。'),
('CNV', '约书亚记', 6, 4, 9, '约书亚又在约旦河中间，在抬约柜的祭司的脚所站的地方，竖立十二块石头；那些石头到今日还在那里。'),
('CNV', '约书亚记', 6, 4, 10, '抬约柜的祭司站在约旦河中间，直到耶和华吩咐约书亚告诉人民的一切事，就是照着摩西吩咐约书亚的一切事，都办完了，人民就急忙过去了。'),
('CNV', '约书亚记', 6, 4, 11, '全体人民都过了河以后，耶和华的约柜和祭司才在人民的面前过去。'),
('CNV', '约书亚记', 6, 4, 12, '流本人、迦得人和玛拿西半个支派的人，都照着摩西吩咐他们的，拿起武器，在以色列人前面过河去了。'),
('CNV', '约书亚记', 6, 4, 13, '他们约有四万人，都装备好，预备打仗，在耶和华面前走过去，来到耶利哥的平原，等候作战。'),
('CNV', '约书亚记', 6, 4, 14, '那一天耶和华使约书亚在以色列众人眼中成为尊大；在他一生的日子，人民敬畏他，好像敬畏摩西一样。'),
('CNV', '约书亚记', 6, 4, 15, '耶和华吩咐约书亚说：'),
('CNV', '约书亚记', 6, 4, 16, '“吩咐抬约柜的祭司从约旦河上来。”'),
('CNV', '约书亚记', 6, 4, 17, '于是约书亚吩咐祭司说：“你们从约旦河上来。”'),
('CNV', '约书亚记', 6, 4, 18, '抬耶和华约柜的祭司从约旦河中间上来的时候，祭司的脚掌一提起来踏在干地上，约旦河的水就流回原处，像以前一样涨过两岸。'),
('CNV', '约书亚记', 6, 4, 19, '正月初十，人民从约旦河上来以后，就在吉甲，在耶利哥的东边安营。'),
('CNV', '约书亚记', 6, 4, 20, '约书亚把他们从约旦河取来的那十二块石头，竖立在吉甲。'),
('CNV', '约书亚记', 6, 4, 21, '约书亚对以色列人说：“如果日后你们的子孙问他们的父亲说：‘这些石头是什么意思？’'),
('CNV', '约书亚记', 6, 4, 22, '那时，你们就要告诉你们的子孙，说：‘以色列人曾经在干地上走过了这约旦河。’'),
('CNV', '约书亚记', 6, 4, 23, '因为耶和华你们的神在你们面前使约旦河的水干了，直到你们都过了河，好像耶和华你们的神从前对红海所行的，在我们面前使红海干了，直到我们都过了河一样；'),
('CNV', '约书亚记', 6, 4, 24, '好使地上万民都认识耶和华的手，是有能力的手，也要使你们永远敬畏耶和华你们的神。”'),
('CNV', '约书亚记', 6, 5, 1, '在约旦河西，亚摩利人的众王和靠近海边迦南人的众王，听见耶和华怎样使约旦河的水在以色列人面前干了，直到他们都过河去，他们都心里惊怕，因以色列人的缘故，勇气全失。'),
('CNV', '约书亚记', 6, 5, 2, '那时，耶和华对约书亚说：“你要制造火石刀，第二次给以色列人行割礼。”'),
('CNV', '约书亚记', 6, 5, 3, '约书亚就制造了火石刀，在包皮山那里给以色列人行了割礼。'),
('CNV', '约书亚记', 6, 5, 4, '约书亚给以色列人行割礼的原因是这样：所有从埃及出来的人民，就是所有能作战的男丁，出埃及以后，都死在旷野的路上。'),
('CNV', '约书亚记', 6, 5, 5, '因为所有从埃及出来的人民都受过割礼；唯有从埃及出来以后，所有在旷野的路上出生的人民，都没有受过割礼。'),
('CNV', '约书亚记', 6, 5, 6, '以色列人在旷野走了四十年，直到全国的人，就是从埃及出来能作战的男丁，都灭尽了，因为他们不听耶和华的话；耶和华曾经向他们起誓，必不容许他们看见耶和华向他们列祖起誓要赐给我们的地，就是流奶与蜜的地。'),
('CNV', '约书亚记', 6, 5, 7, '他们的子孙，就是耶和华兴起来代替他们的，约书亚给他们行了割礼；这些人是未受割礼的人，因为他们在路上没有受过割礼。'),
('CNV', '约书亚记', 6, 5, 8, '全国的人受了割礼之后，都住在营中自己的地方，直到痊愈。'),
('CNV', '约书亚记', 6, 5, 9, '耶和华对约书亚说：“我今日把埃及的耻辱从你们身上辊去了。”因此，那地方名叫吉甲（“吉甲”意即“辊”），直到今日。'),
('CNV', '约书亚记', 6, 5, 10, '以色列人在吉甲安营；正月十四日晚上，他们在耶利哥的平原守逾越节。'),
('CNV', '约书亚记', 6, 5, 11, '逾越节后次日，他们吃了那地的出产；就在那一天，吃了无酵饼和烘的谷物。'),
('CNV', '约书亚记', 6, 5, 12, '他们吃了那地的出产之后，第二天吗哪就停止降下；以色列人不再有吗哪了；那一年他们却吃迦南地的出产。'),
('CNV', '约书亚记', 6, 5, 13, '约书亚走近耶利哥的时候，抬头观看，看见一个人站在他对面，手里拿着拔出来的刀。约书亚走到他那里，对他说：“你是我们的人，还是我们的仇敌呢？”'),
('CNV', '约书亚记', 6, 5, 14, '那人回答：“不是的；我现在来是作耶和华军队的元帅。”约书亚就脸伏在地，向他下拜，对他说：“我主有什么事要吩咐仆人呢？”'),
('CNV', '约书亚记', 6, 5, 15, '耶和华军队的元帅对约书亚说：“把你脚上的鞋脱下来，因为你站的地方是圣地。”约书亚就照着行了。'),
('CNV', '约书亚记', 6, 6, 1, '耶利哥的城门因以色列人的缘故，就紧紧地关闭，没有人出入。'),
('CNV', '约书亚记', 6, 6, 2, '耶和华对约书亚说：“看，我已经把耶利哥和耶利哥的王，以及英勇的战士，都交在你的手中了。'),
('CNV', '约书亚记', 6, 6, 3, '你们所有能作战的男丁要围绕这城，一天围绕一次，六天都要这样行；'),
('CNV', '约书亚记', 6, 6, 4, '并派七个祭司拿着七个羊角，走在约柜的前面；到第七天，你们要绕城七次，祭司也要吹角。'),
('CNV', '约书亚记', 6, 6, 5, '当羊角吹起长号，你们听见角声的时候，全体人民要大声呼喊，那时城墙就必塌陷；你们各人要向前直冲。”'),
('CNV', '约书亚记', 6, 6, 6, '于是嫩的儿子约书亚把祭司召了来，对他们说：“你们要抬起约柜；并派七个祭司拿着七个羊角，走在耶和华约柜的前面。”'),
('CNV', '约书亚记', 6, 6, 7, '他又对人民说：“你们前去绕城吧，拿武器的人要走在耶和华约柜的前面。”'),
('CNV', '约书亚记', 6, 6, 8, '约书亚吩咐人民以后，七个祭司拿着七个羊角，走在耶和华的前面，并且吹角，耶和华的约柜在他们后面跟着走。'),
('CNV', '约书亚记', 6, 6, 9, '拿武器的人走在吹角的祭司前面，在约柜后面也有防卫的队伍跟着走，祭司一面走，一面吹角。'),
('CNV', '约书亚记', 6, 6, 10, '约书亚吩咐人民说：“你们不可呼喊，不可让人听见你们的声音，连一句话也不可出口，等到我吩咐你们‘呼喊’的那天，你们才可以呼喊。”'),
('CNV', '约书亚记', 6, 6, 11, '这样，耶和华的约柜绕城而行，围绕了一次，众人就回到营中，在营里住宿。'),
('CNV', '约书亚记', 6, 6, 12, '约书亚清早起来，祭司又抬起耶和华的约柜。'),
('CNV', '约书亚记', 6, 6, 13, '拿着七个羊角的七位祭司，走在耶和华的约柜前面；一面走，一面吹角；拿武器的人走在他们前面，在耶和华的约柜后面也有防卫的队伍跟着走；祭司一面走，一面吹角。'),
('CNV', '约书亚记', 6, 6, 14, '第二日，众人又绕城一次，然后回到营里去；六日他们都是这样行。'),
('CNV', '约书亚记', 6, 6, 15, '到了第七日，清早黎明的时候，他们起来，以同样的方式绕城七次；只有这一日，他们绕城七次。'),
('CNV', '约书亚记', 6, 6, 16, '到了第七次，祭司吹角的时候，约书亚就对人民说：“你们呼喊吧，因为耶和华已经把这城赐给你们了。'),
('CNV', '约书亚记', 6, 6, 17, '这城要完全毁灭，城和城中的一切都归耶和华；只有妓女喇合，和所有与她在家中的都可以存活，因为她收藏了我们派去的使者。'),
('CNV', '约书亚记', 6, 6, 18, '不过你们要谨慎，不可取那当毁灭的物，恐怕你们贪心，取了那当毁灭的物，就使以色列营成为当毁灭的，使以色列营遭遇灾祸。'),
('CNV', '约书亚记', 6, 6, 19, '可是，所有的金银和铜铁的器皿，都要归耶和华为圣，存入耶和华的库房中。”'),
('CNV', '约书亚记', 6, 6, 20, '于是人民呼喊，祭司也吹角。人民听见角声的时候，就大声呼喊，城墙就塌陷了；于是，人民冲入城中，人人向前，把城攻取。'),
('CNV', '约书亚记', 6, 6, 21, '他们把城中的一切，无论男女老幼、牛羊和驴，都用刀杀尽。'),
('CNV', '约书亚记', 6, 6, 22, '约书亚对窥探那地的两个人说：“你们进那妓女的家里去，照着你们向她所起的誓，把那女人和她所有的一切，都从家里带出来。”'),
('CNV', '约书亚记', 6, 6, 23, '那两个年轻密探就进去，把喇合和她的父母、兄弟、她所有的一切，以及她所有的亲属，都领出来，安置在以色列的营外。'),
('CNV', '约书亚记', 6, 6, 24, '众人把城和城中的一切都用火烧了；只有金银和铜铁的器皿都放入耶和华圣所的库房里。'),
('CNV', '约书亚记', 6, 6, 25, '约书亚却放过妓女喇合和她的父家，以及她所有的一切；她住在以色列中，直到今日，因为她收藏了约书亚派去窥探耶利哥的使者。'),
('CNV', '约书亚记', 6, 6, 26, '那时，约书亚要人民起誓，说：“起来重建这耶利哥城的，那人在耶和华面前是可咒可诅的；他立地基的时候必丧长子；他安城门的时候必失幼子。”'),
('CNV', '约书亚记', 6, 6, 27, '耶和华与约书亚同在；约书亚的名声传遍全地。'),
('CNV', '约书亚记', 6, 7, 1, '以色列人在那当毁灭的物上犯了不忠实的罪；因为犹大支派中，谢拉的曾孙、撒底的孙子、迦米的儿子亚干，取了当毁灭的物，耶和华就向以色列人发怒。'),
('CNV', '约书亚记', 6, 7, 2, '那时，约书亚从耶利哥派人到伯特利东边，靠近伯．亚文的艾城去，吩咐他们说：“你们上去窥探那地。”那些人就上去，窥探艾城。'),
('CNV', '约书亚记', 6, 7, 3, '他们回来，对约书亚说：“不需要全体人民都上去；只要大约二三千人就可以上去攻打艾城了；不必劳动全体人民都上那里去，因为那里的人很少。”'),
('CNV', '约书亚记', 6, 7, 4, '于是人民中约有三千人上那里去，但他们竟在艾城的人面前逃跑了。'),
('CNV', '约书亚记', 6, 7, 5, '艾城的人击杀了他们约三十六人；从城门前追赶他们，一直追到示巴琳；在山坡上把他们击溃；人民的心就极其惊怕。'),
('CNV', '约书亚记', 6, 7, 6, '约书亚就撕裂自己的衣服，和以色列人的长老，在耶和华的约柜前，一同俯伏在地，直到晚上，也把尘土撒在头上。'),
('CNV', '约书亚记', 6, 7, 7, '约书亚说：“唉！主耶和华啊，你为什么领这人民过约旦河，为要把我们交在亚摩利人的手中，使我们灭亡呢？我们宁愿住在约旦河那边倒好。'),
('CNV', '约书亚记', 6, 7, 8, '主啊！以色列人既然在仇敌面前转身逃跑，我还有什么可说的呢？'),
('CNV', '约书亚记', 6, 7, 9, '迦南人和这地所有的居民听见了，就必围困我们，把我们的名字从这世上剪除，那时你为你的大名要怎样行呢？”'),
('CNV', '约书亚记', 6, 7, 10, '耶和华对约书亚说：“你起来，为什么这样脸伏在地呢？'),
('CNV', '约书亚记', 6, 7, 11, '以色列人犯了罪，违背了我吩咐他们的约定，因为他们取了那当毁灭的物，他们偷窃，并且说谎，又把那当毁灭的物放在自己的物件中。'),
('CNV', '约书亚记', 6, 7, 12, '所以，以色列人在他们的仇敌面前站立不住，在他们的仇敌面前转身逃跑，因为他们成了当毁灭的。如果你们不把那当毁灭的物从你们中间除掉，我就必不再与你们同在了。'),
('CNV', '约书亚记', 6, 7, 13, '你起来，要人民自洁，对他们说：‘你们要自洁，预备明天；因为耶和华以色列的神这样说：以色列啊！你们中间有那当毁灭的物；除非你们把那当毁灭的物从你们中间除去，你们在仇敌的面前就不能站立得住。'),
('CNV', '约书亚记', 6, 7, 14, '到了早晨，你们要按着支派前来，耶和华抽签抽中的支派，要按着宗族前来；耶和华抽签抽中的宗族，要按着家庭前来；耶和华抽签抽中的家庭，男丁要一个一个前来。'),
('CNV', '约书亚记', 6, 7, 15, '如果那藏有当毁灭的物的人被抽签抽中了，他和他所有的一切都要用火焚烧；因为他违背了耶和华的约，又因为他在以色列中作了愚昧的事。’”'),
('CNV', '约书亚记', 6, 7, 16, '约书亚清早起来，要以色列人按着支派前来；结果，犹大支派被抽签抽中了；'),
('CNV', '约书亚记', 6, 7, 17, '他要犹大宗族前来，结果，谢拉的家族被抽签抽中了；他要谢拉家族的男丁一个一个前来，结果，撒底被抽签抽中了；'),
('CNV', '约书亚记', 6, 7, 18, '他要撒底家中的男丁一个一个前来，结果，亚干被抽签抽中了，亚干是迦米的儿子、撒底的孙子、谢拉的曾孙，是属于犹大支派的。'),
('CNV', '约书亚记', 6, 7, 19, '约书亚对亚干说：“我儿，我劝你把荣耀归给耶和华以色列的神，向他认罪，告诉我你作了什么事，不可向我隐瞒。”'),
('CNV', '约书亚记', 6, 7, 20, '亚干回答约书亚，说：“我实在得罪了耶和华以色列的神；我作过的事是这样的。'),
('CNV', '约书亚记', 6, 7, 21, '我在战利品中，看见了一件美丽的示拿衣服、二千二百八十克银子，和一条重五百七十克的金条；我因贪爱这些物件，就把它们拿去了；现在埋藏在我帐棚的地里，银子在底下。”'),
('CNV', '约书亚记', 6, 7, 22, '约书亚就派人跑到亚干的帐棚里，果然见到东西埋藏在那里，银子在底下。'),
('CNV', '约书亚记', 6, 7, 23, '他们就把东西从帐棚中拿出来，带到约书亚和以色列人那里，摆在耶和华面前。'),
('CNV', '约书亚记', 6, 7, 24, '约书亚和全体以色列人一起把谢拉的曾孙亚干和那银子、那件衣服、那金条，以及亚干的儿女、牛、驴、羊、帐棚和他所有的一切，都带上亚割谷去。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '约书亚记', 6, 7, 25, '约书亚说：“你为什么给我们招惹灾祸呢？今天耶和华必使你遭受灾祸。”于是全体以色列人用石头把他打死。他们用石头打死他们以后，就把一切用火烧了。'),
('CNV', '约书亚记', 6, 7, 26, '众人又在亚干身上堆起了一大堆石头，这堆石头一直存到今日；于是耶和华就回心转意，不发烈怒。因此那地方名叫亚割谷，直到今日。'),
('CNV', '约书亚记', 6, 8, 1, '耶和华对约书亚说：“你不要惧怕，也不要惊慌，你只管带领所有能作战的人，起来上艾城去；你看，我已经把艾城的王和他的人民、城市、土地都交在你手里了。'),
('CNV', '约书亚记', 6, 8, 2, '你怎样对待耶利哥和耶利哥的王，也要照样对待艾城和艾城的王；只是城中的战利品和牲畜，你们可以据为己有；你要在城后面设下攻城的伏兵。”'),
('CNV', '约书亚记', 6, 8, 3, '于是，约书亚和所有能作战的人都起来上艾城去；约书亚选了三万英勇的战士，趁夜派他们出去，'),
('CNV', '约书亚记', 6, 8, 4, '吩咐他们说：“你们注意，要在城后面埋伏攻城；不可离城太远，人人都要作好准备。'),
('CNV', '约书亚记', 6, 8, 5, '我和所有与我一起的人，要向城推进。城里的人像前一次出来攻击我们的时候，我们就在他们面前逃跑；'),
('CNV', '约书亚记', 6, 8, 6, '他们必定出来追赶我们，我们就把他们引出城来，因为他们必定说：‘这些人像前一次一样在我们面前逃跑了。’所以我们要在他们面前逃跑。'),
('CNV', '约书亚记', 6, 8, 7, '那时你们就要从埋伏的地方起来，占领那城，因为耶和华你们的神必把城交在你们的手里。'),
('CNV', '约书亚记', 6, 8, 8, '你们占领了城以后，就要放火烧城；要照着耶和华的话行事；你们要谨慎，我已经吩咐你们了。”'),
('CNV', '约书亚记', 6, 8, 9, '约书亚差派他们去了，他们就上到埋伏的地方去，住在伯特利和艾城的中间，就是在艾城的西边。那一夜，约书亚却在人民中间住宿。'),
('CNV', '约书亚记', 6, 8, 10, '约书亚清早起来，召集人民上艾城去，他和以色列的长老走在人民的前面。'),
('CNV', '约书亚记', 6, 8, 11, '所有与他在一起的战士都上去，迫近艾城，在城的北面安营；在约书亚和艾城中间有一个山谷，'),
('CNV', '约书亚记', 6, 8, 12, '约书亚挑了大约五千人，要他们埋伏在伯特利和艾城中间，就是艾城的西面。'),
('CNV', '约书亚记', 6, 8, 13, '于是他们把众民，就是在城北的全军和在城西的伏兵都布置好了。那一夜，约书亚走进了山谷之中。'),
('CNV', '约书亚记', 6, 8, 14, '艾城的王看见了这情形，就和艾城的人急忙在清早起来，按着亚拉巴前面所约定之处出到亚拉巴，要与以色列人交战；王却不知道在城后面有伏兵要攻击他。'),
('CNV', '约书亚记', 6, 8, 15, '约书亚和以色列人在他们面前装败，沿着通往旷野的路逃跑。'),
('CNV', '约书亚记', 6, 8, 16, '城里的众民都被召集，去追赶他们；艾城的人追赶约书亚的时候，就都被诱离城。'),
('CNV', '约书亚记', 6, 8, 17, '艾城和伯特利城没有留下一个人不出来追赶以色列人；他们撇下了敞开的城门，去追赶以色列人。'),
('CNV', '约书亚记', 6, 8, 18, '耶和华对约书亚说：“你向着艾城伸出你手中的短枪，因为我要把城交在你手里。”约书亚就向着艾城伸出他手里的短枪。'),
('CNV', '约书亚记', 6, 8, 19, '他一伸手，伏兵就从埋伏的地方急忙起来，冲进城去，把城夺取，并连忙放火烧城。'),
('CNV', '约书亚记', 6, 8, 20, '艾城的人转身观看，看见城里浓烟冲天，就全身乏力，不能逃跑；往旷野逃跑的以色列人就转过来攻击追赶他们的人。'),
('CNV', '约书亚记', 6, 8, 21, '约书亚和以色列人看见伏兵已经夺取了城，又看见城中浓烟上升，就转回，击杀艾城的人。'),
('CNV', '约书亚记', 6, 8, 22, '伏兵也出城攻击艾城的人；艾城的人就被困在以色列人中间，前后受敌；于是以色列人把他们击杀，没有留下一个，也没有一个逃脱。'),
('CNV', '约书亚记', 6, 8, 23, '他们活捉了艾城的王，把他解到约书亚那里。'),
('CNV', '约书亚记', 6, 8, 24, '以色列人在田间、在旷野，杀尽了所有追赶他们的艾城的居民，艾城的人全部倒在刀下，直到完全消灭；接着，以色列众人回到艾城，用刀击杀了城中的人。'),
('CNV', '约书亚记', 6, 8, 25, '那一天被杀的人，连男带女，共有一万二千人，就是艾城所有的人。'),
('CNV', '约书亚记', 6, 8, 26, '约书亚没有收回伸出短枪的手，直到把艾城的居民都消灭为止。'),
('CNV', '约书亚记', 6, 8, 27, '只有那城里的牲畜和战利品，以色列人照着耶和华吩咐约书亚的话，都据为己有。'),
('CNV', '约书亚记', 6, 8, 28, '约书亚烧了艾城，使城永远成为废堆，一片荒凉，直到今日。'),
('CNV', '约书亚记', 6, 8, 29, '他又把艾城的王悬在树上，直到黄昏的时候；日落的时候，约书亚吩咐人把尸体从树上拿下来，丢在城门口那里，又在尸体上堆起了一大堆石头，这堆石头一直存到今日。'),
('CNV', '约书亚记', 6, 8, 30, '那时，约书亚在以巴路山上，为耶和华以色列的神筑了一座祭坛，'),
('CNV', '约书亚记', 6, 8, 31, '是照着耶和华的仆人摩西吩咐以色列人的，照着摩西律法书上所写的，用未经过铁器打凿的整块石块筑成的一座祭坛；在这祭坛之上，众人向耶和华献燔祭，也献平安祭。'),
('CNV', '约书亚记', 6, 8, 32, '约书亚在那里，当着以色列人面前，把摩西所写的摩西律法抄写在石头上。'),
('CNV', '约书亚记', 6, 8, 33, '全体以色列人和他们的长老、官长，以及审判官，都站在约柜的两旁，在抬耶和华约柜的利未支派的祭司前面；无论是寄居的，或是本地人，一半对着基利心山，一半对着以巴路山；正如耶和华的仆人摩西以前所吩咐的，好为以色列民祝福。'),
('CNV', '约书亚记', 6, 8, 34, '然后，约书亚宣读律法上一切祝福和咒诅的话，全都照着律法书上所写的一切。'),
('CNV', '约书亚记', 6, 8, 35, '摩西吩咐的一切话，约书亚在以色列全体会众和妇女、小孩，以及在他们中间来往的寄居者面前，没有一句不向他们宣读出来的。'),
('CNV', '约书亚记', 6, 9, 1, '在约旦河西，住在山上、高原和对着黎巴嫩山大海沿岸所有的王，就是赫人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人的王，听见了这些事的时候，'),
('CNV', '约书亚记', 6, 9, 2, '就聚集起来，同心协力地要与约书亚和以色列人交战。'),
('CNV', '约书亚记', 6, 9, 3, '基遍的居民听见了约书亚向耶利哥和艾城所行的事，'),
('CNV', '约书亚记', 6, 9, 4, '就施诡计，假冒使者而来，把旧的布袋和破裂又修补过的旧皮酒袋驮在驴上，'),
('CNV', '约书亚记', 6, 9, 5, '脚上穿着补过的旧鞋，身穿旧衣服，所带的食物又干又碎。'),
('CNV', '约书亚记', 6, 9, 6, '他们去到吉甲营中约书亚那里，对约书亚和以色列人说：“我们是从远地来的，现在求你们和我们立约。”'),
('CNV', '约书亚记', 6, 9, 7, '以色列人对这些希未人说：“你们也许是这地的居民，若是这样，我们怎样和你们立约呢？”'),
('CNV', '约书亚记', 6, 9, 8, '他们对约书亚说：“我们是你的仆人。”约书亚问他们：“你们是什么人？是从哪里来的？”'),
('CNV', '约书亚记', 6, 9, 9, '他们回答约书亚：“你的仆人为了耶和华你神的名从很远的地方而来，因为我们听见了他的名声和他在埃及所行的一切事，'),
('CNV', '约书亚记', 6, 9, 10, '以及他对约旦河东亚摩利人的两个王，就是希实本王西宏和在亚斯他录的巴珊王噩，所行的一切事。'),
('CNV', '约书亚记', 6, 9, 11, '所以我们的长老和我们本国所有的居民对我们说：‘你们手里要带着旅途用的干粮，去迎见以色列人，对他们说：我们是你们的仆人，现在求你们和我们立约。’'),
('CNV', '约书亚记', 6, 9, 12, '我们出门到你们这里来的时候，从家里带出来作干粮的这饼还是热的；看哪，现在都又干又碎了。'),
('CNV', '约书亚记', 6, 9, 13, '这些皮酒袋，我们盛酒的时候，还是新的；你看，现在都破裂了。我们这些衣服和鞋因路途遥远，都穿旧了。”'),
('CNV', '约书亚记', 6, 9, 14, '以色列人取了他们一些食物，却没有求问耶和华的旨意。'),
('CNV', '约书亚记', 6, 9, 15, '于是约书亚与他们议和，和他们立约，容他们存活；会众的首领也向他们起了誓。'),
('CNV', '约书亚记', 6, 9, 16, '以色列人和他们立约之后，过了三天，才听见他们是自己的近邻，是住在这地的居民。'),
('CNV', '约书亚记', 6, 9, 17, '于是，以色列人起程，第三日就到了他们的城市；他们的城市就是基遍、基非拉、比录、基列．耶琳。'),
('CNV', '约书亚记', 6, 9, 18, '以色列人没有击杀他们，因为会众的首领曾经指着耶和华以色列的神向他们起了誓，全体会众就都向首领发怨言。'),
('CNV', '约书亚记', 6, 9, 19, '众首领对全体会众说：“我们曾经指着耶和华以色列的神向他们起了誓，现在我们不能伤害他们。'),
('CNV', '约书亚记', 6, 9, 20, '我们要这样待他们，就是容他们存活，免得神的忿怒因我们向他们所起的誓，临到我们身上。”'),
('CNV', '约书亚记', 6, 9, 21, '众首领又对会众说：“要让他们存活。”于是他们就给全体会众作了劈柴打水的人，这是按照众首领对他们的吩咐。'),
('CNV', '约书亚记', 6, 9, 22, '约书亚把他们召了来，质问他们：“你们为什么欺骗我们说：‘我们离你们很远’，其实你们却是住在这地的？'),
('CNV', '约书亚记', 6, 9, 23, '现在你们要受到咒诅，你们中间必不断有人作奴仆，为我神的圣所作劈柴打水的人。”'),
('CNV', '约书亚记', 6, 9, 24, '他们回答约书亚，说：“因为你的仆人确实地听见，耶和华你的神曾经吩咐他的仆人摩西，要把这整片土地赐给你们，并且要在你们面前把这地上所有的居民都消灭，因此，我们因你们的缘故，很怕丧命，才行了这事。'),
('CNV', '约书亚记', 6, 9, 25, '现在，你看，我们都在你的手里，你看怎样处置我们算为好、算为对，就怎样行吧。”'),
('CNV', '约书亚记', 6, 9, 26, '约书亚就这样处置他们，救了他们脱离以色列人的手，以色列人就没有杀他们。'),
('CNV', '约书亚记', 6, 9, 27, '在那一天，约书亚指派他们在耶和华选择的地方，为会众和耶和华的祭坛作劈柴打水的人，直到今日。'),
('CNV', '约书亚记', 6, 10, 1, '耶路撒冷王亚多尼．洗德听见约书亚占领了艾城，把城完全毁灭，约书亚怎样对待耶利哥和耶利哥的王，也照样对待艾城和艾城的王；又听见基遍的居民已经与以色列人议和，并可以住在这地，'),
('CNV', '约书亚记', 6, 10, 2, '他们就非常惧怕。因为基遍是大城，好像一座王城；又因为基遍比艾城大，城里所有的人都是勇士。'),
('CNV', '约书亚记', 6, 10, 3, '因此，耶路撒冷王亚多尼．洗德派人到希伯仑王何咸、耶末王毗兰、拉吉王雅非亚和伊矶伦王底璧那里去，对他们说：'),
('CNV', '约书亚记', 6, 10, 4, '“求你们上我这里来帮助我，我们好攻打基遍，因为基遍已经与约书亚和以色列人议和了。”'),
('CNV', '约书亚记', 6, 10, 5, '于是亚摩利人的那五个王，就是耶路撒冷王、希伯仑王、耶末王、拉吉王和伊矶伦王，联合起来，带着他们所有的军队上去，在基遍的对面安营，攻打基遍。'),
('CNV', '约书亚记', 6, 10, 6, '基遍人就派人到吉甲营中约书亚那里去，说：“不可丢弃你的仆人，求你快快上我们这里来拯救我们、帮助我们；因为住在山地的亚摩利人所有的王都集合起来攻击我们。”'),
('CNV', '约书亚记', 6, 10, 7, '于是约书亚和所有能作战的人，以及所有英勇的战士，都一起从吉甲上去。'),
('CNV', '约书亚记', 6, 10, 8, '耶和华对约书亚说：“你不要怕他们，因为我已经把他们交在你手里了；他们必没有一人能在你面前站立得住。”'),
('CNV', '约书亚记', 6, 10, 9, '于是约书亚乘夜从吉甲上去，突然来到他们那里。'),
('CNV', '约书亚记', 6, 10, 10, '耶和华使他们在以色列人面前溃乱，约书亚在基遍大大地击杀他们，沿着伯．和仑的上坡路追赶他们，击打他们，直到亚西加和玛基大。'),
('CNV', '约书亚记', 6, 10, 11, '他们从以色列人面前逃跑，正在下伯．和仑斜坡的时候，耶和华从天上降大冰雹在他们身上，一直到亚西加，打死他们；被冰雹打死的，比以色列人用刀杀死的还多。'),
('CNV', '约书亚记', 6, 10, 12, '那时，就是耶和华把亚摩利人交给以色列人的时候，约书亚在以色列人面前对耶和华说：“太阳啊，停在基遍；月亮啊，停在亚雅仑谷。”'),
('CNV', '约书亚记', 6, 10, 13, '于是太阳停住，月亮站住，直到以色列人在仇敌的身上报了仇。这事不是写在《雅煞珥书》上吗？太阳在天空中站住，不急速下落，约有一整天。'),
('CNV', '约书亚记', 6, 10, 14, '在这日以前或这日以后，耶和华听人的祷告，没有像这日一样的，因为耶和华为以色列作战。'),
('CNV', '约书亚记', 6, 10, 15, '后来，约书亚和众以色列人回到吉甲营那里去。'),
('CNV', '约书亚记', 6, 10, 16, '那五个王逃跑了，躲藏在玛基大洞里。'),
('CNV', '约书亚记', 6, 10, 17, '有人告诉约书亚，说：“那五个王已经找到了，都躲藏在玛基大洞里。”'),
('CNV', '约书亚记', 6, 10, 18, '约书亚说：“你们把几块大石头辊到洞口那里去，并派人到洞口去看守他们。'),
('CNV', '约书亚记', 6, 10, 19, '你们却不可站着，要追赶你们的仇敌，从后面击杀他们，不可让他们逃进自己的城中，因为耶和华你们的神已经把他们交在你们的手里了。”'),
('CNV', '约书亚记', 6, 10, 20, '约书亚和以色列人把他们杀得惨败，直到把他们灭绝为止，那些逃脱的人都逃进设防的城里；'),
('CNV', '约书亚记', 6, 10, 21, '众以色列人都平平安安回到玛基大营中约书亚那里。没有人敢说话攻击以色列人。'),
('CNV', '约书亚记', 6, 10, 22, '约书亚说：“你们打开洞口，把那五个王从洞里拉出来，带到我这里来。”'),
('CNV', '约书亚记', 6, 10, 23, '众人就照着执行，他们把那五个王，就是耶路撒冷王、希伯仑王、耶末王、拉吉王和伊矶伦王，从洞里拉出来，带到约书亚那里去。'),
('CNV', '约书亚记', 6, 10, 24, '众人把那五个王带到约书亚那里去的时候，约书亚把所有的以色列人都召了来，对那些与他同去作战的军长说：“你们走前来，把脚踏在这些王的颈项上。”他们就走前来，把脚踏在那些王的颈项上。'),
('CNV', '约书亚记', 6, 10, 25, '约书亚对他们说：“你们不要惧怕，不要惊慌；总要坚强勇敢，因为耶和华必这样对待你们要攻打的所有仇敌。”'),
('CNV', '约书亚记', 6, 10, 26, '随后，约书亚把那五个王杀死，悬在五棵树上；他们就悬在树上，直到晚上。'),
('CNV', '约书亚记', 6, 10, 27, '到了日落的时候，约书亚吩咐人把他们从树上取下来，丢在他们躲藏过的洞里，把几块大石头放在洞口；这些石头一直存到今日。'),
('CNV', '约书亚记', 6, 10, 28, '在那天，约书亚占领了玛基大，用刀击杀了那城的人和那城的王，把城中所有的人完全毁灭，不容一人逃脱；他对待玛基大王就像对待耶利哥王一样。'),
('CNV', '约书亚记', 6, 10, 29, '约书亚和跟他在一起的众以色列人从玛基大往立拿去，攻打立拿。'),
('CNV', '约书亚记', 6, 10, 30, '耶和华把立拿和立拿的王也交在以色列人手里，约书亚用刀攻击那城，杀了城里所有的人，不容一人逃脱；他对待立拿王就像对待耶利哥王一样。'),
('CNV', '约书亚记', 6, 10, 31, '约书亚和跟他在一起的众以色列人从立拿往拉吉去，对着拉吉安营，攻打这城。'),
('CNV', '约书亚记', 6, 10, 32, '耶和华把拉吉交在以色列人手里，第二天约书亚就占领了拉吉，用刀攻击那城，杀了城中所有的人，跟他对立拿所行的一切一样。'),
('CNV', '约书亚记', 6, 10, 33, '那时，基色王荷兰上来帮助拉吉，约书亚就把他和他的人民都击杀了，没有留下一人。'),
('CNV', '约书亚记', 6, 10, 34, '约书亚和与他在一起的众以色列人从拉吉往伊矶伦去，对着伊矶伦安营，攻打这城。'),
('CNV', '约书亚记', 6, 10, 35, '那一天，他们占领了这城，用刀攻击那城，杀了城中所有的人；那一天约书亚把他们完全毁灭，跟他对拉吉所行的一切一样。'),
('CNV', '约书亚记', 6, 10, 36, '约书亚和与他在一起的众以色列人从伊矶伦上希伯仑去，攻打这城。'),
('CNV', '约书亚记', 6, 10, 37, '他们占领了这城，用刀攻击这城，杀了这城的王，又攻击属于这城的城镇，杀了城中所有的人，不容一人逃脱，跟他对伊矶伦所行的一切一样，把这城和城中所有的人完全毁灭。'),
('CNV', '约书亚记', 6, 10, 38, '约书亚和与他在一起的众以色列人回到了底璧，攻打这城。'),
('CNV', '约书亚记', 6, 10, 39, '约书亚占领了这城，抓住这城的王，又占领了属于这城的一切城镇；以色列人用刀击杀他们，把城中所有的人都毁灭了；约书亚不容一人逃脱，他怎样对待希伯仑，也照样对待底璧和底璧的王；也好像他对待立拿和立拿的王一样。'),
('CNV', '约书亚记', 6, 10, 40, '这样，约书亚击杀了全地的人，就是山地、南地、高原和山坡的人，以及那些地方所有的王，不容一人逃脱；约书亚照着耶和华以色列的神的吩咐，把有气息的都完全毁灭了。'),
('CNV', '约书亚记', 6, 10, 41, '约书亚从加低斯．巴尼亚击杀他们，直到迦萨，又从歌珊全地击杀他们，直到基遍。'),
('CNV', '约书亚记', 6, 10, 42, '约书亚在这一次战役中击败了这些王和占领了他们的地，是因为耶和华以色列的神为以色列作战。'),
('CNV', '约书亚记', 6, 10, 43, '于是约书亚和与他在一起的众以色列人回到吉甲营中。'),
('CNV', '约书亚记', 6, 11, 1, '夏琐王耶宾一听见这些事，就派人去见玛顿王约巴、伸仑王、押煞王，'),
('CNV', '约书亚记', 6, 11, 2, '以及住在北方山地、基尼烈南边的亚拉巴、高原和西边多珥高地的众王，'),
('CNV', '约书亚记', 6, 11, 3, '又去见在东方和西方的迦南人，住在山地的亚摩利人、赫人、比利洗人和耶布斯人，以及米斯巴地黑门山下的希未人。'),
('CNV', '约书亚记', 6, 11, 4, '这些王与他们所有的军队都一同出来，人数众多，好像海边的沙，还有很多马匹和车辆。'),
('CNV', '约书亚记', 6, 11, 5, '这些王都联合起来，来到米伦水边，在那里一起安营，要与以色列人作战。'),
('CNV', '约书亚记', 6, 11, 6, '耶和华对约书亚说：“你不要因他们惧怕，因为明天这个时候，我必使他们全数在以色列人面前被杀；你要砍断他们的马蹄筋，焚烧他们的车辆。”'),
('CNV', '约书亚记', 6, 11, 7, '于是约书亚和所有与他在一起能作战的人，在米伦水边突然迫近，攻打他们。'),
('CNV', '约书亚记', 6, 11, 8, '耶和华把他们交在以色列人手里，以色列人就击杀他们，追赶他们直到西顿大城、米斯利弗．玛音，以及在东边的米斯巴谷；以色列人击杀他们，没有留下一个。'),
('CNV', '约书亚记', 6, 11, 9, '约书亚照着耶和华吩咐他的对待他们；他砍断了他们的马蹄筋，用火烧了他们的车辆。'),
('CNV', '约书亚记', 6, 11, 10, '那时，约书亚转回来，占领了夏琐，用刀击杀了夏琐王，因为夏琐在这些国中素来是为首的。'),
('CNV', '约书亚记', 6, 11, 11, '以色列人用刀击杀了城中所有的人，把他们完全毁灭；有气息的一个也没有留下；约书亚又放火烧了夏琐。'),
('CNV', '约书亚记', 6, 11, 12, '约书亚夺取了那些王的一切城镇，又擒获那些城镇所有的王；他用刀击杀了他们，把一切完全毁灭，正如耶和华仆人摩西所吩咐的。'),
('CNV', '约书亚记', 6, 11, 13, '至于那些立在土丘上的城，除了夏琐以外，以色列人都没有焚烧；约书亚只烧了夏琐。'),
('CNV', '约书亚记', 6, 11, 14, '那些城所有的战利品和牲畜，以色列人都据为己有；只是把所有的人都用刀击杀了，直到把他们杀尽；有气息的，他们没有留下一个。'),
('CNV', '约书亚记', 6, 11, 15, '耶和华怎样吩咐他的仆人摩西，摩西就怎样吩咐约书亚，约书亚也照样行了；耶和华吩咐摩西的一切，约书亚没有一样不办妥的。'),
('CNV', '约书亚记', 6, 11, 16, '这样，约书亚夺取了那整个地区，就是山地、整个南地、歌珊全地、高原、亚拉巴、以色列山地和山地的高原；'),
('CNV', '约书亚记', 6, 11, 17, '从延伸至西珥的哈拉山，直到黑门山下黎巴嫩谷的巴力．迦得；约书亚擒获了那些地方所有的王，击打他们，把他们都杀死了。'),
('CNV', '约书亚记', 6, 11, 18, '约书亚和这些王作战了很多的日子。'),
('CNV', '约书亚记', 6, 11, 19, '除了住在基遍的希未人以外，没有一座城与以色列人议和的；所有其他的城都是以色列人作战夺取的。'),
('CNV', '约书亚记', 6, 11, 20, '因为这是出于耶和华的旨意，他使他们心里刚硬，要与以色列人交战，好把他们完全毁灭，使他们不蒙怜悯，却要被消灭，正如耶和华吩咐摩西的。'),
('CNV', '约书亚记', 6, 11, 21, '那时约书亚来了，把在山地、希伯仑、底璧、亚拿伯、整个犹大山地、整个以色列山地所有的亚衲族人都剪除了。约书亚把他们与他们的城镇都完全毁灭了。'),
('CNV', '约书亚记', 6, 11, 22, '在以色列人的境内，没有留下一个亚衲族人，只在迦萨、迦特和亚实突还有余下的。'),
('CNV', '约书亚记', 6, 11, 23, '这样，约书亚照着耶和华吩咐摩西的一切话，夺取了那全地；于是，约书亚按着以色列的支派把地分给他们作产业。全地也就止息了战争。'),
('CNV', '约书亚记', 6, 12, 1, '以色列人在约旦河东向日出之地击杀了那地的两个王，占领了他们的地，就是从亚嫩谷直到黑门山，和东边的亚拉巴全境。'),
('CNV', '约书亚记', 6, 12, 2, '这两个王，一个是住在希实本的亚摩利人的王西宏；他管辖的地区，是从亚嫩谷旁的亚罗珥起，包括山谷中部和基列的一半，直到雅博河，就是亚扪人的境界；'),
('CNV', '约书亚记', 6, 12, 3, '东边有亚拉巴，上至基尼烈海，下至亚拉巴海，就是盐海，东边是往伯．耶西末的路；南边直到毗斯迦的山麓。'),
('CNV', '约书亚记', 6, 12, 4, '另一个是巴珊王噩（按照《马索拉文本》，“巴珊王噩”作“巴珊王噩的境界”；现参照《七十士译本》翻译），他是利乏音人的余民，住在亚斯他录和以得来；'),
('CNV', '约书亚记', 6, 12, 5, '他管辖的地区，是黑门山、撒迦、巴珊全地，直到基述人和玛迦人的境界，还有基列的一半，直到希实本王西宏的境界。'),
('CNV', '约书亚记', 6, 12, 6, '耶和华的仆人摩西和以色列人把这两个王击杀了。耶和华的仆人摩西把地分给流本人、迦得人和玛拿西半个支派的人作产业。'),
('CNV', '约书亚记', 6, 12, 7, '以下是约书亚和以色列人在约旦河西，从黎巴嫩谷的巴力．迦得，直到延伸至西珥的哈拉山等地，所击杀的众王；约书亚按着分配办法把那地分给以色列各支派作产业；'),
('CNV', '约书亚记', 6, 12, 8, '就是赫人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人所住的山地、高原、亚拉巴、山坡、旷野和南地。'),
('CNV', '约书亚记', 6, 12, 9, '他们的王，一个是耶利哥王，一个是伯特利旁边的艾城王，'),
('CNV', '约书亚记', 6, 12, 10, '一个是耶路撒冷王，一个是希伯仑王，'),
('CNV', '约书亚记', 6, 12, 11, '一个是耶末王，一个是拉吉王，'),
('CNV', '约书亚记', 6, 12, 12, '一个是伊矶伦王，一个是基色王，'),
('CNV', '约书亚记', 6, 12, 13, '一个是底璧王，一个是基德王，'),
('CNV', '约书亚记', 6, 12, 14, '一个是何珥玛王，一个是亚拉得王，'),
('CNV', '约书亚记', 6, 12, 15, '一个是立拿王，一个是亚杜兰王，'),
('CNV', '约书亚记', 6, 12, 16, '一个是玛基大王，一个是伯特利王，'),
('CNV', '约书亚记', 6, 12, 17, '一个是他普亚王，一个是希弗王，'),
('CNV', '约书亚记', 6, 12, 18, '一个是亚弗王，一个是拉沙仑王，'),
('CNV', '约书亚记', 6, 12, 19, '一个是玛顿王，一个是夏琐王，'),
('CNV', '约书亚记', 6, 12, 20, '一个是伸仑．米仑王，一个是押煞王，'),
('CNV', '约书亚记', 6, 12, 21, '一个是他纳王，一个是米吉多王，'),
('CNV', '约书亚记', 6, 12, 22, '一个是基低斯王，一个是靠近迦密的约念王，'),
('CNV', '约书亚记', 6, 12, 23, '一个是多珥山地的多珥王，一个是吉甲的戈印王，'),
('CNV', '约书亚记', 6, 12, 24, '一个是得撒王，共计三十一个王。'),
('CNV', '约书亚记', 6, 13, 1, '约书亚老了，年纪不小；耶和华对他说：“你已经老了，年纪不小；还有很多的地有待征服。'),
('CNV', '约书亚记', 6, 13, 2, '还剩下来的地，就是非利士人的全境和基述人的全地，'),
('CNV', '约书亚记', 6, 13, 3, '从埃及东面的西曷河，向北直到以革伦的境界（这都算是迦南人的地方），由五个非利士人的首领管辖的迦萨人、亚实突人、亚实基伦人、迦特人、以革伦人的地方；并且有亚卫人，'),
('CNV', '约书亚记', 6, 13, 4, '他们是在南方，以及迦南人全境和属西顿人的米亚拉，直到亚弗和亚摩利人的境界；'),
('CNV', '约书亚记', 6, 13, 5, '还有迦巴勒人的地和东面的黎巴嫩全境，从黑门山下的巴力．迦得，直到哈马口；'),
('CNV', '约书亚记', 6, 13, 6, '从黎巴嫩直到米斯利弗．玛音，所有住在山地的居民，就是所有的西顿人，我必在以色列人面前把他们赶出去。你只要照着我吩咐你的，把这地抽签分给以色列人作产业。'),
('CNV', '约书亚记', 6, 13, 7, '现在你要把这地分给九个支派和玛拿西半个支派作产业。”'),
('CNV', '约书亚记', 6, 13, 8, '玛拿西另半个支派（按照《马索拉文本》，“玛拿西另半个支派”作“与它”，意思不明确﹔现参照《七十士译本》翻译），跟流本人和迦得人，已经得了摩西在约旦河东赐给他们的产业，是照着耶和华的仆人摩西赐给他们的，'),
('CNV', '约书亚记', 6, 13, 9, '就是从亚嫩谷边的亚罗珥和谷中间的城，以及米底巴的整片平原，直到底本；'),
('CNV', '约书亚记', 6, 13, 10, '还有在希实本作王的亚摩利人的王西宏所有的城镇，直到亚扪人的境界；'),
('CNV', '约书亚记', 6, 13, 11, '又有基列地、基述人和玛迦人的境界，以及整个黑门山、巴珊全地，直到撒迦；'),
('CNV', '约书亚记', 6, 13, 12, '另有巴珊王噩的全国，他在亚斯他录和以得来作王；他是利乏音人留下的唯一余民。这些地方的人，摩西都把他们击杀了，赶走了。'),
('CNV', '约书亚记', 6, 13, 13, '以色列人却没有赶走基述人和玛迦人；因此，基述人和玛迦人住在以色列人中间，直到今日。'),
('CNV', '约书亚记', 6, 13, 14, '只有利未支派，摩西没有把产业给他们；他们的产业就是献给耶和华以色列的神的火祭，正如耶和华对他们所说的。'),
('CNV', '约书亚记', 6, 13, 15, '摩西按着流本支派的家族，把产业给了他们。'),
('CNV', '约书亚记', 6, 13, 16, '他们的境界是从亚嫩谷边的亚罗珥起，包括谷中间的城、靠近米底巴的整片平原、'),
('CNV', '约书亚记', 6, 13, 17, '希实本和平原上属希实本所有的城、底本、巴末．巴力、伯．巴力．勉、'),
('CNV', '约书亚记', 6, 13, 18, '雅杂、基底莫、米法押、'),
('CNV', '约书亚记', 6, 13, 19, '基列亭、西比玛、谷中山地上的细列哈．沙辖、'),
('CNV', '约书亚记', 6, 13, 20, '伯．毗珥、毗斯迦山坡、伯．耶西末、'),
('CNV', '约书亚记', 6, 13, 21, '平原上所有的城和亚摩利人的王西宏的全国。这西宏曾经在希实本作王，摩西把他和米甸的首领以未、利金、苏珥、户珥和利巴都击杀了。这些都是西宏的王侯，住在那地。'),
('CNV', '约书亚记', 6, 13, 22, '在以色列人所杀的人中，比珥的儿子占卜者巴兰也被他们用刀所杀。'),
('CNV', '约书亚记', 6, 13, 23, '流本人领土的疆界是约旦河，这就是流本人按着家族得着的产业所包括的众城，和属于这些城的村庄。'),
('CNV', '约书亚记', 6, 13, 24, '摩西按着迦得支派的家族把产业分给迦得支派。'),
('CNV', '约书亚记', 6, 13, 25, '他们的境界包括雅谢和基列所有的城，以及亚扪人的一半土地，直到拉巴前面的亚罗珥；'),
('CNV', '约书亚记', 6, 13, 26, '从希实本直到拉抹．米斯巴和比多宁，又从玛哈念直到底璧的境界；'),
('CNV', '约书亚记', 6, 13, 27, '还有在谷中的伯．亚兰、伯．宁拉、疏割、撒分，就是希实本王西宏国中的余地，以约旦河作疆界，直到基尼烈海的底端，都在约旦河东。'),
('CNV', '约书亚记', 6, 13, 28, '这就是迦得人按着家族得着的产业所包括的城镇，和属于这些城的村庄。'),
('CNV', '约书亚记', 6, 13, 29, '摩西把产业分给玛拿西半个支派，是按着玛拿西半个支派的家族分给他们的。'),
('CNV', '约书亚记', 6, 13, 30, '他们的境界是从玛哈念起，包括巴珊全地、巴珊王噩的全国，并且在巴珊的睚珥的所有村落，共六十座城，'),
('CNV', '约书亚记', 6, 13, 31, '还有基列的一半和亚斯他录、以得来，就是在巴珊，噩的王国的两座城，都是按着家族分给玛拿西的儿子玛吉的孙子，就是分给玛吉的一半孙子。'),
('CNV', '约书亚记', 6, 13, 32, '以上这些地方是摩西在约旦河东，耶利哥对面的摩押平原所分配的产业。'),
('CNV', '约书亚记', 6, 13, 33, '可是利未支派，摩西却没有把产业分给他们，因为耶和华以色列的神就是他们的产业，正如耶和华对他们所说的。'),
('CNV', '约书亚记', 6, 14, 1, '以下这些地方是以色列人在迦南地分得的产业，就是以利亚撒祭司和嫩的儿子约书亚，以及以色列人各支派的族长分给他们的，'),
('CNV', '约书亚记', 6, 14, 2, '是照着耶和华藉着摩西所吩咐的，以抽签的方法把产业分给九个半支派。'),
('CNV', '约书亚记', 6, 14, 3, '因为摩西在约旦河东已经把产业分给了那两个半支派；却没有把产业分给他们中间的利未人。'),
('CNV', '约书亚记', 6, 14, 4, '因为约瑟的子孙成了两个支派，就是玛拿西和以法莲，因此以色列人没有把地业分给在那地的利未人，只给他们一些城市居住，还有城市的郊野，可以牧放他们的牲畜，安置他们的财产。'),
('CNV', '约书亚记', 6, 14, 5, '耶和华怎样吩咐摩西，以色列人就照样行，把地分配了。'),
('CNV', '约书亚记', 6, 14, 6, '犹大人来到吉甲约书亚那里，基尼洗人耶孚尼的儿子迦勒对约书亚说：“耶和华在加低斯．巴尼亚对神人摩西所说关于你和我的话，你是知道的。'),
('CNV', '约书亚记', 6, 14, 7, '耶和华的仆人摩西从加低斯．巴尼亚派我去窥探这地的时候，我正四十岁；我照着我心里所想的向他报告。'),
('CNV', '约书亚记', 6, 14, 8, '可是，与我一同上去的众兄弟却使人民的心惊惧，我却完全顺从耶和华我的神。'),
('CNV', '约书亚记', 6, 14, 9, '那天摩西起誓说：‘你的脚踏过的地都必归你和你的子孙作产业，直到永远，因为你完全顺从耶和华我的神。’'),
('CNV', '约书亚记', 6, 14, 10, '现在你看，自从耶和华对摩西说了这话以后，耶和华照着所应许的，使我活了这四十五年，就是以色列人在旷野行走的时期；现在你看，我今日已经是八十五岁了。'),
('CNV', '约书亚记', 6, 14, 11, '今日我还是强壮，像摩西派我去的那天一样；无论是作战，或是出入，那时我的力量怎样，现在我的力量还是怎样。'),
('CNV', '约书亚记', 6, 14, 12, '现在求你把耶和华那日所应许的这山地赐给我；因为那天你也曾听见那里有亚衲人，又有宽大坚固的城；也许耶和华与我同在，我就可以把他们赶出去，正如耶和华所应许的。”'),
('CNV', '约书亚记', 6, 14, 13, '于是约书亚给迦勒祝福，把希伯仑赐给了耶孚尼的儿子迦勒作产业。'),
('CNV', '约书亚记', 6, 14, 14, '因此，希伯仑成了基尼洗人耶孚尼的儿子迦勒的产业，直到今日；因为他完全顺从耶和华以色列的神。'),
('CNV', '约书亚记', 6, 14, 15, '希伯仑从前名叫基列．亚巴；亚巴是亚衲人中最伟大的人。全地也就止息了战争。'),
('CNV', '约书亚记', 6, 15, 1, '犹大支派按着家族抽签所得的地业，是极南的部分，达到以东的边境，去到南边寻的旷野。'),
('CNV', '约书亚记', 6, 15, 2, '他们南方的疆界是从盐海的极南部分起，就是从南边的海湾起；'),
('CNV', '约书亚记', 6, 15, 3, '伸到亚克拉滨山坡的南边，经过寻，上到加低斯．巴尼亚的南边，又经过希斯仑，再上到亚达珥，绕过甲加，'),
('CNV', '约书亚记', 6, 15, 4, '经过押们，伸展到埃及河，疆界直通到海；这就是他们（按照《马索拉文本》，“他们”作“你们”﹔现参照《七十士译本》翻译）南方的疆界。'),
('CNV', '约书亚记', 6, 15, 5, '东方的疆界是从盐海直到约旦河口。北方的疆界是从约旦河口的海湾起，'),
('CNV', '约书亚记', 6, 15, 6, '上到伯．曷拉，经过伯．亚拉巴的北边，再上到流本的儿子波罕的磐石那里；'),
('CNV', '约书亚记', 6, 15, 7, '又从亚割谷上到底璧，再北转到河的南边亚都冥山坡对面的吉甲去；又经过隐．示麦水泉，直通到隐．罗结；'),
('CNV', '约书亚记', 6, 15, 8, '再上到欣嫩子谷，到达耶布斯南面的山坡，耶布斯就是耶路撒冷；又上到欣嫩子谷西边的山顶，就是在利乏音的北端；'),
('CNV', '约书亚记', 6, 15, 9, '又从山顶转到尼弗多亚的水泉，伸展到以弗仑山的众城；又转到巴拉，巴拉就是基列．耶琳；'),
('CNV', '约书亚记', 6, 15, 10, '又从巴拉向西绕到西珥山，经过耶琳山坡的北边，耶琳就是基撒仑；又下到伯．示麦，经过亭纳；'),
('CNV', '约书亚记', 6, 15, 11, '伸展到以革伦北面的山坡，转到施基仑，经过巴拉山，伸展到雅比聂，直通到海为止。'),
('CNV', '约书亚记', 6, 15, 12, '西方的疆界就是大海和海岸。这是犹大人按着家族所得四围的境界。'),
('CNV', '约书亚记', 6, 15, 13, '约书亚照着耶和华所吩咐的，把犹大人的一份地业，就是基列．亚巴，分给了耶孚尼的儿子迦勒；亚巴是亚衲人的祖先。基列．亚巴就是希伯仑。'),
('CNV', '约书亚记', 6, 15, 14, '迦勒把亚衲人的三个子孙，就是示筛、亚希幔、挞买，从那里赶出去；他们是亚衲人的后代。'),
('CNV', '约书亚记', 6, 15, 15, '他又从那里上去攻击底璧的居民；底璧从前名叫基列．西弗。'),
('CNV', '约书亚记', 6, 15, 16, '迦勒说：“谁能攻打基列．西弗，把基列．西弗夺取，我就把我的女儿押撒给他作妻子。”'),
('CNV', '约书亚记', 6, 15, 17, '迦勒的兄弟基纳斯的儿子俄陀聂夺取了那城，迦勒就把女儿押撒给他作妻子。'),
('CNV', '约书亚记', 6, 15, 18, '押撒出嫁的时候，怂恿丈夫向她父亲求一块田地；押撒一下驴，迦勒问她：“你要什么？”'),
('CNV', '约书亚记', 6, 15, 19, '她回答：“求你给我祝福；你既然把南地给了我，求你也把水泉给我。”她父亲就把上泉和下泉都给了她。'),
('CNV', '约书亚记', 6, 15, 20, '以下是犹大支派按着家族所得的产业。'),
('CNV', '约书亚记', 6, 15, 21, '犹大支派极南边的众城，接近以东边界的，有：甲薛、以得、雅姑珥、'),
('CNV', '约书亚记', 6, 15, 22, '基拿、底摩拿、亚大达、'),
('CNV', '约书亚记', 6, 15, 23, '基低斯、夏琐、以提楠、'),
('CNV', '约书亚记', 6, 15, 24, '西弗、提链、比亚绿、'),
('CNV', '约书亚记', 6, 15, 25, '夏琐．哈大他、加略．希斯仑（加略．希斯仑就是夏琐）、'),
('CNV', '约书亚记', 6, 15, 26, '亚曼、示玛、摩拉大、'),
('CNV', '约书亚记', 6, 15, 27, '哈萨．迦大、黑实门、伯．帕列、'),
('CNV', '约书亚记', 6, 15, 28, '哈萨．书亚、别是巴、比斯约他、'),
('CNV', '约书亚记', 6, 15, 29, '巴拉、以因、以森、'),
('CNV', '约书亚记', 6, 15, 30, '伊勒多腊、基失、何珥玛、'),
('CNV', '约书亚记', 6, 15, 31, '洗革拉、麦连拿、三撒拿、'),
('CNV', '约书亚记', 6, 15, 32, '利巴勿、实忻、亚因、临门，共二十九座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 15, 33, '在高原有以实陶、琐拉、亚实拿、'),
('CNV', '约书亚记', 6, 15, 34, '撒挪亚、隐．干宁、他普亚、以楠、'),
('CNV', '约书亚记', 6, 15, 35, '耶末、亚杜兰、梭哥、亚西加、'),
('CNV', '约书亚记', 6, 15, 36, '沙拉音、亚底他音、基底拉、基底罗他音，共十四座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 15, 37, '又有洗楠、哈大沙、麦大．迦得、'),
('CNV', '约书亚记', 6, 15, 38, '底连、米斯巴、约帖、'),
('CNV', '约书亚记', 6, 15, 39, '拉吉、波斯加、伊矶伦、'),
('CNV', '约书亚记', 6, 15, 40, '迦本、拉幔、基提利、'),
('CNV', '约书亚记', 6, 15, 41, '基低罗、伯．大衮、拿玛、玛基大，共十六座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 15, 42, '又有立拿、以帖、亚珊、'),
('CNV', '约书亚记', 6, 15, 43, '益弗他、亚实拿、尼悉、'),
('CNV', '约书亚记', 6, 15, 44, '基伊拉、亚革悉、玛利沙，共九座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 15, 45, '又有以革伦，和属于以革伦的市镇村庄；'),
('CNV', '约书亚记', 6, 15, 46, '从以革伦直到海，所有靠近亚实突的城和属于这些城的村庄。'),
('CNV', '约书亚记', 6, 15, 47, '亚实突和属于亚实突的市镇村庄；迦萨和属于迦萨的市镇村庄；直到埃及小河和大海沿岸的地方。'),
('CNV', '约书亚记', 6, 15, 48, '在山地有沙密、雅提珥、梭哥、'),
('CNV', '约书亚记', 6, 15, 49, '大拿、基列．萨拿（基列．萨拿就是底璧）、'),
('CNV', '约书亚记', 6, 15, 50, '亚拿伯、以实提莫、亚念、'),
('CNV', '约书亚记', 6, 15, 51, '歌珊、何伦、基罗，共十一座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 15, 52, '又有亚拉、度玛、以珊、'),
('CNV', '约书亚记', 6, 15, 53, '雅农、伯．他普亚、亚非加、'),
('CNV', '约书亚记', 6, 15, 54, '宏他、基列．亚巴（基列．亚巴就是希伯仑）、洗珥，共九座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 15, 55, '又有玛云、迦密、西弗、淤他、'),
('CNV', '约书亚记', 6, 15, 56, '耶斯列、约甸、撒挪亚、'),
('CNV', '约书亚记', 6, 15, 57, '该隐、基比亚、亭纳，共十座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 15, 58, '又有哈忽、伯．夙、基突、'),
('CNV', '约书亚记', 6, 15, 59, '玛腊、伯．亚诺、伊勒提君，共六座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 15, 60, '又有基列．巴力（基列．巴力就是基列．耶琳）、拉巴，共两座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 15, 61, '在旷野有伯．亚拉巴、密丁、西迦迦、'),
('CNV', '约书亚记', 6, 15, 62, '匿珊、盐城、隐．基底，共六座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 15, 63, '至于住在耶路撒冷的耶布斯人，犹大人不能把他们赶走；所以耶布斯人在耶路撒冷与犹大人同住，直到今日。'),
('CNV', '约书亚记', 6, 16, 1, '约瑟的子孙抽签所得的地业，是从靠近耶利哥的约旦河起，到耶利哥东边的水泉，经过从耶利哥上去的旷野，进到在山地的伯特利；'),
('CNV', '约书亚记', 6, 16, 2, '又从伯特利到路斯，经过亚基人的境界亚他绿，'),
('CNV', '约书亚记', 6, 16, 3, '又向西下到押利提人的境界，去到下伯．和仑和基色的境界，直通到海。'),
('CNV', '约书亚记', 6, 16, 4, '约瑟的儿子玛拿西和以法莲，也得了他们的产业。'),
('CNV', '约书亚记', 6, 16, 5, '以下是以法莲人按着家族所得的境界：他们的产业在东方的疆界，是亚他绿．亚达，直到上伯．和仑。'),
('CNV', '约书亚记', 6, 16, 6, '向西伸展到北面的密米他，又向东绕到他纳．示罗，经过雅挪哈的东边；'),
('CNV', '约书亚记', 6, 16, 7, '从雅挪哈下到亚他绿，又到拿拉，和耶利哥接壤，伸展到约旦河；'),
('CNV', '约书亚记', 6, 16, 8, '又从他普亚向西行，到加拿河，直通到海；这就是以法莲支派按着家族所得的产业。'),
('CNV', '约书亚记', 6, 16, 9, '此外在玛拿西人的产业中，还有些城镇分给以法莲人的，这些城镇都包括属于它们的村庄在内。'),
('CNV', '约书亚记', 6, 16, 10, '可是他们没有把住在基色的迦南人赶走，于是迦南人住在以法莲中间，直到今日，成了作苦工的奴仆。'),
('CNV', '约书亚记', 6, 17, 1, '玛拿西是约瑟的长子，他的支派抽签所得的地业记在下面；至于玛拿西的长子，基列的父亲玛吉，因为是个战士，所以得到基列和巴珊。'),
('CNV', '约书亚记', 6, 17, 2, '玛拿西其余的子孙按着家族抽签分地，包括亚比以谢的子孙、希勒的子孙、亚斯列的子孙、示剑的子孙、希弗的子孙、示米大的子孙；这些都是约瑟的儿子玛拿西子孙中男丁的各家族。'),
('CNV', '约书亚记', 6, 17, 3, '玛拿西的玄孙、玛吉的曾孙、基列的孙子、希弗的儿子西罗非哈没有儿子，只有女儿；他女儿们的名字是玛拉、挪阿、曷拉、密迦、得撒。'),
('CNV', '约书亚记', 6, 17, 4, '她们来到以利亚撒祭司和嫩的儿子约书亚，以及众首领的面前，说：“耶和华曾经吩咐摩西，在我们的兄弟中把产业分给我们。”于是约书亚照着耶和华所吩咐的，在她们的叔伯中间，把产业分给她们。'),
('CNV', '约书亚记', 6, 17, 5, '这样，除了约旦河东的基列和巴珊地之外，还有十份地业归属玛拿西。'),
('CNV', '约书亚记', 6, 17, 6, '因为玛拿西的孙女，在玛拿西的孩子中，也得了产业；基列地是属于玛拿西其余的子孙的。'),
('CNV', '约书亚记', 6, 17, 7, '玛拿西的疆界，是从亚设起，到示剑东面的密米他；又向南走，到隐．他普亚的居民那里。'),
('CNV', '约书亚记', 6, 17, 8, '（他普亚地是属于玛拿西的，但是在玛拿西疆界上的他普亚城，却是属于以法莲的子孙的。）'),
('CNV', '约书亚记', 6, 17, 9, '玛拿西的疆界又下到加拿河，在加拿河的南边，玛拿西的众城镇中，有这些城镇是属于以法莲的。玛拿西的疆界，从河的北面起，直通到海。'),
('CNV', '约书亚记', 6, 17, 10, '南面是属于以法莲的，北面是属于玛拿西的；玛拿西在西边的疆界就是海，北面与亚设相接，东面和以萨迦相连；'),
('CNV', '约书亚记', 6, 17, 11, '在以萨迦和亚设的境内，伯．善和属于伯．善的市镇，以伯莲和属于以伯莲的市镇，多珥的居民和属于多珥的市镇，都属于玛拿西；还有三处山区，就是：隐．多珥的居民和属于隐．多珥的市镇，他衲的居民和属于他衲的市镇，米吉多的居民和属于米吉多的市镇。'),
('CNV', '约书亚记', 6, 17, 12, '可是玛拿西的子孙却不能把这些城的居民赶走，迦南人决意住在那地。'),
('CNV', '约书亚记', 6, 17, 13, '以色列人强盛以后，就迫使迦南人作苦工，却没有把他们完全赶出去。'),
('CNV', '约书亚记', 6, 17, 14, '约瑟的子孙对约书亚说：“耶和华这样赐福我们，我们族大人多，你为什么只给我们抽一份签，分一份地作产业呢？”'),
('CNV', '约书亚记', 6, 17, 15, '约书亚对他们说：“如果你们族大人多，又嫌以法莲山地过于窄小，就可以上森林区去，在比利洗人和利乏音人之地那里自己砍伐树木。”'),
('CNV', '约书亚记', 6, 17, 16, '约瑟的子孙回答：“那山地容不下我们，并且住在谷地的所有迦南人，就是住在伯．善和属于伯．善的市镇的人，以及住在耶斯列谷的人，都有铁车。”'),
('CNV', '约书亚记', 6, 17, 17, '约书亚对约瑟家，就是对以法莲人和玛拿西人说：“你们族大人多，势力强大，不可以只抽一份地业；'),
('CNV', '约书亚记', 6, 17, 18, '山地也要归给你们，那里虽然是森林，你们可以砍伐，开辟的土地都归给你们，直到它最远的边界；迦南人虽然拥有铁车，势力强大，你们也能把他们赶出去。”'),
('CNV', '约书亚记', 6, 18, 1, '以色列全体会众聚集在示罗，把会幕竖立在那里，因为那地在他们面前被征服了。'),
('CNV', '约书亚记', 6, 18, 2, '以色列人其余的七个支派还没有得着产业。'),
('CNV', '约书亚记', 6, 18, 3, '约书亚对以色列人说：“耶和华你们列祖的神赐给你们的地，你们迟迟不去占领，要到几时呢？'),
('CNV', '约书亚记', 6, 18, 4, '你们每支派要选出三个人，我要派他们去；他们要起程走遍那地，把各支派的产业描绘下来，然后回到我这里。'),
('CNV', '约书亚记', 6, 18, 5, '他们要把地业分作七份，犹大留在南方他们的境界内；约瑟家留在北方他们的境界内。'),
('CNV', '约书亚记', 6, 18, 6, '你们要把地划分七份，然后把图样拿给我；我要在这里，在耶和华我们的神面前，为你们抽签。'),
('CNV', '约书亚记', 6, 18, 7, '利未人在你们中间没有业分，因为耶和华祭司的职分就是他们的产业。迦得支派、流本支派和玛拿西半个支派，已经在约旦河东得了产业，就是耶和华的仆人摩西分给他们的。”'),
('CNV', '约书亚记', 6, 18, 8, '那些人起程前去的时候，约书亚吩咐那些前去绘画那地的人说：“你们要去，走遍那地，绘画地形，然后回到我这里来，我要在示罗这里，在耶和华面前，为你们抽签。”'),
('CNV', '约书亚记', 6, 18, 9, '那些人就去了，走遍那地，并绘画下来，把众城分作七份记在册子上，然后回到示罗营中约书亚那里。'),
('CNV', '约书亚记', 6, 18, 10, '约书亚就在示罗，在耶和华面前为他们抽签；约书亚在那里按着他们的支派把地分给以色列人。'),
('CNV', '约书亚记', 6, 18, 11, '便雅悯支派按着家族抽了签；他们抽签所得的境界，是在犹大子孙和约瑟子孙中间。'),
('CNV', '约书亚记', 6, 18, 12, '他们的疆界，北边是从约旦河起，向上到耶利哥的北边，又向西上到山地，直到伯．亚文的旷野。'),
('CNV', '约书亚记', 6, 18, 13, '又从那里向南经过路斯，路斯就是伯特利，再下到亚他绿．亚达，靠近下伯．和仑南边的山地；'),
('CNV', '约书亚记', 6, 18, 14, '又从那里伸延，绕到西边再向南，从伯．和仑南边对面的山起，直到犹大人的城基列．巴力，基列．巴力就是基列．耶琳；这是西方的疆界。'),
('CNV', '约书亚记', 6, 18, 15, '南方的疆界是从基列．耶琳的边缘起，向西伸展，去到尼弗多亚的水泉；'),
('CNV', '约书亚记', 6, 18, 16, '又下到欣嫩子谷前面的山边，就是利乏音谷北面的山；再下到欣嫩谷，去到耶布斯人的南边，又下去隐．罗结；'),
('CNV', '约书亚记', 6, 18, 17, '再转向北，伸展至隐．示麦，去到亚都冥斜坡对面的基利录，又下到流本的儿子波罕的磐石那里；'),
('CNV', '约书亚记', 6, 18, 18, '又经过亚拉巴对面山坡的北边，直下到亚拉巴；'),
('CNV', '约书亚记', 6, 18, 19, '又经过伯．曷拉的北边，直通到盐海的北湾，约旦河的南端；这是南方的疆界。'),
('CNV', '约书亚记', 6, 18, 20, '东方的疆界是约旦河。这就是便雅悯各家族所得的产业四围的疆界。'),
('CNV', '约书亚记', 6, 18, 21, '便雅悯支派按着家族所得的城就是：耶利哥、伯．曷拉、伊麦．基悉、'),
('CNV', '约书亚记', 6, 18, 22, '伯．亚拉巴、洗玛莲、伯特利、'),
('CNV', '约书亚记', 6, 18, 23, '亚文、巴拉、俄弗拉、'),
('CNV', '约书亚记', 6, 18, 24, '基法．阿摩尼、俄弗尼、迦巴，共十二座城，还有属于这些城的村庄；'),
('CNV', '约书亚记', 6, 18, 25, '又有基遍、拉玛、比录、'),
('CNV', '约书亚记', 6, 18, 26, '米斯巴、基非拉、摩撒、'),
('CNV', '约书亚记', 6, 18, 27, '利坚、伊利毗勒、他拉拉、'),
('CNV', '约书亚记', 6, 18, 28, '洗拉、以利弗、耶布斯（耶布斯就是耶路撒冷）、基比亚、基列，共十四座城，还有属于这些城的村庄。这就是便雅悯人按着家族所得的产业。'),
('CNV', '约书亚记', 6, 19, 1, '为西缅，就是为西缅支派，按着家族抽出第二签；他们的产业是在犹大人的产业中间。'),
('CNV', '约书亚记', 6, 19, 2, '他们所得的产业有别是巴、示巴、摩拉大、'),
('CNV', '约书亚记', 6, 19, 3, '哈萨．书亚、巴拉、以森、'),
('CNV', '约书亚记', 6, 19, 4, '伊利多拉、比土力、何珥玛、'),
('CNV', '约书亚记', 6, 19, 5, '洗革拉、伯．玛加博、哈萨．苏撒、'),
('CNV', '约书亚记', 6, 19, 6, '伯．利巴勿、沙鲁险，共十三座城，还有属于这些城的村庄；'),
('CNV', '约书亚记', 6, 19, 7, '又有亚因、利门、以帖、亚珊，共四座城，还有属于这些城的村庄；'),
('CNV', '约书亚记', 6, 19, 8, '以及这些城周围所有的村庄，直到巴拉．比珥，就是南地的拉玛。这就是西缅支派按着家族所得的产业。'),
('CNV', '约书亚记', 6, 19, 9, '西缅人的产业是从犹大人的地业中得来的；因为犹大人的分过大，所以西缅人在犹大人的产业中得了他们的产业。'),
('CNV', '约书亚记', 6, 19, 10, '为西布伦人，按着家族抽出第三签；他们产业的境界去到撒立；'),
('CNV', '约书亚记', 6, 19, 11, '他们的疆界再向西上到玛拉拉，直达大巴设，再去到约念前面的河；'),
('CNV', '约书亚记', 6, 19, 12, '又从撒立向东转到日出的方向，去到吉斯绿．他泊的境界，又伸展到大比拉，上到雅非亚；'),
('CNV', '约书亚记', 6, 19, 13, '又从那里往东面日出的方向，经过迦特．希弗，到以特．加汛、临门，再伸展到尼亚；'),
('CNV', '约书亚记', 6, 19, 14, '又绕过尼亚的北面，到哈拿顿，直通到伊弗他．伊勒谷；'),
('CNV', '约书亚记', 6, 19, 15, '还有加他、拿哈拉、伸仑、以大拉、伯利恒，共有十二座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 19, 16, '这些城和属于这些城的村庄，就是西布伦人按着家族所得的产业。'),
('CNV', '约书亚记', 6, 19, 17, '为以萨迦，就是为以萨迦人，按着家族抽出第四签。'),
('CNV', '约书亚记', 6, 19, 18, '他们的境界包括耶斯列、基苏律、书念、'),
('CNV', '约书亚记', 6, 19, 19, '哈弗连、示按、亚拿哈拉、'),
('CNV', '约书亚记', 6, 19, 20, '拉璧、基善、亚别、'),
('CNV', '约书亚记', 6, 19, 21, '利蔑、隐．干宁、隐．哈大、伯．帕薛，'),
('CNV', '约书亚记', 6, 19, 22, '又达到他泊、沙哈洗玛、伯．示麦，直通到约旦河，共十六座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 19, 23, '这些城和属于这些城的村庄，就是以萨迦支派按着家族所得的产业。'),
('CNV', '约书亚记', 6, 19, 24, '为亚设支派，按着家族抽出第五签。'),
('CNV', '约书亚记', 6, 19, 25, '他们的境界包括黑甲、哈利、比田、押煞、'),
('CNV', '约书亚记', 6, 19, 26, '亚拉米勒、亚末、米沙勒，向西直达迦密和希曷．立纳；'),
('CNV', '约书亚记', 6, 19, 27, '又转往日出的方向，到伯．大衮，延伸到细步纶，向北去到伊弗他．伊勒谷、伯．以墨和尼业，又伸展到迦布勒的左边，'),
('CNV', '约书亚记', 6, 19, 28, '到义伯仑、利合、哈们、加拿，直到西顿大城；'),
('CNV', '约书亚记', 6, 19, 29, '又转到拉玛，直到设防的城推罗；再转到何萨，直通到海岸靠近亚革悉的地区；'),
('CNV', '约书亚记', 6, 19, 30, '又有乌玛、亚弗、利合，共二十二座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 19, 31, '这些城和属于这些城的村庄，就是亚设支派按着家族所得的产业。'),
('CNV', '约书亚记', 6, 19, 32, '为拿弗他利人抽出第六签，就是拿弗他利人按着家族所得的产业。'),
('CNV', '约书亚记', 6, 19, 33, '他们的疆界，是从希利弗，从撒拿音的橡树林，从亚大米．尼吉和雅比聂起，去到拉共，直通到约旦河；'),
('CNV', '约书亚记', 6, 19, 34, '又向西转到亚斯纳．他泊，从那里伸展到户割，南边达到西布伦，西边达到亚设，东边达到约旦河那里的犹大。'),
('CNV', '约书亚记', 6, 19, 35, '设防的城有西丁、侧耳、哈末、拉甲、基尼烈、'),
('CNV', '约书亚记', 6, 19, 36, '亚大玛、拉玛、夏琐、'),
('CNV', '约书亚记', 6, 19, 37, '基低斯、以得来、隐．夏琐、'),
('CNV', '约书亚记', 6, 19, 38, '以利稳、密大．伊勒、和琏、伯．亚纳、伯．示麦，共十九座城，还有属于这些城的村庄。'),
('CNV', '约书亚记', 6, 19, 39, '这些城和属于这些城的村庄，就是拿弗他利支派按着家族所得的产业。'),
('CNV', '约书亚记', 6, 19, 40, '为但支派，按着家族抽出第七签。'),
('CNV', '约书亚记', 6, 19, 41, '他们产业的境界包括：琐拉、以实陶、伊珥．示麦、'),
('CNV', '约书亚记', 6, 19, 42, '沙拉宾、亚雅仑、伊提拉、'),
('CNV', '约书亚记', 6, 19, 43, '以伦、亭拿他、以革伦、'),
('CNV', '约书亚记', 6, 19, 44, '伊利提基、基比顿、巴拉、'),
('CNV', '约书亚记', 6, 19, 45, '伊胡得、比尼．比拉、迦特．临门、'),
('CNV', '约书亚记', 6, 19, 46, '美．耶昆、拉昆和约帕对面的地区。'),
('CNV', '约书亚记', 6, 19, 47, '但人未能控制他们的境界，因此他们就上去攻打利善，夺取那城，用刀击杀了城中的人；他们占领利善，就住在城中，以他们祖先但的名字，把利善改名为但。'),
('CNV', '约书亚记', 6, 19, 48, '这些城和属于这些城的村庄，就是但支派按着家族所得的产业。'),
('CNV', '约书亚记', 6, 19, 49, '以色列人按着疆界把地分完了之后，就在他们中间把产业分给嫩的儿子约书亚。'),
('CNV', '约书亚记', 6, 19, 50, '他们照着耶和华所吩咐的，把约书亚所要的城，就是以法莲山地的亭拿．西拉，给了他；约书亚就修建那城，住在城中。'),
('CNV', '约书亚记', 6, 19, 51, '以上就是以利亚撒祭司和嫩的儿子约书亚，以及以色列人各支派的族长，在示罗会幕的门口，在耶和华面前，藉着抽签所分的产业。这样，他们就完成了分地的事。'),
('CNV', '约书亚记', 6, 20, 1, '耶和华对约书亚说：'),
('CNV', '约书亚记', 6, 20, 2, '“你要告诉以色列人：‘你们要照着我藉着摩西命令你们的，为自己设立避难城，'),
('CNV', '约书亚记', 6, 20, 3, '好使那出于错误、并非蓄意杀人的，可以逃到那里去；这些城要成为你们逃避报血仇的人的避难所。'),
('CNV', '约书亚记', 6, 20, 4, '那杀人的要逃到这些城中的一座，站在城门口，把自己的事情向城中的众长老述说，长老就要把他接入城中，到他们那里，并要给他地方，使他可以住在他们中间。'),
('CNV', '约书亚记', 6, 20, 5, '如果报血仇的人追赶他，长老不可把他交在报血仇的人手里，因为他并非蓄意杀人，他以前与他并没有仇恨。'),
('CNV', '约书亚记', 6, 20, 6, '那杀人的要住在那城里，直到他站在会众面前受审；等到当时的大祭司死了，才可以回到本城本家，回到他逃出来的城那里。’”'),
('CNV', '约书亚记', 6, 20, 7, '于是以色列人在拿弗他利山地，把加利利的基低斯分别出来；在以法莲山地，把示剑分别出来；在犹大山地，把基列．亚巴分别出来，基列．亚巴就是希伯仑；'),
('CNV', '约书亚记', 6, 20, 8, '又在约旦河东，耶利哥的东面，从流本支派中，指定在旷野平原上的比悉；从迦得支派中，指定在基列的拉末；从玛拿西支派中，指定在巴珊的哥兰。'),
('CNV', '约书亚记', 6, 20, 9, '这些都是为所有的以色列人，和在他们中间寄居的外族人所指定的城，让误杀人的可以逃到那里，不致死在报血仇的人手里，直到他站在会众面前受审为止。'),
('CNV', '约书亚记', 6, 21, 1, '那时，利未人的众族长来到以利亚撒祭司和嫩的儿子约书亚，以及以色列众支派的族长那里，'),
('CNV', '约书亚记', 6, 21, 2, '在迦南地的示罗对他们说：“耶和华曾经藉着摩西吩咐要给我们城市居住，和城的郊野可以牧放我们的牲畜。”'),
('CNV', '约书亚记', 6, 21, 3, '于是以色列人照着耶和华所吩咐的，从自己的产业中，把以下这些城市和城的郊野，给了利未人。'),
('CNV', '约书亚记', 6, 21, 4, '首先为哥辖家族抽出签来：利未支派亚伦祭司的子孙，从犹大支派、西缅支派和便雅悯支派，抽签得了十三座城。'),
('CNV', '约书亚记', 6, 21, 5, '哥辖其余的子孙，从以法莲支派的家族、但支派和玛拿西半个支派，抽签得了十座城。'),
('CNV', '约书亚记', 6, 21, 6, '革顺的子孙，从以萨迦支派的家族、亚设支派、拿弗他利支派和在巴珊的玛拿西半个支派，抽签得了十三座城。'),
('CNV', '约书亚记', 6, 21, 7, '米拉利的子孙，按着家族，从流本支派、迦得支派和西布伦支派，得了十二座城。'),
('CNV', '约书亚记', 6, 21, 8, '以色列人照着耶和华吩咐摩西的，藉着抽签，把这些城市和城的郊野分给利未人。'),
('CNV', '约书亚记', 6, 21, 9, '他们从犹大支派和西缅支派中，把以下这些有提名的城分了'),
('CNV', '约书亚记', 6, 21, 10, '给利未支派、哥辖家族中亚伦的子孙，因为第一签是他们的。'),
('CNV', '约书亚记', 6, 21, 11, '以色列人把犹大山地的基列．亚巴，和它四围的郊野，给了他们；亚巴是亚衲族的祖宗，基列．亚巴就是希伯仑。'),
('CNV', '约书亚记', 6, 21, 12, '属于那城的田地和村庄，他们却给了耶孚尼的儿子迦勒作产业。'),
('CNV', '约书亚记', 6, 21, 13, '以色列人把误杀人者的避难城希伯仑，和希伯仑的郊野，又把立拿和立拿的郊野给了亚伦祭司的子孙，'),
('CNV', '约书亚记', 6, 21, 14, '还有雅提珥和雅提珥的郊野，以实提莫和以实提莫的郊野，'),
('CNV', '约书亚记', 6, 21, 15, '何仑和何仑的郊野，底璧和底璧的郊野，'),
('CNV', '约书亚记', 6, 21, 16, '亚因和亚因的郊野，淤他和淤他的郊野，伯．示麦和伯．示麦的郊野，共九座城，都是从这两个支派分出来的。'),
('CNV', '约书亚记', 6, 21, 17, '又从便雅悯支派中，分给他们基遍和基遍的郊野，迦巴和迦巴的郊野，'),
('CNV', '约书亚记', 6, 21, 18, '亚拿突和亚拿突的郊野，亚勒们和亚勒们的郊野，共四座城。'),
('CNV', '约书亚记', 6, 21, 19, '亚伦子孙众祭司所有的城，共十三座，还有这些城的郊野。'),
('CNV', '约书亚记', 6, 21, 20, '利未支派哥辖子孙的家族，就是哥辖其余的子孙，抽签所得的城是从以法莲支派中分出来的。'),
('CNV', '约书亚记', 6, 21, 21, '以色列人把误杀人者的避难城，就是在以法莲山地的示剑和示剑的郊野，给了他们；又把基色和基色的郊野，给了他们；'),
('CNV', '约书亚记', 6, 21, 22, '又有基伯先和基伯先的郊野，伯．和仑和伯．和仑的郊野，共四座城。'),
('CNV', '约书亚记', 6, 21, 23, '又从但支派中，给了他们伊利提基和伊利提基的郊野，基比顿和基比顿的郊野，'),
('CNV', '约书亚记', 6, 21, 24, '亚雅仑和亚雅仑的郊野，迦特．临门和迦特．临门的郊野，共四座城。'),
('CNV', '约书亚记', 6, 21, 25, '又从玛拿西半个支派中，给了他们他纳和他纳的郊野，迦特．临门和迦特．临门的郊野，共两座城。'),
('CNV', '约书亚记', 6, 21, 26, '哥辖子孙其余的家族所有的城共十座，还有这些城的郊野。'),
('CNV', '约书亚记', 6, 21, 27, '以色列人又从玛拿西半个支派中，把误杀人者的避难城，就是在巴珊的哥兰，和哥兰的郊野，给了利未人的家族中革顺的子孙；又给了他们比．施提拉和比．施提拉的郊野，共两座城。'),
('CNV', '约书亚记', 6, 21, 28, '又从以萨迦支派中，给了他们基善和基善的郊野，大比拉和大比拉的郊野，'),
('CNV', '约书亚记', 6, 21, 29, '耶末和耶末的郊野，隐．干宁和隐．干宁的郊野，共四座城。'),
('CNV', '约书亚记', 6, 21, 30, '又从亚设支派中，给了他们米沙勒和米沙勒的郊野，押顿和押顿的郊野，'),
('CNV', '约书亚记', 6, 21, 31, '黑甲和黑甲的郊野，利合和利合的郊野，共四座城。'),
('CNV', '约书亚记', 6, 21, 32, '以色列人又从拿弗他利支派中，把误杀人者的避难城，就是在加利利的基低斯和基低斯的郊野，给了他们；又给他们哈末．多珥和哈末．多珥的郊野，加珥但和加珥但的郊野，共三座城。'),
('CNV', '约书亚记', 6, 21, 33, '革顺人按着家族所有的城共十三座，还有这些城的郊野。'),
('CNV', '约书亚记', 6, 21, 34, '其余的利未人，米拉利的子孙的家族，从西布伦支派中分得约念和约念的郊野，加珥他和加珥他的郊野，'),
('CNV', '约书亚记', 6, 21, 35, '丁拿和丁拿的郊野，拿哈拉和拿哈拉的郊野，共四座城。'),
('CNV', '约书亚记', 6, 21, 36, '又从流本支派中，给了他们比悉和比悉的郊野，雅杂和雅杂的郊野，'),
('CNV', '约书亚记', 6, 21, 37, '基底莫和基底莫的郊野，米法押和米法押的郊野，共四座城。'),
('CNV', '约书亚记', 6, 21, 38, '以色列人又从迦得支派中，把误杀人者的避难城，就是在基列的拉末和拉末的郊野，给了他们；又给他们玛哈念和玛哈念的郊野，'),
('CNV', '约书亚记', 6, 21, 39, '希实本和希实本的郊野，雅谢和雅谢的郊野，共四座城。'),
('CNV', '约书亚记', 6, 21, 40, '利未人其余的家族，就是米拉利的子孙，按着家族抽签所得的城，共有十二座。'),
('CNV', '约书亚记', 6, 21, 41, '在以色列人的地业中，利未人所得的城共四十八座，还有这些城的郊野。'),
('CNV', '约书亚记', 6, 21, 42, '这些城周围都有自己的郊野，每一座都是这样。'),
('CNV', '约书亚记', 6, 21, 43, '这样，耶和华就把他从前起誓要赐给他们列祖的全地给了以色列人；以色列人占领了那地，就定居下来。'),
('CNV', '约书亚记', 6, 21, 44, '耶和华照着他向他们列祖起誓所说的一切话，使他们四境平静；他们所有的仇敌，没有一人能在他们面前站立得住；耶和华把他们所有的仇敌都交在他们手里。'),
('CNV', '约书亚记', 6, 21, 45, '耶和华向以色列家应许赐福的话，没有一句落空，都应验了。'),
('CNV', '约书亚记', 6, 22, 1, '那时，约书亚把流本人、迦得人和玛拿西半个支派的人召了来，'),
('CNV', '约书亚记', 6, 22, 2, '对他们说：“耶和华的仆人摩西吩咐你们的一切，你们都遵守了；我吩咐你们的一切，你们也都听从了。'),
('CNV', '约书亚记', 6, 22, 3, '这许多日子以来，你们一直没有撇弃你们的兄弟，直到今日；耶和华你们的神吩咐你们的命令，你们也遵守了。'),
('CNV', '约书亚记', 6, 22, 4, '现在耶和华你们的神，照着他应许的，已经使你们兄弟得享平安；现在你们可以返回自己家里，回到耶和华的仆人摩西在约旦河东赐给你们作产业的地方去。'),
('CNV', '约书亚记', 6, 22, 5, '只是你们要谨慎遵守耶和华的仆人摩西吩咐你们的诫命和律法，爱耶和华你们的神，遵行他的一切道路，谨守他的诫命，紧紧倚靠他，一心一意事奉他。”'),
('CNV', '约书亚记', 6, 22, 6, '于是约书亚给他们祝福，打发他们回去，他们就回自己的家里去了。'),
('CNV', '约书亚记', 6, 22, 7, '摩西在巴珊已经把产业分给了玛拿西半个支派；至于另外半个支派，约书亚在约旦河西他们的兄弟中间，也把产业分给了他们。约书亚打发他们回家去的时候，给他们祝福，'),
('CNV', '约书亚记', 6, 22, 8, '对他们说：“你们带着许多财物，许多牲畜和金、银、铜、铁，以及许多衣服，回自己的家去吧；也要把你们从仇敌夺得的战利品与你们的兄弟同分。”'),
('CNV', '约书亚记', 6, 22, 9, '于是流本人、迦得人和玛拿西半个支派的人，从迦南地的示罗起程，离开以色列人，回到他们所得的产业基列地去，就是照着耶和华藉着摩西所吩咐，赐给他们的产业。'),
('CNV', '约书亚记', 6, 22, 10, '流本人、迦得人和玛拿西半个支派的人，来到迦南地靠近约旦河的地区，就在约旦河边那里筑了一座祭坛，那坛十分壮观。'),
('CNV', '约书亚记', 6, 22, 11, '以色列人听见了这事，就说：“看哪，流本人、迦得人和玛拿西半个支派的人，在迦南地边境，靠近约旦河的地区，以色列人境内，筑了一座坛。”'),
('CNV', '约书亚记', 6, 22, 12, '以色列人听见了这事，以色列全体会众就聚集在示罗，要上去讨伐他们。'),
('CNV', '约书亚记', 6, 22, 13, '以色列人派以利亚撒祭司的儿子非尼哈，到基列地去见流本人、迦得人和玛拿西半个支派的人；'),
('CNV', '约书亚记', 6, 22, 14, '又派十个首领与非尼哈同去，每一个都代表以色列的支派家族；他们是全体以色列各家族的领袖。'),
('CNV', '约书亚记', 6, 22, 15, '他们去到基列地，流本人、迦得人和玛拿西半个支派的人那里，对他们说：'),
('CNV', '约书亚记', 6, 22, 16, '“耶和华的全体会众这样说：‘你们作的是什么事？竟对以色列的神不忠，今日转离不跟从耶和华，为自己筑了一座坛，背叛了耶和华。'),
('CNV', '约书亚记', 6, 22, 17, '从前拜毗珥的罪孽，我们还以为是小事吗？虽然有灾疫临到耶和华的会众，直到今日我们还没有洗净这罪呢。'),
('CNV', '约书亚记', 6, 22, 18, '你们今日竟转离不跟从耶和华吗？今日你们既然背叛耶和华，明日他必向以色列全体会众发怒了。'),
('CNV', '约书亚记', 6, 22, 19, '如果你们认为所得的地业不洁净，你们可以过到耶和华的地业，就是耶和华的帐幕居住的地方，在我们中间得地业；只是不可背叛耶和华，也不可背叛我们，在耶和华我们的神的坛以外，为自己筑另一座坛。'),
('CNV', '约书亚记', 6, 22, 20, '从前谢拉的曾孙亚干，不是在当毁灭的物上犯了不忠的罪，以致神的忿怒临到以色列全体会众吗？因他的罪孽而死的，还不只他一人呢！’”'),
('CNV', '约书亚记', 6, 22, 21, '于是流本人、迦得人和玛拿西半个支派的人回答以色列各家族的统领说：'),
('CNV', '约书亚记', 6, 22, 22, '“大能者神耶和华！大能者神耶和华，他是知道的，愿以色列也知道；如果我们存心背叛，或是对耶和华不忠，今日就不要放过我们。'),
('CNV', '约书亚记', 6, 22, 23, '我们若是为自己筑坛，转离不跟从耶和华，或是把燔祭、素祭和平安祭献在坛上，愿耶和华亲自追究我们。'),
('CNV', '约书亚记', 6, 22, 24, '我们作这事，实在是有理由的，因为顾虑将来你们的子孙对我们的子孙说：‘你们与耶和华以色列的神有什么关系呢？'),
('CNV', '约书亚记', 6, 22, 25, '流本人和迦得人啊，耶和华定了约旦河作我们和你们中间的疆界；你们与耶和华无分了。’这样，你们的子孙就使我们的子孙不再敬畏耶和华了。'),
('CNV', '约书亚记', 6, 22, 26, '“因此我们说：‘我们筑一座坛吧，不是为了献燔祭，也不是为了献别的祭，'),
('CNV', '约书亚记', 6, 22, 27, '而是为了在你们和我们中间，也在我们的后代中间作证据，使我们也可以在耶和华面前用燔祭、别的祭和平安祭事奉耶和华，免得你们的子孙将来对我们的子孙说：你们与耶和华无分了。’'),
('CNV', '约书亚记', 6, 22, 28, '因此我们说：‘将来有人对我们，或是对我们的后代这样说，我们就可以回答：你们看我们列祖所筑的坛，是耶和华的祭坛的模式，这并不是用来献燔祭，也不是用来献别的祭，而是在我们和你们中间作证据。’'),
('CNV', '约书亚记', 6, 22, 29, '我们决没有背叛耶和华的意思，今日要转离不跟从耶和华，在耶和华我们的神的帐幕前的祭坛以外，另筑一座坛，为了献燔祭、素祭和别的祭。”'),
('CNV', '约书亚记', 6, 22, 30, '非尼哈祭司和会众的领袖，以及与祭司同来的以色列的统领，听了流本人、迦得人和玛拿西人说的话，都很满意。'),
('CNV', '约书亚记', 6, 22, 31, '以利亚撒祭司的儿子非尼哈对流本人、迦得人和玛拿西人说：“今天我们知道耶和华是在我们中间的，因为你们并没有对耶和华不忠；现在你们已经救了以色列人脱离耶和华的手。”'),
('CNV', '约书亚记', 6, 22, 32, '以利亚撒祭司的儿子非尼哈和众领袖离开了流本人和迦得人，从基列地回到迦南地以色列人那里，把这事向他们报告。'),
('CNV', '约书亚记', 6, 22, 33, '以色列人对这事都很满意，就称颂神，不再说要上去讨伐流本人和迦得人，毁灭他们所住的地方了。'),
('CNV', '约书亚记', 6, 22, 34, '流本人和迦得人给那坛起名叫证坛，因为他们说：“这坛在我们中间证明耶和华是神。”'),
('CNV', '约书亚记', 6, 23, 1, '耶和华使以色列人得享平安，不受四围仇敌的骚扰，已经有一段很长的日子；约书亚已经老了，年纪不小了。'),
('CNV', '约书亚记', 6, 23, 2, '约书亚就把全体以色列人、他们的长老、首领、审判官和官长，都召了来，对他们说：“我已经老了，年纪不小了。'),
('CNV', '约书亚记', 6, 23, 3, '耶和华你们的神，因你们的缘故，向那些国家所行的一切事，你们都亲眼看见了；因为耶和华你们的神为你们作战。'),
('CNV', '约书亚记', 6, 23, 4, '你们看，剩下来的这些国家，连同我剪除的列国，从约旦河起，直到日落之处的大海，我都按着你们各支派，用抽签的方式，分给你们作产业了。'),
('CNV', '约书亚记', 6, 23, 5, '耶和华你们的神必把他们从你们面前赶出去，驱逐他们离开你们，你们就必得着他们的地作产业，正如耶和华你们的神所应许的。'),
('CNV', '约书亚记', 6, 23, 6, '所以你们要十分坚强，谨守遵行写在摩西律法书上的一切话，使你们不偏向左，不偏向右；'),
('CNV', '约书亚记', 6, 23, 7, '使你们不与你们中间剩下的这些国家的人来往；他们的神的名字，你们不可提，不可指着他们起誓，不可事奉他们，也不可敬拜他们；'),
('CNV', '约书亚记', 6, 23, 8, '只要照着你们一直以来所行的，紧紧倚靠耶和华你们的神。'),
('CNV', '约书亚记', 6, 23, 9, '因为耶和华已经把又大又强的列国从你们面前赶出去；至于你们，直到今日，还没有一人能在你们面前站立得住。'),
('CNV', '约书亚记', 6, 23, 10, '你们一人可以追赶千人，因为耶和华你们的神，照着他应许你们的，为你们作战。'),
('CNV', '约书亚记', 6, 23, 11, '你们自己要十分谨慎，爱耶和华你们的神。'),
('CNV', '约书亚记', 6, 23, 12, '如果你们转离耶和华，与你们中间剩下的这些国家的余民联络，和他们通婚，互相来往，'),
('CNV', '约书亚记', 6, 23, 13, '你们就必知道，耶和华你们的神必不再把这些国家从你们面前赶出去；他们必要成为你们的网罗和陷阱，肋下的鞭和眼中的刺，直到你们从耶和华你们的神赐给你们的这美地上灭亡为止。'),
('CNV', '约书亚记', 6, 23, 14, '“看哪，我今天要走世人必经的路了。你们清清楚楚（“清清楚楚”原文作“一心一意”）知道耶和华你们的神应许赐福给你们的话，没有一句落空；完全应验在你们身上，没有一句落空。'),
('CNV', '约书亚记', 6, 23, 15, '耶和华你们的神应许你们的一切福气怎样临到你们身上，耶和华也必照样使各样的灾祸临到你们身上，直到把你们从耶和华你们的神赐给你们的这美地上消灭为止。'),
('CNV', '约书亚记', 6, 23, 16, '如果你们违背了耶和华你们的神吩咐你们遵守的约，去事奉别的神，敬拜他们，耶和华必向你们大发烈怒，使你们从他赐给你们的美地上迅速灭亡。”'),
('CNV', '约书亚记', 6, 24, 1, '约书亚在示剑召集以色列各支派，又把以色列的长老、首领、审判官和官长都召了来，他们就站在神面前。'),
('CNV', '约书亚记', 6, 24, 2, '约书亚对众民说：“耶和华以色列的神这样说：‘古时你们的列祖，就是亚伯拉罕和拿鹤的父亲他拉，住在大河那边；他们事奉别的神。'),
('CNV', '约书亚记', 6, 24, 3, '我把你们的祖先亚伯拉罕，从大河那边带来，领他走遍迦南地，使他的后裔增多，把以撒赐给他；'),
('CNV', '约书亚记', 6, 24, 4, '又把雅各和以扫赐给以撒，把西珥山赐给以扫作产业；雅各和他的子孙却下到埃及去。'),
('CNV', '约书亚记', 6, 24, 5, '我差派了摩西和亚伦，藉着我在埃及所行的神迹，用灾疫击打埃及，然后把你们领出来。'),
('CNV', '约书亚记', 6, 24, 6, '我领你们的列祖离开埃及，他们去到海边；埃及人带着战车和马兵，追赶你们的列祖直到红海。'),
('CNV', '约书亚记', 6, 24, 7, '你们的列祖呼求耶和华，他就以黑暗隔开你们和埃及人，又使海水复流淹没了他们；我在埃及所行的事，你们都亲眼见过；你们在旷野也住了许多日子。'),
('CNV', '约书亚记', 6, 24, 8, '我领你们到了住在约旦河东的亚摩利人的地，他们和你们争战，我把他们交在你们手里，你们就得了他们的地作产业；我也在你们面前把他们消灭。'),
('CNV', '约书亚记', 6, 24, 9, '那时摩押王西拨的儿子巴勒起来攻击以色列人；他派人把比珥的儿子巴兰召了来，咒诅你们。'),
('CNV', '约书亚记', 6, 24, 10, '我不肯听巴兰的话，结果他反而一而再祝福你们；这样，我就救了你们脱离他的手。'),
('CNV', '约书亚记', 6, 24, 11, '你们过了约旦河，来到耶利哥；耶利哥的居民与你们作战，还有亚摩利人、比利洗人、迦南人、赫人、革迦撒人、希未人、耶布斯人，也跟你们作战；我把他们都交在你们手里。'),
('CNV', '约书亚记', 6, 24, 12, '我派了黄蜂飞在你们前面，把亚摩利人的两个王从你们面前赶走，并不是用你的刀，也不是用你的弓。'),
('CNV', '约书亚记', 6, 24, 13, '我赐给你们的土地，不是你们劳苦开垦的；我赐给你们的城市，不是你们建造的，你们却住在城中；你们享用的葡萄园和橄榄园，也不是你们栽种的。’'),
('CNV', '约书亚记', 6, 24, 14, '“现在你们要敬畏耶和华，真诚地按着真理事奉他，把你们列祖在大河那边和在埃及事奉的神除掉，去事奉耶和华。'),
('CNV', '约书亚记', 6, 24, 15, '如果你们认为事奉耶和华不好，那么今日你们就可以选择你们所要事奉的：是你们列祖在大河那边事奉的神呢，还是你们现在所住亚摩利人之地的神呢？至于我和我家，我们必事奉耶和华。”'),
('CNV', '约书亚记', 6, 24, 16, '众民回答：“我们绝对不会离弃耶和华，去事奉别的神；'),
('CNV', '约书亚记', 6, 24, 17, '因为耶和华我们的神把我们和我们的列祖，从埃及地为奴的家领出来，并且在我们眼前行了那些伟大的神迹；又在我们所行的一切路上，和我们经过的一切民族中间，他都保护了我们；'),
('CNV', '约书亚记', 6, 24, 18, '耶和华又把所有的民族和住在这地的亚摩利人，都从我们面前赶走；所以我们必事奉耶和华，因为他是我们的神。”'),
('CNV', '约书亚记', 6, 24, 19, '约书亚对众民说：“你们不能事奉耶和华，因为他是圣洁的神；他是嫉妒的神，他必不赦免你们的过犯和罪恶。'),
('CNV', '约书亚记', 6, 24, 20, '如果你们离弃耶和华，去事奉外族人的神，那么在耶和华赐福给你们之后，他必转而降祸与你们，把你们消灭。”'),
('CNV', '约书亚记', 6, 24, 21, '众民对约书亚说：“不，我们必定事奉耶和华。”'),
('CNV', '约书亚记', 6, 24, 22, '约书亚对众民说：“你们选择了耶和华，要事奉他，你们为自己作证吧。”他们说：“我们愿意作证。”'),
('CNV', '约书亚记', 6, 24, 23, '约书亚说：“现在你们要除掉在你们中间外族人的神，一心归向耶和华以色列的神。”'),
('CNV', '约书亚记', 6, 24, 24, '众民对约书亚说：“我们必事奉耶和华我们的神，必听从他的话。”'),
('CNV', '约书亚记', 6, 24, 25, '那一天，约书亚就与众民立约，在示剑为他们订立律例和典章。'),
('CNV', '约书亚记', 6, 24, 26, '约书亚把这些话都写在神的律法书上；又拿一块大石头，立在耶和华圣所旁边的橡树下。'),
('CNV', '约书亚记', 6, 24, 27, '约书亚对全体人民说：“看哪，这块石头可以向我们作证，因为它听见了耶和华对我们所说的一切话；所以这块石头要向你们作证，免得你们否认你们的神。”'),
('CNV', '约书亚记', 6, 24, 28, '于是约书亚打发众民各自回到自己的地业去了。'),
('CNV', '约书亚记', 6, 24, 29, '这些事以后，耶和华的仆人、嫩的儿子约书亚死了，那时他是一百一十岁。'),
('CNV', '约书亚记', 6, 24, 30, '以色列人把他埋葬在他自己地业的境内，就是在以法莲山地上的亭拿．西拉，在迦实山的北边。'),
('CNV', '约书亚记', 6, 24, 31, '约书亚在世的日子，和约书亚死后，那些知道耶和华为以色列人所行的一切事的长老还在世的日子，以色列人都事奉耶和华。'),
('CNV', '约书亚记', 6, 24, 32, '以色列人从埃及带出来的约瑟骸骨，葬在示剑的一块田里；这块田是雅各从前用一百块银子向示剑的父亲哈抹的子孙那里买来的；这块田就成了约瑟子孙的产业。'),
('CNV', '约书亚记', 6, 24, 33, '亚伦的儿子以利亚撒也死了；以色列人就把他埋葬在基比亚，就是他儿子非尼哈在以法莲山地所得的产业。'),
('CNV', '士师记', 7, 1, 1, '约书亚死后，以色列人求问耶和华说：“谁要为我们首先去攻打迦南人，与他们作战呢？”'),
('CNV', '士师记', 7, 1, 2, '耶和华回答：“犹大要先上去，看哪，我已经把那地交在他手中。”'),
('CNV', '士师记', 7, 1, 3, '犹大对自己的兄弟西缅说：“请你与我一同上我抽签所得的地业去，我们好与迦南人交战；以后我也与你一同到你抽签所得的地业去。”于是西缅与他一同去了。'),
('CNV', '士师记', 7, 1, 4, '犹大上去了；耶和华就把迦南人和比利洗人交在他们手中；他们在比色击杀了一万人。'),
('CNV', '士师记', 7, 1, 5, '他们在那里遇见了比色王，就与他交战，击杀了迦南人和比利洗人。'),
('CNV', '士师记', 7, 1, 6, '比色王逃跑；他们追赶他，把他捉住，砍去了他手脚的大拇指。'),
('CNV', '士师记', 7, 1, 7, '比色王说：“从前有七十个王，手脚的大拇指都被我砍去，在我的桌子底下拾取食物；现在神照着我所行的，报应我了。”于是他们把他带到耶路撒冷，后来他就死在那里。'),
('CNV', '士师记', 7, 1, 8, '犹大人攻打耶路撒冷，把城占领，用刀击杀了城中的居民，又放火烧城。'),
('CNV', '士师记', 7, 1, 9, '后来，犹大人下去，与住在山地、南地和高原的迦南人交战。'),
('CNV', '士师记', 7, 1, 10, '犹大人又去攻击住在希伯仑的迦南人，杀了示筛、亚希幔和挞买；希伯仑从前名叫基列．亚巴。'),
('CNV', '士师记', 7, 1, 11, '他们从那里又去攻击底璧的居民；底璧从前名叫基列．西弗。'),
('CNV', '士师记', 7, 1, 12, '迦勒说：“谁能攻打基列．西弗，把城攻取，我就把我的女儿押撒给他作妻子。”'),
('CNV', '士师记', 7, 1, 13, '迦勒的弟弟基纳斯的儿子俄陀聂攻取了那城，迦勒就把自己的女儿押撒给他作妻子。'),
('CNV', '士师记', 7, 1, 14, '押撒出嫁的时候，她劝俄陀聂向她父亲求一块田；押撒一下驴，迦勒就对她说：“你要什么？”'),
('CNV', '士师记', 7, 1, 15, '她回答：“请你给我一份礼物；你既然把我安置在南地，求你也把水泉赐给我。”迦勒就把上泉和下泉都给了她。'),
('CNV', '士师记', 7, 1, 16, '摩西岳父的子孙基尼人，和犹大人一同离开棕树城，上到亚拉得以南的犹大旷野去，住在那里的人民中。'),
('CNV', '士师记', 7, 1, 17, '犹大与他的兄弟西缅同去，击杀了住在洗法的迦南人，把那城完全毁灭。那城的名字就叫何珥玛。'),
('CNV', '士师记', 7, 1, 18, '犹大又攻取了迦萨和迦萨的四境，亚实基伦和亚实基伦的四境，以革伦和以革伦的四境。'),
('CNV', '士师记', 7, 1, 19, '耶和华与犹大同在，犹大就占领了山地；但不能赶走平原的居民，因为他们有铁车。'),
('CNV', '士师记', 7, 1, 20, '犹大照着摩西的吩咐，把希伯仑给了迦勒；迦勒就从那里赶走亚衲子孙的三族。'),
('CNV', '士师记', 7, 1, 21, '便雅悯人没有赶走住在耶路撒冷的耶布斯人，所以耶布斯人与便雅悯人一同住在耶路撒冷，直到今日。'),
('CNV', '士师记', 7, 1, 22, '约瑟家也上去攻打伯特利；耶和华与他们同在。'),
('CNV', '士师记', 7, 1, 23, '约瑟家派人去窥探伯特利。那城从前的名字叫路斯。'),
('CNV', '士师记', 7, 1, 24, '窥探的人看见一个人从城里出来，就对他说：“请你把进城的路指示我们，我们必恩待你。”'),
('CNV', '士师记', 7, 1, 25, '那人把进城的路指示了他们，他们就用刀击杀了那城的居民，却把那人和他的全家都放走。'),
('CNV', '士师记', 7, 1, 26, '那人到赫人之地去了，筑了一座城，给它起名叫路斯；直到今日那城还叫这名。'),
('CNV', '士师记', 7, 1, 27, '玛拿西没有赶走伯．善和属于伯．善的乡村的居民，他纳和属于他纳的乡村的居民，多珥和属于多珥的乡村的居民，以伯莲和属于以伯莲的乡村的居民，米吉多和属于米吉多的乡村的居民；迦南人决意住在那地。'),
('CNV', '士师记', 7, 1, 28, '到以色列强盛了，就迫使迦南人作苦工，但没有把他们完全赶走。'),
('CNV', '士师记', 7, 1, 29, '以法莲也没有把住在基色的迦南人赶走，于是迦南人还住在基色，在以法莲中间。'),
('CNV', '士师记', 7, 1, 30, '西布伦没有把基伦的居民和拿哈拉的居民赶走；于是迦南人还住在西布伦中间，成了作苦工的人。'),
('CNV', '士师记', 7, 1, 31, '亚设没有把亚柯的居民和西顿的居民赶走，也没有把亚黑拉、亚革悉、黑巴、亚弗革和利合的居民赶走。'),
('CNV', '士师记', 7, 1, 32, '于是亚设人住在当地的居民迦南人中间，因为他们没有把他们赶走。'),
('CNV', '士师记', 7, 1, 33, '拿弗他利没有把伯．示麦的居民和伯．亚纳的居民赶走；于是他们就住在当地的居民迦南人中间；伯．示麦和伯．亚纳的居民成了给他们作苦工的人。'),
('CNV', '士师记', 7, 1, 34, '亚摩利人强迫但人退回山地上，不容他们下到平原来。'),
('CNV', '士师记', 7, 1, 35, '亚摩利人决意住在希烈山、亚雅仑和沙宾；但约瑟家的势力强大以后，他们就成了作苦工的人。'),
('CNV', '士师记', 7, 1, 36, '亚摩利人的境界，是从亚克拉滨山坡，从西拉直上。'),
('CNV', '士师记', 7, 2, 1, '耶和华的使者从吉甲上到波金来，说：“我曾经把你们从埃及领上来，带你们到我向你们列祖起誓应许的地方；我曾说过：‘我永不废弃我与你们所立的约；'),
('CNV', '士师记', 7, 2, 2, '你们不可与这地的居民立约，要拆毁他们的祭坛。’你们竟没有听从我的话；你们作的是什么呢？'),
('CNV', '士师记', 7, 2, 3, '因此我又说：‘我必不把他们从你们面前赶走，他们要作你们的敌人（按照《马索拉文本》，“敌人”作“边旁”，意思不明确，或译﹕“网罗”﹔现参照各古译本翻译），他们的神要作你们的网罗。’”'),
('CNV', '士师记', 7, 2, 4, '耶和华的使者对以色列众人说这些话的时候，众人就放声大哭。'),
('CNV', '士师记', 7, 2, 5, '于是给那地方起名叫波金；他们在那里向耶和华献祭。'),
('CNV', '士师记', 7, 2, 6, '约书亚遣散了众人，以色列人就各归自己承受的地业，要占有那地。'),
('CNV', '士师记', 7, 2, 7, '约书亚在世的时候，以及他去世以后，那些见过耶和华为以色列人所行的大事的众长老还在的日子，众人都事奉耶和华。'),
('CNV', '士师记', 7, 2, 8, '耶和华的仆人，嫩的儿子约书亚，在一百一十岁的时候就死了。'),
('CNV', '士师记', 7, 2, 9, '以色列人把他埋葬在他地业的境内，就是以法莲山地，在迦实山北面的亭拿．希烈。'),
('CNV', '士师记', 7, 2, 10, '那一代的人都归到他们的列祖那里以后，有另一代的人兴起来了；他们不认识耶和华，也不知道耶和华为以色列人所行的事。'),
('CNV', '士师记', 7, 2, 11, '以色列人行了耶和华看为恶的事，去事奉众巴力；'),
('CNV', '士师记', 7, 2, 12, '他们离弃了领他们出埃及的耶和华、他们列祖的神，去跟从别的神，就是他们周围各族的神，敬拜他们，惹耶和华发怒。'),
('CNV', '士师记', 7, 2, 13, '他们离弃了耶和华，去事奉巴力和亚斯他录。'),
('CNV', '士师记', 7, 2, 14, '耶和华的怒气向以色列人发作，就把他们交在抢掠的人手中，他们就抢掠他们；他又把他们完全交在他们四围的仇敌手中，以致他们在仇敌面前再不能站立得住。'),
('CNV', '士师记', 7, 2, 15, '他们无论去哪里，耶和华的手总是加害他们，好像耶和华说过的，又像耶和华对他们起誓过的；他们就非常困苦。'),
('CNV', '士师记', 7, 2, 16, '耶和华兴起了士师，士师就拯救他们脱离抢掠他们的人的手。'),
('CNV', '士师记', 7, 2, 17, '但他们连士师也不听从，竟与别的神行了奸淫，敬拜他们；他们迅速偏离了他们列祖所行、听从耶和华命令的道路，他们没有照样行。'),
('CNV', '士师记', 7, 2, 18, '耶和华为他们兴起士师的时候，耶和华就与那士师同在；那士师在世的日子，耶和华总是拯救他们脱离仇敌的手；因为他们在压迫和苦害他们的人底下发出哀声，耶和华就怜悯他们。'),
('CNV', '士师记', 7, 2, 19, '可是士师死了以后，他们就转而行恶，比他们的列祖更厉害，去随从别的神，事奉和敬拜他们，总不放弃他们的恶行和顽梗的行径。'),
('CNV', '士师记', 7, 2, 20, '于是耶和华的怒气向以色列人发作，说：“因为这国的人违背我吩咐他们列祖的约，不听从我的话，'),
('CNV', '士师记', 7, 2, 21, '因此，约书亚死后仍剩下来的列国，我也不再从他们面前赶走，'),
('CNV', '士师记', 7, 2, 22, '为要藉着他们试验以色列人，看他们肯不肯谨守遵行耶和华的道路，像他们的列祖一样谨守。”'),
('CNV', '士师记', 7, 2, 23, '这样，耶和华留下这些国的民，不迅速把他们赶走，也不把他们交在约书亚手里。'),
('CNV', '士师记', 7, 3, 1, '这些国的人是耶和华留下的，为要藉着他们来试验以色列人，就是所有没有经验过迦南任何战争的人；'),
('CNV', '士师记', 7, 3, 2, '好使以色列人的后代，那些以前没有经验过这些战争的人，知道学习争战。'),
('CNV', '士师记', 7, 3, 3, '他留下的就是非利士人的五个首领，和所有迦南人、西顿人，以及住在黎巴嫩山上的希未人，从巴力．黑门山直到哈马口。'),
('CNV', '士师记', 7, 3, 4, '他们留在那里，为要藉着他们试验以色列人，要知道他们是否听从耶和华藉摩西吩咐他们列祖的诫命。'),
('CNV', '士师记', 7, 3, 5, '以色列人就住在迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人中间；'),
('CNV', '士师记', 7, 3, 6, '他们娶他们的女儿作妻子，也把自己的女儿嫁给他们的儿子，并且事奉他们的神。'),
('CNV', '士师记', 7, 3, 7, '以色列人行了耶和华看为恶的事，忘记了耶和华他们的神，去事奉众巴力和亚舍拉。'),
('CNV', '士师记', 7, 3, 8, '因此，耶和华的怒气向以色列人发作，把他们完全交在两河之间的亚兰王古珊．利萨田的手中；以色列人服事了古珊．利萨田八年。'),
('CNV', '士师记', 7, 3, 9, '以色列人向耶和华哀求的时候，耶和华就为以色列人兴起一位拯救者拯救他们，就是迦勒的弟弟基纳斯的儿子俄陀聂。'),
('CNV', '士师记', 7, 3, 10, '耶和华的灵临到他身上，他就治理以色列人；他出去作战，耶和华把亚兰王古珊．利萨田交在他手中，他的能力就胜过了古珊．利萨田。'),
('CNV', '士师记', 7, 3, 11, '于是国中太平了四十年。后来基纳斯的儿子俄陀聂死了。'),
('CNV', '士师记', 7, 3, 12, '以色列人又行了耶和华看为恶的事，耶和华就使摩押王伊矶伦强盛起来，欺压以色列人，因为他们行了耶和华看为恶的事。'),
('CNV', '士师记', 7, 3, 13, '伊矶伦集合了亚扪人和亚玛力人，前来击败了以色列人，占领了棕树城。'),
('CNV', '士师记', 7, 3, 14, '于是以色列人服事了摩押王伊矶伦十八年。'),
('CNV', '士师记', 7, 3, 15, '以色列人向耶和华哀求的时候，耶和华就为他们兴起一位拯救者，就是便雅悯人基拉的儿子以笏，是一个用左手的人。以色列人派他把贡物送给摩押王伊矶伦。'),
('CNV', '士师记', 7, 3, 16, '以笏做了一把两刃的剑，长半公尺，缚在右腿上，在衣服底下。'),
('CNV', '士师记', 7, 3, 17, '他把贡物呈献给摩押王伊矶伦；伊矶伦原是个非常肥胖的人。'),
('CNV', '士师记', 7, 3, 18, '以笏献完了贡物，就把抬贡物的众人打发走了。'),
('CNV', '士师记', 7, 3, 19, '自己却从靠近吉甲的众雕像那里回来，说：“王啊，我有一件机密的事要对你说。”王说：“暂不要说。”侍立左右的人都离开他出去了。'),
('CNV', '士师记', 7, 3, 20, '以笏来到王那里；王独自一人坐在凉楼上。以笏说：“我有神的话要告诉你。”王就从座位上站起来。'),
('CNV', '士师记', 7, 3, 21, '以笏就伸出左手，从右腿上拔出剑来，刺入王的腹中；'),
('CNV', '士师记', 7, 3, 22, '连剑柄与剑身都刺进去了，肥肉把剑身夹住，因此他没有把剑从王的肚腹里拔出来；接着他就从窗户爬了出去。'),
('CNV', '士师记', 7, 3, 23, '以笏出到走廊，把凉楼上的门关起来，上了锁。'),
('CNV', '士师记', 7, 3, 24, '以笏出来以后，王的仆人才来到；他们看见凉楼上的门锁着，就说：“王一定是在凉楼上大解。”'),
('CNV', '士师记', 7, 3, 25, '他们等到发慌了，见他还不打开凉楼的门，就拿钥匙来开；不料，看见他们的主人早已倒在地上死了。'),
('CNV', '士师记', 7, 3, 26, '他们耽延的时候，以笏已经逃跑了；他经过众雕像那里，逃到西伊拉去。'),
('CNV', '士师记', 7, 3, 27, '他去到以后，就在以法莲山地吹角；以色列人与他一同从山地上下来，他走在他们前头，'),
('CNV', '士师记', 7, 3, 28, '对他们说：“你们跟随我，因为耶和华已经把你们的仇敌摩押人交在你们手中。”他们就跟随他下去，攻取约旦河的渡口，拦截摩押人，不让一个过去。'),
('CNV', '士师记', 7, 3, 29, '那时他们击杀了约有一万摩押人，都是强壮的、勇猛的人，没有一人逃脱。'),
('CNV', '士师记', 7, 3, 30, '这样，从那天起，摩押就在以色列人的手下被制伏了，于是国中太平了八十年。'),
('CNV', '士师记', 7, 3, 31, '以笏之后，有亚拿的儿子珊迦；他用赶牛棒击杀了六百非利士人；他也拯救了以色列人。'),
('CNV', '士师记', 7, 4, 1, '以笏死后，以色列人又行了耶和华看为恶的事。'),
('CNV', '士师记', 7, 4, 2, '因此耶和华把他们交在迦南王耶宾手中，耶宾那时在夏琐作王；他的军长西西拉，住在夏罗设歌印。'),
('CNV', '士师记', 7, 4, 3, '耶宾王有铁车九百辆，他极力欺压以色列人二十年，以色列人就哀求耶和华。'),
('CNV', '士师记', 7, 4, 4, '有一位女先知底波拉，是拉比多的妻子，那时正治理以色列人。'),
('CNV', '士师记', 7, 4, 5, '她常坐在以法莲山地，拉玛和伯特利之间那棵底波拉棕树下；以色列人都上到她那里去听判断。'),
('CNV', '士师记', 7, 4, 6, '底波拉派人去从拿弗他利的基低斯，把亚比挪菴的儿子巴拉召了来，对他说：“耶和华以色列的神不是曾吩咐你说：‘你去向他泊山进军，从拿弗他利人和西布伦人中率领一万人与你同去吗？'),
('CNV', '士师记', 7, 4, 7, '我必引耶宾的军长西西拉，和他的车辆与全军，到基顺河往你那里去；我必把他们交在你手里。’”'),
('CNV', '士师记', 7, 4, 8, '巴拉对她说：“如果你与我同去，我就去；如果你不与我同去，我就不去。”'),
('CNV', '士师记', 7, 4, 9, '底波拉回答：“我必与你同去，只是你这次行程就没有光荣；因为耶和华要把西西拉交在一个妇人手里。”于是底波拉起来，与巴拉一同到基低斯去了。'),
('CNV', '士师记', 7, 4, 10, '巴拉就召集西布伦人和拿弗他利人到基低斯；与他一同步行上去的有一万人，底波拉也与他一同上去。'),
('CNV', '士师记', 7, 4, 11, '摩西的岳父何巴的子孙基尼人希伯，曾经离开基尼族人，到靠近基低斯的撒拿音的橡树旁，支搭帐棚居住。'),
('CNV', '士师记', 7, 4, 12, '有人告诉西西拉，亚比挪菴的儿子巴拉已经上了他泊山；'),
('CNV', '士师记', 7, 4, 13, '西西拉就召集他所有的车辆，就是九百辆铁车，和与他在一起的众人，都从夏罗设歌印出来，到基顺河那里。'),
('CNV', '士师记', 7, 4, 14, '底波拉对巴拉说：“你起来吧，因为今日就是耶和华把西西拉交在你手里的日子；耶和华不是在你前面出战吗？”于是巴拉和跟随他的一万人从他泊山下来。'),
('CNV', '士师记', 7, 4, 15, '耶和华用刀使西西拉和所有的车辆与全军，都在巴拉面前溃乱；西西拉下了车，步行逃跑。'),
('CNV', '士师记', 7, 4, 16, '巴拉追赶西西拉的车辆和军队，直到夏罗设歌印；西西拉的全军都倒在刀下，连一个也没有留下。'),
('CNV', '士师记', 7, 4, 17, '只有西西拉步行逃跑，到了基尼人希伯的妻子雅亿的帐棚那里；因为夏琐王耶宾与基尼人希伯的家友好。'),
('CNV', '士师记', 7, 4, 18, '雅亿出来迎接西西拉，对他说：“请我主转过来，到我这里，不要惧怕。”西西拉就转到她那里去，就是转到她的帐棚里去；雅亿就用毛毡遮盖他。'),
('CNV', '士师记', 7, 4, 19, '西西拉对雅亿说：“请给我一点水喝，因为我渴了。”雅亿就打开盛奶的皮袋，给他喝了，再把他盖着。'),
('CNV', '士师记', 7, 4, 20, '西西拉又对雅亿说：“请你站在帐棚门口，如果有人来问你：‘这里有人吗？’你就要回答：‘没有。’”'),
('CNV', '士师记', 7, 4, 21, '希伯的妻子雅亿取了一根帐棚的橛子，手里拿着锤子，静悄悄地走到西西拉那里，把橛子钉在他的太阳穴里，直钉入地里；因为西西拉疲乏熟睡，就这样死了。'),
('CNV', '士师记', 7, 4, 22, '那时，巴拉追赶西西拉，雅亿出来迎接他，对他说：“来吧，我给你看你寻找的人。”他就进到她那里去；看见西西拉已经仆倒，死了；橛子还在他的太阳穴里。'),
('CNV', '士师记', 7, 4, 23, '这样，神就在那一天，在以色列人面前，制伏了迦南王耶宾。'),
('CNV', '士师记', 7, 4, 24, '以色列人的势力日渐强盛，胜过迦南王耶宾，终于把迦南王耶宾除灭。'),
('CNV', '士师记', 7, 5, 1, '那一天，底波拉和亚比挪菴的儿子巴拉唱起歌来说：'),
('CNV', '士师记', 7, 5, 2, '“你们要称颂耶和华，因为以色列中有勇士，因为有人民自愿从军。'),
('CNV', '士师记', 7, 5, 3, '君王啊，你们要听；官长啊，你们要侧耳倾听；至于我，我要向耶和华歌唱；我要歌颂耶和华以色列的神。'),
('CNV', '士师记', 7, 5, 4, '耶和华啊，你从西珥出发的时候，你从以东地行走的日子，地震天漏，密云也滴下雨。'),
('CNV', '士师记', 7, 5, 5, '群山在耶和华面前震动；这西奈山在耶和华以色列的神面前也是这样。'),
('CNV', '士师记', 7, 5, 6, '在亚拿的儿子珊迦的时候，在雅亿的日子，大道无人行走，行路的人绕道而行。'),
('CNV', '士师记', 7, 5, 7, '以色列中的农村消失了，消失了，直到我底波拉兴起，直到我以色列的母亲兴起。'),
('CNV', '士师记', 7, 5, 8, '以色列人选择了新的神，战争就临近城门；那时四万以色列人中，竟不见有一面盾牌、一枝长矛。'),
('CNV', '士师记', 7, 5, 9, '我的心倾向以色列的官长，他们在民中甘愿牺牲自己；你们要称颂耶和华。'),
('CNV', '士师记', 7, 5, 10, '骑白驴的，坐锦垫的，和路上的行人，你们都要歌唱。'),
('CNV', '士师记', 7, 5, 11, '在打水的地方分开羊群的人发声，在那里人必歌颂耶和华公义的作为，就是他在以色列中的农村所行公义的作为；那时，耶和华的子民下到城门口。'),
('CNV', '士师记', 7, 5, 12, '兴起，兴起，底波拉！兴起，兴起，唱歌吧！兴起，巴拉！亚比挪菴的儿子，掳掠你的俘虏吧！'),
('CNV', '士师记', 7, 5, 13, '那时余剩的贵胄下来；耶和华带着勇士下到我这里来。'),
('CNV', '士师记', 7, 5, 14, '他们出自以法莲，他们的根在亚玛力人之地；有便雅悯在你的族人中跟随你，有官长从玛吉下来；有持着数点民数（“数点民数”意思不明确，或译﹕“经学家”或“指挥官”）之权杖的，从西布伦出来。'),
('CNV', '士师记', 7, 5, 15, '以萨迦的领袖与底波拉在一起；以萨迦怎样，巴拉也怎样；他们都步行下到山谷去。在流本的众溪旁，有心怀大志的。'),
('CNV', '士师记', 7, 5, 16, '你为什么坐在羊圈之中，听呼唤群畜的笛声呢？在流本的众溪旁，有心怀大志的。'),
('CNV', '士师记', 7, 5, 17, '基列人在约旦河东边居住；但人为什么居留在船上呢？亚设人在海岸坐着，在港湾居住。'),
('CNV', '士师记', 7, 5, 18, '西布伦人是敢死的民族；拿弗他利人在田野的高处，奋不顾身。'),
('CNV', '士师记', 7, 5, 19, '众王都来争战；那时迦南众王争战，在米吉多水亭的他纳争战，却没有取得银钱。'),
('CNV', '士师记', 7, 5, 20, '众星从天上争战，从它们的轨道与西西拉交战。'),
('CNV', '士师记', 7, 5, 21, '基顺河的急流把他们冲没，古河的急流、基顺河的急流，我的心哪，你要努力践踏。'),
('CNV', '士师记', 7, 5, 22, '那时马蹄沓沓，勇士急奔飞驰。'),
('CNV', '士师记', 7, 5, 23, '耶和华的使者说：‘你们要咒诅米罗斯，大大咒诅其中的居民；因为他们不来帮助耶和华，不带领勇士帮助耶和华。’'),
('CNV', '士师记', 7, 5, 24, '愿基尼人希伯的妻子雅亿，比众妇女更有福气，比住在帐棚的妇女更有福气。'),
('CNV', '士师记', 7, 5, 25, '西西拉求水，雅亿给了奶；用珍贵的盘子奉上奶酪。'),
('CNV', '士师记', 7, 5, 26, '她伸手拿着帐棚的橛子，右手拿着匠人的锤子，击打西西拉，打破他的头，粉碎他的头颅，贯穿他的鬓角。'),
('CNV', '士师记', 7, 5, 27, '西西拉在雅亿脚前屈身、仆倒、躺卧，在雅亿脚前屈身、仆倒；他在那里屈身，就在那里仆倒死亡。'),
('CNV', '士师记', 7, 5, 28, '西西拉的母亲从窗户里向外观望，从窗棂中呼叫说：‘他的战车为什么迟迟不来呢？车轮为什么行得缓慢呢？’'),
('CNV', '士师记', 7, 5, 29, '聪明的宫女回答她；她也自己回答说：'),
('CNV', '士师记', 7, 5, 30, '‘莫非他们正在分战利品？每个勇士分得一两个女子；西西拉得了彩衣作战利品，得了一两件绣花的彩衣作战利品，为我的颈项，得着绣花的彩衣作战利品吗？’'),
('CNV', '士师记', 7, 5, 31, '耶和华啊，愿你所有的仇敌都这样灭亡；愿爱他的人像太阳出现，大有能力。”于是国中太平了四十年。'),
('CNV', '士师记', 7, 6, 1, '以色列人又行了耶和华看为恶的事；耶和华就把他们交在米甸人手里七年。'),
('CNV', '士师记', 7, 6, 2, '米甸人的势力胜过以色列人；以色列人因米甸人的缘故，就为自己在山上挖穴、挖洞，建营寨。'),
('CNV', '士师记', 7, 6, 3, '每逢以色列人撒种以后，米甸人、亚玛力人和东方人都上来，欺压他们；'),
('CNV', '士师记', 7, 6, 4, '对着他们安营，毁坏那地的出产，直到迦萨一带，他们没有留下牛、羊和驴，没有给以色列人留下一点养生之物。'),
('CNV', '士师记', 7, 6, 5, '因为他们带着牲畜和帐棚上来，像蝗虫那么多；他们来的人和骆驼无数，进入境内，毁坏全地。'),
('CNV', '士师记', 7, 6, 6, '以色列人在米甸人面前，落到极卑微的地步，他们就哀求耶和华。'),
('CNV', '士师记', 7, 6, 7, '以色列人因米甸人的缘故，向耶和华呼求的时候，'),
('CNV', '士师记', 7, 6, 8, '耶和华就差派一位先知到以色列人那里，对他们说：“耶和华以色列的神这样说：‘我曾经把你们从埃及领上来，领你们出了为奴之家；'),
('CNV', '士师记', 7, 6, 9, '我曾经把你们从埃及人的手拯救出来，拯救你们脱离所有欺压你们的人的手，把他们从你们面前赶走，把他们的地赐给你们。'),
('CNV', '士师记', 7, 6, 10, '我又对你们说：我是耶和华你们的神；你们住在亚摩利人的地，不可敬畏他们的神。但你们没有听从我的话。’”'),
('CNV', '士师记', 7, 6, 11, '耶和华的使者来到，坐在俄弗拉，一棵属于亚比以谢族人约阿施的橡树下；约阿施的儿子基甸正在压酒池里打麦子，为要躲避米甸人的抢夺。'),
('CNV', '士师记', 7, 6, 12, '耶和华的使者向基甸显现，对他说：“大能的勇士啊，耶和华与你同在。”'),
('CNV', '士师记', 7, 6, 13, '基甸回答他，说：“唉，我的主，如果耶和华与我们同在，我们怎会遭遇这一切事呢？我们的列祖向我们讲述的，耶和华的一切奇事在哪里呢？他们曾说：‘耶和华不是把我们从埃及领上来吗？’现在他却抛弃了我们，把我们交在米甸人手中！”'),
('CNV', '士师记', 7, 6, 14, '耶和华转向基甸，对他说：“你靠着你这能力，去拯救以色列人脱离米甸人的手吧；我不是差派了你吗？”'),
('CNV', '士师记', 7, 6, 15, '基甸对他说：“唉，我主啊，我凭着什么拯救以色列人呢？看哪，我的家族在玛拿西支派中是最卑微的，我在我的父家是最年轻的。”'),
('CNV', '士师记', 7, 6, 16, '耶和华对他说：“因为我必与你同在，你就必击打米甸人，像击打一人一样。”'),
('CNV', '士师记', 7, 6, 17, '基甸又对他说：“如果我在你眼前蒙恩，求你给我一个凭据，证实是你与我说话。'),
('CNV', '士师记', 7, 6, 18, '求你不要离开这里，等我回来，把我的礼物带来，摆在你面前。”他回答：“我必等你回来。”'),
('CNV', '士师记', 7, 6, 19, '基甸去预备了一只山羊羔，和十公斤面粉做的无酵饼，把肉放在篮子里，把汤盛在锅中，带到橡树之下，献上给他。'),
('CNV', '士师记', 7, 6, 20, '神的使者对基甸说：“把肉和无酵饼拿出来，摆在这块磐石上，把汤倒出来。”他就这样行了。'),
('CNV', '士师记', 7, 6, 21, '耶和华的使者伸出手中的杖，杖头一触着肉和无酵饼，就有火从磐石中上来，把肉和无酵饼都烧尽了；耶和华的使者就从基甸的眼前消失了。'),
('CNV', '士师记', 7, 6, 22, '基甸看出他是耶和华的使者，就说：“哀哉，我主耶和华啊，因为我面对面看见了耶和华的使者。”'),
('CNV', '士师记', 7, 6, 23, '耶和华对他说：“你放心好了，不要怕，你必不会死。”'),
('CNV', '士师记', 7, 6, 24, '基甸就在那里给耶和华筑了一座祭坛，称为耶和华沙龙；直到今日，这坛还在亚比以谢族的俄弗拉。'),
('CNV', '士师记', 7, 6, 25, '当夜，耶和华对基甸说：“取你父亲的牛和另一头七岁大的牛来，拆毁你父亲的巴力祭坛，砍下坛旁的亚舍拉。'),
('CNV', '士师记', 7, 6, 26, '在这坚固的地方上面，你要整整齐齐为耶和华你的神筑一座祭坛，拿第二头牛作燔祭，用你砍下来的亚舍拉作柴。”'),
('CNV', '士师记', 7, 6, 27, '基甸就从他的仆人中选出了十个人，照着耶和华告诉他的行了；但因为害怕他的父家和城里的人，就不敢在日间行事，只好在晚上作了。'),
('CNV', '士师记', 7, 6, 28, '城里的人清早起来，见巴力的祭坛已被拆毁，坛旁的亚舍拉也被砍下来，并且看见那第二头牛献在新筑的祭坛上的时候，'),
('CNV', '士师记', 7, 6, 29, '就彼此说：“谁作了这事呢？”他们追查寻访之后，就说：“是约阿施的儿子基甸作的。”'),
('CNV', '士师记', 7, 6, 30, '城里的人对约阿施说：“把你的儿子领出来，把他处死，因为他拆毁了巴力的祭坛，砍下了坛旁的亚舍拉。”'),
('CNV', '士师记', 7, 6, 31, '约阿施对所有站着攻击他的人说：“你们要为巴力辩护吗？或是你们要救他呢？谁为他辩护，到早晨就必死亡。巴力若是神，有人拆毁了他的祭坛，就让他为自己辩护吧。”'),
('CNV', '士师记', 7, 6, 32, '因此，当日基甸被称为耶路．巴力，意思说：他拆毁了巴力的祭坛，让巴力与他争辩吧。'),
('CNV', '士师记', 7, 6, 33, '那时，米甸人、亚玛力人和东方人，都聚集起来，过了河，在耶斯列平原安营。'),
('CNV', '士师记', 7, 6, 34, '耶和华的灵降在基甸身上，他就吹角；亚比以谢族都应召来跟从他。'),
('CNV', '士师记', 7, 6, 35, '他派使者到玛拿西全地去，玛拿西人也都应召来跟从他；他又派使者到亚设、西布伦、拿弗他利去，他们也都上来与他们会合。'),
('CNV', '士师记', 7, 6, 36, '基甸对神说：“如果你按着你所说的，要藉着我的手拯救以色列人；'),
('CNV', '士师记', 7, 6, 37, '看哪，我要把一团新剪的羊毛放在禾场上；露水若是单单落在羊毛上，而全地都是干的，我就知道你要照着你所说的，藉着我的手拯救以色列了。”'),
('CNV', '士师记', 7, 6, 38, '第二天，基甸清早起来，情形果然是这样；他把羊毛一挤，就从羊毛中挤出一满盆的露水来。'),
('CNV', '士师记', 7, 6, 39, '基甸又对神说：“求你不要向我发怒，我要再说这一次；求你让我把羊毛再试一试，但愿单单羊毛是干的，而全地都有露水。”'),
('CNV', '士师记', 7, 6, 40, '那一夜，神也这样行了；单单羊毛是干的，全地都有露水。'),
('CNV', '士师记', 7, 7, 1, '耶路．巴力，就是基甸，和所有与他在一起的人，清早起来，在哈律泉旁安营；米甸营就在他们的北面，靠近摩利山冈的平原上。'),
('CNV', '士师记', 7, 7, 2, '耶和华对基甸说：“与你在一起的人太多，我不能把米甸人交在你们手中，免得以色列人向我自夸：‘是我们自己的手救了我们。’'),
('CNV', '士师记', 7, 7, 3, '现在你要向众民宣告：‘害怕战栗的，可以回去，离开基列山。’”于是众民中有二万二千人回去，只剩下一万人。'),
('CNV', '士师记', 7, 7, 4, '耶和华对基甸说：“人还是太多，你要领他们下到水旁去，我要在那里为你试验他们。我指着谁对你说：‘这人可以与你同去’，他就可以与你同去；我指着谁对你说：‘这人不可以与你同去’，他就不可以与你同去。”'),
('CNV', '士师记', 7, 7, 5, '于是基甸带他们下到水边去；耶和华对基甸说：“用舌头舔水，像狗舔水的，你要把他们安置在一处；屈膝跪下喝水的，也要把他们安置在一处。”'),
('CNV', '士师记', 7, 7, 6, '用手捧到嘴边舔水的，总数共有三百人；其余的人都屈膝跪下喝水。'),
('CNV', '士师记', 7, 7, 7, '耶和华对基甸说：“我要用这舔水的三百人拯救你们，把米甸人交在你们的手里，所有其他的人都可以各回自己的地方去。”'),
('CNV', '士师记', 7, 7, 8, '于是众民手里拿着食物和号角；所有其他的以色列人，基甸都打发他们各回自己的帐棚去，只留下这三百人。当时米甸营就在他们下面的平原里。'),
('CNV', '士师记', 7, 7, 9, '当夜，耶和华对基甸说：“起来，下去攻营，因为我已经把他们交在你手里了。'),
('CNV', '士师记', 7, 7, 10, '如果你害怕一人下去，可以带着你的童仆普拉一同下到营地那里去；'),
('CNV', '士师记', 7, 7, 11, '你要听听他们说什么，然后你的手就必坚强起来，有胆量下去攻营了。”于是基甸带着他的童仆普拉一同下去，到营中驻军的边缘。'),
('CNV', '士师记', 7, 7, 12, '那时米甸人、亚玛力人和所有的东方人，都散布在平原上，好像蝗虫那么多；他们的骆驼无数，好像海边的沙那么多。'),
('CNV', '士师记', 7, 7, 13, '基甸到了，就听见一个人正在把他的梦告诉他的同伴，说：“我作了一个梦，梦见一个大麦饼滚入米甸营中，到了帐幕，把帐幕撞倒，帐幕就翻转朝上了。”'),
('CNV', '士师记', 7, 7, 14, '他的同伴回答：“这不是别的，这是以色列人约阿施的儿子基甸的刀；神已经把米甸和全营交在他手中了。”'),
('CNV', '士师记', 7, 7, 15, '基甸听见了这梦的叙述和梦的讲解，就敬拜神；然后返回以色列营中，说：“起来，因为耶和华已经把米甸的军队交在你们手里了。”'),
('CNV', '士师记', 7, 7, 16, '于是他把三百人分作三队，把角和空瓶交在各人手里，又把火把放在瓶里。'),
('CNV', '士师记', 7, 7, 17, '然后对他们说：“你们要看着我，也要照样行事。注意！我到了营的边缘，我怎样行事，你们也要怎样行事。'),
('CNV', '士师记', 7, 7, 18, '我和所有与我在一起的人吹角的时候，你们也要在全营的四周吹角，喊叫说：‘为耶和华！为基甸！’”'),
('CNV', '士师记', 7, 7, 19, '基甸和所有与他在一起的一百人，在半夜三更的起初，换更的时候，来到了营的边缘，就吹起角来，打破手中的瓦瓶。'),
('CNV', '士师记', 7, 7, 20, '三队的人就都吹角，打破瓦瓶，左手紧握着火把，右手紧握着角不住地吹，并且喊叫说：“耶和华和基甸的刀！”'),
('CNV', '士师记', 7, 7, 21, '他们在营的四周各站在自己的位置；全营的人都乱跑，他们一面叫喊，一面逃跑。'),
('CNV', '士师记', 7, 7, 22, '三百人吹那三百枝角的时候，耶和华使全营的人用刀互相击杀，然后他们向着西利拉逃到伯．哈示他，直到靠近他巴的亚伯．米何拉河边。'),
('CNV', '士师记', 7, 7, 23, '以色列人就从拿弗他利、亚设和玛拿西全地被召来，追赶米甸人。'),
('CNV', '士师记', 7, 7, 24, '基甸派遣了使者走遍以法莲山地，说：“你们要下来迎战米甸人，在他们前面把守约旦河的渡口，直到伯．巴拉。”于是以法莲的人都被召来，把守约旦河的渡口，直到伯．巴拉。'),
('CNV', '士师记', 7, 7, 25, '他们捉住了米甸人的两个首领：俄立和西伊伯；把俄立杀在俄立磐石上，把西伊伯杀在西伊伯榨酒池那里；然后追赶米甸人，又把俄立和西伊伯的人头带到约旦河对岸，基甸那里。'),
('CNV', '士师记', 7, 8, 1, '以法莲人对基甸说：“你去与米甸人争战的时候，没有召我们同去，你为什么这样待我们呢？”他们就与他激烈地争辩起来。'),
('CNV', '士师记', 7, 8, 2, '基甸对他们说：“我所行的怎能比得上你们呢？在以法莲拾取剩下的葡萄，不是比在亚比以谢收摘的葡萄更好吗？'),
('CNV', '士师记', 7, 8, 3, '神已经把米甸人的两个首领：俄立和西伊伯，交在你们的手里了；我所行的怎能与你们相比呢？”基甸说了这话，他们的怒气就平息了。'),
('CNV', '士师记', 7, 8, 4, '基甸来到约旦河，就过了河；他和与他在一起的三百人虽然都很疲乏，仍然追赶敌人。'),
('CNV', '士师记', 7, 8, 5, '基甸对疏割人说：“求你们把几个饼给跟随我的人吃，因为他们疲乏了，我还要继续追赶米甸人和两个王西巴和撒慕拿。”'),
('CNV', '士师记', 7, 8, 6, '疏割人的首领回答：“西巴和撒慕拿现在不是已经在你的手里吗？我们应该把饼送给你的军队吃吗？”'),
('CNV', '士师记', 7, 8, 7, '基甸说：“好吧，耶和华把西巴和撒慕拿交在我手里的时候，我就必用野地的荆棘鞭打你们的身体。”'),
('CNV', '士师记', 7, 8, 8, '基甸从那里上到毗努伊勒，也向他们说了同样的话；毗努伊勒人回答他也像疏割人回答的一样。'),
('CNV', '士师记', 7, 8, 9, '他亦对毗努伊勒人说：“我平平安安回来的时候，我必拆毁这座望楼。”'),
('CNV', '士师记', 7, 8, 10, '那时，西巴和撒慕拿正在加各，与他们在一起的军队约有一万五千人，就是东方人全营剩下的，因为有十二万持刀的已经倒下了。'),
('CNV', '士师记', 7, 8, 11, '基甸就从挪巴和约比哈东面，顺着住帐棚的人的路上去；在敌军以为安全而不戒备的时候，击败了敌军。'),
('CNV', '士师记', 7, 8, 12, '西巴和撒慕拿逃跑；基甸追赶他们，捉住了米甸人的两个王西巴和撒慕拿，使全军都惊惶。'),
('CNV', '士师记', 7, 8, 13, '约阿施的儿子基甸从战场沿着希列斯的山坡回来，'),
('CNV', '士师记', 7, 8, 14, '捉住了疏割人中的一个青年人，查问他；他就把疏割的首领和长老的名字写给他，共七十七人。'),
('CNV', '士师记', 7, 8, 15, '基甸到了疏割人那里，就说：“你看，西巴和撒慕拿，你们为了他们曾经讥笑我说：‘西巴和撒慕拿现在不是在你的手里吗？我们应该把饼送给你那些疲乏的人吃吗？’”'),
('CNV', '士师记', 7, 8, 16, '于是拿住那城的长老，又拿起野地的荆棘，用荆棘把疏割人教训了一顿；'),
('CNV', '士师记', 7, 8, 17, '又拆毁了毗努伊勒的望楼，杀死了那城里的人。'),
('CNV', '士师记', 7, 8, 18, '基甸问西巴和撒慕拿：“你们在他泊山上所杀的人，是什么模样的人？”他们回答：“他们像你一样，每一个都像王子的模样。”'),
('CNV', '士师记', 7, 8, 19, '基甸说：“他们是我的兄弟，是我母亲的儿子；我指着永活的耶和华起誓，如果你们从前让他们存活，我现在就不杀你们了。”'),
('CNV', '士师记', 7, 8, 20, '于是对他的长子益帖说：“起来，把他们杀了吧。”但是那孩子不敢拔刀，只是害怕，因为他还是个孩子。'),
('CNV', '士师记', 7, 8, 21, '西巴和撒慕拿说：“你亲自起来杀我们吧；因为人怎样，他的力量也怎样。”于是基甸起来，把西巴和撒慕拿杀了，拿了他们骆驼颈项上的月牙圈。'),
('CNV', '士师记', 7, 8, 22, '以色列人对基甸说：“你既然拯救我们脱离了米甸人的手，求你和你的子孙统治我们。”'),
('CNV', '士师记', 7, 8, 23, '基甸回答他们：“我不统治你们，我的子孙也不统治你们，唯有耶和华统治你们。”'),
('CNV', '士师记', 7, 8, 24, '基甸又对他们说：“我有一个要求：请把你们各人夺得的耳环给我。”原来敌人都戴金耳环，因为他们是以实玛利人。'),
('CNV', '士师记', 7, 8, 25, '他们回答：“我们愿意给你。”于是铺开一件外衣，各人把夺得的耳环丢在上面。'),
('CNV', '士师记', 7, 8, 26, '基甸所要的金耳环，共重约二十公斤金子，此外还有米甸王身上的月牙圈、耳坠和紫红色的衣服，另外还有骆驼颈项上的链子。'),
('CNV', '士师记', 7, 8, 27, '基甸用这些金子做了一个以弗得，安置在他的城俄弗拉；后来以色列众人都在那里随从以弗得行了邪淫，因此这就成了基甸和他全家的网罗。'),
('CNV', '士师记', 7, 8, 28, '这样，米甸人在以色列人面前就被制伏了，不能再抬起头来；基甸在世的日子，国中太平了四十年。'),
('CNV', '士师记', 7, 8, 29, '约阿施的儿子耶路．巴力回去，住在自己家里。'),
('CNV', '士师记', 7, 8, 30, '基甸有七十个儿子，都是他亲生的，因为他有很多妻子。'),
('CNV', '士师记', 7, 8, 31, '他在示剑的妾，也给他生了一个儿子，他给他起名叫亚比米勒。'),
('CNV', '士师记', 7, 8, 32, '约阿施的儿子基甸寿数满足而死，埋葬在亚比以谢族的俄弗拉，在他父亲约阿施的坟墓里。'),
('CNV', '士师记', 7, 8, 33, '基甸死了以后，以色列人又转去随从众巴力，行邪淫，并且以巴力．比利土作他们的神。'),
('CNV', '士师记', 7, 8, 34, '以色列人忘记了耶和华他们的神，就是曾经拯救他们脱离四围仇敌之手的那位；'),
('CNV', '士师记', 7, 8, 35, '也没有照着基甸向以色列人所施的一切恩惠，恩待耶路．巴力，就是基甸的家。'),
('CNV', '士师记', 7, 9, 1, '耶路．巴力的儿子亚比米勒，到示剑去见他的众母舅，对他们和他母亲的全体族人说：'),
('CNV', '士师记', 7, 9, 2, '“请你们给示剑的众人说：‘是耶路．巴力的众子七十人都统治你们好呢？还是一个人统治你们好呢？’你们也要记得我是你们的骨肉。”'),
('CNV', '士师记', 7, 9, 3, '他的众母舅就把这一切话为他说给示剑的众人听；他们的心都倾向亚比米勒，因为他们说：“他本是我们的亲族。”'),
('CNV', '士师记', 7, 9, 4, '他们就从巴力．比利土的庙里，取了八百克银子给亚比米勒，亚比米勒用这些银子雇了一些无赖流氓，那些人就跟随了他。'),
('CNV', '士师记', 7, 9, 5, '他回到俄弗拉他父亲的家，把自己的兄弟，耶路．巴力的众子七十人，都杀在一块石头上；只剩下耶路．巴力的小儿子约坦，因为他藏了起来。'),
('CNV', '士师记', 7, 9, 6, '示剑的众人和伯特米罗人都聚集起来，到示剑橡树旁的望楼那里，立亚比米勒为王。'),
('CNV', '士师记', 7, 9, 7, '有人把这事告诉了约坦，约坦就去，站在基利心山顶上，高声向他们呼喊，说：“示剑人哪，你们要听我的话，神也就听你们的话。'),
('CNV', '士师记', 7, 9, 8, '有一次，众树要去膏立一个王统治它们，就对橄榄树说：‘请你作王统治我们吧。’'),
('CNV', '士师记', 7, 9, 9, '橄榄树对它们说：‘我怎可以放弃生产人用来荣耀神和尊崇人的油，飘摇在众树之上呢？’'),
('CNV', '士师记', 7, 9, 10, '众树对无花果树说：‘请你来作王统治我们吧。’'),
('CNV', '士师记', 7, 9, 11, '无花果树对它们说：‘我怎可以放弃结出我的甜美果子，飘摇在众树之上呢？’'),
('CNV', '士师记', 7, 9, 12, '众树对葡萄树说：‘请你来作王统治我们吧。’'),
('CNV', '士师记', 7, 9, 13, '葡萄树对它们说：‘我怎可以放弃生产那使神和世人都喜乐的新酒，飘摇在众树之上呢？’'),
('CNV', '士师记', 7, 9, 14, '于是众树都对荆棘说：‘请你来作王统治我们吧。’'),
('CNV', '士师记', 7, 9, 15, '荆棘对众树说：‘如果你们真诚地膏立我作王统治你们，就要来，投靠在我的荫下；否则，火必从荆棘里出来，吞灭黎巴嫩的香柏树。’'),
('CNV', '士师记', 7, 9, 16, '“现在你们立亚比米勒为王，你们若是诚实和正直，如果你们善待耶路．巴力和他的家，照着他手所作的待他；'),
('CNV', '士师记', 7, 9, 17, '我父亲从前冒死为你们争战，把你们从米甸人手中救了出来；'),
('CNV', '士师记', 7, 9, 18, '今日你们竟起来攻击我的父家，在一块石头上杀了他七十个儿子，又立了他的婢女所生的儿子亚比米勒作示剑人的王，因为他原是你们的亲族。'),
('CNV', '士师记', 7, 9, 19, '今日你们若是按着诚实和正直待耶路．巴力和他的家，你们就可以因亚比米勒得喜乐，亚比米勒也可以因你们得喜乐。'),
('CNV', '士师记', 7, 9, 20, '若不是这样，愿火从亚比米勒出来，吞灭示剑人和伯特米罗人；又愿火从示剑人和伯特米罗人出来，吞灭亚比米勒。”'),
('CNV', '士师记', 7, 9, 21, '接着约坦就逃跑了；他逃到比珥去，住在那里，躲避他的兄弟亚比米勒。'),
('CNV', '士师记', 7, 9, 22, '亚比米勒治理以色列人三年。'),
('CNV', '士师记', 7, 9, 23, '神差派邪恶的灵来到亚比米勒与示剑人中间，示剑人就背弃了亚比米勒。'),
('CNV', '士师记', 7, 9, 24, '这是要报复对耶路．巴力七十个儿子的暴行，把流他们血的罪归到他们的兄弟亚比米勒身上，就是那杀害他们的；也归到示剑人身上，就是那些帮助亚比米勒去杀他自己的兄弟的。'),
('CNV', '士师记', 7, 9, 25, '示剑人在山顶上设下埋伏，路过他们那里的，他们都劫掠；有人把这事告诉亚比米勒。'),
('CNV', '士师记', 7, 9, 26, '那时，以别的儿子迦勒与他的兄弟都来了，到示剑去，示剑人竟信任他。'),
('CNV', '士师记', 7, 9, 27, '他们出到田间去，收取葡萄，榨酒，举行庆祝会，进入他们的神庙吃喝，并且咒诅亚比米勒。'),
('CNV', '士师记', 7, 9, 28, '以别的儿子迦勒说：“亚比米勒是谁？示剑是谁？竟要我们服事他呢？他不是耶路．巴力的儿子吗？他的副官不是西布勒吗？你们要服事示剑的始祖哈抹的后人啊；我们为什么要服事亚比米勒呢？'),
('CNV', '士师记', 7, 9, 29, '但愿这些人民都归在我手下，我好把亚比米勒除掉。”迦勒又对亚比米勒说：“增添你的军队出来吧！”'),
('CNV', '士师记', 7, 9, 30, '那城的首长西布勒听了以别的儿子迦勒的话，他的怒气就发作，'),
('CNV', '士师记', 7, 9, 31, '秘密差派使者去见亚比米勒，说：“以别的儿子迦勒和他的兄弟已经到了示剑，他们正在煽动（“煽动”意思不明确，或译﹕“围困”）那城的人反叛你。'),
('CNV', '士师记', 7, 9, 32, '现在，你和与你在一起的人，要在夜间起来，在野地埋伏。'),
('CNV', '士师记', 7, 9, 33, '到了早晨，太阳出来的时候，你就要起来攻城；你要注意，迦勒和与他在一起的人出来对抗你的时候，你就把握机会对付他们。”'),
('CNV', '士师记', 7, 9, 34, '于是亚比米勒和与他在一起的人，都在夜间起来，分作四队，埋伏着等候示剑人。'),
('CNV', '士师记', 7, 9, 35, '以别的儿子迦勒出去，站在城门口；亚比米勒和与他在一起的人，从埋伏的地方起来。'),
('CNV', '士师记', 7, 9, 36, '迦勒看见了那些人，就对西布勒说：“你看，有人从山顶上下来。”西布勒说：“你看见山的影子以为是人。”'),
('CNV', '士师记', 7, 9, 37, '迦勒又说：“看哪，有人从高地下来，又有一队从米恶尼尼橡树的路径而来。”'),
('CNV', '士师记', 7, 9, 38, '西布勒对他说：“你曾经说过：‘亚比米勒是谁，竟要我们服事他呢？’现在你说这话的嘴在哪里呢？这不是你轻视的人吗？现在请你出去与他们交战吧。”'),
('CNV', '士师记', 7, 9, 39, '于是迦勒在示剑人面前出去，与亚比米勒争战。'),
('CNV', '士师记', 7, 9, 40, '亚比米勒追赶迦勒，迦勒在他面前逃跑，直到城门口，有很多受伤的人仆倒。'),
('CNV', '士师记', 7, 9, 41, '亚比米勒住在亚鲁玛；西布勒把迦勒和他的兄弟赶走，不许他们住在示剑。'),
('CNV', '士师记', 7, 9, 42, '次日，城中众人出到田间去，有人把这事告诉亚比米勒。'),
('CNV', '士师记', 7, 9, 43, '亚比米勒就把他的人分作三队，埋伏在田间；他在那里观看，见有人从城里出来，就起来攻击他们，把他们击杀了。'),
('CNV', '士师记', 7, 9, 44, '亚比米勒和与他在一起的一队人忽然冲过去，站在城门口；其他两队人也冲出来攻打所有在田间的人，把他们击杀了。'),
('CNV', '士师记', 7, 9, 45, '那一天，亚比米勒整天攻打那城，把城攻下了，杀了城中的众人；把城拆毁，又撒上盐。'),
('CNV', '士师记', 7, 9, 46, '示剑楼的众人听见了这事，就逃入伊勒．比利土庙的地穴里。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '士师记', 7, 9, 47, '有人告诉亚比米勒，说：“示剑楼所有的人都聚集在一起。”'),
('CNV', '士师记', 7, 9, 48, '亚比米勒和与他在一起的人都上了撒们山；亚比米勒手里拿着斧子，砍下一根树枝，拿起来放在自己的肩头上，然后对与他在一起的人说：“你们看我作什么，你们也要赶快照样作。”'),
('CNV', '士师记', 7, 9, 49, '于是众人也各自砍下一根树枝，跟随着亚比米勒，把树枝放在地穴上，放火烧了地穴，以致示剑楼的人都死了，男女约有一千人。'),
('CNV', '士师记', 7, 9, 50, '后来亚比米勒到提备斯去，安营攻打提备斯，攻取了那城。'),
('CNV', '士师记', 7, 9, 51, '城中有一座坚固的城楼；那城所有的人，无论男女，都逃到那里去，关上门，上了楼顶。'),
('CNV', '士师记', 7, 9, 52, '亚比米勒到了城楼前，攻打城楼；他走近城楼门口，要用火焚烧。'),
('CNV', '士师记', 7, 9, 53, '有一个妇人把一块上磨石抛在亚比米勒的头上，打破了他的头盖骨。'),
('CNV', '士师记', 7, 9, 54, '他急忙呼喊替他拿兵器的少年人，对他说：“拔出你的刀来，把我杀死吧。免得人讲论我说：‘他被一个妇人所杀。’”于是那少年人把他刺透，他就死了。'),
('CNV', '士师记', 7, 9, 55, '以色列人看见亚比米勒死了，就各回自己的地方去了。'),
('CNV', '士师记', 7, 9, 56, '这样，神报应了亚比米勒向他父亲所行的恶事，就是他杀了自己的兄弟七十个人。'),
('CNV', '士师记', 7, 9, 57, '神也把示剑人的一切恶事，都报应在他们的头上；耶路．巴力的儿子约坦的咒诅，也归到他们身上。'),
('CNV', '士师记', 7, 10, 1, '亚比米勒之后，有以萨迦人朵多的孙子，普瓦的儿子陀拉，兴起拯救以色列人；他住在以法莲山地的沙密。'),
('CNV', '士师记', 7, 10, 2, '陀拉治理以色列人二十三年，就死了，埋葬在沙密。'),
('CNV', '士师记', 7, 10, 3, '在他之后，有基列人睚珥兴起治理以色列人二十二年。'),
('CNV', '士师记', 7, 10, 4, '他有三十个儿子，骑着三十头驴驹；他们有三十座城，叫作哈倭特．睚珥，直到今日都是在基列地。'),
('CNV', '士师记', 7, 10, 5, '睚珥死了以后，就埋葬在加们。'),
('CNV', '士师记', 7, 10, 6, '以色列人又行了耶和华看为恶的事，服事众巴力和亚斯他录，以及亚兰的神、西顿的神、摩押的神、亚扪人的神、非利士人的神；他们离弃了耶和华，不再服事他。'),
('CNV', '士师记', 7, 10, 7, '耶和华的怒气向以色列人发作，就把他们交在非利士人的手中和亚扪人的手中。'),
('CNV', '士师记', 7, 10, 8, '从那一年起，他们就迫害欺压以色列人，就是所有在约旦河东边，住在亚摩利人之地的以色列人，共十八年。'),
('CNV', '士师记', 7, 10, 9, '亚扪人又渡过约旦河去攻打犹大、便雅悯和以法莲家，以色列人就非常困苦。'),
('CNV', '士师记', 7, 10, 10, '以色列人向耶和华哀求，说：“我们得罪了你，因为我们离弃了我们的神，服事众巴力。”'),
('CNV', '士师记', 7, 10, 11, '耶和华对以色列人说：“我不是曾经拯救你们脱离埃及人、亚摩利人、亚扪人和非利士人吗？'),
('CNV', '士师记', 7, 10, 12, '西顿人、亚玛力人、马云人也都压迫你们；你们向我哀求，我也拯救你们脱离他们的手。'),
('CNV', '士师记', 7, 10, 13, '你们竟离弃了我，服事别的神，因此我不再拯救你们了。'),
('CNV', '士师记', 7, 10, 14, '你们去向你们拣选的神呼求吧！让他们在你们遭遇患难的时候拯救你们吧。”'),
('CNV', '士师记', 7, 10, 15, '以色列人对耶和华说：“我们犯了罪了，你任意对待我们吧；只求你今日拯救我们。”'),
('CNV', '士师记', 7, 10, 16, '以色列人就从他们中间除去外族人的神，事奉耶和华；耶和华的心因以色列人所受的患难，就很着急。'),
('CNV', '士师记', 7, 10, 17, '当时亚扪人聚集起来，在基列安营；以色列人也聚集，在米斯巴安营。'),
('CNV', '士师记', 7, 10, 18, '基列的人民和众领袖彼此说：“谁先去攻打亚扪人，谁就可以作基列所有居民的首领。'),
('CNV', '士师记', 7, 11, 1, '基列人耶弗他是个英勇的战士；他是个妓女的儿子；耶弗他是基列所生的。'),
('CNV', '士师记', 7, 11, 2, '基列的妻子也给他生了几个儿子。他妻子的儿子长大了，就把耶弗他赶出去，对他说：“你不可以在我们的父家继承产业，因为你是另一个妇人的儿子。”'),
('CNV', '士师记', 7, 11, 3, '耶弗他就从他的兄弟面前逃跑，住在陀伯地；有些无赖聚集到他那里，与他一起出入。'),
('CNV', '士师记', 7, 11, 4, '过了些日子，亚扪人与以色列人争战。'),
('CNV', '士师记', 7, 11, 5, '亚扪人与以色列人争战的时候，基列的众长老就去，把耶弗他从陀伯请回来。'),
('CNV', '士师记', 7, 11, 6, '他们对耶弗他说：“请你来作我们的统帅，我们好攻打亚扪人。”'),
('CNV', '士师记', 7, 11, 7, '耶弗他对基列的长老说：“从前你们不是恨我，赶逐我离开我的父家吗？现在你们遭遇患难的时候，为什么到我这里来呢？”'),
('CNV', '士师记', 7, 11, 8, '基列的长老对耶弗他说：“现在我们回到你这里来，是要你与我们一同回去，与亚扪人争战，你要作我们基列所有居民的首领。”'),
('CNV', '士师记', 7, 11, 9, '耶弗他对基列的长老说：“如果你们带我回去，攻打亚扪人，耶和华把他们交在我面前，那么我就可以作你们的首领吗？”'),
('CNV', '士师记', 7, 11, 10, '基列的长老对耶弗他说：“有耶和华在我们中间作证，我们必定照着你的话行。”'),
('CNV', '士师记', 7, 11, 11, '于是耶弗他与基列的长老一同回去了，众人就立耶弗他作他们的首领，作他们的统帅；耶弗他在米斯巴，在耶和华面前，把自己的一切话都说了出来。'),
('CNV', '士师记', 7, 11, 12, '耶弗他派遣使者去见亚扪人的王，说：“我跟你有什么关系呢？你竟到我这里来攻打我的土地呢？”'),
('CNV', '士师记', 7, 11, 13, '亚扪人的王对耶弗他的使者说：“因以色列人从埃及上来的时候，夺了我的土地，从亚嫩河到雅博河，直到约旦河；现在你要把它和和平平地交还。”'),
('CNV', '士师记', 7, 11, 14, '耶弗他又再派使者去见亚扪人的王，'),
('CNV', '士师记', 7, 11, 15, '对他说：“耶弗他这样说：‘以色列人并没有夺取过摩押地和亚扪人的土地。'),
('CNV', '士师记', 7, 11, 16, '以色列人从埃及上来的时候，是走过旷野到红海，到了加低斯；'),
('CNV', '士师记', 7, 11, 17, '就派遣使者去见以东王，说：求你让我们经过你的领土。以东王却不答应；又派遣使者去见摩押王，摩押王也不肯；以色列人就住在加低斯。'),
('CNV', '士师记', 7, 11, 18, '以后，他们走过旷野，绕过以东地和摩押地，到了摩押地的东边，在亚嫩河那边安营；他们并没有进入摩押境内，因为亚嫩河是摩押的边界。'),
('CNV', '士师记', 7, 11, 19, '以色列人又派遣使者去见亚摩利人的王西宏，就是希实本王，对他说：求你让我们经过你的领土，到我们自己的地方去。'),
('CNV', '士师记', 7, 11, 20, '西宏却不信任以色列人，不让他们经过他的境界；西宏聚集了他所有的人民，在雅杂安营，与以色列人争战。'),
('CNV', '士师记', 7, 11, 21, '耶和华以色列的神，把西宏和他所有的人民都交在以色列人手中，以色列人击杀了他们，夺取了住在那地的亚摩利人的全地，'),
('CNV', '士师记', 7, 11, 22, '占领了亚摩利人四周的境界，从亚嫩河到雅博河，从旷野直到约旦河。'),
('CNV', '士师记', 7, 11, 23, '现在耶和华以色列的神，已经把亚摩利人从他的子民以色列人面前赶走了，你竟要占有这地吗？'),
('CNV', '士师记', 7, 11, 24, '你不是应占有你的神基抹要你占有的地吗？我们不是应占有耶和华我们的神，从我们面前赶走的人的一切地吗？'),
('CNV', '士师记', 7, 11, 25, '现在难道你比摩押王西拨的儿子巴勒还强吗？他曾经与以色列人争竞吗？或是与以色列人交战过吗？'),
('CNV', '士师记', 7, 11, 26, '以色列人住在希实本和属希实本的村镇，亚罗珥和亚罗珥的村镇，以及亚嫩河沿岸的一切城市，已经有三百年了；在这时期内，你们为什么没有夺回这些地方呢？'),
('CNV', '士师记', 7, 11, 27, '我没有得罪你，你竟恶待我，攻打我；愿审判者耶和华今日在以色列人和亚扪人中间，判断是非。’”'),
('CNV', '士师记', 7, 11, 28, '但亚扪人的王不听从耶弗他差派人去对他所说的话。'),
('CNV', '士师记', 7, 11, 29, '那时耶和华的灵临到耶弗他身上，他就经过基列和玛拿西，经过基列的米斯巴，又从基列的米斯巴去到亚扪人那里。'),
('CNV', '士师记', 7, 11, 30, '耶弗他向耶和华许愿，说：“如果你真的把亚扪人交在我手里，'),
('CNV', '士师记', 7, 11, 31, '我从亚扪人那里平平安安回来的时候，无论谁先从我的家门出来迎接我，他就必归耶和华，我也必把他当作燔祭。”'),
('CNV', '士师记', 7, 11, 32, '于是耶弗他去到亚扪人那里攻打他们，耶和华把他们交在他手里。'),
('CNV', '士师记', 7, 11, 33, '于是他从亚罗珥开始击杀他们，去到米匿，直到亚备勒．基拉明，共二十座城，是一场大击杀；这样，亚扪人就在以色列人面前被制伏了。'),
('CNV', '士师记', 7, 11, 34, '耶弗他回米斯巴去，到了自己的家，不料，他的女儿拿着鼓、跳着舞，出来迎接他；她是耶弗他的独生女，除她以外，耶弗他没有其他的儿女。'),
('CNV', '士师记', 7, 11, 35, '耶弗他看见了她，就撕裂自己的衣服，说：“啊！我的女儿啊，你真使我忧愁，你叫我太作难了；因为我已经向耶和华开过口许愿，我不能收回。”'),
('CNV', '士师记', 7, 11, 36, '她对他说：“我的父亲啊，你既然向耶和华开过口许了愿，就照着你口里所说的向我行吧！因为耶和华已经在你的仇敌亚扪人身上，为你报了仇。”'),
('CNV', '士师记', 7, 11, 37, '她又对自己的父亲说：“请你准我这件事吧：给我两个月时间，让我和我的同伴去漫游山间，为我的童贞哀哭。”'),
('CNV', '士师记', 7, 11, 38, '耶弗他说：“你去吧！”就让她离去两个月；她就带着她的同伴去了，在山上为她的童贞哀哭。'),
('CNV', '士师记', 7, 11, 39, '两个月后，她回到她的父亲那里，她父亲就照他所许的愿向她行了。她没有与男人同过房。以后，在以色列中有个惯例：'),
('CNV', '士师记', 7, 11, 40, '以色列的女子年年都去哀悼基列人耶弗他的女儿，每年四日。'),
('CNV', '士师记', 7, 12, 1, '以法莲人聚集起来，过河到了撒分，对耶弗他说：“你过去攻打亚扪人的时候，为什么没有召我们与你同去呢？我们要用火烧掉你和你的房屋。”'),
('CNV', '士师记', 7, 12, 2, '耶弗他对他们说：“我和我的人民跟亚扪人激烈争战的时候，我曾经呼求你们，你们却没有来救我们脱离他们的手。'),
('CNV', '士师记', 7, 12, 3, '我见你们不来拯救我，我就拚命上去攻击亚扪人，耶和华就把他们交在我的手里。你们今日为什么上我这里来攻打我呢？”'),
('CNV', '士师记', 7, 12, 4, '于是耶弗他召集了基列所有的人，与以法莲人争战；基列人击杀了以法莲人，因为以法莲人曾经说过：“你们基列人在以法莲和玛拿西中间，不过是以法莲逃亡的人罢了。”'),
('CNV', '士师记', 7, 12, 5, '基列人占领约旦河的各渡口，不容以法莲人过去。如果以法莲逃亡的人说：“让我过去吧。”基列人就问他：“你是以法莲人吗？”如果他说：“不是。”'),
('CNV', '士师记', 7, 12, 6, '基列人就对他说：“请说‘示播列’。”以法莲人因为发不出准确的字音，就说成“西播列”；基列人就把他捉住，在约旦河的渡口那里杀了；那时以法莲人死了四万二千人。'),
('CNV', '士师记', 7, 12, 7, '耶弗他治理以色列人共六年；基列人耶弗他死了以后，埋葬在基列其中的一座城里。'),
('CNV', '士师记', 7, 12, 8, '耶弗他之后，有伯利恒人以比赞治理以色列人。'),
('CNV', '士师记', 7, 12, 9, '他有三十个儿子，三十个女儿；女儿都嫁到外面去，又给他的儿子从外面娶了三十个女子作妻子。他治理以色列人共七年。'),
('CNV', '士师记', 7, 12, 10, '以比赞死了，就埋葬在伯利恒。'),
('CNV', '士师记', 7, 12, 11, '以比赞之后，有西布伦人以伦，治理以色列人共十年。'),
('CNV', '士师记', 7, 12, 12, '西布伦人以伦死了以后，就埋葬在西布伦地的亚雅仑。'),
('CNV', '士师记', 7, 12, 13, '以伦之后，有比拉顿人希列的儿子押顿治理以色列人。'),
('CNV', '士师记', 7, 12, 14, '他有四十个儿子，三十个孙子，骑着七十头驴驹；押顿治理以色列人共八年。'),
('CNV', '士师记', 7, 12, 15, '比拉顿人希列的儿子押顿死了，埋葬在以法莲地，就是在亚玛力人的山地。'),
('CNV', '士师记', 7, 13, 1, '以色列人又行了耶和华看为恶的事，耶和华就把他们交在非利士人手中四十年。'),
('CNV', '士师记', 7, 13, 2, '那时有一个琐拉人，是属于但支派的，名叫玛挪亚；他的妻子不能生育，没有孩子。'),
('CNV', '士师记', 7, 13, 3, '耶和华的使者向那妇人显现，对她说：“你向来不能生育，没有孩子，现在你必要怀孕，生一个儿子。'),
('CNV', '士师记', 7, 13, 4, '现在你要谨慎，清酒或烈酒都不可喝，各样不洁的东西也不可吃。'),
('CNV', '士师记', 7, 13, 5, '看哪！你必怀孕，生一个儿子；不可用剃刀剃他的头，这孩子从在母腹开始就归神作拿细耳人；他必拯救以色列人脱离非利士人的手。”'),
('CNV', '士师记', 7, 13, 6, '妇人就回去，告诉她的丈夫说：“有一位神人到我这里来，他的容貌像神使者的容貌，非常可畏，我没有问他从哪里来，他也没有告诉我他的名字。'),
('CNV', '士师记', 7, 13, 7, '他对我说：‘你必要怀孕，生一个儿子；现在清酒或烈酒你都不可喝，各样不洁的东西你也不可吃，因为这孩子从在母腹开始，一直到死，都必归耶和华作拿细耳人。’”'),
('CNV', '士师记', 7, 13, 8, '玛挪亚就恳求耶和华，说：“啊，主啊，求你叫你派来的神人再到我们这里吧！好指教我们要怎样对待将要生下来的孩子。”'),
('CNV', '士师记', 7, 13, 9, '神听了玛挪亚的声音。妇人正坐在田间的时候，神的使者又来到她那里，她的丈夫玛挪亚却没有与她在一起。'),
('CNV', '士师记', 7, 13, 10, '妇人急忙跑去告诉丈夫，对他说：“那天到我这里来的那人，又向我显现了。”'),
('CNV', '士师记', 7, 13, 11, '玛挪亚起来，跟着他的妻子出去，来到那人跟前，问他：“你就是向这个妇人说过话的人吗？”他回答：“我就是。”'),
('CNV', '士师记', 7, 13, 12, '玛挪亚说：“你的话应验的时候，这孩子的生活方式怎样？他要作什么呢？”'),
('CNV', '士师记', 7, 13, 13, '耶和华的使者对玛挪亚说：“我对妇人所说的一切话，她都要谨守。'),
('CNV', '士师记', 7, 13, 14, '从葡萄树所产的，她都不可吃；清酒或烈酒，她都不可喝；各样不洁的东西，她也不可吃；我吩咐她的，她都要谨守。”'),
('CNV', '士师记', 7, 13, 15, '玛挪亚对耶和华的使者说：“请留下，好让我为你预备一只山羊羔。”'),
('CNV', '士师记', 7, 13, 16, '耶和华的使者对玛挪亚说：“你虽然要我留下，我却不吃你的食物；如果你预备燔祭，就当献给耶和华。”原来玛挪亚还不知道他是耶和华的使者。'),
('CNV', '士师记', 7, 13, 17, '玛挪亚问耶和华的使者：“你叫什么名字？到你的话应验的时候，我们好把尊荣归你。”'),
('CNV', '士师记', 7, 13, 18, '耶和华的使者对他说：“你为什么问我的名字呢？我的名是奇妙的。”'),
('CNV', '士师记', 7, 13, 19, '玛挪亚取了一只山羊羔和素祭，在磐石上献与那行奇事的耶和华（按照《马索拉文本》，“行奇事”缺主语，直译是﹕“献与耶和华，和行奇事”；现参照各古译本翻译）；玛挪亚和他的妻子一直在观看。'),
('CNV', '士师记', 7, 13, 20, '火焰从祭坛上往天升起的时候，耶和华的使者在祭坛上的火焰中也升上去了；玛挪亚和他的妻子看见了，就俯伏在地。'),
('CNV', '士师记', 7, 13, 21, '耶和华的使者没有再向玛挪亚和他的妻子显现，那时玛挪亚才知道他是耶和华的使者。'),
('CNV', '士师记', 7, 13, 22, '玛挪亚对他的妻子说：“我们必定要死，因为我们看见了神。”'),
('CNV', '士师记', 7, 13, 23, '他的妻子却对他说：“如果耶和华有意要杀我们，就必不从我们的手里接纳燔祭和素祭，也必不会把这一切事指示我们，更不会在这个时候向我们宣布这些事啊。”'),
('CNV', '士师记', 7, 13, 24, '后来那妇人生了一个儿子，她就给他起名叫参孙；孩子渐渐长大了，耶和华赐福给他。'),
('CNV', '士师记', 7, 13, 25, '在玛哈尼．但（“玛哈尼．但”意即“但的军营”），就是在琐拉和以实陶中间，耶和华的灵开始感动参孙。'),
('CNV', '士师记', 7, 14, 1, '参孙下到亭拿，在亭拿看见了一个女子，是一个非利士人的女儿。'),
('CNV', '士师记', 7, 14, 2, '参孙上来告诉他的父母，说：“我在亭拿看见一个女子，是一个非利士人的女儿；现在请你们把她娶来给我作妻子。”'),
('CNV', '士师记', 7, 14, 3, '他的父母对他说：“在你兄弟的女儿中，或是在你所有的族人中，难道没有一个女子，以致你要去从那些未受割礼的非利士人中娶妻呢？”参孙对他的父亲说：“请你把她娶来给我，因为我看中她。”'),
('CNV', '士师记', 7, 14, 4, '他的父母却不知道这事是出于耶和华，因为他正在找机会攻击非利士人。那时非利士人正统治着以色列人。'),
('CNV', '士师记', 7, 14, 5, '参孙跟他的父母下到亭拿去，到了亭拿的葡萄园；忽然见一只少壮狮子向他吼叫。'),
('CNV', '士师记', 7, 14, 6, '耶和华的灵大大感动参孙，他虽然手里没有武器，竟把狮子撕裂，像人撕裂山羊羔一样；他没有把他所作的这事告诉他的父母。'),
('CNV', '士师记', 7, 14, 7, '参孙下去，和那女子说话，就看中了她。'),
('CNV', '士师记', 7, 14, 8, '过了些日子，参孙回去迎娶那女子，他转向一旁去看看那只死了的狮子；看见有一群蜂子和一些蜂蜜在狮子的尸体内。'),
('CNV', '士师记', 7, 14, 9, '他刮了些蜂蜜，放在手里，就走了；他一面走，一面吃，直走到他的父母那里去；他又把蜂蜜给了他们，他们也吃了；但是他没有告诉他们这蜂蜜是从狮子的尸体内刮下来的。'),
('CNV', '士师记', 7, 14, 10, '参孙的父亲下去见那女子，参孙在那里摆设了筵席，因为青年人都惯常这样行。'),
('CNV', '士师记', 7, 14, 11, '众人看见参孙，就请了三十个人陪伴他。'),
('CNV', '士师记', 7, 14, 12, '参孙对他们说：“现在让我给你们出一个谜语，你们在七天婚宴之内，如果能猜出来，把它的意思清楚告诉我，我就给你们三十件内衣、三十套衣服。'),
('CNV', '士师记', 7, 14, 13, '如果你们不能告诉我，你们就要给我三十件内衣、三十套衣服。”他们对他说：“请你把谜语说给我们听。”'),
('CNV', '士师记', 7, 14, 14, '参孙对他们说：“可吃的从吃者出来；甜的从强者出来。”他们过了三日都不能说出谜语的意思。'),
('CNV', '士师记', 7, 14, 15, '到了第四天（按照《马索拉文本》，“第四天”作“第七天”，大概是手民之误﹔两者在原文非常相似，现参照各古译本翻译），他们对参孙的妻子说：“你要引诱你的丈夫，使他把谜语的意思告诉我们，否则我们用火烧你和你的父家。难道你们请了我们来，是要夺取我们所有的吗？”'),
('CNV', '士师记', 7, 14, 16, '参孙的妻子在丈夫面前哭哭啼啼，说：“你只是恨我，不是爱我；你给我的族人设谜语，却没有把谜语的意思告诉我。”参孙对她说：“连我父母我都没有告诉，怎能告诉你呢？”'),
('CNV', '士师记', 7, 14, 17, '在那七天婚宴期内，她在丈夫跟前常常哭哭啼啼；到了第七天，因为她催逼着参孙，参孙才告诉她；于是她把谜语的意思告诉她的族人。'),
('CNV', '士师记', 7, 14, 18, '到了第七天太阳未落以前，城里的人就对参孙说：“有什么比蜂蜜还甜呢？有什么比狮子还强呢？”参孙对他们说：“你们若不是用我的母牛犊耕田，你们就不会猜出我的谜语的意思来。”'),
('CNV', '士师记', 7, 14, 19, '耶和华的灵大大感动参孙，参孙就下到亚实基伦，击杀了他们中间三十个人，拿了剥下来的衣服，把三十套衣服给了那些把谜语的意思说出来的人；参孙怒气冲冲地上自己的父家去了。'),
('CNV', '士师记', 7, 14, 20, '参孙的妻子却归了一个陪伴参孙的人，就是作过他伴郎的。'),
('CNV', '士师记', 7, 15, 1, '过了些日子，到收割麦子的时候，参孙带着一只山羊羔去看他的妻子；他心里说：“我要进内室去见我的妻子。”但是他妻子的父亲不让他进去。'),
('CNV', '士师记', 7, 15, 2, '她父亲说：“我以为你非常恨她，所以我把她给了你的一个同伴；她的妹妹不是比她更美丽吗？你可以娶来代替她啊。”'),
('CNV', '士师记', 7, 15, 3, '参孙对他们说：“这次如果我加害非利士人，就可以不必负责了。”'),
('CNV', '士师记', 7, 15, 4, '于是参孙去捉了三百只狐狸，又拿了火把来，把狐狸尾巴对尾巴缚在一起，又把一枝火把插在两条尾巴中间。'),
('CNV', '士师记', 7, 15, 5, '他点着了火把，就放狐狸进入非利士人的禾田里，把堆积的禾捆，和未割的禾稼，以及橄榄园都烧了。'),
('CNV', '士师记', 7, 15, 6, '非利士人问：“这是谁作的呢？”有人回答：“是亭拿人的女婿参孙作的，因为他岳父把他的妻子给了他的同伴。”于是非利士人上去，放火烧了那女子和她的父亲。'),
('CNV', '士师记', 7, 15, 7, '参孙对他们说：“你们既然这样行，我必在你们身上报仇，然后才肯罢休。”'),
('CNV', '士师记', 7, 15, 8, '参孙击打他们，连腿带腰都砍断了，那是一场极大的杀戮；然后他下去，住在以坦磐石的穴中。'),
('CNV', '士师记', 7, 15, 9, '非利士人上去，在犹大安营，在利希散开。'),
('CNV', '士师记', 7, 15, 10, '犹大人说：“你们为什么上来攻打我们呢？”他们说：“我们上来是要捆绑参孙，要报复他向我们所行的。”'),
('CNV', '士师记', 7, 15, 11, '于是有三千犹大人下到以坦磐石的穴中去，对参孙说：“非利士人统治我们，你不知道吗？你为什么向我们行这事呢？”参孙对他们说：“他们怎样待我，我也怎样待他们。”'),
('CNV', '士师记', 7, 15, 12, '犹大人对他说：“我们下来要捆绑你，把你交在非利士人手里。”参孙对他们说：“你们要向我发誓，你们不亲自杀害我。”'),
('CNV', '士师记', 7, 15, 13, '他们告诉他说：“我们不会杀害你，我们只要把你捆绑住，交在非利士人手里，我们决不杀死你。”于是他们用两条新绳子把参孙捆绑起来，从磐石的穴里把他带上来。'),
('CNV', '士师记', 7, 15, 14, '参孙来到利希，非利士人就吶喊着出来迎接他，耶和华的灵大大临到参孙身上，他臂上的绳子就像被火烧的麻一样，他的捆绑都从他的手上落下来。'),
('CNV', '士师记', 7, 15, 15, '他找着一块新鲜的驴腮骨，就伸手拾起来，击杀了一千人。'),
('CNV', '士师记', 7, 15, 16, '参孙说：“我用驴腮骨杀人成堆；我用驴腮骨击杀了一千人。”'),
('CNV', '士师记', 7, 15, 17, '说完了，就把那腮骨从手里抛出去，因此那地方就叫拉末．利希（“拉末．利希”意即“腮骨的山”）。'),
('CNV', '士师记', 7, 15, 18, '参孙非常口渴，就呼求耶和华说：“你既然藉着你仆人的手施行这么大的拯救，现在我怎可以渴死，落在未受割礼的人手中呢？”'),
('CNV', '士师记', 7, 15, 19, '于是神在利希使一洼地裂开，就有水从那里涌出来；参孙喝了，就恢复精神，活力充足；因此那泉名叫隐．哈歌利（“隐．哈歌利”意即“呼求者之泉”），那泉直到今日还在利希。'),
('CNV', '士师记', 7, 15, 20, '在非利士人统治的日子，参孙治理以色列人二十年。'),
('CNV', '士师记', 7, 16, 1, '参孙往迦萨去，在那里看见一个妓女，就进去与她亲近。'),
('CNV', '士师记', 7, 16, 2, '有人告诉迦萨人说：“参孙到这里来了。”他们就把他围住，整夜在城门口埋伏着，整夜默不作声，心里说：“等到早晨天亮，我们才杀他。”'),
('CNV', '士师记', 7, 16, 3, '参孙睡到半夜，就在半夜起来，抓紧城门的门扇和两边门柱，把它们与门闩一起拔起来，放在自己的肩头上，扛到希伯仑对面的山顶去。'),
('CNV', '士师记', 7, 16, 4, '后来参孙在梭烈谷又爱上了一个妇人，名叫大利拉。'),
('CNV', '士师记', 7, 16, 5, '非利士人的领袖上到妇人那里去，对她说：“请你引诱他，看看他因什么缘故有这样大的力气，我们用什么方法才能胜过他，把他捆绑，好制伏他；我们每人就给你十二公斤银子。”'),
('CNV', '士师记', 7, 16, 6, '大利拉对参孙说：“求你告诉我，你因什么缘故有这样大的力气，要用什么方法才能捆绑你，好把你制伏。”'),
('CNV', '士师记', 7, 16, 7, '参孙对她说：“如果人用七条未干的青绳子捆绑我，我就会软弱无力，像平常人一样。”'),
('CNV', '士师记', 7, 16, 8, '于是非利士人的领袖把七条未干的青绳子，带上来给那妇人，她就用那些绳子把参孙捆绑起来。'),
('CNV', '士师记', 7, 16, 9, '有人埋伏在她的内室里等候着；她对参孙说：“参孙哪，非利士人上来捉你了！”参孙就挣断绳子，像麻线被火烧断一样。这样，他力气的由来，还是没有人知道。'),
('CNV', '士师记', 7, 16, 10, '大利拉对参孙说：“你作弄我，向我说谎；现在求你告诉我，用什么东西才能把你捆绑。”'),
('CNV', '士师记', 7, 16, 11, '参孙对她说：“如果人用从未使用过的新绳子把我紧紧地捆绑起来，我就软弱无力，像平常人一样。”'),
('CNV', '士师记', 7, 16, 12, '于是大利拉把新绳子拿了来，把参孙捆绑了，对他说：“参孙哪，非利士人上来捉你了！”当时有人埋伏在她的内室里等候着。参孙把绳子从手臂上挣断下来，像挣断一根线一样。'),
('CNV', '士师记', 7, 16, 13, '大利拉对参孙说：“到现在你还是作弄我，向我说谎；求你告诉我，人怎样才能捆绑你。”参孙对她说：“如果你把我头上的七条发辫与织布机上的纬线编织在一起就可以了。”'),
('CNV', '士师记', 7, 16, 14, '于是大利拉把他的发辫与织布机上的纬线同织在一起，再用木橛钉紧，对参孙说：“参孙哪，非利士人上来捉你了！”参孙从睡梦中醒来，竟把织布机上的木橛，和纬线都拔了出来。'),
('CNV', '士师记', 7, 16, 15, '大利拉对参孙说：“你既然对我不真心，你怎能说：‘我爱你’？你这三次作弄我，没有告诉我你这么大的力气是哪里来的。”'),
('CNV', '士师记', 7, 16, 16, '大利拉天天用话逼他，催他，以致他的心烦得要死。'),
('CNV', '士师记', 7, 16, 17, '参孙就把他心中的一切告诉了她，对她说：“向来没有人用剃刀剃过我的头，因为我自出母胎就归神作拿细耳人，如果人剃去我的头发，我的力气就离开了我，我就软弱无力，像所有人一样。”'),
('CNV', '士师记', 7, 16, 18, '大利拉见参孙把心中的一切都告诉了她，就派人去请非利士人的领袖来，说：“这一次你们上来吧！因为他已经把心中的一切都告诉了我。”于是非利士人的领袖上到妇人那里，手里带着银子上去。'),
('CNV', '士师记', 7, 16, 19, '大利拉使参孙睡在自己的膝上，又叫了一个人来，把参孙头上的七条发辫都剃去；大利拉就克制了他，因他的力气离开了他。'),
('CNV', '士师记', 7, 16, 20, '大利拉说：“参孙哪，非利士人上来捉你了！”参孙从睡梦中醒来，心里说：“我要像前几次一样挣扎出去，必能脱身。”但他不知道耶和华已经离开他了。'),
('CNV', '士师记', 7, 16, 21, '非利士人把他捉住，剜去了他的眼睛，带他下到迦萨，用铜链捆绑着他，他就在监牢里推磨。'),
('CNV', '士师记', 7, 16, 22, '但是他的头发被剃去以后，又开始生长起来了。'),
('CNV', '士师记', 7, 16, 23, '非利士人的领袖聚集起来，要给他们的神大衮献大祭，并且欢乐庆祝；他们说：“我们的神把我们的仇敌参孙交在我们手中了。”'),
('CNV', '士师记', 7, 16, 24, '众人看见了参孙，就赞美他们的神，说：“我们的神把我们的仇敌，就是那毁坏我们的地，又杀死我们很多人的，交在我们手中了。”'),
('CNV', '士师记', 7, 16, 25, '他们心里正在高兴的时候，就说：“叫参孙来，给我们耍耍把戏。”于是有人把参孙从监牢里叫出来；参孙就在他们面前耍把戏，他们又把他放在两根柱子中间。'),
('CNV', '士师记', 7, 16, 26, '参孙对拉着他手的童子说：“请你让我摸摸支撑着这庙宇的柱子，我要在柱子上靠一靠。”'),
('CNV', '士师记', 7, 16, 27, '那时房子里满了男男女女，非利士人的领袖也在那里；在房子的平顶上约有三千男女，都在观看参孙耍把戏。'),
('CNV', '士师记', 7, 16, 28, '参孙呼求耶和华，说：“主耶和华啊，求你记念我；神啊，求你加强我这一次的力量，只这一次罢了，使我尽一次在非利士人身上报那剜我双眼的仇！”'),
('CNV', '士师记', 7, 16, 29, '参孙就抱住那支撑着房子中间的两根柱子，右手抱一根，左手抱一根。'),
('CNV', '士师记', 7, 16, 30, '然后参孙说：“让我与非利士人同归于尽吧！”于是尽力屈身，房子就倒塌，压在众领袖和房子里所有的人身上。这样，参孙死的时候杀死的人，比他活着的时候杀死的人还多。'),
('CNV', '士师记', 7, 16, 31, '参孙的众兄弟和他父亲的全家都下来，收殓他的尸体，把他抬上去，埋葬在琐拉和以实陶之间，在他父亲玛挪亚的坟墓里。参孙治理了以色列人二十年。'),
('CNV', '士师记', 7, 17, 1, '以法莲山地有一个人，名叫米迦。'),
('CNV', '士师记', 7, 17, 2, '他对自己的母亲说：“你那十二公斤银子被人拿去了，关于这事你曾说了咒诅的话，我也亲自听见了。看哪！那些银子在我这里，是我拿去了。”他母亲说：“愿我儿蒙耶和华赐福。”'),
('CNV', '士师记', 7, 17, 3, '米迦就把那十二公斤银子归还给他母亲；他母亲说：“我把这些银子从我手中分别为圣，为我的儿子归给耶和华，好做一个雕像，一个铸像；现在，我要还给你。”'),
('CNV', '士师记', 7, 17, 4, '米迦把银子还给他母亲以后，他母亲取出二千三百克银子交给银匠，制造一个雕像和一个铸像，都放在米迦的家里。'),
('CNV', '士师记', 7, 17, 5, '米迦这人有一间神庙，又制造以弗得和家中的神像，并且立了他的一个儿子作祭司。'),
('CNV', '士师记', 7, 17, 6, '在那些日子，以色列中没有王，各人都行自己看为对的事。'),
('CNV', '士师记', 7, 17, 7, '有一个犹大伯利恒的青年人，是属犹大家族的；他本是个利未人，在那里寄居。'),
('CNV', '士师记', 7, 17, 8, '这人离开犹大的伯利恒城，要找一个可以寄居的地方；途中，他到了以法莲山地，米迦的家那里。'),
('CNV', '士师记', 7, 17, 9, '米迦问他：“你是从哪里来的？”他回答米迦：“我是个利未人，是从犹大的伯利恒来的，我来要找一个可以寄居的地方。”'),
('CNV', '士师记', 7, 17, 10, '米迦对他说：“你与我住在一起吧，作我的师父和祭司；我每年给你一百一十四克银子、一套衣服和食用。”利未人就进了米迦的家。'),
('CNV', '士师记', 7, 17, 11, '他同意与那人同住；那人看待这青年人好像自己的一个儿子一样。'),
('CNV', '士师记', 7, 17, 12, '米迦立了这利未青年作他的祭司，住在米迦的家里。'),
('CNV', '士师记', 7, 17, 13, '米迦说：“现在我知道耶和华必善待我，因为有一个利未人作我的祭司。”'),
('CNV', '士师记', 7, 18, 1, '在那些日子，以色列中没有王。那时，但支派还在寻找可居住的地业，因为直到那一天，在以色列的众支派中，但支派仍没有得着地业。'),
('CNV', '士师记', 7, 18, 2, '于是但人从琐拉和以实陶，差派他们家族中的五个勇士，去窥探查察那地，对他们说：“你们去查察那地吧。”他们来到以法莲山地，进了米迦的家，就在那里住宿。'),
('CNV', '士师记', 7, 18, 3, '他们在米迦的家附近，认出那青年利未人的口音来，就过去他那里问他：“谁带你到这里来？你在这里作什么？你在这里有什么？”'),
('CNV', '士师记', 7, 18, 4, '他回答他们：“米迦如此这般待我；他雇了我，我就作了他的祭司。”'),
('CNV', '士师记', 7, 18, 5, '他们对他说：“请你求问神，使我们知道我们要走的道路是否顺利。”'),
('CNV', '士师记', 7, 18, 6, '祭司对他们说：“你们平安地去吧，你们要走的道路是蒙耶和华悦纳的。”'),
('CNV', '士师记', 7, 18, 7, '于是那五个人离开了，来到拉亿，看见那里的人民安然居住，好像西顿人一样，生活平静安稳；在那地又没有人掌权，使他们受屈辱（“在那地又没有人掌权，使他们受屈辱”原文意思不明确，或译﹕“他们在地上没缺什么，且拥有财富”）；他们离西顿人也很远，也没有与别人来往。'),
('CNV', '士师记', 7, 18, 8, '他们回到琐拉和以实陶自己的族人那里去；族人问他们：“你们有什么话说？”'),
('CNV', '士师记', 7, 18, 9, '他们回答：“起来，我们上去攻击他们吧。因为我们已经看过那地，见那地十分美好，你们还静坐不动吗？不可再迟延，要赶快去取得那地。'),
('CNV', '士师记', 7, 18, 10, '你们到了那里的时候，你们必遇见安然居住的人民；那地的两边宽阔，神已经把那地交在你们手里；那地百物俱全，一无所缺。”'),
('CNV', '士师记', 7, 18, 11, '于是但人的家族中有六百人，带着兵器从那里出发，就是从琐拉和以实陶出发。'),
('CNV', '士师记', 7, 18, 12, '他们上去，在犹大的基列．耶琳安营；因此人把那地方叫作玛哈尼．但（“玛哈尼．但”意即“但的军营”），直到现在；这地方是在基列．耶琳的西边。'),
('CNV', '士师记', 7, 18, 13, '他们从那里经过，往以法莲山地去，来到米迦的家。'),
('CNV', '士师记', 7, 18, 14, '从前去窥探拉亿地的五个人，对他们的族人说：“这些屋子里有以弗得、神像、雕像和铸像，你们知道吗？现在你们要考虑一下应该怎样行。”'),
('CNV', '士师记', 7, 18, 15, '于是他们五人转身，进入米迦的家，来到那青年利未人的屋里，向他问安。'),
('CNV', '士师记', 7, 18, 16, '那六百但人，带着兵器，都站在门口。'),
('CNV', '士师记', 7, 18, 17, '从前去窥探那地的五个人上前，进入里面，把雕像、以弗得、神像和铸像都拿去了；祭司和带着兵器的六百人都站在门口。'),
('CNV', '士师记', 7, 18, 18, '当那五个人进了米迦的家，拿走雕像、以弗得、神像和铸像的时候，祭司就问他们：“你们作什么呢？”'),
('CNV', '士师记', 7, 18, 19, '他们回答他：“不要出声，用手掩着你的嘴，跟我们走吧，好作我们的师父和祭司。你作一家的祭司好呢？还是作以色列中一个支派一个家族的祭司好呢？”'),
('CNV', '士师记', 7, 18, 20, '祭司心里高兴，就拿着以弗得、神像和雕像，来到众人中间。'),
('CNV', '士师记', 7, 18, 21, '他们就转身离去，把妇孺和牲畜，以及财物，都放在前面。'),
('CNV', '士师记', 7, 18, 22, '他们离开米迦的家很远的时候，在米迦的家附近各家的人，都被召集出来，去追赶但人。'),
('CNV', '士师记', 7, 18, 23, '他们呼叫但人；但人转过脸来，问米迦：“你召集了这么多人出来作什么？”'),
('CNV', '士师记', 7, 18, 24, '米迦回答：“你们把我所做的神像和我的祭司都带走了，我还有什么呢？你们怎么还问我：‘你作什么’呢？”'),
('CNV', '士师记', 7, 18, 25, '但人对米迦说：“不要再让我们听见你的声音，恐怕有暴躁的人攻击你们，以致你和你全家尽都丧失性命。”'),
('CNV', '士师记', 7, 18, 26, '但人继续走他们的路；米迦见他们比自己强，就转身回自己的家去了。'),
('CNV', '士师记', 7, 18, 27, '但人把米迦所做的神像和他的祭司都带走，他们来到拉亿，去到平静安居的人民那里，就用刀剑击杀了他们，又用火烧了那城。'),
('CNV', '士师记', 7, 18, 28, '没有人搭救，因为离西顿很远，他们又与别人没有来往。这城位于靠近伯．利合的山谷中。但人重建那城，住在其中。'),
('CNV', '士师记', 7, 18, 29, '按着他们的祖宗，以色列所生的儿子但的名字，给那城起名叫但；其实那城原先的名字叫拉亿。'),
('CNV', '士师记', 7, 18, 30, '但人就为自己把那雕像立起来；摩西的孙子、革顺的儿子约拿单和他的子孙，都作了但支派的祭司，直到那地遭受掳掠的日子。'),
('CNV', '士师记', 7, 18, 31, '神的殿在示罗有多少日子，但人为自己设立米迦所做的雕像也有多少日子。'),
('CNV', '士师记', 7, 19, 1, '在以色列中没有王的日子，有一个利未人寄居在以法莲山地的偏远地区；他从犹大的伯利恒给自己娶了一个女子作妾。'),
('CNV', '士师记', 7, 19, 2, '他的妾背夫行淫，离开丈夫，回到犹大的伯利恒她父亲的家那里去了，在那里住了四个月的日子。'),
('CNV', '士师记', 7, 19, 3, '她的丈夫起来，带着一个仆人和两头驴去追她，用话打动她的心，叫她回来。她把丈夫带到自己父家，那少女的父亲见了那人，就欢欢喜喜迎接他。'),
('CNV', '士师记', 7, 19, 4, '那人的岳父，就是女子的父亲，强留那人，那人就与他同住了三天；他们一起吃喝，在那里住宿。'),
('CNV', '士师记', 7, 19, 5, '到了第四天，他们清早起来，那人起身要走；那女子的父亲对女婿说：“请吃点饼增添心力，然后再走。”'),
('CNV', '士师记', 7, 19, 6, '于是二人坐下，一起吃喝；女子的父亲对那人说：“请你答应再过一夜，畅快你的心。”'),
('CNV', '士师记', 7, 19, 7, '那人起来要走，他的岳父强留他，他又在那里过了一夜。'),
('CNV', '士师记', 7, 19, 8, '到了第五天，他清早起来要走；那女子的父亲说：“请吃点饼增添心力，等到日头西斜再走吧。”于是他们耽延，直到日头西斜；二人一同吃饭。'),
('CNV', '士师记', 7, 19, 9, '那人和他的妾，以及他的仆人起来要走的时候，他的岳父，就是那女子的父亲，对他说：“看哪，天快晚了！请再住一夜。看哪，日头西斜了！请在这里再住一夜，畅快你的心；明天可以清早起来，上路回家去。”'),
('CNV', '士师记', 7, 19, 10, '那人不愿再住一夜，就带着自己的妾和两头备好了的驴，起来走了，来到耶布斯对面；耶布斯就是耶路撒冷。'),
('CNV', '士师记', 7, 19, 11, '他们走近耶布斯的时候，日头快要落了；仆人对主人说：“来，让我们转到这耶布斯人的城去，好在那里住宿。”'),
('CNV', '士师记', 7, 19, 12, '主人对他说：“我们不可转到这座不是以色列人居住的外族人的城里去，我们过到基比亚去吧。”'),
('CNV', '士师记', 7, 19, 13, '又对他的仆人说：“来吧，我们可以到这些地方其中一个去投宿，或在基比亚或在拉玛。”'),
('CNV', '士师记', 7, 19, 14, '于是他们走路过去；他们走近便雅悯人的基比亚的时候，日头已经落了。'),
('CNV', '士师记', 7, 19, 15, '他们从那里转身，要进基比亚去住宿；他们进去，坐在城里的广场上，因为没有人接待他们到家里去住宿。'),
('CNV', '士师记', 7, 19, 16, '到晚上，有一个老年人从田间工作回来；那人原是以法莲山地的人，寄居在基比亚；那地方的人却是便雅悯人。'),
('CNV', '士师记', 7, 19, 17, '那老年人举目，看见那个旅客在城里的广场上，就问他：“你要到哪里去？你从哪里来？”'),
('CNV', '士师记', 7, 19, 18, '利未人回答他：“我们是从犹大的伯利恒过来的，要到以法莲山地的偏远地区去，我原是那地方的人；我去过犹大的伯利恒，现在我要到我的家去（“到我的家去”原文作“到耶和华的殿去”），但没有人接待我到家里去。'),
('CNV', '士师记', 7, 19, 19, '其实我有粮草、有饲料，可以喂驴；我和我的妾，以及与你的仆人在一起的那个青年人，都有饼和酒吃喝，一无所缺。”'),
('CNV', '士师记', 7, 19, 20, '那老年人说：“愿你平安，你所缺乏的，由我负责好了；只是不可在广场上过夜。”'),
('CNV', '士师记', 7, 19, 21, '于是把他领到自己的家里，用饲料喂了驴，他们洗了脚，就吃喝起来。'),
('CNV', '士师记', 7, 19, 22, '他们心里正畅快的时候，忽然城里有些无赖之徒，围绕房子，不住地敲门，对老房主说：“把进入你家的那个人带出来，我们要与他交合。”'),
('CNV', '士师记', 7, 19, 23, '那房主出来见他们，对他们说：“我的众兄弟啊，不可这样，请你们不要作恶；这人既然进了我的家，你们就不要作这羞耻的事。'),
('CNV', '士师记', 7, 19, 24, '这里有我的女儿，还是处女，并且有这人的妾，我把她们领出来，让你们污辱她们；你们看怎样好，就怎样待她们吧。只是对这个人，你们却不要作这羞耻的事。”'),
('CNV', '士师记', 7, 19, 25, '那些人却不肯听从他的话，那人就抓住自己的妾，拉出外边去交给他们，他们就与她交合，整夜污辱她；直到早晨，天色破晓的时候，才放她走。'),
('CNV', '士师记', 7, 19, 26, '天快亮的时候，那女子回到留她主人住宿的那人的房子门口，就仆倒在那里，直到天亮。'),
('CNV', '士师记', 7, 19, 27, '到早晨，她的主人起来，开了房门，出去要上路的时候，就看见那妇人，就是他的妾，仆倒在门口，她的双手搭在门槛上。'),
('CNV', '士师记', 7, 19, 28, '他对那妇人说：“起来，我们走吧！”可是却没有回答。那人就把她驮在驴上，起程回自己的地方去了。'),
('CNV', '士师记', 7, 19, 29, '他到了家里，就拿起刀来，抓住自己的妾，把她的肢体切成十二块，叫人送到以色列的全境去。'),
('CNV', '士师记', 7, 19, 30, '看见的人都说：“自从以色列人从埃及地上来的日子，直到今日，这样的事并没有发生过，也没有看见过；你们要思想，要商议，要讨论。”'),
('CNV', '士师记', 7, 20, 1, '于是以色列众人都出来，从但到别是巴，以及基列地的众人，都在米斯巴耶和华面前聚集起来如同一人。'),
('CNV', '士师记', 7, 20, 2, '全民的领袖，就是以色列众支派的领袖，都站在神子民的会中；拿刀的步兵共有四十万人。'),
('CNV', '士师记', 7, 20, 3, '（以色列人上到米斯巴来，便雅悯人听见了。）以色列人说：“这件恶事是怎样发生的？你们说吧。”'),
('CNV', '士师记', 7, 20, 4, '那利未人，就是被害的妇人的丈夫，回答说：“我和我的妾到了便雅悯的基比亚，要在那里住宿。'),
('CNV', '士师记', 7, 20, 5, '基比亚人民起来攻击我，在夜间包围我住的房子攻击我，有意杀害我；他们把我的妾污辱致死。'),
('CNV', '士师记', 7, 20, 6, '我就把我的妾切成块子，送到以色列的各地业，因为基比亚人在以色列中行了极羞耻的恶事。'),
('CNV', '士师记', 7, 20, 7, '以色列人哪，你们都要说出你们的意见，也要在这里提出你们的对策。”'),
('CNV', '士师记', 7, 20, 8, '于是众人都起来如同一人，说：“我们当中谁都不回自己的帐棚，谁都不回自己的家。'),
('CNV', '士师记', 7, 20, 9, '现在我们要这样对待基比亚人：我们要照着所抽的签上去攻打他们。'),
('CNV', '士师记', 7, 20, 10, '我们要从以色列各支派中，每百人抽取十人，每千人抽取百人，每万人抽取千人，好为人民运送粮食；等他们到了便雅悯的基比亚的时候，就可以照着他们在以色列中所行的一切羞耻的事惩罚他们。”'),
('CNV', '士师记', 7, 20, 11, '于是以色列众人彼此联合，如同一人，聚集起来攻击那城。'),
('CNV', '士师记', 7, 20, 12, '以色列各支派打发人到便雅悯的各家去，说：“你们中间怎么发生了这样的恶事呢？'),
('CNV', '士师记', 7, 20, 13, '现在你们要把那些人，基比亚的无赖之徒，交出来，我们好处死他们，从以色列中除掉这恶。”只是便雅悯人却不肯听从他们的兄弟以色列人的话。'),
('CNV', '士师记', 7, 20, 14, '便雅悯人从各城出来聚集，往基比亚去，要与以色列人交战。'),
('CNV', '士师记', 7, 20, 15, '那时便雅悯人，从各城里被数点的，共有二万六千拿刀的，另外被数点的，还有基比亚的居民，共有七百精兵。'),
('CNV', '士师记', 7, 20, 16, '在这些人中，还有七百精兵是善用左手的，个个都能用机弦抛石，毫发不差。'),
('CNV', '士师记', 7, 20, 17, '除了便雅悯人以外，以色列人被数点的，共有四十万拿刀的，个个都是战士。'),
('CNV', '士师记', 7, 20, 18, '以色列人就起来，上伯特利去求问神，说：“我们之中谁应首先上去，与便雅悯人交战呢？”耶和华说：“犹大应首先上去。”'),
('CNV', '士师记', 7, 20, 19, '以色列人早晨起来，对着基比亚安营。'),
('CNV', '士师记', 7, 20, 20, '以色列人出来，要与便雅悯人交战；以色列人在基比亚面前列阵等待他们。'),
('CNV', '士师记', 7, 20, 21, '便雅悯人从基比亚出来，那一天使二万二千以色列人倒地身亡。'),
('CNV', '士师记', 7, 20, 22, '众民，就是以色列人，都奋勇起来，又在头一天列阵的地方列阵。'),
('CNV', '士师记', 7, 20, 23, '事前，以色列人上伯特利去，在耶和华面前哀哭直到晚上，然后求问耶和华，说：“我们再去与我们的兄弟便雅悯人交战，可以不可以？”耶和华说：“你们可以上去攻打他们。”'),
('CNV', '士师记', 7, 20, 24, '第二天，以色列人就前去攻打便雅悯人。'),
('CNV', '士师记', 7, 20, 25, '便雅悯人第二天也从基比亚出来，迎战以色列人，又使一万八千以色列人倒地身亡，都是拿刀的。'),
('CNV', '士师记', 7, 20, 26, '以色列众人，就是全体人民，又上到伯特利，坐在耶和华面前哀哭，那日禁食直到晚上，然后在耶和华面前献上燔祭和平安祭。'),
('CNV', '士师记', 7, 20, 27, '那时，神的约柜在那里。'),
('CNV', '士师记', 7, 20, 28, '那时，亚伦的孙子、以利亚撒的儿子非尼哈，侍立在约柜前供职。以色列人求问耶和华，说：“我们应再出去与我们的兄弟便雅悯人交战呢？还是休战呢？”耶和华说：“你们应上去，因为明天我必把他们交在你们手中。”'),
('CNV', '士师记', 7, 20, 29, '以色列人在基比亚四周设下伏兵。'),
('CNV', '士师记', 7, 20, 30, '第三天，以色列人又上去攻打便雅悯人，在基比亚前面列阵，像前两次一样。'),
('CNV', '士师记', 7, 20, 31, '便雅悯人也出来迎敌，他们被引出城外，在两条大路上，一条通往伯特利，一条通往基比亚，像前两次一样，动手杀敌，在田间杀死以色列人约有三十个。'),
('CNV', '士师记', 7, 20, 32, '便雅悯人说：“他们仍像前一次一样，败在我们面前了。”以色列人却说：“我们逃跑吧，引他们离开城市出到大路上来。”'),
('CNV', '士师记', 7, 20, 33, '以色列众人都从自己的地方起来，在巴力．他玛列阵；以色列的伏兵，从基比亚西边埋伏的地方冲出来。'),
('CNV', '士师记', 7, 20, 34, '全以色列中的精兵，有一万人前来攻打基比亚，战争非常激烈；便雅悯人还不知道灾祸快要临到他们的身上了。'),
('CNV', '士师记', 7, 20, 35, '耶和华在以色列人面前击败了便雅悯人；那天以色列人消灭便雅悯人，共二万五千一百名，都是拿刀的。'),
('CNV', '士师记', 7, 20, 36, '这样，便雅悯人就看出自己被击败了。原来以色列人倚靠在基比亚前面设下的伏兵，就对便雅悯人诈败。'),
('CNV', '士师记', 7, 20, 37, '伏兵急忙冲入基比亚，用刀击杀了全城的人。'),
('CNV', '士师记', 7, 20, 38, '以色列人与伏兵预先约定，就是从城里放火，以烟气上升为号。'),
('CNV', '士师记', 7, 20, 39, '以色列人在战场上撤退的时候，便雅悯人就动手杀人，刺死以色列人约三十个，心里说：“他们真的像头一次战阵一样，在我们面前被击败了。”'),
('CNV', '士师记', 7, 20, 40, '当烟柱信号从城中上升的时候，便雅悯人就转身观看，只见全城烟火冲天。'),
('CNV', '士师记', 7, 20, 41, '那时，以色列人又转身回来，便雅悯人就非常惊慌，因为看见灾祸临到自己身上了。'),
('CNV', '士师记', 7, 20, 42, '他们在以色列人面前转身，向旷野的路上逃走，战争却紧随着他们；那些从各城里出来的人也在他们中间消灭他们。'),
('CNV', '士师记', 7, 20, 43, '以色列人包围了便雅悯人，从挪哈（《马索拉文本》意思不明确，“从挪哈”或译﹕“在他们歇息之地”﹔现参照《七十士译本》翻译）追赶他们，践踏他们，直到基比亚（“基比亚”或作“迦巴”）对面日出之处。'),
('CNV', '士师记', 7, 20, 44, '便雅悯人中倒毙的共有一万八千人，全都是勇士。'),
('CNV', '士师记', 7, 20, 45, '其余的人转身，向着旷野逃跑，到了临门的磐石那里；以色列人在大路上除灭了他们五千人，追赶他们直到基顿，又击杀了他们二千人。'),
('CNV', '士师记', 7, 20, 46, '所以那一天便雅悯人倒毙的，共有二万五千人，都是拿刀的，全部是勇士。'),
('CNV', '士师记', 7, 20, 47, '剩下的六百人转身，向着旷野逃跑，到了临门的磐石那里，就在临门的磐石那里住了四个月。'),
('CNV', '士师记', 7, 20, 48, '以色列人又回到便雅悯人那里，把全城的人和牲畜，以及一切遇见的，都用刀杀尽；又把他们碰见的一切城市放火烧毁了。'),
('CNV', '士师记', 7, 21, 1, '以色列人在米斯巴曾经起誓说：“我们中间不可有人把自己的女儿嫁给便雅悯人作妻子。”'),
('CNV', '士师记', 7, 21, 2, '众人来到伯特利，在那里坐在神面前直到晚上，放声大哭，'),
('CNV', '士师记', 7, 21, 3, '说：“耶和华以色列的神啊，今日以色列中缺少了一个支派，为什么在以色列中发生这事呢？”'),
('CNV', '士师记', 7, 21, 4, '次日，众人清早起来，在那里筑了一座祭坛，献上燔祭和平安祭。'),
('CNV', '士师记', 7, 21, 5, '以色列人彼此说：“以色列各支派中，谁没有与会众上到耶和华面前来呢？”因为他们曾经起过很严厉的誓，说：“不上米斯巴到耶和华面前的，必把他处死。”'),
('CNV', '士师记', 7, 21, 6, '以色列人为他们的兄弟便雅悯难过，说：“今天以色列中有一个支派被剪除了。'),
('CNV', '士师记', 7, 21, 7, '我们曾经指着耶和华起过誓，必不把我们的女儿给便雅悯人作妻子，那么现在我们当怎样办理，使他们剩下的人有妻子呢？”'),
('CNV', '士师记', 7, 21, 8, '他们又彼此问：“以色列各支派中，有谁没有上米斯巴到耶和华面前来的呢？”他们就发现基列．雅比中没有一人去到营中会众那里。'),
('CNV', '士师记', 7, 21, 9, '众人被数点的时候，就发现基列．雅比的居民中没有一人在那里。'),
('CNV', '士师记', 7, 21, 10, '因此会众从勇士中差派一万二千人到那里去，吩咐他们说：“你们去用刀击杀基列．雅比的居民，连妇女与孩子都要杀。'),
('CNV', '士师记', 7, 21, 11, '你们要这样行，你们要把所有的男子，和所有与男子同过房的女子，完全毁灭。”'),
('CNV', '士师记', 7, 21, 12, '他们在基列．雅比的居民中，找到了四百个未曾与人同房，也未曾与男子同寝的年轻少女，就把她们带到迦南地的示罗营那里。'),
('CNV', '士师记', 7, 21, 13, '全体会众又派人到临门的磐石那里，对便雅悯人说话，向他们宣告和平。'),
('CNV', '士师记', 7, 21, 14, '那时便雅悯人回来了，以色列人就把他们保留的基列．雅比的女子给他们作妻子，但还是不够。'),
('CNV', '士师记', 7, 21, 15, '众人为便雅悯人难过，因为耶和华使以色列众支派中有了缺口。'),
('CNV', '士师记', 7, 21, 16, '会众中的长老说：“便雅悯的女子既然都被除灭了，我们应怎样行，使那些余下的人有妻子呢？”'),
('CNV', '士师记', 7, 21, 17, '又说：“便雅悯逃脱的人应有地业，免得有个支派从以色列中被消灭。'),
('CNV', '士师记', 7, 21, 18, '但是我们不能把我们自己的女儿给他们作妻子。”因为以色列人曾经起誓说：“把女儿给便雅悯人作妻子的，是可咒诅的。”'),
('CNV', '士师记', 7, 21, 19, '他们又说：“看哪，每年在示罗都举行耶和华的节期；示罗就是在伯特利的北面，从伯特利上示剑的大路的东面，在利波拿的南面。”'),
('CNV', '士师记', 7, 21, 20, '于是他们吩咐便雅悯人说：“你们去在葡萄园中设下埋伏；'),
('CNV', '士师记', 7, 21, 21, '在那里观看，示罗的女子出来跳舞的时候，你们就从葡萄园出来，从示罗的女子中，各抢一个作妻子，然后回便雅悯地去。'),
('CNV', '士师记', 7, 21, 22, '如果她们的父亲或是兄弟来与我们争论，我们就对他们说：‘求你们恩待他们吧，因为我们在战场上没有给他们留下女子作妻子，而且这次又不是你们把女儿给他们；若是你们给的，你们就有罪了。’”'),
('CNV', '士师记', 7, 21, 23, '于是便雅悯人照样行了：按着他们的数目，从跳舞的女子中强抢她们作妻子，然后离开那里，回到自己的地业去，重建城市，住在其中。'),
('CNV', '士师记', 7, 21, 24, '那时，以色列人离开那里，各人回到自己的支派和自己的家族去；他们离开那里，各人回到自己的地业去。'),
('CNV', '士师记', 7, 21, 25, '在那些日子，以色列中没有王，各人都行自己看为对的事。'),
('CNV', '路得记', 8, 1, 1, '在士师统治期间，国内发生了饥荒。有一个人带着妻子和两个儿子，从犹大的伯利恒前往摩押地去，寄居在那里。'),
('CNV', '路得记', 8, 1, 2, '这个人名叫以利米勒，妻子名叫拿俄米，两个儿子叫玛伦和基连，都是犹大伯利恒的以法他人。他们到了摩押地，就在那里住下来了。'),
('CNV', '路得记', 8, 1, 3, '后来拿俄米的丈夫以利米勒去世了，留下她和两个儿子。'),
('CNV', '路得记', 8, 1, 4, '他们娶了摩押女子作妻子，一个名叫俄耳巴，一个名叫路得。他们在那里住了约有十年。'),
('CNV', '路得记', 8, 1, 5, '后来，玛伦和基连二人也死了，留下拿俄米，既没有了两个儿子，又没有了丈夫。'),
('CNV', '路得记', 8, 1, 6, '拿俄米还在摩押地的时候，因为听说耶和华眷顾他的子民，赐粮食给他们，就带着两个媳妇动身从摩押地回来。'),
('CNV', '路得记', 8, 1, 7, '她离开居住的地方，两个媳妇也随她出发，要回到犹大地去。'),
('CNV', '路得记', 8, 1, 8, '拿俄米对两个媳妇说：“去吧，你们还是各自回娘家吧。愿耶和华恩待你们，像你们善待已死的人和我一样。'),
('CNV', '路得记', 8, 1, 9, '愿耶和华使你们各人有机会再嫁（“有机会再嫁”原文作“在丈夫家里”），找到归宿。”跟着亲吻她们，她们就发声大哭，'),
('CNV', '路得记', 8, 1, 10, '说：“不，我们一定要跟你一起回到你同胞那里去。”'),
('CNV', '路得记', 8, 1, 11, '拿俄米说：“我女儿啊，你们回去吧，为什么要跟我去呢？我肚子里还有儿子作你们的丈夫吗？'),
('CNV', '路得记', 8, 1, 12, '走吧，我女儿啊，你们回去吧，因为我太老，不能嫁人了，就算我说我还有希望今天晚上有个丈夫，又生儿子，'),
('CNV', '路得记', 8, 1, 13, '你们可以等到他们长大吗？你们可以为他们守节而不嫁人吗？不行，我女儿啊，我为你们非常难过，因为耶和华伸手对付我。”'),
('CNV', '路得记', 8, 1, 14, '她们又放声大哭。俄耳巴就和婆婆吻别，路得却舍不得离开拿俄米。'),
('CNV', '路得记', 8, 1, 15, '拿俄米说：“你看，你嫂嫂已经回到她同胞和她的神那里去了。你也跟着嫂嫂回去吧。”'),
('CNV', '路得记', 8, 1, 16, '路得说：“请不要逼我离开你回去，不跟从你。你到哪里去，我也要到哪里去；你在哪里过夜，我也要在哪里过夜；你的同胞就是我的同胞，你的神就是我的神；'),
('CNV', '路得记', 8, 1, 17, '你死在哪里，我也要死在哪里，葬在哪里。除非死亡把你我分离；如果我离开你，愿耶和华加倍惩罚我。”'),
('CNV', '路得记', 8, 1, 18, '拿俄米看路得坚决要跟她走，就不再多费唇舌了。'),
('CNV', '路得记', 8, 1, 19, '她们双双上路，来到伯利恒。她们到达的时候，全城都因她们的缘故骚动起来。妇女们说：“这是拿俄米吗？”'),
('CNV', '路得记', 8, 1, 20, '拿俄米对她们说：“不要叫我拿俄米，叫我玛拉吧，因为全能者使我吃尽了苦头。'),
('CNV', '路得记', 8, 1, 21, '我满满地出去，耶和华却使我空空地回来，你们为什么还叫我拿俄米呢？耶和华折磨我，全能者加害于我。”'),
('CNV', '路得记', 8, 1, 22, '拿俄米就这样回来了。她媳妇摩押女子路得随着她从摩押地回来。她们到达伯利恒，正是开始收割大麦的时候。'),
('CNV', '路得记', 8, 2, 1, '拿俄米的丈夫以利米勒有个同族的亲戚，名叫波阿斯，是个大财主。'),
('CNV', '路得记', 8, 2, 2, '摩押女子路得对拿俄米说：“让我到田里去，我在谁的眼前蒙恩，我就跟在谁的背后捡麦穗。”拿俄米说：“女儿啊，你尽管去。”'),
('CNV', '路得记', 8, 2, 3, '路得就去了，来到田里，在收割的人背后捡麦穗。她恰巧来到以利米勒同族的人波阿斯那块田。'),
('CNV', '路得记', 8, 2, 4, '波阿斯刚好从伯利恒来，对收割的人说：“愿耶和华与你们同在。”他们回答：“愿耶和华赐福与你。”'),
('CNV', '路得记', 8, 2, 5, '波阿斯问那监督收割的仆人：“那是谁家的姑娘呢？”'),
('CNV', '路得记', 8, 2, 6, '监督收割的仆人回答：“她是跟拿俄米从摩押地回来的摩押女子。'),
('CNV', '路得记', 8, 2, 7, '她说：‘请让我捡一点麦穗吧。让我跟在收割的人背后，在禾捆堆中捡些零碎的穗子。’于是她来了。除了在房子里休息了一会儿之外，从早晨到现在一直都留在这里。”'),
('CNV', '路得记', 8, 2, 8, '波阿斯对路得说：“女儿啊，听我说，不要到别人田里去捡麦穗，也不要离开这里，要常常与我的女佣人在一起。'),
('CNV', '路得记', 8, 2, 9, '你看他们在哪块田里收割，就跟着女佣人去。我不是已经吩咐仆人不可欺负你吗？假如你渴了，就到水缸那里去，喝仆人打来的水。”'),
('CNV', '路得记', 8, 2, 10, '路得就俯伏在地叩拜，对他说：“我是个外族人，为什么会在你眼前蒙恩，蒙你关照呢？”'),
('CNV', '路得记', 8, 2, 11, '波阿斯回答她说：“自从你丈夫去世以后，你对婆婆所行的，和你怎样离开父母与出生之地，来到素来不认识的人中间，这一切我都知道得很清楚了。'),
('CNV', '路得记', 8, 2, 12, '愿耶和华照你所作的报答你；你来投靠在耶和华以色列神的翅膀下，愿他充充足足酬报你。”'),
('CNV', '路得记', 8, 2, 13, '路得说：“主人啊，但愿我在你眼前蒙恩，虽然我连你的婢女都不是，你还是安慰我，对我这么好。”'),
('CNV', '路得记', 8, 2, 14, '到了吃饭的时候，波阿斯对路得说：“你过来，吃一点饼吧，拿饼块蘸在醋里。”路得就在收割的人旁边坐下来。波阿斯把一些烘好的麦穗递给她，她吃饱了，还有剩下的。'),
('CNV', '路得记', 8, 2, 15, '她再起来去捡麦穗的时候，波阿斯吩咐仆人说：“就算她在禾捆堆中捡麦穗，也不可以辱骂她。'),
('CNV', '路得记', 8, 2, 16, '甚至要故意为她从禾捆中抽些出来，留给她去捡，千万不可责备她。”'),
('CNV', '路得记', 8, 2, 17, '路得就这样在田里捡麦穗，直到傍晚。她把捡来的麦穗打了，约有二十二公升大麦，'),
('CNV', '路得记', 8, 2, 18, '然后带回城里去。路得把捡来的麦子拿给婆婆看，把吃剩的给了婆婆。'),
('CNV', '路得记', 8, 2, 19, '婆婆问她：“你今天在哪里捡麦穗？在哪里工作呢？愿那关照你的人蒙福。”路得就告诉婆婆她在谁那里工作，说：“我今天在一个名叫波阿斯的人那里工作。”'),
('CNV', '路得记', 8, 2, 20, '拿俄米对媳妇说：“愿不断施慈爱给活人和死人的耶和华赐福给他。”拿俄米又对她说：“这个人是我们的亲人，有买赎权的一位近亲。”'),
('CNV', '路得记', 8, 2, 21, '摩押女子路得说：“他还告诉我：‘紧跟着我的仆人捡麦穗，直到全部收割完毕。’”'),
('CNV', '路得记', 8, 2, 22, '拿俄米对媳妇路得说：“我女儿啊，这样才好，要与他的女佣人一起去，免得在别人的田里遭受敌视。”'),
('CNV', '路得记', 8, 2, 23, '她就紧跟着波阿斯的女佣人捡麦穗，直到大麦和小麦都收割好了。路得一直与婆婆住在一起。'),
('CNV', '路得记', 8, 3, 1, '路得的婆婆拿俄米对她说：“女儿啊，我不是应当为你找个归宿，使你得到幸福吗？'),
('CNV', '路得记', 8, 3, 2, '你常常和他的女佣人在一起的波阿斯不是我们的亲戚吗？他今天晚上要在禾场上簸大麦。'),
('CNV', '路得记', 8, 3, 3, '你洗个澡，抹上香膏，穿上斗篷，就下到禾场去。不过，那个人还没有吃喝完毕，别让他认出你来。'),
('CNV', '路得记', 8, 3, 4, '等到他躺下来，你要弄清楚他所躺的地方，进去掀露他的脚，然后躺下去。他就会告诉你该作什么。”'),
('CNV', '路得记', 8, 3, 5, '路得对她说：“你吩咐的，我就去作。”'),
('CNV', '路得记', 8, 3, 6, '于是，她下到禾场去，照着婆婆吩咐的一切去作。'),
('CNV', '路得记', 8, 3, 7, '波阿斯吃喝完了，心里舒畅，就去躺在麦堆的旁边。路得悄悄地来，掀露他的脚，躺卧下去。'),
('CNV', '路得记', 8, 3, 8, '到了夜半，波阿斯惊醒过来，一翻身就看到一个女子躺在他的脚边，'),
('CNV', '路得记', 8, 3, 9, '就说：“你是谁？”她回答：“我是你的婢女路得，请用你的衣襟遮盖你的婢女，因为你是我一个有买赎权的近亲。”'),
('CNV', '路得记', 8, 3, 10, '波阿斯说：“我女儿，愿你蒙耶和华赐福。你末后表现的爱心比起初更大，因为年轻人无论贫富，你都没有跟从。'),
('CNV', '路得记', 8, 3, 11, '我女儿，现在你不要怕，你所说的，我一定去作。本城的人都知道你是个贤惠的女人。'),
('CNV', '路得记', 8, 3, 12, '不错，我是你那有买赎权的近亲，可惜还有一个有买赎权的近亲比我更亲。'),
('CNV', '路得记', 8, 3, 13, '今晚你就在这里过夜，明早如果他肯尽买赎你的本分，好，就由他来履行；假如他不愿意这样作，我指着永活的耶和华起誓，我一定尽买赎你的本分。你只管躺到天亮吧。”'),
('CNV', '路得记', 8, 3, 14, '路得躺在波阿斯脚边直到早晨。因为波阿斯说过不可以让人知道有女人来过禾场，路得就趁天色未明，人们彼此无法辨认的时候就起来。'),
('CNV', '路得记', 8, 3, 15, '他又说：“拿你所披的外衣来，把它打开。”她打开了，他就量了六簸箕大麦，放在她的肩上。路得就进城去。'),
('CNV', '路得记', 8, 3, 16, '到她婆婆那里，婆婆就问：“我女儿，怎样了？”路得就把那人对她所作的一切都告诉了婆婆，'),
('CNV', '路得记', 8, 3, 17, '又说：“他给我这六簸箕大麦，对我说：‘不要空手去见你婆婆。’”'),
('CNV', '路得记', 8, 3, 18, '拿俄米说：“我女儿，你尽管安静等候，直到你知道事情怎样了结，因为那人今天不把事情办妥，绝不歇息。”'),
('CNV', '路得记', 8, 4, 1, '波阿斯到了城门，坐在那里，恰巧波阿斯所说那个有买赎权的近亲属刚巧路过那里。波阿斯说：“喂，老兄，过来坐一下吧。”他就过去坐下来了。'),
('CNV', '路得记', 8, 4, 2, '波阿斯又邀请城里的十个长老，对他们说：“请坐在这里。”他们就坐下来了。'),
('CNV', '路得记', 8, 4, 3, '他对那个有买赎权的近亲说：“从摩押地回来的拿俄米，现在要卖我们族兄以利米勒的那块地；'),
('CNV', '路得记', 8, 4, 4, '我想把这一件事告诉你，请你在众民的长老，还有在座的各位面前，把它买下来吧。如果你肯赎就赎，假如不肯，就说出来，让我知道；因为除了你当赎它之外，我是第一候补。”那人说：“我肯赎。”'),
('CNV', '路得记', 8, 4, 5, '波阿斯说：“你从拿俄米手中买下那块地的时候，你也得娶（“娶”原文作“买”）已死的人的妻子摩押女子路得，使已死的人的名字留在他的产业上。”'),
('CNV', '路得记', 8, 4, 6, '那有买赎权的近亲说：“那我就不能赎它了，只怕损害了我的产业。你可以赎我当赎的，因为我没有办法赎了。”'),
('CNV', '路得记', 8, 4, 7, '从前在以色列，无论买赎或是交易，决定什么事，当事人就要脱鞋给对方。这是以色列中作证的方式。'),
('CNV', '路得记', 8, 4, 8, '那有买赎权的近亲对波阿斯说：“你自己买下来吧。”就把鞋脱下来。'),
('CNV', '路得记', 8, 4, 9, '波阿斯对长老和众人说：“今天你们都是见证人，所有属于以利米勒、基连和玛伦的，我都从拿俄米手中买下来了。'),
('CNV', '路得记', 8, 4, 10, '我也娶了（“娶了”原文作“买了”）玛伦的妻子摩押女子路得作妻子，使已死的人的名字留在他的产业上，免得他的名字在本族本乡中除掉。今天你们都是见证人。”'),
('CNV', '路得记', 8, 4, 11, '聚集在城门的众人和长老都说：“我们都是见证人。愿耶和华使进你家的这女人，像建立以色列家的拉结和利亚二人一样。愿你在以法他显大，在伯利恒扬名。'),
('CNV', '路得记', 8, 4, 12, '愿耶和华从这少妇赐你后裔，使你的家像他玛从犹大所生法勒斯的家一般。”'),
('CNV', '路得记', 8, 4, 13, '于是波阿斯娶了路得作妻子，与她亲近。耶和华使她怀孕生了一个儿子。'),
('CNV', '路得记', 8, 4, 14, '妇女对拿俄米说：“耶和华是应当称颂的，因为他今天没有断绝你有买赎权的近亲，愿他在以色列中扬名。'),
('CNV', '路得记', 8, 4, 15, '他必甦醒你的生命，养你的老，因为他是爱你的媳妇所生的；有她比有七个儿子更好。”'),
('CNV', '路得记', 8, 4, 16, '拿俄米把孩子接过来，抱在怀中，作他的保姆。'),
('CNV', '路得记', 8, 4, 17, '邻近的妇女要给他起名字，说：“拿俄米生了孩子了。”就给他起名叫俄备得；这俄备得是耶西的父亲，耶西是大卫的父亲。'),
('CNV', '路得记', 8, 4, 18, '以下是法勒斯的后代：法勒斯生希斯仑，'),
('CNV', '路得记', 8, 4, 19, '希斯仑生兰，兰生亚米拿达，'),
('CNV', '路得记', 8, 4, 20, '亚米拿达生拿顺，拿顺生撒门，'),
('CNV', '路得记', 8, 4, 21, '撒门生波阿斯，波阿斯生俄备得，'),
('CNV', '路得记', 8, 4, 22, '俄备得生耶西，耶西生大卫。'),
('CNV', '撒母耳记上', 9, 1, 1, '在以法莲山地的拉玛．琐非，有一个以法莲人名叫以利加拿，是耶罗罕的儿子、以利户的孙子、托户的曾孙、苏弗的玄孙。'),
('CNV', '撒母耳记上', 9, 1, 2, '他有两个妻子，一个名叫哈拿，另一个名叫毗尼拿。毗尼拿有孩子，哈拿却没有孩子。'),
('CNV', '撒母耳记上', 9, 1, 3, '这人每年都从他的本城上示罗去敬拜，献祭给万军之耶和华。在示罗有以利的两个儿子，何弗尼和非尼哈，作耶和华的祭司。'),
('CNV', '撒母耳记上', 9, 1, 4, '以利加拿在献祭的那天，就把祭肉分给妻子毗尼拿和她所有的儿女。'),
('CNV', '撒母耳记上', 9, 1, 5, '但他只分给哈拿一份；他虽然爱哈拿（《马索拉文本》意思不明确，“但他只分给哈拿一份；他虽然爱哈拿”或译﹕“但他分给哈拿双份，因为他爱哈拿”），耶和华却使哈拿不能怀孕。'),
('CNV', '撒母耳记上', 9, 1, 6, '因为耶和华使哈拿不能怀孕，她的对头就尽力刺激她，使她苦恼。'),
('CNV', '撒母耳记上', 9, 1, 7, '年年都是这样；每逢她上耶和华殿的时候，毗尼拿总是刺激哈拿，使她哭泣，吃不下饭。'),
('CNV', '撒母耳记上', 9, 1, 8, '她的丈夫以利加拿对她说：“哈拿，你为什么哭泣？为什么不吃饭，为什么心里难过呢？你有我不是比有十个儿子更好吗？”'),
('CNV', '撒母耳记上', 9, 1, 9, '哈拿在示罗吃喝完了，就起来。（那时以利祭司在耶和华殿的门柱旁边，坐在椅子上。）'),
('CNV', '撒母耳记上', 9, 1, 10, '她心里愁苦，就向耶和华祷告，流泪痛哭，'),
('CNV', '撒母耳记上', 9, 1, 11, '并且许愿，说：“万军之耶和华啊，你若是看顾使女的困苦，记念我，不忘记你的使女，赐给使女一个儿子，我就必把他一生献给耶和华，不剃他的头。”'),
('CNV', '撒母耳记上', 9, 1, 12, '哈拿向耶和华祷告了很久，以利一直在注视她的嘴。'),
('CNV', '撒母耳记上', 9, 1, 13, '原来哈拿是在心中诉说，只见她的嘴唇在动，却听不见她的声音，因此以利以为她是个喝醉了的女人。'),
('CNV', '撒母耳记上', 9, 1, 14, '以利就对她说：“你要醉到几时呢？快快醒过来吧！”'),
('CNV', '撒母耳记上', 9, 1, 15, '哈拿回答：“我主啊，不是的。我是个心灵愁苦的妇人，淡酒烈酒都没有喝，只不过在耶和华面前倾吐我的心意。'),
('CNV', '撒母耳记上', 9, 1, 16, '不要把你的使女看作不检点的女子，我因为极度愁苦和激动，才一直倾诉到现在。”'),
('CNV', '撒母耳记上', 9, 1, 17, '以利回答：“平平安安回去吧！愿以色列的神把你向他所求的赐给你。”'),
('CNV', '撒母耳记上', 9, 1, 18, '哈拿说：“愿你的婢女在你眼前蒙恩！”于是这妇人回去，并且吃饭，脸上再没有愁容。'),
('CNV', '撒母耳记上', 9, 1, 19, '第二天，他们清早起来，在耶和华面前敬拜，然后回到他们的家乡拉玛，回到自己的家里去。以利加拿和妻子哈拿同房；耶和华顾念哈拿，'),
('CNV', '撒母耳记上', 9, 1, 20, '她就怀孕；时候到了，就生了一个儿子，哈拿给他起名叫撒母耳，因为她说：“他是我从耶和华那里求来的。”'),
('CNV', '撒母耳记上', 9, 1, 21, '以利加拿和他全家都上示罗去，向耶和华献年祭和还所许的愿；'),
('CNV', '撒母耳记上', 9, 1, 22, '哈拿却没有上去，因为她对丈夫说：“等孩子断了奶，我才带他去朝见耶和华。他要永远住在那里。”'),
('CNV', '撒母耳记上', 9, 1, 23, '她丈夫以利加拿对她说：“你看怎样好，就怎样作吧。你可以留在这里，等到你给孩子断了奶，但愿耶和华实现他的话。”于是哈拿留在家里乳养孩子，直到给他断了奶。'),
('CNV', '撒母耳记上', 9, 1, 24, '她给孩子断了奶之后，就带他一同上去，又带了一头三岁的公牛（按照《马索拉文本》，“一头三岁的公牛”应作“三头公牛”；现参照《七十士译本》翻译）、十公斤面和一皮袋酒。她把孩子带到示罗耶和华的殿那里；那时孩子还很小。'),
('CNV', '撒母耳记上', 9, 1, 25, '他们宰了公牛以后，就带孩子到以利那里，'),
('CNV', '撒母耳记上', 9, 1, 26, '妇人说：“我主啊，我敢指着我主的性命起誓，我就是从前在这里站在你旁边，向耶和华祷告的那个妇人。'),
('CNV', '撒母耳记上', 9, 1, 27, '那时我祈求为要得这孩子，耶和华已经把我向他所求的赐给我了，'),
('CNV', '撒母耳记上', 9, 1, 28, '所以我现在把他献给耶和华，他的一生是属于耶和华的。”于是他就在那里敬拜耶和华。'),
('CNV', '撒母耳记上', 9, 2, 1, '哈拿祷告说：“我的心因耶和华喜乐，我的角因耶和华高举，我的口向仇敌大大夸耀，因为我以你的救恩为乐。'),
('CNV', '撒母耳记上', 9, 2, 2, '没有人像耶和华那么圣洁，因为除你以外没有别的神，也没有磐石像我们的神。'),
('CNV', '撒母耳记上', 9, 2, 3, '你们不要多说骄傲的话，也不要口出狂妄之言，因为耶和华是全知的神，人的一切行为他都鉴察。'),
('CNV', '撒母耳记上', 9, 2, 4, '勇士的弓都被折断，跌倒的人却以力量束腰。'),
('CNV', '撒母耳记上', 9, 2, 5, '饱足的，要劳碌觅食，饥饿的，不再饥饿；不能生育的，生了七个儿女，有过许多儿女的，反倒衰微。'),
('CNV', '撒母耳记上', 9, 2, 6, '耶和华使人死，也使人活；使人下阴间，也使人从阴间上来。'),
('CNV', '撒母耳记上', 9, 2, 7, '耶和华使人贫穷，也使人富足；使人降卑，也使人升高。'),
('CNV', '撒母耳记上', 9, 2, 8, '他从灰尘中抬举贫寒的人，从粪堆中提拔穷乏的人，使他们与显贵同坐，承受尊贵的座位。大地的柱子属于耶和华，他把全地安放在柱子上面。'),
('CNV', '撒母耳记上', 9, 2, 9, '耶和华必保护虔诚人的脚步，却使恶人在黑暗中灭亡，因为人得胜不是靠着力量。'),
('CNV', '撒母耳记上', 9, 2, 10, '至高者在天上打雷，耶和华必打碎与他作对的人。耶和华要审判地的四极，却要赐力量给他所立的王，高举他膏立之人的角。”'),
('CNV', '撒母耳记上', 9, 2, 11, '后来，以利加拿回拉玛自己的家去。那孩子却留在以利祭司面前事奉耶和华。'),
('CNV', '撒母耳记上', 9, 2, 12, '以利的两个儿子是无赖，不尊重耶和华，'),
('CNV', '撒母耳记上', 9, 2, 13, '也不理会当时祭司待人民的规矩。凡是有人献祭，在煮肉的时候，祭司的仆人就来，手里拿着三齿的叉，'),
('CNV', '撒母耳记上', 9, 2, 14, '把叉子插入煎盘里，或鼎里，或釜里，或锅里，叉子插上来的，祭司都拿去。所有到示罗来的以色列人，祭司都是这样待他们。'),
('CNV', '撒母耳记上', 9, 2, 15, '还有，在焚烧脂油以前，祭司的仆人就来，对献祭的人说：“把祭肉交给祭司烧烤吧，因为他不会向你要煮过的肉，单要生的。”'),
('CNV', '撒母耳记上', 9, 2, 16, '如果那人对仆人说：“必须先把脂油焚烧了，然后你才可以随意去拿。”他就说：“不可以，你现在就要给我，否则我就抢去。”'),
('CNV', '撒母耳记上', 9, 2, 17, '这样，那两个青年人在耶和华面前所犯的罪很大，因为他们藐视献给耶和华的祭物。'),
('CNV', '撒母耳记上', 9, 2, 18, '那时，撒母耳还是个孩童，束着细麻布的以弗得，在耶和华面前事奉。'),
('CNV', '撒母耳记上', 9, 2, 19, '撒母耳的母亲每年为他做一件小外袍，她和丈夫一同上来献年祭的时候，就带来给他。'),
('CNV', '撒母耳记上', 9, 2, 20, '以利给以利加拿和他的妻子祝福，说：“愿耶和华从这妇人身上还给你后裔，代替你献给耶和华的孩子。”他们就回自己的地方去了。'),
('CNV', '撒母耳记上', 9, 2, 21, '耶和华眷顾哈拿，她再怀孕，先后生了三个儿子和两个女儿。那孩子撒母耳在耶和华面前，渐渐长大。'),
('CNV', '撒母耳记上', 9, 2, 22, '以利已经非常老了，听见自己的儿子对待以色列人的一切事，又听见他们与在会幕门口侍应的妇女同寝。'),
('CNV', '撒母耳记上', 9, 2, 23, '以利就对他们说：“你们为什么作这些事？我亲自从众民那里听见了你们的恶行。'),
('CNV', '撒母耳记上', 9, 2, 24, '我儿啊，不要这样，因为我听见的消息很不好，你们使耶和华的子民违背律法。'),
('CNV', '撒母耳记上', 9, 2, 25, '如果有人得罪人，有官长（“官长”原文作“神”）惩罚他；如果有人得罪耶和华，有谁为他求情呢？”他们却不听父亲的话，因为耶和华有意要杀他们。'),
('CNV', '撒母耳记上', 9, 2, 26, '那孩子撒母耳的身量，耶和华和众人对他的喜爱，都不断增长。'),
('CNV', '撒母耳记上', 9, 2, 27, '有一位神人来见以利，对他说：“耶和华这样说：‘你父家在埃及法老家为奴的时候，我不是向他们显现吗？'),
('CNV', '撒母耳记上', 9, 2, 28, '我不是从以色列众支派中，选出他们作我的祭司，上我的坛烧香，在我面前穿以弗得吗？我不是把以色列人所献的火祭，都赐给了你的父家吗？'),
('CNV', '撒母耳记上', 9, 2, 29, '你们为什么轻视（“轻视”直译是“踢”）我所吩咐要为我居所献上的祭牲和礼物呢？（《马索拉文本》本句意思不明确）你为什么尊重你的儿子过于尊重我，用我子民以色列所献一切最好的礼物自肥呢？’'),
('CNV', '撒母耳记上', 9, 2, 30, '因此，耶和华以色列的神说：‘我曾说：你的家和你的父家，必永远行在我面前。’现在耶和华却说：‘我决不容你们这样行了，因为尊重我的，我必尊重他；藐视我的，必受到轻视。'),
('CNV', '撒母耳记上', 9, 2, 31, '日子快到了，我要砍下你和你父亲的膀臂，使你家中再没有有权势的长者。'),
('CNV', '撒母耳记上', 9, 2, 32, '我赐给以色列人的一切福分，你必像一个对头，以嫉妒的眼光来看；而在你的家中，必永远再没有有权势的长者。'),
('CNV', '撒母耳记上', 9, 2, 33, '我必不从我的祭坛那里灭绝你家的人，免得你的眼睛昏花，心灵忧伤，但所有你家中增添的人都必像世人一样死去（按照《七十士译本》和《死海古卷》，“像世人一样死去”作“死在人的刀下”）。'),
('CNV', '撒母耳记上', 9, 2, 34, '你的两个儿子何弗尼和非尼哈所要遭遇的事，是给你的一个证据：他们二人必同日而死。'),
('CNV', '撒母耳记上', 9, 2, 35, '我要为自己兴起一位忠心的祭司，他必依照我的心意行事；我要为他建立一个稳固的家，他一生必行在我的受膏者面前。'),
('CNV', '撒母耳记上', 9, 2, 36, '你家中剩下的人，都要来向他下拜；求一个银币，一块饼，也要说：求你容我参与祭司的职务，使我可以有点饼吃。’”'),
('CNV', '撒母耳记上', 9, 3, 1, '那孩子撒母耳在以利面前事奉耶和华，在那些日子，耶和华的言语稀少，异象也不常有。'),
('CNV', '撒母耳记上', 9, 3, 2, '有一天，以利躺卧在自己的地方，他的眼睛早已昏花，不能看得清楚了。'),
('CNV', '撒母耳记上', 9, 3, 3, '神的灯还没有熄灭，撒母耳躺卧在耶和华的殿中，就是安放神约柜的地方。'),
('CNV', '撒母耳记上', 9, 3, 4, '耶和华呼唤撒母耳，他说：“我在这里。”'),
('CNV', '撒母耳记上', 9, 3, 5, '他就跑到以利那里，说：“你呼唤我，我在这里。”以利说：“我没有呼唤你，回去睡吧。”他就回去睡了。'),
('CNV', '撒母耳记上', 9, 3, 6, '耶和华再次呼唤撒母耳，他就起来走到以利那里，说：“你呼唤我，我在这里。”以利说：“我儿，我没有呼唤你，回去睡吧。”'),
('CNV', '撒母耳记上', 9, 3, 7, '那时撒母耳还没有认识耶和华，因为耶和华的话还没有向他启示。'),
('CNV', '撒母耳记上', 9, 3, 8, '耶和华第三次呼唤撒母耳，他又起来，走到以利那里，说：“你呼唤我，我在这里。”以利就明白是耶和华呼唤这孩子。'),
('CNV', '撒母耳记上', 9, 3, 9, '因此以利对撒母耳说：“去睡吧！如果他呼唤你，你就说：‘耶和华啊！请说，仆人敬听。’”于是撒母耳回去，仍然睡在自己的地方。'),
('CNV', '撒母耳记上', 9, 3, 10, '耶和华又来站着，像前几次一样呼唤：“撒母耳，撒母耳！”他回答：“请说！仆人敬听。”'),
('CNV', '撒母耳记上', 9, 3, 11, '耶和华对撒母耳说：“看哪！我要在以色列中行一件事，听见的人，都必耳鸣；'),
('CNV', '撒母耳记上', 9, 3, 12, '在那日，我必在以利身上彻底实现我论到他的家所说的一切话。'),
('CNV', '撒母耳记上', 9, 3, 13, '我曾告诉他：‘我必按着他所知道的罪孽永远处罚他的家。这罪就是他的儿子自招咒诅，他也不责备他们。’'),
('CNV', '撒母耳记上', 9, 3, 14, '所以我向以利家起了誓：‘以利家的罪孽永远不能用祭物或供物来买赎。’”'),
('CNV', '撒母耳记上', 9, 3, 15, '撒母耳睡到天亮，他就开了耶和华殿的门。但撒母耳不敢把异象告诉以利。'),
('CNV', '撒母耳记上', 9, 3, 16, '以利呼唤撒母耳，说：“我儿撒母耳！”他回答：“我在这里。”'),
('CNV', '撒母耳记上', 9, 3, 17, '以利说：“耶和华对你说了什么话呢？你不要向我隐瞒，他对你所说的一切话，如果你向我隐瞒一句，愿神对付你，并且加倍对付你。”'),
('CNV', '撒母耳记上', 9, 3, 18, '于是撒母耳把一切话都告诉了以利，一句也没有隐瞒。以利说：“他是耶和华，他看怎么好，就怎么行吧。”'),
('CNV', '撒母耳记上', 9, 3, 19, '撒母耳渐渐长大，耶和华与他同在，使他所说的一切话，没有一句落空。'),
('CNV', '撒母耳记上', 9, 3, 20, '从但到别是巴，以色列人都知道撒母耳被耶和华确立为先知。'),
('CNV', '撒母耳记上', 9, 3, 21, '耶和华又在示罗显现，因为耶和华在示罗藉着他的话向撒母耳启示自己。'),
('CNV', '撒母耳记上', 9, 4, 1, '撒母耳的话传遍了以色列。那时，以色列人出去迎战非利士人，他们靠近以便以谢安营，非利士人却在亚弗安营。'),
('CNV', '撒母耳记上', 9, 4, 2, '非利士人列阵，要与以色列人交战。战事展开后，以色列人败在非利士人面前，非利士人在战场上杀了约四千人。'),
('CNV', '撒母耳记上', 9, 4, 3, '军队回到营里，以色列的长老说：“今天耶和华为什么在非利士人面前击败我们呢？我们要把耶和华的约柜从示罗抬到我们这里来。约柜一到我们中间，就会拯救我们脱离仇敌的手。”'),
('CNV', '撒母耳记上', 9, 4, 4, '于是他们派人到示罗去，从那里把坐在二基路伯中间万军之耶和华的约柜抬来；以利的两个儿子，何弗尼和非尼哈，也与神的约柜一同来了。'),
('CNV', '撒母耳记上', 9, 4, 5, '耶和华的约柜来到营中的时候，以色列众人就大声欢呼，大地也回声响应。'),
('CNV', '撒母耳记上', 9, 4, 6, '非利士人听见了欢呼的声音，就问：“在希伯来人的营中为什么有这样大声的欢呼呢？”后来才知道耶和华的约柜来到了营中。'),
('CNV', '撒母耳记上', 9, 4, 7, '非利士人就害怕起来，他们说：“有神来到他们的营中了。”又说：“我们有祸了！因为从来没有这样的事。'),
('CNV', '撒母耳记上', 9, 4, 8, '我们有祸了！从前在旷野用各样灾祸击打埃及人的，就是这些神。谁能救我们脱离这些大能之神的手呢？'),
('CNV', '撒母耳记上', 9, 4, 9, '非利士人哪！你们要刚强，要作大丈夫，免得你们作希伯来人的奴仆，好像他们作过你们的奴仆一样；你们要作大丈夫，作战吧！”'),
('CNV', '撒母耳记上', 9, 4, 10, '于是非利士人起来作战，以色列人就被击败，各人都往自己的帐棚逃跑。这是一场大屠杀，以色列人中有三万步兵阵亡。'),
('CNV', '撒母耳记上', 9, 4, 11, '神的约柜也被抢去，以利的两个儿子何弗尼和非尼哈也死了。'),
('CNV', '撒母耳记上', 9, 4, 12, '有一个便雅悯人跑离战场，衣服撕裂，头蒙尘土，当天来到示罗。'),
('CNV', '撒母耳记上', 9, 4, 13, '他来到的时候，以利正在路旁坐在自己的椅子上观望，因为他为神的约柜担忧战栗。那人进城里报信，全城的人就都喊叫起来。'),
('CNV', '撒母耳记上', 9, 4, 14, '以利听见喊叫的声音，就问：“这喧嚷的声音是什么意思呢？”那人急忙前来，向以利报告。'),
('CNV', '撒母耳记上', 9, 4, 15, '那时以利九十八岁了，眼睛发直，不能看见。'),
('CNV', '撒母耳记上', 9, 4, 16, '那人告诉以利：“我是从战场上来的，今天从战场上逃回来。”以利问：“我儿，事情怎么样？”'),
('CNV', '撒母耳记上', 9, 4, 17, '报信的人回答，说：“以色列人在非利士人面前逃跑，伤亡惨重，你两个儿子何弗尼和非尼哈也都死了，民中被杀的甚多，神的约柜也被抢去了。”'),
('CNV', '撒母耳记上', 9, 4, 18, '因为以利年老体重，报信的人一提到神的约柜，以利就从椅子上往后跌倒在门旁，颈骨折断而死。以利治理了以色列四十年。'),
('CNV', '撒母耳记上', 9, 4, 19, '以利的媳妇，非尼哈的妻子怀了孕，产期近了；她一听见神的约柜被抢去，以及她公公和丈夫都死了的消息，就忽然感到疼痛，曲身生产了。'),
('CNV', '撒母耳记上', 9, 4, 20, '她快要死的时候，站在旁边的妇女们对她说：“不要怕，你生了一个儿子！”她却不回答，也不理会。'),
('CNV', '撒母耳记上', 9, 4, 21, '她给孩子起名叫以迦博，说：“荣耀已经离开以色列了。”这是因为神的约柜被抢去，又因为她的公公和丈夫都死了。'),
('CNV', '撒母耳记上', 9, 4, 22, '她说：“荣耀已经离开了以色列，因为神的约柜被抢去了。”'),
('CNV', '撒母耳记上', 9, 5, 1, '非利士人抢去了神的约柜，就把它从以便以谢运到亚实突。'),
('CNV', '撒母耳记上', 9, 5, 2, '非利士人抢去神的约柜，把它抬进大衮庙，放在大衮神像的旁边。'),
('CNV', '撒母耳记上', 9, 5, 3, '第二天清早，亚实突人起来，看见大衮神像仆倒在地，俯伏在耶和华的约柜面前。他们就把大衮神像竖立起来，放回原处。'),
('CNV', '撒母耳记上', 9, 5, 4, '再次日早晨，他们起来的时候，看见大衮神像又仆倒在地，俯伏在耶和华的约柜面前，大衮的头和双手也都在门槛上折断了，只剩下大衮的身体。'),
('CNV', '撒母耳记上', 9, 5, 5, '因此大衮的祭司和所有进亚实突大衮庙的人，都不踏大衮庙的门槛，直到现在。'),
('CNV', '撒母耳记上', 9, 5, 6, '耶和华的手重重地压在亚实突人身上，败坏他们，用痔疮击打亚实突和亚实突四境的人。'),
('CNV', '撒母耳记上', 9, 5, 7, '亚实突人看见这种情形，就说：“以色列神的约柜不可再留在我们这里，因为他的手重重地加在我们和我们的神大衮身上。”'),
('CNV', '撒母耳记上', 9, 5, 8, '他们就派人去召集非利士人各城的首领前来，问他们：“我们要怎样处理以色列神的约柜呢？”他们回答：“把以色列神的约柜运到迦特去吧。”他们就把它运到迦特去了。'),
('CNV', '撒母耳记上', 9, 5, 9, '运到那里以后，耶和华的手攻击那城，引起很大的恐慌。他击打全城的人，不分老幼，使痔疮在他们中间蔓延。'),
('CNV', '撒母耳记上', 9, 5, 10, '于是他们把神的约柜送到以革伦。神的约柜到了以革伦的时候，以革伦人就喊叫：“他们把以色列神的约柜运到我们这里来，是要杀害我们和我们的人啊！”'),
('CNV', '撒母耳记上', 9, 5, 11, '于是他们派人去召集非利士人各城的首领前来，对他们说：“请把以色列神的约柜送回原处，免得它杀害我们和我们的人民。”死亡的恐慌笼罩全城，因为神的手重重地压在那里。'),
('CNV', '撒母耳记上', 9, 5, 12, '没有死的人都遭受痔疮的打击；那城的哀声，上达于天。'),
('CNV', '撒母耳记上', 9, 6, 1, '耶和华的约柜在非利士人的地方有七个月之久。'),
('CNV', '撒母耳记上', 9, 6, 2, '非利士人把众祭司和占卜的都召了来，问他们：“我们应该怎样处理耶和华的约柜呢？请告诉我们，要怎样才能把它送回原处呢？”'),
('CNV', '撒母耳记上', 9, 6, 3, '他们回答：“你们把以色列神的约柜送回去的时候，不可空空地把它送回去，却要偿还赔罪的礼物，这样，你们就可以得着医治，也可以知道，为什么他的手没有离开你们。”'),
('CNV', '撒母耳记上', 9, 6, 4, '非利士人问：“我们应当偿给他什么作赔罪的礼物呢？”他们回答：“要按照非利士人各城首领的数目，用五个金痔疮和五只金老鼠作赔罪的礼物，因为你们所有的人和你们各城的首领所遭遇的，都是一样的灾祸。'),
('CNV', '撒母耳记上', 9, 6, 5, '所以你们要做痔疮的像和毁坏田地的老鼠的像，还要把荣耀归给以色列的神。也许他会向你们、你们的神和你们的田地手下留情。'),
('CNV', '撒母耳记上', 9, 6, 6, '你们为什么要硬着心，像以前埃及人和法老那样呢？神严严地对付他们以后，他们不是放走了以色列人，以色列人不是真的离开了吗？'),
('CNV', '撒母耳记上', 9, 6, 7, '现在你们要预备一辆新车和两头仍在乳养小牛、未曾负过轭的母牛，把它们紧紧套在车上，把小牛从它们身边带回棚里去。'),
('CNV', '撒母耳记上', 9, 6, 8, '你们要把耶和华的约柜搬来，放在车上，把那些偿给他作赔罪礼物的金器放在盒子里，放置在约柜旁边，然后把它送上路，让它自己走。'),
('CNV', '撒母耳记上', 9, 6, 9, '你们要留意看，如果它是走向自己的境界，往伯．示麦去，那么就是耶和华降这大灾给我们；如果不是这样，我们就知道，不是他的手攻击我们，我们遭遇的不过是偶然的事。”'),
('CNV', '撒母耳记上', 9, 6, 10, '非利士人就照着去行。他们牵来两头还在乳养小牛的母牛，把它们紧紧套在车上，把小牛关在棚里。'),
('CNV', '撒母耳记上', 9, 6, 11, '他们又把耶和华的约柜，装金老鼠和痔疮像的盒子，都放在车上。'),
('CNV', '撒母耳记上', 9, 6, 12, '牛向着伯．示麦的路上直奔，如同走在一条大路上，一面走一面叫，不偏左也不偏右。非利士各城的首领在后面跟着走，直到伯．示麦的边界。'),
('CNV', '撒母耳记上', 9, 6, 13, '那时，伯．示麦人正在谷中收割麦子，他们举目观看，看见了约柜，就欢欢喜喜迎见约柜。'),
('CNV', '撒母耳记上', 9, 6, 14, '牛车到了伯．示麦人约书亚的田间，就停在那里；那里有一块大石，他们把做那车的木料劈开，又把那两只母牛作燔祭献给耶和华。'),
('CNV', '撒母耳记上', 9, 6, 15, '利未人把耶和华的约柜，与它一同送来装有金器的盒子，都搬了下来，放在大石上；那一天，伯．示麦人向耶和华献上燔祭，又献上其他的祭。'),
('CNV', '撒母耳记上', 9, 6, 16, '非利士人的五个首领看见了，当天就回以革伦去。'),
('CNV', '撒母耳记上', 9, 6, 17, '这些金痔疮，就是非利士人偿给耶和华作赔罪的礼物的，一个是为亚实突，一个是为迦萨，一个是为亚实基伦，一个是为迦特，一个是为以革伦。'),
('CNV', '撒母耳记上', 9, 6, 18, '金老鼠的数目是按照非利士人五个首领所有的城市的数目，包括设防城和乡村。他们安放耶和华约柜的那块大石，直到现在还是在伯．示麦人约书亚的田间，是一个证物。'),
('CNV', '撒母耳记上', 9, 6, 19, '耶和华因为伯．示麦人偷窥他的约柜，就击杀他们；他击杀了七十人（“七十人”大多数文本都作“五万零七十人”，少数文本作“七十人”）。众人因为耶和华用大灾击杀他们，就哀哭起来。'),
('CNV', '撒母耳记上', 9, 6, 20, '伯．示麦人说：“在耶和华这位圣洁的神面前，谁能站立得住呢？他可以从我们这里上到哪里去呢？”'),
('CNV', '撒母耳记上', 9, 6, 21, '于是他们派遣使者到基列．耶琳的居民那里去，对他们说：“非利士人把耶和华的约柜送回来了。你们下来把它接到你们那里去吧。”'),
('CNV', '撒母耳记上', 9, 7, 1, '基列．耶琳人就前来，把耶和华的约柜抬上去；他们把它抬到山上亚比拿达的家中，又把他的儿子以利亚撒分别为圣，看守耶和华的约柜。'),
('CNV', '撒母耳记上', 9, 7, 2, '约柜停留在基列．耶琳很久，有二十年之久，以色列全家都痛悔寻求耶和华。'),
('CNV', '撒母耳记上', 9, 7, 3, '于是撒母耳对以色列全家说：“如果你们一心归向耶和华，就当把外族的神和亚斯他录从你们中间除掉，专心归向耶和华，单单事奉他，他必救你们脱离非利士人的手。”'),
('CNV', '撒母耳记上', 9, 7, 4, '以色列人就除掉众巴力和亚斯他录，单单事奉耶和华。'),
('CNV', '撒母耳记上', 9, 7, 5, '撒母耳又说：“你们要把以色列众人都聚集在米斯巴，我好为你们向耶和华祷告。”'),
('CNV', '撒母耳记上', 9, 7, 6, '于是，他们聚集在米斯巴，打了水，浇奠在耶和华面前；当日他们禁食，并且在那里说：“我们得罪了耶和华。”撒母耳就在米斯巴治理以色列人。'),
('CNV', '撒母耳记上', 9, 7, 7, '非利士人听见以色列人集合在米斯巴，各城的领袖就上来攻打以色列人；以色列人听见了，都害怕起来。'),
('CNV', '撒母耳记上', 9, 7, 8, '以色列人对撒母耳说：“请你不要静默，为我们呼求耶和华我们的神吧，好叫他拯救我们脱离非利士人的手。”'),
('CNV', '撒母耳记上', 9, 7, 9, '撒母耳就牵来一只还在吃奶的羊羔，把它作全牲的燔祭献给耶和华，又为以色列人向耶和华呼求，耶和华就应允他。'),
('CNV', '撒母耳记上', 9, 7, 10, '撒母耳正在献上燔祭的时候，非利士人前来要与以色列人争战。当天，耶和华发出极大的雷声，攻击非利士人，使他们溃乱，他们就在以色列人面前被击败。'),
('CNV', '撒母耳记上', 9, 7, 11, '于是以色列人从米斯巴出去，追赶非利士人，击杀他们，直到伯．甲的下边。'),
('CNV', '撒母耳记上', 9, 7, 12, '撒母耳搬来了一块石头，把它竖立在米斯巴和善之间，给这块石头起名叫以便以谢，说：“直到现在，耶和华都帮助我们。”'),
('CNV', '撒母耳记上', 9, 7, 13, '这样，非利士人就被制伏了，不再侵犯以色列的境界。撒母耳在世的日子，耶和华的手一直攻击非利士人。'),
('CNV', '撒母耳记上', 9, 7, 14, '非利士人从以色列人夺得的城市，自以革伦直到迦特，都归还以色列人；属于这些城市的四境，以色列人也从非利士人手中夺回。那时，以色列人和亚摩利人和平相处。'),
('CNV', '撒母耳记上', 9, 7, 15, '撒母耳终生作以色列人的士师。'),
('CNV', '撒母耳记上', 9, 7, 16, '他每年都巡回伯特利、吉甲和米斯巴，在这些地方治理以色列人。'),
('CNV', '撒母耳记上', 9, 7, 17, '然后，他回到拉玛，因为他的家在那里。他也在那里治理以色列人，并且在那里为耶和华筑了一座祭坛。'),
('CNV', '撒母耳记上', 9, 8, 1, '撒母耳年老的时候，立了他的儿子作以色列人的士师。'),
('CNV', '撒母耳记上', 9, 8, 2, '他的长子名叫约珥，次子名叫亚比亚，都在别是巴作士师。'),
('CNV', '撒母耳记上', 9, 8, 3, '两个儿子都没有行撒母耳的道路，反而转去追求不义之财，收受贿赂，屈枉正直。'),
('CNV', '撒母耳记上', 9, 8, 4, '于是以色列所有的长老都集合起来，到拉玛去见撒母耳，'),
('CNV', '撒母耳记上', 9, 8, 5, '对他说：“你老了，看哪，你的儿子不行你的道路，现在求你为我们立一个王治理我们，好像列国一样。”'),
('CNV', '撒母耳记上', 9, 8, 6, '他们说“求你为我们立一个王治理我们”这件事，使撒母耳很不高兴，他就祷告耶和华。'),
('CNV', '撒母耳记上', 9, 8, 7, '耶和华对撒母耳说：“众民对你所说的一切，你只管听从，因为他们不是厌弃你，而是厌弃我，不要我作他们的王。'),
('CNV', '撒母耳记上', 9, 8, 8, '自从我把他们从埃及领上来的那天起，直到现在，他们怎样离开我，事奉别的神，他们对我所行的一切，也照样对你行。'),
('CNV', '撒母耳记上', 9, 8, 9, '现在你只管听从他们的话，但必须郑重警告他们，告诉他们那要统治他们的王要怎样治理他们。”'),
('CNV', '撒母耳记上', 9, 8, 10, '于是，撒母耳把耶和华所讲的一切话都告诉那些向他要求一个王的民众，'),
('CNV', '撒母耳记上', 9, 8, 11, '说：“那要统治你们的王将这样治理你们：他必征用你们的儿子，派他们作他的战车兵、骑兵、在车前奔走的前锋，'),
('CNV', '撒母耳记上', 9, 8, 12, '又派他们作千夫长、五十夫长，替他耕田、收他的庄稼、替他制造作战的武器和战车上的装备。'),
('CNV', '撒母耳记上', 9, 8, 13, '他必征用你们的女儿作配香膏的、烧饭的和烤饼的。'),
('CNV', '撒母耳记上', 9, 8, 14, '他必夺去你们最好的田地、葡萄园和橄榄园，赐给自己的臣仆。'),
('CNV', '撒母耳记上', 9, 8, 15, '你们撒种所得的和葡萄园所出的，他都征收十分之一，赐给他的太监和臣仆。'),
('CNV', '撒母耳记上', 9, 8, 16, '他又必征收你们的仆婢、最精壮的青年和驴，替他工作。'),
('CNV', '撒母耳记上', 9, 8, 17, '你们的羊群，他要征收十分之一；连你们自己也作他的奴仆。'),
('CNV', '撒母耳记上', 9, 8, 18, '到时，你们必因你们为自己拣选的王而哀求，那时耶和华却不应允你们。”'),
('CNV', '撒母耳记上', 9, 8, 19, '众民竟不肯听从撒母耳的话，说：“不，我们要一个王治理我们，'),
('CNV', '撒母耳记上', 9, 8, 20, '让我们也像列国一样，有自己的王治理我们，帅领我们出征，为我们作战。”'),
('CNV', '撒母耳记上', 9, 8, 21, '撒母耳听了众民的一切话，就向耶和华复述。'),
('CNV', '撒母耳记上', 9, 8, 22, '耶和华对撒母耳说：“你只管听从他们的话，为他们立一个王。”于是撒母耳对以色列人说：“你们各人回自己的城去吧。”'),
('CNV', '撒母耳记上', 9, 9, 1, '有一个便雅悯人，名叫基士，是亚别的儿子。亚别是洗罗的儿子，洗罗是比歌拉的儿子，比歌拉是亚斐亚的儿子。（这便雅悯人是个大财主。）'),
('CNV', '撒母耳记上', 9, 9, 2, '他有一个儿子，名叫扫罗，既年轻又英俊；在以色列人中，没有一个能比他更英俊的。他比人高出一个头。'),
('CNV', '撒母耳记上', 9, 9, 3, '扫罗的父亲基士有几头母驴走失了，他就对他的儿子扫罗说：“你带一个仆人，动身去寻找母驴吧！”'),
('CNV', '撒母耳记上', 9, 9, 4, '扫罗走遍以法莲山地，又走遍沙利沙地，但他们都没有找到。他们又走遍沙琳地，母驴也不在那里；又走遍便雅悯地，还是找不到。'),
('CNV', '撒母耳记上', 9, 9, 5, '他们到了苏弗地，扫罗对跟随他的仆人说：“来，我们回去吧，恐怕我父亲不为母驴挂心，反而为我们担忧了。”'),
('CNV', '撒母耳记上', 9, 9, 6, '仆人对他说：“看哪，这城里有一位神人，很受人敬重，他所说的，都必应验。现在，我们到他那里去吧，也许他会告诉我们当走的路。”'),
('CNV', '撒母耳记上', 9, 9, 7, '扫罗对仆人说：“如果我们去，有什么可以送给那人呢？因为我们袋里的食物都已经用尽了，也没有礼物可以送给那神人，我们还有什么呢？”'),
('CNV', '撒母耳记上', 9, 9, 8, '仆人回答扫罗：“看哪！我手里有三克银子，可以送给那神人，请他告诉我们应该走的路。”'),
('CNV', '撒母耳记上', 9, 9, 9, '从前在以色列中，有人去求问神的时候，就这样说：“来，我们去见先见吧。”因为今天称为先知的，从前称为先见。'),
('CNV', '撒母耳记上', 9, 9, 10, '扫罗对仆人说：“你说的好。来，我们去吧！”于是他们到那神人所住的城里去。'),
('CNV', '撒母耳记上', 9, 9, 11, '他们正上山坡要进城的时候，就遇见几个少女出来打水。他们就问那些少女：“先见在这里吗？”'),
('CNV', '撒母耳记上', 9, 9, 12, '那些少女回答他们说：“在这里！他就在你们前面，现在快去吧！他今天正到这城里来，因为今天在邱坛上，人民有献祭的事。'),
('CNV', '撒母耳记上', 9, 9, 13, '你们一进城，在他登上邱坛吃祭物之前，必遇见他。因为他未到，众人不能先吃，他必先为祭物祝谢，然后客人才可以吃。现在你们上去吧！今天，你们必可遇见他。”'),
('CNV', '撒母耳记上', 9, 9, 14, '于是二人上那城去；他们正进城的时候，撒母耳就迎着他们出来，要上邱坛去。'),
('CNV', '撒母耳记上', 9, 9, 15, '原来，在扫罗来到的前一天，耶和华已经启示撒母耳说：'),
('CNV', '撒母耳记上', 9, 9, 16, '“明天大约这个时候，我要差派一个人从便雅悯地到你那里去，你要膏立他作我子民以色列人的领袖。他要拯救我的子民脱离非利士人的手。我眷顾了我的子民，因为他们的哀求已经达到我这里。”'),
('CNV', '撒母耳记上', 9, 9, 17, '撒母耳看见了扫罗，耶和华就对撒母耳说：“你看，这就是我对你所说的那人，他要统治我的子民。”'),
('CNV', '撒母耳记上', 9, 9, 18, '扫罗在城门口，走近撒母耳跟前，说：“请告诉我先见的家在哪里？”'),
('CNV', '撒母耳记上', 9, 9, 19, '撒母耳回答扫罗：“我就是先见，请你在我前面上邱坛去。今天你们要与我一同吃饭，明天早晨我就送你回去。你心里的一切事，我都会告诉你。'),
('CNV', '撒母耳记上', 9, 9, 20, '至于你前三天失了的母驴，你不必为它们担心，因为都已经找到了。以色列众人所渴求的是谁呢？不是你和你的父家吗？”'),
('CNV', '撒母耳记上', 9, 9, 21, '扫罗回答：“我不是以色列众支派中最微小的便雅悯人吗？我的家族不是便雅悯支派的家族中最微小的吗？你为什么对我说这样的话呢？”'),
('CNV', '撒母耳记上', 9, 9, 22, '撒母耳把扫罗和扫罗的仆人领进了客厅，使他们坐在客人中的首位；那里约有三十人。'),
('CNV', '撒母耳记上', 9, 9, 23, '撒母耳对厨师说：“我交给你，吩咐你存放好的那一份祭肉，现在可以拿来。”'),
('CNV', '撒母耳记上', 9, 9, 24, '厨师就把那条腿肉拿上来，摆在扫罗面前。撒母耳说：“这是为你留下的，现在摆在你面前，请吃吧！因为这是我邀请众人的时候，特地为这时刻保留的。”于是，当天扫罗就与撒母耳一同吃饭。'),
('CNV', '撒母耳记上', 9, 9, 25, '他们从邱坛下来，进到城里；撒母耳和扫罗在房顶上说话。'),
('CNV', '撒母耳记上', 9, 9, 26, '他们清早起来；天快亮的时候，撒母耳在房顶上呼叫扫罗说：“起来吧，我要送你回去。”扫罗就起来。于是，他与撒母耳二人一起到外面去。'),
('CNV', '撒母耳记上', 9, 9, 27, '他们下到城边的时候，撒母耳对扫罗说：“吩咐你的仆人先走。（仆人就先走了。）你暂且留在这里，我好把神的话讲给你听。”'),
('CNV', '撒母耳记上', 9, 10, 1, '撒母耳拿了一瓶膏油，倒在扫罗的头上，又与他亲吻，说：“耶和华不是已经膏立你作他产业的领袖吗？'),
('CNV', '撒母耳记上', 9, 10, 2, '今天你离开我以后，在便雅悯境内的泄撒，靠近拉结坟墓的旁边，必遇见两个人。他们会对你说：‘你去寻找的那几头母驴已经找到了。现在你父亲放下了母驴的事，反而为你担忧，说：我为我的儿子要怎么办呢？’'),
('CNV', '撒母耳记上', 9, 10, 3, '你要从那里再往前去，直到他泊的橡树那里，必遇见三个上伯特利去敬拜神的人，一个带着三只山羊羔，一个带着三个饼，一个带着一皮袋酒。'),
('CNV', '撒母耳记上', 9, 10, 4, '他们必向你问安，并且给你两个饼，你要从他们手中接过来。'),
('CNV', '撒母耳记上', 9, 10, 5, '然后，你要到神的山去，那里有非利士人的驻军。你进城的时候，会遇见一班先知从邱坛上下来。在他们前面有鼓瑟的、打鼓的、吹笛的、弹琴的。他们都受感说话。'),
('CNV', '撒母耳记上', 9, 10, 6, '耶和华的灵必大大感动你，你就要与他们一同受感说话，变成另一个人。'),
('CNV', '撒母耳记上', 9, 10, 7, '这些征兆临到你的时候，你就可以见机行事，因为神与你同在。'),
('CNV', '撒母耳记上', 9, 10, 8, '你要在我以先下到吉甲去，我也要下到你那里去献燔祭和平安祭。你要等候七天，等我到了你那里，指示你所当行的。”'),
('CNV', '撒母耳记上', 9, 10, 9, '扫罗转身离开撒母耳的时候，神就改变了他，赐给他一颗新心。那一天，这一切征兆都实现了。'),
('CNV', '撒母耳记上', 9, 10, 10, '扫罗到了那山，有一班先知迎面而来。神的灵大大感动他，他就在他们中间受感说话。'),
('CNV', '撒母耳记上', 9, 10, 11, '所有以前认识扫罗的人，看见他和他们一起受感说话，就彼此说：“基士的儿子怎么啦！扫罗也列在先知中间吗？”'),
('CNV', '撒母耳记上', 9, 10, 12, '那里有一个人回答：“这些人的父亲是谁呢？”因此，后来有句俗语说：“扫罗也列在先知中间吗？”'),
('CNV', '撒母耳记上', 9, 10, 13, '扫罗受感说话完了以后，就到邱坛去了。'),
('CNV', '撒母耳记上', 9, 10, 14, '扫罗的叔叔问扫罗和他的仆人说：“你们到哪里去了？”他回答：“找母驴去。我们找不到，就去见撒母耳。”'),
('CNV', '撒母耳记上', 9, 10, 15, '扫罗的叔叔说：“你把撒母耳对你们所说的话告诉我。”'),
('CNV', '撒母耳记上', 9, 10, 16, '扫罗对他叔叔说：“他清楚地告诉我们，母驴已经找到了。”至于撒母耳所说有关王国的事，扫罗却没有告诉他的叔叔。'),
('CNV', '撒母耳记上', 9, 10, 17, '撒母耳召集众民到米斯巴耶和华那里，'),
('CNV', '撒母耳记上', 9, 10, 18, '对他们说：“耶和华以色列的神这样说：‘我把你们以色列人从埃及带上来，我救你们脱离埃及人的手，又救你们脱离所有欺压你们的列国人的手。’'),
('CNV', '撒母耳记上', 9, 10, 19, '你们今天却离弃了那位拯救你们脱离一切灾难和困苦的神，竟对他说：‘求你立一个王统治我们。’现在你们要按着你们的支派和家族，站在耶和华面前。”'),
('CNV', '撒母耳记上', 9, 10, 20, '撒母耳使以色列众支派都近前来，抽签抽中了便雅悯支派；'),
('CNV', '撒母耳记上', 9, 10, 21, '他又使便雅悯支派按着家族近前来，抽签抽中了马特利族；再抽签抽中了基士的儿子扫罗。众人寻找他，却找不到。'),
('CNV', '撒母耳记上', 9, 10, 22, '于是他们求问耶和华：“那人到这里来了没有？”耶和华说：“他躲在那些物件中。”'),
('CNV', '撒母耳记上', 9, 10, 23, '他们就跑过去，把他从那里领出来；他站在众人中间，比众人都高出一个头。'),
('CNV', '撒母耳记上', 9, 10, 24, '撒母耳对众民说：“你们看见耶和华所拣选的人没有？在众人中没有一个可与他相比。”众人就大声欢呼：“愿王万岁！”'),
('CNV', '撒母耳记上', 9, 10, 25, '撒母耳把国法对众人述说了，又记在书上，存放在耶和华面前，然后遣散众人，各回自己的家去了。'),
('CNV', '撒母耳记上', 9, 10, 26, '扫罗也回基比亚自己的家里去了，有一些勇士与他一起回去；他们的心都被神感动。'),
('CNV', '撒母耳记上', 9, 10, 27, '但是有些流氓说：“这人怎能拯救我们呢？”就藐视他，也没有送他礼物。扫罗却没有说什么。'),
('CNV', '撒母耳记上', 9, 11, 1, '亚扪人拿辖上来，安营攻击基列．雅比。所有的雅比人都对拿辖说：“你与我们立约，我们就服事你。”'),
('CNV', '撒母耳记上', 9, 11, 2, '亚扪人拿辖对他们说：“这是我与你们立约的条件：我要剜出你们各人的右眼，用来羞辱以色列众人。”'),
('CNV', '撒母耳记上', 9, 11, 3, '雅比的长老对他说：“请你宽限我们七天，好让我们派遣使者到以色列的全境去；如果没有人拯救我们，我们就出来向你投降。”'),
('CNV', '撒母耳记上', 9, 11, 4, '使者到了扫罗住的基比亚，把这些话说给众民听，众民就都放声大哭。'),
('CNV', '撒母耳记上', 9, 11, 5, '那时，扫罗正从田里赶牛回来，问说：“什么事啊？为什么人都在哭呢？”于是有人把雅比人的话告诉他。'),
('CNV', '撒母耳记上', 9, 11, 6, '扫罗听了这些话，神的灵大大感动他，他就非常忿怒。'),
('CNV', '撒母耳记上', 9, 11, 7, '他牵来一对牛，把它们切成碎块，交给使者，送到以色列的全境去，说：“不出来跟从扫罗和撒母耳的，他的牛也必受到这样的对待。”因众民惧怕耶和华，他们就都出来，如同一人。'),
('CNV', '撒母耳记上', 9, 11, 8, '扫罗在比色数点他们。以色列人共有三十万，犹大人有三万。'),
('CNV', '撒母耳记上', 9, 11, 9, '扫罗对前来的使者说：“你们要这样对基列．雅比人说：‘明天中午，你们必得拯救。’”使者回去告诉基列．雅比人，他们就欢喜了。'),
('CNV', '撒母耳记上', 9, 11, 10, '雅比人对亚扪人说：“明天我们出来向你们投降，你们看怎么好，就怎么待我们吧。”'),
('CNV', '撒母耳记上', 9, 11, 11, '第二天，扫罗把众人分成三队。在晨更的时候，他们进了亚扪人的营中，击杀他们，直到中午；残余的人都星散了，他们中间没有两个人留在一起的。'),
('CNV', '撒母耳记上', 9, 11, 12, '众民对撒母耳说：“那说‘扫罗怎能作我们的王’的是谁呢？把那些人交出来，我们好杀死他们。”'),
('CNV', '撒母耳记上', 9, 11, 13, '扫罗说：“今天不可以杀人，因为今天是耶和华在以色列中施行拯救的日子。”'),
('CNV', '撒母耳记上', 9, 11, 14, '撒母耳对众民说：“来吧，我们往吉甲去，好在那里重新建立王国。”'),
('CNV', '撒母耳记上', 9, 11, 15, '众民就都到吉甲去，在那里在耶和华面前立扫罗为王，又在那里在耶和华面前献平安祭。扫罗和以色列众民都在那里，非常欢喜。'),
('CNV', '撒母耳记上', 9, 12, 1, '撒母耳对以色列人说：“看哪！我已经听从了你们向我所说的一切话，为你们立了一个王。'),
('CNV', '撒母耳记上', 9, 12, 2, '现在，有这王领导你们。至于我，我已经年老发白，我的儿子也都在你们那里；我自幼年直到今日都领导你们。'),
('CNV', '撒母耳记上', 9, 12, 3, '看哪，我在这里！你们只管在耶和华面前，以及在他的受膏者面前，作证指控我：我夺过谁的牛？抢过谁的驴？欺负过谁？虐待过谁？从谁手里受过贿赂，以致我的眼睛因此被蒙住呢？如果有，我必偿还给你们。”'),
('CNV', '撒母耳记上', 9, 12, 4, '他们回答：“你没有欺负过我们，没有虐待过我们，也没有从谁手里取过什么东西。”'),
('CNV', '撒母耳记上', 9, 12, 5, '撒母耳对他们说：“今天耶和华在你们中间作见证，他的膏立者也作见证；你们在我手里没有找到什么。”他们说：“愿他作证。”'),
('CNV', '撒母耳记上', 9, 12, 6, '撒母耳对人民说：“从前选立摩西和亚伦，又把你们的列祖从埃及地领上来的，是耶和华。'),
('CNV', '撒母耳记上', 9, 12, 7, '现在你们要站住，我要在耶和华面前与你们讲论耶和华向你们和你们的列祖所行一切公义的事。'),
('CNV', '撒母耳记上', 9, 12, 8, '从前雅各到了埃及，后来你们的列祖哀求耶和华，耶和华就差遣摩西和亚伦去把你们的列祖从埃及领出来，又使他们在这地方居住。'),
('CNV', '撒母耳记上', 9, 12, 9, '他们却忘记了耶和华他们的神，神就把他们交在夏琐的将军西西拉的手中，以及非利士人和摩押王的手中，于是这些人常常攻打他们。'),
('CNV', '撒母耳记上', 9, 12, 10, '他们就哀求耶和华，说：‘我们犯了罪，因为我们背弃了耶和华，又去服事巴力和亚斯他录。现在求你救我们脱离仇敌的手，我们就必事奉你。’'),
('CNV', '撒母耳记上', 9, 12, 11, '于是耶和华差遣耶路．巴力、比但、耶弗他、撒母耳，救你们脱离四围仇敌的手，你们才可以安然居住。'),
('CNV', '撒母耳记上', 9, 12, 12, '可是，你们看到亚扪王拿辖来攻击你们，就对我说：‘不行，我们要有一个王来统治我们。’其实，耶和华你们的神是你们的王。'),
('CNV', '撒母耳记上', 9, 12, 13, '现在，你们所拣选、所要求的王在这里。看哪！耶和华已经立了一个王统治你们。'),
('CNV', '撒母耳记上', 9, 12, 14, '如果你们敬畏耶和华，事奉他，听从他的话，不违背他的命令，你们和统治你们的王就必跟从耶和华你们的神。'),
('CNV', '撒母耳记上', 9, 12, 15, '但是，如果你们不听从耶和华的话，违背他的命令，耶和华的手就必攻击你们，好像攻击你们的列祖一样。'),
('CNV', '撒母耳记上', 9, 12, 16, '现在你们要站着，看耶和华在你们眼前将要施行的这件大事。'),
('CNV', '撒母耳记上', 9, 12, 17, '现今不是收割麦子的时候吗？我要向耶和华呼求，他就会打雷降雨，你们就可以知道，又可以看见，你们为自己要求立王的事，在耶和华看来，是行了极大的恶事。”'),
('CNV', '撒母耳记上', 9, 12, 18, '于是撒母耳向耶和华呼求，耶和华就在那天打雷降雨，众民就非常惧怕耶和华和撒母耳。'),
('CNV', '撒母耳记上', 9, 12, 19, '众民对撒母耳说：“求你为仆人向耶和华你的神祷告，免得我们死亡，因为我们为自己要求立王的事，是在我们的一切罪上又增加了这一件恶事。”'),
('CNV', '撒母耳记上', 9, 12, 20, '撒母耳对人民说：“不要惧怕！虽然你们行了这一切恶事，只是不可偏离不跟随耶和华，总要一心事奉他。'),
('CNV', '撒母耳记上', 9, 12, 21, '不可偏离耶和华，去追随那些空虚的偶像，因为它们本是空虚的，对人没有什么益处，也不能救人。'),
('CNV', '撒母耳记上', 9, 12, 22, '耶和华为了自己的大名的缘故，必不丢弃他的子民，因为他喜欢使你们作他的子民。'),
('CNV', '撒母耳记上', 9, 12, 23, '至于我，我决不停止为你们祷告，以致得罪耶和华；我要把善道正路教导你们。'),
('CNV', '撒母耳记上', 9, 12, 24, '你们只要敬畏耶和华，诚实全心事奉他，因为你们已经看过他为你们所作的是何等大的事。'),
('CNV', '撒母耳记上', 9, 12, 25, '如果你们继续行恶，你们和你们的王就必一同灭亡。”'),
('CNV', '撒母耳记上', 9, 13, 1, '扫罗登基的时候年三十岁，作了以色列王四十二年。'),
('CNV', '撒母耳记上', 9, 13, 2, '他从以色列人中为自己拣选了三千人；两千人和扫罗一同驻在密抹和伯特利山，一千人与约拿单一同驻在便雅悯的基比亚。其余的人，扫罗都遣散他们各回自己的家去了。'),
('CNV', '撒母耳记上', 9, 13, 3, '约拿单攻打非利士人在迦巴的驻军，非利士人听见了；扫罗就在全地吹角，说：“让希伯来人都听见。”'),
('CNV', '撒母耳记上', 9, 13, 4, '以色列众人听说扫罗攻打了非利士人的驻军，又听说非利士人憎恨以色列人，就应召在吉甲跟随扫罗。'),
('CNV', '撒母耳记上', 9, 13, 5, '非利士人聚集起来，要与以色列人交战，他们有战车三千辆、骑兵六千人、步兵像海边的沙那么多。他们上来，在伯．亚文东边的密抹安营。'),
('CNV', '撒母耳记上', 9, 13, 6, '以色列人看见自己情况危急，处境窘迫，众人就藏在山洞、岩穴、地洞里和地坑之中。'),
('CNV', '撒母耳记上', 9, 13, 7, '有些希伯来人渡过了约旦河，逃到迦得和基列地。但是扫罗仍然留在吉甲，跟随他的众人都恐惧战兢。'),
('CNV', '撒母耳记上', 9, 13, 8, '扫罗照着撒母耳所定的日期等了七天，但撒母耳还没有来到吉甲，众人就离开扫罗散去了。'),
('CNV', '撒母耳记上', 9, 13, 9, '扫罗说：“你们把燔祭和平安祭带到我这里来。”他就献上燔祭。'),
('CNV', '撒母耳记上', 9, 13, 10, '他刚刚献完了燔祭，撒母耳就来到了；扫罗出去迎接他，向他问安。'),
('CNV', '撒母耳记上', 9, 13, 11, '撒母耳说：“你作了什么事？”扫罗回答：“因为我看见众民都离开我散去了，你又没有照所定的日子来到，而非利士人正在密抹聚集起来。'),
('CNV', '撒母耳记上', 9, 13, 12, '我心里想：‘非利士人现在就要下到吉甲来攻打我，我却还没有向耶和华求恩。’所以我就勉强自己把燔祭献上了。”'),
('CNV', '撒母耳记上', 9, 13, 13, '撒母耳对扫罗说：“你作了糊涂事了！你没有谨守耶和华你的神吩咐你的命令。如果你谨守，耶和华就必在以色列中坚立你的王位，直到永远。'),
('CNV', '撒母耳记上', 9, 13, 14, '但现在你的王位必不长久，耶和华已经为自己找到一个合他心意的人，立他作自己子民的领袖，因为你没有谨守耶和华所吩咐你的。”'),
('CNV', '撒母耳记上', 9, 13, 15, '于是撒母耳动身，从吉甲上便雅悯的基比亚去；扫罗数点跟随他的人，约有六百人。'),
('CNV', '撒母耳记上', 9, 13, 16, '扫罗和他的儿子约拿单，以及跟随他们的人都停留在便雅悯的迦巴，非利士人却在密抹安营。'),
('CNV', '撒母耳记上', 9, 13, 17, '有突击队从非利士人的营里出来，分成三队，一队往俄弗拉向书亚地去，'),
('CNV', '撒母耳记上', 9, 13, 18, '一队往伯．和仑去，一队往洗波音谷对面的境界向旷野去。'),
('CNV', '撒母耳记上', 9, 13, 19, '那时，以色列全地找不到一个铁匠，因为非利士人说：“恐怕希伯来人制造刀剑或枪矛。”'),
('CNV', '撒母耳记上', 9, 13, 20, '以色列众人要磨锄头、犁头、斧头和铲子，就各自下到非利士人那里去磨。'),
('CNV', '撒母耳记上', 9, 13, 21, '磨锄头或犁头的价钱是七克银子，磨三齿叉、斧头或刺棒的价钱是四克银子。'),
('CNV', '撒母耳记上', 9, 13, 22, '所以，到了争战的时候，跟随扫罗和约拿单的众民，没有一个手里有刀或枪的，只有扫罗和他的儿子约拿单有刀枪。'),
('CNV', '撒母耳记上', 9, 13, 23, '有一队非利士人的驻军出到密抹的隘口去。'),
('CNV', '撒母耳记上', 9, 14, 1, '有一天，扫罗的儿子约拿单对替他拿武器的仆人说：“来！我们过到非利士人的驻军那边去吧。”但他没有告诉父亲。'),
('CNV', '撒母耳记上', 9, 14, 2, '那时扫罗在基比亚的边界，坐在米矶仑的石榴树下，跟随他的约有六百人。'),
('CNV', '撒母耳记上', 9, 14, 3, '其中有亚希突的儿子亚希亚带着以弗得；亚希突是以迦博的哥哥，非尼哈的儿子，以利的孙子。以利从前在示罗作耶和华的祭司。约拿单去了，众人都不知道。'),
('CNV', '撒母耳记上', 9, 14, 4, '约拿单设法要经过那个隘口到非利士人的驻军那里去，隘口的两边各有一个山峰，一个名叫播薛，另一个名叫西尼。'),
('CNV', '撒母耳记上', 9, 14, 5, '一个高峰向北，与密抹相对，另一个向南，与迦巴相对。'),
('CNV', '撒母耳记上', 9, 14, 6, '约拿单对替他拿武器的仆人说：“来！我们过到这些未受割礼的人的驻军那里去，也许耶和华会为我们动工，因为不论人多或人少，都不能妨碍耶和华施行拯救。”'),
('CNV', '撒母耳记上', 9, 14, 7, '替他拿武器的仆人对他说：“照你的心意作吧！去吧，我必与你同心。”'),
('CNV', '撒母耳记上', 9, 14, 8, '约拿单说：“我们要过到那些人那里去，让他们看见我们。'),
('CNV', '撒母耳记上', 9, 14, 9, '如果他们对我们这样说：‘你们站住！等我们到你们那里去。’我们就站在原地，不上他们那里去。'),
('CNV', '撒母耳记上', 9, 14, 10, '如果他们对我们这样说：‘你们上到我们这里来吧！’我们就上去，这就是我们的凭据，因为耶和华已经把他们交在我们的手里了。”'),
('CNV', '撒母耳记上', 9, 14, 11, '他们二人就让非利士人的驻军看见。非利士人说：“看哪！有希伯来人从他们躲藏的洞里出来了。”'),
('CNV', '撒母耳记上', 9, 14, 12, '驻军中有人应声对约拿单和替他拿武器的人说：“你们上我们这里来吧！我们有一件事要告诉你们。”约拿单对替他拿武器的人说：“你跟我上去，因为耶和华已经把他们交在以色列人的手里了。”'),
('CNV', '撒母耳记上', 9, 14, 13, '约拿单手脚并用地爬了上去，替他拿武器的人跟着他。非利士人在约拿单面前倒下，替他拿武器的也跟在后面把他们杀死。'),
('CNV', '撒母耳记上', 9, 14, 14, '约拿单和替他拿武器的第一次杀敌，约杀死了二十人，都是在四分之一公顷的范围内杀的。'),
('CNV', '撒母耳记上', 9, 14, 15, '于是在营房里，在田野中和在众人中间，都有恐慌，驻军和突击队也都恐惧，地也震动，这是从神而来的恐惧。'),
('CNV', '撒母耳记上', 9, 14, 16, '在便雅悯的基比亚，扫罗的瞭望兵看见非利士人的大军溃败，四处逃窜。'),
('CNV', '撒母耳记上', 9, 14, 17, '于是扫罗对跟随他的众民说：“你们数点一下，看看谁从我们这里出去了。”他们一数点，就发现约拿单和替他拿武器的不在那里。'),
('CNV', '撒母耳记上', 9, 14, 18, '扫罗对亚希亚说：“把神的约柜运来！”因为那时神的约柜在以色列人那里。'),
('CNV', '撒母耳记上', 9, 14, 19, '扫罗正对祭司说话的时候，非利士营中的骚乱越来越大，扫罗就对祭司说：“住手吧！”'),
('CNV', '撒母耳记上', 9, 14, 20, '扫罗和所有跟随他的人就聚集起来，到了战场，就看见非利士人用刀互相击杀，十分混乱。'),
('CNV', '撒母耳记上', 9, 14, 21, '那些从前归顺非利士人的希伯来人，就是混杂在营里与非利士人一起上来的，现在也转过来，与那些跟从扫罗和约拿单的以色列人在一起。'),
('CNV', '撒母耳记上', 9, 14, 22, '那些躲藏在以法莲山地的以色列众人一听见非利士人逃跑，也就在战场上紧紧追赶他们。'),
('CNV', '撒母耳记上', 9, 14, 23, '那一天，耶和华拯救了以色列人。战争伸展到伯．亚文。'),
('CNV', '撒母耳记上', 9, 14, 24, '那一天，以色列人处境很窘迫，因为扫罗叫众人起誓说：“不等到晚上，不等到我向敌人报了仇，就吃食物的，那人必受咒诅。”所以众民都没有尝过食物。'),
('CNV', '撒母耳记上', 9, 14, 25, '众人进了树林，林中地上有蜂蜜。'),
('CNV', '撒母耳记上', 9, 14, 26, '他们进了树林，看见有蜂蜜流出来，却没有人敢伸手取蜜入口，因为众人都害怕所起的誓。'),
('CNV', '撒母耳记上', 9, 14, 27, '约拿单没有听见他父亲叫众民所起的誓，所以伸出手中的杖，用杖头蘸在蜂房里，转手送进口里，他的眼睛就明亮了。'),
('CNV', '撒母耳记上', 9, 14, 28, '众民中有一个人说：“你父亲曾经叫众人严严地起誓说：‘今天吃食物的，那人必受咒诅。’所以众人都疲乏了。”'),
('CNV', '撒母耳记上', 9, 14, 29, '约拿单说：“我父亲连累了这地的人。你们看！我尝了这一点蜂蜜以后，我的眼睛就明亮了。'),
('CNV', '撒母耳记上', 9, 14, 30, '今天众民若是随意吃了从他们的仇敌夺得的东西，不是更好吗？如今被击杀的非利士人，不是更多吗？”'),
('CNV', '撒母耳记上', 9, 14, 31, '那一天，他们击杀非利士人，从密抹直到亚雅仑；众人都非常疲乏了，'),
('CNV', '撒母耳记上', 9, 14, 32, '就急忙抢夺战利品；他们捉住了羊、牛或牛犊，就地宰杀，带着血一起吃了。'),
('CNV', '撒母耳记上', 9, 14, 33, '有人告诉扫罗说：“众民吃了带着血的肉，得罪耶和华了。”他说：“你们作了不忠的事了，立刻把一块大石头滚到我这里来。”'),
('CNV', '撒母耳记上', 9, 14, 34, '扫罗又说：“你们分散到众人中去，对他们说：‘你们各人要把自己的牛羊带到我面前来，在这里宰了吃；不可吃带着血的肉，得罪耶和华。’”于是当天晚上，众人都各把自己的牛羊带到那里宰了。'),
('CNV', '撒母耳记上', 9, 14, 35, '扫罗为耶和华筑了一座祭坛，这是他初次为耶和华筑的祭坛。'),
('CNV', '撒母耳记上', 9, 14, 36, '扫罗说：“我们趁着晚上下去追赶非利士人，抢掠他们，直到天亮，不让他们留下一人。”他们说：“你看怎么好，就怎么行吧！”但祭司说：“我们先在这里亲近神！”'),
('CNV', '撒母耳记上', 9, 14, 37, '扫罗求问神：“我可以下去追赶非利士人吗？你把他们交在以色列人的手里吗？”那天神没有回答他。'),
('CNV', '撒母耳记上', 9, 14, 38, '扫罗说：“民间的众领袖啊，你们都要走近这里来；你们要查看今天我们犯了什么罪。'),
('CNV', '撒母耳记上', 9, 14, 39, '我指着拯救以色列、永活的耶和华起誓，即使是我的儿子约拿单犯了罪，他也一定要死。”众人中没有一人回答他。'),
('CNV', '撒母耳记上', 9, 14, 40, '于是扫罗对以色列众人说：“你们站在这里，我和我的儿子约拿单站在那边。”众民回答扫罗：“你看怎么好，就怎么行吧！”'),
('CNV', '撒母耳记上', 9, 14, 41, '扫罗祷告耶和华以色列的神说：“求你指示实情！”于是抽签，抽中了约拿单和扫罗；众民都没事。'),
('CNV', '撒母耳记上', 9, 14, 42, '扫罗说：“你们再抽签，看是我，或是我的儿子约拿单。”结果抽中约拿单。'),
('CNV', '撒母耳记上', 9, 14, 43, '扫罗对约拿单说：“告诉我，你作了什么事？”约拿单告诉他：“我用我手中的杖头尝了一点蜂蜜。我在这里，我愿意死！”'),
('CNV', '撒母耳记上', 9, 14, 44, '扫罗说：“约拿单啊！你必定要死，否则，愿神加倍惩罚我。”'),
('CNV', '撒母耳记上', 9, 14, 45, '众民对扫罗说：“约拿单在以色列人中行了这样大的拯救，难道一定要他死吗？绝对不可以！我们指着永活的耶和华起誓，连他一根头发也不可落在地上，因为他今天是与神一同作工。”这样，众民救了约拿单，使他免了一死。'),
('CNV', '撒母耳记上', 9, 14, 46, '扫罗上去，不再追赶非利士人；非利士人也回到自己的地方去了。'),
('CNV', '撒母耳记上', 9, 14, 47, '扫罗取得了以色列的王国以后，常常攻打四围的一切仇敌，就是摩押人、亚扪人、以东人、琐巴众王和非利士人，他无论往哪里去，都得到胜利。'),
('CNV', '撒母耳记上', 9, 14, 48, '扫罗行事勇敢，击败了亚玛力人，把以色列人从抢掠他们的人手中救了出来。'),
('CNV', '撒母耳记上', 9, 14, 49, '扫罗的儿子是约拿单、亦施韦和麦基舒亚。他的两个女儿，长女名叫米拉，次女名叫米甲。'),
('CNV', '撒母耳记上', 9, 14, 50, '扫罗的妻子名叫亚希暖，是亚希玛斯的女儿。扫罗军队的元帅名叫押尼珥，是尼珥的儿子，尼珥是扫罗的叔叔。'),
('CNV', '撒母耳记上', 9, 14, 51, '扫罗的父亲基士和押尼珥的父亲尼珥都是亚别的儿子。'),
('CNV', '撒母耳记上', 9, 14, 52, '扫罗的一生常常与非利士人有猛烈的争战。每逢扫罗看见任何勇士或有能力的人，就都招募归他。'),
('CNV', '撒母耳记上', 9, 15, 1, '撒母耳对扫罗说：“耶和华差遣我膏立你作他子民以色列的王，所以现在你要听耶和华的话。'),
('CNV', '撒母耳记上', 9, 15, 2, '万军之耶和华这样说：‘以色列人从埃及上来的时候，亚玛力人对他们所行的，在路上攻击他们的事，我必要惩罚。'),
('CNV', '撒母耳记上', 9, 15, 3, '现在你要去攻打亚玛力人，彻底毁灭他们所有的一切，不可怜惜他们。无论男女、孩童，或吃奶的婴儿，牛羊、骆驼、驴子，都要杀死。’”'),
('CNV', '撒母耳记上', 9, 15, 4, '于是扫罗招聚众人，在提拉因数点他们，共有步兵二十万，另有犹大人一万。'),
('CNV', '撒母耳记上', 9, 15, 5, '扫罗到了亚玛力人的城市，就在山谷中设下伏兵。'),
('CNV', '撒母耳记上', 9, 15, 6, '扫罗又对基尼人说：“你们走吧！离开亚玛力人下去吧！免得我把你们与他们一同消灭。因为以色列众人从埃及上来的时候，你们曾经以慈爱待他们。”于是基尼人离开亚玛力人去了。'),
('CNV', '撒母耳记上', 9, 15, 7, '扫罗击杀亚玛力人，从哈腓拉直到埃及东的书珥，'),
('CNV', '撒母耳记上', 9, 15, 8, '生擒了亚玛力人的王亚甲，用刀杀灭了所有人民。'),
('CNV', '撒母耳记上', 9, 15, 9, '但扫罗和众人怜惜亚甲，也爱惜上好的牛羊、肥牛犊、羊羔和一切美好的东西。他们不愿彻底毁灭这些；凡是卑贱的、没有价值的，他们就彻底毁灭。'),
('CNV', '撒母耳记上', 9, 15, 10, '耶和华的话临到撒母耳说：'),
('CNV', '撒母耳记上', 9, 15, 11, '“我后悔立了扫罗为王，因为他已经离去不跟随我，也不执行我的命令了。”撒母耳非常忿怒，整夜哀求耶和华。'),
('CNV', '撒母耳记上', 9, 15, 12, '撒母耳清早起来，要在早晨去见扫罗；有人告诉撒母耳：“扫罗到了迦密，在那里为自己立了一座纪念碑，然后转身下到吉甲去了。”'),
('CNV', '撒母耳记上', 9, 15, 13, '撒母耳到了扫罗那里，扫罗对他说：“愿耶和华赐福给你！我已经执行了耶和华的命令。”'),
('CNV', '撒母耳记上', 9, 15, 14, '撒母耳说：“我耳中听见有羊叫牛鸣的声音，到底是什么呢？”'),
('CNV', '撒母耳记上', 9, 15, 15, '扫罗回答：“这是众民从亚玛力人那里带来的，因为他们爱惜这些上好的牛羊，要献给耶和华你的神为祭；其余的，我们都已经彻底毁灭了。”'),
('CNV', '撒母耳记上', 9, 15, 16, '撒母耳对扫罗说：“住口吧！让我把耶和华昨天晚上对我所说的话告诉你。”扫罗对他说：“请说。”'),
('CNV', '撒母耳记上', 9, 15, 17, '撒母耳说：“从前你虽然自以为微小，不是作了以色列众支派的首领吗？耶和华膏立了你作以色列的王，'),
('CNV', '撒母耳记上', 9, 15, 18, '差遣你去，说：‘你去彻底毁灭那些犯罪的亚玛力人，攻打他们，直到把他们全部毁灭。’'),
('CNV', '撒母耳记上', 9, 15, 19, '你为什么没有听从耶和华的话，急于夺取战利品，作了耶和华看为恶的事呢？”'),
('CNV', '撒母耳记上', 9, 15, 20, '扫罗回答撒母耳：“我实在听从了耶和华的话，行了耶和华差遣我行的路；我把亚玛力人的王亚甲带了回来，又把亚玛力人都彻底毁灭了。'),
('CNV', '撒母耳记上', 9, 15, 21, '可是众民却从那些战利品中，取了应当毁灭之物中上好的牛羊，要在吉甲献给耶和华你的神为祭。”'),
('CNV', '撒母耳记上', 9, 15, 22, '撒母耳说：“耶和华喜悦燔祭和平安祭，岂像喜悦人听从耶和华的话呢？听从胜过献祭，听命胜过公羊的脂油。'),
('CNV', '撒母耳记上', 9, 15, 23, '因为悖逆与行邪术的罪相同，顽梗与拜虚无偶像一样，因为你弃绝了耶和华的话，耶和华也弃绝了你作王。”'),
('CNV', '撒母耳记上', 9, 15, 24, '于是扫罗对撒母耳说：“我犯了罪了，我违背了耶和华的命令和你的话，因为我害怕众人，听从了他们的话。'),
('CNV', '撒母耳记上', 9, 15, 25, '现在求你赦免我的罪，与我一同回去，我好敬拜耶和华。”'),
('CNV', '撒母耳记上', 9, 15, 26, '撒母耳回答扫罗：“我不与你一同回去，因为你弃绝了耶和华的话，耶和华也弃绝你作以色列的王。”'),
('CNV', '撒母耳记上', 9, 15, 27, '撒母耳转身要走，扫罗拉着他外袍的衣边，衣边就撕裂了。'),
('CNV', '撒母耳记上', 9, 15, 28, '撒母耳就对他说：“今天耶和华把以色列国从你身上撕裂，赐给比你更好的人。'),
('CNV', '撒母耳记上', 9, 15, 29, '以色列的大能者必不说谎，也不后悔。因为他不是世人，他决不后悔。”'),
('CNV', '撒母耳记上', 9, 15, 30, '扫罗说：“我犯了罪了，但是求你在我人民的长老面前和以色列人面前给我面子，与我一同回去，我好敬拜耶和华你的神。”'),
('CNV', '撒母耳记上', 9, 15, 31, '于是撒母耳跟着扫罗回去，扫罗就敬拜耶和华。'),
('CNV', '撒母耳记上', 9, 15, 32, '随后撒母耳说：“把亚玛力人的王亚甲带到我这里来！”亚甲欢欢喜喜走到他面前，心里说：“死亡的痛苦必定过去了！”'),
('CNV', '撒母耳记上', 9, 15, 33, '撒母耳说：“你的刀怎样使妇人丧子，你的母亲在妇人中也要怎样丧子。”于是撒母耳在吉甲，在耶和华面前把亚甲斩成碎块。'),
('CNV', '撒母耳记上', 9, 15, 34, '后来撒母耳回拉玛去，扫罗也上他所住的基比亚自己的家去了。'),
('CNV', '撒母耳记上', 9, 15, 35, '撒母耳直到死的日子，再没有看见扫罗。撒母耳为扫罗悲伤，因为耶和华后悔立了扫罗作以色列的王。'),
('CNV', '撒母耳记上', 9, 16, 1, '耶和华对撒母耳说：“你为扫罗悲哀要到几时呢？我已经弃绝他作以色列的王了。你把膏油盛满了角，然后去吧！我要差派你到伯利恒人耶西那里去，因为我在他的众子中，已经预定了一个为我作王。”'),
('CNV', '撒母耳记上', 9, 16, 2, '撒母耳说：“我怎能去呢？扫罗听见了，必定杀我。”耶和华说：“你可以带一头母牛犊去，就说：‘我来是要向耶和华献祭。’'),
('CNV', '撒母耳记上', 9, 16, 3, '你要请耶西参加献祭的筵席，我就会指示你当作的。我指示你的那人，你要为我膏立他。”'),
('CNV', '撒母耳记上', 9, 16, 4, '于是撒母耳照着耶和华的话去行。他到了伯利恒的时候，城里的长老就都战战兢兢地出来迎接他，说：“你是为平安来的吗？”'),
('CNV', '撒母耳记上', 9, 16, 5, '他回答：“是为平安来的。我来是要向耶和华献祭。你们要自洁，与我一同参加献祭的筵席。”撒母耳使耶西和他的儿子自洁，邀请他们来参加献祭的筵席。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '撒母耳记上', 9, 16, 6, '他们来到的时候，撒母耳看见以利押，就心里想：“在耶和华面前的这位，必是他所要膏立的。”'),
('CNV', '撒母耳记上', 9, 16, 7, '但耶和华对撒母耳说：“不要看他的外貌和他高大的身材，因为我不拣选他。耶和华看人不像人看人，人是看外表，耶和华是看内心。”'),
('CNV', '撒母耳记上', 9, 16, 8, '耶西叫亚比拿达在撒母耳面前经过，撒母耳说：“这也不是耶和华所拣选的。”'),
('CNV', '撒母耳记上', 9, 16, 9, '耶西又叫沙玛经过。撒母耳说：“耶和华也不拣选这个。”'),
('CNV', '撒母耳记上', 9, 16, 10, '耶西叫他的七个儿子都在撒母耳面前经过。但撒母耳对耶西说：“这些都不是耶和华所拣选的。”'),
('CNV', '撒母耳记上', 9, 16, 11, '撒母耳问耶西：“孩子们全都在这里吗？”耶西回答：“还有一个最小的，正在牧羊。”撒母耳对耶西说：“你派人去把他带回来，因为他没有来到以前，我们决不入席。”'),
('CNV', '撒母耳记上', 9, 16, 12, '耶西就派人去把大卫带回来。他面色红润，眼目清秀，外貌英俊。耶和华说：“就是这一个，你起来膏立他吧！”'),
('CNV', '撒母耳记上', 9, 16, 13, '撒母耳就拿起盛油的角，在他的兄长中膏立他。从那天起，耶和华的灵就大大感动大卫。后来撒母耳动身往拉玛去了。'),
('CNV', '撒母耳记上', 9, 16, 14, '耶和华的灵离开了扫罗。有恶鬼从耶和华那里来惊扰他。'),
('CNV', '撒母耳记上', 9, 16, 15, '扫罗的臣仆对他说：“看哪！有恶鬼从神那里来惊扰你。'),
('CNV', '撒母耳记上', 9, 16, 16, '愿我们的主吩咐你面前的臣仆，去寻找一位善于弹琴的人；从神那里来的灵临到你身上的时候，他可以弹琴，你就好了。”'),
('CNV', '撒母耳记上', 9, 16, 17, '扫罗对他的臣仆说：“你们可以为我找一个善于弹琴的人，带到我这里来。”'),
('CNV', '撒母耳记上', 9, 16, 18, '有一个仆人回答：“我见过伯利恒人耶西的一个儿子，他善于弹琴，是个大能的勇士，又是个战士，谈吐合宜，容貌俊美，耶和华也与他同在。”'),
('CNV', '撒母耳记上', 9, 16, 19, '于是扫罗派遣使者去见耶西，说：“请你叫你放羊的儿子大卫到我这里来。”'),
('CNV', '撒母耳记上', 9, 16, 20, '耶西就牵来一头驴子，驮上饼、一皮袋酒和一只山羊羔，交给他的儿子大卫送给扫罗。'),
('CNV', '撒母耳记上', 9, 16, 21, '大卫到了扫罗那里，就侍立在他面前。扫罗很爱他，他就作了替扫罗拿武器的人。'),
('CNV', '撒母耳记上', 9, 16, 22, '扫罗再派人到耶西那里去，说：“请你让大卫侍立在我面前吧，因为我喜欢他。”'),
('CNV', '撒母耳记上', 9, 16, 23, '每逢从神那里来的恶鬼临到扫罗身上的时候，大卫就拿起琴来弹奏，扫罗就舒服畅快，恶鬼也离开了他。'),
('CNV', '撒母耳记上', 9, 17, 1, '非利士人聚集他们的军队作战。他们聚集在属犹大的梭哥，在梭哥和亚西加之间的以弗．大悯安营。'),
('CNV', '撒母耳记上', 9, 17, 2, '扫罗和以色列人也聚集起来，在以拉谷安营；他们列出战阵，要迎战非利士人。'),
('CNV', '撒母耳记上', 9, 17, 3, '非利士人站在这边山上，以色列人站在那边山上，中间有山谷分隔。'),
('CNV', '撒母耳记上', 9, 17, 4, '有一个挑战的人从非利士人的军营中出来，名叫歌利亚，是迦特人，身高三公尺。'),
('CNV', '撒母耳记上', 9, 17, 5, '他头戴铜盔，身穿铠甲，铠甲的铜重五十七公斤。'),
('CNV', '撒母耳记上', 9, 17, 6, '他的腿上有铜护膝，两肩之间背着一根铜枪。'),
('CNV', '撒母耳记上', 9, 17, 7, '另外，他手上拿着矛，矛杆有织布的机轴那么粗，矛头的铁重七公斤。还有一个拿大盾牌的人在他前面走。'),
('CNV', '撒母耳记上', 9, 17, 8, '歌利亚站着，向着以色列人的军队喊叫，对他们说：“你们为什么出来这里摆列战阵呢？我不是非利士人吗？你们不是扫罗的仆人吗？你们自己挑选一个人，叫他下到我这里来吧。'),
('CNV', '撒母耳记上', 9, 17, 9, '如果他能与我决斗，击杀了我，我们就作你们的奴仆；但是，如果我能胜过他，击杀了他，你们就作我们的奴仆，服事我们。”'),
('CNV', '撒母耳记上', 9, 17, 10, '那非利士人又说：“今天我向以色列人的军队骂阵。你们派一个人出来，我们可以决斗！”'),
('CNV', '撒母耳记上', 9, 17, 11, '扫罗和以色列众人听见了那非利士人所说的这些话，就都惊惶，非常害怕。'),
('CNV', '撒母耳记上', 9, 17, 12, '大卫是犹大伯利恒的以法他人耶西的儿子；耶西有八个儿子。在扫罗的日子，耶西已经年纪老迈了。'),
('CNV', '撒母耳记上', 9, 17, 13, '耶西的三个大儿子跟随了扫罗去作战。去了作战的这三个儿子的名字是：长子以利押、次子亚比拿达、三子沙玛。'),
('CNV', '撒母耳记上', 9, 17, 14, '大卫是最小的，那三个年长的都跟随扫罗去了。'),
('CNV', '撒母耳记上', 9, 17, 15, '大卫有时离开扫罗，回到伯利恒牧放他父亲的羊群。'),
('CNV', '撒母耳记上', 9, 17, 16, '那非利士人每天早晚都近前来，站着骂阵，一连有四十天之久。'),
('CNV', '撒母耳记上', 9, 17, 17, '有一天，耶西对他的儿子大卫说：“你拿这十公斤烘了的谷子和这十个饼去给你的哥哥们；你要跑到营里去给你的哥哥们，'),
('CNV', '撒母耳记上', 9, 17, 18, '又拿这十块奶酪去给他们的千夫长，看看你的哥哥们平安不平安，把他们的家书带回来。”'),
('CNV', '撒母耳记上', 9, 17, 19, '扫罗和大卫的哥哥们，以及以色列众人都在以拉谷与非利士人作战。'),
('CNV', '撒母耳记上', 9, 17, 20, '大卫清早起来，把羊群托给一个看守的人，就照着耶西所吩咐他的，带着食物去了。他来到军营中的时候，军队正出去列阵，吶喊助阵。'),
('CNV', '撒母耳记上', 9, 17, 21, '以色列人和非利士人都摆列阵势，互相对峙。'),
('CNV', '撒母耳记上', 9, 17, 22, '大卫把身上的东西留在看守物件的人手中，跑到战阵上去，向他的哥哥们问安。'),
('CNV', '撒母耳记上', 9, 17, 23, '大卫正与他们说话的时候，那个讨战的人，就是迦特的非利士人，名叫歌利亚，从非利士人阵中上来；他说的又是同样的那些话，大卫都听见了。'),
('CNV', '撒母耳记上', 9, 17, 24, '所有的以色列人一看见那人，就都从他面前逃跑，非常害怕。'),
('CNV', '撒母耳记上', 9, 17, 25, '以色列人彼此说：“这个上来的人你们看见了吗？他上来是要向以色列人骂阵的。如果有人能击杀他，王必赏赐他大财富，把自己的女儿给他作妻子，并且使他的父家在以色列中免纳税，免服役。”'),
('CNV', '撒母耳记上', 9, 17, 26, '大卫问站在他旁边的人说：“如果有人击杀这个非利士人，除去以色列人的耻辱，那人会得到怎么的对待呢？这未受割礼的非利士人是谁呢？竟敢向永活的神的军队骂阵？”'),
('CNV', '撒母耳记上', 9, 17, 27, '于是众民用以上的那些话回答他说：“如果有人能击杀他，那人必得这样的对待。”'),
('CNV', '撒母耳记上', 9, 17, 28, '大卫与那些人说话的时候，他的大哥以利押听见了，就向大卫发怒，说：“你为什么下这里来呢？在旷野的那几只羊你托了给谁呢？我知道你的骄傲和你心里的恶意。你下来是要看打仗。”'),
('CNV', '撒母耳记上', 9, 17, 29, '大卫说：“我现在作了什么事呢？不是只说了一句话吗？”'),
('CNV', '撒母耳记上', 9, 17, 30, '大卫离开他的哥哥，转向另一个人，问同样的问题。众民还是用先前的话回答他。'),
('CNV', '撒母耳记上', 9, 17, 31, '有人听见大卫所说的这些话，就告诉扫罗；扫罗就派人去把大卫接来。'),
('CNV', '撒母耳记上', 9, 17, 32, '大卫对扫罗说：“大家都不要因这非利士人丧胆，你的仆人要去与这非利士人决斗。”'),
('CNV', '撒母耳记上', 9, 17, 33, '扫罗对大卫说：“你不能去与这非利士人决斗，因为你年纪还轻，那人从小就作战士。”'),
('CNV', '撒母耳记上', 9, 17, 34, '大卫对扫罗说：“你仆人是为父亲放羊的，有时狮子或熊来了，从羊群中抓去一只小羊，'),
('CNV', '撒母耳记上', 9, 17, 35, '我就出去追赶它，击打它，从它的嘴里把小羊救出来。如果它起来攻击我，我就揪住它的胡须，击打它，把它杀死。'),
('CNV', '撒母耳记上', 9, 17, 36, '你仆人不但击杀过狮子，也击杀过熊。这个未受割礼的非利士人也必像一只狮子或熊一样，因为他向永活的神的军队骂阵。”'),
('CNV', '撒母耳记上', 9, 17, 37, '大卫又说：“那曾救我脱离狮爪和熊掌的耶和华，也必救我脱离这非利士人的手。”于是扫罗对大卫说：“你去吧！愿耶和华与你同在。”'),
('CNV', '撒母耳记上', 9, 17, 38, '扫罗把自己的战袍给大卫穿上，把铜盔戴在他的头上，又给他穿上铠甲。'),
('CNV', '撒母耳记上', 9, 17, 39, '大卫把刀佩带在战袍上。因为他以前没有穿过，现在试着走一下。大卫对扫罗说：“穿戴着这些东西，我不能走动，因为我从前没有穿过。”大卫就把这些装备从身上脱下来。'),
('CNV', '撒母耳记上', 9, 17, 40, '他手中拿着自己的杖，又从溪里挑选了五块光滑的石子，放在口袋里，就是牧人用的那种袋子，手里又拿着甩石的机弦，就向那非利士人走近去。'),
('CNV', '撒母耳记上', 9, 17, 41, '那非利士人也向着大卫慢慢走过来，拿大盾牌的人在他前面走。'),
('CNV', '撒母耳记上', 9, 17, 42, '那非利士人观看，看见了大卫，就藐视他，因为他年纪还轻，面色红润，外貌英俊。'),
('CNV', '撒母耳记上', 9, 17, 43, '那非利士人对大卫说：“难道我是一条狗吗？你竟拿杖来攻击我。”于是指着自己的神咒诅大卫。'),
('CNV', '撒母耳记上', 9, 17, 44, '那非利士人又对大卫说：“你到我这里来吧！我要把你的肉给空中的飞鸟和田野的走兽吃。”'),
('CNV', '撒母耳记上', 9, 17, 45, '大卫回答那非利士人：“你来攻击我是靠刀、靠矛、靠枪，但我来攻击你是靠万军之耶和华的名；万军之耶和华就是你所辱骂的以色列军队的神。'),
('CNV', '撒母耳记上', 9, 17, 46, '今天耶和华要把你交在我手里，我必击杀你，砍下你的头。今天我还要把非利士人军队的尸体给空中的飞鸟和地上的野兽吃。这样，全地的人就都知道以色列中有一位神。'),
('CNV', '撒母耳记上', 9, 17, 47, '也使这些人群都知道，耶和华拯救人不是靠刀，不是靠枪，因为战争的胜败在于耶和华，他必把你们交在我们的手里。”'),
('CNV', '撒母耳记上', 9, 17, 48, '那非利士人起身，迎着大卫慢慢走过来；大卫也赶快往阵上跑去，迎战那非利士人。'),
('CNV', '撒母耳记上', 9, 17, 49, '大卫伸手入口袋里，从里面拿出了一块石子来，用机弦甩去，击中了那非利士人的前额；石子穿入前额里面，他就仆倒，面伏于地。'),
('CNV', '撒母耳记上', 9, 17, 50, '这样，大卫用机弦和一块石子胜过了那非利士人。大卫击杀了那非利士人，但他手中没有刀。'),
('CNV', '撒母耳记上', 9, 17, 51, '大卫跑过去，站在那非利士人的身边，拿起他的刀来，把刀从鞘中拔出来，杀死他，又用刀砍下他的头。非利士人看见他们的勇士死了，就都逃跑。'),
('CNV', '撒母耳记上', 9, 17, 52, '以色列人和犹大人就起来，高声吶喊，追赶非利士人，直到迦特的入口和以革伦的城门。被刺死的非利士人都倒在沙拉音的路上，直到迦特和以革伦。'),
('CNV', '撒母耳记上', 9, 17, 53, '以色列人穷追非利士人回来以后，就抢掠他们的营房。'),
('CNV', '撒母耳记上', 9, 17, 54, '大卫拿起那非利士人的头，把它带到耶路撒冷去，却把那人的武器放在自己的帐棚里。'),
('CNV', '撒母耳记上', 9, 17, 55, '扫罗看见大卫出去迎战那非利士人，就问元帅押尼珥：“押尼珥啊，这个年轻人是谁的儿子？”押尼珥回答：“我敢指着王起誓，我不知道。”'),
('CNV', '撒母耳记上', 9, 17, 56, '王说：“你去问问这个少年是谁的儿子。”'),
('CNV', '撒母耳记上', 9, 17, 57, '大卫击杀了那非利士人回来的时候，押尼珥迎接他，把他带到扫罗面前，大卫手中还拿着那非利士人的头。'),
('CNV', '撒母耳记上', 9, 17, 58, '扫罗问他：“年轻人啊，你是谁的儿子？”大卫回答：“我是你仆人伯利恒人耶西的儿子。”'),
('CNV', '撒母耳记上', 9, 18, 1, '大卫对扫罗说完了话，约拿单的心和大卫的心就深相契合。约拿单爱大卫如同爱自己的命。'),
('CNV', '撒母耳记上', 9, 18, 2, '从那天起，扫罗就把大卫留下来，不让他回到父家去。'),
('CNV', '撒母耳记上', 9, 18, 3, '约拿单与大卫立盟约，因为他爱大卫如同爱自己的命。'),
('CNV', '撒母耳记上', 9, 18, 4, '约拿单把自己身上的外袍脱下来给大卫，又把自己的战衣、刀、弓和腰带都给了他。'),
('CNV', '撒母耳记上', 9, 18, 5, '扫罗无论差派大卫到哪里去，他都去，并且凡事亨通。于是扫罗立他作军兵的将领。所有的人民和扫罗的臣仆都非常高兴。'),
('CNV', '撒母耳记上', 9, 18, 6, '大卫击杀了那非利士人，与众人一同回来的时候，妇女们从以色列各城里出来，唱歌、跳舞、打鼓、欢呼、击磬迎接扫罗王。'),
('CNV', '撒母耳记上', 9, 18, 7, '妇女们跳舞、歌唱，说：“扫罗杀死千千！大卫杀死万万！”'),
('CNV', '撒母耳记上', 9, 18, 8, '扫罗非常恼怒，不喜欢这话，就说：“他们给大卫万万，只给我千千，就只剩下王位没给他。”'),
('CNV', '撒母耳记上', 9, 18, 9, '从那天起，扫罗就妒忌大卫。'),
('CNV', '撒母耳记上', 9, 18, 10, '第二天，从神那里来的恶鬼降在扫罗身上，他就在家中胡言乱语。大卫照常弹琴，扫罗手里拿着枪。'),
('CNV', '撒母耳记上', 9, 18, 11, '扫罗把枪掷过去，心里说：“我要把大卫刺在墙上。”大卫两次避开了他。'),
('CNV', '撒母耳记上', 9, 18, 12, '扫罗惧怕大卫，因为耶和华与大卫同在，却离开了扫罗。'),
('CNV', '撒母耳记上', 9, 18, 13, '因此扫罗使大卫离开自己，立他作千夫长，大卫就领导众民出入。'),
('CNV', '撒母耳记上', 9, 18, 14, '大卫所行的一切都亨通，因为耶和华与他同在。'),
('CNV', '撒母耳记上', 9, 18, 15, '扫罗看见大卫所行的十分亨通，就怕他。'),
('CNV', '撒母耳记上', 9, 18, 16, '但是所有的以色列人和犹大人都爱大卫，因为他领导他们出入。'),
('CNV', '撒母耳记上', 9, 18, 17, '扫罗对大卫说：“我的大女儿米拉在这里。我要把她赐给你作妻子；只要你作我的勇士，为耶和华争战。”原来扫罗心里说：“我不好亲手害他，让非利士人害他吧。”'),
('CNV', '撒母耳记上', 9, 18, 18, '大卫回答扫罗：“我是谁？我是什么身分？我父家在以色列人中算得什么？我怎么作王的女婿呢？”'),
('CNV', '撒母耳记上', 9, 18, 19, '到了扫罗的女儿米拉该嫁给大卫的时候，扫罗却把她给了米何拉人亚得列作妻子。'),
('CNV', '撒母耳记上', 9, 18, 20, '扫罗的女儿米甲爱大卫。有人把这事告诉扫罗，扫罗就欢喜，'),
('CNV', '撒母耳记上', 9, 18, 21, '心里想：“我要把米甲给大卫，利用米甲作他的陷阱，好让非利士人的手害他。”于是扫罗对大卫说：“你今天可以第二次作我的女婿。”'),
('CNV', '撒母耳记上', 9, 18, 22, '扫罗吩咐他的臣仆：“你们要私下对大卫说：‘王喜欢你，他的臣仆也都爱你，现在你要作王的女婿！’”'),
('CNV', '撒母耳记上', 9, 18, 23, '于是扫罗的臣仆把这些话说给大卫听。大卫说：“你们以为作王的女婿是一件小事吗？我是个贫穷卑微的人。”'),
('CNV', '撒母耳记上', 9, 18, 24, '扫罗的臣仆把大卫所说的这些话都报告了扫罗。'),
('CNV', '撒母耳记上', 9, 18, 25, '扫罗说：“你们要对大卫这样说：‘王不要什么聘礼，只要一百个非利士人的包皮，好在王的仇敌身上报仇。’”扫罗企图使大卫死在非利士人的手里。'),
('CNV', '撒母耳记上', 9, 18, 26, '扫罗的臣仆把这些话告诉了大卫，大卫就乐意作王的女婿。在日期未满之时，'),
('CNV', '撒母耳记上', 9, 18, 27, '大卫和跟随他的人就起身出去，在非利士人中击杀了二百人，把他们的包皮带回来，满数交给王，要作王的女婿。于是扫罗把他的女儿米甲给大卫作妻子。'),
('CNV', '撒母耳记上', 9, 18, 28, '扫罗看见耶和华与大卫同在，又知道自己的女儿米甲也爱大卫，'),
('CNV', '撒母耳记上', 9, 18, 29, '就更怕大卫，常常与他为敌。'),
('CNV', '撒母耳记上', 9, 18, 30, '非利士人的领袖常常出征，每逢他们出征，大卫作事都比扫罗所有的臣仆所作的更亨通，所以他的名字极为人尊重。'),
('CNV', '撒母耳记上', 9, 19, 1, '扫罗吩咐他的儿子约拿单和他所有的臣仆要把大卫杀死，但扫罗的儿子约拿单非常喜爱大卫。'),
('CNV', '撒母耳记上', 9, 19, 2, '约拿单告诉大卫：“我父亲扫罗正设法要杀死你。所以明天早晨你要小心，留在隐密的地方里，躲藏起来。'),
('CNV', '撒母耳记上', 9, 19, 3, '我会出去，到你藏身的那块田那里，站在我父亲旁边，和他谈论你的事。我看看情形怎样，然后告诉你。”'),
('CNV', '撒母耳记上', 9, 19, 4, '约拿单向父亲扫罗替大卫说好话，说：“王不要得罪你的仆人大卫，因为他没有得罪你；并且他所作的，对你大有好处。'),
('CNV', '撒母耳记上', 9, 19, 5, '他冒着生命的危险击杀了那非利士人，耶和华为以色列人施行了大拯救，那时你看见了，也很欢喜。现在你为什么要犯罪，无缘无故杀死大卫，流无辜人的血呢？”'),
('CNV', '撒母耳记上', 9, 19, 6, '扫罗听了约拿单的话，就起誓，说：“我指着永活的耶和华起誓，大卫必不会被杀死。”'),
('CNV', '撒母耳记上', 9, 19, 7, '约拿单叫大卫来，把这一切话都告诉他；约拿单把大卫带到扫罗那里，他就像以前一样，侍候在扫罗面前。'),
('CNV', '撒母耳记上', 9, 19, 8, '后来，又有战事；大卫出去与非利士人交战，大败他们，他们就在大卫面前逃跑。'),
('CNV', '撒母耳记上', 9, 19, 9, '从耶和华那里来的恶鬼又临到扫罗身上；那时扫罗坐在屋里，手里拿着枪。大卫正在弹琴，'),
('CNV', '撒母耳记上', 9, 19, 10, '扫罗就想用枪刺杀大卫，把他刺在墙上，但大卫从扫罗面前躲开了，他的枪刺在墙上。那天晚上大卫逃跑，就逃脱了。'),
('CNV', '撒母耳记上', 9, 19, 11, '扫罗派人到大卫家里去监视他，要在第二天早晨杀死他。大卫的妻子米甲告诉他说：“今天晚上你若不逃命，明天就会被杀死。”'),
('CNV', '撒母耳记上', 9, 19, 12, '于是米甲从窗口把大卫缒下去，大卫就离开那里逃走，逃脱了。'),
('CNV', '撒母耳记上', 9, 19, 13, '米甲把家中的一尊神像拿来，放在床上，把头枕在用山羊毛弄成的枕头上，再用衣服盖着。'),
('CNV', '撒母耳记上', 9, 19, 14, '扫罗派人来捉拿大卫，米甲说：“他病了。”'),
('CNV', '撒母耳记上', 9, 19, 15, '扫罗又派人去看大卫说：“你们把他连床一起抬到我这里来，我好杀死他。”'),
('CNV', '撒母耳记上', 9, 19, 16, '奉派的人进去，看见床上有一尊家中的神像，头枕在用山羊毛弄成的枕头上。'),
('CNV', '撒母耳记上', 9, 19, 17, '扫罗问米甲：“你为什么这样欺骗我，放了我的仇敌，让他逃走呢？”米甲回答扫罗：“他对我说：‘放我走！否则我要杀死你。’”'),
('CNV', '撒母耳记上', 9, 19, 18, '大卫逃跑，逃脱了，来到拉玛见撒母耳，把扫罗对他所作的一切都告诉了撒母耳。然后他和撒母耳去拿约，住在那里。'),
('CNV', '撒母耳记上', 9, 19, 19, '有人告诉扫罗：“大卫住在拉玛的拿约。”'),
('CNV', '撒母耳记上', 9, 19, 20, '于是扫罗派人去捉大卫。派去的人看见一群先知正在受感说话，撒母耳站着带领他们。那时，神的灵也临到扫罗的使者身上，他们都受感说话。'),
('CNV', '撒母耳记上', 9, 19, 21, '有人把这事告诉了扫罗，他就再派别的人去，这些人也受感说话。扫罗第三次派人去，他们也受感说话。'),
('CNV', '撒母耳记上', 9, 19, 22, '后来，扫罗也亲自到拉玛去，到了西沽的大井，就问人，说：“撒母耳和大卫在哪里？”有一个人回答：“在拉玛的拿约。”'),
('CNV', '撒母耳记上', 9, 19, 23, '扫罗就从那里往拉玛的拿约去。神的灵也临到他身上，他一面走，一面受感说话，直到他到了拉玛的拿约。'),
('CNV', '撒母耳记上', 9, 19, 24, '他脱掉了自己的衣服，也在撒母耳面前受感说话。那一日，他整天整夜赤着身子躺着，因此有一句俗语说：“扫罗也列在先知中吗？”'),
('CNV', '撒母耳记上', 9, 20, 1, '大卫从拉玛的拿约逃走，来见约拿单，说：“我作了什么？我有什么罪孽？我在你父亲面前犯了什么罪，他竟寻索我的性命呢？”'),
('CNV', '撒母耳记上', 9, 20, 2, '约拿单对他说：“绝对没有这事，你必不会死。我父亲作事，无论大小，没有不让我知道的，为什么这事他偏要隐瞒我呢？不会这样的。”'),
('CNV', '撒母耳记上', 9, 20, 3, '大卫再起誓说：“你父亲一定知道我在你眼中蒙恩，就心里想：‘不要让约拿单知道这事，免得他伤心。’可是，我指着永活的耶和华，又指着你的性命起誓，我离死只差一步。”'),
('CNV', '撒母耳记上', 9, 20, 4, '约拿单对大卫说：“你心里想要什么，我必为你作成。”'),
('CNV', '撒母耳记上', 9, 20, 5, '大卫就对约拿单说：“你看，明天是初一，我本该与王一同坐席。但是，求你容我去藏在田里，直到后天晚上。'),
('CNV', '撒母耳记上', 9, 20, 6, '如果你父亲不见我在座，你就说：‘大卫恳求我让他赶回他的本城伯利恒去，因为他全家在那里有献年祭的事。’'),
('CNV', '撒母耳记上', 9, 20, 7, '如果你父亲这样说：‘好！’那么仆人就平安无事了；如果他大大发怒，你就知道，他决意要害我了。'),
('CNV', '撒母耳记上', 9, 20, 8, '求你以慈爱待仆人，因为你曾与仆人在耶和华面前立盟约。如果我有罪孽，你就亲手把我杀死，为什么要把我交给你父亲呢？”'),
('CNV', '撒母耳记上', 9, 20, 9, '约拿单说：“绝对没有这事，如果我知道我父亲决意要害你，我会不告诉你吗？”'),
('CNV', '撒母耳记上', 9, 20, 10, '大卫对约拿单说：“如果你父亲严厉地回答你，谁来告诉我呢？”'),
('CNV', '撒母耳记上', 9, 20, 11, '约拿单对大卫说：“你来，我们出到田里去吧！”他们二人就出到田里去了。'),
('CNV', '撒母耳记上', 9, 20, 12, '约拿单对大卫说：“愿耶和华以色列的神作证，明天或后天约在这个时候，我探出了我父亲的意思，如果他对你有好感，那时我会不派人来告诉你吗？'),
('CNV', '撒母耳记上', 9, 20, 13, '假如我父亲有意要害你，我若是不告诉你，不让你走，不使你平平安安地离去，愿耶和华加倍惩罚我。愿耶和华与你同在，好像从前与我父亲同在一样。'),
('CNV', '撒母耳记上', 9, 20, 14, '我活着的时候，求你以耶和华的慈爱待我，使我不致于死。'),
('CNV', '撒母耳记上', 9, 20, 15, '我死了以后，耶和华从地上一一剪除大卫的仇敌的时候，你也不可向我的家永远断绝你的慈爱。”'),
('CNV', '撒母耳记上', 9, 20, 16, '于是约拿单与大卫家立盟约，说：“愿耶和华藉大卫仇敌的手追讨违背盟约的罪。”'),
('CNV', '撒母耳记上', 9, 20, 17, '约拿单由于爱大卫，就使大卫再起誓；他爱大卫如同爱自己的命。'),
('CNV', '撒母耳记上', 9, 20, 18, '约拿单对大卫说：“明天是初一，因为你的座位空着，人必注意到你不在。'),
('CNV', '撒母耳记上', 9, 20, 19, '到后天，你要赶快下去，到你以前出事那天藏身的地方，在以色磐石旁边等候。'),
('CNV', '撒母耳记上', 9, 20, 20, '我要向磐石旁边射三支箭，好像射箭靶一样。'),
('CNV', '撒母耳记上', 9, 20, 21, '然后，我要派一个仆人去，说：‘你去把箭找回来。’如果我对那仆人说：‘看哪！箭在你的后面，把箭拿回来。’你就可以回来，因为我指着永活的耶和华起誓，你必平安无事。'),
('CNV', '撒母耳记上', 9, 20, 22, '如果我对仆人说：‘看哪！箭在你的前面。’你就要离去，因为是耶和华打发你去的。'),
('CNV', '撒母耳记上', 9, 20, 23, '至于你我之间所说的这事，有耶和华永远在你我之间作证。”'),
('CNV', '撒母耳记上', 9, 20, 24, '于是大卫在田里藏起来。到了初一，王坐席吃饭。'),
('CNV', '撒母耳记上', 9, 20, 25, '王照常坐在他的座位上，就是靠墙的座位，约拿单坐在对面，押尼珥坐在扫罗旁边，大卫的座位却空着。'),
('CNV', '撒母耳记上', 9, 20, 26, '那天扫罗没有说什么，因为他心里想：“这是恰巧的事，或许大卫沾染了不洁，还没有得到洁净。”'),
('CNV', '撒母耳记上', 9, 20, 27, '次日，就是初二，大卫的座位仍是空着。于是扫罗问他的儿子约拿单：“为什么耶西的儿子昨天今天都没有来吃饭呢？”'),
('CNV', '撒母耳记上', 9, 20, 28, '约拿单回答扫罗：“大卫恳切地求我让他回伯利恒去。'),
('CNV', '撒母耳记上', 9, 20, 29, '他说：‘求你让我去，因为我们的家在城里有献祭的事，我哥哥吩咐我去。所以，我若是在你眼前蒙恩，求你让我离开，看看我的哥哥们。’因此，大卫没有来赴王的筵席。”'),
('CNV', '撒母耳记上', 9, 20, 30, '于是扫罗向约拿单发怒，对他说：“你这邪僻悖逆妇人所生的，我岂不知道你喜悦耶西的儿子，自取羞辱，也羞辱生你的母亲吗？'),
('CNV', '撒母耳记上', 9, 20, 31, '因为只要耶西的儿子还活在这世上，你和你的国就不能稳固。现在，你要派人去把他抓到我这里来，因为他是该死的。”'),
('CNV', '撒母耳记上', 9, 20, 32, '约拿单回答他父亲扫罗说：“为什么要把他处死呢？他作了什么事呢？”'),
('CNV', '撒母耳记上', 9, 20, 33, '扫罗向着约拿单把枪掷过去，要刺杀他。约拿单就知道，他父亲已经决意要杀死大卫。'),
('CNV', '撒母耳记上', 9, 20, 34, '约拿单怒气冲冲地从席间退去，初二这天，他没有吃饭；因为他父亲羞辱了大卫，他就为大卫担忧。'),
('CNV', '撒母耳记上', 9, 20, 35, '到了早晨，约拿单照着与大卫约定的时候，出到田里去，有一个小童与他在一起。'),
('CNV', '撒母耳记上', 9, 20, 36, '他对那童仆说：“你跑去，把我所射的箭找回来。”那童仆跑去的时候，约拿单就把箭射到他前面。'),
('CNV', '撒母耳记上', 9, 20, 37, '那童仆到了约拿单的箭射到的地方，约拿单就在那童仆的背后喊叫：“箭不是在你的前面吗？”'),
('CNV', '撒母耳记上', 9, 20, 38, '约拿单又在那童仆的背后喊叫：“赶快跑去！不要停留！”那童仆就把箭拾起来，回到他主人那里去。'),
('CNV', '撒母耳记上', 9, 20, 39, '那童仆一点也不知道这是什么意思，只有约拿单和大卫知道。'),
('CNV', '撒母耳记上', 9, 20, 40, '约拿单把自己的武器交给他的童仆，对他说：“你带回城里去吧！”'),
('CNV', '撒母耳记上', 9, 20, 41, '那童仆一离去，大卫就从石堆的南边起来，脸伏于地，叩拜了三次。二人互相亲吻，相对哭泣，大卫哭得更悲痛。'),
('CNV', '撒母耳记上', 9, 20, 42, '约拿单对大卫说：“你平平安安走吧！我们二人曾指着耶和华的名起誓说：‘愿耶和华在你我之间，也在我的后裔和你的后裔之间作证，直到永远。’”大卫就起身离开，约拿单也回城里去了。'),
('CNV', '撒母耳记上', 9, 21, 1, '大卫到了挪伯祭司亚希米勒那里，亚希米勒战战兢兢地迎接大卫，对他说：“你为什么独自一人，没有人跟随你呢？”'),
('CNV', '撒母耳记上', 9, 21, 2, '大卫对亚希米勒祭司说：“王吩咐我作一件事，对我说：‘我差派你，吩咐你去办的这事，你不要让任何人知道，我已经指示我的仆人在某地会面。’'),
('CNV', '撒母耳记上', 9, 21, 3, '现在你手中有什么？求你给我五个饼，或是别的食物。”'),
('CNV', '撒母耳记上', 9, 21, 4, '祭司回答大卫：“我手中没有普通的饼，只有圣饼。只有那些没有亲近过女人的年轻人，才可以吃的。”'),
('CNV', '撒母耳记上', 9, 21, 5, '大卫回答祭司说：“像以往我出征的时候一样，这次我们出征前，确实没有亲近女人。虽然这是一次普通的任务，众仆人的器皿还是清洁的，何况今天这些器皿更加是清洁的。”'),
('CNV', '撒母耳记上', 9, 21, 6, '于是祭司把圣饼给他，因为在那里没有别的饼，只有陈设饼，就是那些刚从耶和华面前拿下来，为要换上热的。'),
('CNV', '撒母耳记上', 9, 21, 7, '那天有一个扫罗的臣仆在那里，留在耶和华面前。他名叫多益，是以东人，是扫罗牧羊人中的领袖。'),
('CNV', '撒母耳记上', 9, 21, 8, '大卫问亚希米勒：“你手下有枪有刀没有？因为王的事很急迫，所以我手里连刀剑或其他武器都没有带来。”'),
('CNV', '撒母耳记上', 9, 21, 9, '祭司回答：“有一把刀，是你从前在以拉谷击杀的那非利士人歌利亚的刀。这刀用布包着，放在以弗得后面，你若是要拿去自用，就拿去吧，因为这里除了这刀以外，再没有别的武器了。”大卫说：“没有比这更好的刀了，请你给我吧！”'),
('CNV', '撒母耳记上', 9, 21, 10, '那一天大卫起来，从扫罗面前逃走，到了迦特王亚吉那里。'),
('CNV', '撒母耳记上', 9, 21, 11, '亚吉的臣仆对亚吉说：“这不是那地的王大卫吗？那里的妇女不是指着他跳舞歌唱说：‘扫罗杀死千千，大卫杀死万万’吗？”'),
('CNV', '撒母耳记上', 9, 21, 12, '大卫把这些话记在心里，他非常怕迦特王亚吉，'),
('CNV', '撒母耳记上', 9, 21, 13, '就在众人面前假装神智不健全，在他们手下装疯，在城门的门扇上胡乱涂写，又让唾沫流到胡须上。'),
('CNV', '撒母耳记上', 9, 21, 14, '亚吉就对他的臣仆说：“你们看，这个人疯了，你们为什么把他带到我这里来呢？'),
('CNV', '撒母耳记上', 9, 21, 15, '难道我缺少疯子吗？你们竟把这人带来我面前发疯。这人怎可以进我的家呢？”'),
('CNV', '撒母耳记上', 9, 22, 1, '大卫离开那里，逃到亚杜兰洞。他哥哥们和他父亲的全家听到了，就都下到他那里去。'),
('CNV', '撒母耳记上', 9, 22, 2, '凡是受窘迫的、负债的、心里不满的，都聚集到大卫那里，他就成了他们的领袖。那时，跟从他的约有四百人。'),
('CNV', '撒母耳记上', 9, 22, 3, '大卫从那里到摩押的米斯巴去，对摩押王说：“求你容许我父母来住在你们这里，直到我知道神要为我作什么。”'),
('CNV', '撒母耳记上', 9, 22, 4, '于是大卫把他们留在摩押王那里。大卫住在山寨的日子有多久，他父母也与摩押王同住多久。'),
('CNV', '撒母耳记上', 9, 22, 5, '迦得先知对大卫说：“你不要留在山寨，要到犹大地去。”大卫就离开那里，往哈列的森林去了。'),
('CNV', '撒母耳记上', 9, 22, 6, '扫罗听见发现了大卫和跟从他的人的行踪。那时扫罗在基比亚坐在山上一棵垂柳树下，手中拿着枪，众臣仆侍立在他周围。'),
('CNV', '撒母耳记上', 9, 22, 7, '扫罗就对侍立在他周围的臣仆说：“便雅悯人哪，你们要听！耶西的儿子能把田地和葡萄园赐给你们各人吗？他能立你们各人作千夫长、作百夫长吗？'),
('CNV', '撒母耳记上', 9, 22, 8, '你们竟都同谋陷害我。我的儿子与耶西的儿子立盟约的时候，没有人告诉我；我的儿子挑唆我的臣仆陷害我，就像今天一样，你们中间也没有人关心我，告诉我。”'),
('CNV', '撒母耳记上', 9, 22, 9, '那时以东人多益与扫罗的臣仆侍立在那里，他回答说：“我曾看见耶西的儿子到了挪伯亚希突的儿子亚希米勒那里。'),
('CNV', '撒母耳记上', 9, 22, 10, '亚希米勒为他求问耶和华，给他粮食，又把非利士人歌利亚的刀给他。”'),
('CNV', '撒母耳记上', 9, 22, 11, '扫罗就派人去把亚希突的儿子，亚希米勒祭司和他父亲的全家，就是在挪伯的众祭司，都召了来；他们众人都来见王。'),
('CNV', '撒母耳记上', 9, 22, 12, '扫罗说：“亚希突的儿子啊！你要听。”他回答：“我主啊！我在这里。”'),
('CNV', '撒母耳记上', 9, 22, 13, '扫罗对他说：“你为什么与耶西的儿子合谋陷害我？把食物和刀给他，又为他求问神，使他起来陷害我，就像今天一样呢？”'),
('CNV', '撒母耳记上', 9, 22, 14, '亚希米勒回答王说：“在你所有的臣仆中，有谁像大卫那样忠心呢？他是王的女婿，又是你的卫队的队长，并且在你朝中是受敬重的。'),
('CNV', '撒母耳记上', 9, 22, 15, '我岂是今天才开始为他求问神的呢？绝对不是。请王不要归罪于我和我父的全家，因为这整件事无论大小，我都不知道。”'),
('CNV', '撒母耳记上', 9, 22, 16, '王说：“亚希米勒啊！你和你父的全家都是该死的。”'),
('CNV', '撒母耳记上', 9, 22, 17, '王就对侍立在他周围的卫兵说：“你们转过去，把耶和华的祭司杀死，因为他们与大卫携手，又因为他们知道大卫逃跑，也不告诉我。”但王的臣仆不愿下手杀害耶和华的祭司。'),
('CNV', '撒母耳记上', 9, 22, 18, '于是王对多益说：“你转过去把祭司击杀。”以东人多益就转过去把祭司击杀了。那一天，他杀了八十五个穿细麻布以弗得的人，'),
('CNV', '撒母耳记上', 9, 22, 19, '又用刀击杀了祭司城挪伯，无论男女，孩童或吃奶的婴儿，牛驴或羊，都用刀杀尽。'),
('CNV', '撒母耳记上', 9, 22, 20, '亚希突的儿子亚希米勒有一个儿子，名叫亚比亚他，逃过了大难，就逃去跟随大卫。'),
('CNV', '撒母耳记上', 9, 22, 21, '亚比亚他把扫罗杀害耶和华祭司的事告诉了大卫，'),
('CNV', '撒母耳记上', 9, 22, 22, '大卫就对亚比亚他说：“那一天我见以东人多益在那里，就知道他必定会告诉扫罗。你父全家每个人的死，我都有责任。'),
('CNV', '撒母耳记上', 9, 22, 23, '你可以住在我这里。不要惧怕，因为那寻索你命的，正在寻索我的命，你与我在一起就可保安全。”'),
('CNV', '撒母耳记上', 9, 23, 1, '有人告诉大卫：“看哪，非利士人正在攻打基伊拉，并且抢掠禾场。”'),
('CNV', '撒母耳记上', 9, 23, 2, '大卫就求问耶和华说：“我可以去击打这些非利士人吗？”耶和华对大卫说：“你可以去击打非利士人，拯救基伊拉。”'),
('CNV', '撒母耳记上', 9, 23, 3, '跟随大卫的人对他说：“看哪，我们在犹大地这里尚且惧怕，何况到基伊拉去攻打非利士人的军兵呢？”'),
('CNV', '撒母耳记上', 9, 23, 4, '于是大卫再求问耶和华。耶和华回答他说：“你只管起来，下到基伊拉去，因为我必把非利士人交在你的手里。”'),
('CNV', '撒母耳记上', 9, 23, 5, '大卫和跟随他的人就到基伊拉去，与非利士人争战，掳走了他们的牲畜，又在他们中间杀戮多人。这样，大卫拯救了基伊拉的居民。'),
('CNV', '撒母耳记上', 9, 23, 6, '亚希米勒的儿子亚比亚他逃到基伊拉去见大卫的时候，是手里带着以弗得下来的。'),
('CNV', '撒母耳记上', 9, 23, 7, '有人告诉扫罗，大卫到了基伊拉，扫罗就说：“神把他交在我的手中了，因为他进了一座有门有闩的城，把自己关闭起来了。”'),
('CNV', '撒母耳记上', 9, 23, 8, '于是扫罗召集众人去争战，要下到基伊拉去，围困大卫和跟随他的人。'),
('CNV', '撒母耳记上', 9, 23, 9, '大卫知道扫罗设计害他，就对亚比亚他祭司说：“把以弗得拿来！”'),
('CNV', '撒母耳记上', 9, 23, 10, '大卫说：“耶和华以色列的神啊！你仆人确实听见了扫罗想要到基伊拉来，为了我的缘故要毁灭这城。'),
('CNV', '撒母耳记上', 9, 23, 11, '基伊拉人会把我交在扫罗的手里吗？扫罗会照着你仆人所听到的下来吗？耶和华以色列的神啊！求你告诉你仆人。”耶和华说：“他必下来。”'),
('CNV', '撒母耳记上', 9, 23, 12, '大卫又说：“基伊拉人会把我和跟随我的人交在扫罗手里吗？”耶和华说：“他们必把你们交出来。”'),
('CNV', '撒母耳记上', 9, 23, 13, '大卫和跟从他的人，约有六百人，就起身离开基伊拉，到处漂泊。有人告诉扫罗，大卫已经逃离了基伊拉，扫罗就不出去了。'),
('CNV', '撒母耳记上', 9, 23, 14, '大卫住在旷野的山寨里，又住在西弗旷野的山里。扫罗天天寻索大卫，神却不把大卫交在他手里。'),
('CNV', '撒母耳记上', 9, 23, 15, '大卫惧怕，因为扫罗出来寻索他的命。那时大卫住在西弗旷野的何列斯那里。'),
('CNV', '撒母耳记上', 9, 23, 16, '扫罗的儿子约拿单起身，到何列斯去见大卫，鼓励他，使他靠神坚强起来，'),
('CNV', '撒母耳记上', 9, 23, 17, '对他说：“你不要惧怕！我父亲扫罗的手必不能害你。你必要作以色列的王，我要在你以下位居第二，这事连我父亲扫罗也知道了。”'),
('CNV', '撒母耳记上', 9, 23, 18, '于是他们二人在耶和华面前立了约。大卫仍住在何列斯，约拿单却回自己的家去了。'),
('CNV', '撒母耳记上', 9, 23, 19, '西弗人上到基比亚去见扫罗，说：“大卫不是在我们这里的何列斯的山寨，就是在旷野南边的哈基拉山上藏着吗？'),
('CNV', '撒母耳记上', 9, 23, 20, '王啊，现在请下来，请你随着你的心愿下来，我们必亲自把他交在王的手里。”'),
('CNV', '撒母耳记上', 9, 23, 21, '扫罗说：“愿耶和华赐福你们，因为你们关心我。'),
('CNV', '撒母耳记上', 9, 23, 22, '你们要去再确实查看他脚踪所到的地方，有谁看见他在那里，因为有人对我说，他非常狡猾。'),
('CNV', '撒母耳记上', 9, 23, 23, '你们要去查看他所有藏身的地方，确定以后再回来见我，我就与你们同去；如果他在本地，我必从犹大的千门万户中把他搜出来。”'),
('CNV', '撒母耳记上', 9, 23, 24, '于是西弗人起身，在扫罗以先到西弗去了。那时大卫和跟随他的人却在玛云旷野，就是在荒野南边的亚拉巴。'),
('CNV', '撒母耳记上', 9, 23, 25, '扫罗和跟随他的人去寻找大卫。有人告诉大卫，他就下到磐石那里，留在玛云旷野。扫罗听见了，就在玛云旷野追赶大卫。'),
('CNV', '撒母耳记上', 9, 23, 26, '扫罗在山这边走，大卫和跟随他的人却在山那边走。大卫匆匆忙忙逃避扫罗，扫罗和跟随他的人却四面包围大卫和跟随他的人，要把他们捉住。'),
('CNV', '撒母耳记上', 9, 23, 27, '那时忽有使者来见扫罗说：“请你赶快回去，因为非利士人来突击这地。”'),
('CNV', '撒母耳记上', 9, 23, 28, '于是扫罗不再追赶大卫，回去迎战非利士人。因此这地方被称为西拉．哈玛希罗结。'),
('CNV', '撒母耳记上', 9, 23, 29, '大卫从那里上去，住在隐．基底的山寨里。'),
('CNV', '撒母耳记上', 9, 24, 1, '扫罗追赶非利士人回来的时候，有人告诉他说：“看哪，大卫在隐．基底的旷野。”'),
('CNV', '撒母耳记上', 9, 24, 2, '扫罗就从以色列人中选出三千精兵，带领他们到野羊磐石去搜索大卫和跟随他的人。'),
('CNV', '撒母耳记上', 9, 24, 3, '到了路旁的羊圈，那里有一个洞，扫罗进去大解；那时，大卫和跟随他的人正坐在洞里的深处。'),
('CNV', '撒母耳记上', 9, 24, 4, '跟随大卫的人对他说：“耶和华曾应许你说：‘我要把你的仇敌交在你的手里，你可以随意待他。’看哪！今天就是时候了。”于是大卫起来，悄悄地割下扫罗外袍的衣边。'),
('CNV', '撒母耳记上', 9, 24, 5, '事后，大卫为了割下扫罗的衣边，心中自责，'),
('CNV', '撒母耳记上', 9, 24, 6, '就对跟随他的人说：“我在耶和华面前绝对不能这样对待我主耶和华的受膏者，我绝对不能动手攻击他，因为他是耶和华的受膏者。”'),
('CNV', '撒母耳记上', 9, 24, 7, '大卫用这些话阻止了跟随他的人，不让他们起来攻击扫罗。扫罗起来，出了山洞，继续走他的路去了。'),
('CNV', '撒母耳记上', 9, 24, 8, '随后，大卫也起来，离开了山洞，在扫罗背后呼叫，说：“我主！我王！”扫罗回头向后看的时候，大卫就脸伏于地，向他叩拜。'),
('CNV', '撒母耳记上', 9, 24, 9, '大卫对扫罗说：“你为什么听信人的话，说：‘大卫想要害你’呢？'),
('CNV', '撒母耳记上', 9, 24, 10, '现在你亲眼看到，今天耶和华在山洞里，把你交在我手里。有人叫我杀你，我却爱惜你。我说：‘我不敢下手伤害我主，因为他是耶和华的受膏者。’'),
('CNV', '撒母耳记上', 9, 24, 11, '我父啊，请看，你外袍的衣边在我手中。我割下了你外袍的衣边，却没有杀你。你从此可以知道，也可以看出我手中没有邪恶，也没有过犯。我虽然没有得罪你，你却要猎取我的性命。'),
('CNV', '撒母耳记上', 9, 24, 12, '愿耶和华在你我之间判断是非；愿耶和华在你身上为我伸冤。我的手却不敢伤害你。'),
('CNV', '撒母耳记上', 9, 24, 13, '正如古时的格言：‘恶事出于恶人。’所以，我的手不敢伤害你。'),
('CNV', '撒母耳记上', 9, 24, 14, '以色列的王出去追捕谁呢？你现在追赶谁呢？不过是追赶一条死狗，一只跳蚤罢了！'),
('CNV', '撒母耳记上', 9, 24, 15, '愿耶和华在你我中间施行审判，断定是非；愿他鉴察，为我的案件伸冤，救我脱离你的手。”'),
('CNV', '撒母耳记上', 9, 24, 16, '大卫对扫罗说完了这些话，扫罗就说：“我儿大卫啊，这是你的声音吗？”于是扫罗放声大哭，'),
('CNV', '撒母耳记上', 9, 24, 17, '对大卫说：“你比我公义，因为你以良善待我，我却以恶待你。'),
('CNV', '撒母耳记上', 9, 24, 18, '今天你所作的说明了你以良善待我，因为耶和华把我交在你手里，你却没有杀我。'),
('CNV', '撒母耳记上', 9, 24, 19, '如果人遇见仇敌，怎会让他平平安安离去呢？愿耶和华因你今天对我所作的以福报答你。'),
('CNV', '撒母耳记上', 9, 24, 20, '现在我知道你必要作王，以色列的王国必在你手里坚立起来。'),
('CNV', '撒母耳记上', 9, 24, 21, '现在你要指着耶和华向我起誓，不剪除我的后裔，也不从我父家消灭我的名。”'),
('CNV', '撒母耳记上', 9, 24, 22, '于是大卫向扫罗起誓，扫罗就回自己的家去了，大卫和跟随他的人也上山寨去了。'),
('CNV', '撒母耳记上', 9, 25, 1, '撒母耳死了，以色列众人都聚集起来，为他哀哭，把他埋葬在拉玛他自己的家里。大卫起身，下到巴兰的旷野去。'),
('CNV', '撒母耳记上', 9, 25, 2, '在玛云有一个人，他的产业在迦密。他是一个很富有的人，有绵羊三千只，山羊一千只，那时他正在迦密剪羊毛。'),
('CNV', '撒母耳记上', 9, 25, 3, '那人名叫拿八，他的妻子名叫亚比该。这女人既聪明，又美丽。但那男人为人粗暴，又行事凶恶。他是个迦勒族的人。'),
('CNV', '撒母耳记上', 9, 25, 4, '大卫在旷野听说拿八正在剪羊毛，'),
('CNV', '撒母耳记上', 9, 25, 5, '就差派十个仆人，对他们说：“你们上迦密去见拿八，以我的名义向他问安。'),
('CNV', '撒母耳记上', 9, 25, 6, '你们要这样说：‘愿你长寿！愿你平安！愿你的家平安！愿你所有的一切都平安！'),
('CNV', '撒母耳记上', 9, 25, 7, '现在我听说有人为你剪羊毛。你的牧人与我们在一起的时候，我们都没有侮辱他们；他们在迦密的日子，也从没有遗失过什么。'),
('CNV', '撒母耳记上', 9, 25, 8, '你可以问问你的仆人，他们必会告诉你。愿我派来的这些仆人在你眼前蒙恩，因为我们是在好日子来的，请你把手中所有的，随便赏赐一点给你的仆人和你的儿子大卫。’”'),
('CNV', '撒母耳记上', 9, 25, 9, '大卫的仆人到了，就以大卫的名义，把这些话都对拿八说了，然后等候答覆。'),
('CNV', '撒母耳记上', 9, 25, 10, '拿八回答大卫的仆人说：“大卫是谁？耶西的儿子是谁？现在离开主人逃走的仆人太多了。'),
('CNV', '撒母耳记上', 9, 25, 11, '我怎能把我的饼、我的水，和我为剪羊毛的人宰杀的肉，给那些我不知道从哪里来的人呢？”'),
('CNV', '撒母耳记上', 9, 25, 12, '于是大卫的仆人转回原路，回去了。他们到了以后，就把这一切话都告诉大卫。'),
('CNV', '撒母耳记上', 9, 25, 13, '大卫对跟随他的人说：“你们各人都佩上刀。”他们各人就佩上自己的刀，大卫也佩上自己的刀。跟随大卫上去的约有四百人，有二百人留下来看守器具。'),
('CNV', '撒母耳记上', 9, 25, 14, '拿八的一个仆人告诉拿八的妻子亚比该说：“大卫从旷野派遣使者来向我们的主人问候，主人却辱骂了他们。'),
('CNV', '撒母耳记上', 9, 25, 15, '但是，那些人对我们很好。我们在田野与他们往来的时候，他们都没有侮辱我们，我们也从没有遗失过什么。'),
('CNV', '撒母耳记上', 9, 25, 16, '我们与他们在一起牧羊的日子，他们日夜都作保护我们的墙。'),
('CNV', '撒母耳记上', 9, 25, 17, '现在，你要想一想，看看你该怎么办，因为灾祸必定临到我们的主人和他的全家。他是一个性情凶恶的人，没有人敢对他说话。”'),
('CNV', '撒母耳记上', 9, 25, 18, '亚比该急忙拿了两百个饼、两皮袋酒、五只预备好了的羊、十七公斤烘好了的穗子、一百个葡萄饼、两百个无花果饼，都驮在驴背上，'),
('CNV', '撒母耳记上', 9, 25, 19, '然后对她的仆人说：“你们先去，我随着你们来。”这事她却没有告诉她的丈夫拿八。'),
('CNV', '撒母耳记上', 9, 25, 20, '亚比该骑着驴，正从山坡下来，忽见大卫和跟随他的人也正从对面迎着她走下来，亚比该就与他相遇了。'),
('CNV', '撒母耳记上', 9, 25, 21, '大卫曾经说过：“我在旷野看守这人一切所有的，使他一切所有的一样也没有失落，实在是白费心机了。他竟然对我以恶报善。'),
('CNV', '撒母耳记上', 9, 25, 22, '如果我让这人一切所有的，就是一个男丁，留到明天早晨，神怎样惩罚大卫的仇敌，愿他也怎样加倍惩罚我。”'),
('CNV', '撒母耳记上', 9, 25, 23, '亚比该见了大卫，就急忙从驴背下来，俯伏在大卫面前，脸伏于地，向他叩拜。'),
('CNV', '撒母耳记上', 9, 25, 24, '她又俯伏在大卫的脚前，说：“我主啊，愿这罪孽归我。求你容婢女向你讲话，求你听婢女所说的话。'),
('CNV', '撒母耳记上', 9, 25, 25, '请我主不要把这个性情凶恶的人拿八放在心上。因为他的名字怎样，他的为人也怎样。他名叫拿八，他也真是愚笨。我主派来的仆人，你的婢女并没有看见。'),
('CNV', '撒母耳记上', 9, 25, 26, '我主啊，现在我指着永活的耶和华，又在你面前起誓，耶和华既然阻止了你流人的血，又阻止了你亲手报仇，愿你的仇敌和那些谋害我主的人，都像拿八一样。'),
('CNV', '撒母耳记上', 9, 25, 27, '现在，请把你婢女给我主带来的这礼物，赐给跟随我主的仆人。'),
('CNV', '撒母耳记上', 9, 25, 28, '求你饶恕你婢女的过犯。耶和华必为我主建立一个坚固的家，因为我主为耶和华争战；在你一生的日子里，在你身上也找不到什么过错。'),
('CNV', '撒母耳记上', 9, 25, 29, '虽然有人起来追赶你，寻索你的命，我主的性命必得保全在耶和华你的神生命的囊中。至于你仇敌的命，耶和华却要甩去，像从甩石机甩出去一样。'),
('CNV', '撒母耳记上', 9, 25, 30, '将来耶和华照着他应许的一切善待了你，立了你作以色列的领袖的时候，'),
('CNV', '撒母耳记上', 9, 25, 31, '我主就不致因为无缘无故流人的血或亲自报仇而良心不安，心里有愧了。耶和华恩待了我主以后，求你记念你的婢女。”'),
('CNV', '撒母耳记上', 9, 25, 32, '大卫对亚比该说：“耶和华以色列的神是应当称颂的！他今天差派你来迎接我。'),
('CNV', '撒母耳记上', 9, 25, 33, '你的智慧和你的为人也是应当称赞的，因为你今天阻止了我流人的血，又阻止了我亲手报仇。'),
('CNV', '撒母耳记上', 9, 25, 34, '我指着那拦阻了我加害你的永活的耶和华以色列的神起誓，如果你不及时来迎见我，到明天早晨，拿八所有的男丁必不留一个。”'),
('CNV', '撒母耳记上', 9, 25, 35, '大卫从亚比该手中接受了她带来给他的东西，就对她说：“你平平安安回家去吧！你看，我已经听了你的话，也答应了你的请求。”'),
('CNV', '撒母耳记上', 9, 25, 36, '亚比该到了拿八那里，他正在家中摆设筵席，好像帝王的筵席一样。拿八心里畅快，喝得烂醉如泥，所以无论大事小事亚比该都没有告诉他，直到第二天早晨。'),
('CNV', '撒母耳记上', 9, 25, 37, '到了早晨，拿八酒醒了，他的妻子才把这些事告诉他，他就吓得魂不附体，立刻中风瘫痪了。'),
('CNV', '撒母耳记上', 9, 25, 38, '大约过了十天，耶和华击打拿八，他就死了。'),
('CNV', '撒母耳记上', 9, 25, 39, '大卫听见拿八死了，就说：“耶和华是应当称颂的，因为他为我伸了拿八羞辱我的冤，又阻止了仆人行恶，也使拿八的恶归到他自己的头上。”于是大卫派人去对亚比该说要娶她作他的妻子。'),
('CNV', '撒母耳记上', 9, 25, 40, '大卫的仆人到了迦密去见亚比该，对她说：“大卫差派我们到你这里来，要娶你作他的妻子。”'),
('CNV', '撒母耳记上', 9, 25, 41, '亚比该就起来，面伏于地叩拜，说：“婢女愿意作女仆，洗我主人的脚！”'),
('CNV', '撒母耳记上', 9, 25, 42, '亚比该急忙起来，骑上驴，带着五个跟随她的女仆，跟从大卫的使者去了，就作了大卫的妻子。'),
('CNV', '撒母耳记上', 9, 25, 43, '大卫先娶了耶斯列人亚希暖，她们二人都作了他的妻子。'),
('CNV', '撒母耳记上', 9, 25, 44, '扫罗已经把他的女儿米甲，就是大卫的妻子，赐给了迦琳人拉亿的儿子帕提作妻子。'),
('CNV', '撒母耳记上', 9, 26, 1, '西弗人到基比亚来见扫罗，说：“大卫不是在旷野前面的哈基拉山中躲藏起来吗？”'),
('CNV', '撒母耳记上', 9, 26, 2, '扫罗就动身，下到西弗旷野去，跟随他的有三千以色列精兵，要在西弗的旷野寻索大卫。'),
('CNV', '撒母耳记上', 9, 26, 3, '那时，扫罗在旷野前面的哈基拉山的路旁安营，大卫仍然住在旷野。大卫看见扫罗来到旷野追寻他，'),
('CNV', '撒母耳记上', 9, 26, 4, '就派出探子，知道扫罗已经到了纳康。'),
('CNV', '撒母耳记上', 9, 26, 5, '大卫起来，来到扫罗安营的地方，看见扫罗和他的元帅，尼珥的儿子押尼珥睡卧的地方。扫罗睡在军营的中央，众人都在他的周围安营。'),
('CNV', '撒母耳记上', 9, 26, 6, '大卫问赫人亚希米勒和洗鲁雅的儿子约押的兄弟亚比筛，说：“谁愿与我一起下到扫罗的营里去呢？”亚比筛回答：“我愿与你一起下去。”'),
('CNV', '撒母耳记上', 9, 26, 7, '于是大卫和亚比筛趁着夜里到了众军那里。扫罗正躺在军营的中央睡着了，他的矛插在头旁的地上；押尼珥和众军都躺在他的周围。'),
('CNV', '撒母耳记上', 9, 26, 8, '亚比筛对大卫说：“今天神把你的仇敌交在你手里了。现在求你容我用矛把他刺透在地上，一刺就够，不必再刺。”'),
('CNV', '撒母耳记上', 9, 26, 9, '大卫却对亚比筛说：“不可杀死他，因为有谁伸手伤害耶和华的受膏者而无罪呢？”'),
('CNV', '撒母耳记上', 9, 26, 10, '大卫又说：“我指着永活的耶和华起誓，他或被耶和华击打，或死期到了，或下到战场阵亡了，'),
('CNV', '撒母耳记上', 9, 26, 11, '我在耶和华面前，绝对不敢伸手伤害耶和华的受膏者。现在，你可以把扫罗头旁的矛和水袋拿来，我们就走吧！”'),
('CNV', '撒母耳记上', 9, 26, 12, '于是大卫从扫罗的头旁拿了矛和水袋，他们二人就走了。没有人看见，没有人知道，也没有人醒来。他们都睡着了，因为耶和华使他们沉睡。'),
('CNV', '撒母耳记上', 9, 26, 13, '然后大卫过到另一边去，远远地站在山顶上，两者之间的距离很远。'),
('CNV', '撒母耳记上', 9, 26, 14, '大卫呼叫众人和尼珥的儿子押尼珥说：“押尼珥啊，你不答话吗？”押尼珥回答说：“你是谁，竟敢呼叫王？”'),
('CNV', '撒母耳记上', 9, 26, 15, '大卫对押尼珥说：“你不是一个男子汉吗？以色列人中有谁能与你相比呢？众民中有一个人来要杀害王你的主，你为什么没有保护王你的主呢？'),
('CNV', '撒母耳记上', 9, 26, 16, '你所作的这事不好。我指着永活的耶和华起誓，你们都是该死的，因为你们没有保护你的主，就是耶和华的受膏者。现在你看看王头旁的矛和水袋在哪里？”'),
('CNV', '撒母耳记上', 9, 26, 17, '扫罗认出是大卫的声音，就说：“我儿大卫啊！这是你的声音吗？”大卫说：“我主我王啊！是我的声音。”'),
('CNV', '撒母耳记上', 9, 26, 18, '又说：“我主为什么这样追赶仆人呢？我作了什么？我手里犯了什么过错？'),
('CNV', '撒母耳记上', 9, 26, 19, '现在求我主我王听你仆人的话。如果是耶和华激动你攻击我，愿耶和华收纳祭物；如果是人激动你，愿他们在耶和华面前受咒诅，因为他们今天把我赶出来，不容我在耶和华的产业上有分，说：‘你去服事别的神吧！’'),
('CNV', '撒母耳记上', 9, 26, 20, '现在，求王不要让我的血流在远离耶和华的地上，因为以色列王出来寻索我的性命，就像人在山中猎取一只鹧鸪一样。”'),
('CNV', '撒母耳记上', 9, 26, 21, '扫罗说：“我有罪了，我儿大卫啊，你回来吧！因为今天你看我的命为宝贵，我必不再害你。看哪！我作了糊涂事了，并且错得很厉害。”'),
('CNV', '撒母耳记上', 9, 26, 22, '大卫回答说：“看哪！王的矛在这里，可以叫一个仆人过来拿去。'),
('CNV', '撒母耳记上', 9, 26, 23, '耶和华必按着各人的公义和信实报答他；今天耶和华把你交在我手里，我却不愿伸手伤害耶和华的受膏者。'),
('CNV', '撒母耳记上', 9, 26, 24, '看哪，我今天怎样看重你的命，愿耶和华也怎样看重我的命，并且救我脱离一切患难。”'),
('CNV', '撒母耳记上', 9, 26, 25, '扫罗对大卫说：“我儿大卫啊，愿你得福，你必作成你所要作的，也必得胜。”于是大卫离去了，扫罗也回自己的地方去了。'),
('CNV', '撒母耳记上', 9, 27, 1, '大卫心里说：“总有一天，我会死在扫罗的手里，我倒不如逃奔到非利士人的国土，扫罗对我就会死心，不再在以色列全境寻索我，我就可以逃脱他的手了。”'),
('CNV', '撒母耳记上', 9, 27, 2, '于是大卫起来，和跟随他的六百人都越过边界，到迦特王玛俄的儿子亚吉那里去。'),
('CNV', '撒母耳记上', 9, 27, 3, '大卫和跟随他的人，以及他们各人的家眷，都与亚吉一同住在迦特。大卫的两个妻子，就是耶斯列人亚希暖和作过拿八妻子的迦密人亚比该也都住在那里。'),
('CNV', '撒母耳记上', 9, 27, 4, '有人告诉扫罗，大卫已经逃到迦特去了，扫罗就不再寻索他了。'),
('CNV', '撒母耳记上', 9, 27, 5, '大卫对亚吉说：“我若是在你眼前蒙恩，求你在这地的城市中，给我一个地方，让我住在那里。为什么要你的仆人与你一同住在王城呢？”'),
('CNV', '撒母耳记上', 9, 27, 6, '那天，亚吉就把洗革拉赐给大卫，因此，洗革拉直到今日还是属犹大王的。'),
('CNV', '撒母耳记上', 9, 27, 7, '大卫在非利士人的乡镇居住的日子，共有一年零四个月。'),
('CNV', '撒母耳记上', 9, 27, 8, '大卫和跟随他的人上去袭击基述人、基色人和亚玛力人，这些人自古以来就是这地的居民，居于书珥到埃及地之间。'),
('CNV', '撒母耳记上', 9, 27, 9, '大卫攻打那地，无论男女，都不让一人存活，又掳走了牛、羊、驴子、骆驼和衣服，然后回来，到亚吉那里去。'),
('CNV', '撒母耳记上', 9, 27, 10, '亚吉问：“你们今天袭击了什么地方呢？”大卫回答：“我们袭击了犹大的南方，耶拉蔑的南部，和基尼的南方。”'),
('CNV', '撒母耳记上', 9, 27, 11, '无论男女，大卫都不让一人活着带到迦特来，他说：“恐怕他们把我们的事告诉别人，说：‘大卫作了这样的事，他住在非利士人乡镇的日子，常常这样作。’”'),
('CNV', '撒母耳记上', 9, 27, 12, '亚吉相信了大卫，心里说：“他在自己的族人以色列中留下了臭名，他必永远作我的仆人了。”'),
('CNV', '撒母耳记上', 9, 28, 1, '那时，非利士人聚集他们的军队，要与以色列人争战。亚吉对大卫说：“你要清楚知道，你和跟随你的人都要在军队中与我一同出征。”'),
('CNV', '撒母耳记上', 9, 28, 2, '大卫回答亚吉说：“仆人所能作的事你都知道。”于是亚吉对大卫说：“好吧，我要立你永远作我的护卫长。”'),
('CNV', '撒母耳记上', 9, 28, 3, '那时，撒母耳死了，以色列众人都为他哀哭，把他埋葬在拉玛他自己的城里。扫罗曾经把交鬼的和行巫术的，都从国中除去了。'),
('CNV', '撒母耳记上', 9, 28, 4, '非利士人聚集起来，来到书念安营；扫罗也聚集以色列众人，在基利波安营。'),
('CNV', '撒母耳记上', 9, 28, 5, '扫罗看见了非利士人的军队，就惧怕，他的心大大发抖。'),
('CNV', '撒母耳记上', 9, 28, 6, '扫罗求问耶和华，耶和华却没有藉着梦，或乌陵，或先知回答他。'),
('CNV', '撒母耳记上', 9, 28, 7, '于是扫罗对他的臣仆说：“你们要为我寻找一个能交鬼的女人，我好去求问她。”他的臣仆回答他说：“在隐．多珥有一个能交鬼的女人。”'),
('CNV', '撒母耳记上', 9, 28, 8, '于是扫罗改装易服，带着两个人与他一同去了。他们夜里到了那女人那里。扫罗说：“请你用交鬼的法术，把我所告诉你的那人为我招上来。”'),
('CNV', '撒母耳记上', 9, 28, 9, '那女人回答他：“你是知道扫罗所作的，他已经把交鬼的和行巫术的，都从国中剪除了，你为什么要陷害我的命，使我死呢？”'),
('CNV', '撒母耳记上', 9, 28, 10, '扫罗指着耶和华起誓说：“我指着永活的耶和华起誓，你必不因这事受惩罚。”'),
('CNV', '撒母耳记上', 9, 28, 11, '那女人问：“我要为你招谁上来呢？”扫罗回答：“为我招撒母耳上来。”'),
('CNV', '撒母耳记上', 9, 28, 12, '那女人看见了撒母耳，就大声呼叫。那女人对扫罗说：“你为什么欺骗我？你就是扫罗！”'),
('CNV', '撒母耳记上', 9, 28, 13, '王对她说：“不要惧怕。你看见了什么？”那女人回答扫罗：“我看见有神灵从地里上来。”'),
('CNV', '撒母耳记上', 9, 28, 14, '扫罗问她：“他的容貌怎样？”她回答：“上来的是一个身披外袍的老人。”扫罗知道那人是撒母耳，就脸伏于地向他叩拜。'),
('CNV', '撒母耳记上', 9, 28, 15, '撒母耳对扫罗说：“你为什么搅扰我，把我招上来呢？”扫罗说：“我非常苦恼，非利士人正在攻打我，神又离开了我，不再藉着先知或异梦回答我。所以我请你上来，指示我应该怎样行。”'),
('CNV', '撒母耳记上', 9, 28, 16, '撒母耳说：“耶和华既然离开了你，又成了你的敌人，你为什么还问我呢？'),
('CNV', '撒母耳记上', 9, 28, 17, '耶和华已经照着他藉我所说的话行了，他把王国从你手中夺去，赐给别人，就是大卫。'),
('CNV', '撒母耳记上', 9, 28, 18, '因为你没有听从耶和华的话，没有执行他对亚玛力人所怀的烈怒，所以今天耶和华向你行了这样的事，'),
('CNV', '撒母耳记上', 9, 28, 19, '并且耶和华必把以色列和你一起都交在非利士人手里；明天你和你的儿子们都要和我一起了。耶和华必把以色列的军队交在非利士人手里。”'),
('CNV', '撒母耳记上', 9, 28, 20, '扫罗立刻全身仆倒在地上，他因撒母耳的话，非常惧怕，又因为他已经一日一夜没有吃饭，所以一点气力也没有。'),
('CNV', '撒母耳记上', 9, 28, 21, '那女人来到扫罗面前，见他非常惊慌，就对他说：“你看，婢女听从了你的话；我冒着生命危险，听从了你对我所说的话。'),
('CNV', '撒母耳记上', 9, 28, 22, '现在求你也听从婢女的话，允许我在你面前摆上一点食物。你吃了，身体就有气力，可以走路。”'),
('CNV', '撒母耳记上', 9, 28, 23, '扫罗不肯，说：“我不吃。”可是他的臣仆和那女人再三劝他，他才听从了他们的话，从地上起来，坐在床上。'),
('CNV', '撒母耳记上', 9, 28, 24, '那女人的家里有一头肥牛犊，她急忙把它宰了，又拿点面粉，搓好了，烤成无酵饼，'),
('CNV', '撒母耳记上', 9, 28, 25, '送到扫罗和他臣仆的面前；他们吃了以后，当夜就起身离去了。'),
('CNV', '撒母耳记上', 9, 29, 1, '非利士人把他们所有的军队都聚集在亚弗，以色列人却在耶斯列的泉旁安营。'),
('CNV', '撒母耳记上', 9, 29, 2, '非利士人的首领各率领百人或千人前进；大卫和跟随他的人也跟在亚吉的后面前进。'),
('CNV', '撒母耳记上', 9, 29, 3, '非利士人的领袖说：“这些希伯来人在这里作什么？”亚吉对非利士人的领袖说：“这人不是以色列王扫罗的臣仆大卫吗？他已经在我这里有好些年日了。自从他降服我的一天，直到今日，我未曾发现他有什么过错。”'),
('CNV', '撒母耳记上', 9, 29, 4, '非利士人的领袖向亚吉发怒，对他说：“你叫这人回去，好让他回到你为他安排的地方去。他不可与我们一同下战场，免得他在战场上成为我们的对头。这人可用什么去得他主人的欢心呢？岂不是用我们这些人的头吗？'),
('CNV', '撒母耳记上', 9, 29, 5, '这人不就是大卫吗？从前以色列的妇女向他歌唱跳舞说：‘扫罗杀死千千，大卫杀死万万！’”'),
('CNV', '撒母耳记上', 9, 29, 6, '亚吉把大卫叫来，对他说：“我指着永活的耶和华说，你是正直的人，你与我在军中出入，我感到很满意，因为自从你到我这里来的那一天，直到今日，我未曾在你身上找到什么过失；只是各首领不喜欢你。'),
('CNV', '撒母耳记上', 9, 29, 7, '现在，你可以回去，平平安安走吧！不要行非利士人的首领看为恶的事。”'),
('CNV', '撒母耳记上', 9, 29, 8, '大卫对亚吉说：“我作了什么呢？自从我来到你面前的那一天，直到今日，你在仆人身上找到什么，使我不能与我主我王的仇敌争战呢？”'),
('CNV', '撒母耳记上', 9, 29, 9, '亚吉回答大卫，说：“我知道你在我眼中是个好人，像神的使者一样；只是非利士人的领袖曾经说过：‘他不可与我们一同上战场。’'),
('CNV', '撒母耳记上', 9, 29, 10, '所以明天早晨，你和跟你来的人，就是你主人的仆人都要清早起来。你们明天早晨都要早起，天一亮你们就要离开。”'),
('CNV', '撒母耳记上', 9, 29, 11, '于是大卫和跟随他的人清早起来，一早就离开，回到非利士人的地去。非利士人也上耶斯列去了。'),
('CNV', '撒母耳记上', 9, 30, 1, '第三天，大卫和跟随他的人到了洗革拉。那时亚玛力人袭击了南地和洗革拉。他们攻破了洗革拉，又放火焚烧。'),
('CNV', '撒母耳记上', 9, 30, 2, '他们把城里的妇女，无论大小都掳走了。他们没有杀人，都带着他们从原路回去了。'),
('CNV', '撒母耳记上', 9, 30, 3, '大卫和跟随他的人到了那城，看见城已经被火烧毁，他们的妻子、儿女都被掳走了，'),
('CNV', '撒母耳记上', 9, 30, 4, '就放声大哭，直哭到没有力气再哭。'),
('CNV', '撒母耳记上', 9, 30, 5, '大卫的两个妻子，耶斯列人亚希暖和作过拿八妻子的迦密人亚比该，也都被掳去了。'),
('CNV', '撒母耳记上', 9, 30, 6, '大卫处境非常困难，因为众人都为自己的儿女心中苦恼，说要用石头打死大卫；但大卫靠着耶和华他的神坚强起来。'),
('CNV', '撒母耳记上', 9, 30, 7, '大卫对亚希米勒的儿子、亚比亚他祭司说：“请你把以弗得带到我这里来。”亚比亚他就把以弗得带到大卫那里去。'),
('CNV', '撒母耳记上', 9, 30, 8, '大卫求问耶和华说：“我可以追赶这群匪徒吗？我可以追上他们吗？”耶和华回答他：“你可以追赶，你必定追上，也必定把一切救回来。”'),
('CNV', '撒母耳记上', 9, 30, 9, '于是大卫和跟随他的六百人出发。他们到了比梭溪，有些跟不上的就留在那里。'),
('CNV', '撒母耳记上', 9, 30, 10, '有二百人太疲乏，不能渡过比梭溪，就留在那里，大卫和四百人继续追赶。'),
('CNV', '撒母耳记上', 9, 30, 11, '他们在田野里遇见一个埃及人，就把他带到大卫那里。他们给他饭吃，又给他水喝。'),
('CNV', '撒母耳记上', 9, 30, 12, '又给他一块无花果饼，两个葡萄饼。他吃了，精神就恢复过来，因为他已经三天三夜没有吃东西，没有喝水了。'),
('CNV', '撒母耳记上', 9, 30, 13, '大卫问他：“你是属谁的？你从哪里来？”他回答：“我是个埃及的青年人，是亚玛力人的奴仆。因为我三天前病了，我的主人就把我丢弃了。'),
('CNV', '撒母耳记上', 9, 30, 14, '我们侵袭了基利提的南方和属犹大地的南方，以及迦勒地的南方，又用火烧了洗革拉。”'),
('CNV', '撒母耳记上', 9, 30, 15, '大卫对他说：“你愿意带我下到那一群匪徒那里吗？”他回答：“如果你指着神向我起誓，不杀死我，也不把我交在我主人手里，我就带你下到那一群匪徒那里去。”'),
('CNV', '撒母耳记上', 9, 30, 16, '他带大卫下去。匪徒们都分散在各处，正在吃喝、跳舞，因为他们从非利士地和犹大地抢来的战利品很多。'),
('CNV', '撒母耳记上', 9, 30, 17, '大卫击杀他们，从黄昏直到次日的晚上。除了四百个骑骆驼的年轻人逃跑了以外，他们当中一个人也没有逃脱。'),
('CNV', '撒母耳记上', 9, 30, 18, '亚玛力人抢去的一切，大卫都救回来了，也救回了他的两个妻子。'),
('CNV', '撒母耳记上', 9, 30, 19, '无论大小，不分男女，无论是他们抢来的，或是被人掳去的，大卫都夺回来，没有失落一样。'),
('CNV', '撒母耳记上', 9, 30, 20, '大卫夺了所有的羊群和牛群，跟从大卫的人把它们赶到原有的群畜面前，说：“这是大卫的战利品。”'),
('CNV', '撒母耳记上', 9, 30, 21, '大卫来到那二百人那里，那些人因太疲乏不能跟随大卫去，而留在比梭溪旁；他们出来迎接大卫和跟随他的众人。大卫接近众人的时候，就向他们问安。'),
('CNV', '撒母耳记上', 9, 30, 22, '与大卫一起去的那些人中，有些恶人和流氓说：“他们没有和我们一起去，我们就不把夺回来的战利品分给他们，只把他们各人的妻子和儿子还给他们，让他们领回去就是了。”'),
('CNV', '撒母耳记上', 9, 30, 23, '大卫说：“兄弟们，耶和华赐给我们的，你们不可以这样作。他保护了我们，又把那些攻击我们的匪徒交在我们手里。'),
('CNV', '撒母耳记上', 9, 30, 24, '这事谁要听从你们呢？下战场的得多少，留守武器的也得多少，应当大家平分。”'),
('CNV', '撒母耳记上', 9, 30, 25, '从那天起，大卫定此为以色列的律例典章，直到今日。'),
('CNV', '撒母耳记上', 9, 30, 26, '大卫到了洗革拉，就从战利品中取一部分送给他的朋友、犹大的长老，说：“看哪，这是从耶和华的仇敌那里得来的战利品，送给你们作礼物。”'),
('CNV', '撒母耳记上', 9, 30, 27, '他送礼物给在伯特利的、在南地拉末的、在雅提珥的、'),
('CNV', '撒母耳记上', 9, 30, 28, '在亚罗珥的、在息末的、在以实提莫的、'),
('CNV', '撒母耳记上', 9, 30, 29, '在拉哈勒的、在耶拉蔑各城的、在基尼各城的、'),
('CNV', '撒母耳记上', 9, 30, 30, '在何珥玛的、在歌拉珊的、在亚挞的、'),
('CNV', '撒母耳记上', 9, 30, 31, '在希伯仑的人，又送给一切大卫及其跟随者所到过之地的人。'),
('CNV', '撒母耳记上', 9, 31, 1, '非利士人与以色列人交战。以色列人从非利士人面前逃跑，有很多人在基利波山上倒毙。'),
('CNV', '撒母耳记上', 9, 31, 2, '非利士人紧紧追赶扫罗和他的众子，击杀了扫罗的儿子约拿单、亚比拿达和麦基舒亚。'),
('CNV', '撒母耳记上', 9, 31, 3, '战争激烈，扫罗受到猛烈的攻击，弓箭手发现了他，射箭的人射中了他，他的伤势严重；'),
('CNV', '撒母耳记上', 9, 31, 4, '扫罗就对替他拿兵器的人说：“拔出你的刀来，把我刺透，免得这些未受割礼的人来把我刺透，戏弄我。”但替他拿兵器的人不肯这样作，因为他非常害怕。于是扫罗拿过刀来，自己伏在刀上死了。'),
('CNV', '撒母耳记上', 9, 31, 5, '替他拿兵器的人看见扫罗死了，他也伏在自己的刀上，与扫罗一起死了。'),
('CNV', '撒母耳记上', 9, 31, 6, '这样，扫罗和他的三个儿子，以及替他拿兵器的人，还有所有跟随他的人，都在那一天一同死了。'),
('CNV', '撒母耳记上', 9, 31, 7, '在山谷那边，和约旦河那边的以色列人，看见以色列人逃跑，扫罗和他的儿子都死了，他们就弃城逃跑。非利士人就来住在城中。'),
('CNV', '撒母耳记上', 9, 31, 8, '第二天，非利士人来剥那些被杀的人的衣物的时候，发现扫罗和他的三个儿子都倒毙在基利波山上，'),
('CNV', '撒母耳记上', 9, 31, 9, '就砍下他的头，解下他的兵器，又派人到非利士地的各处，去向他们的偶像的庙和人民报信。'),
('CNV', '撒母耳记上', 9, 31, 10, '他们把扫罗的兵器放在亚斯他录的庙里，又把他的尸体钉在伯．珊的城墙上。'),
('CNV', '撒母耳记上', 9, 31, 11, '基列．雅比的居民听见非利士人向扫罗所行的事，'),
('CNV', '撒母耳记上', 9, 31, 12, '所有的勇士就动身，走了一整夜，把扫罗的尸体和他三个儿子的尸体都从伯．珊的城墙上取下来，带回雅比，在那里把他们烧了，'),
('CNV', '撒母耳记上', 9, 31, 13, '又把他们的骸骨埋葬在雅比的垂柳树下，并且禁食七天。'),
('CNV', '撒母耳记下', 10, 1, 1, '扫罗死后，大卫杀退了亚玛力人回来，就在洗革拉住了两天。'),
('CNV', '撒母耳记下', 10, 1, 2, '第三天，忽然有一个人从扫罗的营回来，衣服撕裂，头上蒙灰。这人一来到大卫面前，就俯伏在地上叩拜他。'),
('CNV', '撒母耳记下', 10, 1, 3, '大卫问他：“你从哪里来？”他对他说：“我是从以色列的营中逃出来的。”'),
('CNV', '撒母耳记下', 10, 1, 4, '大卫又问他：“情况怎么样？请你告诉我！”他回答：“众人都逃离战场，他们中间不但有许多人倒地阵亡，连扫罗和他的儿子约拿单也死了。”'),
('CNV', '撒母耳记下', 10, 1, 5, '于是，大卫问那向他报信的年轻人：“你怎么知道扫罗和他的儿子死了呢？”'),
('CNV', '撒母耳记下', 10, 1, 6, '那个向大卫报信的年轻人回答：“我刚巧在基利波山，看见扫罗靠在自己的矛枪上，又见有战车和马兵紧紧地追赶他。'),
('CNV', '撒母耳记下', 10, 1, 7, '他回头看到我，就呼唤我。我说：‘我在这里。’'),
('CNV', '撒母耳记下', 10, 1, 8, '他问我：‘你是谁？’我回答他：‘我是亚玛力人。’'),
('CNV', '撒母耳记下', 10, 1, 9, '于是他对我说：‘请你站到我身边来，把我杀死，因为痛苦抓住我，我却还死不了。’'),
('CNV', '撒母耳记下', 10, 1, 10, '我就站到他身边去，把他杀了，因为我知道他一倒下，就不能再活了。我摘下他头上的王冠，取下他臂上的手镯，带到这里来奉给我主。”'),
('CNV', '撒母耳记下', 10, 1, 11, '大卫就抓住自己的衣服，把它们全都撕裂。所有与他在一起的人也都是这样。'),
('CNV', '撒母耳记下', 10, 1, 12, '他们为了扫罗、他的儿子约拿单、耶和华的子民和以色列家的缘故悲哀、哭泣、禁食直到晚上，因为他们已经倒毙在刀下。'),
('CNV', '撒母耳记下', 10, 1, 13, '大卫问那向他报信的年轻人：“你是哪里的人？”他回答：“我是个寄居这地的亚玛力人的儿子。”'),
('CNV', '撒母耳记下', 10, 1, 14, '大卫对他说：“你伸手毁灭耶和华的受膏者，怎么还不惧怕呢？”'),
('CNV', '撒母耳记下', 10, 1, 15, '于是大卫叫了一个年轻人来，说：“你上前去，砍倒他。”那年轻人击杀他，他就死了。'),
('CNV', '撒母耳记下', 10, 1, 16, '大卫对他说：“你流人血的罪要归到自己的头上，因为你亲口作证指控自己说：‘我杀了耶和华的受膏者。’”'),
('CNV', '撒母耳记下', 10, 1, 17, '大卫为扫罗和他的儿子约拿单作了这首哀歌。'),
('CNV', '撒母耳记下', 10, 1, 18, '他又吩咐要把这首“弓歌”教导犹大人。'),
('CNV', '撒母耳记下', 10, 1, 19, '“以色列啊！尊荣的人都在高处被杀，勇士怎么都已仆倒！'),
('CNV', '撒母耳记下', 10, 1, 20, '你们不要在迦特报道，不要在亚实基伦的街上宣扬，免得非利士的女子欢喜，免得未受割礼之人的女子快乐。'),
('CNV', '撒母耳记下', 10, 1, 21, '基利波的群山啊！愿雨露都不降在你们上面，愿你们的田地不产供物。因为勇士的盾牌在那里玷污，扫罗的盾牌没有用油抹亮。'),
('CNV', '撒母耳记下', 10, 1, 22, '不见被杀者的血、勇士的脂油，约拿单的弓不缩回，扫罗的剑也不空空返回。'),
('CNV', '撒母耳记下', 10, 1, 23, '扫罗和约拿单，生时相亲相爱，死时也不分离。他们比鹰还快速，比狮子更勇猛。'),
('CNV', '撒母耳记下', 10, 1, 24, '以色列的女子啊！你们要为扫罗哭泣，他曾给你们穿上朱红色豪华的衣服，又给你们的外衣加上金饰。'),
('CNV', '撒母耳记下', 10, 1, 25, '勇士怎么会在战阵上倒毙，约拿单在高处被刺死！'),
('CNV', '撒母耳记下', 10, 1, 26, '我的兄弟约拿单啊！我为你悲痛，你是我最好的朋友，你对我的爱情奇妙，远超过妇女的爱情。'),
('CNV', '撒母耳记下', 10, 1, 27, '勇士怎么会倒毙！争战的武器怎么会毁灭！”'),
('CNV', '撒母耳记下', 10, 2, 1, '这事以后，大卫求问耶和华说：“我可以上犹大的一座城去吗？”耶和华回答：“你上去吧。”大卫又问：“我应该上到哪里去呢？”他回答：“上希伯仑去！”'),
('CNV', '撒母耳记下', 10, 2, 2, '于是大卫带着他的两个妻子，一个是耶斯列人亚希暖，一个是作过迦密人拿八妻子的亚比该，上到那里去了。'),
('CNV', '撒母耳记下', 10, 2, 3, '大卫也把与他在一起的人，和他们各人的家眷都带上去。他们就在希伯仑的城镇里住下来。'),
('CNV', '撒母耳记下', 10, 2, 4, '于是犹大人来到希伯仑，在那里膏立了大卫作王，统治犹大家。有人报告大卫说：“埋葬扫罗的是基列‧雅比人。”'),
('CNV', '撒母耳记下', 10, 2, 5, '大卫就差派使者到基列‧雅比人那里去，对他们说：“愿耶和华赐福给你们，因为你们厚待了你们的主扫罗，把他埋葬了。'),
('CNV', '撒母耳记下', 10, 2, 6, '你们既作了这事，现在就愿耶和华以慈爱和诚实待你们，我也要善待你们。'),
('CNV', '撒母耳记下', 10, 2, 7, '现在你们要坚强，要作勇敢的人，因为你们的主扫罗已经死了；犹大家已经膏立了我作他们的王了。”'),
('CNV', '撒母耳记下', 10, 2, 8, '当时，扫罗的元帅尼珥的儿子押尼珥已经领着扫罗的儿子伊施波设，把他带过河到玛哈念去，'),
('CNV', '撒母耳记下', 10, 2, 9, '并且立了他作王，统治基列、亚书利、耶斯列、以法莲、便雅悯和以色列众人。'),
('CNV', '撒母耳记下', 10, 2, 10, '扫罗的儿子伊施波设作以色列王的时候，已经四十岁；他作王共两年。犹大家却追随大卫。'),
('CNV', '撒母耳记下', 10, 2, 11, '大卫在希伯仑作王统治犹大家的时候共有七年零六个月。'),
('CNV', '撒母耳记下', 10, 2, 12, '尼珥的儿子押尼珥带着扫罗的儿子伊施波设的仆从，离开玛哈念，到基遍去。'),
('CNV', '撒母耳记下', 10, 2, 13, '洗鲁雅的儿子约押和大卫的臣仆也出来，在基遍的水池旁边与他们会面。大家都坐下，一队在水池这边，一队在水池那边。'),
('CNV', '撒母耳记下', 10, 2, 14, '押尼珥对约押说：“让年轻人起来，在我们面前比比武。”约押说：“好！叫他们起来。”'),
('CNV', '撒母耳记下', 10, 2, 15, '他们就起来，按着人数走过去：属便雅悯，就是属扫罗的儿子伊施波设的，有十二人；属大卫臣仆的也有十二人。'),
('CNV', '撒母耳记下', 10, 2, 16, '他们各人都紧紧抓住对手的头，用刀刺进对手的肋旁，于是他们全都倒毙。所以在基遍那地方就叫作希利甲‧哈素林。'),
('CNV', '撒母耳记下', 10, 2, 17, '那天的战事非常激烈，结果押尼珥和以色列人败在大卫的臣仆面前。'),
('CNV', '撒母耳记下', 10, 2, 18, '洗鲁雅的三个儿子约押、亚比筛和亚撒黑都在那里。亚撒黑的腿轻快如野地的羚羊一般。'),
('CNV', '撒母耳记下', 10, 2, 19, '亚撒黑追赶押尼珥，紧紧地跟着他，不偏左，也不偏右。'),
('CNV', '撒母耳记下', 10, 2, 20, '押尼珥往后瞧着，说：“你是亚撒黑吗？”他回答：“我正是。”'),
('CNV', '撒母耳记下', 10, 2, 21, '押尼珥对他说：“你或转左或转右，抓住一个年轻人，夺去他的武器吧！”可是亚撒黑不愿意离开不追赶他。'),
('CNV', '撒母耳记下', 10, 2, 22, '押尼珥再一次对亚撒黑说：“你离开，别追赶我！我为什么要把你砍倒在地上呢？以后怎么还有脸见你的哥哥约押呢？”'),
('CNV', '撒母耳记下', 10, 2, 23, '亚撒黑不肯离开，所以押尼珥就用枪的尾端刺入了他的肚子，枪从他的背后穿出。亚撒黑仆倒在那里，当场死了。所有来到亚撒黑倒毙的地方的人，都站住不动。'),
('CNV', '撒母耳记下', 10, 2, 24, '约押和亚比筛却继续追赶押尼珥。日落的时候，他们来到亚玛山，就在通往基遍旷野的路旁，基亚的对面。'),
('CNV', '撒母耳记下', 10, 2, 25, '便雅悯人集结在押尼珥后面，站在一座山头上，列成一个队伍。'),
('CNV', '撒母耳记下', 10, 2, 26, '押尼珥对约押喊叫，说：“刀剑要不停地杀人吗？你不知道结局是痛苦的吗？你要等到什么时候才吩咐人民转去，不追赶自己的兄弟呢？”'),
('CNV', '撒母耳记下', 10, 2, 27, '约押说：“我指着永活的神起誓，如果你没有说过比武的话，大家必在早晨的时候离去，不再追赶自己的兄弟。”'),
('CNV', '撒母耳记下', 10, 2, 28, '于是约押吹响号角，众人就站住，不再追赶以色列人，也不再打仗了。'),
('CNV', '撒母耳记下', 10, 2, 29, '押尼珥和属他的人，整夜走过亚拉巴，渡过约旦河，又走过毕伦，才回到玛哈念。'),
('CNV', '撒母耳记下', 10, 2, 30, '约押追赶押尼珥回来，集合所有人的时候，发现在大卫的臣仆中，除了亚撒黑以外，还少了十九个人。'),
('CNV', '撒母耳记下', 10, 2, 31, '但大卫的臣仆击杀便雅悯人和跟随押尼珥的人，共有三百六十人死了。'),
('CNV', '撒母耳记下', 10, 2, 32, '他们把亚撒黑抬回去，埋葬在伯利恒他父亲的坟墓里。约押和属他的人走了一整夜，天亮的时候才回到希伯仑。'),
('CNV', '撒母耳记下', 10, 3, 1, '扫罗家和大卫家之间的战争相持很久。大卫家逐渐兴盛，扫罗家却日趋衰微。'),
('CNV', '撒母耳记下', 10, 3, 2, '大卫在希伯仑生了几个儿子：他的长子暗嫩，是耶斯列人亚希暖所生的。'),
('CNV', '撒母耳记下', 10, 3, 3, '次子基利押，是作过迦密人拿八的妻子亚比该所生的。三子押沙龙，是基述王达买的女儿玛迦所生的。'),
('CNV', '撒母耳记下', 10, 3, 4, '四子亚多尼雅，是哈及所生的。五子示法提雅，是亚比他所生的。'),
('CNV', '撒母耳记下', 10, 3, 5, '六子以特念，是大卫妻子以格拉所生的。这些儿子都是大卫在希伯仑所生的。'),
('CNV', '撒母耳记下', 10, 3, 6, '当扫罗家和大卫家交战的时候，押尼珥使自己在扫罗家的权势日渐强大。'),
('CNV', '撒母耳记下', 10, 3, 7, '扫罗有一个妃子，名叫利斯巴，是爱亚的女儿。伊施波设对押尼珥说：“你为什么亲近我父亲的妃子呢？”'),
('CNV', '撒母耳记下', 10, 3, 8, '押尼珥因伊施波设的话非常忿怒，说：“我是犹大的狗头吗？今天我厚待你的父亲扫罗家、他的兄弟和他的朋友，没有把你交在大卫的手中；可是，今天你竟为了这女人的事来找我的错！'),
('CNV', '撒母耳记下', 10, 3, 9, '我若不按着耶和华向大卫所起誓应许的去行：废去扫罗家的王国，建立大卫的王位，使他统治以色列和犹大，从但直到别是巴，愿神降罚押尼珥，重重地降罚他。”'),
('CNV', '撒母耳记下', 10, 3, 11, '伊施波设因为惧怕押尼珥，就连一句话也不敢回答他。'),
('CNV', '撒母耳记下', 10, 3, 12, '押尼珥差派使者代表他去见大卫，说：“这地是属谁的呢？”又说：“你与我立约，我就必帮助你，使全以色列都归顺你。”'),
('CNV', '撒母耳记下', 10, 3, 13, '大卫说：“好！我与你立约。不过，我要求你一件事：你来见我面的时候，首先要把扫罗的女儿米甲带来，否则你必不得见我的面。”'),
('CNV', '撒母耳记下', 10, 3, 14, '后来，大卫差派使者去见扫罗的儿子伊施波设，说：“请你把我的妻子米甲还给我，她是我从前用一百个非利士人的包皮聘下的。”'),
('CNV', '撒母耳记下', 10, 3, 15, '于是伊施波设派人去，把米甲从拉亿的儿子她丈夫帕铁那里接回来。'),
('CNV', '撒母耳记下', 10, 3, 16, '米甲的丈夫与她一起去，跟在她后面，一边走、一边哭，一直跟到巴户琳。押尼珥对他说：“你去吧！回去吧！”他只好回去了。'),
('CNV', '撒母耳记下', 10, 3, 17, '押尼珥与以色列的长老商议说：“从前你们希望大卫作你们的王。'),
('CNV', '撒母耳记下', 10, 3, 18, '现在可以实现了！因为耶和华曾经论到大卫说：‘我要藉着我的仆人大卫的手，把我的子民以色列从非利士人和他们所有敌人的手中拯救出来。’”'),
('CNV', '撒母耳记下', 10, 3, 19, '押尼珥也把这话说给便雅悯人听，然后又去希伯仑，把以色列人和便雅悯全都同意的一切事说给大卫听。'),
('CNV', '撒母耳记下', 10, 3, 20, '押尼珥带着二十个人，来到希伯仑见大卫的时候，大卫就为押尼珥和与他同来的人摆设筵席。'),
('CNV', '撒母耳记下', 10, 3, 21, '后来，押尼珥对大卫说：“让我去把以色列众人召集到我主我王这里来，好叫他们与你立约，这样你就可以照着自己的心愿统治所有的人。”于是大卫打发押尼珥回去，他就平平安安地走了。'),
('CNV', '撒母耳记下', 10, 3, 22, '那时，大卫的臣仆和约押攻击敌人回来，带回许多的战利品。当时，押尼珥不在希伯仑大卫那里，因为大卫已经打发他离去，他也平平安安地走了。'),
('CNV', '撒母耳记下', 10, 3, 23, '约押和跟随他的全军一到达，就有人告诉约押，尼珥的儿子押尼珥曾经来见过王。王打发他离去，他已经平平安安地走了。'),
('CNV', '撒母耳记下', 10, 3, 24, '约押进去见王，说：“你作了什么事？押尼珥来见你，你为什么把他送走？现在他已经走了。'),
('CNV', '撒母耳记下', 10, 3, 25, '你认识尼珥的儿子押尼珥，他来是要欺骗你，是要了解你的起居行动和你所作的一切事。”'),
('CNV', '撒母耳记下', 10, 3, 26, '约押从大卫那里出来，就差派使者去追赶押尼珥，使者从西拉的水井那里把他带回来。可是，大卫一点都不知道。'),
('CNV', '撒母耳记下', 10, 3, 27, '押尼珥回到了希伯仑，约押就拉他到城门的瓮洞里与他密谈。约押就在那里刺透他的肚子，他就死了。这样，他替自己的兄弟亚撒黑报了血仇。'),
('CNV', '撒母耳记下', 10, 3, 28, '事后大卫听到了，就说：“关于尼珥的儿子押尼珥的血案，我和我的国家，在耶和华面前永远是无辜的。'),
('CNV', '撒母耳记下', 10, 3, 29, '愿这流人血的罪归到约押的头上和他父亲的全家！又愿约押家不断有患血漏病的、长痲风的、拿拐杖的、倒毙在剑下的和缺乏粮食的。”'),
('CNV', '撒母耳记下', 10, 3, 30, '因押尼珥在基遍的战场上，杀死了他们的兄弟亚撒黑，约押和他的兄弟亚比筛就杀了押尼珥。'),
('CNV', '撒母耳记下', 10, 3, 31, '大卫对约押和与他在一起的众人说：“你们要撕裂衣服，腰束麻布，在押尼珥面前哀哭！”大卫王也走在棺木后面。'),
('CNV', '撒母耳记下', 10, 3, 32, '他们把押尼珥埋葬在希伯仑。王在押尼珥的墓旁放声大哭，众人也都哭了。'),
('CNV', '撒母耳记下', 10, 3, 33, '王又为押尼珥作了哀歌，说：“难道押尼珥死去，要像愚妄的人死去一样吗？'),
('CNV', '撒母耳记下', 10, 3, 34, '你的手没有被绳索绑住，你的脚也没有被铜链锁住，你倒毙，好像人在暴徒面前倒毙一样！”于是，众民又为押尼珥哀哭。'),
('CNV', '撒母耳记下', 10, 3, 35, '还在白天的时候，众人都来劝大卫吃点饭；大卫起誓说：“我若在日落以前吃饭或吃什么东西，愿神降罚我，重重地降罚我。”'),
('CNV', '撒母耳记下', 10, 3, 36, '众人看见了，就都喜悦。王所作的一切，他们都很喜悦。'),
('CNV', '撒母耳记下', 10, 3, 37, '那一天众人和全以色列都知道，杀死尼珥的儿子押尼珥，并不是出于王的意思。'),
('CNV', '撒母耳记下', 10, 3, 38, '王对他的臣仆说：“你们不知道今天在以色列中，有一位将领和伟人倒毙了吗？'),
('CNV', '撒母耳记下', 10, 3, 39, '今天我虽然受膏为王，但我还是幼弱的。洗鲁雅的两个儿子太强了，非我所能应付。愿耶和华照着恶人所行的恶，报应恶人。”'),
('CNV', '撒母耳记下', 10, 4, 1, '扫罗的儿子伊施波设听见押尼珥在希伯仑死了，就怕得手都发软，以色列众人也都惊惶失措。'),
('CNV', '撒母耳记下', 10, 4, 2, '扫罗的儿子伊施波设有两个统率突击队的将领，一个名叫巴拿，一个名叫利甲，他们是便雅悯支派比录人临门的儿子。（比录也算是便雅悯的一部分。'),
('CNV', '撒母耳记下', 10, 4, 3, '比录人原先逃到基他音，就在那里寄居，直到今日。）'),
('CNV', '撒母耳记下', 10, 4, 4, '扫罗的儿子约拿单有一个儿子，双腿都跛了。扫罗和约拿单死亡的消息从耶斯列传到的时候，他才五岁。他的乳母抱着他逃跑。乳母在慌忙中逃跑，孩子掉了下来，腿就瘸了。他的名字叫米非波设。'),
('CNV', '撒母耳记下', 10, 4, 5, '比录人临门的儿子利甲和巴拿出去，约在正午炎热的时候，来到了伊施波设的家。伊施波设正在睡午觉。'),
('CNV', '撒母耳记下', 10, 4, 6, '他们进了屋里，假装要拿麦子，就刺透伊施波设的肚腹，然后利甲和他的兄弟巴拿都逃脱了。'),
('CNV', '撒母耳记下', 10, 4, 7, '他们进屋子的时候，伊施波设正在自己的卧室里躺在床上，他们刺透他，把他杀死，然后割下他的头，拿着头颅在亚拉巴的路上走了一夜，'),
('CNV', '撒母耳记下', 10, 4, 8, '把伊施波设的头带到希伯仑去见大卫，对王说：“你的仇敌扫罗过去常常寻索你的命。看哪！这是他儿子伊施波设的头。今天耶和华在扫罗和他后裔的身上为我主我王报了仇了。”'),
('CNV', '撒母耳记下', 10, 4, 9, '大卫回答比录人临门的儿子利甲和他的兄弟巴拿，说：“我指着那曾救赎我的命脱离一切患难的永活的耶和华起誓：'),
('CNV', '撒母耳记下', 10, 4, 10, '从前有人向我报信说：‘看哪！扫罗死了。’他自以为是报好消息，我却抓住他，把他杀在洗革拉，这就是我给他作报好消息的酬报。'),
('CNV', '撒母耳记下', 10, 4, 11, '何况恶人在义人的家里，把义人杀在床上。现在我怎能不从你们手中追讨流他血的罪，把你们从这世上除灭呢？”'),
('CNV', '撒母耳记下', 10, 4, 12, '于是，大卫吩咐年轻人把他们杀了，并且砍断他们的手脚，把身体挂在希伯仑的水池旁边；却把伊施波设的头拿去，埋葬在希伯仑押尼珥的坟墓里。'),
('CNV', '撒母耳记下', 10, 5, 1, '以色列众支派都到希伯仑来见大卫，说：“看哪！我们都是你的骨肉至亲。'),
('CNV', '撒母耳记下', 10, 5, 2, '从前扫罗作我们的王的时候，领导以色列人行动的是你。耶和华也曾对你说：‘你要牧养我的子民以色列，要作以色列的领袖。’”'),
('CNV', '撒母耳记下', 10, 5, 3, '以色列的众长老都到希伯仑来见王。大卫王在希伯仑耶和华面前与他们立约，他们就膏立大卫作以色列的王。'),
('CNV', '撒母耳记下', 10, 5, 4, '大卫登基的时候是三十岁，在位共四十年。'),
('CNV', '撒母耳记下', 10, 5, 5, '他在希伯仑作犹大的王七年零六个月；在耶路撒冷作全以色列和犹大的王三十三年。'),
('CNV', '撒母耳记下', 10, 5, 6, '王和随从他的人到了耶路撒冷，要攻打住在那地的耶布斯人。耶布斯人对大卫说：“你不能进这里来，这些瞎眼的、跛脚的就能把你抵挡住。”他们心里想：“大卫决不能进那里去。”'),
('CNV', '撒母耳记下', 10, 5, 7, '大卫却攻取了锡安的保障，就是大卫的城。'),
('CNV', '撒母耳记下', 10, 5, 8, '那一天大卫说：“攻打耶布斯人的，要把大卫心中恨恶的‘瞎子’和‘瘸子’丢进水沟里。”因此有句俗语说：“瞎眼的或瘸腿的，都不能进殿里。”'),
('CNV', '撒母耳记下', 10, 5, 9, '后来大卫住在保障里，称保障为“大卫的城”。大卫又从米罗向里面周围筑墙。'),
('CNV', '撒母耳记下', 10, 5, 10, '大卫渐渐强大，因为耶和华万军的神与他同在。'),
('CNV', '撒母耳记下', 10, 5, 11, '推罗王希兰差派使者来见大卫，又送来香柏木、木匠和石匠，他们就给大卫建造宫殿。'),
('CNV', '撒母耳记下', 10, 5, 12, '大卫就知道耶和华已经立他作以色列的王，又因自己的子民以色列的缘故，使他的国兴盛。'),
('CNV', '撒母耳记下', 10, 5, 13, '大卫离开希伯仑后，在耶路撒冷又娶了多位妃嫔，并且生了很多儿女。'),
('CNV', '撒母耳记下', 10, 5, 14, '以下这些就是他在耶路撒冷所生的孩子的名字：沙母亚、朔罢、拿单、所罗门、'),
('CNV', '撒母耳记下', 10, 5, 15, '益辖、以利书亚、尼斐、雅非亚、'),
('CNV', '撒母耳记下', 10, 5, 16, '以利沙玛、以利雅大、以利法列。'),
('CNV', '撒母耳记下', 10, 5, 17, '非利士人听见有人膏立了大卫作王统治以色列人，就全体上来搜寻大卫。大卫听见了，就下到保障去。'),
('CNV', '撒母耳记下', 10, 5, 18, '非利士人来到，散布在利乏音谷。'),
('CNV', '撒母耳记下', 10, 5, 19, '大卫求问耶和华说：“我可以上去攻打非利士人吗？你会把他们交在我手里吗？”耶和华对大卫说：“你可以上去，我必把非利士人交在你手里。”'),
('CNV', '撒母耳记下', 10, 5, 20, '于是大卫来到巴力‧毗拉心，在那里击败了非利士人，说：“耶和华在我面前冲破我的敌人，好像洪水冲破堤岸一般。”因此他给那地方起名叫巴力‧毗拉心。'),
('CNV', '撒母耳记下', 10, 5, 21, '非利士人把他们的神像遗弃在那里，大卫和跟随他的人就把它们拿走了。'),
('CNV', '撒母耳记下', 10, 5, 22, '非利士人又上来，散布在利乏音谷。'),
('CNV', '撒母耳记下', 10, 5, 23, '大卫又求问耶和华，耶和华说：“你不要直接上去，要绕到他们后面，从桑林对面攻打他们。'),
('CNV', '撒母耳记下', 10, 5, 24, '你一听到桑林树梢上有脚步的声音，就要赶快行动，因为那时耶和华已经在你前面出去击杀非利士人的军队了。”'),
('CNV', '撒母耳记下', 10, 5, 25, '于是大卫照着耶和华所吩咐他的去作，击杀非利士人，从迦巴直到基色。'),
('CNV', '撒母耳记下', 10, 6, 1, '大卫又聚集以色列中所有拣选出来的三万人。'),
('CNV', '撒母耳记下', 10, 6, 2, '大卫和与他在一起的众人起程前去，要从巴拉‧犹大把神的约柜运来，这约柜的名称是以坐在二基路伯之上万军之耶和华的名字而起的。'),
('CNV', '撒母耳记下', 10, 6, 3, '他们把神的约柜从山冈上亚比拿达的家里抬出来，安放在一辆新车上；亚比拿达的两个儿子，乌撒和亚希约赶着这辆新车，'),
('CNV', '撒母耳记下', 10, 6, 4, '车上有神的约柜。亚希约走在约柜的前面。'),
('CNV', '撒母耳记下', 10, 6, 5, '大卫和以色列全家在耶和华面前用各种松木制造的乐器，就是用琴、瑟、鼓、钹、锣，作乐跳舞。'),
('CNV', '撒母耳记下', 10, 6, 6, '他们到了拿艮的打禾场的时候，因为牛几乎绊倒，乌撒就伸手扶住神的约柜。'),
('CNV', '撒母耳记下', 10, 6, 7, '耶和华的怒气向乌撒发作；神因这错误的举动，就当场击杀他，他就死在神的约柜旁边。'),
('CNV', '撒母耳记下', 10, 6, 8, '大卫因为耶和华击杀了乌撒，就很生气，因此称那地方为毗列斯‧乌撒，直到今日。'),
('CNV', '撒母耳记下', 10, 6, 9, '那一天，大卫惧怕耶和华，说：“耶和华的约柜怎可以到我这里来呢？”'),
('CNV', '撒母耳记下', 10, 6, 10, '于是大卫不肯把耶和华的约柜运进大卫的城到他那里去，却转运到迦特人俄别‧以东的家里去。'),
('CNV', '撒母耳记下', 10, 6, 11, '耶和华的约柜在迦特人俄别‧以东的家停留了三个月，耶和华赐福给俄别‧以东和他的全家。'),
('CNV', '撒母耳记下', 10, 6, 12, '有人告诉大卫王：“耶和华因为神的约柜的缘故，赐福给俄别‧以东的家和一切属他的。”大卫就去，欢欢喜喜把神的约柜从俄别‧以东的家中抬上大卫的城里去。'),
('CNV', '撒母耳记下', 10, 6, 13, '那些抬耶和华的约柜的人走了六步，大卫就献一头公牛和一只肥畜为祭。'),
('CNV', '撒母耳记下', 10, 6, 14, '大卫束着细麻布的以弗得，在耶和华面前极力跳舞。'),
('CNV', '撒母耳记下', 10, 6, 15, '这样，大卫和以色列全家，以欢呼和角声，把耶和华的约柜抬了上来。'),
('CNV', '撒母耳记下', 10, 6, 16, '耶和华的约柜运进大卫城的时候，扫罗的女儿米甲从窗户往外观看，看见大卫王在耶和华面前跳跃舞蹈，心里就鄙视他。'),
('CNV', '撒母耳记下', 10, 6, 17, '他们把耶和华的约柜抬进去，安放在帐棚里它自己的地方，就是安放在大卫给它支搭的帐棚里，大卫就在耶和华面前献上燔祭和平安祭。'),
('CNV', '撒母耳记下', 10, 6, 18, '大卫献完了燔祭和平安祭，就奉万军之耶和华的名给人民祝福。'),
('CNV', '撒母耳记下', 10, 6, 19, '又分给众人，就是分给以色列全体群众，无论男女，每人一个饼、一个枣饼、一个葡萄干饼；然后众人就各归各家去了。'),
('CNV', '撒母耳记下', 10, 6, 20, '大卫回去要给自己的家人祝福。扫罗的女儿米甲出来迎见大卫，说：“以色列王今天多么荣耀啊！他今天竟在众臣仆的婢女眼前，赤身露体，就像一个卑贱的人无耻地露体一样。”'),
('CNV', '撒母耳记下', 10, 6, 21, '大卫对米甲说：“我是在耶和华面前跳舞；耶和华拣选了我，使我高过你父亲和他的全家，立我作耶和华的子民以色列的领袖，所以我要在耶和华面前跳舞作乐。'),
('CNV', '撒母耳记下', 10, 6, 22, '我还要比今天这样更卑贱，我要自视卑微。至于你所说的那些婢女，她们倒要尊重我。”'),
('CNV', '撒母耳记下', 10, 6, 23, '扫罗的女儿米甲，一直到她死的日子，都没有生育。'),
('CNV', '撒母耳记下', 10, 7, 1, '那时，王住在自己的宫中，耶和华使他安享太平，不受周围仇敌的侵扰。'),
('CNV', '撒母耳记下', 10, 7, 2, '王对拿单先知说：“你看！我自己住在香柏木的宫里，耶和华的约柜却停在帐幕内。”'),
('CNV', '撒母耳记下', 10, 7, 3, '拿单对王说：“你可以照着你心所想的一切去作，因为耶和华与你同在。”'),
('CNV', '撒母耳记下', 10, 7, 4, '那天晚上，耶和华的话临到拿单说：'),
('CNV', '撒母耳记下', 10, 7, 5, '“你去对我的仆人大卫说：耶和华这样说：‘你要建造一座殿宇给我居住吗？'),
('CNV', '撒母耳记下', 10, 7, 6, '因为自从我把以色列人从埃及带上来的那天起，直到今日，我都没有住过殿宇。我一直都住在帐棚和会幕里，到处漂泊。'),
('CNV', '撒母耳记下', 10, 7, 7, '我与以色列众人一起走过的地方，我可曾对以色列的一个支派的官长，就是我所吩咐要牧养我子民以色列的，说：你们为什么不给我建造一座香柏木的殿宇呢？’'),
('CNV', '撒母耳记下', 10, 7, 8, '现在你要对我的仆人大卫这样说：‘万军之耶和华这样说：我把你从牧场中、从照顾羊群的工作中拣选出来，使你作我子民以色列的领袖，'),
('CNV', '撒母耳记下', 10, 7, 9, '你无论到哪里去，我都与你同在；我必在你面前剪除你所有的仇敌。我要使你得享大名，像世上那些伟人的名一样。'),
('CNV', '撒母耳记下', 10, 7, 10, '我要为我的子民以色列选定一个地方，栽培他们，使他们住自己的地方，不再受骚扰；恶人也不能再像以前那样苦待他们，'),
('CNV', '撒母耳记下', 10, 7, 11, '像我立了士师治理我的子民以色列的那天以来那样。我要使你安享太平，不受你所有的仇敌侵扰。耶和华向你宣告，耶和华要亲自为你建立一个朝代。'),
('CNV', '撒母耳记下', 10, 7, 12, '到了你的寿数满足，你与你的列祖一起长眠的时候，我必兴起你亲生的后裔接替你，并且我要坚固他的国。'),
('CNV', '撒母耳记下', 10, 7, 13, '他必为我的名建造一座殿宇，我要永远坚固他的国位。'),
('CNV', '撒母耳记下', 10, 7, 14, '我要作他的父亲，他要作我的儿子，他若是犯了罪，我要用人的刑杖、用世人的鞭子纠正他。'),
('CNV', '撒母耳记下', 10, 7, 15, '但我的慈爱必不离开他，像离开在你面前的扫罗一样。'),
('CNV', '撒母耳记下', 10, 7, 16, '你的家和你的王国，也必在我的面前永远坚定，你的王位也必永远坚立。’”'),
('CNV', '撒母耳记下', 10, 7, 17, '拿单按着这一切话，又照着全部的默示，都对大卫说了。'),
('CNV', '撒母耳记下', 10, 7, 18, '于是，大卫王进去，坐在耶和华面前，说：“主耶和华啊！我是谁，我的家又算什么，你竟带领我到这地步？'),
('CNV', '撒母耳记下', 10, 7, 19, '主耶和华啊，这在你眼中还看为小事，你也说到你仆人的家未来的事。主耶和华啊，这岂是人常遇到的事吗？'),
('CNV', '撒母耳记下', 10, 7, 20, '主耶和华啊，你认识你的仆人，大卫还有什么话可以对你说呢？'),
('CNV', '撒母耳记下', 10, 7, 21, '你因自己应许的缘故，又按照自己的心意，行了这大事，为要使你仆人明白。'),
('CNV', '撒母耳记下', 10, 7, 22, '主耶和华啊，因此，你是伟大的！按照我们耳朵所听见的，没有像你的，除了你以外，再没有别的神。'),
('CNV', '撒母耳记下', 10, 7, 23, '世上有哪一个国家像你的子民以色列呢？神曾亲自救赎他们，使他们作自己的子民，又为他自己立名，为他们作了大事，为你的地作了可畏的事；在你的子民面前，就是你从埃及救赎出来归你自己的子民面前，赶出了列国的人和他们的神。'),
('CNV', '撒母耳记下', 10, 7, 24, '你为自己坚立了你的子民以色列，使他们永远作你的子民；耶和华啊，你也作了他们的神。'),
('CNV', '撒母耳记下', 10, 7, 25, '耶和华神啊！你所应许关于你仆人和他的家的话，现在求你永远坚守，并且照着你所说的去行吧；'),
('CNV', '撒母耳记下', 10, 7, 26, '这样，你的名必永远为大，以致人要说：‘万军之耶和华是以色列的神。’你仆人大卫的家也必在你面前得坚立。'),
('CNV', '撒母耳记下', 10, 7, 27, '万军之耶和华以色列的神啊！因为你曾启示你的仆人说：‘我要为你建立家室。’所以你的仆人才敢来向你作这样的祷告。'),
('CNV', '撒母耳记下', 10, 7, 28, '主耶和华啊！你是神；你的话是真实可信的。你向你仆人应许了这美好的福分。'),
('CNV', '撒母耳记下', 10, 7, 29, '现在求你乐意赐福给你仆人的家，使它在你面前可以永远存在。主耶和华啊！因为你曾经这样应许，愿你仆人的家因你的赐福永远蒙福。”'),
('CNV', '撒母耳记下', 10, 8, 1, '这事以后，大卫攻打非利士人，制伏了他们。大卫从非利士人手中取得了京城的控制权。'),
('CNV', '撒母耳记下', 10, 8, 2, '他又击败摩押人，使他们躺在地上，用绳子量他们，把量两绳的杀死，让量一绳的存活。这样，摩押人就臣服大卫，给他进贡。'),
('CNV', '撒母耳记下', 10, 8, 3, '琐巴王利合的儿子哈大底谢，往幼发拉底河去要夺回他统治这河的势力的时候，大卫就攻打他。'),
('CNV', '撒母耳记下', 10, 8, 4, '大卫从他那里掳获了战车一千辆，骑兵七千，步兵二万，大卫把所有战车的马的蹄筋都砍断。只留下一百辆战车的马。'),
('CNV', '撒母耳记下', 10, 8, 5, '大马士革的亚兰人来协助琐巴王哈大底谢，大卫就击杀了亚兰人二万二千。'),
('CNV', '撒母耳记下', 10, 8, 6, '于是大卫在大马士革的亚兰地驻军。这样亚兰人就臣服大卫，给他进贡。大卫无论到什么地方去，耶和华都使他得胜。'),
('CNV', '撒母耳记下', 10, 8, 7, '大卫夺取了哈大底谢臣仆所拿的金盾牌，带回耶路撒冷。'),
('CNV', '撒母耳记下', 10, 8, 8, '大卫王又从哈大底谢的两座城比他和比罗他夺取了大量的铜。'),
('CNV', '撒母耳记下', 10, 8, 9, '哈马王陀以听见大卫打败了哈大底谢的全军，'),
('CNV', '撒母耳记下', 10, 8, 10, '就差派他的儿子约兰去见大卫王，向他问安，祝贺他，因为大卫和哈大底谢争战，竟击败了他。原来陀以常常与哈大底谢争战。约兰手里还带着一些银器、金器和铜器。'),
('CNV', '撒母耳记下', 10, 8, 11, '大卫王也把这些器皿，连同他从他征服的各国得来的金银都一起分别为圣，献给耶和华。'),
('CNV', '撒母耳记下', 10, 8, 12, '就是从以东、摩押、亚扪人、非利士人、亚玛力人所得来的，以及从琐巴王利合的儿子哈大底谢获得的战利品。'),
('CNV', '撒母耳记下', 10, 8, 13, '大卫在盐谷击杀了一万八千以东人回来以后，就大有名声。'),
('CNV', '撒母耳记下', 10, 8, 14, '他又在以东设立防军；他在以东各地都设立防军，所有以东人就都臣服大卫。大卫无论到什么地方去，耶和华都使他得胜。'),
('CNV', '撒母耳记下', 10, 8, 15, '大卫作王统治全以色列，以公平和正义对待所有的人。'),
('CNV', '撒母耳记下', 10, 8, 16, '洗鲁雅的儿子约押作军队的统帅，亚希律的儿子约沙法作史官，'),
('CNV', '撒母耳记下', 10, 8, 17, '亚希突的儿子撒督和亚比亚他的儿子亚希米勒作祭司长，西莱雅作书记，'),
('CNV', '撒母耳记下', 10, 8, 18, '耶何耶大的儿子比拿雅统管基利提人和比利提人；大卫的众子都作领袖。'),
('CNV', '撒母耳记下', 10, 9, 1, '大卫问：“扫罗家还有剩下的人没有？我要因约拿单的缘故，以慈爱待他。”'),
('CNV', '撒母耳记下', 10, 9, 2, '扫罗家有一个仆人，名叫洗巴。有人叫他来见大卫；王问他：“你是洗巴吗？”他回答：“仆人正是。”'),
('CNV', '撒母耳记下', 10, 9, 3, '王又问：“扫罗家还有人没有？我要以神的慈爱待他。”洗巴回答王说：“还有约拿单的一个儿子，他双脚残废了。”'),
('CNV', '撒母耳记下', 10, 9, 4, '王又问他说：“他在哪里？”洗巴回答王说：“他在罗‧底巴亚米利的儿子玛吉家里。”'),
('CNV', '撒母耳记下', 10, 9, 5, '于是大卫王派人去把他从罗‧底巴亚米利的儿子玛吉家里接来。'),
('CNV', '撒母耳记下', 10, 9, 6, '扫罗的孙子，约拿单的儿子米非波设来到大卫面前，俯伏叩拜。大卫说：“米非波设！”他回答：“仆人在这里。”'),
('CNV', '撒母耳记下', 10, 9, 7, '大卫对他说：“你不要怕，我必因你父亲约拿单的缘故，以慈爱待你，把你祖父扫罗所有的田地都归还给你；你也可以常常与我同席吃饭。”'),
('CNV', '撒母耳记下', 10, 9, 8, '米非波设再叩拜说：“仆人算什么？你竟然眷顾我这个像条死狗的人！”'),
('CNV', '撒母耳记下', 10, 9, 9, '王把扫罗的仆人洗巴召来，对他说：“我已经把属于扫罗，以及他全家所有的一切，给了你主人的孙子。'),
('CNV', '撒母耳记下', 10, 9, 10, '你和你的儿子，以及你的仆人，都要替他耕种田地；你要把所收获的拿来，供他食用。你主人的孙子米非波设要常常与我同席吃饭。”洗巴有十五个儿子，二十个仆人。'),
('CNV', '撒母耳记下', 10, 9, 11, '洗巴对王说：“我主我王吩咐仆人的一切，仆人都必遵行。”于是米非波设与大卫同桌吃饭，象是王的一个儿子一样。'),
('CNV', '撒母耳记下', 10, 9, 12, '米非波设有一个小儿子，名叫米迦。住在洗巴家里的人，都作了米非波设的仆人。'),
('CNV', '撒母耳记下', 10, 9, 13, '这样，米非波设住在耶路撒冷，常常与王同席吃饭。可是他的双腿都是瘸的。'),
('CNV', '撒母耳记下', 10, 10, 1, '后来，亚扪人的王死了，他的儿子哈嫩继承他作王。'),
('CNV', '撒母耳记下', 10, 10, 2, '大卫说：“我要恩待拿辖的儿子哈嫩，像他父亲恩待我一样。”于是大卫差派自己的臣仆，为他丧父的事安慰他。大卫的臣仆到了亚扪人境内时，'),
('CNV', '撒母耳记下', 10, 10, 3, '亚扪人的众领袖对他们的主哈嫩说：“大卫差派这些慰问的人到你这里来，你以为他是尊敬你父亲吗？他派遣臣仆到你这里来，不是为了要窥探这城，侦察清楚，然后把城倾覆吗？”'),
('CNV', '撒母耳记下', 10, 10, 4, '于是哈嫩拿住大卫的臣仆，把他们的胡须剃去一半，又把他们的外袍割去半截，露出臀部，然后才放他们走。'),
('CNV', '撒母耳记下', 10, 10, 5, '有人告诉大卫，他就派人去迎接他们，因为他们非常羞耻。王就说：“你们可以住在耶利哥，等到你们的胡须长长了才回来。”'),
('CNV', '撒母耳记下', 10, 10, 6, '亚扪人知道大卫憎恶他们，就派人去招募伯‧利合的亚兰人和琐巴的亚兰人，步兵二万，玛迦王的人一千，陀伯人一万二千。'),
('CNV', '撒母耳记下', 10, 10, 7, '大卫听见了，就差派约押和全体勇士出去。'),
('CNV', '撒母耳记下', 10, 10, 8, '亚扪人出来，在城门前摆阵，琐巴和利合的亚兰人，陀伯人和玛迦人，也分别在郊野摆阵。'),
('CNV', '撒母耳记下', 10, 10, 9, '约押看见自己前后受敌，就从以色列所有的精兵中，挑选一部分出来，使他们摆阵去迎战亚兰人，'),
('CNV', '撒母耳记下', 10, 10, 10, '他把其余的人交在他兄弟亚比筛手下，使他们摆阵去迎战亚扪人。'),
('CNV', '撒母耳记下', 10, 10, 11, '约押对亚比筛说：“如果亚兰人比我强，你就来帮助我。如果亚扪人比你强，我就去帮助你。'),
('CNV', '撒母耳记下', 10, 10, 12, '你要刚强；为了我们的人民和我们神的众城镇，我们要刚强！愿耶和华成全他看为美的事。”'),
('CNV', '撒母耳记下', 10, 10, 13, '于是约押和与他在一起的人前进，攻击亚兰人；亚兰人在约押面前逃跑。'),
('CNV', '撒母耳记下', 10, 10, 14, '亚扪人看见亚兰人逃跑，他们也在亚比筛面前逃跑，逃进城里去了。约押就从亚扪人那里回来，回到耶路撒冷去了。'),
('CNV', '撒母耳记下', 10, 10, 15, '亚兰人见自己被以色列人击败，就再聚集起来。'),
('CNV', '撒母耳记下', 10, 10, 16, '哈大底谢差遣人把幼发拉底河那边的亚兰人调来。他们来到了希兰，由哈大底谢的将军朔法率领他们。'),
('CNV', '撒母耳记下', 10, 10, 17, '有人告诉了大卫，他就聚集所有的以色列人，渡过约旦河，来到了希兰。亚兰人摆好了阵迎击大卫，与他交战。'),
('CNV', '撒母耳记下', 10, 10, 18, '亚兰人却在以色列人面前逃跑。大卫杀了亚兰七百名驾驶战车的军兵，四万骑兵。又击杀了亚兰军队的将军朔法，他就死在那里。'),
('CNV', '撒母耳记下', 10, 10, 19, '所有臣服于哈大底谢的王看见自己被以色列人打败，就与以色列人议和，臣服于他们。于是亚兰人害怕，不敢再帮助亚扪人了。'),
('CNV', '撒母耳记下', 10, 11, 1, '过了年，在列王出征的时候，大卫派遣约押和自己的臣仆，以及以色列众军一同出征。他们歼灭了亚扪人，并且包围了拉巴。大卫却留在耶路撒冷。'),
('CNV', '撒母耳记下', 10, 11, 2, '有一天近黄昏的时候，大卫从床上起来，在王宫的平顶上散步。他从平顶上看见一个妇人在洗澡；这妇人容貌非常美丽。'),
('CNV', '撒母耳记下', 10, 11, 3, '大卫派人去查问那妇人是谁。有人说：“这不是以连的女儿、赫人乌利亚的妻子拔示巴吗？”'),
('CNV', '撒母耳记下', 10, 11, 4, '于是大卫差派使者去把她接来。她来到大卫那里，大卫就与她同房。那时她的月经刚得洁净。事后，她就回家去了。'),
('CNV', '撒母耳记下', 10, 11, 5, '后来那妇人怀了孕，就打发人去告诉大卫，说：“我怀孕了！”'),
('CNV', '撒母耳记下', 10, 11, 6, '大卫派人到约押那里，说：“你打发赫人乌利亚到我这里来。”约押就打发乌利亚去见大卫。'),
('CNV', '撒母耳记下', 10, 11, 7, '乌利亚来到大卫那里，大卫就问约押和士兵可好，又问战场上的情形怎样。'),
('CNV', '撒母耳记下', 10, 11, 8, '大卫对乌利亚说：“你回家去，洗洗脚吧！”乌利亚就离开了王宫。随后王的一份礼物也跟着送去。'),
('CNV', '撒母耳记下', 10, 11, 9, '乌利亚却和他主人的臣仆一同睡在王宫门外，没有回到自己家里去。'),
('CNV', '撒母耳记下', 10, 11, 10, '有人告诉大卫说：“乌利亚没有下到自己家里去。”大卫就问乌利亚：“你不是从远路回来吗？为什么不下到自己家里去呢？”'),
('CNV', '撒母耳记下', 10, 11, 11, '乌利亚回答大卫说：“约柜、以色列人和犹大人都住在棚里，我主人约押和我主人的臣仆都在野地安营，我怎能回家吃喝，与妻子同睡呢？我指着王和王的生命发誓：我绝不敢作这样的事。”'),
('CNV', '撒母耳记下', 10, 11, 12, '大卫对乌利亚说：“你今天还留在这里，明天我才打发你去。”那一天，乌利亚就留在耶路撒冷。'),
('CNV', '撒母耳记下', 10, 11, 13, '次日，大卫召了乌利亚来，叫乌利亚与他一起吃喝，使他喝醉。到了晚上，乌利亚出去，与他主人的臣仆一同睡在自己的床铺上，还是没有下到自己家里去。'),
('CNV', '撒母耳记下', 10, 11, 14, '到了早晨，大卫写了一封给约押的信，交乌利亚亲手带去。'),
('CNV', '撒母耳记下', 10, 11, 15, '他在信里写着说：“要把乌利亚派到战斗最猛烈的前线去，然后你们就退到他后边，让他被击杀。”'),
('CNV', '撒母耳记下', 10, 11, 16, '那时，约押正在围城，他知道哪里有强悍的守军，就派乌利亚到那里去。'),
('CNV', '撒母耳记下', 10, 11, 17, '城里的人出来，与约押交战。大卫的仆人中有一些倒毙了，赫人乌利亚也死了。'),
('CNV', '撒母耳记下', 10, 11, 18, '于是，约押派人去把战事的一切情形都报告大卫。'),
('CNV', '撒母耳记下', 10, 11, 19, '他又吩咐那使者说：“你把战事的一切情形对王说完了以后，'),
('CNV', '撒母耳记下', 10, 11, 20, '王若是大怒，责问你：‘你们为什么那样靠近那城争战呢？你们不知道敌人会从城墙上射箭下来吗？'),
('CNV', '撒母耳记下', 10, 11, 21, '从前击杀了耶路‧比设的儿子亚比米勒的是谁呢？不是一个妇人从城墙上把一块磨石丢在他身上，他就死在提备斯吗？你们为什么靠近城墙呢？’你就回答：‘王的仆人赫人乌利亚也死了。’”'),
('CNV', '撒母耳记下', 10, 11, 22, '于是那使者去了；他一来到，就把约押差遣他所要说的一切都报告了大卫。'),
('CNV', '撒母耳记下', 10, 11, 23, '那使者又对大卫说：“那些人比我们强，他们出到旷野攻打我们，我们把他们赶回城门口。'),
('CNV', '撒母耳记下', 10, 11, 24, '那时射手从城墙上射王的仆人；王的仆人中有些阵亡了，你的仆人赫人乌利亚也死了。”'),
('CNV', '撒母耳记下', 10, 11, 25, '大卫对那使者说：“你要对约押这样说：‘不要为这件事难过，因为刀剑有时吞灭这人，有时吞灭那人。你只要加紧攻打这城，把城毁灭。’你要这样鼓励他。”'),
('CNV', '撒母耳记下', 10, 11, 26, '乌利亚的妻子听到丈夫乌利亚死了，就为他哀哭。'),
('CNV', '撒母耳记下', 10, 11, 27, '守丧期一过，大卫就派人去把拔示巴接到宫里，她就作了大卫的妻子，给大卫生了一个儿子。大卫所作的这事，耶和华看为恶。'),
('CNV', '撒母耳记下', 10, 12, 1, '耶和华差派拿单去见大卫。于是拿单来到大卫那里，对他说：“在一座城里有两个人，一个富有，一个贫穷。'),
('CNV', '撒母耳记下', 10, 12, 2, '那富有的有极多牛羊，'),
('CNV', '撒母耳记下', 10, 12, 3, '那贫穷的除了买来养的一只母羊羔以外，什么也没有。那小羊在他家里和他的儿女一同长大，小羊吃他的食物，喝他杯中的饮料，睡在他的怀里，就像他的女儿一样。'),
('CNV', '撒母耳记下', 10, 12, 4, '有一个旅客来到富翁那里，他舍不得从自己的牛群羊群中取一头出来，款待到他那里来的旅客，却取了那穷人的母羊羔，款待到他那里来的客人。”'),
('CNV', '撒母耳记下', 10, 12, 5, '大卫就非常恼怒那人，对拿单说：“我指着永活的耶和华起誓，作这事的人该死。'),
('CNV', '撒母耳记下', 10, 12, 6, '他必须四倍赔偿这羊羔，因为他作了这事，又因他没有怜悯的心。”'),
('CNV', '撒母耳记下', 10, 12, 7, '拿单对大卫说：“你就是那人！耶和华以色列的神这样说：‘我膏立了你作以色列的王，把你从扫罗的手里救了出来，'),
('CNV', '撒母耳记下', 10, 12, 8, '把你主人的家赐给你，把你主人的妻妾交在你怀里，又把以色列和犹大家赐给你。如果太少了，我还可以多多加给你。'),
('CNV', '撒母耳记下', 10, 12, 9, '你为什么藐视耶和华的话，行他看为恶的事呢？你用刀击杀了赫人乌利亚，娶了他的妻子作你的妻子，你藉着亚扪人的刀杀了乌利亚。'),
('CNV', '撒母耳记下', 10, 12, 10, '所以，从今以后，刀剑必不离开你的家，因为你藐视了我，娶了赫人乌利亚的妻子作你的妻子。’'),
('CNV', '撒母耳记下', 10, 12, 11, '耶和华这样说：‘看哪！我必从你家中兴起祸患攻击你；我要在你的眼前把你的妃嫔拿去赐给你的同伴。他要在光天化日之下与她们同床。'),
('CNV', '撒母耳记下', 10, 12, 12, '你在暗中行了这事，我却要在所有以色列人面前，在光天化日之下行这事报应你。’”'),
('CNV', '撒母耳记下', 10, 12, 13, '大卫对拿单说：“我得罪了耶和华了。”拿单对大卫说：“耶和华已经除去了你的罪，你必不至于死。'),
('CNV', '撒母耳记下', 10, 12, 14, '只是因为你作了这事，使耶和华的仇敌大得亵渎的机会，所以你所生的儿子必定死。”'),
('CNV', '撒母耳记下', 10, 12, 15, '于是拿单回自己的家去了。耶和华击打乌利亚的妻子给大卫所生的孩子，他就害了重病。'),
('CNV', '撒母耳记下', 10, 12, 16, '大卫为那孩子恳求神，并且禁食。他进房里去，终夜躺在地上。'),
('CNV', '撒母耳记下', 10, 12, 17, '他家中的老侍从站在他旁边，要把他从地上扶起来，他却不肯，也不与他们一起吃饭。'),
('CNV', '撒母耳记下', 10, 12, 18, '到了第七天，孩子死了。大卫的臣仆不敢告诉他孩子死了，因为他们说：“看哪，孩子还活着的时候，我们劝他，他尚且不听我们的话。现在我们怎么能告诉他孩子已经死了呢？他会伤心欲绝的。”'),
('CNV', '撒母耳记下', 10, 12, 19, '大卫看见他的臣仆彼此低声耳语，就知道孩子已经死了。他问臣仆说：“孩子死了吗？”他们回答：“死了！”'),
('CNV', '撒母耳记下', 10, 12, 20, '于是大卫从地上起来，洗澡，抹膏，更换衣服，进耶和华的殿去敬拜，然后回到自己的宫里去，吩咐人给他摆上饭，他就吃了。'),
('CNV', '撒母耳记下', 10, 12, 21, '臣仆问他：“你为什么这样作呢？孩子还活着的时候，你为他禁食哭泣；孩子死了，你倒起来吃饭！”'),
('CNV', '撒母耳记下', 10, 12, 22, '他回答：“孩子还活着的时候，我禁食哭泣，因为我想：‘谁知道呢？也许耶和华怜悯我，让孩子可以活着。’'),
('CNV', '撒母耳记下', 10, 12, 23, '现在他死了，我为什么还要禁食呢？我还能使他回来吗？我要到他那里去，他却不能回到我这里来。”'),
('CNV', '撒母耳记下', 10, 12, 24, '大卫安慰他的妻子拔示巴，进到她那里去，与她同睡。她生了一个儿子，大卫给他起名叫所罗门；耶和华也喜爱他，'),
('CNV', '撒母耳记下', 10, 12, 25, '就差派拿单先知去，照着耶和华的吩咐，给他起名叫耶底底亚。'),
('CNV', '撒母耳记下', 10, 12, 26, '那时，约押正在攻打亚扪人的拉巴，攻取了王城。'),
('CNV', '撒母耳记下', 10, 12, 27, '约押派遣使者去见大卫，说：“我攻打拉巴，已经攻取了水城。'),
('CNV', '撒母耳记下', 10, 12, 28, '现在，请你聚集其余的人民，安营攻打这城，把城攻取；免得我攻取了这城，人就以我的名字来叫这城。”'),
('CNV', '撒母耳记下', 10, 12, 29, '于是大卫聚集所有的人民，向拉巴进军；攻打那城，把它攻取了。'),
('CNV', '撒母耳记下', 10, 12, 30, '大卫从他们的王的头上夺取了王冠。王冠的金子重三十五公斤，上面嵌有宝石，人把这冠冕戴在大卫的头上。大卫又从这城里带走了许多战利品，'),
('CNV', '撒母耳记下', 10, 12, 31, '又把那城里的人民带出去，使他们用锯子、铁耙、铁斧作工，或使他们在砖窑服役。大卫对待亚扪各城的居民都是这样。后来，大卫和众人都回耶路撒冷去了。'),
('CNV', '撒母耳记下', 10, 13, 1, '大卫的儿子押沙龙有一个美丽的妹妹，名叫他玛；大卫的儿子暗嫩爱上了她。'),
('CNV', '撒母耳记下', 10, 13, 2, '暗嫩为了他妹妹他玛的缘故，因爱成病。因为他玛还是处女，所以暗嫩看来很难对她采取什么行动。'),
('CNV', '撒母耳记下', 10, 13, 3, '暗嫩有一个朋友，名叫约拿达，是大卫的哥哥示米亚的儿子。约拿达是一个非常狡猾的人。'),
('CNV', '撒母耳记下', 10, 13, 4, '他问暗嫩说：“王子啊！你为什么一天比一天瘦弱呢？你可以告诉我吗？”暗嫩说：“我爱上了我兄弟押沙龙的妹妹他玛。”'),
('CNV', '撒母耳记下', 10, 13, 5, '约拿达对他说：“你可以躺在床上装病。你父亲来看你的时候，你就对他说：‘求你叫我的妹妹他玛来，把食物递给我吃；叫她在我眼前预备食物，好使我可以看见，也可以从她的手中取食。’”'),
('CNV', '撒母耳记下', 10, 13, 6, '于是暗嫩躺着装病。王来看他，暗嫩对王说：“求你叫我的妹妹他玛来，叫她在我眼前给我做两个饼，我可以从她的手里拿过来吃。”'),
('CNV', '撒母耳记下', 10, 13, 7, '大卫就派人到宫里去对他玛说：“你到你哥哥暗嫩的屋里去，为他预备食物。”'),
('CNV', '撒母耳记下', 10, 13, 8, '他玛就到她哥哥暗嫩的屋里去；暗嫩正躺着。他玛取了点面，把面和好，就在暗嫩面前做饼，并且把饼烤熟了。'),
('CNV', '撒母耳记下', 10, 13, 9, '她拿过锅来，在他面前把饼倒出来，暗嫩却不肯吃，他说：“叫众人离开我出去！”众人就都离开他出去了。'),
('CNV', '撒母耳记下', 10, 13, 10, '暗嫩对他玛说：“把食物带到卧房来，我好从你的手里拿过来吃。”他玛拿着她做好的饼，进了卧房，到她哥哥暗嫩那里去。'),
('CNV', '撒母耳记下', 10, 13, 11, '他玛上到他面前，给他吃的时候，暗嫩却拉住她，对她说：“妹妹，来与我同寝吧！”'),
('CNV', '撒母耳记下', 10, 13, 12, '他玛对他说：“不要！哥哥！不要污辱我！在以色列中不可作这样的事。你不要作这丑事。'),
('CNV', '撒母耳记下', 10, 13, 13, '至于我，我到哪里除去我的耻辱呢？至于你，你在以色列中也会成了一个愚妄的人。现在请你去对王说，他必不会禁止我归你的。”'),
('CNV', '撒母耳记下', 10, 13, 14, '但暗嫩不肯听她的话，他又比他玛有力，就污辱了她，与她同寝。'),
('CNV', '撒母耳记下', 10, 13, 15, '事后，暗嫩非常恨她；他对他玛的恨比以前对她的爱更大，所以暗嫩对她说：“你起来！走吧！”'),
('CNV', '撒母耳记下', 10, 13, 16, '他玛却对他说：“我的哥哥啊，不！你赶我出去的这罪比你刚才与我所行的罪更大了。”但是暗嫩不肯听她的话，'),
('CNV', '撒母耳记下', 10, 13, 17, '就叫了侍候他的仆人来，说：“把这女人从我面前赶到外面去，然后把门锁上。”'),
('CNV', '撒母耳记下', 10, 13, 18, '那时他玛身上穿着长袖彩衣，因为未嫁的公主都是这样穿的。那侍候暗嫩的仆人把她赶到外面去，随后把门锁上。'),
('CNV', '撒母耳记下', 10, 13, 19, '他玛把尘土撒在自己的头上，撕裂身上的长袖彩衣，又把一只手放在头上，一边行走一边哭叫。'),
('CNV', '撒母耳记下', 10, 13, 20, '她哥哥押沙龙问她：“是不是你哥哥暗嫩与你亲近了？我妹妹啊，你现在不要作声，他是你的哥哥，你不要把这事放在心上。”于是他玛孤单凄凉地住在她哥哥押沙龙的家里。'),
('CNV', '撒母耳记下', 10, 13, 21, '大卫王听见了这一切事，就非常生气。'),
('CNV', '撒母耳记下', 10, 13, 22, '押沙龙什么话都没有对暗嫩说。押沙龙恨暗嫩，因为暗嫩污辱了他的妹妹他玛。'),
('CNV', '撒母耳记下', 10, 13, 23, '两年以后，在以法莲边界的巴力‧夏琐，押沙龙雇了人为他剪羊毛，押沙龙邀请王所有的儿子到那里去。'),
('CNV', '撒母耳记下', 10, 13, 24, '押沙龙去见王说：“看哪！现在你的仆人雇了人剪羊毛；请王和王的臣仆与我一同去。”'),
('CNV', '撒母耳记下', 10, 13, 25, '王对押沙龙说：“不！我儿，我们不必都去，免得我们成为你的重担。”押沙龙再三勉强王去，王还是不肯去，只是为他祝福。'),
('CNV', '撒母耳记下', 10, 13, 26, '押沙龙说：“王若是不去，求王让我的哥哥暗嫩与我一同去。”王问他：“为什么要他与你一同去呢？”'),
('CNV', '撒母耳记下', 10, 13, 27, '押沙龙再三求王，王就派暗嫩和王所有的儿子与他一同去。'),
('CNV', '撒母耳记下', 10, 13, 28, '押沙龙吩咐他的仆人说：“你们注意！暗嫩酒酣耳热的时候，我对你们说：‘击杀暗嫩！’你们就把他杀死。不要惧怕，这不是我吩咐你们的吗？你们要坚强，作勇敢的人。”'),
('CNV', '撒母耳记下', 10, 13, 29, '押沙龙的仆人就照押沙龙所吩咐的，向暗嫩行了。王所有的儿子就起来，各人骑上自己的骡子逃跑了。'),
('CNV', '撒母耳记下', 10, 13, 30, '他们还在路上的时候，有消息传到大卫那里，说：“押沙龙杀了王所有的儿子，没有剩下一个。”'),
('CNV', '撒母耳记下', 10, 13, 31, '王就起来，撕裂衣服，躺在地上。侍立在他身旁的所有臣仆，也都撕裂衣服。'),
('CNV', '撒母耳记下', 10, 13, 32, '大卫的哥哥示米亚的儿子约拿达说：“我主不要以为所有的年轻人、王的儿子都被杀死了。其实死的只有暗嫩一人；自从暗嫩污辱了押沙龙的妹妹他玛那一天起，押沙龙就定意要杀死他了。'),
('CNV', '撒母耳记下', 10, 13, 33, '现在我主我王不要把这事放在心上，以为王所有的儿子都死了。其实死的只有暗嫩一人。”'),
('CNV', '撒母耳记下', 10, 13, 34, '押沙龙逃走了。守望的年轻人举目观看，看见许多人从后面山坡旁边的路而来。'),
('CNV', '撒母耳记下', 10, 13, 35, '约拿达对王说：“看哪！王的儿子都回来了。正如你仆人所说的，事情果然是这样。”'),
('CNV', '撒母耳记下', 10, 13, 36, '他刚说完了，王的众子就都来到了，他们都放声大哭；王和他所有的臣仆也都号咷痛哭。'),
('CNV', '撒母耳记下', 10, 13, 37, '押沙龙逃亡，走到基述王亚米忽的儿子达买那里去了。大卫天天为他的儿子哀伤。'),
('CNV', '撒母耳记下', 10, 13, 38, '押沙龙逃亡，逃到基述那里去，在那里住了三年。'),
('CNV', '撒母耳记下', 10, 13, 39, '大卫的心不再怀恨押沙龙，对暗嫩的死也不再那么难过了。'),
('CNV', '撒母耳记下', 10, 14, 1, '洗鲁雅的儿子约押知道王的心想念押沙龙，'),
('CNV', '撒母耳记下', 10, 14, 2, '就派人到提哥亚去，从那里带了一位聪明的妇人来，对她说：“你要假装居丧的，穿上丧服，不要用油膏抹身体。要装成一个为死者居丧很久的妇人。'),
('CNV', '撒母耳记下', 10, 14, 3, '然后进去见王，对他这样这样说。”于是约押把要说的话教了她。'),
('CNV', '撒母耳记下', 10, 14, 4, '提哥亚妇人进去见王，俯伏在地，叩拜他，说：“王啊！求你帮助我。”'),
('CNV', '撒母耳记下', 10, 14, 5, '王问她：“你有什么事呢？”她回答：“我实在是个寡妇，我的丈夫死了。'),
('CNV', '撒母耳记下', 10, 14, 6, '婢女有两个儿子；有一天，他们两人在田里打架，当时没有人劝开他们，这个就击打那个，竟把他打死了。'),
('CNV', '撒母耳记下', 10, 14, 7, '看哪！现在全家族的人都起来攻击婢女，说：‘你要把那击杀他兄弟的凶手交出来，好让我们把他处死，以偿他兄弟的命，也可以灭绝那继承产业的。’这样他们要使我所剩下的炭火也都熄灭了，不让我丈夫在这世上留下名字，或留下后代。”'),
('CNV', '撒母耳记下', 10, 14, 8, '王对那妇人说：“你回家去吧！我必为你下令办这件事。”'),
('CNV', '撒母耳记下', 10, 14, 9, '提哥亚妇人又对王说：“我主我王，愿这罪归于我和我父的家；愿王和王的王位与这罪无关。”'),
('CNV', '撒母耳记下', 10, 14, 10, '王说：“对你说这事的，你就把他带到我这里来，他必不会再打扰你了。”'),
('CNV', '撒母耳记下', 10, 14, 11, '妇人说：“愿王记念耶和华你的神，不许报血仇的人多行杀戮，免得他们灭绝我的儿子。”王说：“我指着永活的耶和华起誓，你的儿子连一根头发也不会落在地上。”'),
('CNV', '撒母耳记下', 10, 14, 12, '那妇人又说：“请允许婢女对我主我王再说一句话。”王说：“你说吧。”'),
('CNV', '撒母耳记下', 10, 14, 13, '妇人说：“你为什么想出这样的事来陷害神的子民呢？王说了这话，如果不让自己逃亡的人回来，就是个有罪的人了。'),
('CNV', '撒母耳记下', 10, 14, 14, '我们都是必死的，像水泼在地上不能收回来一样；但神并不取去人的命，反而设法使逃亡的人不致永远离开他逃亡。'),
('CNV', '撒母耳记下', 10, 14, 15, '现在我来对我主我王说这话，是因为众民使我害怕，所以婢女想：‘现在我要对王说，也许王会成全婢女所求的。’'),
('CNV', '撒母耳记下', 10, 14, 16, '人要把我和我的儿子从神的产业上一同消灭，也许王会垂听，会把婢女从那人的手下救出来。'),
('CNV', '撒母耳记下', 10, 14, 17, '婢女又想：‘我主我王的话必能使我得安慰，因为我主我王像神的使者一样，能分辨是非。愿耶和华你的神与你同在。’”'),
('CNV', '撒母耳记下', 10, 14, 18, '王对那妇人说：“我要问你一句话，请你不要瞒我。”妇人回答：“我主我王，请说！”'),
('CNV', '撒母耳记下', 10, 14, 19, '王问：“这一切都是约押一手安排的吗？”妇人回答：“我指着我主我王起誓，王所说的丝毫不差。这正是王的仆人约押吩咐我的，这一切话也都是他教婢女说的。'),
('CNV', '撒母耳记下', 10, 14, 20, '王的仆人约押这样作，为要挽回这件事。我主有智慧，像神使者的智慧一样，能知道世上的一切事。”'),
('CNV', '撒母耳记下', 10, 14, 21, '王对约押说：“看哪！这事我已经同意了。你去把那年轻人押沙龙带回来吧！”'),
('CNV', '撒母耳记下', 10, 14, 22, '约押就面伏于地，叩拜王，为王祝福；又说：“今天你仆人知道在我主我王眼前蒙了恩宠，因为王成全了你仆人所求的。”'),
('CNV', '撒母耳记下', 10, 14, 23, '于是约押起来，往基述去，把押沙龙带回耶路撒冷。'),
('CNV', '撒母耳记下', 10, 14, 24, '王说：“让他回自己的家里去，不要见王的面。”押沙龙就转回自己的家里去，没有见王的面。'),
('CNV', '撒母耳记下', 10, 14, 25, '在全以色列中，没有一个人像押沙龙那样英俊，得人称赞，从脚底到头顶，都没有一点缺陷。'),
('CNV', '撒母耳记下', 10, 14, 26, '他每年年底剪发一次，因为他头上的头发太厚，所以把它剪下来；他把头发剪下来以后，总是把头发称一称；按照王的法码重约两公斤。'),
('CNV', '撒母耳记下', 10, 14, 27, '押沙龙生了三个儿子，一个女儿。女儿名叫他玛，是个容貌美丽的女子。'),
('CNV', '撒母耳记下', 10, 14, 28, '押沙龙在耶路撒冷住了两年，都没有见王的面。'),
('CNV', '撒母耳记下', 10, 14, 29, '押沙龙派人去叫约押来，要托他去见王，约押却不肯来见他。他第二次再派人去叫他，他还是不肯来。'),
('CNV', '撒母耳记下', 10, 14, 30, '于是押沙龙对仆人说：“你们看，约押的一块田和我相邻，田里有大麦。你们去放火烧田！”押沙龙的仆人就放火把那块田烧了。'),
('CNV', '撒母耳记下', 10, 14, 31, '于是约押起来，到了押沙龙的家，问他：“你的仆人为什么放火烧了我那块田呢？”'),
('CNV', '撒母耳记下', 10, 14, 32, '押沙龙回答约押：“看哪，我派人去见你，说：‘请你到这里来，我要托你去见王，替我说：“我为什么从基述回来呢？我若是还留在那边，会觉得更好。”’现在，我要见王的面，如果我有罪，任由他把我杀死好了。”'),
('CNV', '撒母耳记下', 10, 14, 33, '于是约押进去见王，把这事告诉了他，王就召见押沙龙。押沙龙进去见王，在王面前脸伏在地拜他，王就与押沙龙亲吻。'),
('CNV', '撒母耳记下', 10, 15, 1, '这事以后，押沙龙为自己预备了一辆战车和一些马匹，又预备了五十人在他前面奔走开路。'),
('CNV', '撒母耳记下', 10, 15, 2, '押沙龙常常清早起来，站在通往城门口的路旁。有争讼的案件要进去请王判决的人，押沙龙就把他叫到跟前来，问他：“你是从哪一座城来的？”他回答：“仆人是从以色列某一支派来的。”'),
('CNV', '撒母耳记下', 10, 15, 3, '押沙龙就对他说：“你看！你的案件有情有理，但是王并没有委人听你的案子。”'),
('CNV', '撒母耳记下', 10, 15, 4, '押沙龙又说：“但愿有人立我作这地的审判官，这样，有案件或诉讼的人，都可以到我这里来，我就给他公平的审判。”'),
('CNV', '撒母耳记下', 10, 15, 5, '如果有人走近押沙龙要拜他，他就伸手拉住他，并且与他亲吻。'),
('CNV', '撒母耳记下', 10, 15, 6, '所有来到王面前请求审决的以色列人，押沙龙都是这样对待他们。因此，押沙龙暗中迷惑了以色列人的心。'),
('CNV', '撒母耳记下', 10, 15, 7, '过了四年，押沙龙对王说：“求你准我到希伯仑去，好向耶和华还我所许的愿。'),
('CNV', '撒母耳记下', 10, 15, 8, '因为仆人住在亚兰的基述的时候，曾经许了一个愿说：‘如果耶和华使我再回到耶路撒冷来，我就要在希伯仑事奉他。’”'),
('CNV', '撒母耳记下', 10, 15, 9, '王对他说：“你平平安安地去吧！”于是他动身，往希伯仑去了。'),
('CNV', '撒母耳记下', 10, 15, 10, '押沙龙派遣探子到以色列的各支派中，说：“你们一听见号角的声音，就说：‘押沙龙在希伯仑作王了！’”'),
('CNV', '撒母耳记下', 10, 15, 11, '有二百人从耶路撒冷应邀与押沙龙同去。他们都是诚诚实实地去，对内情一点也不知道。'),
('CNV', '撒母耳记下', 10, 15, 12, '押沙龙献祭的时候，差派人去把大卫的参谋基罗人亚希多弗从他的本城基罗请来。于是叛乱的势力越来越大，跟随押沙龙的人民也越来越多。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '撒母耳记下', 10, 15, 13, '有一个报信的人来见大卫说：“以色列人的心都归向押沙龙了。”'),
('CNV', '撒母耳记下', 10, 15, 14, '大卫就对所有在耶路撒冷与他在一起的臣仆说：“我们要起来逃走，不然我们就不能逃避押沙龙的面了，要赶快离开，恐怕他迅速赶上我们，使灾难临到我们身上，用刀击杀全城的人。”'),
('CNV', '撒母耳记下', 10, 15, 15, '王的臣仆对王说：“我主我王决定的一切，仆人都必遵行。”'),
('CNV', '撒母耳记下', 10, 15, 16, '于是王出走了，他的全家都跟在他的后头，却留下十个妃嫔看守王宫。'),
('CNV', '撒母耳记下', 10, 15, 17, '王出发了，众人都跟在他的脚后；他们在伯‧墨哈停下来。'),
('CNV', '撒母耳记下', 10, 15, 18, '王所有的臣仆都从王的身边走过去，所有的基利提人、比利提人和迦特人，就是从迦特来跟从王的六百人，都从王面前走过去。'),
('CNV', '撒母耳记下', 10, 15, 19, '王对迦特人以太说：“你为什么也与我们一同走呢？回去留在新王那里吧！因为你是个外族人，是个远离自己家乡逃到这里来的人。'),
('CNV', '撒母耳记下', 10, 15, 20, '你昨天才来，我怎可以今天就让你与我们一同流浪呢？现在我还不知道我要到哪里去。你回去吧！带着你的兄弟一同回去吧！愿耶和华的慈爱和信实与你同在。”'),
('CNV', '撒母耳记下', 10, 15, 21, '以太回答王说：“我指着永活的耶和华，在我主我王面前起誓，无论我主我王在什么地方，或生或死，你仆人也必在那里。”'),
('CNV', '撒母耳记下', 10, 15, 22, '大卫对以太说：“你可以去，向前走吧！”迦特人以太就带着所有属他的人，和与他在一起的妇人孩子都向前走。'),
('CNV', '撒母耳记下', 10, 15, 23, '众人向前走的时候，遍地的人都放声大哭；王过了汲沦溪，众人就都走上通往旷野去的路。'),
('CNV', '撒母耳记下', 10, 15, 24, '看哪！撒督也来了，所有抬神约柜的利未人都与他在一起。他们把神的约柜放下。亚比亚他上来，直到从城里出来的众人都走过去了。'),
('CNV', '撒母耳记下', 10, 15, 25, '王对撒督说：“把神的约柜抬回城里去吧！我若是在耶和华眼前蒙恩，他必使我回来再看到约柜和他安居的地方。'),
('CNV', '撒母耳记下', 10, 15, 26, '他若是说：‘我不喜悦你。’看哪！我就在这里，他看怎样好，就怎样对待我吧！”'),
('CNV', '撒母耳记下', 10, 15, 27, '王又对撒督祭司说：“你不是先见吗？平平安安地回到城里去吧！你的儿子亚希玛斯和亚比亚他的儿子约拿单要与你一同回去。'),
('CNV', '撒母耳记下', 10, 15, 28, '我会在旷野的渡口那里等候，直到我接到从你们那里来的消息。”'),
('CNV', '撒母耳记下', 10, 15, 29, '于是撒督和亚比亚他把神的约柜抬回耶路撒冷去，并且住在那里。'),
('CNV', '撒母耳记下', 10, 15, 30, '大卫走上橄榄山；他蒙着头，赤着脚，一边上，一边哭，所有与他在一起的人民也都蒙着头，一边上，一边哭。'),
('CNV', '撒母耳记下', 10, 15, 31, '有人告诉大卫说：“亚希多弗也在押沙龙的叛党之中。”大卫祷告说：“耶和华啊，求你使亚希多弗的计谋变为愚拙。”'),
('CNV', '撒母耳记下', 10, 15, 32, '大卫到了山顶，就是人敬拜神的地方。看哪！有亚基人户筛衣服撕裂，头蒙灰尘，在那里迎接他。'),
('CNV', '撒母耳记下', 10, 15, 33, '大卫对他说：“你若是与我同去；必成为我的累赘。'),
('CNV', '撒母耳记下', 10, 15, 34, '如果你回到城里去，对押沙龙说：‘王啊！我愿作你的仆人，以前我作你父亲的仆人，现在我也照样作你的仆人。’这样，你就可以为我破坏亚希多弗的计谋。'),
('CNV', '撒母耳记下', 10, 15, 35, '撒督祭司和亚比亚他不是都在那里与你在一起吗？你在王宫里听见的话，都要告诉撒督祭司和亚比亚他。'),
('CNV', '撒母耳记下', 10, 15, 36, '看哪！还有他们的两个儿子和他们在那里，就是撒督的儿子亚希玛斯和亚比亚他的儿子约拿单。你们听见的一切，可以托他们来告诉我。”'),
('CNV', '撒母耳记下', 10, 15, 37, '于是大卫的朋友户筛进了城；押沙龙也进了耶路撒冷。'),
('CNV', '撒母耳记下', 10, 16, 1, '大卫刚越过山顶不远，就看见米非波设的仆人洗巴前来迎接他；又有一对预备好了的驴子，驴子身上驮着两百个饼，一百个葡萄干饼，一百个夏天的果饼和一皮袋酒。'),
('CNV', '撒母耳记下', 10, 16, 2, '王问洗巴：“你为什么带这些东西来？”洗巴回答：“驴子是给王的家眷骑的，饼和夏天的果饼是给年轻人吃的，酒是给在旷野里疲乏的人喝的。”'),
('CNV', '撒母耳记下', 10, 16, 3, '王又问：“你主人的孙子米非波设在哪里？”洗巴回答王说：“唉！他还留在耶路撒冷，因为他心里想：‘今日以色列家会把我祖父扫罗的王国归还给我。’”'),
('CNV', '撒母耳记下', 10, 16, 4, '王对洗巴说：“看哪！凡属米非波设所有的，都归给你了。”洗巴说：“我叩拜我主我王，愿我在你眼前蒙恩！”'),
('CNV', '撒母耳记下', 10, 16, 5, '大卫王来到巴户琳的时候，忽然有一人从那里出来，他是属扫罗家族的，名叫示每，是基拉的儿子。他一边出来，一边咒骂；'),
('CNV', '撒母耳记下', 10, 16, 6, '又拿石头投掷大卫和大卫王所有的臣仆，那时众人和众勇士都在王的左右。'),
('CNV', '撒母耳记下', 10, 16, 7, '示每咒骂的时候，这样说：“你这流人血的人啊，滚开！你这无赖啊，滚开！'),
('CNV', '撒母耳记下', 10, 16, 8, '你流了扫罗全家的血，接替扫罗作王，耶和华已经把这罪报应在你身上；耶和华已经把这国交在你儿子押沙龙的手里。看哪！你现在自取其祸了，因为你是个流人血的人。”'),
('CNV', '撒母耳记下', 10, 16, 9, '洗鲁雅的儿子亚比筛对王说：“为什么让这条死狗咒骂我主我王呢？让我过去，把他的头砍下来。”'),
('CNV', '撒母耳记下', 10, 16, 10, '王说：“洗鲁雅的儿子啊，我与你们有什么关系呢？如果他咒骂是因为耶和华对他说：‘你要咒骂大卫！’那么谁敢说：‘你为什么这样作呢？’”'),
('CNV', '撒母耳记下', 10, 16, 11, '大卫又对亚比筛和他所有的臣仆说：“看哪！连我亲生的儿子尚且寻索我的命，何况这便雅悯人呢？由他去吧，由他咒骂吧！因为这是耶和华吩咐他的。'),
('CNV', '撒母耳记下', 10, 16, 12, '也许耶和华看见我的苦难，就施恩与我，以取代今天这人对我的咒骂。”'),
('CNV', '撒母耳记下', 10, 16, 13, '于是大卫和跟从他的人继续在大路上往前去。示每也沿着山坡，与大卫并排而行，一边走，一边咒骂，又用石头投掷他，拿尘土扬他。'),
('CNV', '撒母耳记下', 10, 16, 14, '王和所有与他在一起的人到了一个地方，都觉得累了，就在那里舒展一下。'),
('CNV', '撒母耳记下', 10, 16, 15, '押沙龙和以色列众人进了耶路撒冷，亚希多弗也与押沙龙在一起。'),
('CNV', '撒母耳记下', 10, 16, 16, '大卫的朋友亚基人户筛去见押沙龙，对他说：“愿王万岁！愿王万岁！”'),
('CNV', '撒母耳记下', 10, 16, 17, '押沙龙问户筛：“你就以这样的‘慈爱’待你的朋友吗？你为什么没有与你的朋友一同走呢？”'),
('CNV', '撒母耳记下', 10, 16, 18, '户筛回答押沙龙：“不！耶和华和这民，以及以色列众人所拣选的，我应该归属他，与他在一起。'),
('CNV', '撒母耳记下', 10, 16, 19, '再者，我要事奉谁呢？不是前王的儿子吗？我以前怎样事奉你的父亲，我现在也必怎样事奉你。”'),
('CNV', '撒母耳记下', 10, 16, 20, '押沙龙对亚希多弗说：“你们出个主意，我们应该怎样行才好？”'),
('CNV', '撒母耳记下', 10, 16, 21, '亚希多弗对押沙龙说：“你去与你父亲留下来看守王宫的那些妃嫔亲近，这样以色列众人听见你与你父亲已经完全决裂，所有跟随你的人的手就都更坚强了。”'),
('CNV', '撒母耳记下', 10, 16, 22, '于是有人为押沙龙在王宫的平顶上搭了一座帐棚，押沙龙就在以色列众人眼前与他父亲的妃嫔亲近。'),
('CNV', '撒母耳记下', 10, 16, 23, '那时，亚希多弗所出的策略，好像是人求问神得来的话一样。亚希多弗为大卫，或为押沙龙所出的策略都是这样。'),
('CNV', '撒母耳记下', 10, 17, 1, '亚希多弗又对押沙龙说：“求你准我挑选一万二千人，今晚我要动身去追赶大卫，'),
('CNV', '撒母耳记下', 10, 17, 2, '趁他疲乏手软的时候，忽然追上他，使他惊惶失措，与他在一起的人就必逃跑；我只要单单击杀王一人，'),
('CNV', '撒母耳记下', 10, 17, 3, '使众人都来归你。好像新娘归回丈夫那里一样。你所寻索的不过是一个人的性命，众人会平安无事。众人就都归你了，众人也可以平安无事。”'),
('CNV', '撒母耳记下', 10, 17, 4, '押沙龙和以色列的众长老都看这事为美。'),
('CNV', '撒母耳记下', 10, 17, 5, '押沙龙说：“把亚基人户筛召来，我们也听听他怎么说。”'),
('CNV', '撒母耳记下', 10, 17, 6, '于是户筛来见押沙龙，押沙龙问他说：“亚希多弗说了这样的话，我们可以照着他的话去行吗？如果不可以，请你提议吧！”'),
('CNV', '撒母耳记下', 10, 17, 7, '户筛回答押沙龙：“亚希多弗这次计划的谋略不好。”'),
('CNV', '撒母耳记下', 10, 17, 8, '户筛又说：“你知道你父亲和那些跟随他的人都是勇士；他们心里正在恼怒，好像野地里丧子的母熊一样；并且你父亲是个战士，必不会与众人在一起住宿。'),
('CNV', '撒母耳记下', 10, 17, 9, '现在他或躺在一个坑中，或在另一个地方，如果他首先攻击你的手下，听见的人就必说：‘跟从押沙龙的人被杀了！’'),
('CNV', '撒母耳记下', 10, 17, 10, '那时，纵使有人像狮子一般勇敢，心里也必惊慌，因为全以色列都知道你父亲是个勇士，跟随他的人都是英勇的人。'),
('CNV', '撒母耳记下', 10, 17, 11, '因此，我建议把以色列众人，从但到别是巴，都聚集到你这里来，好像海边的沙那样多，然后你亲自率领他们上战场。'),
('CNV', '撒母耳记下', 10, 17, 12, '无论我们在哪一个地方找到大卫，就攻击他；我们临到他，像露水降在地上一样。这样，他和跟随他的人，就一个也不会留下。'),
('CNV', '撒母耳记下', 10, 17, 13, '如果他退入城里去，以色列众人就要带绳子到那城去，我们要把那城拉到河里去，使那里连一块小石头也找不到。”'),
('CNV', '撒母耳记下', 10, 17, 14, '押沙龙和以色列众人都说：“亚基人户筛的谋略比亚希多弗的好。”因为耶和华定意要破坏亚希多弗的好计谋，为要降灾祸给押沙龙。'),
('CNV', '撒母耳记下', 10, 17, 15, '于是户筛对撒督祭司和亚比亚他说：“亚希多弗为押沙龙和以色列的众长老所策定的谋略是这样这样的，我所策定的谋略又是这样这样的。'),
('CNV', '撒母耳记下', 10, 17, 16, '现在你们要赶快派人去告诉大卫：‘今天晚上你不可在旷野的渡口住宿，务要过河，免得王和跟随他的众人都被吞灭。’”'),
('CNV', '撒母耳记下', 10, 17, 17, '那时，约拿单和亚希玛斯停留在隐‧罗结，他们不敢进城，怕被人看见。有一个婢女经常出来，把话告诉他们，然后他们再去告诉大卫王。'),
('CNV', '撒母耳记下', 10, 17, 18, '但有一个仆人看见他们，就去告诉押沙龙。因此，他们两人急忙离开那里，来到巴户琳某人的家里；那人的院子里有一口井，他们就下到井里。'),
('CNV', '撒母耳记下', 10, 17, 19, '那家的主妇拿了一块大布，盖在井口上，又在上面铺了一些麦子，所以没有人知道这件事。'),
('CNV', '撒母耳记下', 10, 17, 20, '押沙龙的臣仆到这家来见那妇人，问她：“亚希玛斯和约拿单在哪里？”那妇人回答他们说：“他们已经过了河了。”于是臣仆搜索他们，却没有找着，就都回耶路撒冷去了。'),
('CNV', '撒母耳记下', 10, 17, 21, '他们走了以后，两人从井里上来，去告诉大卫王，对大卫说：“你们要起来，赶快过河，因为亚希多弗已经定了这样这样的谋略攻击你们。”'),
('CNV', '撒母耳记下', 10, 17, 22, '于是大卫和跟随他的众人都起来，渡过约旦河；到了天亮，没有一人还没有渡过约旦河的。'),
('CNV', '撒母耳记下', 10, 17, 23, '亚希多弗见自己的谋略不被采纳，就预备了驴子，起程往本城自己的家去。他安排好了家里的事，就上吊死了，埋葬在他父亲的坟墓里。'),
('CNV', '撒母耳记下', 10, 17, 24, '大卫到了玛哈念，押沙龙和跟随他的以色列众人也都过了约旦河。'),
('CNV', '撒母耳记下', 10, 17, 25, '押沙龙派亚玛撒统率军队，取代约押。亚玛撒是以实玛利人以特拉的儿子。以特拉曾经与拿辖的女儿亚比该亲近过；亚比该和约押的母亲洗鲁雅是姊妹。'),
('CNV', '撒母耳记下', 10, 17, 26, '以色列人和押沙龙都在基列地安营。'),
('CNV', '撒母耳记下', 10, 17, 27, '大卫到了玛哈念的时候，亚扪族的拉巴人拿辖的儿子朔比、罗‧底巴人亚米利的儿子玛吉、基列的罗基琳人巴西莱，'),
('CNV', '撒母耳记下', 10, 17, 28, '带来寝具、碗盆、瓦器、小麦、大麦、面粉、炒麦、豆子、红豆、炒豆、'),
('CNV', '撒母耳记下', 10, 17, 29, '蜂蜜、奶油、绵羊和奶酪送给大卫和跟随他的人吃，因为他们说：“这些人在旷野一定又饥饿，又疲倦，又口渴了。”'),
('CNV', '撒母耳记下', 10, 18, 1, '大卫数点了跟随他的人，亦立千夫长、百夫长率领他们。'),
('CNV', '撒母耳记下', 10, 18, 2, '大卫派遣众人出战：三分之一在约押手下，三分之一在约押的兄弟、洗鲁雅的儿子亚比筛手下，三分之一在迦特人以太手下。大卫对众人说：“我也必与你们一同出战。”'),
('CNV', '撒母耳记下', 10, 18, 3, '众人却说：“你不可以出战。因为如果我们逃跑，他们不会把我们放在心上，即使我们死了一半，他们也不会把我们放在心上。因为你一个人抵得上我们一万人；所以你最好还是留在城里，随时支援我们。”'),
('CNV', '撒母耳记下', 10, 18, 4, '王对他们说：“你们看怎么好，我就怎样作吧！”于是王站在城门旁边，众人组成百人一队或千人一队出发了。'),
('CNV', '撒母耳记下', 10, 18, 5, '王吩咐约押、亚比筛和以太说：“为我的缘故，你们要宽待那年轻人押沙龙。”王为押沙龙吩咐众将领的话，众人都听到了。'),
('CNV', '撒母耳记下', 10, 18, 6, '众人出到田野迎战以色列人；战争发生在以法莲的树林里。'),
('CNV', '撒母耳记下', 10, 18, 7, '在那里，以色列人在大卫的臣仆面前被打败了；那天被杀的人很多，共有二万人。'),
('CNV', '撒母耳记下', 10, 18, 8, '战事在那里蔓延到全地；那一天，树林所吞灭的比刀剑所吞灭的更多。'),
('CNV', '撒母耳记下', 10, 18, 9, '押沙龙偶然遇上了大卫的臣仆。那时押沙龙骑着骡子，骡子从一棵大橡树茂密的树枝下经过，押沙龙的头发被橡树枝紧紧勾住，他就吊在空中，他所骑的骡子却跑开了。'),
('CNV', '撒母耳记下', 10, 18, 10, '有一个人看见了，就告诉约押说：“看哪！我看见押沙龙悬在一棵橡树上。”'),
('CNV', '撒母耳记下', 10, 18, 11, '约押对那向他报告的人说：“你既然看见了，为什么不当场把他击杀，落在地上呢？那样，我就赏赐你一百一十四克银子和一条腰带。”'),
('CNV', '撒母耳记下', 10, 18, 12, '那人回答约押：“就是量十一公斤银子放在我手中，我也不敢伸手伤害王的儿子，因为我们亲耳听见王吩咐你、亚比筛和以太说：‘你们要为我的缘故，照顾那年轻人押沙龙。’'),
('CNV', '撒母耳记下', 10, 18, 13, '我若是胆大妄为伤害了他的性命，什么事情都瞒不过王的，那时你也不会维护我。”'),
('CNV', '撒母耳记下', 10, 18, 14, '约押说：“我不能与你这样耽误时间。”于是约押手里拿起三根短矛，趁押沙龙还悬挂在橡树上活着的时候，就刺透了他的心。'),
('CNV', '撒母耳记下', 10, 18, 15, '给约押拿武器的十个年轻人围着押沙龙，攻击他，把他杀死。'),
('CNV', '撒母耳记下', 10, 18, 16, '约押吹响号角，众人就回来，不再追赶以色列人；因为约押拦阻众人继续追赶。'),
('CNV', '撒母耳记下', 10, 18, 17, '他们把押沙龙的尸体抬起来，丢在树林中的一个大坑里，又在上面堆起一大堆石头。以色列众人都逃跑，各回自己的家去了。'),
('CNV', '撒母耳记下', 10, 18, 18, '押沙龙生前曾在王谷为自己立了一根石柱，因为他想：“我没有儿子记念我的名字。”他就以自己的名字称那石柱。因此人称那石柱为押沙龙柱，直到今日。'),
('CNV', '撒母耳记下', 10, 18, 19, '撒督的儿子亚希玛斯说：“让我跑去，把这好消息向王报告，就是耶和华已经把他从仇敌的手中拯救出来了。”'),
('CNV', '撒母耳记下', 10, 18, 20, '约押对他说：“你今天不可去报消息，改天才可以去报。你今天不可去报消息，因为王的儿子死了。”'),
('CNV', '撒母耳记下', 10, 18, 21, '于是约押对一个古实人说：“你去把你所看见的告诉王吧！”那古实人叩拜了约押，就跑去了。'),
('CNV', '撒母耳记下', 10, 18, 22, '撒督的儿子亚希玛斯又对约押说：“不管怎样，请让我也跟着那古实人跑去。”约押说：“你为什么要跑去呢？我儿，你是不会得到报消息的赏赐的。”'),
('CNV', '撒母耳记下', 10, 18, 23, '“不管怎样，请让我跑去！”于是约押对他说：“你跑去吧！”亚希玛斯就沿着约旦河大道跑去，赶过了那古实人。'),
('CNV', '撒母耳记下', 10, 18, 24, '那时，大卫正坐在内外城门中间的地方。守望的人上到城楼的平顶上，举目观看，见有一个人独自跑来。'),
('CNV', '撒母耳记下', 10, 18, 25, '守望的人就喊叫，把这事告诉王；王说：“他若是单独一人，必是来报好消息的。”那人越走越近了。'),
('CNV', '撒母耳记下', 10, 18, 26, '后来，守望的人又看见另一个人跑来，就对守城门的人喊叫，说：“看哪！又有一个人独自跑来！”王说：“这也必是来报好消息的。”'),
('CNV', '撒母耳记下', 10, 18, 27, '守望的人说：“我看前头那人的跑法好像撒督的儿子亚希玛斯的跑法一样。”王说：“他是个好人，必是带好消息来的。”'),
('CNV', '撒母耳记下', 10, 18, 28, '亚希玛斯向王呼叫，说：“平安！”就脸伏于地，叩拜王，说：“耶和华你的神是应当称颂的，因为他已经把举手攻击我主我王的人交给你了！”'),
('CNV', '撒母耳记下', 10, 18, 29, '王问：“那年轻人押沙龙平安不平安？”亚希玛斯回答：“约押差派王的仆人，就是你的仆人我来的时候，我看见有大动乱，却不知道是什么事。”'),
('CNV', '撒母耳记下', 10, 18, 30, '王说：“你退到一旁，站在那里！”他就退到一旁，站在那里。'),
('CNV', '撒母耳记下', 10, 18, 31, '那古实人也到了。他说：“有好消息报给我主我王；今天耶和华已经救你脱离那些起来攻击你的人的手了！”'),
('CNV', '撒母耳记下', 10, 18, 32, '王问古实人：“那年轻人押沙龙平安吗？”古实人回答：“愿我主我王的仇敌和一切来攻击你、伤害你的人，都像那年轻人一样。”'),
('CNV', '撒母耳记下', 10, 18, 33, '王悲恸得全身发抖，就上城楼去哀哭。他一面走一面这样说：“我儿押沙龙啊！我儿，我儿押沙龙啊！但愿我替你死。押沙龙啊！我儿，我儿啊！”'),
('CNV', '撒母耳记下', 10, 19, 1, '有人告诉约押：“看哪！王正在为押沙龙悲哀哭泣。”'),
('CNV', '撒母耳记下', 10, 19, 2, '那一天，众人胜利的欢乐变成了悲哀，因为他们听说王为他的儿子伤痛。'),
('CNV', '撒母耳记下', 10, 19, 3, '那一天，众人偷偷进城，就像军人从战场上逃跑，羞愧地偷偷回来一样。'),
('CNV', '撒母耳记下', 10, 19, 4, '王蒙着脸，大声哀哭，说：“我儿押沙龙啊！押沙龙，我儿，我儿啊！”'),
('CNV', '撒母耳记下', 10, 19, 5, '约押进了屋子去见王，说：“你所有的臣仆今天救了你的性命，和你儿女妻妾的性命，你今天却使他们满面羞愧；'),
('CNV', '撒母耳记下', 10, 19, 6, '你爱那些恨你的，恨那些爱你的。因为你今天表明了你不重视将帅和臣仆；我今天才明白，如果押沙龙活着，我们大家都死去，你就欢喜了。'),
('CNV', '撒母耳记下', 10, 19, 7, '现在请你起来，出去，说些安慰你仆人们的话。我指着耶和华起誓，如果你不出去，今夜就必没有一人留下来与你在一起。这祸患就比你从幼年到现在所遭受的一切祸患更厉害了。”'),
('CNV', '撒母耳记下', 10, 19, 8, '于是王起来，坐在城门口。有人告诉众民说：“看哪！王坐在城门口。”于是众人都来到王的面前。以色列人已经逃跑，各回自己的家去了。'),
('CNV', '撒母耳记下', 10, 19, 9, '以色列众支派的人都纷纷议论，说：“王曾经拯救我们脱离仇敌的手，又救了我们脱离非利士人的手，现在他却躲避押沙龙，离开这地逃走了。'),
('CNV', '撒母耳记下', 10, 19, 10, '我们所膏立统治我们的押沙龙，已经在战场上死了。现在你们为什么不出声请王回来呢？”'),
('CNV', '撒母耳记下', 10, 19, 11, '大卫王派人去见撒督祭司和亚比亚他，说：“你们要对犹大的众长老说：‘你们为什么在请王回宫的事上落在人后头呢？全以色列请王回宫的话已经传到王和王宫那里去了。'),
('CNV', '撒母耳记下', 10, 19, 12, '你们是我的兄弟，我的骨肉至亲，为什么在请王回来的事上，倒落在人后头呢？’'),
('CNV', '撒母耳记下', 10, 19, 13, '你们又要对亚玛撒说：‘你不是我的骨肉至亲吗？我若不立你代替约押，在我面前作军队的元帅，愿神重重地惩罚我，并且加倍严厉地惩罚我。’”'),
('CNV', '撒母耳记下', 10, 19, 14, '这样，大卫挽回了犹大众人的心，好像一人的心。于是他们差派人去见王，说：“请你和你的众臣仆都回来！”'),
('CNV', '撒母耳记下', 10, 19, 15, '王就回来，到了约旦河。犹大人也来到吉甲，要去迎接王，接王过约旦河。'),
('CNV', '撒母耳记下', 10, 19, 16, '巴户琳的便雅悯人，基拉的儿子示每，急忙与犹大人一同下去迎接大卫王。'),
('CNV', '撒母耳记下', 10, 19, 17, '与示每同来的有一千便雅悯人，还有扫罗家的仆人洗巴，和他的十五个儿子，以及二十个仆人。他们都冲过约旦河去迎接王。'),
('CNV', '撒母耳记下', 10, 19, 18, '有人渡过渡口，把王的家眷接过去，并且照着王的心意去作。大卫过约旦河的时候，基拉的儿子示每俯伏在王面前，'),
('CNV', '撒母耳记下', 10, 19, 19, '对王说：“我主我王从耶路撒冷出来的那一天，你仆人所犯的错，现在求我主不要归罪于我，求你不要记念，求王也不要放在心上。'),
('CNV', '撒母耳记下', 10, 19, 20, '因为你的仆人知道自己犯了罪，所以你看，在约瑟全家之中，今天我是第一个下来迎接我主我王的。”'),
('CNV', '撒母耳记下', 10, 19, 21, '洗鲁雅的儿子亚比筛回答说：“示每咒骂了耶和华的受膏者，岂不该因此把他处死吗？”'),
('CNV', '撒母耳记下', 10, 19, 22, '大卫说：“洗鲁雅的儿子们啊，我与你们有什么关系呢？今天你们竟与我作对！今天在以色列中，岂可有人被处死呢？难道我不知道今天我作以色列的王吗？”'),
('CNV', '撒母耳记下', 10, 19, 23, '于是王对示每说：“你一定不会被处死！”王又向他起誓。'),
('CNV', '撒母耳记下', 10, 19, 24, '扫罗的孙子米非波设也下去迎接王。他自从王出走那天，直到王平平安安回来的日子，都没有修脚，没有刮胡子，也没有洗衣服。'),
('CNV', '撒母耳记下', 10, 19, 25, '他从耶路撒冷来迎接王的时候，王问他：“米非波设啊，你为什么没有与我一同离开呢？”'),
('CNV', '撒母耳记下', 10, 19, 26, '他回答：“我主我王，你仆人是瘸腿的；那天，我心里想我要预备驴子，可以骑上，与王一同离开，但是我的仆人却欺骗了我，'),
('CNV', '撒母耳记下', 10, 19, 27, '又在我主我王面前毁谤你仆人。但我主我王像神的使者一样，现在，你看怎样好，就怎样行吧！'),
('CNV', '撒母耳记下', 10, 19, 28, '因为我祖父全家的人，在我主我王面前都算不得什么，都不过是该死的人；你却使仆人在你席上与你一同吃饭。我还有什么权利再向王哀求什么呢？”'),
('CNV', '撒母耳记下', 10, 19, 29, '王就对他说：“你为什么再提你的事呢？我已经决定，你与洗巴要均分那地。”'),
('CNV', '撒母耳记下', 10, 19, 30, '米非波设对王说：“我主我王既然已平平安安回宫，所有的一切就都任凭洗巴拿去好了。”'),
('CNV', '撒母耳记下', 10, 19, 31, '基列人巴西莱也从罗基琳下来，与王一同过约旦河，要在约旦河边给王送行。'),
('CNV', '撒母耳记下', 10, 19, 32, '巴西莱年纪非常老迈，已经八十岁。王住在玛哈念的时候，是他供养王的，因为他是一个很富有的人。'),
('CNV', '撒母耳记下', 10, 19, 33, '王对巴西莱说：“你与我一同过河去，在耶路撒冷与我同住，我要供养你。”'),
('CNV', '撒母耳记下', 10, 19, 34, '巴西莱对王说：“我活着的年日还能有多少，可使我与王一同上耶路撒冷呢？'),
('CNV', '撒母耳记下', 10, 19, 35, '我现在已经八十岁了，还能分别美丑吗？你仆人还能尝出吃喝的味道吗？我还能细听男女歌手的声音吗？你仆人为什么要负累我主我王呢？'),
('CNV', '撒母耳记下', 10, 19, 36, '你仆人只不过与王一同过约旦河，王为什么要这样赏赐我呢？'),
('CNV', '撒母耳记下', 10, 19, 37, '请让你仆人回去，好死在我自己的城里，埋葬在我父母的坟墓旁。看哪，你仆人金罕在这里，请让他与我主我王一同过河；你看怎么好，就怎么待他吧！”'),
('CNV', '撒母耳记下', 10, 19, 38, '王说：“金罕可以与我一同过河。你看怎么好，我就怎么待他。你向我所要求的，我都必为你成全。”'),
('CNV', '撒母耳记下', 10, 19, 39, '于是众人都渡过约旦河，王也渡过了。王与巴西莱亲吻，为他祝福，巴西莱就回自己的地方去了。'),
('CNV', '撒母耳记下', 10, 19, 40, '王过了河，到了吉甲，金罕也与王一同渡河。所有的犹大人和半数以色列人，也都与王一同渡河。'),
('CNV', '撒母耳记下', 10, 19, 41, '以色列众人都来见王，问王说：“我们的兄弟犹大人为什么把你偷去了，把王和王的家眷接过约旦河呢？属大卫的人不都一样是他的人民吗？”'),
('CNV', '撒母耳记下', 10, 19, 42, '犹大众人回答以色列人说：“因为王与我们的关系亲密。你们为什么因这事而生气呢？我们从王那里得到什么吃的呢？或是他给了我们什么礼物呢？”'),
('CNV', '撒母耳记下', 10, 19, 43, '以色列人回答犹大人说：“在王的事上，我们有十分的投入。在大卫身上，我们也与大卫比你们更有情分。你们为什么轻视我们呢？先说要请我们的王回来的，不是我们吗？”但是犹大人的话比以色列人的话更强硬。'),
('CNV', '撒母耳记下', 10, 20, 1, '在那里恰巧有一个流氓名叫示巴，是便雅悯人比基利的儿子。他吹号角，说：“我们在大卫的身上无分，在耶西的儿子身上无干，以色列人哪！各回自己的帐棚去吧！”'),
('CNV', '撒母耳记下', 10, 20, 2, '于是以色列众人都上山去，不跟随大卫，却跟随了比基利的儿子示巴；犹大人却紧紧跟随他们的王，从约旦河直到耶路撒冷。'),
('CNV', '撒母耳记下', 10, 20, 3, '大卫王回到耶路撒冷自己的宫里，就把以前留下来看守王宫的那十个妃嫔捉起来，关在禁宫里。王供养她们，却不再亲近她们。她们被禁闭，过着寡妇一般的生活，直到死的日子。'),
('CNV', '撒母耳记下', 10, 20, 4, '王对亚玛撒说：“你要在三天之内把犹大人召集到我这里来。你自己也要在这里。”'),
('CNV', '撒母耳记下', 10, 20, 5, '亚玛撒就去召集犹大人。他却耽延，超过了王限定的日期。'),
('CNV', '撒母耳记下', 10, 20, 6, '大卫对亚比筛说：“现在比基利的儿子示巴要加害我们，比押沙龙更甚。你要带着你主人的仆人去追赶他，免得他找到了设防的城镇，就避过我们的眼目，从我们的手中逃脱了。”'),
('CNV', '撒母耳记下', 10, 20, 7, '于是约押的人，基利提人、比利提人和所有的勇士，都跟随亚比筛出去。他们从耶路撒冷出去，追赶比基利的儿子示巴。'),
('CNV', '撒母耳记下', 10, 20, 8, '他们到了基遍的大磐石那里，亚玛撒来与他们会合。那时约押穿着战衣，腰间束着佩刀的带子，刀在鞘里。他往前走的时候，刀掉了下来。'),
('CNV', '撒母耳记下', 10, 20, 9, '约押对亚玛撒说：“我的兄弟，你好吗？”约押用右手握住亚玛撒的胡子，要与他亲吻。'),
('CNV', '撒母耳记下', 10, 20, 10, '亚玛撒没有防备约押手中的刀，约押用这刀刺进他的肚子，他的内脏就流在地上。不用再刺第二刀，亚玛撒就死了。约押和他的兄弟亚比筛继续追赶比基利的儿子示巴。'),
('CNV', '撒母耳记下', 10, 20, 11, '约押的仆从之中，有一个人站在亚玛撒的尸体旁边，说：“谁喜欢约押，谁归顺大卫，就当跟随约押去！”'),
('CNV', '撒母耳记下', 10, 20, 12, '亚玛撒在大道当中，滚在自己的血里。那人看见经过的众人都站住，就把亚玛撒的尸体从大道上拖到田里，又扔一件衣服把他盖住，因为他看见众人来到亚玛撒的尸体旁边都站住。'),
('CNV', '撒母耳记下', 10, 20, 13, '尸体从大道上挪去以后，众人就都过去，跟随约押去追赶比基利的儿子示巴。'),
('CNV', '撒母耳记下', 10, 20, 14, '示巴走遍以色列各支派，直到伯‧玛迦的亚比拉和比利人的全境，他们聚集起来跟随他。'),
('CNV', '撒母耳记下', 10, 20, 15, '所有跟随约押的人都来了，把示巴围困在伯‧玛迦的亚比拉。他们对着城筑起攻城的土垒，高度与城的外墙一样。他们撞击城墙，要把城墙撞倒。'),
('CNV', '撒母耳记下', 10, 20, 16, '有一个聪明的妇人在城墙上呼叫：“请听！请听！请你们对约押说：‘请你走近这里，我有话对你说。’”'),
('CNV', '撒母耳记下', 10, 20, 17, '约押走近妇人那里，妇人问：“你是约押吗？”他回答：“我是。”妇人对他说：“请听婢女的话！”他说：“我正在听！”'),
('CNV', '撒母耳记下', 10, 20, 18, '妇人说：“古时人常说：‘只要在亚比拉求问，事就必成全。’'),
('CNV', '撒母耳记下', 10, 20, 19, '我在以色列中是和平信实的人，你却设法毁灭这座以色列的母城。你为什么要吞灭耶和华的产业呢？”'),
('CNV', '撒母耳记下', 10, 20, 20, '约押回答：“绝对不会！我绝对不会吞灭，也不会毁坏。'),
('CNV', '撒母耳记下', 10, 20, 21, '事情不是这样的；只因以法莲山地有一个人名叫示巴，是比基利的儿子，他举手攻击大卫王。你们只要把他一人交出来，我就离开这城。”妇人对约押说：“看哪！那人的头必从这城墙上丢给你。”'),
('CNV', '撒母耳记下', 10, 20, 22, '妇人就凭她的智慧去见众人，他们就把比基利的儿子示巴的头砍下来，丢给约押；约押吹号角，众人就离城散开，各回自己的家去了。约押也回耶路撒冷去见王。'),
('CNV', '撒母耳记下', 10, 20, 23, '约押作以色列所有军队的统帅。耶何耶大的儿子比拿雅统辖基利提人和比利提人；'),
('CNV', '撒母耳记下', 10, 20, 24, '亚多兰管理作苦工的人。亚希律的儿子约沙法作史官；'),
('CNV', '撒母耳记下', 10, 20, 25, '示法作书记。撒督和亚比亚他作祭司长；'),
('CNV', '撒母耳记下', 10, 20, 26, '睚珥人以拉也作大卫的祭司。'),
('CNV', '撒母耳记下', 10, 21, 1, '大卫在位的日子，有连续三年的饥荒；大卫就寻求耶和华的面。耶和华说：“这是因为扫罗和扫罗家流人血的罪，因为他曾经杀死了基遍人。”'),
('CNV', '撒母耳记下', 10, 21, 2, '原来基遍人不是以色列人，而是亚摩利人中余剩的后人。以色列人曾经起誓与他们立约，但扫罗却为以色列人和犹大人发热心，设法要击杀他们。王把基遍人召了来，对他们说话。'),
('CNV', '撒母耳记下', 10, 21, 3, '大卫问基遍人：“我能为你们作什么？我该用什么来赎罪，使你们为耶和华的产业祝福呢？”'),
('CNV', '撒母耳记下', 10, 21, 4, '基遍人回答大卫：“我们与扫罗和他家的事，都与金子银子没有关系；我们也不愿以色列中有一个人被杀。”大卫问：“那么，你们说，我当为你们作什么？”'),
('CNV', '撒母耳记下', 10, 21, 5, '他们回答王：“从前破坏我们，谋害我们，要消灭我们，使我们不能在以色列境内立足的那人，'),
('CNV', '撒母耳记下', 10, 21, 6, '现在请你把他子孙中的七个男丁交给我们，我们可以在基遍耶和华的山上，在耶和华面前把他们处决。”王说：“我必交给你们。”'),
('CNV', '撒母耳记下', 10, 21, 7, '王顾惜扫罗的孙子、约拿单的儿子米非波设，因为大卫与扫罗的儿子约拿单，曾经在耶和华面前有过誓约。'),
('CNV', '撒母耳记下', 10, 21, 8, '于是王逮捕了爱雅的女儿利斯巴为扫罗所生的两个儿子：亚摩尼和米非波设，和扫罗的女儿米拉为米何拉人巴西莱的儿子亚得列所生的五个儿子，'),
('CNV', '撒母耳记下', 10, 21, 9, '把他们交在基遍人的手里。基遍人就在山上耶和华面前把他们处决，这七人就一同倒毙了。他们被处死的时候，正是收获季节之初，就是开始收割大麦的时候。'),
('CNV', '撒母耳记下', 10, 21, 10, '爱雅的女儿利斯巴拿了一块麻布，为自己铺在磐石上。从开始收割的时候，直到雨水从天上倾倒在他们的尸身上的时候，白天她不让空中的飞鸟落在尸身上，夜间不让田间的走兽来糟践他们。'),
('CNV', '撒母耳记下', 10, 21, 11, '有人把扫罗的妃子，爱雅的女儿利斯巴所作的这事告诉了大卫，'),
('CNV', '撒母耳记下', 10, 21, 12, '大卫就去把扫罗的骸骨和他儿子约拿单的骸骨，从基列‧雅比人那里搬回来。原来非利士人从前在基利波山击杀扫罗那一天，就把他们二人的尸体挂在伯‧珊的广场上，基列‧雅比人却把他们偷了去。'),
('CNV', '撒母耳记下', 10, 21, 13, '大卫把扫罗和他儿子约拿单的骸骨从那里搬上来；又有人收殓了那些被处决者的骸骨。'),
('CNV', '撒母耳记下', 10, 21, 14, '他们把扫罗和他儿子约拿单的骸骨埋葬在便雅悯地的洗拉，在扫罗父亲基士的坟墓里。王所吩咐的一切，众人都行了。这事以后，神垂听了人们为那地的祷告。'),
('CNV', '撒母耳记下', 10, 21, 15, '非利士人与以色列人又有了战事。大卫和跟随他的臣仆一同下去，要与非利士人争战；大卫疲倦了。'),
('CNV', '撒母耳记下', 10, 21, 16, '他们住在歌伯。有一个人，是巨人的儿子，他的铜矛有三公斤半重，又佩带着新刀；他想要击杀大卫。'),
('CNV', '撒母耳记下', 10, 21, 17, '洗鲁雅的儿子亚比筛帮助了大卫；亚比筛击打那非利士人，把他杀死了。那时，跟随大卫的人向他起誓说：“以后你不可再与我们一同出去打仗，免得以色列的灯熄灭了。”'),
('CNV', '撒母耳记下', 10, 21, 18, '后来，以色列人又在歌伯与非利士人争战。那时，户沙人西比该击杀了巨人的一个儿子撒弗。'),
('CNV', '撒母耳记下', 10, 21, 19, '在歌伯又再与非利士人争战。伯利恒人雅雷俄珥金的儿子伊勒哈难击杀了迦特人歌利亚。这人的矛杆好像织布的机轴那么粗大。'),
('CNV', '撒母耳记下', 10, 21, 20, '在迦特又有一场战事，那里有一个身量高大的人，手脚都各有六个指头，总数是二十四个；这人也是巨人所生的。'),
('CNV', '撒母耳记下', 10, 21, 21, '这人向以色列人骂阵，大卫的哥哥示米亚的儿子约拿单把他击杀了。'),
('CNV', '撒母耳记下', 10, 21, 22, '以上这四个人都是迦特城里那个巨人所生的，都死在大卫和大卫臣仆的手下。'),
('CNV', '撒母耳记下', 10, 22, 1, '在耶和华拯救大卫脱离所有仇敌和扫罗的手的日子，他向耶和华唱出这首歌的歌词。'),
('CNV', '撒母耳记下', 10, 22, 2, '他说：“耶和华是我的岩石、我的山寨、我的救主、'),
('CNV', '撒母耳记下', 10, 22, 3, '我的神、我的磐石、我所投靠的、我的盾牌、我救恩的角、我的高台、我的避难所、我的救主；你是救我脱离强暴的。'),
('CNV', '撒母耳记下', 10, 22, 4, '我向那当受赞美的耶和华呼求，就得到拯救，脱离我的仇敌。'),
('CNV', '撒母耳记下', 10, 22, 5, '死亡的波浪环绕我，毁灭的急流淹没了我。'),
('CNV', '撒母耳记下', 10, 22, 6, '阴间的绳索围绕着我；死亡的网罗迎面而来。'),
('CNV', '撒母耳记下', 10, 22, 7, '急难临到我的时候，我求告耶和华，我向我的神呼求；他从殿中听了我的声音，我的呼求进了他的耳中。'),
('CNV', '撒母耳记下', 10, 22, 8, '那时大地摇撼震动，天的根基也都摇动；它们摇撼，是因为耶和华发怒。'),
('CNV', '撒母耳记下', 10, 22, 9, '浓烟从他的鼻孔往上冒，烈火从他的口中喷出来，连炭也烧着了。'),
('CNV', '撒母耳记下', 10, 22, 10, '他使天下垂，亲自降临；在他的脚下黑云密布。'),
('CNV', '撒母耳记下', 10, 22, 11, '他乘着基路伯飞行，藉着风的翅膀急飞。'),
('CNV', '撒母耳记下', 10, 22, 12, '他以黑暗作他的隐密处，他以浓黑的水气，就是天空的密云，作他四周的帷帐。'),
('CNV', '撒母耳记下', 10, 22, 13, '从他面前发出的光辉，火炭都烧起来！'),
('CNV', '撒母耳记下', 10, 22, 14, '耶和华从天上打雷，至高者发出声音。'),
('CNV', '撒母耳记下', 10, 22, 15, '他射出箭来，使它们四散；他发出闪电，使它们混乱。'),
('CNV', '撒母耳记下', 10, 22, 16, '耶和华的斥责一发，他鼻孔的气一出，海底就出现，大地的根基也显露。'),
('CNV', '撒母耳记下', 10, 22, 17, '他从高处伸手抓住我，把我从大水中拉上来。'),
('CNV', '撒母耳记下', 10, 22, 18, '他救我脱离我的强敌，脱离那些恨我的人，因为他们比我强盛。'),
('CNV', '撒母耳记下', 10, 22, 19, '在我遭难的日子，他们来攻击我；但耶和华是我的支持。'),
('CNV', '撒母耳记下', 10, 22, 20, '他又领我出去，到那宽阔之地；他搭救我，因为他喜悦我。'),
('CNV', '撒母耳记下', 10, 22, 21, '耶和华按着我的公义报答我，照着我手中的清洁回报我。'),
('CNV', '撒母耳记下', 10, 22, 22, '因为我谨守了耶和华的道；未曾作恶离开我的神。'),
('CNV', '撒母耳记下', 10, 22, 23, '因为他的一切典章常摆在我面前，他的律例，我未曾丢弃。'),
('CNV', '撒母耳记下', 10, 22, 24, '我在他面前作完全的人，我也谨守自己，脱离我的罪孽；'),
('CNV', '撒母耳记下', 10, 22, 25, '所以耶和华按着我的公义，照着我在他眼前的清洁回报我。'),
('CNV', '撒母耳记下', 10, 22, 26, '对慈爱的人，你显出你的慈爱；对完全的人，你显出你的完全。'),
('CNV', '撒母耳记下', 10, 22, 27, '对清洁的人，你显出你的清洁；对狡诈的人，你显出你的机巧。'),
('CNV', '撒母耳记下', 10, 22, 28, '谦卑的人，你要拯救；你的眼睛察看高傲的人，要使他们降卑。'),
('CNV', '撒母耳记下', 10, 22, 29, '耶和华啊！你是我的灯；耶和华照明了我的黑暗。'),
('CNV', '撒母耳记下', 10, 22, 30, '藉着你，我攻破敌军；靠着我的神，我跳过墙垣。'),
('CNV', '撒母耳记下', 10, 22, 31, '这位神，他的道路是完全的；耶和华的话是炼净的；凡是投靠他的，他都作他们的盾牌。'),
('CNV', '撒母耳记下', 10, 22, 32, '除了耶和华，谁是神呢？除了我们的神，谁是磐石呢？'),
('CNV', '撒母耳记下', 10, 22, 33, '这位神是我坚固的避难所，他使我的道路完全。'),
('CNV', '撒母耳记下', 10, 22, 34, '他使我的脚像母鹿的蹄，又使我站稳在高处。'),
('CNV', '撒母耳记下', 10, 22, 35, '他教导我的手怎样作战，又使我的手臂可以拉开铜弓。'),
('CNV', '撒母耳记下', 10, 22, 36, '你把你救恩的盾牌赐给我；你的回答使我昌大。'),
('CNV', '撒母耳记下', 10, 22, 37, '你使我脚底下的路径宽阔，我的两膝不会动摇。'),
('CNV', '撒母耳记下', 10, 22, 38, '我追赶仇敌，把他们追上，不消灭他们，我必不归回。'),
('CNV', '撒母耳记下', 10, 22, 39, '我吞灭他们，重创他们，使他们不能起来；他们都倒在我的脚下。'),
('CNV', '撒母耳记下', 10, 22, 40, '你以能力给我束腰，使我能够作战；你又使那些起来攻击我的人都屈服在我的脚下。'),
('CNV', '撒母耳记下', 10, 22, 41, '你使我的仇敌在我面前转背逃跑，使我可以歼灭恨我的人。'),
('CNV', '撒母耳记下', 10, 22, 42, '他们呼叫，却没有人拯救；就算向耶和华呼求，他也不答应他们。'),
('CNV', '撒母耳记下', 10, 22, 43, '我捣碎他们，像地上的尘土；我打碎他们，践踏他们，像街上的烂泥。'),
('CNV', '撒母耳记下', 10, 22, 44, '你救我脱离了我民的争竞，你立我作列国的元首；我不认识的人民要服事我。'),
('CNV', '撒母耳记下', 10, 22, 45, '外族人都向我假意归顺；他们一听见，就服从我；'),
('CNV', '撒母耳记下', 10, 22, 46, '外族人大势已去，战战兢兢地从他们的要塞走出来。'),
('CNV', '撒母耳记下', 10, 22, 47, '耶和华是永活的，我的磐石是应当称颂的；拯救我的神，我的磐石，是应当被尊为至高的。'),
('CNV', '撒母耳记下', 10, 22, 48, '他是那位为我伸冤的神，他使万民服在我的脚下，'),
('CNV', '撒母耳记下', 10, 22, 49, '他救我脱离我的仇敌。你还把我高举起来，高过那些起来攻击我的人，又救我脱离了强暴的人。'),
('CNV', '撒母耳记下', 10, 22, 50, '因此，耶和华啊，我要在列国中称赞你，歌颂你的名。'),
('CNV', '撒母耳记下', 10, 22, 51, '耶和华赐极大的救恩给他所立的王，又向他的受膏者施慈爱，就是向大卫和他的后裔施慈爱，直到永远。”'),
('CNV', '撒母耳记下', 10, 23, 1, '以下是大卫末了的话：“耶西的儿子大卫的宣告，被高举的人的宣告。大卫是雅各的神所膏立的，是以色列美妙的诗人。'),
('CNV', '撒母耳记下', 10, 23, 2, '耶和华的灵藉着我说话，他的话在我的舌头上。'),
('CNV', '撒母耳记下', 10, 23, 3, '以色列的神说，以色列的磐石告诉我：那以公义统治人的，那存敬畏神的心施行统治的，'),
('CNV', '撒母耳记下', 10, 23, 4, '他必像旭日升起的光芒，像无云的早晨，像雨后的晴朗，使地长出绿草。'),
('CNV', '撒母耳记下', 10, 23, 5, '我的家在神面前不是这样吗？他与我立了永远的约；这约安排了一切，稳固妥当。我的一切救恩、一切愿望，他不都成全吗？'),
('CNV', '撒母耳记下', 10, 23, 6, '流氓却像荆棘被丢弃，人不敢用手拿它。'),
('CNV', '撒母耳记下', 10, 23, 7, '人要碰它，必须带备铁器和枪杆，他们要在原地被火彻底烧毁。”'),
('CNV', '撒母耳记下', 10, 23, 8, '以下是大卫勇士的名字：他革扪人约设‧巴设，是军官的首领，又称为伊斯尼人亚底挪。他曾在一次战役中杀死了八百人。'),
('CNV', '撒母耳记下', 10, 23, 9, '其次是亚合人朵多的儿子以利亚撒。从前非利士人在巴斯达闵聚集要争战，与大卫一同去向他们骂阵的三个勇士，其中之一就是以利亚撒；那时以色列人向上撤退，'),
('CNV', '撒母耳记下', 10, 23, 10, '他却起来，击杀非利士人，直到他的手疲乏无力，紧贴在刀把上。那一天耶和华使以色列人获得了大胜利。众人转到以利亚撒后面，只顾剥夺死者的财物。'),
('CNV', '撒母耳记下', 10, 23, 11, '再其次是哈拉人亚基的儿子沙玛。非利士人聚集在利希，那里有一块田地长满了红豆，众人都从非利士人面前逃走。'),
('CNV', '撒母耳记下', 10, 23, 12, '沙玛却在那块田中间站稳脚步，保护了那块田，又击杀了非利士人。耶和华又使以色列人获得了大胜利。'),
('CNV', '撒母耳记下', 10, 23, 13, '收割的时候，三十个首领中有三个人下到亚杜兰洞那里去见大卫；有一队非利士人在利乏音谷安营。'),
('CNV', '撒母耳记下', 10, 23, 14, '那时大卫在山寨中，非利士人的驻军却在伯利恒。'),
('CNV', '撒母耳记下', 10, 23, 15, '大卫渴望说：“但愿有人把伯利恒城门旁边井里的水拿来给我喝！”'),
('CNV', '撒母耳记下', 10, 23, 16, '那三个勇士就闯过非利士人的营地，从伯利恒城门旁边的井里打水，把水取上来，带到大卫那里。大卫不肯喝，却把水浇奠在耶和华面前。'),
('CNV', '撒母耳记下', 10, 23, 17, '大卫说：“耶和华啊！我绝对不可作这事。这三个人冒着生命危险去打水，这水不是他们的血吗？”因此大卫不肯喝那水。这些是那三个勇士所作的事。'),
('CNV', '撒母耳记下', 10, 23, 18, '洗鲁雅的儿子约押的兄弟亚比筛是三十勇士的首领。他曾挥舞矛枪杀死了三百人，因此他与“三勇士”齐名。'),
('CNV', '撒母耳记下', 10, 23, 19, '他的荣誉比那“三十勇士”高，所以成为他们的领袖；不过，却不及“三勇士”。'),
('CNV', '撒母耳记下', 10, 23, 20, '甲薛人耶何耶大的儿子比拿雅，是一个力气很大的人，作过许多大事。他曾经击杀了摩押人的两个勇将；又在下雪的时候，下到坑里去击杀了一只狮子。'),
('CNV', '撒母耳记下', 10, 23, 21, '他还击杀了一个体格高大的埃及人。这埃及人手里有矛，比拿雅只拿着棍子下去与他对抗；结果他把埃及人手中的矛枪夺了过来，用那矛枪杀死他。'),
('CNV', '撒母耳记下', 10, 23, 22, '这些是耶何耶大的儿子比拿雅所作的事。他与“三勇士”齐名。'),
('CNV', '撒母耳记下', 10, 23, 23, '他的荣誉比那“三十勇士”高，不过，却不及“三勇士”。大卫立他作侍卫长。'),
('CNV', '撒母耳记下', 10, 23, 24, '三十个勇士中有约押的兄弟亚撒黑、伯利恒人朵多的儿子伊勒哈难、'),
('CNV', '撒母耳记下', 10, 23, 25, '哈律人沙玛、哈律人以利加、'),
('CNV', '撒母耳记下', 10, 23, 26, '帕勒提人希利斯、提哥亚人益吉的儿子以拉、'),
('CNV', '撒母耳记下', 10, 23, 27, '亚拿突人亚比以谢、户沙人米本乃、'),
('CNV', '撒母耳记下', 10, 23, 28, '亚合人撒门、尼陀法人玛哈莱、'),
('CNV', '撒母耳记下', 10, 23, 29, '尼陀法人巴拿的儿子希立、便雅悯子孙基比亚人利拜的儿子以太、'),
('CNV', '撒母耳记下', 10, 23, 30, '比拉顿人比拿雅、迦实溪人希太、'),
('CNV', '撒母耳记下', 10, 23, 31, '伯‧亚拉巴人亚比亚本、巴鲁米人押斯玛弗、'),
('CNV', '撒母耳记下', 10, 23, 32, '沙本人以利雅哈巴、雅善的儿子约拿单、'),
('CNV', '撒母耳记下', 10, 23, 33, '哈拉人沙玛、哈拉人沙拉的儿子亚希暗、'),
('CNV', '撒母耳记下', 10, 23, 34, '玛迦人亚哈拜的儿子以利法列、基罗人亚希多弗的儿子以连、'),
('CNV', '撒母耳记下', 10, 23, 35, '迦密人希斯莱、亚巴人帕莱、'),
('CNV', '撒母耳记下', 10, 23, 36, '琐巴人拿单的儿子以申、迦得人巴尼、'),
('CNV', '撒母耳记下', 10, 23, 37, '亚扪人洗勒、比录人拿哈莱、'),
('CNV', '撒母耳记下', 10, 23, 38, '以帖人以拉、以帖人迦立、'),
('CNV', '撒母耳记下', 10, 23, 39, '赫人乌利亚，共有三十七人。'),
('CNV', '撒母耳记下', 10, 24, 1, '耶和华又向以色列人发怒，就激动大卫，使他们受害，说：“你去数点一下以色列和犹大的人数吧！”'),
('CNV', '撒母耳记下', 10, 24, 2, '王就对约押和跟随他的军官说：“你们走遍以色列各支派，从但到别是巴，数点人民，我好知道人民的数目。”'),
('CNV', '撒母耳记下', 10, 24, 3, '约押回答王：“无论人民有多少，愿耶和华你的神再增加一百倍，又愿我主我王亲眼看见。不过，我主我王为什么喜欢这事呢？”'),
('CNV', '撒母耳记下', 10, 24, 4, '但是王的命令约押和众军官不敢不从。于是约押和众军官从王面前出去，数点以色列的人民。'),
('CNV', '撒母耳记下', 10, 24, 5, '他们过了约旦河，就在谷中那座亚罗珥城的右边安营。后来他们经过迦得，直到雅谢，'),
('CNV', '撒母耳记下', 10, 24, 6, '然后又到了基列和他停‧合示地，再到了但‧雅安，并绕过了西顿，'),
('CNV', '撒母耳记下', 10, 24, 7, '来到推罗的堡垒，以及希未人和迦南人所有的城市。最后，他们出到犹大的南端别是巴去了。'),
('CNV', '撒母耳记下', 10, 24, 8, '以后，他们走遍了全地，过了九个月又二十天，就回到耶路撒冷。'),
('CNV', '撒母耳记下', 10, 24, 9, '约押把数点人民的数目向王呈报：在以色列中能拔刀的勇士共有八十万人；犹大共有五十万人。'),
('CNV', '撒母耳记下', 10, 24, 10, '大卫数点了人民以后，良心一直不安，于是对耶和华说：“我作了这事，犯了大罪。耶和华啊！现在求你除去你仆人的罪孽，因为我作了非常糊涂的事！”'),
('CNV', '撒母耳记下', 10, 24, 11, '大卫早晨起来；耶和华的话临到迦得先知，就是大卫的先见，说：'),
('CNV', '撒母耳记下', 10, 24, 12, '“你去告诉大卫说：‘耶和华这样说：我给你三个选择，你要选择一个，我好向你施行。’”'),
('CNV', '撒母耳记下', 10, 24, 13, '于是迦得来见大卫，问他说：“你要国中三年的饥荒呢？或是要在你敌人面前逃跑，被追赶三个月呢？或是要国中有三天的瘟疫呢？现在你要想想，决定我该用什么话回覆那差我来的。”'),
('CNV', '撒母耳记下', 10, 24, 14, '大卫对迦得说：“我非常为难，我们情愿落在耶和华的手里，因为他有丰盛的怜悯。不要让我落在人的手里。”'),
('CNV', '撒母耳记下', 10, 24, 15, '于是耶和华降瘟疫在以色列地，从早晨直到所定的时间；从但到别是巴，众民中死了七万人。'),
('CNV', '撒母耳记下', 10, 24, 16, '当天使向耶路撒冷伸手，要毁灭耶路撒冷的时候，耶和华就后悔降这灾祸，就对那毁灭众民的天使说：“够了，现在住手吧！”那时，耶和华的天使在耶布斯人亚劳拿的打禾场那里。'),
('CNV', '撒母耳记下', 10, 24, 17, '大卫看见那击杀人民的天使，就对耶和华说：“犯了罪的是我，行了恶的是我，这群羊又作了什么呢？求你的手攻击我和我的父家吧！”'),
('CNV', '撒母耳记下', 10, 24, 18, '那一天，迦得来见大卫，对他说：“你上去，在耶布斯人亚劳拿的打禾场那里，为耶和华立一座祭坛。”'),
('CNV', '撒母耳记下', 10, 24, 19, '大卫就照着迦得的话，正如耶和华所吩咐的，上去了。'),
('CNV', '撒母耳记下', 10, 24, 20, '亚劳拿往下观看，看见王和他的臣仆正朝着他这边走过来，就出去迎接，脸伏于地向王叩拜。'),
('CNV', '撒母耳记下', 10, 24, 21, '亚劳拿问：“我主我王为什么来到你仆人这里呢？”大卫回答：“是要向你买这打禾场，好为耶和华筑一座祭坛，使民间的瘟疫可以止住。”'),
('CNV', '撒母耳记下', 10, 24, 22, '亚劳拿对大卫说：“我主我王看什么好，就拿去献上吧！看哪，这里有牛可以作燔祭，打禾的器具和套牛的轭可以当柴烧。'),
('CNV', '撒母耳记下', 10, 24, 23, '王啊，这一切亚劳拿都奉给你。”亚劳拿又对王说：“愿耶和华你的神悦纳你！”'),
('CNV', '撒母耳记下', 10, 24, 24, '王回答亚劳拿：“不！我一定要按价钱向你买，我不要用白白得来的作燔祭献给耶和华我的神。”于是大卫用五百七十克银子，买下了那打禾场和牛。'),
('CNV', '撒母耳记下', 10, 24, 25, '于是大卫在那里为耶和华筑了一座坛，献上燔祭和平安祭。这样耶和华垂听了人们为那地的祷告，瘟疫就在以色列人中止住了。'),
('CNV', '列王纪上', 11, 1, 1, '大卫王老了，年事已高，他们虽用许多衣服盖着他，他仍不感到暖和。'),
('CNV', '列王纪上', 11, 1, 2, '所以他的臣仆对他说：“不如为我主我王寻找一个年轻的处女，使她侍候在王面前，照顾王，睡在王的怀中，好使我主我王得到暖和。”'),
('CNV', '列王纪上', 11, 1, 3, '于是他们在以色列全境寻找一个美貌的少女，结果找着了一个书念的女子亚比煞，就把她带到王面前。'),
('CNV', '列王纪上', 11, 1, 4, '这少女极其美丽。她照顾王，服事他，可是王没有与她发生过关系。'),
('CNV', '列王纪上', 11, 1, 5, '那时哈及的儿子亚多尼雅妄自尊大，说：“我必作王。”就为自己预备了战车、骑兵，又有五十人在他前面奔走。'),
('CNV', '列王纪上', 11, 1, 6, '他的父亲从来没有责难他说：“你为什么这样作呢？”他的容貌也很英俊，他是在押沙龙之后生的。'),
('CNV', '列王纪上', 11, 1, 7, '亚多尼雅与洗鲁雅的儿子约押和亚比亚他祭司商议以后，二人都答应支持他。'),
('CNV', '列王纪上', 11, 1, 8, '但撒督祭司、耶何耶大的儿子比拿雅，拿单先知、示每、利以和大卫的勇士都不拥护亚多尼雅。'),
('CNV', '列王纪上', 11, 1, 9, '有一天，亚多尼雅在隐．罗结旁边，琐希列的磐石那里，宰杀牛羊和肥畜，邀请他所有的兄弟，就是王的众子和所有作王的臣仆的犹大人，来参加筵席。'),
('CNV', '列王纪上', 11, 1, 10, '只是没有邀请拿单先知、比拿雅、众勇士和他的兄弟所罗门。'),
('CNV', '列王纪上', 11, 1, 11, '拿单对所罗门的母亲拔示巴说：“哈及的儿子亚多尼雅作了王，而我们的主大卫还不知道，你难道没有听见吗？'),
('CNV', '列王纪上', 11, 1, 12, '现在你来，我可以给你出一个主意，好救你的性命和你儿子所罗门的性命。'),
('CNV', '列王纪上', 11, 1, 13, '你进去见大卫王，对他说：‘我主我王，你不是曾经向婢女起誓，说：“你的儿子所罗门必接续我作王，他要坐在我的王位上”吗？现在为什么亚多尼雅作了王呢？’'),
('CNV', '列王纪上', 11, 1, 14, '你还在那里与王说话的时候，我会随后进来，证实你的话。”'),
('CNV', '列王纪上', 11, 1, 15, '于是拔示巴进到内室去见王。王很老了，书念的女子亚比煞正在服事王。'),
('CNV', '列王纪上', 11, 1, 16, '拔示巴向王俯伏叩拜，王问：“你要什么？”'),
('CNV', '列王纪上', 11, 1, 17, '她回答说：“我主啊，你曾经指着耶和华你的神向婢女起誓，说：‘你的儿子所罗门必接续我作王，他要坐在我的王位上’，'),
('CNV', '列王纪上', 11, 1, 18, '可是，现在亚多尼雅作了王了；而我主我王，你还不知道。'),
('CNV', '列王纪上', 11, 1, 19, '他宰杀了许多公牛、肥畜和羊，邀请了王所有的儿子、亚比亚他祭司和军队的元帅约押，却没有邀请王的仆人所罗门。'),
('CNV', '列王纪上', 11, 1, 20, '我主我王啊，现在以色列众人的眼睛都看着你，等你告诉他们谁要坐在我主我王的王位上，接续你作王。'),
('CNV', '列王纪上', 11, 1, 21, '否则，到我主我王与列祖同睡之后，我和我的儿子所罗门就要被算为罪人了。”'),
('CNV', '列王纪上', 11, 1, 22, '拔示巴还在与王说话的时候，拿单先知就进来了。'),
('CNV', '列王纪上', 11, 1, 23, '有人告诉王说：“拿单先知来了。”拿单来到王面前，向王叩拜。'),
('CNV', '列王纪上', 11, 1, 24, '拿单说：“我主我王啊，你曾说过：‘亚多尼雅要接续我作王，坐在我的王位上’吗？'),
('CNV', '列王纪上', 11, 1, 25, '今天他下去宰杀了许多公牛、肥畜和羊，又请了王所有的儿子、众军长和亚比亚他祭司。他们正在亚多尼雅面前又吃又喝，说：‘亚多尼雅王万岁。’'),
('CNV', '列王纪上', 11, 1, 26, '只有我，就是你的仆人，撒督祭司、耶何耶大的儿子比拿雅和你的仆人所罗门，他都没有邀请。'),
('CNV', '列王纪上', 11, 1, 27, '我主我王是不是作了这事，而你没有告诉你的众臣仆，谁要接续我主我王，坐你的王位呢？”'),
('CNV', '列王纪上', 11, 1, 28, '大卫回答说：“召拔示巴到我这里来。”于是拔示巴来到王面前，站在那里。'),
('CNV', '列王纪上', 11, 1, 29, '王就起誓说：“我指着曾经救我的性命脱离一切患难的永活的耶和华起誓，'),
('CNV', '列王纪上', 11, 1, 30, '我从前怎样指着耶和华以色列的神向你起誓，说：‘你的儿子所罗门必接续我作王，要坐在我的王位上’，我今天也必照样行。”'),
('CNV', '列王纪上', 11, 1, 31, '于是拔示巴面伏在地，向王叩拜，说：“愿我主大卫王万岁！”'),
('CNV', '列王纪上', 11, 1, 32, '大卫王又说：“召撒督祭司、拿单先知和耶何耶大的儿子比拿雅到我这里来。”他们都来到王面前。'),
('CNV', '列王纪上', 11, 1, 33, '王就对他们说：“你们要带着你们主人的仆人，使我的儿子所罗门骑上我的骡子，送他下到基训去。'),
('CNV', '列王纪上', 11, 1, 34, '在那里撒督祭司和拿单先知要膏立他作以色列的王。你们要吹角，说：‘所罗门王万岁！’'),
('CNV', '列王纪上', 11, 1, 35, '然后你们要跟随他上来；他要来坐在我的王位上；他要接续我作王。我已经立了他作以色列和犹大的统治者。”'),
('CNV', '列王纪上', 11, 1, 36, '耶何耶大的儿子比拿雅回答王说：“阿们！愿耶和华我主我王的神也是这样说。'),
('CNV', '列王纪上', 11, 1, 37, '耶和华怎样与我主我王同在，愿他也照样与所罗门同在，使他的王位，比我主大卫王的王位更伟大。”'),
('CNV', '列王纪上', 11, 1, 38, '于是撒督祭司、拿单先知和耶何耶大的儿子比拿雅，以及基利提人和比利提人都下去，使所罗门骑上大卫王的骡子，送他到基训去。'),
('CNV', '列王纪上', 11, 1, 39, '撒督祭司从帐幕里拿出那盛膏油的角，膏立所罗门；然后有人吹角，众民就说：“所罗门王万岁！”'),
('CNV', '列王纪上', 11, 1, 40, '众民都跟随他上去，吹着笛子，十分欢乐，以致大地也因他们的声音震裂。'),
('CNV', '列王纪上', 11, 1, 41, '亚多尼雅和所有与他在一起的宾客刚刚吃完了饭，听到这声音；约押听到角声，就说：“城里为什么有这样喧嚷的声音呢？”'),
('CNV', '列王纪上', 11, 1, 42, '他还在说话的时候，亚比亚他祭司的儿子约拿单来了。亚多尼雅对他说：“进来吧！你是个忠义的人，一定带来了好消息。”'),
('CNV', '列王纪上', 11, 1, 43, '约拿单对亚多尼雅说：“不好了，我们的主大卫王已经立了所罗门为王了。'),
('CNV', '列王纪上', 11, 1, 44, '王差派撒督祭司、拿单先知和耶何耶大的儿子比拿雅，以及基利提人和比利提人，与所罗门同去。他们使所罗门骑上王的骡子。'),
('CNV', '列王纪上', 11, 1, 45, '撒督祭司和拿单先知已经在基训膏立他作王。众人都从那里欢欢喜喜上路；你们听见的声音，就是城里的喧闹声。'),
('CNV', '列王纪上', 11, 1, 46, '不但所罗门已经坐在这王国的王位上，'),
('CNV', '列王纪上', 11, 1, 47, '而且王的臣仆也来为我们的主大卫王祝福说：‘愿你的神使所罗门的名声比你的更尊荣，使他的王位比你的更伟大。’王就在床上屈身下拜。'),
('CNV', '列王纪上', 11, 1, 48, '王又这样说：‘耶和华以色列的神是应当称颂的，因为他今天赐了一人坐在我的王位上，也使我亲眼看见这事。’”'),
('CNV', '列王纪上', 11, 1, 49, '亚多尼雅所有的宾客都惧怕，大家起身，各自逃走了。'),
('CNV', '列王纪上', 11, 1, 50, '亚多尼雅惧怕所罗门，就起来，去抓紧祭坛的角。'),
('CNV', '列王纪上', 11, 1, 51, '有人告诉所罗门说：“亚多尼雅惧怕所罗门王。他现在抓紧祭坛的角说：‘愿所罗门王今天向我起誓，决不会用刀杀死他的仆人。’”'),
('CNV', '列王纪上', 11, 1, 52, '所罗门说：“他若是作一个忠义的人，他的头发连一根也不会掉在地上；但在他身上若是发现有什么恶行，他必定死。”'),
('CNV', '列王纪上', 11, 1, 53, '于是所罗门派人去把亚多尼雅从祭坛上带下来。他来向所罗门叩拜；所罗门对他说：“回你的家去吧！”'),
('CNV', '列王纪上', 11, 2, 1, '大卫的死期近了，就嘱咐他的儿子所罗门说：'),
('CNV', '列王纪上', 11, 2, 2, '“我现在要走世人必走的路了，你当坚强作大丈夫，'),
('CNV', '列王纪上', 11, 2, 3, '谨守耶和华你神所吩咐的，遵行他的道，按摩西律法所写的，谨守他的律例、诫命、典章和法度；这样，无论你作什么，无论你往哪里去，都可以亨通。'),
('CNV', '列王纪上', 11, 2, 4, '这样，耶和华必坚立他所说有关我的话，说：‘如果你的子孙谨慎自己所行的，一心一意、诚诚实实行在我面前，就不断有人坐以色列的王位了。’'),
('CNV', '列王纪上', 11, 2, 5, '你也要知道洗鲁雅的儿子约押对我所行的，就是对以色列的两个元帅：尼珥的儿子押尼珥和益帖的儿子亚玛撒所行的。他杀了他们，在和平的时候流他们的血，像作战时一样，把战争的血染在他腰间所束的带子上和脚上所穿的鞋子上。'),
('CNV', '列王纪上', 11, 2, 6, '所以你要凭你的智慧而行，不要让他白发到老，平平安安下到阴间。'),
('CNV', '列王纪上', 11, 2, 7, '但是你要恩待基列人巴西莱的众子，使他们与你同席吃饭，因为我逃避你哥哥押沙龙的时候，他们拿食物来迎接我。'),
('CNV', '列王纪上', 11, 2, 8, '与你在一起的有巴户琳的便雅悯人基拉的儿子示每；我往玛哈念去的那天，他用狠毒的咒语咒骂我。后来他下到约旦河来迎接我的时候，我就指着耶和华向他起誓，说：‘我必不用刀杀死你。’'),
('CNV', '列王纪上', 11, 2, 9, '现在，你不要以他为无罪，你是个聪明人，你必知道该怎样待他，使他白发苍苍流血下到阴间。”'),
('CNV', '列王纪上', 11, 2, 10, '大卫与他的列祖同睡，葬在大卫城里。'),
('CNV', '列王纪上', 11, 2, 11, '大卫作以色列王四十年：在希伯仑作王七年；在耶路撒冷作王三十三年。'),
('CNV', '列王纪上', 11, 2, 12, '于是所罗门坐在他父亲的王位上，他的国非常稳固。'),
('CNV', '列王纪上', 11, 2, 13, '哈及的儿子亚多尼雅去见所罗门的母亲拔示巴，拔示巴问他：“你来是为和平吗？”他回答：“是为和平来的。”'),
('CNV', '列王纪上', 11, 2, 14, '他又说：“我有话对你说。”拔示巴说：“你说吧！”'),
('CNV', '列王纪上', 11, 2, 15, '亚多尼雅说：“你知道这国位原是我的，以色列众人都希望我作王；不料国位反归了我的弟弟，因为他得着国位是出于耶和华。'),
('CNV', '列王纪上', 11, 2, 16, '现在我有一事请求你，请你不要拒绝。”拔示巴对他说：“你说吧！”'),
('CNV', '列王纪上', 11, 2, 17, '他说：“求你向所罗门王说，请他把书念的女子亚比煞赐给我作妻子，因为他必不会拒绝你。”'),
('CNV', '列王纪上', 11, 2, 18, '拔示巴说：“好吧，我必为你向王请求。”'),
('CNV', '列王纪上', 11, 2, 19, '于是拔示巴去见所罗门王，为亚多尼雅的事向他请求。王起来迎接她，向她下拜，然后坐在自己的王座上，又吩咐人为王的母亲摆设一个座位；她就坐在王的右边。'),
('CNV', '列王纪上', 11, 2, 20, '拔示巴说：“我有一件小事求你，请不要拒绝我。”王对她说：“母亲，你说吧，我必不会拒绝你。”'),
('CNV', '列王纪上', 11, 2, 21, '拔示巴说：“请把书念的女子亚比煞赐给你哥哥亚多尼雅作妻子。”'),
('CNV', '列王纪上', 11, 2, 22, '所罗门王回答他母亲，说：“你为什么要为亚多尼雅求书念的女子亚比煞呢？你也可以为他求这个国位，因为他是我的哥哥，又有亚比亚他祭司和洗鲁雅的儿子约押拥护他。”'),
('CNV', '列王纪上', 11, 2, 23, '于是所罗门王指着耶和华起誓，说：“如果亚多尼雅不因说了这话而送命，愿神惩罚我，并且加倍惩罚我。'),
('CNV', '列王纪上', 11, 2, 24, '现在，我指着永活的耶和华─那位坚立了我，使我坐在我父亲大卫的王位上，又照他所应许，为我建立家室的─起誓，今天亚多尼雅必被处死！”'),
('CNV', '列王纪上', 11, 2, 25, '于是，所罗门王差派耶何耶大的儿子比拿雅去击杀亚多尼雅，他就死了。'),
('CNV', '列王纪上', 11, 2, 26, '王对亚比亚他祭司说：“你回亚拿突自己的田地去吧！你本来是该死的，但我今天不杀死你，因为你在我父亲大卫面前抬过主耶和华的约柜，又与我父亲同受一切苦难。”'),
('CNV', '列王纪上', 11, 2, 27, '所罗门就罢免了亚比亚他，不准他作耶和华的祭司，这样就应验了耶和华在示罗所说有关以利家的话。'),
('CNV', '列王纪上', 11, 2, 28, '约押虽然没有拥护过押沙龙，但曾拥护亚多尼雅；这消息传到约押那里，他就逃到耶和华的帐幕里去，抓紧祭坛的角。'),
('CNV', '列王纪上', 11, 2, 29, '有人告诉所罗门王约押逃到耶和华的帐幕里去了，现在就在祭坛的旁边。于是所罗门差派耶何耶大的儿子比拿雅去说：“你去把他杀死。”'),
('CNV', '列王纪上', 11, 2, 30, '比拿雅来到耶和华的帐幕那里，对约押说：“王这样吩咐说：‘你出来！’”约押说：“我不出去！我要死在这里。”于是比拿雅回覆王说：“约押这样说，他这样回答我。”'),
('CNV', '列王纪上', 11, 2, 31, '王对比拿雅说：“你照着约押的话行吧！杀死他，把他埋葬，好叫约押所流无辜人的血，从我和我父的家除去。'),
('CNV', '列王纪上', 11, 2, 32, '耶和华必使约押流无辜人的血的罪归到他自己头上，因为他击杀了两个比他又公义又良善的人，就是用刀杀了以色列的元帅尼珥的儿子押尼珥，和犹大的元帅益帖的儿子亚玛撒，这事我的父亲大卫一点都不知道。'),
('CNV', '列王纪上', 11, 2, 33, '愿流这二人的血的罪归到约押和他后裔的头上，直到永远；但大卫和他的后裔，他的家和他的国却要从耶和华那里得享平安，直到永远。”'),
('CNV', '列王纪上', 11, 2, 34, '于是耶何耶大的儿子比拿雅上去击杀他，把他杀死，葬在旷野约押自己的家中。'),
('CNV', '列王纪上', 11, 2, 35, '王任命耶何耶大的儿子比拿雅取代约押统领军队；又任命撒督祭司取代亚比亚他的职位。'),
('CNV', '列王纪上', 11, 2, 36, '王派人去把示每召来，对他说：“你要为自己在耶路撒冷建造一座房屋，住在那里，不可从那里出来到任何别的地方去。'),
('CNV', '列王纪上', 11, 2, 37, '你必须知道，你哪一天出来，越过汲沦溪，你哪一天就要死。你流人血的罪必归到你自己的头上。”'),
('CNV', '列王纪上', 11, 2, 38, '示每对王说：“这话很好，我主我王怎么说，你仆人就照着行。”于是示每在耶路撒冷住了很久。'),
('CNV', '列王纪上', 11, 2, 39, '三年以后，示每的两个仆人逃到迦特王玛迦的儿子亚吉那里。有人告诉示每说：“你的仆人在迦特。”'),
('CNV', '列王纪上', 11, 2, 40, '于是示每起来，预备好自己的骡子，就往迦特亚吉王那里去寻找他的仆人。示每去了，又把他的仆人从迦特带回来。'),
('CNV', '列王纪上', 11, 2, 41, '有人告诉所罗门示每离开耶路撒冷往迦特去，又回来了。'),
('CNV', '列王纪上', 11, 2, 42, '王就派人把示每召来，对他说：“我不是叫你指着耶和华起誓，并且警告你：‘你必须知道，你哪一天出去到任何别的地方，你哪一天就要死’吗？你也对我说过：‘这话很好，我必听从。’'),
('CNV', '列王纪上', 11, 2, 43, '现在你为什么不遵守你向耶和华所起的誓，和我吩咐你的命令呢？”'),
('CNV', '列王纪上', 11, 2, 44, '王又对示每说：“你自己知道你心里的一切恶事，就是你向我父亲大卫所行的；现在耶和华要把你的罪归到你的头上。'),
('CNV', '列王纪上', 11, 2, 45, '所罗门王却要蒙福，大卫的王位必在耶和华眼前得坚立，直到永远。”'),
('CNV', '列王纪上', 11, 2, 46, '于是王命令耶何耶大的儿子比拿雅，比拿雅就出去击杀示每，示每就死了。这样，所罗门就巩固了他的国。'),
('CNV', '列王纪上', 11, 3, 1, '所罗门与埃及王法老结亲，娶了法老的女儿，把她迎进大卫城，直等到他的王宫、耶和华的殿和耶路撒冷周围的城墙都建造完了。'),
('CNV', '列王纪上', 11, 3, 2, '不过在那些日子，人民仍然在邱坛上献祭，因为还没有为耶和华的名建造殿宇。'),
('CNV', '列王纪上', 11, 3, 3, '所罗门爱耶和华，遵行他父亲大卫的律例；只是他仍然在邱坛上宰杀和焚烧祭牲。'),
('CNV', '列王纪上', 11, 3, 4, '有一次，王到基遍去献祭，因为那里有极大的邱坛。所罗门在那祭坛上献上了一千燔祭。'),
('CNV', '列王纪上', 11, 3, 5, '那天晚上在基遍，耶和华在梦中向所罗门显现；神说：“你无论求什么，我必赐给你。”'),
('CNV', '列王纪上', 11, 3, 6, '所罗门说：“你仆人我父亲大卫以诚实、公义和正直的心在你面前行事为人，你就以极大的慈爱待他；你又为他存留这极大的慈爱，赐给他一个儿子坐在他的王位上，正如今日一样。'),
('CNV', '列王纪上', 11, 3, 7, '耶和华我的神啊，现在你使仆人接续我的父亲大卫作王，但我还年轻，不知道应当怎样处事。'),
('CNV', '列王纪上', 11, 3, 8, '仆人住在你拣选的子民中；这些子民很多，多得不能数算。'),
('CNV', '列王纪上', 11, 3, 9, '所以，求你赐给仆人一颗明辨的心，可以判断你的子民，能辨别是非，因为谁能判断你这众多的子民呢？”'),
('CNV', '列王纪上', 11, 3, 10, '所罗门因为求这些事，就蒙主的喜悦。'),
('CNV', '列王纪上', 11, 3, 11, '神对他说：“因为你求这事，不为自己求长寿，不为自己求财富，也不求你仇敌的性命，单单为自己求聪明可以明辨是非公平，'),
('CNV', '列王纪上', 11, 3, 12, '我就照着你所求的而行；赐给你一个智慧和明辨的心，在你以前没有人像你，在你以后也不会有人像你。'),
('CNV', '列王纪上', 11, 3, 13, '连你所没有求的，我也赐给你，就是财富、尊荣，以至你一生的年日，在列王之中没有一人能像你。'),
('CNV', '列王纪上', 11, 3, 14, '如果你遵行了我的道，谨守我的律例、诫命，正如你父亲大卫所行的，我就必延长你的寿数。”'),
('CNV', '列王纪上', 11, 3, 15, '所罗门醒来，原来是一个梦。于是他回到耶路撒冷，站在耶和华的约柜前，献上燔祭，又献上平安祭，也为他的众臣仆摆设筵席。'),
('CNV', '列王纪上', 11, 3, 16, '有一天，有两个作妓女的妇人来见王，站在他面前。'),
('CNV', '列王纪上', 11, 3, 17, '其中一个妇人说：“我主啊，我和这妇人同住；她与我在房子里的时候，我生了一个孩子。'),
('CNV', '列王纪上', 11, 3, 18, '我生了孩子以后的第三天，这妇人也生了一个孩子。我们都住在一起。除了我们两个人在房子里以外，再没有别人与我们一起在这房子里。'),
('CNV', '列王纪上', 11, 3, 19, '夜间，这妇人睡觉的时候，压死了她的孩子。'),
('CNV', '列王纪上', 11, 3, 20, '她却在半夜，趁着婢女睡着的时候，起来，从我身旁把儿子抱去，放在她的怀里；又把她死了的儿子放在我的怀里。'),
('CNV', '列王纪上', 11, 3, 21, '第二天早上我起来，要给我的儿子吃奶的时候，发觉他死了。那天早晨我再仔细察看，发觉他并不是我所生的儿子！”'),
('CNV', '列王纪上', 11, 3, 22, '那一个妇人说：“不！活的儿子是我的，死的儿子才是你的。”但这一个妇人说：“不！死的儿子是你的，活的儿子才是我的。”她们在王面前彼此争辩。'),
('CNV', '列王纪上', 11, 3, 23, '王说：“这个妇人说：‘活的儿子是我的，死的儿子才是你的’，那个妇人却说：‘不！死的儿子是你的，活的儿子才是我的。’”'),
('CNV', '列王纪上', 11, 3, 24, '王就吩咐：“给我拿一把刀来！”人就把刀带到王面前。'),
('CNV', '列王纪上', 11, 3, 25, '王说：“把活的孩子劈成两半，一半给这个妇人，一半给那个妇人。”'),
('CNV', '列王纪上', 11, 3, 26, '那活孩子的母亲因为爱子心切，就对王说：“我主啊，把那活的孩子给她吧，千万不可杀死他！”另一个妇人却说：“这孩子也不归我，也不归你，把他劈开吧！”'),
('CNV', '列王纪上', 11, 3, 27, '王回答说：“把活孩子给这个妇人，千万不可杀死他，这个妇人实在是他的母亲。”'),
('CNV', '列王纪上', 11, 3, 28, '以色列众人听见王判断的这案件，就都敬畏他，因为看见他心里有神的智慧，能够判案。'),
('CNV', '列王纪上', 11, 4, 1, '所罗门王作了全以色列的王。'),
('CNV', '列王纪上', 11, 4, 2, '以下这些人是他的官员：撒督的儿子亚撒利雅作祭司；'),
('CNV', '列王纪上', 11, 4, 3, '示沙的两个儿子以利何烈和亚希亚作书记；亚希律的儿子约沙法作史官；'),
('CNV', '列王纪上', 11, 4, 4, '耶何耶大的儿子比拿雅统领军队；撒督和亚比亚他作祭司；'),
('CNV', '列王纪上', 11, 4, 5, '拿单的儿子亚撒利雅作幕僚长；拿单的儿子撒布得作祭司，他也是王的朋友；'),
('CNV', '列王纪上', 11, 4, 6, '亚希煞作家宰；亚比大的儿子亚多尼兰掌管服劳役的人。'),
('CNV', '列王纪上', 11, 4, 7, '所罗门在全以色列立了十二个官员；他们为王和王家供应食物，每人每年供应一个月。'),
('CNV', '列王纪上', 11, 4, 8, '以下是他们的名字：便．户珥在以法莲山地；'),
('CNV', '列王纪上', 11, 4, 9, '便．底甲在玛迦斯、沙宾、伯．示麦、以伦和伯．哈南；'),
('CNV', '列王纪上', 11, 4, 10, '便．希悉在亚鲁泊，梭哥和希弗全地是属他管理的；'),
('CNV', '列王纪上', 11, 4, 11, '便．亚比拿达在拿法多珥全境，他娶了所罗门的女儿他法为妻；'),
('CNV', '列王纪上', 11, 4, 12, '亚希律的儿子巴拿在他纳、米吉多和那靠近撒利但、在耶斯列下边的伯．善全地，由伯．善到亚伯．米何拉，再到约克米暗之外；'),
('CNV', '列王纪上', 11, 4, 13, '便．基列在基列的拉末；玛拿西的子孙睚珥在基列的村落是属他的，巴珊的亚珥歌伯地的六十座有城墙和铜闩的大城也是属他的。'),
('CNV', '列王纪上', 11, 4, 14, '易多的儿子亚希拿达在玛哈念；'),
('CNV', '列王纪上', 11, 4, 15, '亚希玛斯在拿弗他利，他娶了所罗门的女儿巴实抹为妻；'),
('CNV', '列王纪上', 11, 4, 16, '户筛的儿子巴拿在亚设和亚录；'),
('CNV', '列王纪上', 11, 4, 17, '帕路亚的儿子约沙法在以萨迦；'),
('CNV', '列王纪上', 11, 4, 18, '以拉的儿子示每在便雅悯；'),
('CNV', '列王纪上', 11, 4, 19, '乌利的儿子基别在基列地，就是从前亚摩利王西宏和巴珊王噩之地。这地只有一个官员管理。'),
('CNV', '列王纪上', 11, 4, 20, '犹大人和以色列人很多，像海边的沙那样多；他们都吃喝、快乐。'),
('CNV', '列王纪上', 11, 4, 21, '所罗门统治列国，从大河到非利士地，直到埃及的边界。这些国家，在所罗门在世的日子，都向他进贡，服事他。'),
('CNV', '列王纪上', 11, 4, 22, '所罗门每天的食物是细面粉五千公升、粗面粉一万公升、'),
('CNV', '列王纪上', 11, 4, 23, '肥牛十头、草场的牛二十头、羊一百只，此外还有鹿、羚羊、狍子和肥禽。'),
('CNV', '列王纪上', 11, 4, 24, '因为所罗门统治大河西边，从提弗萨直到迦萨的全境和大河西边的列王，所以他的四境都平安无事。'),
('CNV', '列王纪上', 11, 4, 25, '所罗门在世的日子，犹大和以色列人从但到别是巴，都各在自己的葡萄树下和无花果树下安然居住。'),
('CNV', '列王纪上', 11, 4, 26, '所罗门有套车的马四万匹和骑兵一万二千人。'),
('CNV', '列王纪上', 11, 4, 27, '那些官员分别每月供应所罗门王和所有与所罗门王一同坐席的人的食物，从没有缺少。'),
('CNV', '列王纪上', 11, 4, 28, '他们也各按各的职分供给拉车的马和快马吃的大麦和干草，送到指定的地方。'),
('CNV', '列王纪上', 11, 4, 29, '神赐给所罗门智慧、极大的聪明和广大的心，好像海边的沙那样无限无量。'),
('CNV', '列王纪上', 11, 4, 30, '所罗门的智慧大过所有东方人的智慧，大过埃及人的一切智慧。'),
('CNV', '列王纪上', 11, 4, 31, '他比万人都有智慧，胜过以斯拉人以探和玛曷的三个儿子希幔、甲各、达大的智慧。他的名声传遍了四周列国。'),
('CNV', '列王纪上', 11, 4, 32, '他说了箴言三千句，他的诗歌有一千零五首；'),
('CNV', '列王纪上', 11, 4, 33, '他讲论草木，从黎巴嫩的香柏木到生长在墙上的牛膝草；他也讲论走兽、飞禽、爬行的动物和鱼类。'),
('CNV', '列王纪上', 11, 4, 34, '万族之中和地上列王之中，听闻所罗门的智慧的，都有人来听所罗门的智慧。'),
('CNV', '列王纪上', 11, 5, 1, '推罗王希兰听见以色列人膏立了所罗门接续他父亲作王，就派遣自己的臣仆来见所罗门；因为希兰一向爱大卫。'),
('CNV', '列王纪上', 11, 5, 2, '所罗门也派遣人去见希兰，说：'),
('CNV', '列王纪上', 11, 5, 3, '“你知道我的父亲大卫为了四周的战事，在耶和华使敌人都服在他的脚下以前，他不能为耶和华他的神的名建造殿宇。'),
('CNV', '列王纪上', 11, 5, 4, '但是，现在耶和华我的神使我四境太平，没有仇敌，也没有灾祸。'),
('CNV', '列王纪上', 11, 5, 5, '所以我有意要为耶和华我的神的名建造殿宇，正如耶和华曾对我的父亲大卫说：‘你的儿子，就是我要使他接续你坐在王位上的，要为我的名建造殿宇。’'),
('CNV', '列王纪上', 11, 5, 6, '现在请你命令人从黎巴嫩为我砍伐香柏木；我的仆人要与你的仆人一起工作；至于你的仆人的工资，我必按照你所说的付给你，因为你也知道，我们中间没有人像西顿人那样善于砍伐树木。”'),
('CNV', '列王纪上', 11, 5, 7, '希兰听见了所罗门的话，就十分欢喜，说：“今天耶和华是应当称颂的，因为他赐给了大卫一个有智慧的儿子治理这么众多的人民。”'),
('CNV', '列王纪上', 11, 5, 8, '于是希兰派遣人去见所罗门，说：“你派人来向我所传的消息，我都听到了。关于香柏木和松木的事，你心所愿的，我都照办。'),
('CNV', '列王纪上', 11, 5, 9, '我的仆人要把这些木材从黎巴嫩运下海中；我会把木材扎成木筏，从海上运到你指定我的地方去。我在那里把木材拆开，你就可以运走。你也要成全我的心愿，用粮食供应我家。”'),
('CNV', '列王纪上', 11, 5, 10, '于是希兰照所罗门所想要的，供给他香柏木和松木。'),
('CNV', '列王纪上', 11, 5, 11, '所罗门也给了希兰麦子四百万公升，纯油四十万公升，作为他家的食物。所罗门年年都这样供给希兰。'),
('CNV', '列王纪上', 11, 5, 12, '耶和华照着他应许所罗门的，把智慧赐给他。希兰与所罗门之间，彼此和平相处，二人互相立约。'),
('CNV', '列王纪上', 11, 5, 13, '所罗门从以色列众人中征召作苦工的人，这些作苦工的人共有三万，'),
('CNV', '列王纪上', 11, 5, 14, '派他们轮班上黎巴嫩山去，每月一万人；他们一个月在黎巴嫩山上，两个月在家里。管理这些作苦工的是亚多尼兰。'),
('CNV', '列王纪上', 11, 5, 15, '所罗门有七万个搬运重物的工人，有八万个在山上凿石的石匠。'),
('CNV', '列王纪上', 11, 5, 16, '除此以外，所罗门还有三千三百个监管工作的官长，管理作工的人民。'),
('CNV', '列王纪上', 11, 5, 17, '王下令，人就开凿出又大又贵重的石头，用凿好的石头作殿的地基。'),
('CNV', '列王纪上', 11, 5, 18, '所罗门的工匠、希兰的工匠和迦巴勒人把石头凿好，又预备建造殿宇用的木料和石料。'),
('CNV', '列王纪上', 11, 6, 1, '以色列人出埃及地以后四百八十年，所罗门作以色列王的第四年西弗月，就是二月，他动工建造耶和华的殿。'),
('CNV', '列王纪上', 11, 6, 2, '所罗门为耶和华所建的殿，长二十七公尺，宽九公尺，高十三公尺半。'),
('CNV', '列王纪上', 11, 6, 3, '殿的前廊长九公尺，和殿的宽度一样，宽四公尺半。'),
('CNV', '列王纪上', 11, 6, 4, '又为殿做了窗架子内宽外窄的窗户。'),
('CNV', '列王纪上', 11, 6, 5, '紧靠殿墙，就是围着外殿和内殿的墙，他又建造平台，围绕殿的四周，做成厢房。'),
('CNV', '列王纪上', 11, 6, 6, '厢房的下层宽两公尺两公寸；中层宽两公尺七公寸；第三层宽三公尺一公寸。他在殿墙外面四周留有暗架，所以梁木不必插入殿墙里。'),
('CNV', '列王纪上', 11, 6, 7, '建殿是用采石场预备好了的石料；所以建殿的时候，在殿里听不到锤子、斧头或任何铁器的声音。'),
('CNV', '列王纪上', 11, 6, 8, '厢房的下层门在殿的右边，人可以从螺旋形梯子上厢房的中层，再从中层上到第三层。'),
('CNV', '列王纪上', 11, 6, 9, '所罗门建殿，建造完成以后，就用香柏木的栋梁和香柏木的木板做殿的天花板。'),
('CNV', '列王纪上', 11, 6, 10, '靠着圣殿所建的厢房，每层高两公尺两公寸，都用香柏木的梁木与殿连接。'),
('CNV', '列王纪上', 11, 6, 11, '耶和华的话临到所罗门说：'),
('CNV', '列王纪上', 11, 6, 12, '“关于你正在建造的这殿，如果你遵行我的律例，实行我的典章，谨守我的一切诫命，并且照着去行，我就必向你实现我应许你父亲大卫的话。'),
('CNV', '列王纪上', 11, 6, 13, '我必住在以色列人中间，也必不离弃我的子民以色列。”'),
('CNV', '列王纪上', 11, 6, 14, '所罗门建殿，并且建造完成。'),
('CNV', '列王纪上', 11, 6, 15, '殿内的墙壁，从地面到天花板，都贴上香柏木，殿内的地面，都铺上松木板。'),
('CNV', '列王纪上', 11, 6, 16, '又建内殿长九公尺，从地面到天花板，他用香柏木板隔开，成为至圣所。'),
('CNV', '列王纪上', 11, 6, 17, '内殿前面的外殿长十八公尺。'),
('CNV', '列王纪上', 11, 6, 18, '殿的内部都贴上香柏木，上面刻有匏瓜和初开的花朵，全部都是香柏木，一块石头都看不见。'),
('CNV', '列王纪上', 11, 6, 19, '他在殿中预备了内殿，好把耶和华的约柜安放在那里。'),
('CNV', '列王纪上', 11, 6, 20, '内殿长九公尺，宽九公尺，高九公尺；内部都贴上精金，用香柏木做的坛也贴上精金。'),
('CNV', '列王纪上', 11, 6, 21, '殿的内部所罗门都贴上精金，把金链挂在内殿的前面，内殿也都贴上精金。'),
('CNV', '列王纪上', 11, 6, 22, '他把整个的殿都贴上金子，直到整个的殿都贴完；在内殿的坛，整个都贴上了金子。'),
('CNV', '列王纪上', 11, 6, 23, '在内殿，他用橄榄木做了两个基路伯，各高四公尺四公寸。'),
('CNV', '列王纪上', 11, 6, 24, '第一个基路伯一边的翅膀长两公尺两公寸，另一边的翅膀也是两公尺两公寸；由这翅膀尖到那翅膀尖共有四公尺四公寸。'),
('CNV', '列王纪上', 11, 6, 25, '第二个基路伯的两个翅膀也是四公尺四公寸长。两个基路伯的大小和样式都是一样的。'),
('CNV', '列王纪上', 11, 6, 26, '第一个基路伯高四公尺四公寸，第二个基路伯也是一样。'),
('CNV', '列王纪上', 11, 6, 27, '他把两个基路伯安放在内殿里面，基路伯的翅膀是张开的；这一个基路伯的一个翅膀接到这边的墙壁，另一个基路伯的一个翅膀接到另一边的墙壁，他们另外的两个翅膀在殿的中间彼此相接。'),
('CNV', '列王纪上', 11, 6, 28, '他又把这两个基路伯贴上金子。'),
('CNV', '列王纪上', 11, 6, 29, '内殿和外殿周围的墙壁上，他都刻上基路伯、棕树和初开的花朵的雕刻。'),
('CNV', '列王纪上', 11, 6, 30, '内殿和外殿的地板上也都贴上金子。'),
('CNV', '列王纪上', 11, 6, 31, '内殿的入口，他用橄榄木做了门扇、门楣和五根门柱。'),
('CNV', '列王纪上', 11, 6, 32, '他在橄榄木做的两门上，雕刻上基路伯、棕树和初开的花朵。他又在基路伯和棕树上包上了金子。'),
('CNV', '列王纪上', 11, 6, 33, '他又照样为外殿的门，用橄榄木做了四根门柱。'),
('CNV', '列王纪上', 11, 6, 34, '用松木做的两扇门，这一扇有两叶，是叠合在一起的，那一扇也有两叶，也是叠合在一起的。'),
('CNV', '列王纪上', 11, 6, 35, '他又在上面刻上了基路伯、棕树和初开的花朵；又在雕刻上紧贴上金子。'),
('CNV', '列王纪上', 11, 6, 36, '他又用凿好了的石头三层，香柏木一层建造内院。'),
('CNV', '列王纪上', 11, 6, 37, '所罗门在位第四年西弗月，奠定了耶和华殿的根基。'),
('CNV', '列王纪上', 11, 6, 38, '第十一年布勒月，就是八月，圣殿各部分都按照计划完工了。所罗门共用了七年的时间建造圣殿。'),
('CNV', '列王纪上', 11, 7, 1, '所罗门为自己建造宫殿花了十三年才完成。'),
('CNV', '列王纪上', 11, 7, 2, '他又建造黎巴嫩林宫，长四十四公尺，宽二十二公尺，高十三公尺半。有四行香柏木的柱子，柱子上有香柏木的横梁。'),
('CNV', '列王纪上', 11, 7, 3, '柱子每行十五根，共四十五根；柱子上有厢房，是用香柏木盖屋顶的。'),
('CNV', '列王纪上', 11, 7, 4, '有窗框三行，窗与窗相对，共有三层。'),
('CNV', '列王纪上', 11, 7, 5, '所有的门和窗都有四方的框子，有窗三层，窗与窗相对。'),
('CNV', '列王纪上', 11, 7, 6, '他又建造柱廊，长二十二公尺，宽十三公尺半。在柱廊前有廊子，在廊子前又有柱子和台阶。'),
('CNV', '列王纪上', 11, 7, 7, '又建造王室座廊，就是审判廊，他在这里执行审判。由地板到天花板，都贴上香柏木板。'),
('CNV', '列王纪上', 11, 7, 8, '所罗门自己住的宫殿，是在廊后的另一个院内，建造法相同。他又为他娶法老的女儿建造一座宫院，建法与这廊子一样。'),
('CNV', '列王纪上', 11, 7, 9, '从根基到屋檐，从外院到大院，这一切都是用贵重的石块，按尺寸凿好，用锯子内外锯齐的石块建成的。'),
('CNV', '列王纪上', 11, 7, 10, '根基也都是用贵重的大石块；有长四公尺的，也有长三公尺半的。'),
('CNV', '列王纪上', 11, 7, 11, '上面有按着尺寸凿好的贵重石块和香柏木。'),
('CNV', '列王纪上', 11, 7, 12, '大院的周围有凿好的石头三层，香柏木一层，与耶和华的内院和殿廊一样。'),
('CNV', '列王纪上', 11, 7, 13, '所罗门王派人去把户兰从推罗接来。'),
('CNV', '列王纪上', 11, 7, 14, '户兰是拿弗他利支派中一个寡妇的儿子；他父亲是推罗人，是个铜匠。户兰满有智慧、聪明和知识，能作各样铜工；他来到所罗门王那里，作王的一切工作。'),
('CNV', '列王纪上', 11, 7, 15, '他铸造了两根铜柱，每根高八公尺，圆周五公尺三公寸。'),
('CNV', '列王纪上', 11, 7, 16, '他又用铜铸造了两个柱顶，安放在柱头上，每个柱顶高两公尺两公寸。'),
('CNV', '列王纪上', 11, 7, 17, '他又为柱头上的柱头顶做了两块网子和辫结成的链子，每个柱顶有七块。'),
('CNV', '列王纪上', 11, 7, 18, '他又做了两行石榴围绕在柱头上，柱顶的网子上，两个柱顶都是这样。'),
('CNV', '列王纪上', 11, 7, 19, '廊子里柱头上的柱顶，刻有百合花细工，一公尺八公寸。'),
('CNV', '列王纪上', 11, 7, 20, '两根柱子上柱顶的鼓肚上，网子旁边，各有石榴二百个，分两行环绕着。'),
('CNV', '列王纪上', 11, 7, 21, '他把这两根柱子竖立在殿廊的前面。竖立在南边的柱子，他起名叫雅斤；竖立在北面的柱子，起名叫波阿斯。'),
('CNV', '列王纪上', 11, 7, 22, '在柱子的上头刻有百合花的细工。这样，做柱子的工作就完成了。'),
('CNV', '列王纪上', 11, 7, 23, '他又铸造了一座圆形的铜海，从这边到那边四公尺四公寸，高两公尺两公寸，圆周十三公尺两公寸。'),
('CNV', '列王纪上', 11, 7, 24, '在铜海边缘以下有匏瓜围绕着，每四十五公分十个。匏瓜共有两行，是铸造铜海的时候，一并铸造上去的。'),
('CNV', '列王纪上', 11, 7, 25, '铜海安放在十二头铜牛背上，三头向北，三头向西，三头向南，三头向东，铜海是在铜牛之上，牛尾都向内。'),
('CNV', '列王纪上', 11, 7, 26, '铜海厚七公分半，边缘好像杯子的边缘，又好像百合花蕾，能盛水四万公升。'),
('CNV', '列王纪上', 11, 7, 27, '他又做了十个铜盆座；每个长一公尺八公寸，宽一公尺八公寸，高一公尺三公寸。'),
('CNV', '列王纪上', 11, 7, 28, '盆座的做法是这样：盆座有数边，各边都连接在盆架中。'),
('CNV', '列王纪上', 11, 7, 29, '在盆架间的各边上，有狮子、牛和基路伯。盆架上有座，狮子和牛的上下都有花纹的浮雕。'),
('CNV', '列王纪上', 11, 7, 30, '每个盆座都有四个铜轮和铜轴，在盆座以下的四脚上有铸成的支架，各边都刻有花纹。'),
('CNV', '列王纪上', 11, 7, 31, '盆座的口从内缘到顶，高四十五公分。盆口作圆形，照盆架上那座的样式，直径六十六公分。盆口的边上也有雕刻，盆座的边是四方形，不是圆形的。'),
('CNV', '列王纪上', 11, 7, 32, '盆座的四个轮子是在盆边的下面，轮座与轴相接，每个轮子高六十六公分。'),
('CNV', '列王纪上', 11, 7, 33, '轮子的形状，好像车轮的做法，轮轴、轮辋、轮辐、轮毂都是铸成的。'),
('CNV', '列王纪上', 11, 7, 34, '每一个盆座的四角都有四个支架；支架是与盆座一块铸成的。'),
('CNV', '列王纪上', 11, 7, 35, '盆座顶上有一个圆圈，高二十二公分；在盆座顶的座的撑子和边缘是与座一块铸成的。'),
('CNV', '列王纪上', 11, 7, 36, '又在撑子和边缘的上面刻有基路伯、狮子和棕树，又在各空处，周围刻上花纹。'),
('CNV', '列王纪上', 11, 7, 37, '他这样做了十个盆座，铸法、尺寸和样式都是相同的。'),
('CNV', '列王纪上', 11, 7, 38, '他又做了十个铜盆，每个铜盆能盛水八百公升；每个铜盆的直径都是一公尺八公寸。在十个盆座上，每个都安放一个铜盆。'),
('CNV', '列王纪上', 11, 7, 39, '他把五个盆座放在殿的南边，五个放在殿的北边，又把铜海放在殿的南边，就是靠东南角的地方。'),
('CNV', '列王纪上', 11, 7, 40, '户兰又做了盆子、铲子和碗。这样，户兰为所罗门王完成了在耶和华的殿里所要作的一切工程。'),
('CNV', '列王纪上', 11, 7, 41, '所做的就是两根柱子和在柱子顶上碗形的柱顶；两块遮盖柱子顶上碗形柱顶的网子；'),
('CNV', '列王纪上', 11, 7, 42, '在两块网子上的四百个石榴，每块网子上有两行石榴，遮盖在柱子上头两个碗形的柱顶；'),
('CNV', '列王纪上', 11, 7, 43, '十个盆座和盆座上的十个铜盆；'),
('CNV', '列王纪上', 11, 7, 44, '一个铜海和铜海下的十二头铜牛；'),
('CNV', '列王纪上', 11, 7, 45, '锅、铲子和盘子。以上这一切器皿都是户兰为所罗门在耶和华的殿里用磨亮的铜做成的。'),
('CNV', '列王纪上', 11, 7, 46, '是王在约旦平原，在疏割与撒利但之间用泥模铸造的。'),
('CNV', '列王纪上', 11, 7, 47, '这一切器皿所罗门都没有称算过；由于数量太多，铜的重量也无法估计。'),
('CNV', '列王纪上', 11, 7, 48, '所罗门又做了耶和华殿里的一切器具，就是金坛和放陈设饼的桌子，'),
('CNV', '列王纪上', 11, 7, 49, '内殿前面的精金灯台，右边五行，左边五行；还有金花、金灯盏，'),
('CNV', '列王纪上', 11, 7, 50, '精金的碗盆、烛剪、盘子、调羹和火鼎，内殿至圣所的门框和外殿的门枢。'),
('CNV', '列王纪上', 11, 7, 51, '这样，所罗门为耶和华的殿所作的一切工程都完成了。所罗门把他父亲大卫分别为圣的金银和器皿，都运了来，存放在耶和华殿的库房里。'),
('CNV', '列王纪上', 11, 8, 1, '那时，所罗门把以色列的长老、各支派的首领和以色列的族长，都召集到耶路撒冷自己面前，要把耶和华的约柜从大卫城，就是锡安运上来。'),
('CNV', '列王纪上', 11, 8, 2, '于是，在以他念月，就是七月，在守节期的时候，以色列众人都聚集到所罗门王那里。'),
('CNV', '列王纪上', 11, 8, 3, '以色列的众长老都来到了，祭司们就把约柜抬起来。'),
('CNV', '列王纪上', 11, 8, 4, '祭司和利未人把耶和华的约柜、会幕和会幕里的一切圣器具都运上来。'),
('CNV', '列王纪上', 11, 8, 5, '所罗门王和聚集到他那里的以色列全体会众，都一同在约柜前献牛羊为祭，数目多得不可胜数，无法计算。'),
('CNV', '列王纪上', 11, 8, 6, '祭司把耶和华的约柜抬进内殿为它预备的地方，就是至圣所，放在两个基路伯的翅膀底下。'),
('CNV', '列王纪上', 11, 8, 7, '因为基路伯展开翅膀在约柜所在地的上面，遮掩约柜和抬柜的杠。'),
('CNV', '列王纪上', 11, 8, 8, '这些杠很长，在内殿前的圣所可以看见杠头，在殿外却看不见；直到今日，这些杠还在那里。'),
('CNV', '列王纪上', 11, 8, 9, '约柜里面只有两块石版，这两块石版在以色列人出埃及地以后，耶和华与他们立约的时候，摩西在何烈山放在那里的。'),
('CNV', '列王纪上', 11, 8, 10, '祭司从圣所里出来的时候，有云彩充满耶和华的殿，'),
('CNV', '列王纪上', 11, 8, 11, '因为云彩的缘故，祭司不能站立服事，因为耶和华的荣光充满了圣殿。'),
('CNV', '列王纪上', 11, 8, 12, '那时，所罗门说：“耶和华曾说，他要住在密云中。'),
('CNV', '列王纪上', 11, 8, 13, '现在我果然为你建造了一座巍峨的殿，作你永远的居所。”'),
('CNV', '列王纪上', 11, 8, 14, '于是王把脸转过来，为全体以色列会众祝福，全体以色列会众都站着。'),
('CNV', '列王纪上', 11, 8, 15, '所罗门说：“耶和华以色列的神是应当称颂的，因为他亲口对我父亲大卫应许过的，现在他亲手成全了。他说：'),
('CNV', '列王纪上', 11, 8, 16, '‘自从我把我的子民以色列领出埃及的日子以来，我未曾在以色列的各支派中拣选一座城，建造殿宇，作我名的居所；但我拣选了大卫治理我的子民以色列。’'),
('CNV', '列王纪上', 11, 8, 17, '我父大卫心里有意要为耶和华以色列的神的名建殿。'),
('CNV', '列王纪上', 11, 8, 18, '但耶和华对我父大卫说：‘你心里有意为我的名建一座殿，你这心意是好的。'),
('CNV', '列王纪上', 11, 8, 19, '然而你不要建造这殿，只有你亲生的儿子，他必为我的名建造这殿。’'),
('CNV', '列王纪上', 11, 8, 20, '现在耶和华已经实现了他说过的话，我已经起来继承我父大卫，坐在以色列的王位上，正如耶和华所说过的。我也已经为耶和华以色列的神的名建造了这殿。'),
('CNV', '列王纪上', 11, 8, 21, '我又为约柜预备了一个地方。这约柜里有耶和华的约，就是他领我们列祖出埃及地的时候与他们所立的。”'),
('CNV', '列王纪上', 11, 8, 22, '所罗门当着以色列的全体会众，站在耶和华的祭坛前，向天伸开双手，'),
('CNV', '列王纪上', 11, 8, 23, '祷告说：“耶和华以色列的神啊，天上地下没有别的神像你；你对一心在你面前行事为人的仆人守约施慈爱。'),
('CNV', '列王纪上', 11, 8, 24, '你谨守了你应许过你仆人我父大卫的话。你亲口说过，也亲手作成，正如今天一样。'),
('CNV', '列王纪上', 11, 8, 25, '耶和华以色列的神啊，现在求你谨守你应许你仆人我父亲大卫的话：‘只要你的子孙谨守他们的行为，像你在我面前所行的一样，就必不断有人坐以色列的王位。’'),
('CNV', '列王纪上', 11, 8, 26, '以色列的神啊，现在求你成就你应许你仆人我父大卫的话吧！'),
('CNV', '列王纪上', 11, 8, 27, '“神真的住在地上吗？看哪！天和天上的天尚且不能容纳你，何况我建造的这殿呢？'),
('CNV', '列王纪上', 11, 8, 28, '然而耶和华我的神啊，求你垂顾你仆人的祷告和恳求，垂听你仆人今天在你面前所作的呼吁和祷告。'),
('CNV', '列王纪上', 11, 8, 29, '愿你的眼睛昼夜看顾这殿，看顾你所说‘我的名要留在那里’的地方。愿你垂听你仆人向这地方所发的祷告。'),
('CNV', '列王纪上', 11, 8, 30, '你仆人和你的子民以色列向这地方祷告的时候，求你垂听他们的恳求。求你在天上的居所垂听，垂听而赦免。'),
('CNV', '列王纪上', 11, 8, 31, '“如果有人得罪他的邻居被迫起誓，他来到这殿在你的祭坛前起誓的时候，'),
('CNV', '列王纪上', 11, 8, 32, '求你在天上垂听，采取行动，审判你的仆人，定恶人有罪，使他所行的，都归到他自己的头上。定义人有理，照着他的公义赏赐他。'),
('CNV', '列王纪上', 11, 8, 33, '“你的子民以色列若是得罪了你，以致在仇敌面前被打败，又回转归向你，承认你的名，在这殿里向你祷告恳求的时候，'),
('CNV', '列王纪上', 11, 8, 34, '求你在天上垂听，赦免你的子民以色列的罪，领他们返回你赐给他们列祖之地。'),
('CNV', '列王纪上', 11, 8, 35, '“如果他们因为得罪了你，天就闭塞不下雨；他们若是向这地方祷告，承认你的名；又因你苦待他们，就离开他们的罪，'),
('CNV', '列王纪上', 11, 8, 36, '求你在天上垂听，赦免你仆人和你的子民以色列的罪，指示他们当行的善道，赐雨水在你的地上，就是你赐给你子民的产业之地。'),
('CNV', '列王纪上', 11, 8, 37, '“如果这地有饥荒、瘟疫、旱风、霉烂、蝗虫、蚂蚱，或有仇敌把他们围困在城里，无论遭遇什么灾祸，什么疾病，'),
('CNV', '列王纪上', 11, 8, 38, '你的子民以色列，或是众人，或是个人，知道自己心里的苦痛，向这殿伸开双手所作的一切祷告、一切恳求，'),
('CNV', '列王纪上', 11, 8, 39, '求你在天上你的居所垂听而赦免，并且采取行动。你是知道人心的，只有你知道万人的心，求你照着各人所行的报应他，'),
('CNV', '列王纪上', 11, 8, 40, '好使他们在你赐给我们列祖的地上，一生一世敬畏你。'),
('CNV', '列王纪上', 11, 8, 41, '“至于不属于你的子民以色列的外族人，为了你的名的缘故从远地而来，'),
('CNV', '列王纪上', 11, 8, 42, '因为他们听到你的大名、大能的手和伸出来的膀臂，他们来向这殿祷告的时候，'),
('CNV', '列王纪上', 11, 8, 43, '求你在天上你的居所垂听，照着外族人向你呼求的一切而行，好使地上的万族万民都认识你的名，敬畏你，像你的子民以色列一样；又使他们知道我建造的这殿是称为你的名下的。'),
('CNV', '列王纪上', 11, 8, 44, '“如果你的子民出去与仇敌争战，无论你派他们到哪处，他们若是向你所拣选的这城，并向我为你的名建造的这殿祷告，'),
('CNV', '列王纪上', 11, 8, 45, '求你在天上垂听他们的祷告和恳求，为他们主持公道。'),
('CNV', '列王纪上', 11, 8, 46, '“如果你的子民得罪了你，你向他们发怒，把他们交给仇敌，以致仇敌把他们掳到仇敌的地方，或是远或是近，'),
('CNV', '列王纪上', 11, 8, 47, '在被掳的地方，他们若是回心转意，在他们被掳去之地回转，向你祈求，说：‘我们犯了罪了；我们犯了过了，我们作了恶事。’'),
('CNV', '列王纪上', 11, 8, 48, '如果他们在俘掳他们的仇敌的地方，一心一意回转归向你，又向着你赐给他们列祖的地方，向你所拣选的这城，和我为你的名建造的这殿祷告，'),
('CNV', '列王纪上', 11, 8, 49, '求你在天上你的居所垂听他们的祷告和恳求，为他们主持公道。'),
('CNV', '列王纪上', 11, 8, 50, '赦免得罪了你的子民，又赦免他们冒犯你的一切过犯，使他们在掳他们的人面前蒙怜悯。'),
('CNV', '列王纪上', 11, 8, 51, '因为他们是你的子民、你的产业，是你从埃及、从铁炉中领出来的。'),
('CNV', '列王纪上', 11, 8, 52, '愿你睁开眼睛看顾你仆人的祈求，和你的子民以色列的祈求，他们向你呼求的，愿你都垂听。'),
('CNV', '列王纪上', 11, 8, 53, '主耶和华啊！因为你已经把他们从地上万族万民中分别出来，作自己的产业，正如你领我们的列祖出埃及的时候，藉着你的仆人摩西所应许的。”'),
('CNV', '列王纪上', 11, 8, 54, '所罗门在耶和华的祭坛前屈膝下跪，向天伸开双手，向耶和华献完了这一切祷告和恳求以后，就起来，'),
('CNV', '列王纪上', 11, 8, 55, '站着，大声给以色列的全体会众祝福，说：'),
('CNV', '列王纪上', 11, 8, 56, '“耶和华是应当称颂的。他照着自己一切所应许的，赐安息给他的子民以色列人。藉着他的仆人摩西所应许一切美好的话，一句都没有落空。'),
('CNV', '列王纪上', 11, 8, 57, '愿耶和华我们的神与我们同在，像与我们的列祖同在一样。愿他不离弃我们，也不撇下我们。'),
('CNV', '列王纪上', 11, 8, 58, '愿他使我们的心归向他，遵行他的一切道，谨守他吩咐我们列祖的诫命、律例和典章。'),
('CNV', '列王纪上', 11, 8, 59, '愿我在耶和华面前恳求的这些话，昼夜都不离耶和华我们的神，好使他天天为他仆人和他的子民以色列人主持公道，'),
('CNV', '列王纪上', 11, 8, 60, '使地上万族万民都知道耶和华是神，除他以外没有别的神。'),
('CNV', '列王纪上', 11, 8, 61, '所以你们的心要完全归给耶和华我们的神，遵行他的律例，谨守他的诫命，像今天一样。”'),
('CNV', '列王纪上', 11, 8, 62, '王和所有与他在一起的以色列人都在耶和华面前献祭。'),
('CNV', '列王纪上', 11, 8, 63, '所罗门向耶和华献平安祭，牛二万二千头，羊十二万只；这样，王和以色列众人为耶和华的殿举行了奉献典礼。'),
('CNV', '列王纪上', 11, 8, 64, '那一天，因为耶和华面前的铜祭坛太小，容不下燔祭、素祭和平安祭牲的脂肪，王就把耶和华殿前院子当中的地方分别为圣，在那里献燔祭、素祭和平安祭牲的脂肪。'),
('CNV', '列王纪上', 11, 8, 65, '那时所罗门与从哈马口直到埃及小河的以色列人，都在耶和华我们的神面前举行盛大的集会，守节七天，又七天，一共十四天。'),
('CNV', '列王纪上', 11, 8, 66, '到了第八天，王遣散了众人；众人都祝福过王以后，就高高兴兴地回自己的家去。他们因为看见耶和华向他仆人大卫和他子民以色列所施的一切恩惠，心中都感到欢喜。'),
('CNV', '列王纪上', 11, 9, 1, '所罗门建造完了耶和华的殿、王宫和所罗门渴想建造的一切以后，'),
('CNV', '列王纪上', 11, 9, 2, '耶和华就第二次向所罗门显现，像先前在基遍向他显现一样。'),
('CNV', '列王纪上', 11, 9, 3, '耶和华对他说：“你在我面前所作的祷告和恳求，我都已经听见了。你建造的这殿，我已经把它分别为圣，要使我的名永远留在那里；我的眼和我的心也必常在那里。'),
('CNV', '列王纪上', 11, 9, 4, '至于你，如果你像你父亲大卫那样，存诚实和正直的心在我面前行事为人，遵行我一切所吩咐你的，谨守我的律例和典章，'),
('CNV', '列王纪上', 11, 9, 5, '我就必坚固你统治以色列的国位，直到永远，正如我应许你父亲大卫说：‘你的子孙，总不断有人坐以色列的王位。'),
('CNV', '列王纪上', 11, 9, 6, '你们或是你们的子孙，若是转去不跟从我，不遵守我赐给你们的诫命和律例，去事奉别的神，敬拜他们，'),
('CNV', '列王纪上', 11, 9, 7, '我就必把以色列人从我赐给他们的这地上剪除，甚至为自己的名分别为圣的这殿，我也必从我面前把它丢弃不顾，使以色列人在万族中成为笑谈和讥笑的对象。'),
('CNV', '列王纪上', 11, 9, 8, '这殿必成为废墟，经过的人都必惊讶，取笑说：耶和华为什么向这地和这殿这样作啊？'),
('CNV', '列王纪上', 11, 9, 9, '人要回答说：是因为他们离弃了那把他们的列祖从埃及地领出来的耶和华他们的神，去亲近别的神，敬拜他们，事奉他们，因此耶和华使这一切灾祸临到他们。’”'),
('CNV', '列王纪上', 11, 9, 10, '所罗门用了二十年的时间来建造耶和华的殿和王宫这两座建筑物。'),
('CNV', '列王纪上', 11, 9, 11, '因为推罗王希兰曾照着所罗门所喜爱的，以香柏木、松木和金子帮助他，于是所罗门王把加利利地的二十座城给了希兰。'),
('CNV', '列王纪上', 11, 9, 12, '希兰从推罗出来，看看所罗门给他的这些城。他不喜欢这些城，'),
('CNV', '列王纪上', 11, 9, 13, '他说：“我的兄弟啊，这些就是你送给我的城吗？”于是他给这些城起名叫迦步勒，直到今日。'),
('CNV', '列王纪上', 11, 9, 14, '希兰送给所罗门约有四千公斤金子。'),
('CNV', '列王纪上', 11, 9, 15, '这是所罗门王征召服劳役的建筑耶和华的殿和他自己的王宫，以及米罗、耶路撒冷的城墙、夏琐、米吉多和基色的记录。'),
('CNV', '列王纪上', 11, 9, 16, '先前埃及王法老上来攻取基色，放火烧城，杀了住在城里的迦南人，把城送给自己的女儿、所罗门的妻子作嫁妆。'),
('CNV', '列王纪上', 11, 9, 17, '所以所罗门重建基色、下伯．和仑、'),
('CNV', '列王纪上', 11, 9, 18, '巴拉和在犹大地旷野里的他玛，'),
('CNV', '列王纪上', 11, 9, 19, '以及属于所罗门所有的一切积货城、屯车城、马兵城，与所罗门在耶路撒冷、黎巴嫩和他统治的各地他喜爱建造的。'),
('CNV', '列王纪上', 11, 9, 20, '所有亚摩利人、赫人、比利洗人、希未人和耶布斯人余下的人，他们不是以色列人。'),
('CNV', '列王纪上', 11, 9, 21, '他们的子孙仍然留在那地，以色列人不能灭绝他们。于是所罗门征召他们作苦工的奴仆，直到今日。'),
('CNV', '列王纪上', 11, 9, 22, '至于以色列人，所罗门却没有使他们作奴仆，而是作他的战士、臣仆、统领、军长、战车长和骑兵长。'),
('CNV', '列王纪上', 11, 9, 23, '所罗门有督工五百五十人，负责管理作工的人和监督工程。'),
('CNV', '列王纪上', 11, 9, 24, '法老的女儿从大卫城搬到所罗门为她建造的宫里以后，所罗门才重建米罗。'),
('CNV', '列王纪上', 11, 9, 25, '所罗门每年三次在他为耶和华建造的祭坛上献上燔祭和平安祭；又在耶和华面前的坛上烧香，这样，他完成了建殿的工程。'),
('CNV', '列王纪上', 11, 9, 26, '所罗门王又在以东地、红海边，靠近以禄的以旬．迦别，建造船队。'),
('CNV', '列王纪上', 11, 9, 27, '希兰派遣他船队的仆人，就是熟悉航海的船员，与所罗门的仆人一同航海。'),
('CNV', '列王纪上', 11, 9, 28, '他们到达了俄斐，从那里取得黄金约有一万四千公斤，运到所罗门王那里。'),
('CNV', '列王纪上', 11, 10, 1, '示巴女王听到所罗门因耶和华的名所得的名声，就来要用难题试试他。'),
('CNV', '列王纪上', 11, 10, 2, '她带着大批随员到耶路撒冷来，又有骆驼驮着香料、许多金子和宝石。她来到所罗门那里，就把她心里所有的难题都对他说出来。'),
('CNV', '列王纪上', 11, 10, 3, '所罗门把她所有的问题都给她解说明白，没有一件事难倒王，使王不能回答她的。'),
('CNV', '列王纪上', 11, 10, 4, '示巴女王看见所罗门的一切智慧和他建造的宫殿、'),
('CNV', '列王纪上', 11, 10, 5, '桌上的食物、臣仆的座位、仆人的侍候、他们的服饰、王的酒政和王在耶和华的殿献上的燔祭，就惊奇得不知所措。'),
('CNV', '列王纪上', 11, 10, 6, '于是她对王说：“我在本国听见有关你的事和你的智慧，原来都是真的；'),
('CNV', '列王纪上', 11, 10, 7, '以前我并不相信那些话，等到我来了，亲眼看见，才知道人告诉我的还不到一半；你的智慧和财富，超过我所听闻的。'),
('CNV', '列王纪上', 11, 10, 8, '属你的人是有福的，你的这些臣仆是有福的，他们常常侍立在你面前，聆听你的智慧。'),
('CNV', '列王纪上', 11, 10, 9, '耶和华你的神是应当称颂的！他喜悦你，使你坐在以色列的王位上；因为耶和华永远喜爱以色列，所以立你作王，要你秉行公义。”'),
('CNV', '列王纪上', 11, 10, 10, '于是示巴女王把约四千公斤金子、大批香料和宝石送给王；以后奉来的香料再也没有像示巴女王送给所罗门的那么多。'),
('CNV', '列王纪上', 11, 10, 11, '此外，从俄斐运金子来的希兰船队，又从俄斐运了大批檀香木和宝石来。'),
('CNV', '列王纪上', 11, 10, 12, '王用檀香木为耶和华的殿和王宫做栏杆，又为歌唱的做琴瑟。以后再也没有这样的檀香木运来，也没有人看见过，直到今日。'),
('CNV', '列王纪上', 11, 10, 13, '所罗门王照着示巴女王所愿所求的一切赐给她，另外又厚厚地馈赠她。于是女王和她的臣仆都返回本国去了。'),
('CNV', '列王纪上', 11, 10, 14, '所罗门每年收入的金子重两万三千公斤。'),
('CNV', '列王纪上', 11, 10, 15, '另外，还有从商人和行商的课税，阿拉伯诸王和国内省长的收入。'),
('CNV', '列王纪上', 11, 10, 16, '所罗门王用锤炼好的金子做了二百面大盾牌，每一面大盾牌用金子七公斤；'),
('CNV', '列王纪上', 11, 10, 17, '又用锤炼好的金子做了三百面小盾牌，每一面小盾牌用金子两公斤。王把这些盾牌都放在黎巴嫩林宫。'),
('CNV', '列王纪上', 11, 10, 18, '王又做了一个象牙大宝座，贴上了精金。'),
('CNV', '列王纪上', 11, 10, 19, '那宝座有六级台阶，宝座的后背有一个圆顶，座处的两旁有一个扶手。扶手的旁边各有一只狮子站立着。'),
('CNV', '列王纪上', 11, 10, 20, '在六级台阶上共有十二只狮子站着，左边一只，右边一只。在列国中都没有这样做过。'),
('CNV', '列王纪上', 11, 10, 21, '所罗门的一切饮器都是金子做的；黎巴嫩林宫里的一切器皿也都是精金做的，没有用银子做的；原来在所罗门王的时代，银子算不得什么。'),
('CNV', '列王纪上', 11, 10, 22, '因为王有他施船队与希兰船队一同在海上航行。他施船队三年一次运来金银、象牙、猿猴和孔雀。'),
('CNV', '列王纪上', 11, 10, 23, '所罗门王的财富和智慧，超过了世界上所有的君王。'),
('CNV', '列王纪上', 11, 10, 24, '世上所有的人都要求晋见所罗门，聆听神赋予他心中的智慧。'),
('CNV', '列王纪上', 11, 10, 25, '他们各人都带着自己的贡物而来，就是银器、金器、衣裳、军械、香料、马和骡等，年年都是这样。'),
('CNV', '列王纪上', 11, 10, 26, '所罗门聚集战车和骑兵，他有战车一千四百辆，骑兵一万二千人，安置在屯车城和耶路撒冷，就是与王在一起。'),
('CNV', '列王纪上', 11, 10, 27, '王在耶路撒冷使银子好像石头一样，使香柏木好像平原的桑树那么多。'),
('CNV', '列王纪上', 11, 10, 28, '所罗门的马是从埃及和古厄运出来的，是王的商人从古厄按着定价买来的。'),
('CNV', '列王纪上', 11, 10, 29, '从埃及运上来的车，每辆银子六千八百四十克，马每匹一千七百一十克。赫人众王和亚兰诸王也都是这样经他们的手买来的。'),
('CNV', '列王纪上', 11, 11, 1, '所罗门王除了法老的女儿以外，又宠爱许多外族女子，就是摩押女子、亚扪女子、以东女子、西顿女子和赫人女子等。'),
('CNV', '列王纪上', 11, 11, 2, '关于这些国家的人，耶和华曾经吩咐以色列人：“你们不可与他们往来通婚，否则他们必会引诱你们的心，去随从他们的神。”但所罗门深深爱恋这些女子。'),
('CNV', '列王纪上', 11, 11, 3, '所罗门有妃七百，都是公主；有嫔三百。他的妃嫔使他的心偏离了神。'),
('CNV', '列王纪上', 11, 11, 4, '所罗门年老的时候，他的妃嫔诱惑他的心偏离了神去随从别的神。他的心不像他的父亲大卫那样完全归于耶和华他的神。'),
('CNV', '列王纪上', 11, 11, 5, '因为所罗门随从西顿人的女神亚斯他录，和亚扪人可憎的偶像米勒公。'),
('CNV', '列王纪上', 11, 11, 6, '所罗门行耶和华看为恶的事，不效法他的父亲大卫完完全全跟从耶和华。'),
('CNV', '列王纪上', 11, 11, 7, '那时，所罗门为摩押人可憎的偶像基抹和亚扪人可憎的偶像摩洛，在耶路撒冷东面的山上建造邱坛。'),
('CNV', '列王纪上', 11, 11, 8, '他为他娶自外族的妃嫔都这样作；她们都向自己的神烧香献祭。'),
('CNV', '列王纪上', 11, 11, 9, '耶和华向所罗门发怒，因为他的心偏离了曾经两次向他显现的耶和华以色列的神。'),
('CNV', '列王纪上', 11, 11, 10, '耶和华为了这事曾经吩咐他，不可随从别的神，可是他没有遵守耶和华吩咐的。'),
('CNV', '列王纪上', 11, 11, 11, '耶和华对所罗门说：“你既然作了这事，不遵守我吩咐你的约和律例，我必夺去你的国，把国赐给你的一个臣子。'),
('CNV', '列王纪上', 11, 11, 12, '然而，为了你父亲大卫的缘故，我不会在你有生之日作这事，我要从你儿子的手中把国夺去。'),
('CNV', '列王纪上', 11, 11, 13, '只是我不把整个国家夺去，为了我的仆人大卫的缘故，又为了我所拣选的耶路撒冷的缘故，我要给你的儿子留下一个支派。”'),
('CNV', '列王纪上', 11, 11, 14, '于是耶和华兴起一个人敌挡所罗门，他是以东王的后裔以东人哈达。'),
('CNV', '列王纪上', 11, 11, 15, '从前大卫击败以东，元帅约押上去埋葬阵亡的人的时候，就把以东所有的男人都杀了。'),
('CNV', '列王纪上', 11, 11, 16, '约押和以色列人在那里住了六个月，直到把以东所有的男人都除灭了。'),
('CNV', '列王纪上', 11, 11, 17, '哈达与他父亲的几个以东臣仆一起逃往埃及，那时哈达还是一个小孩子。'),
('CNV', '列王纪上', 11, 11, 18, '他们从米甸动身，来到巴兰，又从巴兰带了几个人来到埃及，见埃及王法老。法老吩咐人给他一所房子，供应他粮食，又赐他一块田地。'),
('CNV', '列王纪上', 11, 11, 19, '哈达在法老面前十分蒙恩，以致法老把自己妻子的妹妹，就是王后答比匿的妹妹，赐给他作妻子。'),
('CNV', '列王纪上', 11, 11, 20, '答比匿的妹妹给他生了一个儿子，名叫基努拔。答比匿使他在法老的宫中长大，基努拔就与法老的众子一起住在法老的宫中。'),
('CNV', '列王纪上', 11, 11, 21, '后来哈达在埃及听说大卫已经与他的列祖同睡，元帅约押也死了，哈达就对法老说：“求你容我离去，我好回到本国去。”'),
('CNV', '列王纪上', 11, 11, 22, '法老问他：“你在我这里有什么欠缺，竟要回到你本国去呢？”他回答：“没有什么欠缺，只求你无论如何让我离开。”'),
('CNV', '列王纪上', 11, 11, 23, '神又兴起一个人敌挡所罗门，就是以利亚大的儿子利逊。他是从他主人琐巴王哈大底谢那里逃出来的。'),
('CNV', '列王纪上', 11, 11, 24, '大卫击杀琐巴人的时候，利逊招聚了一些人，自己作了这些土匪的领袖。他前往大马士革，住在那里，又在大马士革作王。'),
('CNV', '列王纪上', 11, 11, 25, '在所罗门一生的日子，利逊都敌挡以色列人。他恨恶以色列人，并且作了亚兰人的王。另外，哈达也不断为患。'),
('CNV', '列王纪上', 11, 11, 26, '所罗门王的臣仆，尼八的儿子耶罗波安也举手攻击王。他是洗利达的以法莲人，他母亲是个寡妇，名叫洗鲁雅。'),
('CNV', '列王纪上', 11, 11, 27, '他举手攻击王的情形是这样的：所罗门重建米罗，修补他父亲大卫城的破口；'),
('CNV', '列王纪上', 11, 11, 28, '耶罗波安这个人原是个有才干的人。所罗门见这个年轻人作事殷勤，就派他管理约瑟家的所有奴工。'),
('CNV', '列王纪上', 11, 11, 29, '有一次，耶罗波安从耶路撒冷出来，示罗人亚希雅先知在路上遇见他。亚希雅身上穿着一件新衣，那时田野里只有他们二人。'),
('CNV', '列王纪上', 11, 11, 30, '亚希雅拿着自己身上所穿的新衣，把它撕成十二片，'),
('CNV', '列王纪上', 11, 11, 31, '对耶罗波安说：“你拿十片去吧！因为耶和华以色列的神这样说：‘看哪，我必从所罗门的手里把国夺去，把十个支派赐给你。'),
('CNV', '列王纪上', 11, 11, 32, '但是为了我的仆人大卫和为了我从以色列众支派中所拣选的耶路撒冷的缘故，所罗门仍然可以拥有一个支派。'),
('CNV', '列王纪上', 11, 11, 33, '因为他们离弃了我，去敬拜西顿人的女神亚斯他录、摩押人的神基抹和亚扪人的神米勒公，没有遵行我的道，行我眼中看为正的事，谨守我的律例典章，像他的父亲大卫一样。'),
('CNV', '列王纪上', 11, 11, 34, '但是，我不会把整个国家从他的手里夺去，我必使他终身作人君，是因我所拣选的仆人大卫谨守了我的诫命律例的缘故。'),
('CNV', '列王纪上', 11, 11, 35, '我要从他儿子的手中把国夺去，赐给你十个支派。'),
('CNV', '列王纪上', 11, 11, 36, '至于所罗门的儿子，我要给他一个支派，好使我的仆人大卫在我所拣选立我名的城耶路撒冷，在我面前常常有灯光。'),
('CNV', '列王纪上', 11, 11, 37, '我要拣选你，使你可以照心里想望的去统治。你必作以色列的王。'),
('CNV', '列王纪上', 11, 11, 38, '你若是听从我吩咐你的一切，遵行我的道，行我看为正的事，谨守我的律例诫命，像我的仆人大卫所行的一样，我就与你同在，为你建立一个巩固的朝代，像我为大卫建立的一样，并且我要把以色列赐给你。'),
('CNV', '列王纪上', 11, 11, 39, '因此，我要使大卫的后裔遭受苦难，不过，却不是永远的。’”'),
('CNV', '列王纪上', 11, 11, 40, '于是所罗门想要杀死耶罗波安，耶罗波安却逃往埃及去，到了埃及王示撒那里，就留在埃及，直等到所罗门死了为止。'),
('CNV', '列王纪上', 11, 11, 41, '所罗门其余的事：他所行的和他的智慧，不是都写在《所罗门记》上吗？'),
('CNV', '列王纪上', 11, 11, 42, '所罗门在耶路撒冷作以色列众人的王共四十年。'),
('CNV', '列王纪上', 11, 11, 43, '所罗门与他的列祖同睡，埋葬在他父亲大卫的城里。他的儿子罗波安接续他作王。'),
('CNV', '列王纪上', 11, 12, 1, '罗波安往示剑去，因为以色列众人都到了示剑，要立他作王。'),
('CNV', '列王纪上', 11, 12, 2, '尼八的儿子耶罗波安那时因逃避所罗门的面，仍然住在埃及，他听见了这事。'),
('CNV', '列王纪上', 11, 12, 3, '以色列人就派遣人去请他来，于是耶罗波安和以色列全体会众都来见罗波安，告诉他说：'),
('CNV', '列王纪上', 11, 12, 4, '“你父亲加给我们的重担，现在求你减轻你父亲使我们作的苦工和加在我们背上的重担，我们就服事你。”'),
('CNV', '列王纪上', 11, 12, 5, '罗波安回答他们：“你们暂时回去，三天以后再来见我。”众民就离开了。'),
('CNV', '列王纪上', 11, 12, 6, '罗波安王请教他父亲所罗门在世的时候，侍立在他面前的长老说：“你们给我出个主意，我应该怎样回答这民呢？”'),
('CNV', '列王纪上', 11, 12, 7, '长老对他说：“今天如果王作这民的仆人，服事他们，用好话回答他们，他们就常作王的仆人。”'),
('CNV', '列王纪上', 11, 12, 8, '可是王拒绝了老年人给他出的主意，反去请教那些与他一起长大，侍立在他面前的年轻人，'),
('CNV', '列王纪上', 11, 12, 9, '问他们：“你们的主意怎样，我应该怎样回覆这民？他们对我说：‘请你减轻你父亲加在我们身上的重担。’”'),
('CNV', '列王纪上', 11, 12, 10, '那些与他一同长大的年轻人回答他：“这民对王说：‘你父亲加重我们的重担，现在求你减轻我们的重担。’你要这样回答他们：‘我的小指头比我父亲的腰还粗！'),
('CNV', '列王纪上', 11, 12, 11, '我父亲把一个重担加在你们身上，我要使你们负更重的重担；我父亲用鞭子责打你们，我要用蝎子鞭责打你们。’”'),
('CNV', '列王纪上', 11, 12, 12, '耶罗波安和众民，照王所说“三天以后再来见我”的那话，第三天来见罗波安。'),
('CNV', '列王纪上', 11, 12, 13, '王严厉地回答众人。他拒绝了老年人给他所出的主意，'),
('CNV', '列王纪上', 11, 12, 14, '却照着年轻人给他所出的主意，对他们说：“我父亲加重你们所负的重担，我要使你们负更重的重担；我父亲用鞭子责打你们，我要用蝎子鞭责打你们。”'),
('CNV', '列王纪上', 11, 12, 15, '王不肯听从民众的请求，因为这个转变是出于耶和华，为要应验他藉示罗人亚希雅对尼八的儿子耶罗波安所说的话。'),
('CNV', '列王纪上', 11, 12, 16, '以色列众人见王不肯听从他们的请求，就回答王说：“我们在大卫里面有什么分呢？我们在耶西的儿子里面也没有产业；以色列人哪，回你们自己的家去吧！大卫啊，照顾你自己的家吧！”于是以色列人都回自己的家去了。'),
('CNV', '列王纪上', 11, 12, 17, '不过住在犹大各城的以色列人，罗波安仍然作他们的王。'),
('CNV', '列王纪上', 11, 12, 18, '罗波安王差派掌管作苦工之人的亚多兰往以色列人那里去，以色列众人却用石头打死他。罗波安王急忙上车逃回耶路撒冷去了。'),
('CNV', '列王纪上', 11, 12, 19, '这样，以色列人背叛了大卫家，直到今日。'),
('CNV', '列王纪上', 11, 12, 20, '以色列众人听说耶罗波安回来了，就派人去请他到会众面前，立他作以色列的王；除了犹大支派以外，没有跟随大卫家的。'),
('CNV', '列王纪上', 11, 12, 21, '罗波安来到耶路撒冷，就召集了犹大全家和便雅悯支派精选的战士十八万人，要与以色列家争战，好把国夺回，重归所罗门的儿子罗波安。'),
('CNV', '列王纪上', 11, 12, 22, '但是，神的话临到神人示玛雅，说：'),
('CNV', '列王纪上', 11, 12, 23, '“你去告诉所罗门王的儿子犹大王罗波安、犹大全家和便雅悯，以及其余的人民，说：'),
('CNV', '列王纪上', 11, 12, 24, '‘耶和华这样说：你们不可上去，不可与你们的兄弟以色列人争战。你们各自回家去吧！因为这事是出于我。’”众人就听从了耶和华的话，照着耶和华的话回家去了。'),
('CNV', '列王纪上', 11, 12, 25, '耶罗波安在以法莲山地修筑了示剑城，就住在城中，又从那里出去，修建了毗努伊勒。'),
('CNV', '列王纪上', 11, 12, 26, '耶罗波安心里说：“现在这国仍然要归回大卫家。'),
('CNV', '列王纪上', 11, 12, 27, '这民若是上去，在耶路撒冷耶和华的殿里献祭，这民的心就必归向他们的主犹大王罗波安，他们必把我杀了，然后回到犹大王罗波安那里去。”'),
('CNV', '列王纪上', 11, 12, 28, '王打定了主意，就做了两个金牛犊，对众民说：“以色列人哪，你们上耶路撒冷去实在够了。看哪，这是你们的神，就是从埃及地领你们上来的那位。”'),
('CNV', '列王纪上', 11, 12, 29, '他就把一个牛犊安放在伯特利，一个安放在但。'),
('CNV', '列王纪上', 11, 12, 30, '这事成了以色列人的罪，因为众民都到但那个牛犊面前敬拜。'),
('CNV', '列王纪上', 11, 12, 31, '耶罗波安在邱坛那里建殿，把不是利未子孙的平民立为祭司。'),
('CNV', '列王纪上', 11, 12, 32, '耶罗波安又定了八月十五日为节期，像在犹大的节期一样，他自己在祭坛上献祭，他在伯特利也是这样向他所铸造的牛犊献祭；他又在伯特利为他所建造的邱坛设立祭司。'),
('CNV', '列王纪上', 11, 12, 33, '八月十五日，就是他心里私定作为以色列人节期的日子，他在伯特利在自己所建的祭坛上献祭烧香。'),
('CNV', '列王纪上', 11, 13, 1, '有一个神人，奉耶和华的命令，从犹大来到伯特利；那时，耶罗波安正站在祭坛旁边烧香。'),
('CNV', '列王纪上', 11, 13, 2, '神人奉耶和华的命令，向那祭坛喊叫，说：“祭坛哪，祭坛哪，耶和华这样说：‘看哪，大卫家要生一个儿子，名叫约西亚；他要把邱坛的祭司，就是在你上面烧香的，作祭物献在你上面。人的骨头也要在你上面焚烧。’”'),
('CNV', '列王纪上', 11, 13, 3, '那天，神人提出一个兆头，说：“这是耶和华所说的兆头。看哪，这祭坛必破裂，祭坛上的灰必倾撒下来。”'),
('CNV', '列王纪上', 11, 13, 4, '耶罗波安王听见神人向伯特利的祭坛喊叫的话，就从祭坛上伸手，说：“抓住他！”王向他伸出的手却瘫痪了，不能缩回来。'),
('CNV', '列王纪上', 11, 13, 5, '祭坛也破裂了，灰从祭坛上倾撒下来，好像神人奉耶和华的命令所提出的预兆一样。'),
('CNV', '列王纪上', 11, 13, 6, '王对神人说：“求你为我向耶和华你的神求情，又为我祷告，使我的手复原。”于是神人向耶和华求情，王的手就复了原，像起先一样。'),
('CNV', '列王纪上', 11, 13, 7, '王对神人说：“请与我一起回王宫去，吃点东西，加添心力，我还要赐给你一份礼物。”'),
('CNV', '列王纪上', 11, 13, 8, '神人对王说：“你就是把王宫的一半给我，我也不会与你回去，也不在这地方吃饭喝水。'),
('CNV', '列王纪上', 11, 13, 9, '因为有耶和华的话吩咐我说：‘你不可吃饭喝水，也不可从你去的原路回来。’”'),
('CNV', '列王纪上', 11, 13, 10, '于是神人从另一条路去了，没有从他来伯特利的原路回去。'),
('CNV', '列王纪上', 11, 13, 11, '有一个老先知住在伯特利，他的儿子们来告诉他，那一天神人在伯特利所行的一切事。他们也把他对王所说的话，都告诉了他们的父亲。'),
('CNV', '列王纪上', 11, 13, 12, '他们的父亲问他们：“神人从哪条路走了呢？”他的儿子们就把从犹大来的神人所走的路，指给他看。'),
('CNV', '列王纪上', 11, 13, 13, '他对儿子们说：“给我备驴！”于是他们给他备驴，他就骑上，'),
('CNV', '列王纪上', 11, 13, 14, '去追赶神人，遇见他正坐在橡树底下，就问他：“你是从犹大来的神人吗？”他回答：“是的！”'),
('CNV', '列王纪上', 11, 13, 15, '老先知对他说：“请你与我一起回家去吃饭。”'),
('CNV', '列王纪上', 11, 13, 16, '神人说：“我不能与你回去，或是与你同行，也不能与你在这地方吃饭喝水，'),
('CNV', '列王纪上', 11, 13, 17, '因为有耶和华的话对我说：‘你在那里不可吃饭喝水，也不可从你去的原路回来。’”')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '列王纪上', 11, 13, 18, '老先知对他说：“我也是先知，和你一样。有一位天使奉耶和华的命令告诉我说：‘你去带他与你一起回家，给他吃饭喝水。’”但是，老先知是欺骗他的。'),
('CNV', '列王纪上', 11, 13, 19, '于是神人与他一起回去，在他的家里吃饭喝水。'),
('CNV', '列王纪上', 11, 13, 20, '他们二人正在席上吃喝的时候，耶和华的话临到那把神人带回来的先知，'),
('CNV', '列王纪上', 11, 13, 21, '他就对那从犹大来的神人喊叫，说：“耶和华这样说：‘你既然违背了耶和华的命令，没有谨守耶和华你的神吩咐你的诫命，'),
('CNV', '列王纪上', 11, 13, 22, '反倒回来，在耶和华吩咐你不可吃饭喝水的地方，吃了饭喝了水，因此，你的尸体不能入葬你列祖的坟墓里。’”'),
('CNV', '列王纪上', 11, 13, 23, '吃了饭喝了水之后，老先知为他带回来的先知备驴。'),
('CNV', '列王纪上', 11, 13, 24, '他就去了；在路上有一只狮子遇见了他，就把他咬死了。他的尸体被丢在路上，驴子站在尸体旁边，狮子也站在尸体旁边。'),
('CNV', '列王纪上', 11, 13, 25, '有人从那里经过，看见尸体被丢在路上，狮子站在尸体旁边，就来到老先知所住的城里，述说这事。'),
('CNV', '列王纪上', 11, 13, 26, '那把神人从路上带回来的先知听见了这事，就说：“这是那违背了耶和华命令的神人；耶和华把他交给狮子，狮子就把他撕裂，咬死了他，正如耶和华对他说过的话。”'),
('CNV', '列王纪上', 11, 13, 27, '老先知又吩咐他的儿子们说：“给我备驴。”他们就备了驴。'),
('CNV', '列王纪上', 11, 13, 28, '于是他去了，看见神人的尸体被丢在路上，驴子和狮子都站在尸体旁边，那狮子并没有吃掉尸体，也没有撕裂驴子。'),
('CNV', '列王纪上', 11, 13, 29, '老先知把神人的尸体抱起来，放在驴子上，带回自己的城里，要为他举哀，要埋葬他。'),
('CNV', '列王纪上', 11, 13, 30, '老先知把他的尸体埋葬在自己的坟墓里；人们为他举哀，说：“哀哉，我兄啊！”'),
('CNV', '列王纪上', 11, 13, 31, '埋葬他以后，老先知就对儿子们说：“我死了以后，你们要把我埋葬在神人的坟墓里，把我的骸骨放在他的骸骨旁边。'),
('CNV', '列王纪上', 11, 13, 32, '因为他奉耶和华的命令，攻击伯特利的坛和在撒玛利亚各城邱坛上的殿所喊叫的话，必定应验。”'),
('CNV', '列王纪上', 11, 13, 33, '这事以后，耶罗波安还不从他的恶道转回，竟然把平民立为邱坛的祭司；愿意的，他都把他们分别为圣，立他们为邱坛的祭司。'),
('CNV', '列王纪上', 11, 13, 34, '这事成为耶罗波安的家的罪，以致他的家从地上被涂抹与除灭。'),
('CNV', '列王纪上', 11, 14, 1, '那时，耶罗波安的儿子亚比雅病了。'),
('CNV', '列王纪上', 11, 14, 2, '耶罗波安对他的妻子说：“你起来改装，使人认不出你是耶罗波安的妻子。到示罗去，有亚希雅先知在那里，他曾对我说，我必作这民的王。'),
('CNV', '列王纪上', 11, 14, 3, '你要带十个饼，一些饼干和一瓶蜜去见他，他会告诉你孩子将要怎样。”'),
('CNV', '列王纪上', 11, 14, 4, '耶罗波安的妻子就这样行了。她动身往示罗去，到了亚希雅的家；亚希雅因为年纪老迈，眼睛昏花，不能看见。'),
('CNV', '列王纪上', 11, 14, 5, '耶和华对亚希雅说：“看哪，耶罗波安的妻子要来向你求问关于她儿子的事，因为他病了。你要这样这样告诉她。她进来的时候，必装作别的妇人。”'),
('CNV', '列王纪上', 11, 14, 6, '她刚进门的时候，亚希雅就听见她的脚步声，就说：“耶罗波安的妻子啊！进来吧！你为什么要这样改装呢？我奉差派要把凶信告诉你。'),
('CNV', '列王纪上', 11, 14, 7, '你去告诉耶罗波安：‘耶和华以色列的神这样说：我从人民中提拔了你，又立了你作治理我的子民以色列的领袖。'),
('CNV', '列王纪上', 11, 14, 8, '我把国从大卫家夺过来，赏赐给你；你却不像我仆人大卫那样谨守我的诫命，一心跟从我，行我看为正的事。'),
('CNV', '列王纪上', 11, 14, 9, '你反倒行恶，比那些在你以前的更坏；又去为自己制造了别的神和铸造偶像惹我发怒，把我丢在背后。'),
('CNV', '列王纪上', 11, 14, 10, '因此，我必使灾祸临到耶罗波安的家；我必剪除以色列中所有属于耶罗波安的男丁，无论是自由的或是不自由的；我必铲除耶罗波安的家，像人扫除粪土一样，直到完全除尽为止。'),
('CNV', '列王纪上', 11, 14, 11, '属于耶罗波安的人，死在城里的，必被狗吃掉；死在田野的，必给空中的飞鸟吃掉。因为这是耶和华说的。’'),
('CNV', '列王纪上', 11, 14, 12, '所以你起来，回家去吧，你的脚一进城，你的孩子就必死亡。'),
('CNV', '列王纪上', 11, 14, 13, '以色列众人要为他举哀，把他埋葬；属耶罗波安的人中，只有他可以入葬坟墓；因为在耶罗波安的家中，只有他向耶和华以色列的神显出善行。'),
('CNV', '列王纪上', 11, 14, 14, '耶和华必为自己兴起一个王治理以色列，他必剪除耶罗波安家，今天就是时候了，就是现在！'),
('CNV', '列王纪上', 11, 14, 15, '耶和华必击打以色列人，他们就摆动，像芦苇在水中摆动一样。他要把以色列人从他赐给他们列祖的这块美地上拔出来，把他们分散在幼发拉底河那边，因为他们做了亚舍拉，惹耶和华发怒。'),
('CNV', '列王纪上', 11, 14, 16, '为了耶罗波安所犯的罪，又为了他使以色列人所犯的罪，耶和华必丢弃以色列人。”'),
('CNV', '列王纪上', 11, 14, 17, '耶罗波安的妻子动身离去，回到得撒；她一踏进门槛，孩子就死了。'),
('CNV', '列王纪上', 11, 14, 18, '以色列众人把他埋葬了，又为他举哀，好像耶和华藉着他的仆人亚希雅先知所说的话一样。'),
('CNV', '列王纪上', 11, 14, 19, '耶罗波安其余的事迹，他怎样争战，怎样作王，都写在以色列诸王的年代志上。'),
('CNV', '列王纪上', 11, 14, 20, '耶罗波安作王的日子共二十二年，就与他的列祖同睡。他的儿子拿答接续他作王。'),
('CNV', '列王纪上', 11, 14, 21, '所罗门的儿子罗波安在犹大作王。他登基的时候，是四十一岁；他在耶路撒冷，就是耶和华从以色列各支派中所拣选，在那里立他名的城，作王十七年。他的母亲名叫拿玛，是亚扪人。'),
('CNV', '列王纪上', 11, 14, 22, '犹大人行耶和华看为恶的事；他们所犯的罪，惹动他的妒忿比他们的列祖更厉害。'),
('CNV', '列王纪上', 11, 14, 23, '他们又为自己在各高冈上，各茂盛树下建造邱坛、神柱和亚舍拉。'),
('CNV', '列王纪上', 11, 14, 24, '国内又有男妓，他们仿效耶和华在以色列人面前所赶出的外族人，行了一切可憎的事。'),
('CNV', '列王纪上', 11, 14, 25, '罗波安王第五年，埃及王示撒上来攻打耶路撒冷。'),
('CNV', '列王纪上', 11, 14, 26, '他夺去了耶和华的宝物和王宫的宝物，并且把所有的东西都夺去了；又把所罗门所做的一切金盾牌都夺了去。'),
('CNV', '列王纪上', 11, 14, 27, '罗波安王做了铜盾牌代替那些金盾牌；交给看守宫门的卫兵队长看管。'),
('CNV', '列王纪上', 11, 14, 28, '王每次进耶和华殿的时候，卫兵就拿着这些盾牌，随后又把盾牌送回护卫室里。'),
('CNV', '列王纪上', 11, 14, 29, '罗波安其余的事迹和他所行的一切，不是都写在犹大列王的年代志上吗？'),
('CNV', '列王纪上', 11, 14, 30, '罗波安与耶罗波安之间常有战争。'),
('CNV', '列王纪上', 11, 14, 31, '罗波安与他的列祖同睡，与他的列祖一同埋葬在大卫的城里。他的母亲名叫拿玛，是亚扪人；他的儿子亚比央接续他作王。'),
('CNV', '列王纪上', 11, 15, 1, '尼八的儿子耶罗波安王第十八年，亚比央登基作犹大王。'),
('CNV', '列王纪上', 11, 15, 2, '他在耶路撒冷作王三年，他的母亲名叫玛迦，是押沙龙的女儿。'),
('CNV', '列王纪上', 11, 15, 3, '亚比央行他父亲在他以前所行的一切罪恶。他的心不完完全全归向耶和华他的神，像他先祖大卫的心一样。'),
('CNV', '列王纪上', 11, 15, 4, '然而，耶和华他的神却因大卫的缘故，使他在耶路撒冷仍然有灯光，兴起他的儿子接续他作王，并且坚立耶路撒冷。'),
('CNV', '列王纪上', 11, 15, 5, '因为除了赫人乌利亚那事以外，大卫都行耶和华看为正的事，一生之中从来没有偏离耶和华所吩咐他的一切。'),
('CNV', '列王纪上', 11, 15, 6, '亚比央一生的日子中，罗波安与耶罗波安之间常有战争。'),
('CNV', '列王纪上', 11, 15, 7, '亚比央其余的事迹和他所行的一切，不是都写在犹大列王的年代志上吗？亚比央与耶罗波安之间常有战争。'),
('CNV', '列王纪上', 11, 15, 8, '亚比央与他的列祖同睡，人们把他埋葬在大卫城里，他的儿子亚撒继承他作王。'),
('CNV', '列王纪上', 11, 15, 9, '以色列王耶罗波安第二十年，亚撒登基作犹大王。'),
('CNV', '列王纪上', 11, 15, 10, '他在耶路撒冷作王四十一年。他的祖母名叫玛迦，是押沙龙的女儿。'),
('CNV', '列王纪上', 11, 15, 11, '亚撒行耶和华看为正的事，像他祖大卫一样。'),
('CNV', '列王纪上', 11, 15, 12, '他从国中除去庙妓，又除掉他列祖所做的一切偶像。'),
('CNV', '列王纪上', 11, 15, 13, '并且废除他祖母玛迦太后的后位，因为她为亚舍拉做了可怕的偶像。亚撒把她那可怕的偶像砍下来，在汲沦溪旁烧掉。'),
('CNV', '列王纪上', 11, 15, 14, '只是邱坛还没有废去；不过亚撒一生都完完全全归向耶和华。'),
('CNV', '列王纪上', 11, 15, 15, '亚撒把他父亲所分别为圣和他自己所分别为圣的金银和器皿，都带到耶和华的殿里。'),
('CNV', '列王纪上', 11, 15, 16, '亚撒与以色列王巴沙在世的日子，双方常有战争。'),
('CNV', '列王纪上', 11, 15, 17, '以色列王巴沙上来攻击犹大，修筑拉玛，不准人进出到犹大王亚撒那里。'),
('CNV', '列王纪上', 11, 15, 18, '于是亚撒把耶和华殿和王宫的府库里所剩下的金银，都交在他臣仆的手中。亚撒王差派他们到大马士革的亚兰王，希旬的孙子、他伯利们的儿子便．哈达那里去，说：'),
('CNV', '列王纪上', 11, 15, 19, '“你父与我父之间曾经立过约，我也要与你立约。现在我把金银送给你作礼物，请你去废除与以色列王巴沙所立的约，好使他离开我。”'),
('CNV', '列王纪上', 11, 15, 20, '便．哈达听从亚撒王的话，派遣他的众军长去攻击以色列的各城。他们攻破了以云、但、亚伯．伯．玛迦、基尼烈全境和拿弗他利全地。'),
('CNV', '列王纪上', 11, 15, 21, '巴沙听见了，就停止修筑拉玛，仍然留在得撒。'),
('CNV', '列王纪上', 11, 15, 22, '于是亚撒王通告犹大众人，没有一个人例外。他们就把巴沙修筑拉玛所用的石头和木料运走；亚撒王用那些材料来修筑便雅悯的迦巴和米斯巴。'),
('CNV', '列王纪上', 11, 15, 23, '亚撒其余的一切事迹，他的英勇事迹，他所行的一切和他所建造的众城，不是都写在犹大列王的年代志上吗？可是他年老的时候，脚上却患了病。'),
('CNV', '列王纪上', 11, 15, 24, '亚撒与他的列祖同睡，与他的列祖一同埋葬在他祖大卫的城里，他的儿子约沙法接续他作王。'),
('CNV', '列王纪上', 11, 15, 25, '犹大王亚撒第二年，耶罗波安的儿子拿答登基作以色列王；他作以色列王共二年。'),
('CNV', '列王纪上', 11, 15, 26, '拿答行耶和华看为恶的事，跟随他父亲的路，犯他父亲使以色列人陷在罪中的那罪。'),
('CNV', '列王纪上', 11, 15, 27, '以萨迦家族亚希雅的儿子巴沙密谋背叛拿答。拿答和以色列众人正在围攻非利士地的基比顿的时候，巴沙在基比顿把拿答杀了。'),
('CNV', '列王纪上', 11, 15, 28, '犹大王亚撒第三年，巴沙杀死了拿答接续他作王。'),
('CNV', '列王纪上', 11, 15, 29, '巴沙一作王，就击杀了耶罗波安的全家。凡有气息的，他都没有留下一个，直到灭尽了，正如耶和华藉着他的仆人示罗人亚希雅所说的话一样。'),
('CNV', '列王纪上', 11, 15, 30, '这是因为耶罗波安所犯的罪，和他使以色列人陷在罪中的那罪，又因为他惹动耶和华以色列的神的怒气。'),
('CNV', '列王纪上', 11, 15, 31, '拿答其余的事迹和他所行的一切，不是都记在以色列诸王的年代志上吗？'),
('CNV', '列王纪上', 11, 15, 32, '亚撒与以色列王巴沙在世的日子，双方常常有争战。'),
('CNV', '列王纪上', 11, 15, 33, '犹大王亚撒第三年，亚希雅的儿子巴沙在得撒登基作以色列的王，共二十四年。'),
('CNV', '列王纪上', 11, 15, 34, '他行耶和华看为恶的事，行耶罗波安的路，犯了耶罗波安使以色列人陷在罪中的那罪。'),
('CNV', '列王纪上', 11, 16, 1, '耶和华的话临到哈尼拿的儿子耶户，责备巴沙说：'),
('CNV', '列王纪上', 11, 16, 2, '“我既然从尘埃中高举了你，立你作我的子民以色列的领袖；然而，你却走耶罗波安的路，使我的子民以色列犯罪，因他们的罪惹我发怒。'),
('CNV', '列王纪上', 11, 16, 3, '看哪，我要除灭巴沙和他的家；我要使你的家像尼八的儿子耶罗波安的家一样。'),
('CNV', '列王纪上', 11, 16, 4, '属巴沙的人，死在城里的，必被狗吃掉；死在田野的，必被空中的飞鸟吃掉。”'),
('CNV', '列王纪上', 11, 16, 5, '巴沙其余的事迹，他所行的，以及他的英勇事迹，不是都记在以色列诸王的年代志上吗？'),
('CNV', '列王纪上', 11, 16, 6, '巴沙与他的列祖同睡，埋葬在得撒；他的儿子以拉接续他作王。'),
('CNV', '列王纪上', 11, 16, 7, '再者，耶和华的话藉着哈尼拿的儿子耶户先知指责巴沙和他的家，是因为他像耶罗波安的家一样，行了耶和华看为恶的事，以他手所作的惹耶和华发怒，又因为他击杀了耶罗波安的家。'),
('CNV', '列王纪上', 11, 16, 8, '犹大王亚撒第二十六年，巴沙的儿子以拉在得撒登基作以色列的王，共二年。'),
('CNV', '列王纪上', 11, 16, 9, '他的臣仆心利，就是统率他一半战车的军长，密谋背叛他。那时他在得撒，在管理得撒王家的亚杂的家喝醉了，'),
('CNV', '列王纪上', 11, 16, 10, '心利就进去击打他，把他杀死了，接续他作王，这事发生在犹大王亚撒第二十七年。'),
('CNV', '列王纪上', 11, 16, 11, '心利一登基，坐了王位以后，就把巴沙的全家击杀了；连他的亲属和朋友，也没有留下一个男子。'),
('CNV', '列王纪上', 11, 16, 12, '心利这样灭绝巴沙的全家，是照着耶和华藉耶户先知责备巴沙所说的话。'),
('CNV', '列王纪上', 11, 16, 13, '这是因为巴沙和他的儿子以拉的一切罪，就是他们自己所犯，又使以色列人陷在罪中的那些罪，以虚无的神惹耶和华以色列的神发怒。'),
('CNV', '列王纪上', 11, 16, 14, '以拉其余的事迹和他所行的一切，不是都记在以色列诸王的年代志上吗？'),
('CNV', '列王纪上', 11, 16, 15, '犹大王亚撒第二十七年，心利在得撒作王七日。那时，众人正在安营围攻非利士的基比顿。'),
('CNV', '列王纪上', 11, 16, 16, '正在安营的众人听说：“心利已经密谋背叛，又击杀了王。”于是以色列众人在那一天，就在营中立了军长暗利作以色列王。'),
('CNV', '列王纪上', 11, 16, 17, '暗利和与他在一起的众人，从基比顿上去，围攻得撒。'),
('CNV', '列王纪上', 11, 16, 18, '心利看见城被攻占，就走进了王宫的城堡里，放火焚烧王宫，自焚而死。'),
('CNV', '列王纪上', 11, 16, 19, '这是因为他所犯的罪，行耶和华看为恶的事，走耶罗波安的路，犯了他使以色列人陷在罪中的那罪。'),
('CNV', '列王纪上', 11, 16, 20, '心利其余的事迹和他密谋背叛的事，不是都记在以色列诸王的年代志上吗？'),
('CNV', '列王纪上', 11, 16, 21, '那时，以色列人分成两半：一半跟从基纳的儿子提比尼，要立他作王；一半跟从暗利。'),
('CNV', '列王纪上', 11, 16, 22, '跟从暗利的人胜过了跟从基纳的儿子提比尼的人。提比尼死了以后，暗利就作了王。'),
('CNV', '列王纪上', 11, 16, 23, '犹大王亚撒第三十一年，暗利登基作以色列王共十二年，在得撒作王六年。'),
('CNV', '列王纪上', 11, 16, 24, '暗利用六十公斤银子，向撒玛购买了撒玛利亚山。他在山上建造一城，按山的原主撒玛的名，给他所建造的城起名叫撒玛利亚。'),
('CNV', '列王纪上', 11, 16, 25, '暗利行耶和华看为恶的事，比他以前所有的王更厉害。'),
('CNV', '列王纪上', 11, 16, 26, '他行尼八的儿子耶罗波安的一切路，犯了耶罗波安使以色列人陷在罪中的那罪；以他们虚无的神惹耶和华以色列的神发怒。'),
('CNV', '列王纪上', 11, 16, 27, '暗利其余的事迹，他所行的和他所表现的英勇事迹，不是都记在以色列诸王的年代志上吗？'),
('CNV', '列王纪上', 11, 16, 28, '暗利与他的列祖同睡，埋葬在撒玛利亚。他的儿子亚哈接续他作王。'),
('CNV', '列王纪上', 11, 16, 29, '犹大王亚撒第三十八年，暗利的儿子亚哈登基作以色列王。暗利的儿子亚哈在撒玛利亚作以色列王，共二十二年。'),
('CNV', '列王纪上', 11, 16, 30, '暗利的儿子亚哈行耶和华看为恶的事，比他以前所有的王更厉害。'),
('CNV', '列王纪上', 11, 16, 31, '亚哈犯了尼八的儿子耶罗波安所犯的罪，还以为是小事。他又娶了西顿王谒巴力的女儿耶洗别作妻子，去服事巴力，敬拜巴力。'),
('CNV', '列王纪上', 11, 16, 32, '他在撒玛利亚建筑巴力庙，又在庙里为巴力立了一座祭坛。'),
('CNV', '列王纪上', 11, 16, 33, '亚哈又做了亚舍拉，亚哈所行的，惹耶和华以色列的神发怒，比他以前所有的以色列王更厉害。'),
('CNV', '列王纪上', 11, 16, 34, '亚哈在位的日子，伯特利人希伊勒重建耶利哥城。他立城的根基的时候，死了长子亚比兰，安放城门的时候，丧了幼子西割，正如耶和华藉着嫩的儿子约书亚所说的话。'),
('CNV', '列王纪上', 11, 17, 1, '提斯比人以利亚，就是从基列的提斯比来的先知，对亚哈说：“我指着我所事奉永活的耶和华以色列的神起誓，这几年若是没有我的命令，天必不降露，也不下雨。”'),
('CNV', '列王纪上', 11, 17, 2, '耶和华的话临到以利亚说：'),
('CNV', '列王纪上', 11, 17, 3, '“你离开这里，向东方去，躲藏在约旦河东面的基立溪旁。'),
('CNV', '列王纪上', 11, 17, 4, '你要喝那溪里的水，我已经吩咐乌鸦在那里供养你。”'),
('CNV', '列王纪上', 11, 17, 5, '于是以利亚去了，照着耶和华的话行了；他去住在约旦河东面的基立溪旁。'),
('CNV', '列王纪上', 11, 17, 6, '乌鸦早晨给他送饼和肉来，晚上也送饼和肉来，他也喝那溪里的水。'),
('CNV', '列王纪上', 11, 17, 7, '过了一些日子，那溪就干了，因为没有雨下在地上。'),
('CNV', '列王纪上', 11, 17, 8, '耶和华的话又临到以利亚说：'),
('CNV', '列王纪上', 11, 17, 9, '“你起来，往西顿的撒勒法去，住在那里；我已经吩咐那里的一个寡妇供养你。”'),
('CNV', '列王纪上', 11, 17, 10, '于是以利亚起来，往撒勒法去了；他来到城门口的时候，就看见一个寡妇在那里捡柴；以利亚呼叫她，说：“请你用器皿取点水来给我！”'),
('CNV', '列王纪上', 11, 17, 11, '她去取水的时候，以利亚又叫她，说：“请你也给我拿点饼来！”'),
('CNV', '列王纪上', 11, 17, 12, '她说：“我指着永活的耶和华你的神起誓，我没有饼，缸里只有一把面粉，瓶里只有一点油。你看我正在捡两根柴，然后回去，为自己和儿子做饼，我们吃完了，就等死。”'),
('CNV', '列王纪上', 11, 17, 13, '以利亚对她说：“不要惧怕，照着你所说的去作吧，不过要先为我做一个小饼，拿出来给我，然后才为你自己和儿子做饼。'),
('CNV', '列王纪上', 11, 17, 14, '因为耶和华以色列的神这样说：‘缸里的面粉必不会用完，瓶里的油决不会短缺，直等到耶和华降雨在地面上的日子。’”'),
('CNV', '列王纪上', 11, 17, 15, '她就去照着以利亚所说的作了。她和以利亚，以及她的家人，吃了许多日子。'),
('CNV', '列王纪上', 11, 17, 16, '缸里的面粉果然没有用完，瓶里的油也没有短缺，正像耶和华藉着以利亚所说的话一样。'),
('CNV', '列王纪上', 11, 17, 17, '这些事以后，那妇人，就是那个家庭的女主人的儿子病了。他的病情十分严重，以致呼吸都停止了。'),
('CNV', '列王纪上', 11, 17, 18, '于是妇人对以利亚说：“神人哪，我跟你有什么关系呢？你竟到我这里来，使耶和华想起我的罪孽，杀死我的儿子。”'),
('CNV', '列王纪上', 11, 17, 19, '以利亚对她说：“把你的儿子交给我吧！”以利亚就从她的怀中把孩子接过来，抱他上到自己所住的楼上去，放在自己的床上。'),
('CNV', '列王纪上', 11, 17, 20, '以利亚呼求耶和华说：“耶和华我的神啊，我寄居在这寡妇的家里，你也降祸与她，使她的儿子死去吗？”'),
('CNV', '列王纪上', 11, 17, 21, '然后，以利亚三次伏在孩子的身上，向耶和华呼求说：“耶和华我的神，求你恢复这孩子的生命吧。”'),
('CNV', '列王纪上', 11, 17, 22, '耶和华垂听了以利亚的话，孩子的生命果然恢复，活过来了。'),
('CNV', '列王纪上', 11, 17, 23, '以利亚把孩子抱起来，从楼上下到屋子里去，把孩子交给他的母亲；以利亚说：“看，你的儿子活了！”'),
('CNV', '列王纪上', 11, 17, 24, '妇人对以利亚说：“现在我知道你是神人，耶和华藉着你的口所说的话是真实的。”'),
('CNV', '列王纪上', 11, 18, 1, '过了许久，到第三年，耶和华的话临到以利亚说：“你去在亚哈面前出现，我要降雨在地面上。”'),
('CNV', '列王纪上', 11, 18, 2, '于是以利亚去了，要在亚哈面前出现。那时撒玛利亚发生十分严重的饥荒。'),
('CNV', '列王纪上', 11, 18, 3, '亚哈把他的家宰俄巴底召了来。原来俄巴底是个非常敬畏耶和华的人。'),
('CNV', '列王纪上', 11, 18, 4, '耶洗别除灭耶和华众先知的时候，俄巴底带走了一百个先知，每五十个人一组，分散藏在山洞里，又用饼和水供养他们。'),
('CNV', '列王纪上', 11, 18, 5, '亚哈对俄巴底说：“你走遍这地，到所有的水泉和溪水那里去看看，也许我们可以找到青草，使骡马能够生存，免得牲畜灭绝。”'),
('CNV', '列王纪上', 11, 18, 6, '于是他们分地巡视。亚哈独自走一路，俄巴底独自走另一路。'),
('CNV', '列王纪上', 11, 18, 7, '俄巴底在路上走的时候，以利亚遇见了他。俄巴底认出他来，就脸伏在地，说：“你真是我主以利亚吗？”'),
('CNV', '列王纪上', 11, 18, 8, '以利亚对他说：“我是。你去告诉你主人，说：‘以利亚在这里。’”'),
('CNV', '列王纪上', 11, 18, 9, '俄巴底说：“我犯了什么罪，你竟要把你仆人交在亚哈手里，使他杀死我呢？'),
('CNV', '列王纪上', 11, 18, 10, '我指着永活的耶和华你的神起誓，没有一邦一国我主人不派人去找你的，人们若是说你不在那里，他就要那国邦起誓说实在找不到你。'),
('CNV', '列王纪上', 11, 18, 11, '现在你说：‘你去告诉你主人：以利亚在这里。’'),
('CNV', '列王纪上', 11, 18, 12, '我一离开你，耶和华的灵就把你提到我不知道的地方去。这样，如果我去告诉亚哈，他找不到你，必定杀我。你仆人却是自幼敬畏耶和华的。'),
('CNV', '列王纪上', 11, 18, 13, '难道没有人把我所作的事告诉我主吗？就是耶洗别杀害耶和华众先知的时候，我把一百个先知，五十人一组的分别藏在山洞里，又用饼和水供养他们。'),
('CNV', '列王纪上', 11, 18, 14, '现在你说：‘你去告诉你主人以利亚在这里！’他必定杀我。”'),
('CNV', '列王纪上', 11, 18, 15, '以利亚说：“我指着我所服事永活的万军之耶和华起誓，今天我必在亚哈面前出现。”'),
('CNV', '列王纪上', 11, 18, 16, '于是俄巴底去见亚哈，把这事告诉他。亚哈就去见以利亚。'),
('CNV', '列王纪上', 11, 18, 17, '亚哈看见了以利亚，就问他：“给以色列惹麻烦的这个人就是你吗？”'),
('CNV', '列王纪上', 11, 18, 18, '以利亚说：“给以色列惹麻烦的，不是我，而是你和你父的家；因为你们离弃了耶和华的诫命，又去随从巴力。'),
('CNV', '列王纪上', 11, 18, 19, '现在你要派人去召集以色列众人和四百五十个巴力的先知，以及耶洗别供养的四百个亚舍拉的先知，都上迦密山来见我。”'),
('CNV', '列王纪上', 11, 18, 20, '于是亚哈派人召集众以色列人和众先知上迦密山去。'),
('CNV', '列王纪上', 11, 18, 21, '以利亚走近众人说：“你们三心两意，要到几时呢？如果耶和华是神，你们就应当随从耶和华；如果巴力是神，你们就应当随从巴力。”众人一句话也不回答。'),
('CNV', '列王纪上', 11, 18, 22, '以利亚对众人说：“耶和华的先知只剩下我一个，巴力的先知却有四百五十个。'),
('CNV', '列王纪上', 11, 18, 23, '现在，请给我们两头公牛。让巴力的先知自己挑选一头，把它切成块子，放在柴上，但不要点火；我也预备一头公牛，摆在柴上，也不点火。'),
('CNV', '列王纪上', 11, 18, 24, '你们呼求你们神的名，我也呼求耶和华的名。那降火来显示回答的神就是神了。”众人都回答：“这话说得很好！”'),
('CNV', '列王纪上', 11, 18, 25, '以利亚对巴力的众先知说：“你们既然人多，可以先为自己选一头公牛；预备好了，就呼求你们神的名，但不要点火。”'),
('CNV', '列王纪上', 11, 18, 26, '他们把人给他们的公牛牵了来，预备好了，就从早晨直到中午，呼求巴力的名，说：“巴力啊，应允我们吧！”可是没有声音，也没有回应。他们就在所筑的祭坛周围跳舞。'),
('CNV', '列王纪上', 11, 18, 27, '到了中午，以利亚嘲笑他们，说：“大声呼求吧，因为他是神，也许他正在默想，或事务繁忙，或正在旅行，或正在睡觉，你们要把他叫醒。”'),
('CNV', '列王纪上', 11, 18, 28, '他们就大声呼求，按着他们的规矩，用刀和枪刺自己，直到身体流血。'),
('CNV', '列王纪上', 11, 18, 29, '中午过后，他们继续狂呼乱叫，直到献晚祭的时候；可是仍没有声音，没有回应，也没有理睬他们的。'),
('CNV', '列王纪上', 11, 18, 30, '以利亚对众人说：“你们走近我这里来。”众人就都走近他面前。他重修已经毁坏了的耶和华的祭坛。'),
('CNV', '列王纪上', 11, 18, 31, '以利亚照着雅各子孙支派的数目，拿了十二块石头。'),
('CNV', '列王纪上', 11, 18, 32, '以利亚奉耶和华的名用这些石头筑了一座坛，在坛的四周挖沟，可容十四公升种籽，'),
('CNV', '列王纪上', 11, 18, 33, '然后把柴排好，又把公牛切成块子，放在柴上，就说：“你们盛满四桶水，倒在燔祭和柴上。”'),
('CNV', '列王纪上', 11, 18, 34, '又说：“倒第二次。”他们就倒第二次；又说：“倒第三次。”他们就倒第三次。'),
('CNV', '列王纪上', 11, 18, 35, '水流到祭坛的四周，甚至水沟里也满了水。'),
('CNV', '列王纪上', 11, 18, 36, '到了献晚祭的时候，以利亚先知近前来，说：“亚伯拉罕、以撒、以色列的神耶和华，求你今天使人知道你是在以色列中的神，我是你的仆人，又是奉你的命令行这一切事。'),
('CNV', '列王纪上', 11, 18, 37, '耶和华啊，求你应允我，应允我！使这民知道你耶和华是神，又知道是你使这民的心再回转过来的。”'),
('CNV', '列王纪上', 11, 18, 38, '于是有耶和华的火降下来，吞灭了燔祭、木柴、石头和尘土，连沟里的水也烧干了。'),
('CNV', '列王纪上', 11, 18, 39, '众人看见了，就面伏于地，说：“耶和华是神！耶和华是神！”'),
('CNV', '列王纪上', 11, 18, 40, '以利亚对他们说：“捉住巴力的先知，一个也不要让他们逃脱。”于是众人捉住他们。以利亚带他们下到基顺河边，在那里杀了他们。'),
('CNV', '列王纪上', 11, 18, 41, '以利亚对亚哈说：“你上去吃喝吧！因为已经有下大雨的响声了。”'),
('CNV', '列王纪上', 11, 18, 42, '亚哈就上去吃喝。以利亚上了迦密山顶，屈身在地，把脸放在两膝之间。'),
('CNV', '列王纪上', 11, 18, 43, '以利亚对自己的仆人说：“你上去向海那边观看。”他就上去观看，说：“什么也没有。”以利亚说：“你再回去观看。”这样说了七次。'),
('CNV', '列王纪上', 11, 18, 44, '到第七次，仆人说：“我看到一小片乌云，好像人的手掌那么大，正在从海里升上来。”以利亚说：“你上去告诉亚哈：‘赶快套车下山，免得被大雨所阻。’”'),
('CNV', '列王纪上', 11, 18, 45, '霎时之间，天空因风云而变为黑暗，随着降下大雨来。于是亚哈坐上了车，往耶斯列去了。'),
('CNV', '列王纪上', 11, 18, 46, '耶和华的能力临到以利亚的身上，以利亚就束上腰，跑在亚哈的前头，直跑到耶斯列的城门口。'),
('CNV', '列王纪上', 11, 19, 1, '亚哈把以利亚所行的一切，和他用刀杀死众先知的一切事，都告诉了耶洗别。'),
('CNV', '列王纪上', 11, 19, 2, '耶洗别就差派一个使者去见以利亚说：“明天这个时候，如果我不使你的性命，像那些人一样，愿神明惩罚我，并且加倍惩罚我。”'),
('CNV', '列王纪上', 11, 19, 3, '以利亚害怕，就起来，逃命去了。他到了犹大的别是巴，就把自己的仆人留在那里。'),
('CNV', '列王纪上', 11, 19, 4, '他自己却在旷野走了一天的路，来到一棵罗腾树下，就坐在那里求死，说：“耶和华啊，现在已经够了，求你取我的性命吧，因为我并不比我的列祖好。”'),
('CNV', '列王纪上', 11, 19, 5, '他躺在那棵罗腾树下，睡着了。忽然有一位天使拍他，说：“起来，吃吧！”'),
('CNV', '列王纪上', 11, 19, 6, '他张眼一看，只见头旁有用炭火烤的饼和一瓶水。他就起来吃喝，然后又躺下去。'),
('CNV', '列王纪上', 11, 19, 7, '耶和华的使者第二次回来拍他，说：“起来吃吧！因为你要走的路程太远了。”'),
('CNV', '列王纪上', 11, 19, 8, '于是他起来吃喝，靠着那食物的力量，他走了四十昼夜，直走到神的山，就是何烈山。'),
('CNV', '列王纪上', 11, 19, 9, '他在那里进了一个洞，就在洞里过夜。耶和华的话临到他，说：“以利亚啊，你在这里干什么？”'),
('CNV', '列王纪上', 11, 19, 10, '他说：“我为耶和华万军的神大发热心，因为以色列人背弃了你的约，拆毁了你的祭坛，用刀杀死了你的众先知，只剩下我一个人，他们还在寻索，要取去我的性命。”'),
('CNV', '列王纪上', 11, 19, 11, '耶和华说：“你出来站在山上，在我耶和华面前。”那时，耶和华从那里经过。在耶和华面前有强烈的大风，山崩石碎，但耶和华不在风中；风过以后有地震，但耶和华也不在地震中；'),
('CNV', '列王纪上', 11, 19, 12, '地震过后有火，耶和华也不在火中；火后有低微柔和的声音。'),
('CNV', '列王纪上', 11, 19, 13, '以利亚听见了，就用自己的外衣蒙着脸，走出来，站在洞口。忽然有声音向他说：“以利亚啊，你在这里干什么？”'),
('CNV', '列王纪上', 11, 19, 14, '以利亚说：“我为耶和华万军的神大发热心，因为以色列人背弃了你的约，拆毁了你的祭坛，用刀杀了你的众先知，只剩下我一个人，他们还在寻索，要取去我的性命。”'),
('CNV', '列王纪上', 11, 19, 15, '耶和华对他说：“你离去吧，从你来的路回到大马士革的旷野去。你到了那里，就要膏哈薛作亚兰王。'),
('CNV', '列王纪上', 11, 19, 16, '又要膏宁示的孙子耶户作以色列王，还要膏亚伯．米何拉人沙法的儿子以利沙接续你作先知。'),
('CNV', '列王纪上', 11, 19, 17, '将来逃得过哈薛的刀的，必被耶户杀死；逃得过耶户的刀的，必被以利沙杀死。'),
('CNV', '列王纪上', 11, 19, 18, '但我在以色列人中留下七千人，他们全是未曾向巴力屈过膝的，也未曾与巴力亲过嘴的。”'),
('CNV', '列王纪上', 11, 19, 19, '于是以利亚离开那里去了。他遇见沙法的儿子以利沙正在耕田。在他面前有十二对牛，他自己正在赶着第十二对牛。以利亚走过他那里去，把自己的外衣披在以利沙身上。'),
('CNV', '列王纪上', 11, 19, 20, '以利沙就撇下那些牛，跑在以利亚的后面，说：“请你允许我与父母亲吻别，然后我就跟随你。”以利亚对他说：“你回去吧！我向你作了什么呢？”'),
('CNV', '列王纪上', 11, 19, 21, '以利沙就离开他回去了。他牵了一对牛来宰了，用套牛的器具把牛煮熟，就分给众人，他们都吃了。然后以利沙就起来，跟随以利亚，服事他。'),
('CNV', '列王纪上', 11, 20, 1, '亚兰王便．哈达聚集他的全军，有三十二个王与他在一起，他带着战马和战车，上去围困撒玛利亚，攻打那城。'),
('CNV', '列王纪上', 11, 20, 2, '他派遣一些使者进城去见以色列王亚哈，对他说：“便．哈达这样说：'),
('CNV', '列王纪上', 11, 20, 3, '‘你的银子，你的金子都是我的；你的妻子和你最健壮的儿女也是我的。’”'),
('CNV', '列王纪上', 11, 20, 4, '以色列王回答说：“我主我王啊，就照着你所说的，我和我所有的一切都可以归你。”'),
('CNV', '列王纪上', 11, 20, 5, '那些使者再来说：“便．哈达这样说：‘我曾经差派人对你说：你要把你的银子，你的金子，你的妻子和你的儿女都给我。'),
('CNV', '列王纪上', 11, 20, 6, '明天大约这个时间，我要差派我的臣仆到你那里去；他们要搜查你的王宫和你臣仆的家；凡是他们看为宝贵的，他们都要下手拿走。’”'),
('CNV', '列王纪上', 11, 20, 7, '以色列王把国中所有的长老都召了来，对他们说：“请你们想想，看这人怎样的麻烦，他曾经差派人来我这里要我的妻子、我的儿女、我的银子和我的金子，我都没有拒绝他。”'),
('CNV', '列王纪上', 11, 20, 8, '众长老和人民对王说：“不要听从他，也不要答应他。”'),
('CNV', '列王纪上', 11, 20, 9, '于是亚哈对便．哈达的使者说：“请你们告诉我主我王说：‘王第一次差派人来向你仆人所要的一切，我都必照办；可是这次所要的，我却不能照办。’”于是使者去了，把这些话回覆便．哈达。'),
('CNV', '列王纪上', 11, 20, 10, '便．哈达又差派人去见亚哈说：“撒玛利亚的尘土若是足够跟从我的人每人捧一捧的话，愿神明惩罚我，并且加倍惩罚我。”'),
('CNV', '列王纪上', 11, 20, 11, '以色列王回答说：“你们去告诉他，佩戴武器的人，不可像解除武器的那样自夸。”'),
('CNV', '列王纪上', 11, 20, 12, '便．哈达与众王正在帐棚里喝酒，一听见了这话，就对他的臣仆说：“你们列队进攻。”他们就列队进攻那城。'),
('CNV', '列王纪上', 11, 20, 13, '这时，忽然有一个先知前来见以色列王亚哈，说：“耶和华这样说：‘你看见这些强大的军兵吗？看啊，今天我必把他们交在你手里，你就知道我是耶和华。’”'),
('CNV', '列王纪上', 11, 20, 14, '亚哈问：“藉着谁呢？”先知回答：“耶和华这样说：‘藉着跟从各省省长的年轻人。’”亚哈又问：“谁先开战呢？”先知说：“是你。”'),
('CNV', '列王纪上', 11, 20, 15, '于是亚哈数点了跟从各省省长的年轻人，共有二百三十二人。以后，他又数点所有的人民，以色列众民共有七千人。'),
('CNV', '列王纪上', 11, 20, 16, '在正午，便．哈达与帮助他的三十二个王正在帐棚里痛饮的时候，他们出发了。'),
('CNV', '列王纪上', 11, 20, 17, '跟从各省省长的年轻人首先出发。便．哈达派人去察看，他们回报他说：“有人从撒玛利亚出来了。”'),
('CNV', '列王纪上', 11, 20, 18, '便．哈达说：“如果他们是为了求和出来，你们要活捉他们；如果他们是为了争战出来，你们也要活捉他们。”'),
('CNV', '列王纪上', 11, 20, 19, '从城里出来的这些人，就是跟从各省省长的年轻人，军兵跟在他们后面。'),
('CNV', '列王纪上', 11, 20, 20, '他们各人遇见对手就杀。亚兰人逃跑，以色列人追赶他们。亚兰王便．哈达骑着马，与一些骑兵一起逃走。'),
('CNV', '列王纪上', 11, 20, 21, '以色列王出来，攻打战马和战车，大大地击败了亚兰人。'),
('CNV', '列王纪上', 11, 20, 22, '那先知前来见以色列王，对他说：“你要自强，留意看看你所要预备的，因为明年春天亚兰王必再上来攻击你。”'),
('CNV', '列王纪上', 11, 20, 23, '亚兰王的臣仆对亚兰王说：“以色列人的神是山神，所以他们比我们强；但我们若是在平原上与他们争战，我们必比他们强大。'),
('CNV', '列王纪上', 11, 20, 24, '王应该这样作：把众王各人的职务解除，另立军官代替他们；'),
('CNV', '列王纪上', 11, 20, 25, '又照着王损失的军兵的数目，招募一支新的军队，照数补充战马和战车。然后我们可以与他们在平原上作战，我们必定比他们强。”王听从他们的话，并且这样行了。'),
('CNV', '列王纪上', 11, 20, 26, '过了年，便．哈达数点了亚兰人，就上到亚弗去，要与以色列人争战。'),
('CNV', '列王纪上', 11, 20, 27, '以色列人数点人数，预备了粮食，就去迎战亚兰人。以色列人对着他们安营，好像两小群山羊羔；亚兰人却满布了那地。'),
('CNV', '列王纪上', 11, 20, 28, '有一位神人前来对以色列王说：“耶和华这样说：‘因为亚兰人说耶和华是山神，不是平原的神，所以我要把这些强大的军兵交在你手里，你们就知道我是耶和华。’”'),
('CNV', '列王纪上', 11, 20, 29, '以色列人和亚兰人相对安营，共七天。到了第七日，两军终于接战了。那一天，以色列人杀了亚兰人步兵十万。'),
('CNV', '列王纪上', 11, 20, 30, '余下来的都逃入亚弗城里，城墙倒塌，压死了余下来的二万七千人。便．哈达也逃到城里来，躲进一间密室里。'),
('CNV', '列王纪上', 11, 20, 31, '他的臣仆对他说：“我们听说以色列家的王都是仁慈的王；我们不如腰束麻布，头套绳索，出去投降以色列王，或许他会使你的性命存活。”'),
('CNV', '列王纪上', 11, 20, 32, '于是他们腰束麻布，头套绳索，来见以色列王，对他说：“你的仆人便．哈达说：‘求你使我的性命存活！’”亚哈说：“他还活着吗？他是我的兄弟！”'),
('CNV', '列王纪上', 11, 20, 33, '那些人认为这些话是个吉兆，急忙抓住他的话，说：“便．哈达是王的兄弟！”亚哈说：“你们去请他来。”便．哈达出来见王，亚哈就去请他上车。'),
('CNV', '列王纪上', 11, 20, 34, '便．哈达对王说：“我父亲从你父亲夺得的众城，我都必还给你；你可以为自己在大马士革设立市场，像我父亲在撒玛利亚设立市场一样。”亚哈说：“我与你立了这样的约，就放你去。”于是他和便．哈达立了约，就放他走了。'),
('CNV', '列王纪上', 11, 20, 35, '先知门徒中有一个人奉耶和华的命令对他的一个同伴说：“你打我吧！”可是，那人却不肯打他。'),
('CNV', '列王纪上', 11, 20, 36, '他就对那人说：“因为你不听从耶和华的话，你一离开我，就必有狮子咬死你。”那人一离开他，果然遇见了狮子，把他咬死。'),
('CNV', '列王纪上', 11, 20, 37, '先知的门徒又遇见另一个人，对他说：“你打我吧！”那人就打他，把他打伤。'),
('CNV', '列王纪上', 11, 20, 38, '于是那先知去了，在路旁等候王。他用头巾蒙住自己的眼睛，把自己改了装。'),
('CNV', '列王纪上', 11, 20, 39, '王从那里经过的时候，他向王呼叫说：“你仆人出征，在战阵之中，忽然有一个人转过来，带了另一个人来见我，说：‘你看守这个人，他若是走失了，就要你替他偿命，否则你要支付三十公斤银子。’'),
('CNV', '列王纪上', 11, 20, 40, '你仆人正在忙这忙那的时候，那人就不见了。”以色列王对他说：“你的判案就是这样，你已经自己判决了。”'),
('CNV', '列王纪上', 11, 20, 41, '他急忙把蒙在眼上的头巾除下，以色列王就认出他是一个先知。'),
('CNV', '列王纪上', 11, 20, 42, '先知对王说：“耶和华这样说：因为你把我要灭绝的人从你手中放走，所以要你替他偿命。要你的人民抵偿他的人民。”'),
('CNV', '列王纪上', 11, 20, 43, '于是以色列王闷闷不乐回到撒玛利亚，自己的王宫里去了。'),
('CNV', '列王纪上', 11, 21, 1, '耶斯列人拿伯在耶斯列有一个葡萄园，靠近撒玛利亚王亚哈的王宫。'),
('CNV', '列王纪上', 11, 21, 2, '亚哈对拿伯说：“把你的葡萄园让给我，我可以用作菜园，因为你的葡萄园靠近我的王宫。我要把一个更好的葡萄园与你交换。如果你喜欢，我也可以按市价给你银子。”'),
('CNV', '列王纪上', 11, 21, 3, '可是拿伯对亚哈说：“耶和华绝对不容许我把祖业给你。”'),
('CNV', '列王纪上', 11, 21, 4, '亚哈因为耶斯列人拿伯对他说：“我不能把祖业给你”，就闷闷不乐回到宫里。他躺在床上，脸朝向内，也不吃饭。'),
('CNV', '列王纪上', 11, 21, 5, '他的妻子耶洗别进来见他，问他说：“你为什么心里这么烦闷，连饭也不吃呢？”'),
('CNV', '列王纪上', 11, 21, 6, '亚哈回答她说：“因为我对耶斯列人拿伯说：‘把你的葡萄园让给我，我付你银子；或者你喜欢的话，我可以用另一个葡萄园与你交换’；可是他说：‘我不能把我的葡萄园让给你。’”'),
('CNV', '列王纪上', 11, 21, 7, '他的妻子耶洗别对他说：“你现在不是统治以色列的王吗？只管起来吃饭，心神畅快，我必能把耶斯列人拿伯的葡萄园给你。”'),
('CNV', '列王纪上', 11, 21, 8, '于是耶洗别以亚哈的名义写了一些信，盖上王的印章，然后把这些信送给那些住在拿伯城里的长老和贵胄。'),
('CNV', '列王纪上', 11, 21, 9, '她在信上写着说：“你们要宣告禁食，使拿伯坐在民间的首位上。'),
('CNV', '列王纪上', 11, 21, 10, '又叫两个匪徒坐在拿伯的对面，作见证控告他说：‘你曾经咒诅神和君王’；然后把他拉出去，用石头把他打死。”'),
('CNV', '列王纪上', 11, 21, 11, '于是拿伯城里的人，就是那些与拿伯同住一城的长老和贵胄，都照着耶洗别送给他们的信上所写的去行。'),
('CNV', '列王纪上', 11, 21, 12, '他们宣告禁食，使拿伯坐在民间的首席上。'),
('CNV', '列王纪上', 11, 21, 13, '然后两个匪徒来坐在拿伯的对面。这两个流氓当众作见证控告拿伯，说：“拿伯曾经咒诅神和君王。”众人就把拿伯拉出城外，用石头打他，把他打死了。'),
('CNV', '列王纪上', 11, 21, 14, '于是他们派人去见耶洗别，说：“拿伯已经被人用石头打死了。”'),
('CNV', '列王纪上', 11, 21, 15, '耶洗别听见拿伯已经被人用石头打死了，就对亚哈说：“你起来，去占有那耶斯列人拿伯从前不肯收银子给你的葡萄园，因为拿伯现在没有命了，他已经死了。”'),
('CNV', '列王纪上', 11, 21, 16, '亚哈听见拿伯已经死了，就起来，下到耶斯列人拿伯的葡萄园那里去，要占有那园。'),
('CNV', '列王纪上', 11, 21, 17, '那时，耶和华的话临到提斯比人以利亚说：'),
('CNV', '列王纪上', 11, 21, 18, '“你起来，下去迎见住在撒玛利亚的以色列王亚哈，他现在正在耶斯列人拿伯的葡萄园里。他下到那里去，是要占有那个园。'),
('CNV', '列王纪上', 11, 21, 19, '你要对他说：‘耶和华这样说：你杀了人，又占有他的产业吗？’你又要对他说：‘耶和华这样说：狗在什么地方舔拿伯的血，也必在什么地方舔你的血。’”'),
('CNV', '列王纪上', 11, 21, 20, '亚哈对以利亚说：“我的仇人哪，你找到了我吗？”以利亚说：“我找到你了，因为你出卖了你自己，去行耶和华看为恶的事。'),
('CNV', '列王纪上', 11, 21, 21, '耶和华说：‘看哪，我必使灾祸临到你，除灭你的后代，在以色列中属亚哈的男丁，无论是自由的，或是不自由的，我都要除灭。'),
('CNV', '列王纪上', 11, 21, 22, '我要使你的家像尼八的儿子耶罗波安的家，又像亚希雅的儿子巴沙的家，因为你惹我发怒，又因为你使以色列人陷在罪中。’'),
('CNV', '列王纪上', 11, 21, 23, '至于耶洗别，耶和华也说：‘狗必在耶斯列的地方吃耶洗别的肉。'),
('CNV', '列王纪上', 11, 21, 24, '属亚哈的人，死在城里的，必被野狗吃掉；死在田野的，必被空中的飞鸟吃掉。’”'),
('CNV', '列王纪上', 11, 21, 25, '只是从来没有人像亚哈的；他受了他妻子耶洗别的引诱，出卖了他自己，行耶和华看为恶的事。'),
('CNV', '列王纪上', 11, 21, 26, '他按照耶和华在以色列人面前赶走的亚摩利人所行的一切，跟从偶像。行了非常可憎的事。'),
('CNV', '列王纪上', 11, 21, 27, '亚哈听见这些话，就撕裂自己的衣服，披上麻布，禁食，睡在麻布上，并且神色颓丧地行走。'),
('CNV', '列王纪上', 11, 21, 28, '耶和华的话临到提斯比人以利亚说：'),
('CNV', '列王纪上', 11, 21, 29, '“你看见了亚哈在我面前怎样谦卑自己，因为他在我面前谦卑自己，所以他还在世的日子，我必不降这灾祸；到他儿子的日子，我必降这灾祸与他的家。”'),
('CNV', '列王纪上', 11, 22, 1, '亚兰人和以色列人之间，连续三年没有战争。'),
('CNV', '列王纪上', 11, 22, 2, '到了第三年，犹大王约沙法下去见以色列王。'),
('CNV', '列王纪上', 11, 22, 3, '以色列王对他的臣仆说：“你们知道吗？基列的拉末原属于我们，我们怎可静坐不动，不把它从亚兰王的手中夺回来呢？”'),
('CNV', '列王纪上', 11, 22, 4, '亚哈问约沙法：“你肯与我一起到基列的拉末去作战吗？”约沙法回答以色列王：“你我不分彼此，我的人民就象是你的人民，我的战马就象是你的战马。”'),
('CNV', '列王纪上', 11, 22, 5, '约沙法又对以色列王说：“现在请你先求问耶和华。”'),
('CNV', '列王纪上', 11, 22, 6, '于是以色列王把众先知聚集了来，约有四百人，问他们：“我可以去攻打基列的拉末吗？或是应当忍耐不去呢？”他们说：“你可以上去，主必把那城交在王的手里。”'),
('CNV', '列王纪上', 11, 22, 7, '约沙法说：“这里不是还有耶和华的先知，我们可以求问他吗？”'),
('CNV', '列王纪上', 11, 22, 8, '以色列王对约沙法说：“还有一个人，我们可以托他求问耶和华。不过我憎恨他，因为他对我说的预言，都是凶话，不是吉话。这人就是音拉的儿子米该雅。”但约沙法说：“请王不要这么说。”'),
('CNV', '列王纪上', 11, 22, 9, '于是王召了一位太监来，说：“快去把音拉的儿子米该雅召来！”'),
('CNV', '列王纪上', 11, 22, 10, '以色列王和犹大王约沙法穿着朝服，在撒玛利亚城门口的广场上，各人坐在自己的王位上；所有的先知都在他们面前说预言。'),
('CNV', '列王纪上', 11, 22, 11, '基拿拿的儿子西底家做了些铁角，说：“耶和华这样说：‘你要用这些铁角抵触亚兰人，直到把他们完全消灭。’”'),
('CNV', '列王纪上', 11, 22, 12, '所有的先知也都这样预言说：“你可以上基列的拉末去，必得胜利！因为耶和华必把那城交在王的手里。”'),
('CNV', '列王纪上', 11, 22, 13, '那去召米该雅的使者对米该雅说：“看哪，这里的众先知都异口同声地对王说吉话，请你与他们一样说吉话。”'),
('CNV', '列王纪上', 11, 22, 14, '米该雅说：“我指着永活的耶和华起誓，耶和华吩咐我什么，我就说什么。”'),
('CNV', '列王纪上', 11, 22, 15, '米该雅来到王那里的时候，王就问他：“米该雅啊，我们可以到基列的拉末去作战吗？或是要忍耐不去呢？”米该雅回答亚哈：“你可以上去，必得胜利，因为耶和华必把那城交在王的手里！”'),
('CNV', '列王纪上', 11, 22, 16, '王对他说：“我要嘱咐你多少次，你才奉耶和华的名对我只说真话呢？”'),
('CNV', '列王纪上', 11, 22, 17, '米该雅说：“我看见以色列人四散在山上，好像没有牧人的羊群一样；耶和华说：‘这些人没有主人，使他们平平安安各自回家吧！’”'),
('CNV', '列王纪上', 11, 22, 18, '以色列王对约沙法说：“我不是告诉过你，这人对我说的预言，总不说吉话，只说凶话吗？”'),
('CNV', '列王纪上', 11, 22, 19, '米该雅说：“因此，你要听耶和华的话；我看见耶和华坐在他的宝座上，天上的万军都侍立在他的左右。'),
('CNV', '列王纪上', 11, 22, 20, '耶和华说：‘谁去引诱亚哈，使他上基列的拉末阵亡呢？’有说这样的，有说那样的。'),
('CNV', '列王纪上', 11, 22, 21, '后来有一个灵出来，站在耶和华面前，说：‘我去引诱他。’耶和华问他：‘你用什么方法呢？’'),
('CNV', '列王纪上', 11, 22, 22, '他回答：‘我要出去，在亚哈所有先知的口中，作说谎的灵。’耶和华说：‘你可以去引诱他，你也必能成功，你去这样行吧！’'),
('CNV', '列王纪上', 11, 22, 23, '现在，耶和华已经把说谎的灵放在你这些先知的口中，耶和华已经命定灾祸临到你。”'),
('CNV', '列王纪上', 11, 22, 24, '基拿拿的儿子西底家近前来，打米该雅的脸颊说：“耶和华的灵怎样离开了我，去与你说话呢？”'),
('CNV', '列王纪上', 11, 22, 25, '米该雅说：“你进密室躲藏的那一天，就必看见了。”'),
('CNV', '列王纪上', 11, 22, 26, '以色列王说：“把米该雅带回去，交给市长亚们和王的儿子约阿施，'),
('CNV', '列王纪上', 11, 22, 27, '说：‘王这样吩咐：把这人囚在监里，少给他食物和水，直到我平平安安回来。’”'),
('CNV', '列王纪上', 11, 22, 28, '米该雅说：“如果你真的可以平平安安回来，那么耶和华就没有藉着我说话了。”他又说：“众民啊，你们都要听。”'),
('CNV', '列王纪上', 11, 22, 29, '于是，以色列王和犹大王约沙法上基列的拉末去了。'),
('CNV', '列王纪上', 11, 22, 30, '以色列王对约沙法说：“我要改装上战场去了；你可以仍穿自己的朝服。”于是以色列王改装到战场去了。'),
('CNV', '列王纪上', 11, 22, 31, '亚兰王曾经嘱咐他的三十二个战车长说：“无论大小将兵，你们都不要与他们争战，只要与以色列王争战。”'),
('CNV', '列王纪上', 11, 22, 32, '战车长们看见约沙法的时候，就说：“这人必是以色列王。”他们就转过去与他争战，约沙法便喊叫起来。'),
('CNV', '列王纪上', 11, 22, 33, '战车长们一见他不是以色列王，就转回来，不追赶他了。'),
('CNV', '列王纪上', 11, 22, 34, '有一个人随便射了一箭，竟射中了以色列王铁甲与护胸甲之间的地方。王对驾车的说：“你把车转过来，载我离开战场吧！我受了重伤。”'),
('CNV', '列王纪上', 11, 22, 35, '那一天战争不断升级，有人扶着王站在车上抵挡亚兰人。到了黄昏，王就死了；血从伤口流到战车的底下去。'),
('CNV', '列王纪上', 11, 22, 36, '约在日落的时候，有命令传遍军中说：“各归各城，各归各地吧。”'),
('CNV', '列王纪上', 11, 22, 37, '王死了以后，人们把他送回撒玛利亚，埋葬在那里。'),
('CNV', '列王纪上', 11, 22, 38, '他们在撒玛利亚的池旁，妓女洗澡的地方清洗战车，有狗来舔亚哈的血，正如耶和华说过的话一样。'),
('CNV', '列王纪上', 11, 22, 39, '亚哈其余的事迹，他所作的一切，他建造的象牙宫和他重建的一切城镇，不是都记在以色列诸王的年代志上吗？'),
('CNV', '列王纪上', 11, 22, 40, '亚哈与他的列祖同睡，他的儿子亚哈谢接续他作王。'),
('CNV', '列王纪上', 11, 22, 41, '以色列王亚哈第四年，亚撒的儿子约沙法登基作犹大王。'),
('CNV', '列王纪上', 11, 22, 42, '约沙法登基的时候是三十五岁；他在耶路撒冷作王二十五年。他母亲名叫阿苏巴，是示利希的女儿。'),
('CNV', '列王纪上', 11, 22, 43, '约沙法遵行他父亲亚撒所行的一切，总不偏离，行耶和华看为正的事。只是邱坛还没有废去，人民仍在邱坛上献祭烧香。'),
('CNV', '列王纪上', 11, 22, 44, '约沙法王与以色列王和平相处。'),
('CNV', '列王纪上', 11, 22, 45, '约沙法其余的事迹，他作过的英勇的事和他怎样争战的事，不是都写在犹大列王的年代志上吗？'),
('CNV', '列王纪上', 11, 22, 46, '约沙法把父亲亚撒在世时遗留下来的庙妓都从国中除灭。'),
('CNV', '列王纪上', 11, 22, 47, '那时，以东没有王，由总督统治。'),
('CNV', '列王纪上', 11, 22, 48, '约沙法建造了他施船只，要到俄斐去运金子，可是不能开船，因为船只在以旬．迦别坏了。'),
('CNV', '列王纪上', 11, 22, 49, '那时亚哈的儿子亚哈谢对约沙法说：“让我的仆人与你的仆人一同坐船去吧！”但是约沙法不肯。'),
('CNV', '列王纪上', 11, 22, 50, '约沙法与他的列祖同睡，与他的列祖一同埋葬在他先祖大卫的城里；他的儿子约兰接续他作王。'),
('CNV', '列王纪上', 11, 22, 51, '犹大王约沙法第十七年，亚哈的儿子亚哈谢在撒玛利亚登基作以色列王。他作以色列王两年。'),
('CNV', '列王纪上', 11, 22, 52, '他行耶和华看为恶的事，行他父亲的道和他母亲的道，又行尼八的儿子耶罗波安使以色列人陷在罪中的道。'),
('CNV', '列王纪上', 11, 22, 53, '他事奉巴力，敬拜巴力，照着他父亲所行的一切惹耶和华以色列的神发怒。'),
('CNV', '列王纪下', 12, 1, 1, '亚哈死后，摩押背叛以色列。'),
('CNV', '列王纪下', 12, 1, 2, '有一天，亚哈谢在撒玛利亚，从楼上的窗户掉下来，他就病了；于是他差派使者，对他们说：“你们去求问以革伦的神巴力．西卜，我这个病到底能否复原？”'),
('CNV', '列王纪下', 12, 1, 3, '但耶和华的使者对提斯比人以利亚说：“你动身上去迎着撒玛利亚王的使者，对他们说：‘你们去求问以革伦的神巴力．西卜，是因为以色列中没有神吗？'),
('CNV', '列王纪下', 12, 1, 4, '因此，耶和华这样说：你必不能从你躺上去的那张床上下来，因为你必定死。’”于是以利亚去了。'),
('CNV', '列王纪下', 12, 1, 5, '众使者回到亚哈谢那里；他对他们说：“你们为什么回来呢？”'),
('CNV', '列王纪下', 12, 1, 6, '他们对王说：“有一个人上来迎着我们，又对我们说：‘去吧，回到那差派你们的王那里，对他说：耶和华这样说：你派人去求问以革伦的神巴力．西卜，是因为以色列中没有神吗？因此，你必不能从你躺上去的那张床上下来，因为你必定死。’”'),
('CNV', '列王纪下', 12, 1, 7, '王对他们说：“那上来迎着你们，又对你们说这番话的是个怎样的人？”'),
('CNV', '列王纪下', 12, 1, 8, '他们对王说：“那人穿着毛皮衣，腰间束上皮带。”王说：“这人必是提斯比人以利亚。”'),
('CNV', '列王纪下', 12, 1, 9, '于是王差派一个五十夫长和他的五十名手下到以利亚那里；那位五十夫长就上到以利亚那里去。他看见以利亚正坐在山顶上，就对以利亚说：“神人哪！王吩咐你下来。”'),
('CNV', '列王纪下', 12, 1, 10, '以利亚回答五十夫长说：“如果我是神人，愿火从天降下，把你和你的五十名手下吞灭。”于是有火从天降下，吞灭了五十夫长和他的五十名手下。'),
('CNV', '列王纪下', 12, 1, 11, '王再次派一个五十夫长和他的五十名手下到以利亚那里去。那五十夫长对以利亚说：“神人哪！王这样吩咐：‘你赶快下来。’”'),
('CNV', '列王纪下', 12, 1, 12, '以利亚回答他们说：“如果我是神人，愿火从天降下，把你和你的五十名手下吞灭。”于是神的火从天降下，吞灭了五十夫长和他的五十名手下。'),
('CNV', '列王纪下', 12, 1, 13, '王又派出第三名五十夫长和他的五十名手下；那五十夫长来到，就双膝跪在以利亚面前，恳求他，对他说：“神人哪！愿我的性命和这五十个仆人的性命在你眼中看为宝贵。'),
('CNV', '列王纪下', 12, 1, 14, '看哪！曾经有火从天降下，吞灭了先前两个五十夫长和他们各五十名手下；现在，愿我的性命在你眼中看为宝贵。”'),
('CNV', '列王纪下', 12, 1, 15, '耶和华的使者对以利亚说：“你和他下去吧，不要怕他。”于是以利亚起来，和他下山到王那里去了。'),
('CNV', '列王纪下', 12, 1, 16, '以利亚对亚哈谢说：“耶和华这样说：‘你差派使者去求问以革伦的神巴力．西卜，是因为以色列中没有神可以求问吗？因此，你必不能从你躺上去的那张床上下来，因为你必定死。’”'),
('CNV', '列王纪下', 12, 1, 17, '亚哈谢果然死了，正如耶和华藉以利亚所宣告的话。因为他没有儿子，他的弟弟约兰就接续他作王，那时是犹大王约沙法的儿子约兰第二年。'),
('CNV', '列王纪下', 12, 1, 18, '亚哈谢其余所行的事迹，不是都写在以色列诸王的年代志上吗？'),
('CNV', '列王纪下', 12, 2, 1, '耶和华将要用旋风接以利亚往天上去的时候，以利亚和以利沙一起离开吉甲。'),
('CNV', '列王纪下', 12, 2, 2, '以利亚对以利沙说：“你留在这里吧，因为耶和华差派我到伯特利去。”以利沙说：“我指着永活的耶和华和你的性命起誓：我必不离开你。”于是他们下到伯特利去。'),
('CNV', '列王纪下', 12, 2, 3, '在伯特利的先知门徒出来见以利沙，对他说：“你知道今天耶和华要接你的老师离开你吗？”他说：“我已经知道了，你们别再多说。”'),
('CNV', '列王纪下', 12, 2, 4, '以利亚对以利沙说：“你留在这里吧，因为耶和华差派我往耶利哥。”他说：“我指着永活的耶和华和你的性命起誓：我必不离开你。”于是他们来到耶利哥。'),
('CNV', '列王纪下', 12, 2, 5, '在耶利哥的先知门徒前来见以利沙，对他说：“你知道今天耶和华要接你的老师离开你吗？”他说：“我已经知道了，你们别再多说。”'),
('CNV', '列王纪下', 12, 2, 6, '以利亚对他说：“你留在这里吧，因为耶和华差派我往约旦河去。”以利沙说：“我指着永活的耶和华和你的性命起誓：我必不离开你。”于是他们二人继续前行。'),
('CNV', '列王纪下', 12, 2, 7, '先知门徒中有五十人跟着他们，远远地站在他们对面；他们二人在约旦河河边站着。'),
('CNV', '列王纪下', 12, 2, 8, '以利亚拿着自己的外衣，把它卷起，击打河水，河水就左右分开，他们二人就在干地上走过去了。'),
('CNV', '列王纪下', 12, 2, 9, '他们过去之后，以利亚对以利沙说：“在我没有被接离开你以先，我可以为你作些什么，你尽管求吧！”以利沙说：“求你使你的灵双倍地临到我。”'),
('CNV', '列王纪下', 12, 2, 10, '以利亚说：“你所求的是一件难事，不过我被接离开你的时候，如果你看见我，就必得着，否则就得不着了。”'),
('CNV', '列王纪下', 12, 2, 11, '他们边走边谈的时候，忽然，有火车火马把他们二人分开，以利亚就在旋风中被接往天上去了。'),
('CNV', '列王纪下', 12, 2, 12, '以利沙看见，就喊叫：“我父！我父！以色列的战车马兵啊！”跟着就不再看见他了。以利沙抓住自己的衣服，把它撕成两片。'),
('CNV', '列王纪下', 12, 2, 13, '他拾起以利亚身上掉下来的外衣，就回去，站在约旦河河边。'),
('CNV', '列王纪下', 12, 2, 14, '他拿着从以利亚身上掉下来的外衣，击打河水，说：“耶和华以利亚的神在哪里呢？”他一击打河水，河水就左右分开，以利沙就走过去了。'),
('CNV', '列王纪下', 12, 2, 15, '那些耶利哥的先知门徒在远处看见，就说：“以利亚的灵在以利沙身上了。”他们就来迎接他，俯伏在地拜他。'),
('CNV', '列王纪下', 12, 2, 16, '他们对他说：“请看，你的仆人这里有五十个壮士；请让他们去寻找你的老师，或者耶和华的灵把他提去，丢在某一座山上，或某一处山谷里。”以利沙说：“你们不必派人去了。”'),
('CNV', '列王纪下', 12, 2, 17, '他们恳求他，使他不好意思推辞，于是他说：“你们派人去吧。”他们就派出五十个人，寻觅了三天，仍然找不着。'),
('CNV', '列王纪下', 12, 2, 18, '于是他们回到以利沙那里；那时，他还停留在耶利哥，他对他们说：“我不是告诉了你们不必去的吗？”'),
('CNV', '列王纪下', 12, 2, 19, '那城的人对以利沙说：“请看这城的地势很好，老师你也看见，可惜水恶劣，以致此地没有出产。”'),
('CNV', '列王纪下', 12, 2, 20, '以利沙说：“给我拿一个新碗来，里面要盛点盐。”他们就把碗拿给他。'),
('CNV', '列王纪下', 12, 2, 21, '他就出去到水源那里，把盐倒在那里，然后说：“耶和华这样说：‘我已经医好了这水，从此不再有人死亡，地也不再没有出产了。’”'),
('CNV', '列王纪下', 12, 2, 22, '那水果然治好了，直到今日，正如以利沙所说的话。'),
('CNV', '列王纪下', 12, 2, 23, '以利沙从那里上伯特利去，正沿路上去的时候，从城里有一班年轻人走出来，讥笑他，说：“秃头的上去吧！秃头的上去吧！”'),
('CNV', '列王纪下', 12, 2, 24, '以利沙回头看着他们，奉耶和华的名咒诅他们。于是有两只母熊从树林里走出来，撕裂了他们中间四十二个年轻人。'),
('CNV', '列王纪下', 12, 2, 25, '以利沙从那里上迦密山，又从迦密山回到撒玛利亚。'),
('CNV', '列王纪下', 12, 3, 1, '犹大王约沙法第十八年，亚哈的儿子约兰在撒玛利亚作王，统治以色列；他作王共有十二年。'),
('CNV', '列王纪下', 12, 3, 2, '他行耶和华看为恶的事，只是还不至于像他的父亲和母亲一样，因为他除去了他父亲所做的巴力神柱。'),
('CNV', '列王纪下', 12, 3, 3, '只是尼八的儿子耶罗波安使以色列人陷在罪中的那些罪，他却坚持不舍，不肯脱离。'),
('CNV', '列王纪下', 12, 3, 4, '摩押王米沙是个以牧羊为生的人。他每年进贡十万头绵羊羔和十万头公羊羔给以色列王。'),
('CNV', '列王纪下', 12, 3, 5, '亚哈死后，摩押王背叛以色列王。'),
('CNV', '列王纪下', 12, 3, 6, '那时约兰王从撒玛利亚出来点阅以色列众人。'),
('CNV', '列王纪下', 12, 3, 7, '他一面起行，一面派人到犹大王约沙法那里，说：“摩押王背叛了我，你肯不肯和我同去攻打摩押呢？”约沙法说：“我愿意去；我和你不分彼此，我的人民就象是你的人民，我的马就象是你的马。”'),
('CNV', '列王纪下', 12, 3, 8, '约沙法问：“我们从哪条路上去呢？”约兰回答：“从以东旷野的路上去。”'),
('CNV', '列王纪下', 12, 3, 9, '于是以色列王、犹大王和以东王，绕道行了七日的路程。军队和随行的牲畜都没有水喝。'),
('CNV', '列王纪下', 12, 3, 10, '以色列王说：“哎哟，耶和华招聚这三位君王，是要把他们交在摩押人的手中。”'),
('CNV', '列王纪下', 12, 3, 11, '约沙法说：“这里不是有一位耶和华的先知吗？我们可以托他求问耶和华。”以色列王的一位臣仆说：“这里有沙法的儿子以利沙，他从前是服事以利亚的。”'),
('CNV', '列王纪下', 12, 3, 12, '约沙法说：“他必有耶和华的话。”于是以色列王、约沙法和以东王都下到他那里。'),
('CNV', '列王纪下', 12, 3, 13, '以利沙对以色列王说：“我和你有什么关系呢？去问你父亲和你母亲的先知吧！”以色列王对他说：“不要这样说，耶和华招聚这三位君王，是要把他们交在摩押人手中。”'),
('CNV', '列王纪下', 12, 3, 14, '以利沙说：“我指着我所事奉永活的万军耶和华起誓，若不是看犹大王约沙法的情面，我根本不会理你，看也不看你。'),
('CNV', '列王纪下', 12, 3, 15, '现在，给我找一个琴师来。”当琴师弹琴的时候，耶和华的能力就临到他身上。'),
('CNV', '列王纪下', 12, 3, 16, '以利沙说：“耶和华这样说：‘要在这山谷到处挖濠沟。’'),
('CNV', '列王纪下', 12, 3, 17, '因为耶和华这样说：‘你们虽然没有看见风，也没有看见雨，但这山谷必充满了水，你们和你们的牲畜都可以有水喝。'),
('CNV', '列王纪下', 12, 3, 18, '这事在耶和华眼中算是小事，他还要把摩押交在你们手中。'),
('CNV', '列王纪下', 12, 3, 19, '你们要攻破所有坚固的城和一切繁华的都市；砍下各种佳美的树木，堵塞所有水泉，用石头堆满一切肥沃的田地。’”'),
('CNV', '列王纪下', 12, 3, 20, '到了早上，约在献祭的时候，忽然有水从以东来，遍地就满了水。'),
('CNV', '列王纪下', 12, 3, 21, '摩押全国听见这几位君王上来要攻打他们，就召集所有能够穿上武装的，不论老幼，到边界上防守。'),
('CNV', '列王纪下', 12, 3, 22, '第二天早上，他们起来的时候，太阳照在水上，摩押人从那边看见水红得像血一样。'),
('CNV', '列王纪下', 12, 3, 23, '他们说：“这是血啊！一定是那些王互相攻击，自相残杀；现在，摩押人哪，去抢掠吧！”'),
('CNV', '列王纪下', 12, 3, 24, '他们来到以色列营，以色列人起来，击杀摩押人，摩押人就在以色列人面前逃跑；以色列人就攻进摩押，击杀他们。'),
('CNV', '列王纪下', 12, 3, 25, '他们毁坏城市，各人向一切肥沃的田地抛掷石头，把田地填满了，又堵塞一切水泉，砍下各种佳美的树木，直到吉珥．哈列设只剩下石头，甩石的兵把它包围，攻击它。'),
('CNV', '列王纪下', 12, 3, 26, '摩押王见战事激烈，无法抵抗，于是带领七百持刀的兵，想要突围到以东王那里，可是不成功，'),
('CNV', '列王纪下', 12, 3, 27, '于是他把那要接续他作王的长子，在城墙上献为燔祭。以色列人就遭遇极大的忿怒，于是离开他，回到自己的地方去了。'),
('CNV', '列王纪下', 12, 4, 1, '一位先知门徒的妻子哀求以利沙说：“你仆人我的丈夫死了，你知道你的仆人是敬畏耶和华的。现在债主来要抓我的两个孩子作他的奴仆。”'),
('CNV', '列王纪下', 12, 4, 2, '以利沙对他说：“我可以为你作什么呢？告诉我，你家里有什么呢？”她说：“婢女家中除了一瓶油以外，什么也没有。”'),
('CNV', '列王纪下', 12, 4, 3, '以利沙说：“你到外面去向你所有的邻居借空器皿，要尽量多借。'),
('CNV', '列王纪下', 12, 4, 4, '然后回去，把你和你儿子关在家里，你要把油倒在所有器皿里面，装满了的就放在一边。”'),
('CNV', '列王纪下', 12, 4, 5, '于是妇人离开了他，把自己和儿子关在门内；她的儿子不住地把器皿拿到她面前，她就把油倒进去。'),
('CNV', '列王纪下', 12, 4, 6, '器皿都倒满了的时候，她对儿子说：“再拿一个器皿给我。”他对她说：“再没有器皿了。”油就止住了。'),
('CNV', '列王纪下', 12, 4, 7, '她去告诉神人，神人说：“你去把油卖掉，还清你的债务，你和你的儿子可以靠着剩下的过活。”'),
('CNV', '列王纪下', 12, 4, 8, '有一天，以利沙经过书念的时候，那里有一位贵妇坚持留他吃饭；于是以后每逢他从那里经过，他总进去吃饭。'),
('CNV', '列王纪下', 12, 4, 9, '那妇人对她的丈夫说：“你看，我知道那常从我们这里经过的，是个圣洁的神人。'),
('CNV', '列王纪下', 12, 4, 10, '让我们盖一间有墙的小阁，为他在里面摆设睡床、桌子、椅子和灯盏；他到我们这里来的时候，就可以到那里休息。”'),
('CNV', '列王纪下', 12, 4, 11, '有一天，以利沙来到那里，就上小阁休息，在那里躺下。'),
('CNV', '列王纪下', 12, 4, 12, '他对他的仆人基哈西说：“你去叫这书念的妇人来。”于是他叫了她来，站在他的面前。'),
('CNV', '列王纪下', 12, 4, 13, '他对他的仆人说：“你对她说：‘看哪！你为我们费了这么多心思。我可以为你作些什么呢？你有事要我替你向王或军长说的吗？’”她说：“我住在自己的人民中间。”'),
('CNV', '列王纪下', 12, 4, 14, '于是他说：“我到底可以为她作些什么呢？”基哈西说：“她没有儿子，而她的丈夫又老了。”'),
('CNV', '列王纪下', 12, 4, 15, '于是以利沙对他说：“再叫她来。”他就再去叫了她来，她就站在门口。'),
('CNV', '列王纪下', 12, 4, 16, '以利沙说：“明年这个时分，时候到了，你必怀抱一个儿子。”她说：“神人哪！不要欺哄你的婢女。”'),
('CNV', '列王纪下', 12, 4, 17, '这妇人果然怀了孕，到明年这个时分，时候到了，她就生了一个儿子，正如以利沙对她所说的。'),
('CNV', '列王纪下', 12, 4, 18, '孩子渐渐长大。有一天，他出来到收割的人中找他的父亲。'),
('CNV', '列王纪下', 12, 4, 19, '他对他的父亲说：“我的头啊！我的头啊！”他的父亲对仆人说：“把他抱到他母亲那里。”'),
('CNV', '列王纪下', 12, 4, 20, '于是仆人把他抱着，送到他母亲那里。孩子坐在他母亲的双膝上，到中午就死了。'),
('CNV', '列王纪下', 12, 4, 21, '她把孩子抱上小阁，放在神人的床上；她把他关在里面，就出去了。'),
('CNV', '列王纪下', 12, 4, 22, '她呼唤她的丈夫，说：“请你派一个仆人和一头驴子给我。我要赶到神人那里，立刻就回来。”'),
('CNV', '列王纪下', 12, 4, 23, '他说：“为什么你要在今天去见他呢？今天既不是月朔，也不是安息日。”她说：“一切都平安。”'),
('CNV', '列王纪下', 12, 4, 24, '于是她把驴套上鞍，对她的仆人说：“你来赶驴子走吧，除非我告诉你，否则不要因为我慢下来。”'),
('CNV', '列王纪下', 12, 4, 25, '于是她起程，去到迦密山神人那里。神人从远处看见她的时候，就对他的仆人基哈西说：“看哪！书念的妇人在那边呢！'),
('CNV', '列王纪下', 12, 4, 26, '现在你跑去迎接她，对她说：‘你平安吗？你的丈夫平安吗？你的儿子平安吗？’”她说：“都平安。”'),
('CNV', '列王纪下', 12, 4, 27, '她来到山上神人那里，就抱住神人的脚；基哈西上前要推开她，但神人说：“由她吧，因为她的心灵很痛苦。耶和华隐瞒我，没有告诉我。”'),
('CNV', '列王纪下', 12, 4, 28, '她说：“我有向我主求过儿子吗？我不是说过：‘不要欺哄我’的吗？”'),
('CNV', '列王纪下', 12, 4, 29, '神人对基哈西说：“你束上腰，手里拿着我的手杖前去；不论遇见的是谁，都不要向他问安；若是有人向你问安，你也不要回答他，只要去把我的手杖放在孩子的脸上。”'),
('CNV', '列王纪下', 12, 4, 30, '孩子的母亲说：“我指着永活的耶和华和你的性命起誓，我决不会离开你。”神人只好起身随她而去。'),
('CNV', '列王纪下', 12, 4, 31, '基哈西在他们前面去了，把手杖放在孩子的脸上，可是没有声音，也没有反应；于是他回来迎着以利沙，告诉他说：“那孩子还没有醒过来。”'),
('CNV', '列王纪下', 12, 4, 32, '以利沙来到书念妇人的家，看见孩子已经死了，躺在他的床上。'),
('CNV', '列王纪下', 12, 4, 33, '于是他进去，把自己和孩子二人关在门内，然后向耶和华祷告。'),
('CNV', '列王纪下', 12, 4, 34, '他又上床伏在孩子身上，使自己的口对着孩子的口，自己的眼对着孩子的眼，自己的手放在孩子的手上；他伏在孩子身上，孩子的身体就渐渐温暖起来。'),
('CNV', '列王纪下', 12, 4, 35, '然后他下来在房内来回走了一趟，再上去，伏在孩子身上；那孩子打了七个喷嚏，跟着就张开了眼睛。'),
('CNV', '列王纪下', 12, 4, 36, '神人呼唤基哈西，说：“你去叫那书念的妇人来。”他就去叫她，她来到他那里，他就说：“把你的儿子抱起来。”'),
('CNV', '列王纪下', 12, 4, 37, '于是她进去，在他的脚前下拜，俯伏在地上；然后把儿子抱起来，出去了。'),
('CNV', '列王纪下', 12, 4, 38, '以利沙又回到吉甲，那地正发生饥荒。先知的门徒坐在他面前。他对他的仆人说：“把大锅放在火上，给先知的门徒们煮点东西吃。”'),
('CNV', '列王纪下', 12, 4, 39, '有一个人到田野那里去采摘野菜。他找到一棵野瓜藤，就摘下藤上的野瓜装满了他的衣服。他回来，把瓜切了放入煮东西的锅中，他们不知道是什么东西。'),
('CNV', '列王纪下', 12, 4, 40, '后来他们倒出来给众人吃，他们在吃锅里的东西的时候，都惨叫起来，说：“神人哪！锅中有致死的毒物！”他们就不能吃了。'),
('CNV', '列王纪下', 12, 4, 41, '他说：“拿些面给我。”他把面放在锅中，说：“倒出来给众人吃吧。”锅里就没有毒了。'),
('CNV', '列王纪下', 12, 4, 42, '有一个人从巴力．沙利沙来，他带给神人二十个用初熟大麦做的饼，还有新穗子，装在他的袋子里；以利沙说：“把这些给众人吃吧！”'),
('CNV', '列王纪下', 12, 4, 43, '他的仆人说：“我怎能把这一些食物摆在一百个人面前呢？”神人说：“给众人吃吧，因为耶和华这样说：‘他们要吃，而且还有剩下的。’”'),
('CNV', '列王纪下', 12, 4, 44, '于是仆人摆在众人面前，他们都吃，而且还有剩下的，正如耶和华所说的。'),
('CNV', '列王纪下', 12, 5, 1, '亚兰王的军长乃缦在他的主人面前是一个大人物，很得王的赏识，因为耶和华曾藉他把胜利赐给亚兰。这个人是个勇猛的战士，可惜他是个痲风病人。'),
('CNV', '列王纪下', 12, 5, 2, '亚兰人曾经出去结队抢掠，从以色列地掳了一个小女孩，她就侍候乃缦的妻子。'),
('CNV', '列王纪下', 12, 5, 3, '她对她的女主人说：“如果我的主人去见撒玛利亚的先知就好了，他必定能治好他的痲风。”'),
('CNV', '列王纪下', 12, 5, 4, '于是乃缦去告诉他的主人说：“从以色列地掳回来的女孩子这样这样说。”'),
('CNV', '列王纪下', 12, 5, 5, '亚兰王说：“你去吧！我会送一封书信给以色列王的。”于是乃缦去了，手里带着三百公斤银子，约七十公斤金子和十套衣裳。'),
('CNV', '列王纪下', 12, 5, 6, '他把信带到以色列王那里，信上说：“这信既已达到你那里，你看见我差去见你的臣仆乃缦，你就要医好他的痲风。”'),
('CNV', '列王纪下', 12, 5, 7, '以色列王读了这信后，就撕裂自己的衣服，说：“我是神，能使人死使人活吗？这人竟派人到我这里来，要我治好他的痲风。请你们想想看，他是要找机会攻击我。”'),
('CNV', '列王纪下', 12, 5, 8, '神人以利沙听见以色列王撕裂自己的衣服，就打发人去见王说：“你为什么撕裂自己的衣服呢？请你把他送到我这里来吧！他就知道在以色列中有先知了。”'),
('CNV', '列王纪下', 12, 5, 9, '于是乃缦带着他的车马来到，停在以利沙的门前。'),
('CNV', '列王纪下', 12, 5, 10, '以利沙差派一个使者去见他说：“你去在约旦河中沐浴七次，你的身体就会复原，得着洁净。”'),
('CNV', '列王纪下', 12, 5, 11, '乃缦却发怒走了，他说：“我以为他必会出来，站着求告耶和华他的神的名，向着患处摇手，洁净这痲风病。'),
('CNV', '列王纪下', 12, 5, 12, '大马士革的亚罢拿河和法珥法河，不是比以色列一切河流更好吗？我不是可以在那里沐浴，得着洁净吗？”于是他掉过头来，气忿忿地走了。'),
('CNV', '列王纪下', 12, 5, 13, '他的仆人上前，对他说：“我父啊，先知如果吩咐你作一件大事，你不是照着行吗？何况他只是说：‘你去沐浴就得洁净’呢？”'),
('CNV', '列王纪下', 12, 5, 14, '于是他下去，在约旦河里浸了七趟，正如神人所吩咐的。他的肌肉就复原，好像小孩子的肌肉，他就得了洁净。'),
('CNV', '列王纪下', 12, 5, 15, '乃缦和他的随员又回到神人那里，他进去，站在他面前，说：“看哪！现在我知道除了在以色列以外，全地都没有神。现在，请你收下你仆人一点礼物吧。”'),
('CNV', '列王纪下', 12, 5, 16, '以利沙说：“我指着我所事奉永活的耶和华起誓，我决不收取任何礼物。”乃缦再三促请他接受，都被他拒绝。'),
('CNV', '列王纪下', 12, 5, 17, '乃缦说：“你若是不肯收取，就请你赐你仆人两头驴子可以驮的泥土，因为你的仆人不再献燔祭或别的祭给别的神，只献给耶和华。'),
('CNV', '列王纪下', 12, 5, 18, '但有一件事，求耶和华赦免你的仆人；我的主人到临门庙那里叩拜的时候，他总是靠在我的手臂上，因此，我也曾在临门庙叩拜。我在临门庙叩拜这事，求耶和华赦免你的仆人。”'),
('CNV', '列王纪下', 12, 5, 19, '以利沙说：“你平平安安回去吧。”于是乃缦离开他去了，走了一段路程。'),
('CNV', '列王纪下', 12, 5, 20, '神人以利沙的仆人基哈西心里说：“看哪，我主人不肯从这亚兰人乃缦手中收取他带来的礼物；我指着永活的耶和华起誓，我要追上他，向他要些东西。”'),
('CNV', '列王纪下', 12, 5, 21, '于是基哈西追赶乃缦。乃缦看见有人追上来，就下车迎着他，说：“平安吗？”'),
('CNV', '列王纪下', 12, 5, 22, '他说：“平安。我主人派我来说：‘刚才有两位年轻人，都是先知的门徒，从以法莲山地来到我这里，请你给他们三十公斤银子和两套衣服。’”'),
('CNV', '列王纪下', 12, 5, 23, '乃缦说：“请你拿六十公斤吧。”他再三促请基哈西，并把六十公斤银子，装在两个袋子里，还有两套衣服，交给两个仆人。他们就在基哈西前面捧着走。'),
('CNV', '列王纪下', 12, 5, 24, '到达山冈后，他就从他们手中接过东西，存放在屋子里，然后打发他们离去，他们就走了。'),
('CNV', '列王纪下', 12, 5, 25, '他进去，侍立在他主人面前，以利沙对他说：“基哈西，你从哪里来？”他说：“你的仆人没有到过什么地方。”'),
('CNV', '列王纪下', 12, 5, 26, '以利沙对他说：“那人下车转身迎着你的时候，我的心不是和你同去吗？现在不是收受银子、衣服、橄榄园、葡萄园、羊、牛、仆人和婢女的时候。'),
('CNV', '列王纪下', 12, 5, 27, '因此，乃缦的痲风要附在你的身上和你后裔的身上，直到永远。”基哈西从以利沙面前离去时，就长了痲风，好像雪那样白。'),
('CNV', '列王纪下', 12, 6, 1, '众先知门徒对以利沙说：“请看，我们在你面前居住的那一个地方，对我们来说实在是太窄小了。'),
('CNV', '列王纪下', 12, 6, 2, '请你让我们到约旦河，每人从那里取一根木头，我们要在那里为自己建造一个地方居住。”以利沙说：“你们去吧！”'),
('CNV', '列王纪下', 12, 6, 3, '有一个门徒说：“请你和你的仆人们一起去。”他说：“我会去的。”'),
('CNV', '列王纪下', 12, 6, 4, '他就和他们同去。他们到了约旦河，就砍伐树木。'),
('CNV', '列王纪下', 12, 6, 5, '有一个门徒砍伐木头的时候，斧头掉到水里去了。他就喊着说：“惨啦！我主啊，这斧头是借回来的。”'),
('CNV', '列王纪下', 12, 6, 6, '神人说：“掉在哪里呢？”于是他把那地点指给他看。他砍了一根木头，丢在那里，那斧头就浮上来了。'),
('CNV', '列王纪下', 12, 6, 7, '以利沙说：“你自己拿上来吧。”他就伸手把它拿住了。'),
('CNV', '列王纪下', 12, 6, 8, '亚兰王与以色列人打仗，他和他的臣仆商议，说：“我要在某处某处埋伏。”'),
('CNV', '列王纪下', 12, 6, 9, '神人就差派人去见以色列王说：“你要小心，不要经过这个地方，因为亚兰人在那里埋伏。”'),
('CNV', '列王纪下', 12, 6, 10, '以色列王派人到那地方，就是神人曾告诉他，警告他的，他就在那里小心防范；这样不止一两次。'),
('CNV', '列王纪下', 12, 6, 11, '亚兰王因为这事心中大感困惑，他召了他的臣仆来，对他们说：“在我们中间有谁帮助以色列王，你们不告诉我吗？”'),
('CNV', '列王纪下', 12, 6, 12, '他的一位臣仆说：“我主我王啊！不是的；只不过是以色列的以利沙先知，把你在你卧室内所说的话，告知了以色列王。”'),
('CNV', '列王纪下', 12, 6, 13, '于是王说：“你们去看看他在哪里，我要派人把他捉住。”有人告诉他说：“看哪！他正在多坍。”'),
('CNV', '列王纪下', 12, 6, 14, '他就差派车马和一大队军兵往那里去，他们在夜间抵达，围困那城。'),
('CNV', '列王纪下', 12, 6, 15, '神人的侍从清早起来，走出屋子，看见军队、车马围住了城。神人的仆人对神人说：“惨啦，我主啊！我们怎样办才好呢？”'),
('CNV', '列王纪下', 12, 6, 16, '神人说：“不要惧怕，因为和我们在一起的比和他们在一起的更多。”'),
('CNV', '列王纪下', 12, 6, 17, '以利沙祷告，说：“耶和华啊！请你打开他的眼睛，使他能看见。”于是耶和华打开了仆人的眼睛，他就看见；看哪！那山上布满了火马火车，围绕着以利沙。'),
('CNV', '列王纪下', 12, 6, 18, '亚兰人下来攻击以利沙，以利沙就祷告耶和华，说：“求你击打这民族，使他们瞎眼。”于是耶和华击打他们，使他们瞎眼，正如以利沙所说的。'),
('CNV', '列王纪下', 12, 6, 19, '以利沙对他们说：“这不是那条路，这边不是那座城；你们跟着我来，我要把你们领到你们要寻找的人那里。”于是他把他们领到撒玛利亚。'),
('CNV', '列王纪下', 12, 6, 20, '他们进入撒玛利亚的时候，以利沙就说：“耶和华啊！求你开这些人的眼睛，使他们能看见。”于是耶和华开了他们的眼睛，他们就看见了。看哪！他们竟是在撒玛利亚城中。'),
('CNV', '列王纪下', 12, 6, 21, '以色列王看见他们，就对以利沙说：“我父啊，我可以击杀他们吗？”'),
('CNV', '列王纪下', 12, 6, 22, '以利沙说：“你不可击杀他们。你可以击杀你自己用刀用弓掳回来的人吗？你要在他们面前摆上食物和水，给他们吃喝，然后回到他们的主人那里去。”'),
('CNV', '列王纪下', 12, 6, 23, '于是王为他们预备盛大的宴会；他们吃喝完了，王打发他们离去，他们就回到他们的主人那里去了。从此，亚兰的军队不再侵犯以色列地了。'),
('CNV', '列王纪下', 12, 6, 24, '后来，亚兰王便．哈达征召他全部的军队上来围困撒玛利亚。'),
('CNV', '列王纪下', 12, 6, 25, '于是撒玛利亚发生了极大的饥荒，敌军继续包围，以致一个驴头要卖九百克银子，两百克的鸽子粪也值六十克银子。'),
('CNV', '列王纪下', 12, 6, 26, '以色列王在城墙上经过时，有一个妇人向他呼求说：“我主我王啊，救救我！”'),
('CNV', '列王纪下', 12, 6, 27, '他说：“如果耶和华不救你，我又从哪里救你？是从打谷场，或是从榨酒池呢？”'),
('CNV', '列王纪下', 12, 6, 28, '王对她说：“到底有什么事呢？”她说：“这妇人对我说：‘把你的儿子交出来，今日我们好把他吃了；明天我们可以吃我的儿子。’'),
('CNV', '列王纪下', 12, 6, 29, '于是我们把我的儿子煮了，把他吃了。第二日，我对她说：‘把你的儿子交出来，我们好把他吃了。’她却把她的儿子收藏起来。”'),
('CNV', '列王纪下', 12, 6, 30, '王听见那妇人的话，就撕裂衣服，他当时正在城墙上，人民都看见他；看哪，他里面贴身穿着的是件麻衣。'),
('CNV', '列王纪下', 12, 6, 31, '他说：“如果今日沙法的儿子以利沙的头仍留在他身上，愿神惩罚我，而且加倍惩罚我。”'),
('CNV', '列王纪下', 12, 6, 32, '那时，以利沙正坐在自己的屋子里，众长老也和他坐在一起。王差派一个在他面前侍立的人去，那使者去到以利沙那里以前，以利沙对众长老说：“你们看这凶手之子派人来取我的首级。你们留意那使者来到的时候，你们要把门关上，把他挡在门外。他主人的脚步声不是在他后面吗？”'),
('CNV', '列王纪下', 12, 6, 33, '他和众长老还在说话的时候，看哪，王就下到他那里，说：“看哪，这灾祸是从耶和华来的，我为什么还仰望耶和华呢？”'),
('CNV', '列王纪下', 12, 7, 1, '以利沙说：“你们要听耶和华的话。耶和华这样说：‘明日大约这个时候，在撒玛利亚的城门，三公斤面粉只卖十一克银子，六公斤大麦也只是卖十一克银子。’”'),
('CNV', '列王纪下', 12, 7, 2, '但那搀扶王的官长回答神人，说：“即使耶和华在天上开了窗户，也不会有这事发生。”以利沙说：“看哪，你要亲眼看见，却吃不着。”'),
('CNV', '列王纪下', 12, 7, 3, '有四个痲风病人在城门口那里，他们彼此说：“我们为什么坐在这里等死呢？'),
('CNV', '列王纪下', 12, 7, 4, '我们如果说：‘我们进城去吧！’城里正有饥荒，我们就要死在那里。我们如果坐在这里，也是要死。现在，让我们去投降亚兰人的军队吧；如果他们饶我们一命，我们就可以活着；如果他们要杀死我们，我们就死吧。”'),
('CNV', '列王纪下', 12, 7, 5, '于是他们在黄昏动身去到亚兰人的军营那里；他们来到亚兰人的军营外边，竟看不见一个人在那里。'),
('CNV', '列王纪下', 12, 7, 6, '因为主使亚兰人的军队听见战车、战马和大军的声音；他们就彼此说：“看哪，一定是以色列王雇用了赫人的众王和埃及人的众王来攻击我们。”'),
('CNV', '列王纪下', 12, 7, 7, '于是他们在黄昏的时候起来逃跑，他们丢下他们的帐幕，他们的马匹和他们的驴子；军营仍在那里，他们却只顾逃命去了。'),
('CNV', '列王纪下', 12, 7, 8, '这些患痲风病的人来到军营的外边，他们进入其中一座帐幕，又吃又喝，并且从那里取去金子、银子和衣服，然后离去，把东西收藏起来。他们再回去，进入另一座帐幕，从那里拿走财物，去收藏起来。'),
('CNV', '列王纪下', 12, 7, 9, '他们彼此说：“我们这样作是不对的。今天是报好消息的日子，我们竟不出声，如果我们等到早上天亮，我们就算为有罪了。现在，来吧，我们要去通知王家。”'),
('CNV', '列王纪下', 12, 7, 10, '他们就去呼喊守城门的，告诉他们说：“我们去过亚兰人的军营那里，看见那里一个人也没有，也没有人声。只有马仍拴着，驴仍拴着，帐幕都原封不动。”'),
('CNV', '列王纪下', 12, 7, 11, '守城门的就喊叫起来，又往城内给王家报信。'),
('CNV', '列王纪下', 12, 7, 12, '王在夜间起来，对他的臣仆说：“我告诉你们亚兰人对我们所作的是怎么一回事。他们知道我们闹饥荒，所以出到军营外在田野埋伏，心里说：‘他们必从城里出来。我们就可以活捉他们，进入城里去了。’”'),
('CNV', '列王纪下', 12, 7, 13, '他的一位臣仆回答，说：“请叫人拉五匹剩下的马来；看哪，它们像所有剩下在这里的以色列人，都要像所有死去的以色列人一样；让我们打发人去看看吧。”'),
('CNV', '列王纪下', 12, 7, 14, '于是他们取了两辆战车和马匹，王差人去追踪亚兰军，吩咐他们：“去查看吧。”'),
('CNV', '列王纪下', 12, 7, 15, '他们就去追踪亚兰军直到约旦河。看哪，沿途堆满了衣物器具，就是亚兰人在匆忙逃走时丢弃的。于是使者回去向王报告。'),
('CNV', '列王纪下', 12, 7, 16, '众民就出去，抢掠亚兰人的军营。于是三公斤面粉卖十一克银子，六公斤大麦也卖十一克银子，好像耶和华所说的。'),
('CNV', '列王纪下', 12, 7, 17, '王指派那官长，就是那搀扶他的，在城门口镇压。众民在城门那里把他践踏在地，他就死了，好像神人所说的，就是王下来到神人那里时，他所说的。'),
('CNV', '列王纪下', 12, 7, 18, '这是因为当神人对王说：“明天大约这个时分，在撒玛利亚城门口，六公斤大麦卖十一克银子，三公斤面粉也卖十一克银子。”'),
('CNV', '列王纪下', 12, 7, 19, '那官长回答神人，说：“即使耶和华在天上开了窗户，也不会有这事发生。”神人说：“看哪，你要亲眼看见，却吃不着。”'),
('CNV', '列王纪下', 12, 7, 20, '这事果然发生在他身上：众民把他践踏在地，他就死了。'),
('CNV', '列王纪下', 12, 8, 1, '以利沙告诉那妇人，说：“你和你全家要动身，离开这里，住在你可以寄居的地方，因为耶和华宣布了将有饥荒，这饥荒要临到这地七年。”'),
('CNV', '列王纪下', 12, 8, 2, '那妇人就动身，按照神人所说的去作。她和她的全家离去，住在非利士地七年。'),
('CNV', '列王纪下', 12, 8, 3, '七年结束的时候，那妇人从非利士地回来，就去为自己的房屋、田产哀求王。'),
('CNV', '列王纪下', 12, 8, 4, '那时王正在和神人的仆人基哈西交谈，说：“请你向我讲述以利沙所作的一切大事。”'),
('CNV', '列王纪下', 12, 8, 5, '他正向王讲述以利沙叫死人复活的事的时候；看哪，以利沙曾救活她的儿子的那妇人来为她的房屋、田产哀求王。基哈西说：“我主我王，这就是那妇人了，她的这个儿子就是以利沙救活的了。”'),
('CNV', '列王纪下', 12, 8, 6, '王问那妇人，她就告诉他一切事。于是王指派一个太监给他，说：“把所有属于她的，以及从她离开此地直到现在，她田地的一切出产都归还她。”'),
('CNV', '列王纪下', 12, 8, 7, '以利沙来到大马士革。亚兰王便．哈达患了病。有人告诉他说：“神人来到这里了。”'),
('CNV', '列王纪下', 12, 8, 8, '王对哈薛说：“你带着礼物，去见神人，托他求问耶和华说：‘我这病能痊愈吗？’”'),
('CNV', '列王纪下', 12, 8, 9, '于是哈薛去见以利沙。他带着礼物，就是大马士革各样的美物，由四十匹骆驼驮着，去站在他的面前，说：“你的儿子亚兰王便．哈达派我到你这里来，问你说：‘我这病能痊愈吗？’”'),
('CNV', '列王纪下', 12, 8, 10, '以利沙对他说：“你去告诉他说：‘你一定会痊愈的’，但耶和华指示我，他一定要死。”'),
('CNV', '列王纪下', 12, 8, 11, '以利沙定睛看着他，直到他感到侷促不安；然后，神人哭了起来。'),
('CNV', '列王纪下', 12, 8, 12, '哈薛说：“我主为什么哭起来了？”他回答：“因为我已知道你要对以色列人施行的恶事。他们的城堡，你要放火焚烧；他们的年轻人，你要用刀杀死；他们的婴孩，你要摔死；他们的孕妇，你要剖开。”'),
('CNV', '列王纪下', 12, 8, 13, '哈薛说：“你仆人算什么？不过是一条狗罢了；怎可以作这样的大事呢？”以利沙说：“耶和华已指示我，你要作王统治亚兰。”'),
('CNV', '列王纪下', 12, 8, 14, '于是他离开以利沙，回到他主人那里。便．哈达对他说：“以利沙对你说了些什么呢？”他说：“他对我说：‘你一定痊愈的。’”'),
('CNV', '列王纪下', 12, 8, 15, '第二天，哈薛拿被窝浸在水里，然后蒙住便．哈达的面，他就死了；于是哈薛接续他作王。'),
('CNV', '列王纪下', 12, 8, 16, '以色列王亚哈的儿子约兰第五年，犹大王约沙法还在的时候，犹大王约沙法的儿子约兰登基作了王。'),
('CNV', '列王纪下', 12, 8, 17, '他登基时是三十二岁；在耶路撒冷作王八年。'),
('CNV', '列王纪下', 12, 8, 18, '他照着以色列诸王的道路而行，好像亚哈家所行的；因为他娶了亚哈的女儿为妻，并且行耶和华看为恶的事。'),
('CNV', '列王纪下', 12, 8, 19, '但耶和华因他仆人大卫的缘故不愿毁灭犹大，却要照他应许大卫的，赐给他和他的后裔永远有灯光延续。'),
('CNV', '列王纪下', 12, 8, 20, '约兰王在位的日子，以东人反叛，脱离犹大人的手，自己立王统治本国。'),
('CNV', '列王纪下', 12, 8, 21, '于是约兰过到撒益去，并且带着他所有的战车。他夜间起来攻击包围他和他的战车军长的以东人，他的军民却逃回自己的帐棚去了。'),
('CNV', '列王纪下', 12, 8, 22, '于是以东人背叛，脱离犹大人的手，直到今日；那时立拿人也同时背叛。'),
('CNV', '列王纪下', 12, 8, 23, '约兰其余的事迹和他所行的一切，不是都写在犹大列王的年代志上吗？'),
('CNV', '列王纪下', 12, 8, 24, '约兰和他的祖先同睡；人把他埋葬在大卫城和他的祖先一起；他的儿子亚哈谢接续他作王。'),
('CNV', '列王纪下', 12, 8, 25, '以色列王亚哈的儿子约兰在位第十二年，犹大王约兰的儿子亚哈谢作犹大王。'),
('CNV', '列王纪下', 12, 8, 26, '他登基时是二十二岁，在耶路撒冷作王一年。他母亲名叫亚他利雅，是以色列王暗利的孙女。'),
('CNV', '列王纪下', 12, 8, 27, '他照着亚哈家的道路而行，行耶和华看为恶的事，好像亚哈家一样，因为他是亚哈家的女婿。'),
('CNV', '列王纪下', 12, 8, 28, '亚哈谢与亚哈的儿子约兰往基列的拉末，同亚兰王哈薛交战；亚兰人击伤了约兰。'),
('CNV', '列王纪下', 12, 8, 29, '约兰于是回去，到耶斯列治伤，就是当他攻打亚兰王哈薛时，亚兰人在拉末击伤他的。犹大王约兰的儿子亚哈谢因为亚哈的儿子约兰病了，所以下到耶斯列去探望他。'),
('CNV', '列王纪下', 12, 9, 1, '以利沙先知唤来一位先知门徒，对他说：“你要束上腰，手里拿着这瓶膏油，到基列的拉末去。'),
('CNV', '列王纪下', 12, 9, 2, '你到了那里，要在那里寻找宁示的孙子、约沙法的儿子耶户。你要去，请他从他的兄弟中起来，然后把他带进一个密室。'),
('CNV', '列王纪下', 12, 9, 3, '你要拿着这瓶膏油，把油倒在他的头上，说：“耶和华这样说：‘我膏立你作王统治以色列。’然后，你要开门逃跑，不可停留。”'),
('CNV', '列王纪下', 12, 9, 4, '于是那年轻的先知往基列的拉末去了。'),
('CNV', '列王纪下', 12, 9, 5, '他到了那里，看见军队的将领都坐在那里。他就说：“将军，我有话要对你说。”耶户说：“我们这里所有的人，你要对哪一个说话呢？”他说：“将军，我要对你说。”'),
('CNV', '列王纪下', 12, 9, 6, '耶户就起来，进了屋子；先知门徒就把油倒在耶户的头上，对他说：“以色列的神耶和华这样说：‘我膏立你作王，统治耶和华的人民以色列。'),
('CNV', '列王纪下', 12, 9, 7, '你要击杀你的主人亚哈的家。我要为我仆人众先知的血和所有耶和华的仆人的血，在耶洗别身上报仇。'),
('CNV', '列王纪下', 12, 9, 8, '亚哈的全家都要灭亡；我要剪除在以色列属亚哈的男人，无论是自由的，或是为奴的。'),
('CNV', '列王纪下', 12, 9, 9, '我要使亚哈的家好像尼八的儿子耶罗波安的家，又好像亚希雅的儿子巴沙的家。'),
('CNV', '列王纪下', 12, 9, 10, '至于耶洗别，她的尸体要在耶斯列的田间被狗吃掉，没有人来埋葬。’”他一说完，就开门逃走了。'),
('CNV', '列王纪下', 12, 9, 11, '耶户出来，到他主人的臣仆那里去；他们问他说：“一切都平安吗？那疯子来见你有什么事呢？”他对他们说：“你们认识这个人，也知道他说些什么。”'),
('CNV', '列王纪下', 12, 9, 12, '他们说：“谎话！请你告诉我们吧。”他说：“他这样对我说：‘耶和华这样说：我已经膏立你作王统治以色列。’”'),
('CNV', '列王纪下', 12, 9, 13, '他们就急忙把自己的衣服放在他脚下的上层台阶上，然后吹响号角宣告：“耶户作王了。”'),
('CNV', '列王纪下', 12, 9, 14, '这样，宁示的孙子、约沙法的儿子耶户背叛约兰了。约兰和以色列众人曾因亚兰王哈薛的缘故，守卫着基列的拉末。'),
('CNV', '列王纪下', 12, 9, 15, '但后来约兰王回到耶斯列去治伤，就是他与亚兰王哈薛作战时，亚兰人击伤他的。耶户说：“你们若是同意，就不要让人逃出这城到耶斯列去报信。”'),
('CNV', '列王纪下', 12, 9, 16, '于是耶户登上战车，往耶斯列去了；因约兰正在那里卧病，犹大王亚哈谢下来探望他。'),
('CNV', '列王纪下', 12, 9, 17, '站在耶斯列城楼的哨兵看见耶户的队伍来临，就说：“我看见有一队人马。”约兰说：“叫一个骑兵来，派他去见他们，说：‘平安吗？’”'),
('CNV', '列王纪下', 12, 9, 18, '于是有一个骑兵去迎见耶户，说：“王这样问：‘平安吗？’”耶户说：“平安不平安和你有什么关系呢？转到我后面去吧！”那哨兵又报告：“使者到了他们那里，却没有回来。”'),
('CNV', '列王纪下', 12, 9, 19, '王又派第二个骑兵去。他来到他们那里，说：“王这样问：‘平安吗？’”耶户说：“平安不平安和你有什么关系呢？转到我后面去吧！”'),
('CNV', '列王纪下', 12, 9, 20, '那哨兵又报告：“他已经去到他那里，却没有回来。那驾车的手法很像宁示的孙子耶户，因为他驾车很凶猛。”'),
('CNV', '列王纪下', 12, 9, 21, '约兰就说：“备车。”他们就为他备了车。以色列王约兰和犹大王亚哈谢出城，他们各自乘坐战车出去见耶户，就在耶斯列人拿伯的田间遇上了他。'),
('CNV', '列王纪下', 12, 9, 22, '约兰看见耶户的时候，就说：“耶户，平安吗？”耶户说：“你的母亲耶洗别的淫行和邪术这么多，还有平安吗？”'),
('CNV', '列王纪下', 12, 9, 23, '约兰立刻把车调转过来逃跑，对亚哈谢说：“亚哈谢啊，反了！”'),
('CNV', '列王纪下', 12, 9, 24, '耶户拉满弓，射中约兰的背；箭从他的心窝穿出，他就倒在自己的车上。'),
('CNV', '列王纪下', 12, 9, 25, '耶户对副官毕甲说：“把他抬起来，丢在耶斯列人拿伯的田地里，因为我还记得你我一起驾车跟随他父亲亚哈的时候，耶和华曾宣告了这些有关亚哈的话：'),
('CNV', '列王纪下', 12, 9, 26, '‘昨天我实在看见了拿伯的血和他儿子们的血；我要在这块田地上报应你。’现在你要按着耶和华的话，把他抬起来丢在田里。”'),
('CNV', '列王纪下', 12, 9, 27, '犹大王亚哈谢看见这一切，就沿着通往伯哈干的路逃走。耶户紧追着他，说：“还有他！”他们就在靠近以伯莲的姑珥坡把他击伤在战车上。他逃到米吉多，就死在那里。'),
('CNV', '列王纪下', 12, 9, 28, '他的臣仆用车把他的尸体送到耶路撒冷，葬在大卫城他自己的坟墓，和他的祖先一同长眠。'),
('CNV', '列王纪下', 12, 9, 29, '亚哈的儿子约兰第十一年，亚哈谢登基统治犹大。'),
('CNV', '列王纪下', 12, 9, 30, '耶户到了耶斯列。耶洗别已经听闻，就涂眼梳头，从窗户里往外观望。'),
('CNV', '列王纪下', 12, 9, 31, '耶户进入城门的时候，她说：“平安吗，杀主的心利？”'),
('CNV', '列王纪下', 12, 9, 32, '耶户抬头对着窗户，说：“有谁拥护我？谁？”立时有两三个太监往外望着他。'),
('CNV', '列王纪下', 12, 9, 33, '他说：“把她抛下来！”他们就把她抛下去。她的血溅在墙上和马匹身上，它们也践踏了她。'),
('CNV', '列王纪下', 12, 9, 34, '耶户进入屋内，又吃又喝，然后说：“你们去料理那被咒诅的妇人，把她埋了，因为她是王的女儿。”'),
('CNV', '列王纪下', 12, 9, 35, '于是他们去收殓她，却找不到她的尸体，只找到头骨、双脚和双掌。'),
('CNV', '列王纪下', 12, 9, 36, '他们就回去，告诉他，他说：“这正是耶和华藉着他仆人提斯比人以利亚所说的话：‘野狗必在耶斯列的地方吃耶洗别的肉。’'),
('CNV', '列王纪下', 12, 9, 37, '耶洗别的尸体要像耶斯列田间的粪肥，以致人不能说：‘这是耶洗别。’”'),
('CNV', '列王纪下', 12, 10, 1, '亚哈有七十个儿子在撒玛利亚。耶户写了一批信，送到撒玛利亚，对耶斯列的首领、长老和亚哈众子的导师说：'),
('CNV', '列王纪下', 12, 10, 2, '“你们主人的儿子都在你们那里，你们也有战车、马匹、设防城和武器，那么这封信到达你们那里的时候，'),
('CNV', '列王纪下', 12, 10, 3, '你们就要看看在你们主人的儿子中，哪一个是最好最合适的，把他立在父亲的宝座上；你们又要为你们主人的家作战。”'),
('CNV', '列王纪下', 12, 10, 4, '他们就十分害怕，说：“看哪，两个王尚且不能在他面前站立得住，我们又怎能站得住呢？”'),
('CNV', '列王纪下', 12, 10, 5, '于是内务长、市长、长老和亚哈众子的导师送信给耶户说：“我们是你的仆人，你吩咐我们的，我们都必照办；我们也不会立什么人作王；你看怎样好，我们就怎样作。”'),
('CNV', '列王纪下', 12, 10, 6, '于是耶户写第二封信给他们说：“如果你们是归从我，听我的话的，就要把你们主人的儿子们的头颅取下，明天大约这个时候，带来耶斯列给我。”那时，王的七十个儿子是住在抚养他们的城中的大臣那里。'),
('CNV', '列王纪下', 12, 10, 7, '这信到达他们那里的时候，他们就拿住王的众子，把这七十人杀了，然后把他们的头放在篮子里，送到耶斯列耶户那里。'),
('CNV', '列王纪下', 12, 10, 8, '有使者来告诉耶户说：“王的众子的头送到了。”他说：“把它们分作两堆放在城门口，直到早上。”'),
('CNV', '列王纪下', 12, 10, 9, '第二天早上的时候，耶户出来，站着对众民说：“你们都是无罪的，看哪，是我自己背叛了我的主人，把他杀了，但这所有的人又是谁击杀的呢？'),
('CNV', '列王纪下', 12, 10, 10, '你们要知道耶和华的话，就是耶和华所说攻击亚哈家的话，一句也没有落空；耶和华藉着他的仆人以利亚所说的话，他都作成了。”'),
('CNV', '列王纪下', 12, 10, 11, '于是耶户击杀了亚哈家在耶斯列剩下的人，还有他所有的大臣、有关的人、祭司，没有一个给他存留。'),
('CNV', '列王纪下', 12, 10, 12, '耶户动身，往撒玛利亚去。在路上，他经过牧羊人的伯艾吉那里。'),
('CNV', '列王纪下', 12, 10, 13, '他遇见了犹大王亚哈谢的兄弟们。他说：“你们是谁？”他们说：“我们是亚哈谢的兄弟。我们下来要向王的众子和太后的众子请安。”'),
('CNV', '列王纪下', 12, 10, 14, '他说：“活捉他们！”他的手下就活捉了他们，在伯艾吉的坑边杀了他们；一共是四十二个人，没有留下一人。'),
('CNV', '列王纪下', 12, 10, 15, '他又从那里往前行，看见利甲的儿子约拿达来迎接他。耶户向他请安，然后说：“你的心对我忠诚，就像我的心对你的心一样吗？”约拿达说：“是的。”耶户说：“如果是的话，伸出你的手来。”他伸出他的手，耶户就把他拉上他的战车。'),
('CNV', '列王纪下', 12, 10, 16, '耶户说：“你和我一起去，看看我对耶和华的热诚。”于是用自己的战车载他同去。'),
('CNV', '列王纪下', 12, 10, 17, '他来到撒玛利亚，就击杀亚哈家所有在撒玛利亚剩下的人，把他们完全消灭，正如耶和华对以利亚所说的话。'),
('CNV', '列王纪下', 12, 10, 18, '耶户集合众民，对他们说：“从前亚哈信奉巴力还算是少，耶户要信奉更多。'),
('CNV', '列王纪下', 12, 10, 19, '现在，所有的巴力先知、所有信奉他的和他所有的祭司都要给我召来，不要走漏一人；因为我要向巴力献一个极大的祭，缺席的必不得活。”耶户用诡计这样行，是要除灭所有信奉巴力的人。'),
('CNV', '列王纪下', 12, 10, 20, '耶户又说：“要为巴力召开一个严肃会。”于是众人宣告召开大会。'),
('CNV', '列王纪下', 12, 10, 21, '耶户派人走遍以色列各地，所有信奉巴力的人都来了，没有一个不来的。他们都进了巴力庙，以致巴力庙从这边到那边都塞满了人。'),
('CNV', '列王纪下', 12, 10, 22, '耶户对掌管衣橱的说：“把礼服拿出来，给所有拜巴力的人穿。”他就把礼服拿出来给他们穿上。'),
('CNV', '列王纪下', 12, 10, 23, '耶户和利甲的儿子约拿达来到巴力的庙中。他对信奉巴力的人说：“搜查看看，这里不要有信奉耶和华的人和你们同在一起，只可以有信奉巴力的人。”'),
('CNV', '列王纪下', 12, 10, 24, '他们进去献祭和献燔祭。耶户布置了八十个人在外面，说：“如果我带来交在你们手中的人，有一个从他们中间逃脱了，你们就要以命抵命。”'),
('CNV', '列王纪下', 12, 10, 25, '耶户献完了燔祭，就对卫兵和军长说：“你们进去，杀死他们，一个也不让他们出来。”卫兵和军长于是用刀击杀他们，又把他们的尸体抛出去，然后往巴力庙的内室去了。'),
('CNV', '列王纪下', 12, 10, 26, '他们又把巴力庙内的神柱搬出去烧了。'),
('CNV', '列王纪下', 12, 10, 27, '他们毁坏了巴力的神柱，又拆毁了巴力庙，作为厕所，直到今日。'),
('CNV', '列王纪下', 12, 10, 28, '这样，耶户从以色列中消灭了巴力。'),
('CNV', '列王纪下', 12, 10, 29, '只是耶户没有离弃尼八的儿子耶罗波安的罪，就是他使以色列人陷于罪中的那些罪，敬拜在伯特利和但的金牛犊。'),
('CNV', '列王纪下', 12, 10, 30, '耶和华对耶户说：“因为你办好了我看为正的事，照我的一切心意对付亚哈家，你的子孙要坐在以色列的王位上，直到第四代。”'),
('CNV', '列王纪下', 12, 10, 31, '可是耶户没有尽心遵行耶和华以色列神的律法，离弃耶罗波安使以色列人陷于罪中的那些罪。'),
('CNV', '列王纪下', 12, 10, 32, '在那些日子，耶和华开始削弱以色列，哈薛在以色列各处的边境攻击他们：'),
('CNV', '列王纪下', 12, 10, 33, '从约旦河以东，基列的全地，迦得人、流本人和玛拿西人之地，从靠近亚嫩河的亚罗珥起，至基列和巴珊。'),
('CNV', '列王纪下', 12, 10, 34, '耶户其余的事迹和他所行的一切，以及他的一切英雄事迹，不是都写在以色列诸王的年代志上吗？'),
('CNV', '列王纪下', 12, 10, 35, '耶户和他的祖先同享安息，葬在撒玛利亚，他儿子约哈斯接续他作王。'),
('CNV', '列王纪下', 12, 10, 36, '耶户在撒玛利亚作王统治以色列共二十八年。'),
('CNV', '列王纪下', 12, 11, 1, '亚哈谢的母亲亚他利雅看见自己的儿子死了，就起来消灭王室所有的后裔。'),
('CNV', '列王纪下', 12, 11, 2, '但约兰王的女儿，亚哈谢的妹妹约示巴，把亚哈谢的儿子约阿施从正要被杀的王子中偷了出来，把他和他的乳母藏在卧室里面；他们把他收藏起来，躲避亚他利雅，免得他被杀死。'),
('CNV', '列王纪下', 12, 11, 3, '约阿施和他的乳母在耶和华的殿中躲藏了六年；亚他利雅却作王统治那地。'),
('CNV', '列王纪下', 12, 11, 4, '在第七年，耶何耶大派人把迦利人和卫兵的众百夫长带来，领他们进入耶和华的殿中，和他们立约，使他们在耶和华的殿里起誓，然后把王子带出来和他们见面。'),
('CNV', '列王纪下', 12, 11, 5, '他又吩咐他们说：“你们要这样作：你们在安息日值班的，三分之一要守卫王宫；'),
('CNV', '列王纪下', 12, 11, 6, '三分之一要在苏珥门；三分之一要在卫兵院的后门；你们要轮班把守王宫。'),
('CNV', '列王纪下', 12, 11, 7, '你们在安息日不用当值的两班人，要为王的缘故守卫耶和华的殿。'),
('CNV', '列王纪下', 12, 11, 8, '你们要在四周围护着王，各人手中要拿着自己的武器。擅自闯入班次的，必被处死。王出入的时候，你们要紧随左右。”'),
('CNV', '列王纪下', 12, 11, 9, '于是众百夫长照着耶何耶大祭司的一切吩咐去行。他们各自率领人马，无论在安息日值班或不用当值的，都来到耶何耶大祭司那里。'),
('CNV', '列王纪下', 12, 11, 10, '耶何耶大就把藏在耶和华殿里，属于大卫王的矛枪和盾牌交给众百夫长。'),
('CNV', '列王纪下', 12, 11, 11, '各卫兵手持兵器，从殿的右面到殿的左面，面对祭坛和殿，围绕着王侍立。'),
('CNV', '列王纪下', 12, 11, 12, '耶何耶大领王子出来，把王冠戴在他的头上，又把约书交给他。他们就拥立他为王，用膏膏他，并且拍掌，说：“愿王万岁！”'),
('CNV', '列王纪下', 12, 11, 13, '亚他利雅听见卫兵和民众的声音，就进到耶和华的殿、众民那里去。'),
('CNV', '列王纪下', 12, 11, 14, '她看见王子按着规例站在柱旁那里，首领和号手在王的旁边，当地所有的人民欢乐吹号。亚他利雅于是撕裂衣服，呼叫：“反了！反了！”'),
('CNV', '列王纪下', 12, 11, 15, '耶何耶大祭司吩咐众百夫长，就是统领军兵的，对他们说：“把她从各班军兵中赶出去，跟随她的，都要用刀杀死。”因为祭司说：“不可在耶和华的殿内杀死她。”'),
('CNV', '列王纪下', 12, 11, 16, '于是他们下手拿住她；她回到王宫的马门的时候，就在那里被人杀死。'),
('CNV', '列王纪下', 12, 11, 17, '耶何耶大又使王和人民与耶和华立约，好使他们作耶和华的人民；又使王与人民立约。'),
('CNV', '列王纪下', 12, 11, 18, '然后当地所有的人民都来到巴力庙，把它拆毁，把它的坛和像完全打碎，又在祭坛前把巴力的祭司玛坦杀了。耶何耶大祭司又设立官员管理耶和华的殿。'),
('CNV', '列王纪下', 12, 11, 19, '他又率领众百夫长、迦利人、卫兵和当地所有的人民，护送王从耶和华的殿下来，经卫兵的门进入王宫。这样，约阿施就坐上了王位。'),
('CNV', '列王纪下', 12, 11, 20, '当地所有的人民都欢乐，阖城平静；至于亚他利雅，他们在王宫用刀把她杀死了。'),
('CNV', '列王纪下', 12, 11, 21, '约阿施作王的时候，只有七岁。'),
('CNV', '列王纪下', 12, 12, 1, '耶户在位第七年，约阿施登基，在耶路撒冷作王四十年。他母亲名叫西比亚，是从别是巴来的。'),
('CNV', '列王纪下', 12, 12, 2, '在耶何耶大祭司教导他的日子，他就行耶和华看为正的事。'),
('CNV', '列王纪下', 12, 12, 3, '只是邱坛没有废去，人民仍在邱坛献祭焚香。'),
('CNV', '列王纪下', 12, 12, 4, '约阿施对众祭司说：“所有分别为圣，奉到耶和华殿里的银子，或是各被数点之人的赎价，或是各种的赎价，或是各人随着心意，奉到耶和华殿里的银子，'),
('CNV', '列王纪下', 12, 12, 5, '各祭司可向自己熟悉的人收取。他们要修理殿内毁坏的地方，就是一切发现有毁坏的地方。”'),
('CNV', '列王纪下', 12, 12, 6, '可是到了约阿施王在位二十三年的时候，祭司还未修好圣殿毁坏的地方。'),
('CNV', '列王纪下', 12, 12, 7, '于是约阿施王召了耶何耶大祭司和众祭司来，说：“你们为什么不修理圣殿毁坏的地方呢？现在不要向你们熟识的人收取银子，却要把所收的交出来，修理圣殿毁坏的地方。”'),
('CNV', '列王纪下', 12, 12, 8, '众祭司答应不再从人民收取银子，也不修理圣殿毁坏的地方。'),
('CNV', '列王纪下', 12, 12, 9, '耶何耶大祭司搬来了一个箱子，在它的顶上钻了一个孔，把它放在祭坛旁边，在圣殿入口的右边。守门的祭司把奉到耶和华殿所有的银子都投进箱里。'),
('CNV', '列王纪下', 12, 12, 10, '他们看见箱内的银子多起来的时候，就叫王的书记和大祭司上来，他们就数点在耶和华殿里所得的银子，装在袋中。'),
('CNV', '列王纪下', 12, 12, 11, '他们把所称的银子交在耶和华殿中管理工匠的监工手里，然后他们支付给在耶和华殿作工的木匠和建筑工人，'),
('CNV', '列王纪下', 12, 12, 12, '以及泥匠和石匠；又用来购买木材和凿好的石头，来修理耶和华殿里毁坏的地方，以及支付一切修理耶和华殿的开支。'),
('CNV', '列王纪下', 12, 12, 13, '但耶和华殿里的银杯、烛剪、碗、号或任何金银器皿，都没有用奉到耶和华殿里的银子来做。'),
('CNV', '列王纪下', 12, 12, 14, '他们只把银子交给工匠，用来修理耶和华殿里毁坏的地方。'),
('CNV', '列王纪下', 12, 12, 15, '他们没有要求经手把银子转付工匠的人交代帐目，因为他们办事诚实。'),
('CNV', '列王纪下', 12, 12, 16, '但是赎愆祭和赎罪祭的银子，他们没有奉入耶和华的殿，这些银子是属于祭司的。'),
('CNV', '列王纪下', 12, 12, 17, '那时亚兰王哈薛上来，攻打迦特，把它夺取了。他又决心上来攻打耶路撒冷。'),
('CNV', '列王纪下', 12, 12, 18, '犹大王约阿施于是拿出所有的圣物，就是他的祖先犹大王约沙法、约兰和亚哈谢所献的圣物，以及他自己所献的圣物，还有耶和华殿和王宫宝库里所有的金子，送给亚兰王哈薛，哈薛就离开耶路撒冷去了。'),
('CNV', '列王纪下', 12, 12, 19, '约阿施其余的事迹和他所行的一切，不是都写在犹大列王的年代志上吗？'),
('CNV', '列王纪下', 12, 12, 20, '约阿施的臣仆起来背叛，他们在米罗宫内，他下到悉拉的时候，击杀了他。'),
('CNV', '列王纪下', 12, 12, 21, '他的臣仆示米押的儿子约撒甲和朔默的儿子约萨拔击杀他，他就死了。人把他埋葬在大卫城，和他的祖先在一起。他的儿子亚玛谢接续他作王。'),
('CNV', '列王纪下', 12, 13, 1, '犹大王亚哈谢的儿子约阿施在位第二十三年，耶户的儿子约哈斯在撒玛利亚登基，统治以色列共十七年。'),
('CNV', '列王纪下', 12, 13, 2, '他行耶和华看为恶的事，随从尼八的儿子耶罗波安使以色列人陷于罪中的那些罪，不肯转离。'),
('CNV', '列王纪下', 12, 13, 3, '于是耶和华的怒气向以色列发作，常把他们交在亚兰王哈薛的手中和哈薛的儿子便．哈达的手中。'),
('CNV', '列王纪下', 12, 13, 4, '约哈斯恳求耶和华，耶和华垂听他的祷告，因为看见了以色列所受的压迫，就是亚兰王对他们的压迫。'),
('CNV', '列王纪下', 12, 13, 5, '耶和华就赐给以色列一位拯救者，他救他们脱离亚兰王的手，于是以色列人可以在自己的家安居，好像以前一样。'),
('CNV', '列王纪下', 12, 13, 6, '可是他们没有离开耶罗波安家使以色列人陷于罪中的那些罪，仍然行在罪中；亚舍拉依然立在撒玛利亚。'),
('CNV', '列王纪下', 12, 13, 7, '于是耶和华没有给约哈斯留下余民，只剩下骑兵五十人，战车十辆和步兵一万人，因为亚兰王毁灭他们，践踏他们好像禾场上的尘土。'),
('CNV', '列王纪下', 12, 13, 8, '约哈斯其余的事迹和他所行的一切，以及他的英勇事迹，不是都写在以色列诸王的年代志上吗？'),
('CNV', '列王纪下', 12, 13, 9, '约哈斯和他的祖先一同长眠，葬在撒玛利亚。他的儿子约阿施接续他作王。'),
('CNV', '列王纪下', 12, 13, 10, '犹大王约阿施在位第三十七年，约哈斯的儿子约阿施在撒玛利亚登基，统治以色列共十六年。'),
('CNV', '列王纪下', 12, 13, 11, '他行耶和华看为恶的事，不转离尼八的儿子耶罗波安使以色列人陷于罪中的一切罪，仍然行在罪中。'),
('CNV', '列王纪下', 12, 13, 12, '约阿施其余的事迹和他所行的一切，以及他与犹大王亚玛谢作战时的英勇事迹，不是都写在以色列诸王的年代志上吗？'),
('CNV', '列王纪下', 12, 13, 13, '约阿施和他的祖先一同长眠后，耶罗波安坐上了他的王位。他把约阿施葬在撒玛利亚，和以色列诸王在一起。'),
('CNV', '列王纪下', 12, 13, 14, '以利沙患了必死的病。以色列王约阿施下到他那里，伏在他的脸上哭，说：“父啊，父啊！以色列的战车和骑兵啊！”'),
('CNV', '列王纪下', 12, 13, 15, '以利沙对他说：“拿弓箭来！”他就把弓箭拿给他。'),
('CNV', '列王纪下', 12, 13, 16, '他对以色列王说：“把你的手放在弓上吧！”他就把手放在弓上，以利沙又把自己的手放在王的手上。'),
('CNV', '列王纪下', 12, 13, 17, '他说：“打开向东的窗户。”他就打开了。以利沙说：“放箭吧！”他就放箭。以利沙说：“这是耶和华胜利的箭，耶和华得胜亚兰人的箭。你要在亚弗击杀亚兰人，直到完全灭绝。”'),
('CNV', '列王纪下', 12, 13, 18, '他又说：“拿箭来！”他就拿了来。他对以色列王说：“你击打地吧！”他就击打地，打了三次就站起来了。'),
('CNV', '列王纪下', 12, 13, 19, '神人就对他发怒，说：“你应该击打五次或者六次，那样就能打败亚兰人，直到完全消灭他们。现在，你只可以打败亚兰人三次了。”'),
('CNV', '列王纪下', 12, 13, 20, '以利沙死了，也埋葬了。摩押人常在每年春天入侵以色列地。'),
('CNV', '列王纪下', 12, 13, 21, '有人正在埋葬死人的时候，看见一群来侵略的人，他们就把死尸丢在以利沙的坟上，随即走了。死尸碰着以利沙的骨头就复活了，双脚站了起来。'),
('CNV', '列王纪下', 12, 13, 22, '约哈斯在位的日子，亚兰王哈薛一直都欺压以色列。'),
('CNV', '列王纪下', 12, 13, 23, '但耶和华仍然施恩给他们，怜悯他们，眷顾他们，这是因为他与亚伯拉罕、以撒和雅各所立的约，不愿意毁灭他们，把他们从自己的面前丢弃，直到今日。'),
('CNV', '列王纪下', 12, 13, 24, '亚兰王哈薛死了，他的儿子便．哈达接续他作王。'),
('CNV', '列王纪下', 12, 13, 25, '约哈斯的儿子约阿施从哈薛的儿子便．哈达手中，把哈薛在战争时从约阿施的父亲约哈斯手中夺去的城市收复。约阿施三次打败便．哈达，收复以色列的城市。'),
('CNV', '列王纪下', 12, 14, 1, '以色列王约哈斯的儿子约阿施在位第二年，犹大王约阿施的儿子亚玛谢登基作王。'),
('CNV', '列王纪下', 12, 14, 2, '他登基的时候是二十五岁，在耶路撒冷作王共二十九年。他母亲名叫约耶但，是从耶路撒冷来的。'),
('CNV', '列王纪下', 12, 14, 3, '他行耶和华看为正的事；只是不像他的祖先大卫，却是照着他父亲约阿施所行的一切去行。'),
('CNV', '列王纪下', 12, 14, 4, '只是邱坛还没有废去，人民仍在邱坛献祭焚香。'),
('CNV', '列王纪下', 12, 14, 5, '当国家在他手中稳定以后，他就把那些击杀他父王的臣仆杀了。'),
('CNV', '列王纪下', 12, 14, 6, '但他们的儿子没有处死，这是按照摩西律法书上所写，是耶和华的吩咐：“不可因儿子的罪处死父亲，也不可因父亲的罪处死儿子；各人要因自己的罪而死。”'),
('CNV', '列王纪下', 12, 14, 7, '他在盐谷击杀了一万以东人，又攻取了西拉，然后把它的名字改称为约帖，直到今日。'),
('CNV', '列王纪下', 12, 14, 8, '那时，亚玛谢派使者去见耶户的孙子、约哈斯的儿子以色列王约阿施说：“来，我们在战场相见吧！”'),
('CNV', '列王纪下', 12, 14, 9, '以色列王约阿施派人去见犹大王亚玛谢说：“黎巴嫩的蒺藜派人去见黎巴嫩的香柏树说：‘请你把你的女儿给我的儿子作妻子吧！’后来有黎巴嫩的野兽经过，就把蒺藜踩倒了。'),
('CNV', '列王纪下', 12, 14, 10, '不错，你打败了以东人，你的心就高傲。你尽管自己夸耀，安坐家中就是了。为什么要惹祸，使你覆亡，也使犹大跟你一起覆亡呢？”'),
('CNV', '列王纪下', 12, 14, 11, '但是亚玛谢不听他的话。于是以色列王约阿施上来，和犹大王亚玛谢在属犹大的伯．示麦相见。'),
('CNV', '列王纪下', 12, 14, 12, '犹大人被以色列人击败，各人逃回自己的家去了。'),
('CNV', '列王纪下', 12, 14, 13, '以色列王约阿施在伯．示麦捉住了亚哈谢的孙子、约阿施的儿子犹大王亚玛谢。他们来到耶路撒冷，拆毁了耶路撒冷一段城墙，从以法莲门直到角门，共两百公尺。'),
('CNV', '列王纪下', 12, 14, 14, '又掠去耶和华殿里和王宫的宝库里找到的所有金子、银子和一切器皿，还有人质，就回撒玛利亚去了。'),
('CNV', '列王纪下', 12, 14, 15, '约阿施其余的事迹和他的英勇事迹，就是与犹大王亚玛谢作战的事，不是都写在以色列诸王的年代志上吗？'),
('CNV', '列王纪下', 12, 14, 16, '约阿施和他的祖先一同长眠，他和以色列诸王一样，葬在撒玛利亚。他的儿子耶罗波安接续他作王。'),
('CNV', '列王纪下', 12, 14, 17, '以色列王约哈斯的儿子约阿施死后，犹大王约阿施的儿子亚玛谢仍活了十五年。'),
('CNV', '列王纪下', 12, 14, 18, '亚玛谢其余的事迹不是都写在犹大列王的年代志上吗？'),
('CNV', '列王纪下', 12, 14, 19, '在耶路撒冷有人阴谋反叛他，他就逃到拉吉去。他们派人跟踪他到拉吉，就在那里把他杀死了。'),
('CNV', '列王纪下', 12, 14, 20, '他们把他的尸首驮在马背上运回来，葬在耶路撒冷，在大卫的城里，和他的祖先在一起。'),
('CNV', '列王纪下', 12, 14, 21, '犹大的众民选立了亚撒利雅；他只有十六岁，他们就立他接续他父亲亚玛谢作王。'),
('CNV', '列王纪下', 12, 14, 22, '亚玛谢和他的祖先一同长眠以后，亚撒利雅重建了以拉他，并且收归犹大。'),
('CNV', '列王纪下', 12, 14, 23, '犹大王约阿施的儿子亚玛谢十五年，以色列王约阿施的儿子耶罗波安在撒玛利亚登基，他作王共四十一年。'),
('CNV', '列王纪下', 12, 14, 24, '他行耶和华看为恶的事，不转离尼八的儿子耶罗波安使以色列人陷于罪中的一切罪。'),
('CNV', '列王纪下', 12, 14, 25, '他收复以色列的边境，从哈马口直到亚拉巴海，正如耶和华以色列的神的话，就是藉着他的仆人迦特希弗人亚米太的儿子约拿先知所说的；'),
('CNV', '列王纪下', 12, 14, 26, '因为耶和华看见以色列十分艰苦，无论是自由的或为奴的都没有了，也没有帮助以色列的。'),
('CNV', '列王纪下', 12, 14, 27, '耶和华没有定命要将以色列的名从天下涂抹，所以藉着约阿施的儿子耶罗波安的手拯救他们。'),
('CNV', '列王纪下', 12, 14, 28, '耶罗波安其余的事迹和他所行的一切，以及他作战时的英勇，怎样收复大马士革和原属犹大的哈马归以色列，不是都写在以色列诸王的年代志上吗？'),
('CNV', '列王纪下', 12, 14, 29, '耶罗波安和他的祖先以色列诸王一同长眠。他的儿子撒迦利雅就接续他作王。'),
('CNV', '列王纪下', 12, 15, 1, '以色列王耶罗波安在位第二十七年，犹大王亚玛谢的儿子亚撒利雅登基作王。'),
('CNV', '列王纪下', 12, 15, 2, '他登基的时候才十六岁，他在耶路撒冷作王五十二年。他母亲名叫耶可利雅，是来自耶路撒冷的。'),
('CNV', '列王纪下', 12, 15, 3, '他行耶和华看为正的事，就像他父亲亚玛谢所行的一切。'),
('CNV', '列王纪下', 12, 15, 4, '只是邱坛还没有废去，人民仍在邱坛献祭焚香。'),
('CNV', '列王纪下', 12, 15, 5, '耶和华击打王，他就患了痲风病，直到他死的日子。于是他住在隔离的房子，他的儿子约坦执掌朝务，治理国民。'),
('CNV', '列王纪下', 12, 15, 6, '亚撒利雅其余的事迹和他所行的一切，不是都写在犹大列王的年代志上吗？'),
('CNV', '列王纪下', 12, 15, 7, '亚撒利雅和他的祖先一同长眠，葬在大卫的城，和他的祖先在一起。他的儿子约坦接续他作王。'),
('CNV', '列王纪下', 12, 15, 8, '犹大王亚撒利雅在位第三十八年，耶罗波安的儿子撒迦利雅在撒玛利亚登基，统治以色列共六个月。'),
('CNV', '列王纪下', 12, 15, 9, '他行耶和华看为恶的事，好像他祖先所行的，没有转离尼八的儿子耶罗波安使以色列人陷于罪中的那些罪。'),
('CNV', '列王纪下', 12, 15, 10, '雅比的儿子沙龙阴谋反叛他，在人民面前把他杀死，接续他作王。'),
('CNV', '列王纪下', 12, 15, 11, '撒迦利雅其余的事迹，看哪，都写在以色列诸王的年代志上。'),
('CNV', '列王纪下', 12, 15, 12, '这就是耶和华曾论到有关耶户的话说：“你的子孙必坐在以色列的王位上，直到第四代。”这话果然应验了。'),
('CNV', '列王纪下', 12, 15, 13, '犹大王乌西雅在位第三十九年，雅比的儿子沙龙登基作王；他在撒玛利亚作王一个月。'),
('CNV', '列王纪下', 12, 15, 14, '迦底的儿子米拿现从得撒上去，到撒玛利亚攻击雅比人沙龙，把他杀死，接续他作王。'),
('CNV', '列王纪下', 12, 15, 15, '沙龙其余的事迹和他反叛的经过，看哪，都写在以色列诸王的年代志上。'),
('CNV', '列王纪下', 12, 15, 16, '那时，米拿现从得撒开始，攻打提斐萨和城中所有的人，以及它的四境；因为他们不给他打开城门，所以他攻击它，把所有的孕妇剖腹。'),
('CNV', '列王纪下', 12, 15, 17, '犹大王亚撒利雅在位第三十九年，迦底的儿子米拿现在撒玛利亚登基，统治以色列共十年。'),
('CNV', '列王纪下', 12, 15, 18, '他行耶和华看为恶的事，他在位的日子，没有转离尼八的儿子耶罗波安使以色列人陷于罪中的那些罪。'),
('CNV', '列王纪下', 12, 15, 19, '亚述王普勒来攻打以色列地，米拿现给普勒三万公斤银子，请普勒帮助他坚固王位。'),
('CNV', '列王纪下', 12, 15, 20, '米拿现向以色列人，就是所有大财主强索银子，每人五百七十克，好献给亚述王。于是亚述王回去了，不在以色列地停留。'),
('CNV', '列王纪下', 12, 15, 21, '米拿现其余的事迹和他所行的一切，不是都写在以色列诸王的年代志上吗？'),
('CNV', '列王纪下', 12, 15, 22, '米拿现和他的祖先一同长眠，他的儿子比加辖接续他作王。'),
('CNV', '列王纪下', 12, 15, 23, '犹大王亚撒利雅在位第五十年，米拿现的儿子比加辖在撒玛利亚登基，统治以色列二年。'),
('CNV', '列王纪下', 12, 15, 24, '他行耶和华看为恶的事，不转离尼八的儿子耶罗波安使以色列人陷于罪中的那些罪。'),
('CNV', '列王纪下', 12, 15, 25, '比加辖的军长，利玛利的儿子比加阴谋背叛他，在撒玛利亚王宫的卫所击杀他；与比加同谋的，有亚珥歌伯和亚利耶，以及和他一起的五十个基列人；比加把他杀死，接续他作王。'),
('CNV', '列王纪下', 12, 15, 26, '比加辖其余的事迹和他所行的一切，看哪，都写在以色列诸王的年代志上。'),
('CNV', '列王纪下', 12, 15, 27, '犹大王亚撒利雅在位第五十二年，利玛利的儿子比加在撒玛利亚作王统治以色列共二十年。'),
('CNV', '列王纪下', 12, 15, 28, '他行耶和华看为恶的事，不转离尼八的儿子耶罗波安使以色列人陷于罪中的那些罪。'),
('CNV', '列王纪下', 12, 15, 29, '以色列王比加在位的日子，亚述王提革拉．毗列色前来，攻取了以云、亚伯．伯．玛迦、亚挪、基低斯、夏琐、基列、加利利和拿弗他利全地，把居民掳到亚述去。'),
('CNV', '列王纪下', 12, 15, 30, '乌西雅的儿子约坦在位第二十年，以拉的儿子何细亚阴谋背叛利玛利的儿子比加，击打他，把他杀死，接续他作王。'),
('CNV', '列王纪下', 12, 15, 31, '比加其余的事迹和他所行的一切，看哪，都写在以色列诸王的年代志上。'),
('CNV', '列王纪下', 12, 15, 32, '以色列王利玛利的儿子比加在位第二年，乌西雅的儿子约坦登基作犹大王。'),
('CNV', '列王纪下', 12, 15, 33, '他登基的时候是二十五岁，在耶路撒冷作王十六年。他母亲名叫耶路沙，是撒督的女儿。'),
('CNV', '列王纪下', 12, 15, 34, '他行耶和华看为正的事，效法他父亲乌西雅一切所行的。'),
('CNV', '列王纪下', 12, 15, 35, '只是他没有把邱坛废去，国民仍在邱坛献祭焚香。他就是那建造耶和华殿的上门的。'),
('CNV', '列王纪下', 12, 15, 36, '约坦所行其余的事迹，不是都写在犹大列王的年代志上吗？'),
('CNV', '列王纪下', 12, 15, 37, '在那些日子，耶和华开始派遣亚兰王利汛和利玛利的儿子比加去攻击犹大。'),
('CNV', '列王纪下', 12, 15, 38, '约坦和他的祖先一同长眠，也和他的祖先葬在一起，在他祖宗大卫的城里。他的儿子亚哈斯接续他作王。'),
('CNV', '列王纪下', 12, 16, 1, '利玛利的儿子比加在位第十七年，犹大王约坦的儿子亚哈斯登基作王。'),
('CNV', '列王纪下', 12, 16, 2, '亚哈斯登基的时候是二十岁，他在耶路撒冷作王十六年。但是他不像他祖宗大卫行耶和华他的神看为正的事，'),
('CNV', '列王纪下', 12, 16, 3, '反倒跟随以色列诸王的道路，甚至焚烧他的儿子为祭，好像耶和华在以色列人面前驱逐的外族人所行可憎恶的事，'),
('CNV', '列王纪下', 12, 16, 4, '并且在邱坛上，在山冈上和所有青翠的树下献祭和焚香。'),
('CNV', '列王纪下', 12, 16, 5, '那时，亚兰王利汛与以色列王利玛利的儿子比加上来攻打耶路撒冷。他们把亚哈斯围困起来，却不能战胜他。'),
('CNV', '列王纪下', 12, 16, 6, '当时，亚兰王利汛收复以拉他归与亚兰。他把犹大人逐出以拉他，亚兰人来到以拉他住在那里，直到今日。'),
('CNV', '列王纪下', 12, 16, 7, '于是亚哈斯差派使者去见亚述王提革拉．毗列色，说：“我是你的臣仆，你的儿子，求你上来，救我脱离那起来攻击我的亚兰王和以色列王的手。”'),
('CNV', '列王纪下', 12, 16, 8, '亚哈斯拿耶和华殿里和王宫宝库内找到的金子和银子，送给亚述王作礼物。'),
('CNV', '列王纪下', 12, 16, 9, '于是亚述王答应了他。亚述王上去攻打大马士革，把城攻取，把居民掳到吉珥，又把利汛杀死了。'),
('CNV', '列王纪下', 12, 16, 10, '亚哈斯王到大马士革会见亚述王提革拉．毗列色，看见在大马士革的祭坛。亚哈斯王就派人把祭坛的图样、结构和详尽的做法送到乌利亚祭司那里。'),
('CNV', '列王纪下', 12, 16, 11, '于是乌利亚祭司按着亚哈斯王从大马士革送回来的一切指示建造祭坛。在亚哈斯王从大马士革回来以前，乌利亚祭司就照样做了。'),
('CNV', '列王纪下', 12, 16, 12, '王从大马士革回来，看见了那祭坛，于是王走到祭坛旁边，登上台阶，'),
('CNV', '列王纪下', 12, 16, 13, '烧他的燔祭和素祭，又浇上他的奠祭，并且把他的平安祭牲的血洒在祭坛上。'),
('CNV', '列王纪下', 12, 16, 14, '至于耶和华面前的铜祭坛，他把它从殿前，从新坛与耶和华殿中间移至新坛的北边。'),
('CNV', '列王纪下', 12, 16, 15, '亚哈斯王吩咐乌利亚祭司说：“要在这大祭坛上焚烧早晨的燔祭、黄昏的素祭、王的燔祭牲和素祭、所有国民的燔祭和素祭；也要在坛上浇上他们的奠祭，以及所有燔祭牲和平安祭牲的血。至于铜祭坛，我要用来求问神。”'),
('CNV', '列王纪下', 12, 16, 16, '乌利亚祭司就照着亚哈斯王一切所吩咐的去行。'),
('CNV', '列王纪下', 12, 16, 17, '亚哈斯又砍掉盆座的边缘，把洗濯盆拿下来，又把铜海从驮着铜海的铜牛上取下来，放在铺了石的地上。'),
('CNV', '列王纪下', 12, 16, 18, '又因亚述王的缘故，他把耶和华殿里为安息日而建造的廊子，和王从外边进殿的廊子，从耶和华的殿内拆除。'),
('CNV', '列王纪下', 12, 16, 19, '亚哈斯所行其余的事迹，不是都写在犹大列王的年代志上吗？'),
('CNV', '列王纪下', 12, 16, 20, '亚哈斯和他的祖先一同长眠，葬在大卫城和他的祖先在一起。他的儿子希西家接续他作王。'),
('CNV', '列王纪下', 12, 17, 1, '犹大王亚哈斯在位第十二年，以拉的儿子何细亚在撒玛利亚登基，统治以色列九年。'),
('CNV', '列王纪下', 12, 17, 2, '他行耶和华看为恶的事，只是不像他以前的以色列诸王。'),
('CNV', '列王纪下', 12, 17, 3, '亚述王撒缦以色上来攻击他，他就臣服于他，并且向他进贡。'),
('CNV', '列王纪下', 12, 17, 4, '后来，亚述王发觉何细亚阴谋反叛：他曾派使者去见埃及王梭，并且不再向亚述王献上贡物，像过去每年一样。亚述王就拿住他，把他囚在牢里。'),
('CNV', '列王纪下', 12, 17, 5, '亚述王上来攻击以色列全国各地，并且到撒玛利亚来，围城三年。'),
('CNV', '列王纪下', 12, 17, 6, '何细亚在位第九年，亚述王占领了撒玛利亚，把以色列人掳到亚述去，安置他们在哈腊，在哈博河和歌散河一带，以及在玛代人的各城。'),
('CNV', '列王纪下', 12, 17, 7, '这是因为以色列人得罪了那曾带领他们从埃及王法老的手下离开埃及的耶和华他们的神，去敬畏别的神。'),
('CNV', '列王纪下', 12, 17, 8, '他们随从耶和华从以色列人面前驱逐的外族人的风俗，以及以色列诸王奉行的风俗。'),
('CNV', '列王纪下', 12, 17, 9, '以色列人暗中做了不对的事，违背耶和华他们的神，并且在他们所有的城市，从哨站到设防城，为他们自己建筑邱坛。'),
('CNV', '列王纪下', 12, 17, 10, '又在各高山顶上和每一棵青翠的树下竖立神柱和亚舍拉。'),
('CNV', '列王纪下', 12, 17, 11, '他们在各邱坛上献祭和焚香，好像耶和华从他们的面前掳去的外族人一样，又行恶事，使耶和华发怒。'),
('CNV', '列王纪下', 12, 17, 12, '他们又服事雕刻的偶像，耶和华曾警告他们不可以行这事。'),
('CNV', '列王纪下', 12, 17, 13, '耶和华曾藉着他的众先知和先见警告以色列人和犹大人说：“从你们的恶道上转回吧！谨守我的吩咐和我的律例，就是我曾吩咐你们的祖先，和藉着我的仆人众先知传递给你们的一切律法。”'),
('CNV', '列王纪下', 12, 17, 14, '可是他们不听从，反而硬着自己的颈项，好像他们的祖先，不信服耶和华他们的神；'),
('CNV', '列王纪下', 12, 17, 15, '厌弃他的律例和他与他们的祖先订立的约，以及他对他们的警戒；却信从虚无的神，自己成为虚妄，跟从他们周围的外族人，耶和华曾吩咐他们不可跟从他们的行为。'),
('CNV', '列王纪下', 12, 17, 16, '他们丢弃耶和华他们神的一切吩咐，为自己做了两个牛犊的铸像，又做亚舍拉，并且敬拜天上的万象和服事巴力；'),
('CNV', '列王纪下', 12, 17, 17, '他们又把儿女用火烧为祭，并且占卜，行法术，出卖自己去行耶和华看为恶的事，使他发怒。'),
('CNV', '列王纪下', 12, 17, 18, '于是耶和华向以色列人大大发怒，把他们从自己面前赶走，只剩下犹大一个支派。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '列王纪下', 12, 17, 19, '连犹大人也不持守耶和华他们的神的吩咐，随从以色列人所行的习俗。'),
('CNV', '列王纪下', 12, 17, 20, '耶和华就厌弃以色列人的后裔，使他们受苦，把他们交在抢掠他们的人的手中，直到把他们从自己的面前完全丢弃。'),
('CNV', '列王纪下', 12, 17, 21, '因为他自从使以色列从大卫家分裂出来后，他们就立了尼八的儿子耶罗波安作王，耶罗波安却引诱以色列人不去跟从耶和华，又使他们犯了大罪。'),
('CNV', '列王纪下', 12, 17, 22, '以色列人就随从耶罗波安所犯的一切罪恶，总不转离；'),
('CNV', '列王纪下', 12, 17, 23, '以致最后耶和华把以色列人从自己的面前赶走，就像他藉着自己的仆人众先知所说的。于是以色列人被掳离开自己的国土，往亚述去，直到今日。'),
('CNV', '列王纪下', 12, 17, 24, '亚述王从巴比伦、古他、亚瓦、哈马和西法瓦音带人来，安置在撒玛利亚的城市，代替以色列人。他们就得了撒玛利亚作产业，住在它的城市中。'),
('CNV', '列王纪下', 12, 17, 25, '他们开始在那里居住的时候，并不敬畏耶和华，所以耶和华派狮子到他们中间，咬死他们好些人。'),
('CNV', '列王纪下', 12, 17, 26, '有人告诉亚述王说：“你所掳去，安置在撒玛利亚各城市的众民族不知道当地的神的规矩，所以他派狮子到他们中间。看哪，狮子咬死他们，因为他们不知道当地的神的规矩。”'),
('CNV', '列王纪下', 12, 17, 27, '于是亚述王下令：“我从那里掳来的祭司中，要叫一个回到那里去。他要去住在那里，教导他们当地的神的规矩。”'),
('CNV', '列王纪下', 12, 17, 28, '于是从撒玛利亚被掳来的祭司中，有一个回去，住在伯特利，教导他们怎样敬畏耶和华。'),
('CNV', '列王纪下', 12, 17, 29, '但各族的人仍然制造自己的神像，安放在撒玛利亚人所造各邱坛的庙中；各族人在他们所居住的城市都这样作。'),
('CNV', '列王纪下', 12, 17, 30, '巴比伦人做了疏割．比讷像，古他人做了匿甲像，哈马人做了亚示玛像，'),
('CNV', '列王纪下', 12, 17, 31, '亚瓦人做了匿哈和他珥他像，西法瓦音人用火焚烧自己的儿女，献给西法瓦音的神亚得米勒和亚拿米勒。'),
('CNV', '列王纪下', 12, 17, 32, '他们也惧怕耶和华，所以从他们中间选立邱坛的祭司，替他们在邱坛的庙里献祭。'),
('CNV', '列王纪下', 12, 17, 33, '他们既惧怕耶和华，又服事他们的神；从哪个民族掳来的，就按照哪个民族的习俗服事他们的神。'),
('CNV', '列王纪下', 12, 17, 34, '直到今日，他们仍是按照他们初时的习俗去行；他们不敬畏耶和华，行事不按他们的规例和典章，也不按耶和华曾吩咐雅各的子孙的律法和诫命。耶和华曾给雅各起名为以色列。'),
('CNV', '列王纪下', 12, 17, 35, '耶和华曾经和他们立约，又吩咐他们说：“你们不可崇敬别的神，不可跪拜他们，不可服事他们，也不可向他们献祭。'),
('CNV', '列王纪下', 12, 17, 36, '但那曾用大能和伸出的膀臂把你们从埃及地领出来的耶和华，你们应当敬畏他，跪拜他和向他献祭。'),
('CNV', '列王纪下', 12, 17, 37, '他写给你们的律例、典章、律法和诫命，你们要永远谨守遵行，不要崇敬别的神。'),
('CNV', '列王纪下', 12, 17, 38, '我和你们所立的约你们不可忘记，不要崇敬别的神。'),
('CNV', '列王纪下', 12, 17, 39, '但要敬畏耶和华你们的神，他必救你们脱离所有仇敌的手。”'),
('CNV', '列王纪下', 12, 17, 40, '可是他们没有听从，仍然照着他们起初的习俗去行。'),
('CNV', '列王纪下', 12, 17, 41, '这样，这些民族一方面敬畏耶和华；另一方面又继续服事他们的偶像。他们的子子孙孙继续照着他们的祖先所行的去行，直到今日。'),
('CNV', '列王纪下', 12, 18, 1, '以色列王以拉的儿子何细亚在位第三年，犹大王亚哈斯的儿子希西家登基作王。'),
('CNV', '列王纪下', 12, 18, 2, '他登基的时候是二十五岁；他在耶路撒冷作王二十九年，他母亲名叫亚比，是撒迦利雅的女儿。'),
('CNV', '列王纪下', 12, 18, 3, '他行耶和华看为正的事，效法他的祖宗大卫一切所行的。'),
('CNV', '列王纪下', 12, 18, 4, '他废去邱坛，打碎神柱，砍掉亚舍拉；他又打碎摩西所做的铜蛇，因为直到那些日子，以色列人仍然向它焚香，称它作尼忽士但。'),
('CNV', '列王纪下', 12, 18, 5, '他倚靠耶和华以色列的神，在他以前或以后的犹大列王中，没有像他的。'),
('CNV', '列王纪下', 12, 18, 6, '他忠于耶和华，没有转离不跟从他，谨守他的吩咐，就是他曾吩咐摩西的。'),
('CNV', '列王纪下', 12, 18, 7, '耶和华和他同在，他所有的征战都得到成功。他背叛亚述王，不再臣服他。'),
('CNV', '列王纪下', 12, 18, 8, '他攻击非利士人，直到迦萨和它的四境，从哨站以至设防城。'),
('CNV', '列王纪下', 12, 18, 9, '希西家王在位第四年，就是以色列王以拉的儿子何细亚在位第七年，亚述王撒缦以色上来攻击撒玛利亚，把城围困；'),
('CNV', '列王纪下', 12, 18, 10, '过了三年，他们就攻取了撒玛利亚。希西家在位第六年，就是以色列王何细亚在位第九年，撒玛利亚被攻取了。'),
('CNV', '列王纪下', 12, 18, 11, '亚述王把以色列人掳到亚述去，把他们安置在哈腊、哈博河和歌散河，以及玛代人的城里；'),
('CNV', '列王纪下', 12, 18, 12, '这是因为他们不听从耶和华他们神的话，违背他的约；耶和华的仆人摩西吩咐的一切，他们都不听从，不遵行。'),
('CNV', '列王纪下', 12, 18, 13, '希西家王在位第十四年，亚述王西拿基立上来攻击犹大所有的设防城，占据了它们。'),
('CNV', '列王纪下', 12, 18, 14, '犹大王希西家派人往拉吉去见亚述王说：“我有罪了，请你离我回去吧，你们加于我的处分，我必承当。”于是亚述王罚了犹大王希西家九千公斤银子和九百公斤金子。'),
('CNV', '列王纪下', 12, 18, 15, '希西家就把耶和华殿和王宫宝库内找到的所有金子都给了他。'),
('CNV', '列王纪下', 12, 18, 16, '那时，犹大王希西家把耶和华殿门上和自己包在门柱上的金子，都刮了下来，给了亚述王。'),
('CNV', '列王纪下', 12, 18, 17, '亚述王从拉吉派他珥探、拉伯撒利和拉伯沙基率领大军，往耶路撒冷，到希西家王那里去。他们就上来，去到耶路撒冷。他们到达以后，就站在上池的引水道旁，在漂布地的大路上。'),
('CNV', '列王纪下', 12, 18, 18, '他们呼叫王；希勒家的儿子王宫总管以利亚敬、书记舍伯那和亚萨的儿子史官约亚就出来见他们。'),
('CNV', '列王纪下', 12, 18, 19, '拉伯沙基对他们说：“你们要对希西家说：‘亚述大王这样说：你所倚赖的这种防御算是什么呢？'),
('CNV', '列王纪下', 12, 18, 20, '你说有作战的智谋和能力，只是嘴上空言，现在你倚赖谁才背叛我呢？'),
('CNV', '列王纪下', 12, 18, 21, '你看，你倚赖埃及这压伤的芦苇做的手杖，人若是倚靠它，它必刺入他的手，把手刺伤，埃及王法老对所有倚赖他的人正是这样。'),
('CNV', '列王纪下', 12, 18, 22, '如果你们对我说：我们倚靠的是耶和华我们的神，希西家不是曾把他的邱坛和祭坛废去，又对犹大人和耶路撒冷人说：你们要在耶路撒冷这祭坛前敬拜吗？'),
('CNV', '列王纪下', 12, 18, 23, '现在，你可以和我主亚述王打赌，我给你二千匹战马，看你能否派出骑兵来骑它们？'),
('CNV', '列王纪下', 12, 18, 24, '否则，你怎能使我主最小的一位臣仆转脸逃跑呢？你竟然倚赖埃及供应战车和战马吗？'),
('CNV', '列王纪下', 12, 18, 25, '现在，我上来攻击这地方，要毁灭它，不是有耶和华的意思吗？耶和华曾对我说：上去攻击那地，把它毁灭。’”'),
('CNV', '列王纪下', 12, 18, 26, '希勒家的儿子以利亚敬、舍伯那和约亚对拉伯沙基说：“请用亚兰语和你的仆人们说话，因为我们听得懂；不要用犹大语和我们说话，免得传入在城墙上的人民的耳中。”'),
('CNV', '列王纪下', 12, 18, 27, '拉伯沙基对他们说：“我主派我来，只是对你的主和你说这些话吗？不也是对坐在城墙上，和你们在一起吃自己的粪、喝自己的尿的人民说的吗？”'),
('CNV', '列王纪下', 12, 18, 28, '于是拉伯沙基站着，用犹大语大声喊着，说：“你们要听亚述大王的话。'),
('CNV', '列王纪下', 12, 18, 29, '王这样说：‘不要给希西家欺骗了你们，因为他不能从我的手中解救你们；'),
('CNV', '列王纪下', 12, 18, 30, '也不要让希西家欺骗你们去信赖耶和华说：耶和华一定会解救我们，这城必不会交在亚述王的手中。'),
('CNV', '列王纪下', 12, 18, 31, '不要听从希西家，因为亚述王这样说：你们要与我和好，出来向我投降，各人就可以吃自己的葡萄树和无花果树的果子，喝自己水池里的水。'),
('CNV', '列王纪下', 12, 18, 32, '直到我来带你们到一个像你们国家的地方，那地方有五谷新酒，粮食和葡萄园，橄榄树和蜂蜜，你们必可以活着，不会死亡。不要听从希西家，因为他误导你们说：耶和华必解救我们。'),
('CNV', '列王纪下', 12, 18, 33, '列国的神真能解救他们的国土脱离亚述王的手吗？'),
('CNV', '列王纪下', 12, 18, 34, '哈马和亚珥拔的神在哪里呢？西法瓦音、希拿和以瓦的神在哪里呢？他们可以解救撒玛利亚脱离我的手吗？'),
('CNV', '列王纪下', 12, 18, 35, '这些国家所有的神，有哪一个曾解救他自己的国家脱离我的手呢？难道耶和华能解救耶路撒冷脱离我的手吗？’”'),
('CNV', '列王纪下', 12, 18, 36, '众民都不出声，一句话也不回答他，因为王吩咐他们：“不要回答他。”'),
('CNV', '列王纪下', 12, 18, 37, '当时王宫总管希勒家的儿子以利亚敬、书记舍伯那和亚萨的儿子史官约亚来到希西家那里，他们的衣服都撕裂了，他们把拉伯沙基的话都告诉了他。'),
('CNV', '列王纪下', 12, 19, 1, '希西家王听见了，就把自己的衣服撕裂，披上麻布，来到耶和华的殿。'),
('CNV', '列王纪下', 12, 19, 2, '王又派王宫总管以利亚敬、书记舍伯那和祭司中的长老披上麻布，到亚摩斯的儿子以赛亚先知那里。'),
('CNV', '列王纪下', 12, 19, 3, '他们对他说：“希西家这样说：‘今天是痛苦、责罚和侮辱的日子，好像婴儿的产期到了，却没有力量生产。'),
('CNV', '列王纪下', 12, 19, 4, '或者耶和华你的神听到拉伯沙基所说的话，就因着耶和华你的神所听见的话责罚他。所以请为这里余剩的人献上祷告。’”'),
('CNV', '列王纪下', 12, 19, 5, '希西家王的臣仆就来到以赛亚那里。'),
('CNV', '列王纪下', 12, 19, 6, '以赛亚对他们说：“你们要这样告诉你们的主人：‘耶和华这样说：不要因你所听见亚述王的随从亵渎我的话而惊怕。'),
('CNV', '列王纪下', 12, 19, 7, '看哪，我要使他的心惊颤，他将听见消息，就退回自己的地方去；我要使他在自己的国土倒在刀下。’”'),
('CNV', '列王纪下', 12, 19, 8, '拉伯沙基回去，发觉亚述王正在攻打立拿，因为他曾听说亚述王已拔营离开拉吉。'),
('CNV', '列王纪下', 12, 19, 9, '亚述王听见有关古实王特哈加的消息说：“看哪，他出来要和你交战。”于是亚述王再派使者去见希西家说：'),
('CNV', '列王纪下', 12, 19, 10, '“你们要对犹大王希西家说：‘不要让你所信靠的神欺骗你说：耶路撒冷不会交在亚述王的手中。'),
('CNV', '列王纪下', 12, 19, 11, '看哪，你听过亚述列王怎样对付列国，把它们完全毁灭，你会得着解救吗？'),
('CNV', '列王纪下', 12, 19, 12, '我祖先所消灭的民族，就是歌散人、哈兰人、利色人和在提．拉撒的伊甸人，他们的神可曾解救他们吗？'),
('CNV', '列王纪下', 12, 19, 13, '哈马王、亚珥拔王、西法瓦音城的王、希拿王和以瓦王在哪里呢？’”'),
('CNV', '列王纪下', 12, 19, 14, '希西家从使者手中接过信件，念完了，就上耶和华的殿。希西家把信件在耶和华面前展开。'),
('CNV', '列王纪下', 12, 19, 15, '希西家在耶和华面前祷告，说：“耶和华以色列的神，坐在二基路伯中间的啊，只有你是地上万国的神，天地是你创造的。'),
('CNV', '列王纪下', 12, 19, 16, '耶和华啊！求你侧耳聆听；耶和华啊！求你睁眼垂顾；听那派使者来侮辱永活的神的西拿基立的话。'),
('CNV', '列王纪下', 12, 19, 17, '耶和华啊！亚述列王真的曾毁坏列国和它们的领土，'),
('CNV', '列王纪下', 12, 19, 18, '把它们的神丢进火里，但他们并不是神，不过是人手用木头、石头做成的，因此他们可以把他们除掉。'),
('CNV', '列王纪下', 12, 19, 19, '现在，耶和华我们的神啊，求你从他的手中把我们拯救出来，地上万国就可以知道只有你耶和华才是神。”'),
('CNV', '列王纪下', 12, 19, 20, '于是亚摩斯的儿子以赛亚派人去见希西家，说：“耶和华以色列的神这样说：‘你向我祷告有关亚述王西拿基立的事，我已经听见了。’'),
('CNV', '列王纪下', 12, 19, 21, '下面是耶和华所说关于他的话：‘锡安的居民藐视你，嗤笑你；耶路撒冷的居民在你背后摇头。'),
('CNV', '列王纪下', 12, 19, 22, '你辱骂了谁，亵渎了谁？你扬声攻击谁呢？你高举眼目是向谁傲慢呢？就是攻击以色列的圣者。'),
('CNV', '列王纪下', 12, 19, 23, '你藉着你的使者侮辱了我的主，你说─我要用大批的战车，攀登众山的高峰，到达黎巴嫩山的顶端，砍伐高大的香柏树，佳美的松木；我要进入极远的峰峦，最茂密的森林。'),
('CNV', '列王纪下', 12, 19, 24, '我掘井饮外地的水，我用脚掌踏干埃及所有的河道。'),
('CNV', '列王纪下', 12, 19, 25, '你没有听过吗？在远古我已决定，在古时我已筹划，现在我要实现，就是你使设防城变成乱堆。'),
('CNV', '列王纪下', 12, 19, 26, '他们的居民没有能力，惊惶、羞惭。他们好像田野的嫩草，青绿的蔬菜，和房顶上的草，还未长成就枯萎了。'),
('CNV', '列王纪下', 12, 19, 27, '你坐下，你出去，你进来，以及你对我所发的烈怒，我都知道。'),
('CNV', '列王纪下', 12, 19, 28, '因为你向我发了烈怒，你狂傲的话进入我的耳中，我要把我的钩子钩在你的鼻子上，把嚼环套在你的嘴上，使你在你来的路上转回去。'),
('CNV', '列王纪下', 12, 19, 29, '‘这要给你作一个征兆：这一年要吃自然生长的，第二年也要吃自己长出来的，第三年要撒种、收割，栽种葡萄园，吃它们的果子。'),
('CNV', '列王纪下', 12, 19, 30, '犹大家逃脱的余民，必再往下扎根，往上结果；'),
('CNV', '列王纪下', 12, 19, 31, '因为将有剩余的人从耶路撒冷出来，将有逃脱的人从锡安山而来，耶和华的热心必成全这事。'),
('CNV', '列王纪下', 12, 19, 32, '因此，耶和华论到亚述王这样说：他不会来到这城，不会在那里射箭，也不会拿着盾牌向城进攻，不会筑起土堆围攻它。'),
('CNV', '列王纪下', 12, 19, 33, '他必循他来的路回去，他必不能来到这城，这是耶和华的宣告。'),
('CNV', '列王纪下', 12, 19, 34, '为了我和我仆人大卫的缘故，我必保护这城，拯救这城。’”'),
('CNV', '列王纪下', 12, 19, 35, '那天晚上，耶和华的使者出去，在亚述军营杀了十八万五千人。早上，他们起来的时候，看哪，到处都是死尸。'),
('CNV', '列王纪下', 12, 19, 36, '于是亚述王西拿基立拔营离开，回去住在尼尼微。'),
('CNV', '列王纪下', 12, 19, 37, '一日，他正在他的神亚斯洛的庙中叩拜的时候，亚得米勒和沙利色用刀刺杀了他，然后逃到亚拉腊地。他的儿子以撒哈顿接续他作王。'),
('CNV', '列王纪下', 12, 20, 1, '在那些日子，希西家病得要死了。亚摩斯的儿子以赛亚先知来见他，对他说：“耶和华这样说：‘你要留遗命给你的家人，因为你将要死，不能再活了。’”'),
('CNV', '列王纪下', 12, 20, 2, '他却转脸向墙，祷告耶和华说：'),
('CNV', '列王纪下', 12, 20, 3, '“唉，耶和华啊！求你记念我曾怎样以真诚和完全的心在你面前行事为人，我所行的都是你看为善的事。”希西家就痛哭起来。'),
('CNV', '列王纪下', 12, 20, 4, '以赛亚还没有出到中院，耶和华的话就临到他说：'),
('CNV', '列王纪下', 12, 20, 5, '“你回去对我子民的君主希西家说：‘你祖大卫的神耶和华这样说：我听见了你的祷告，看见了你的眼泪。看哪，我必医治你，第三日你要上耶和华的殿。'),
('CNV', '列王纪下', 12, 20, 6, '我必把十五年的寿命增添给你。我要拯救你和这城脱离亚述王的手，又要因我自己和我仆人大卫的缘故保护这城。’”'),
('CNV', '列王纪下', 12, 20, 7, '以赛亚说：“取一片无花果饼来。”他们就取了来，把它贴在疮上。希西家就痊愈了。'),
('CNV', '列王纪下', 12, 20, 8, '希西家对以赛亚说：“有什么征兆告诉我耶和华必医治我，第三日我能上耶和华的殿呢？”'),
('CNV', '列王纪下', 12, 20, 9, '以赛亚说：“这就是耶和华给你的征兆，显明耶和华必成全他应许的这事：你要日影向前进十级或是倒退十级呢？”'),
('CNV', '列王纪下', 12, 20, 10, '希西家说：“日影延伸十级容易；不，我要日影倒后十级。”'),
('CNV', '列王纪下', 12, 20, 11, '以赛亚先知呼求耶和华，他就使日晷上的日影，就是在亚哈斯的日晷上已经下移的日影倒退了十级。'),
('CNV', '列王纪下', 12, 20, 12, '那时，巴比伦王巴拉但的儿子比罗达．巴拉但送信和礼物给希西家，因为他听见希西家病了。'),
('CNV', '列王纪下', 12, 20, 13, '希西家听了使者的话，随后把宝库内的一切银子、金子、香料、贵重的油和军器库，以及他宝库内一切所有的，都给他们看。无论是在他的宫中或是在全国各地的，希西家没有一样不给他们看的。'),
('CNV', '列王纪下', 12, 20, 14, '后来，以赛亚先知来到希西家王那里，对他说：“这些人说了些什么？他们是从哪里来见你的呢？”希西家说：“他们是从遥远的巴比伦来见我的。”'),
('CNV', '列王纪下', 12, 20, 15, '以赛亚说：“他们在你宫中看到了什么呢？”希西家说：“我宫中的一切，他们都看见了。在我宝库内的，我没有一样不给他们看的。”'),
('CNV', '列王纪下', 12, 20, 16, '以赛亚对希西家说：“你要听耶和华的话：'),
('CNV', '列王纪下', 12, 20, 17, '‘看哪，日子快到，那时你宫中的一切和你的祖先所积存直到今日的一切，都要被掠到巴比伦去，没有一样留下。’这是耶和华说的。'),
('CNV', '列王纪下', 12, 20, 18, '并且你的众子中，就是由你所出，你所生的，有一部分要被掳去。他们要在巴比伦王的王宫中当太监。”'),
('CNV', '列王纪下', 12, 20, 19, '希西家对以赛亚说：“你所说耶和华的话很好。”他心里说：“在我的日子有和平和安全不是很好吗？”'),
('CNV', '列王纪下', 12, 20, 20, '希西家其余的事迹和他所有的英勇事迹，以及他做水池和引水道，把水引入城里的事，不是都写在犹大列王的年代志上吗？'),
('CNV', '列王纪下', 12, 20, 21, '希西家和他的祖先一同长眠，他的儿子玛拿西就接续他作王。'),
('CNV', '列王纪下', 12, 21, 1, '玛拿西登基的时候是十二岁；他在耶路撒冷作王五十五年，他的母亲名叫协西巴。'),
('CNV', '列王纪下', 12, 21, 2, '他行耶和华看为恶的事，好像耶和华在以色列人面前赶走的民族所行的可憎恶的事。'),
('CNV', '列王纪下', 12, 21, 3, '他重新建造邱坛，就是他父亲希西家所拆毁的；又为巴力建立祭坛，做亚舍拉，好像以色列王亚哈所做的，并且敬拜事奉天上的万象。'),
('CNV', '列王纪下', 12, 21, 4, '他又在耶和华的殿内建造祭坛，耶和华曾指着这殿说：“我要立我的名在耶路撒冷。”'),
('CNV', '列王纪下', 12, 21, 5, '他又在耶和华殿的两院中为天上的万象建造祭坛。'),
('CNV', '列王纪下', 12, 21, 6, '他又把他的儿子用火烧为祭，并且算命、观兆，交鬼和行巫术；多行耶和华看为恶的事，惹他发怒。'),
('CNV', '列王纪下', 12, 21, 7, '他又把自己所做的亚舍拉雕像安放在圣殿中，耶和华曾对大卫和他的儿子所罗门论到这殿说：“我要在这殿和我从以色列众支派中拣选的耶路撒冷，立我的名，直到永远。'),
('CNV', '列王纪下', 12, 21, 8, '只要以色列人谨守遵行我吩咐他们的一切，就是我的仆人摩西吩咐他们的一切律法，我必不会再使他们的脚离开我赐给他们祖先的土地，流离飘荡。”'),
('CNV', '列王纪下', 12, 21, 9, '但是他们没有听从。玛拿西引诱他们去作坏事，比耶和华从以色列人面前消灭的外族人更厉害。'),
('CNV', '列王纪下', 12, 21, 10, '于是耶和华藉着他的仆人众先知说：'),
('CNV', '列王纪下', 12, 21, 11, '“因为犹大王玛拿西所作这些可憎恶的事，比在他以前的亚摩利人所行的恶更坏，并且以他的偶像使犹大人犯罪。'),
('CNV', '列王纪下', 12, 21, 12, '所以，耶和华以色列的神这样说：‘看哪，我要把灾祸降在耶路撒冷和犹大，使听见的人，双耳都要刺痛。'),
('CNV', '列王纪下', 12, 21, 13, '我要用量度撒玛利亚的准绳和测试亚哈家的铅锤，测量耶路撒冷；我要抹净耶路撒冷，像人抹净盘子一样。抹完了，就把盘子翻转过来。'),
('CNV', '列王纪下', 12, 21, 14, '我要舍弃我的产业的余民，把他们交在他们的仇敌手上；他们要成为他们的仇敌的掠物和战利品。'),
('CNV', '列王纪下', 12, 21, 15, '因为自从他们的祖先从埃及出来的那天，直到今日，他们一直行我看为恶的事，惹我发怒。’”'),
('CNV', '列王纪下', 12, 21, 16, '此外，玛拿西又流了许多无辜人的血，耶路撒冷，从这边直到那边，都满了血。这还是在他使犹大人犯罪，去行耶和华看为恶的事那罪之外。'),
('CNV', '列王纪下', 12, 21, 17, '玛拿西其余的事迹和他所行的一切，以及他所犯的众罪，不是都记录在犹大列王的年代志上吗？'),
('CNV', '列王纪下', 12, 21, 18, '玛拿西和他的祖先一同长眠，葬在他宫中的花园、乌撒的花园里；他的儿子亚们接续他作王。'),
('CNV', '列王纪下', 12, 21, 19, '亚们登基时是二十二岁；他在耶路撒冷作王二年。他母亲名叫米舒利密，来自约提巴，是哈鲁斯的女儿。'),
('CNV', '列王纪下', 12, 21, 20, '他行耶和华看为恶的事，好像他父亲玛拿西所行的。'),
('CNV', '列王纪下', 12, 21, 21, '他跟随他父亲所行的一切道路，服事他父亲所服事的偶像，敬拜它们。'),
('CNV', '列王纪下', 12, 21, 22, '他离弃耶和华他祖先的神，不跟随耶和华的道路。'),
('CNV', '列王纪下', 12, 21, 23, '亚们的臣仆阴谋背叛他，在王宫中把他杀死。'),
('CNV', '列王纪下', 12, 21, 24, '可是国民却击杀了所有阴谋背叛亚们王的人。国民立了他的儿子约西亚接续他作王。'),
('CNV', '列王纪下', 12, 21, 25, '亚们其余的事迹，就是他所行的一切，不是都记在犹大列王的年代志上吗？'),
('CNV', '列王纪下', 12, 21, 26, '他葬在乌撒园里他自己的坟墓中；他的儿子约西亚接续他作王。'),
('CNV', '列王纪下', 12, 22, 1, '约西亚登基的时候只有八岁。他在耶路撒冷作王共三十一年。他母亲名叫耶底大，是亚大雅的女儿，来自波斯加。'),
('CNV', '列王纪下', 12, 22, 2, '他行耶和华看为正的事，跟随他祖宗大卫所行的一切道路，不偏左右。'),
('CNV', '列王纪下', 12, 22, 3, '约西亚在位第十八年，王差派米书兰的孙子、亚萨利的儿子、书记沙番到耶和华的殿，吩咐他说：'),
('CNV', '列王纪下', 12, 22, 4, '“你上去到希勒家大祭司那里，叫他把献给耶和华殿的银子，就是守门的从人民所收集的，结算一下。'),
('CNV', '列王纪下', 12, 22, 5, '然后要他们把银子交到在耶和华殿管理工匠的人手中，他们可以把银子交付在耶和华殿修补破坏的地方的工匠，'),
('CNV', '列王纪下', 12, 22, 6, '就是交给木匠、建筑工人、石匠，又购买木材和凿好的石头，用来修理圣殿破坏的地方。'),
('CNV', '列王纪下', 12, 22, 7, '银子交在他们手中，不用和他们算帐，因为他们办事诚实。”'),
('CNV', '列王纪下', 12, 22, 8, '希勒家大祭司对书记沙番说：“我在耶和华的殿里找到了一卷律法书。”他把书卷交给沙番；沙番就阅读那书卷。'),
('CNV', '列王纪下', 12, 22, 9, '书记沙番来见王，向王回报说：“你的臣仆已经把殿里的银子清点，交在耶和华殿里管理工匠的人手中。”'),
('CNV', '列王纪下', 12, 22, 10, '书记沙番又告诉王说：“希勒家大祭司交给我一卷书卷。”书记沙番就在王面前诵读那书卷。'),
('CNV', '列王纪下', 12, 22, 11, '王听见律法书上的话的时候，就撕裂自己的衣服。'),
('CNV', '列王纪下', 12, 22, 12, '王又吩咐希勒家祭司、沙番的儿子亚希甘、米该亚的儿子亚革博、书记沙番和王的臣仆及亚撒雅说：'),
('CNV', '列王纪下', 12, 22, 13, '“你们去，为了我、为了人民、为了犹大全国，因着所发现的这书卷上的话求问耶和华，因为耶和华向我们所发的怒气极大；这是因着我们的祖先没有听从这律法书上的话，没有照着所有写给我们的去行。”'),
('CNV', '列王纪下', 12, 22, 14, '于是希勒家祭司、亚希甘、亚革博、沙番、亚撒雅去见女先知户勒大。她就是掌管礼服的沙龙的妻子，沙龙是哈珥哈斯的孙子、特瓦的儿子。她住在耶路撒冷第二区；他们就把事情都告诉了她。'),
('CNV', '列王纪下', 12, 22, 15, '她对他们说：“耶和华以色列的神这样说：‘告诉那差你们到我这里来的人说：'),
('CNV', '列王纪下', 12, 22, 16, '耶和华这样说：看哪，我要照着犹大王所念那书卷上所有的话，使灾祸降临在这地方和它的居民身上，'),
('CNV', '列王纪下', 12, 22, 17, '因为他们背弃了我，向别的神焚香。他们所行的一切都使我发怒，因此我的怒火要在这地方燃点，不会熄灭。'),
('CNV', '列王纪下', 12, 22, 18, '至于那差你们来求问耶和华的犹大王，你们要这样对他说：耶和华以色列的神这样说：有关你所听见的话，'),
('CNV', '列王纪下', 12, 22, 19, '你听见我攻击这地方和它的居民的话，就是他们要成为荒凉，受咒诅，你的心就顺服，在我面前谦卑，又撕裂自己的衣服，在我面前哀哭，我已经听到了。这是耶和华的宣告。'),
('CNV', '列王纪下', 12, 22, 20, '因此，看哪，我要使你归到你的祖先那里，你必平平安安地葬在你的坟墓里；你不会看见我要降在这地的一切灾祸。’”他们就把这话向王回报。'),
('CNV', '列王纪下', 12, 23, 1, '于是王派人召集犹大和耶路撒冷所有的长老到他那里。'),
('CNV', '列王纪下', 12, 23, 2, '王登上耶和华的殿，犹大众人、耶路撒冷所有的居民，还有祭司、先知和众民，不论大小，都一同前往。王就把在耶和华殿发现的约书所记的一切话都念给他们听。'),
('CNV', '列王纪下', 12, 23, 3, '王站在柱旁，在耶和华面前立约，要一心一意跟从耶和华，谨守他的诫命、典章和律例，实行这书上所写有关这约的话。众民都一同立约。'),
('CNV', '列王纪下', 12, 23, 4, '王吩咐希勒家大祭司、副祭司和守殿门的，把所有为巴力、亚舍拉和天上的万象所制造的器皿，从耶和华殿里搬出去，在耶路撒冷城外汲沦谷的田野，把它们烧了。然后把它们的灰烬带到伯特利去。'),
('CNV', '列王纪下', 12, 23, 5, '他废除了从前犹大列王所立、在犹大各城的邱坛，和耶路撒冷的周围焚香拜偶像的祭司。又废除向巴力、日、月、星辰和天上万象焚香的人。'),
('CNV', '列王纪下', 12, 23, 6, '他把亚舍拉像从耶和华殿里搬走，拿到耶路撒冷外的汲沦溪去，在汲沦溪把它烧毁，磨碎成灰，把灰撒在平民的坟墓上。'),
('CNV', '列王纪下', 12, 23, 7, '他拆毁在耶和华殿内男性庙妓的房屋，就是妇女为亚舍拉编织袍子的地方。'),
('CNV', '列王纪下', 12, 23, 8, '他又从犹大各城把祭司们召来，污秽祭司们焚香的邱坛，从迦巴直到别是巴。他又拆毁设在城门的邱坛，就是在市长约书亚门的出入处，在城门的左边。'),
('CNV', '列王纪下', 12, 23, 9, '但是邱坛的祭司不会登上在耶路撒冷耶和华的祭坛，他们只是在他们的兄弟中间吃无酵饼。'),
('CNV', '列王纪下', 12, 23, 10, '他又污秽在欣嫩子谷的陀斐特，不许人在那里将儿女焚烧献给摩洛。'),
('CNV', '列王纪下', 12, 23, 11, '他又除去犹大列王献给日头的马匹；这些马匹是在耶和华殿的入口处，靠近太监拿单．米勒在院子里的住宅。他又把献给日头的战车用火烧掉。'),
('CNV', '列王纪下', 12, 23, 12, '他又把亚哈斯的楼房顶上，犹大列王所做的祭坛，和玛拿西在耶和华殿的两院中所做的祭坛拆毁，就地打碎，把它们的灰尘倒进汲沦溪去。'),
('CNV', '列王纪下', 12, 23, 13, '在耶路撒冷东面、橄榄山南面的邱坛，就是以色列王所罗门为西顿人可憎的神亚斯他录、摩押人可憎的神基抹，和亚扪人可憎的神米勒公所筑的邱坛，王都污秽了。'),
('CNV', '列王纪下', 12, 23, 14, '他又打碎神柱，砍下亚舍拉，把死人的骨头布满那个地方。'),
('CNV', '列王纪下', 12, 23, 15, '此外，甚至在伯特利的祭坛和那使以色列人陷于罪中的尼八的儿子耶罗波安所做的邱坛，他都拆毁焚烧，压碎成灰，又把亚舍拉烧了。'),
('CNV', '列王纪下', 12, 23, 16, '约西亚转过身来，看见在山上的坟墓，于是派人把骨头从坟墓中取出来，烧在祭坛上，污秽它，就像神人从前所宣告的耶和华的话。'),
('CNV', '列王纪下', 12, 23, 17, '约西亚说：“我看见的这墓碑是谁的呢？”那城的人对他说：“这是以前从犹大来预告你在伯特利祭坛上所作的事的神人的坟墓。”'),
('CNV', '列王纪下', 12, 23, 18, '所以王说：“由他吧！不要让人动他的骨头。”于是他们没有碰他的骨头和那从撒玛利亚来的先知的骨头。'),
('CNV', '列王纪下', 12, 23, 19, '以色列诸王在撒玛利亚各城市建造，以致激怒耶和华的一切邱坛上的庙堂，约西亚都除去；他照着在伯特利所行的一切对付它们。'),
('CNV', '列王纪下', 12, 23, 20, '他又把所有邱坛的祭司都在祭坛上宰了。他把人的骨头烧在它们上面，然后回到耶路撒冷去了。'),
('CNV', '列王纪下', 12, 23, 21, '王又命令众民说：“照着这约书上所写的，守逾越节，记念耶和华你们的神。”'),
('CNV', '列王纪下', 12, 23, 22, '真的自从士师治理以色列的日子以来，以及以色列诸王和犹大列王所有的日子以来，没有守过像这次的逾越节的。'),
('CNV', '列王纪下', 12, 23, 23, '只有在约西亚王第十八年，在耶路撒冷守了这逾越节，记念耶和华。'),
('CNV', '列王纪下', 12, 23, 24, '约西亚也除去在犹大地和耶路撒冷所有招魂的、行巫术的、家神、偶像和一切可憎之物，为要实践希勒家祭司在耶和华殿里所寻得的书上所写律法的话。'),
('CNV', '列王纪下', 12, 23, 25, '在他以前没有王好像他按着摩西一切律法，全心、全性、全力归向耶和华；在他以后也没有兴起一个王好像他的。'),
('CNV', '列王纪下', 12, 23, 26, '但耶和华并没有把他向犹大所发的烈怒消除，因玛拿西种种的恶行激怒了他。'),
('CNV', '列王纪下', 12, 23, 27, '耶和华说：“我也要把犹大从我面前赶走，好像我把以色列除去一样。我要丢弃我所拣选的城市耶路撒冷，以及圣殿，我曾说：‘我的名必立在那里。’”'),
('CNV', '列王纪下', 12, 23, 28, '约西亚其余的事迹和他所行的一切，不是都写在犹大列王的年代志上吗？'),
('CNV', '列王纪下', 12, 23, 29, '在约西亚的日子，埃及王法老尼哥上来幼发拉底河帮助亚述王，约西亚王竟去迎战他，法老看见他的时候，就把他杀死在米吉多。'),
('CNV', '列王纪下', 12, 23, 30, '他的臣仆把他的尸体从米吉多用马车运载，送到耶路撒冷，把他埋葬在他自己的坟墓里。国民选举约西亚的儿子约哈斯，膏了他，立他接续他父亲作王。'),
('CNV', '列王纪下', 12, 23, 31, '约哈斯登基时是二十三岁，他在耶路撒冷作王三个月。他母亲名叫哈慕他，是立拿人耶利米的女儿。'),
('CNV', '列王纪下', 12, 23, 32, '他行耶和华看为恶的事，好像他的祖先所行的。'),
('CNV', '列王纪下', 12, 23, 33, '法老尼哥把他囚禁在哈马地的利比拉，使他不能在耶路撒冷作王；又罚了犹大国三千公斤银子和三十公斤金子。'),
('CNV', '列王纪下', 12, 23, 34, '法老尼哥另立约西亚的儿子以利雅敬接续他的父亲约西亚作王，改了他的名字作约雅敬。他俘掳了约哈斯，把他带到埃及，他就死在那里。'),
('CNV', '列王纪下', 12, 23, 35, '约雅敬把银子、金子付给法老；为了应付法老的命令，他向全国征收税银，按着他的评估，向每位国民索取金银，好付给法老尼哥。'),
('CNV', '列王纪下', 12, 23, 36, '约雅敬登基的时候是二十五岁，他在耶路撒冷作王十一年。他母亲名叫西布大，是鲁玛人毗大雅的女儿。'),
('CNV', '列王纪下', 12, 23, 37, '他行耶和华看为恶的事，好像他的祖先一切所行的。'),
('CNV', '列王纪下', 12, 24, 1, '约雅敬在位的时候，巴比伦王尼布甲尼撒来攻打他，约雅敬就臣服他三年，后来却反悔，背叛他。'),
('CNV', '列王纪下', 12, 24, 2, '耶和华差派迦勒底的军队、亚兰的军队、摩押的军队和亚扪人的军队攻打他，他差他们攻击犹大，毁灭它，就像耶和华藉着他的仆人众先知预言的话。'),
('CNV', '列王纪下', 12, 24, 3, '这事临到犹大完全是出于耶和华的命令，因着玛拿西的罪，就是他所行的一切，要把他们从自己面前赶走；'),
('CNV', '列王纪下', 12, 24, 4, '又因着他所流无辜人的血，他使耶路撒冷满了无辜人的血，耶和华决不赦免。'),
('CNV', '列王纪下', 12, 24, 5, '约雅敬其余的事迹和他所行的一切，不是都记在犹大列王的年代志上吗？'),
('CNV', '列王纪下', 12, 24, 6, '约雅敬和他的祖先一同长眠，他的儿子约雅斤接续他作王。'),
('CNV', '列王纪下', 12, 24, 7, '埃及王不再从本国出征，因为巴比伦王占据了所有从前属于埃及王的领土，从埃及小河直到幼发拉底河。'),
('CNV', '列王纪下', 12, 24, 8, '约雅斤登基的时候是十八岁，他在耶路撒冷作王三个月；他母亲名叫尼护施他，是耶路撒冷人以利拿单的女儿。'),
('CNV', '列王纪下', 12, 24, 9, '他行耶和华看为恶的事，好像他的祖先一切所行的。'),
('CNV', '列王纪下', 12, 24, 10, '那时，巴比伦王尼布甲尼撒的臣仆来到耶路撒冷，城就被围困。'),
('CNV', '列王纪下', 12, 24, 11, '尼布甲尼撒的臣仆正在围城的时候，巴比伦王尼布甲尼撒亲自来到耶路撒冷。'),
('CNV', '列王纪下', 12, 24, 12, '犹大王约雅斤和他的母亲、众臣仆、众领袖，以及众太监，出城投降巴比伦王。巴比伦王于是捉住他。那时，是巴比伦王在位第八年。'),
('CNV', '列王纪下', 12, 24, 13, '他又从耶路撒冷把耶和华殿一切宝物和王宫的宝物取去，并且把以色列王所罗门在耶和华殿所做的一切金器都捣毁，就像耶和华所说的。'),
('CNV', '列王纪下', 12, 24, 14, '他又掳去耶路撒冷的众民、众领袖，以及英勇的战士共一万人，还有工匠、铁匠；除了国民中最贫穷的以外，没有剩下的。'),
('CNV', '列王纪下', 12, 24, 15, '他把约雅斤掳到巴比伦去，又把太后、后妃、太监和国中的要员都从耶路撒冷掳到巴比伦；'),
('CNV', '列王纪下', 12, 24, 16, '还有七千位战士，一千位工匠和铁匠，全都是能作战的勇士，巴比伦王把他们都掳到巴比伦去。'),
('CNV', '列王纪下', 12, 24, 17, '巴比伦王立约雅斤的叔叔玛探雅接续他作王，并且把玛探雅的名字改为西底家。'),
('CNV', '列王纪下', 12, 24, 18, '西底家登基的时候是二十一岁，他在耶路撒冷作王十一年；他母亲名叫哈慕他，是立拿人耶利米的女儿。'),
('CNV', '列王纪下', 12, 24, 19, '他行耶和华眼中看为恶的事，像约雅敬一切所行的。'),
('CNV', '列王纪下', 12, 24, 20, '因为耶和华的怒气向耶路撒冷和犹大发作，直到他把他们从自己的面前赶走。后来，西底家背叛了巴比伦王。'),
('CNV', '列王纪下', 12, 25, 1, '西底家作王第九年十月十日，巴比伦王尼布甲尼撒率领他的全军来攻打耶路撒冷；他们在城外安营，又在四围筑垒攻城。'),
('CNV', '列王纪下', 12, 25, 2, '于是，城被围困，直到西底家王第十一年。'),
('CNV', '列王纪下', 12, 25, 3, '四月九日，城里饥荒非常严重，甚至那地的人民都断了粮食。'),
('CNV', '列王纪下', 12, 25, 4, '城终于被攻破了，所有的战士就在夜间从靠近王的花园的两墙中间的那门，逃跑出城。那时迦勒底人在四围攻城；他们就往亚拉巴的方向逃走。'),
('CNV', '列王纪下', 12, 25, 5, '迦勒底人的军队追赶王，在耶利哥的原野上把他追上了；他的全军都离开他四散了。'),
('CNV', '列王纪下', 12, 25, 6, '他们把王擒住，把他解到利比拉巴比伦王那里；他们就宣判他的罪。'),
('CNV', '列王纪下', 12, 25, 7, '他们又在西底家眼前杀了他的众子，并且把西底家的眼睛弄瞎，然后用铜链锁住他，把他带到巴比伦去。'),
('CNV', '列王纪下', 12, 25, 8, '五月七日，就是巴比伦王尼布甲尼撒第十九年，巴比伦王的大臣，护卫长尼布撒拉旦来到耶路撒冷。'),
('CNV', '列王纪下', 12, 25, 9, '他放火焚烧耶和华的殿和王宫，以及耶路撒冷一切房屋；一切高大的房屋，他都放火烧了。'),
('CNV', '列王纪下', 12, 25, 10, '跟随护卫长的迦勒底人全军拆毁了耶路撒冷周围的城墙。'),
('CNV', '列王纪下', 12, 25, 11, '至于城中剩下的人民，和已经向巴比伦王投降的人，以及剩下的民众，护卫长尼布撒拉旦都掳了去。'),
('CNV', '列王纪下', 12, 25, 12, '至于那地最贫穷的人，护卫长把他们留下，去修理葡萄园和耕种田地。'),
('CNV', '列王纪下', 12, 25, 13, '耶和华殿的铜柱，以及耶和华殿的铜座和铜海，迦勒底人都打碎了，把铜运到巴比伦去。'),
('CNV', '列王纪下', 12, 25, 14, '他们又把锅、铲子、烛剪、碟子和敬拜用的一切铜器都拿去了。'),
('CNV', '列王纪下', 12, 25, 15, '此外，火鼎和碗，无论是金的或是银的，护卫长都拿去了。'),
('CNV', '列王纪下', 12, 25, 16, '所罗门为耶和华殿所做的两根铜柱、一个铜海和十个铜座，这一切器皿的铜，重得无法可称。'),
('CNV', '列王纪下', 12, 25, 17, '铜柱每根高八公尺，柱上有铜柱头；柱头高一公尺三公寸，柱头四周有网子和石榴都是铜的；另一根柱子同样也有网子。'),
('CNV', '列王纪下', 12, 25, 18, '护卫长拿住祭司长西莱雅、副祭司长西番亚和三个守门的；'),
('CNV', '列王纪下', 12, 25, 19, '又从城里拿住一个管理军兵的官长，并且在城里搜获常见王面的五个人，和一个负责召募当地人民的军长书记，又在城中搜获六十个当地的人民。'),
('CNV', '列王纪下', 12, 25, 20, '护卫长尼布撒拉旦把他们拿住，带到利比拉巴比伦王那里。'),
('CNV', '列王纪下', 12, 25, 21, '巴比伦王击杀他们，在哈马地的利比拉把他们处死。这样，犹大人被掳，离开了他们的国土。'),
('CNV', '列王纪下', 12, 25, 22, '至于在犹大地剩下来的人民，就是巴比伦王尼布甲尼撒留下来的，巴比伦王委派沙番的孙子、亚希甘的儿子基大利管理他们。'),
('CNV', '列王纪下', 12, 25, 23, '众将领和他们的士兵，听见巴比伦王委派了基大利，他们就来到米斯巴去见基大利；其中有尼探雅的儿子以实玛利、加利亚的儿子约哈难、尼陀法人单户篾的儿子西莱雅、玛迦人的儿子雅撒尼亚，以及他们的士兵。'),
('CNV', '列王纪下', 12, 25, 24, '基大利向他们和他们的士兵起誓，又对他们说：“你们不必惧怕迦勒底的官员，只管住在这地，服事巴比伦王，就可以平安无事。”'),
('CNV', '列王纪下', 12, 25, 25, '但在七月的时候，王裔以利沙玛的孙子、尼探雅的儿子以实玛利，带了十个人和他一起，他们袭击基大利，把他杀死，和他一起在米斯巴的犹大人和迦勒底人，也被杀死。'),
('CNV', '列王纪下', 12, 25, 26, '因此，众民无论大小，以及众将领都起来逃往埃及去，因为他们惧怕迦勒底人。'),
('CNV', '列王纪下', 12, 25, 27, '犹大王约雅斤被掳后第三十七年，就是巴比伦王以未．米罗达登基的那一年，十二月二十七日，他恩待犹大王约雅斤，把他从狱中领出来，'),
('CNV', '列王纪下', 12, 25, 28, '并且安慰他，使他的地位高过和他一起在巴比伦的众王。'),
('CNV', '列王纪下', 12, 25, 29, '又换下他的囚衣，赐他终生常在王面前吃饭。'),
('CNV', '列王纪下', 12, 25, 30, '他的生活费用，在他一生的年日中，每日不断由王供应。'),
('CNV', '历代志上', 13, 1, 1, '亚当、塞特、以挪士、'),
('CNV', '历代志上', 13, 1, 2, '该南、玛勒列、雅列、'),
('CNV', '历代志上', 13, 1, 3, '以诺、玛土撒拉、拉麦、'),
('CNV', '历代志上', 13, 1, 4, '挪亚、挪亚生闪、含和雅弗。'),
('CNV', '历代志上', 13, 1, 5, '雅弗的儿子是歌篾、玛各、玛代、雅完、土巴、米设、提拉。'),
('CNV', '历代志上', 13, 1, 6, '歌篾的儿子是亚实基拿、低法、陀迦玛。'),
('CNV', '历代志上', 13, 1, 7, '雅完的儿子是以利沙、他施，基提人和多单人也是他的子孙。'),
('CNV', '历代志上', 13, 1, 8, '含的儿子是古实、埃及、弗和迦南。'),
('CNV', '历代志上', 13, 1, 9, '古实的儿子是西巴、哈腓拉、撒弗他、拉玛和撒弗提迦。拉玛的儿子是示巴和底但。'),
('CNV', '历代志上', 13, 1, 10, '古实又生宁录；宁录是世上第一位英雄。'),
('CNV', '历代志上', 13, 1, 11, '埃及生路低人、亚拿米人、利哈比人、拿弗土希人、'),
('CNV', '历代志上', 13, 1, 12, '帕斯鲁细人、迦斯路希人和迦斐托人；从迦斐托而出的有非利士人。'),
('CNV', '历代志上', 13, 1, 13, '迦南生了长子西顿，又生赫。'),
('CNV', '历代志上', 13, 1, 14, '他的子孙还有：耶布斯人、亚摩利人、革迦撒人、'),
('CNV', '历代志上', 13, 1, 15, '希未人、亚基人、西尼人、'),
('CNV', '历代志上', 13, 1, 16, '亚瓦底人、洗玛利人和哈马人。'),
('CNV', '历代志上', 13, 1, 17, '闪的儿子是以拦、亚述、亚法撒、路德、亚兰、亚兰的儿子是乌斯、户勒、基帖、米设。'),
('CNV', '历代志上', 13, 1, 18, '亚法撒生沙拉，沙拉生希伯。'),
('CNV', '历代志上', 13, 1, 19, '希伯生了两个儿子，一个名叫法勒，因为他在世的时候，世人就分散各地；法勒的兄弟名叫约坍。'),
('CNV', '历代志上', 13, 1, 20, '约坍生亚摩答、沙列、哈萨玛非、耶拉、'),
('CNV', '历代志上', 13, 1, 21, '哈多兰、乌萨、德拉、'),
('CNV', '历代志上', 13, 1, 22, '以巴录、亚比玛利、示巴、'),
('CNV', '历代志上', 13, 1, 23, '阿斐、哈腓拉、约巴。这些人都是约坍的儿子。'),
('CNV', '历代志上', 13, 1, 24, '闪、亚法撒、沙拉、'),
('CNV', '历代志上', 13, 1, 25, '希伯、法勒、拉吴、'),
('CNV', '历代志上', 13, 1, 26, '西鹿、拿鹤、他拉、'),
('CNV', '历代志上', 13, 1, 27, '亚伯兰，亚伯兰就是亚伯拉罕。'),
('CNV', '历代志上', 13, 1, 28, '亚伯拉罕的儿子是以撒和以实玛利。'),
('CNV', '历代志上', 13, 1, 29, '以下是他们的后代：以实玛利的长子是尼拜约，他其余的儿子是基达、押德别、米比衫、'),
('CNV', '历代志上', 13, 1, 30, '米施玛、度玛、玛撒、哈达、提玛、'),
('CNV', '历代志上', 13, 1, 31, '伊突、拿非施、基底玛；这些人都是以实玛利的儿子。'),
('CNV', '历代志上', 13, 1, 32, '亚伯拉罕的妾基土拉所生的儿子，就是心兰、约珊、米但、米甸、伊施巴、书亚。约珊的儿子是示巴和底但。'),
('CNV', '历代志上', 13, 1, 33, '米甸的儿子是以法、以弗、哈诺、亚比大、以勒大。这些人都是基土拉的子孙。'),
('CNV', '历代志上', 13, 1, 34, '亚伯拉罕生以撒。以撒的儿子是以扫和以色列。'),
('CNV', '历代志上', 13, 1, 35, '以扫的儿子是以利法、流珥、耶乌施、雅兰和可拉。'),
('CNV', '历代志上', 13, 1, 36, '以利法的儿子是提幔、阿抹、洗玻、迦坦、基纳斯、亭纳和亚玛力。'),
('CNV', '历代志上', 13, 1, 37, '流珥的儿子是拿哈、谢拉、沙玛和米撒。'),
('CNV', '历代志上', 13, 1, 38, '西珥的儿子是罗坍、朔巴、祭便、亚拿、底顺、以察和底珊。'),
('CNV', '历代志上', 13, 1, 39, '罗坍的儿子是何利、荷幔；罗坍的妹妹是亭纳。'),
('CNV', '历代志上', 13, 1, 40, '朔巴的儿子是亚勒、玛拿辖、以巴录、示非和阿南。祭便的儿子是亚雅和亚拿。'),
('CNV', '历代志上', 13, 1, 41, '亚拿的儿子是底顺。底顺的儿子是哈默兰、伊是班、益兰和基兰。'),
('CNV', '历代志上', 13, 1, 42, '以察的儿子是辟罕、撒番、耶亚干。底珊的儿子是乌斯和亚兰。'),
('CNV', '历代志上', 13, 1, 43, '以色列人没有君王统治的时候，在以东地作王的有以下这些人：比珥的儿子比拉，他的京城名叫亭哈巴。'),
('CNV', '历代志上', 13, 1, 44, '比拉死了，波斯拉人谢拉的儿子约巴接续他作王。'),
('CNV', '历代志上', 13, 1, 45, '约巴死了，来自提幔地的户珊接续他作王。'),
('CNV', '历代志上', 13, 1, 46, '户珊死了，比达的儿子哈达接续他作王；这哈达就是在摩押的田野击败了米甸人的，他的京城名叫亚未得。'),
('CNV', '历代志上', 13, 1, 47, '哈达死了，玛士利加人桑拉接续他作王。'),
('CNV', '历代志上', 13, 1, 48, '桑拉死了，来自幼发拉底河旁边的利河伯的扫罗接续他作王。'),
('CNV', '历代志上', 13, 1, 49, '扫罗死了，亚革波的儿子巴勒．哈南接续他作王。'),
('CNV', '历代志上', 13, 1, 50, '巴勒．哈南死了，哈达接续他作王，他的京城名叫巴伊；他的妻子名叫米希他别，是米．萨合的孙女、玛特列的女儿。'),
('CNV', '历代志上', 13, 1, 51, '哈达死了，以东人的族长有亭纳族长、亚勒瓦族长、耶帖族长、'),
('CNV', '历代志上', 13, 1, 52, '阿何利巴玛族长、以拉族长、比嫩族长、'),
('CNV', '历代志上', 13, 1, 53, '基纳斯族长、提幔族长、米比萨族长、'),
('CNV', '历代志上', 13, 1, 54, '玛基叠族长、以兰族长，这些人都是以东的族长。'),
('CNV', '历代志上', 13, 2, 1, '以色列的儿子是：流本、西缅、利未、犹大、以萨迦、西布伦、'),
('CNV', '历代志上', 13, 2, 2, '但、约瑟、便雅悯、拿弗他利、迦得和亚设。'),
('CNV', '历代志上', 13, 2, 3, '犹大的儿子是珥、俄南和示拉。这三人是迦南人书亚的女儿所生的。犹大的长子珥行耶和华看为恶的事，耶和华就使他死去。'),
('CNV', '历代志上', 13, 2, 4, '犹大的媳妇他玛，给犹大生了法勒斯和谢拉。犹大共有五个儿子。'),
('CNV', '历代志上', 13, 2, 5, '法勒斯的儿子是希斯仑和哈母勒。'),
('CNV', '历代志上', 13, 2, 6, '谢拉的儿子是心利、以探、希幔、甲各和大拉，共五人。'),
('CNV', '历代志上', 13, 2, 7, '迦米的儿子是亚干；这亚干偷取了当毁灭之物，连累了以色列人。'),
('CNV', '历代志上', 13, 2, 8, '以探的儿子是亚撒利雅。'),
('CNV', '历代志上', 13, 2, 9, '希斯仑所生的儿子是耶拉篾、兰和基路拜。'),
('CNV', '历代志上', 13, 2, 10, '兰生亚米拿达；亚米拿达生拿顺；拿顺是犹大人的领袖。'),
('CNV', '历代志上', 13, 2, 11, '拿顺生撒门；撒门生波阿斯。'),
('CNV', '历代志上', 13, 2, 12, '波阿斯生俄备得；俄备得生耶西。'),
('CNV', '历代志上', 13, 2, 13, '耶西生长子以利押、次子亚比拿达、三子示米亚、'),
('CNV', '历代志上', 13, 2, 14, '四子拿坦业、五子拉代、'),
('CNV', '历代志上', 13, 2, 15, '六子阿鲜、七子大卫。'),
('CNV', '历代志上', 13, 2, 16, '他们的姊妹是洗鲁雅和亚比该。洗鲁雅的儿子是亚比筛、约押和亚撒黑，共三人。'),
('CNV', '历代志上', 13, 2, 17, '亚比该生亚玛撒；亚玛撒的父亲是以实玛利人益帖。'),
('CNV', '历代志上', 13, 2, 18, '希斯仑的儿子迦勒与妻子阿苏巴生了儿子，也和耶略生了儿子；她的儿子是耶设、朔罢和押墩。'),
('CNV', '历代志上', 13, 2, 19, '阿苏巴死了，迦勒又娶以法他；以法他给他生了户珥。'),
('CNV', '历代志上', 13, 2, 20, '户珥生乌利；乌利生比撒列。'),
('CNV', '历代志上', 13, 2, 21, '后来希斯仑在六十岁的时候，娶了基列的父亲玛吉的女儿，与她同房，她就给他生了西割。'),
('CNV', '历代志上', 13, 2, 22, '西割生睚珥；睚珥在基列地有二十三座城。'),
('CNV', '历代志上', 13, 2, 23, '基述人和亚兰人却从他们那里夺取了睚珥的村镇，以及基纳和基纳的村庄，共六十座城。以上这些人都是基列的父亲玛吉的子孙。'),
('CNV', '历代志上', 13, 2, 24, '希斯仑在迦勒．以法他死后，他的妻子亚比雅给他生了亚施户；亚施户是提哥亚的父亲。'),
('CNV', '历代志上', 13, 2, 25, '希斯仑的长子耶拉篾的儿子是长子兰、布拿、阿连、阿鲜和亚希雅。'),
('CNV', '历代志上', 13, 2, 26, '耶拉篾另有一个妻子，名叫亚他拉，是阿南的母亲。'),
('CNV', '历代志上', 13, 2, 27, '耶拉篾的长子兰的儿子是玛斯、雅悯和以结。'),
('CNV', '历代志上', 13, 2, 28, '阿南的儿子是沙买和雅大；沙买的儿子是拿答和亚比述。'),
('CNV', '历代志上', 13, 2, 29, '亚比述的妻子名叫亚比孩；亚比孩给他生了亚办和摩利。'),
('CNV', '历代志上', 13, 2, 30, '拿答的儿子是西列和亚遍；西列死了，没有儿子。'),
('CNV', '历代志上', 13, 2, 31, '亚遍的儿子是以示；以示的儿子是示珊；示珊的儿子是亚来。'),
('CNV', '历代志上', 13, 2, 32, '沙买的兄弟雅大的儿子是益帖和约拿单；益帖死了，没有儿子。'),
('CNV', '历代志上', 13, 2, 33, '约拿单的儿子是比勒和撒萨。以上这些人都是耶拉篾的子孙。'),
('CNV', '历代志上', 13, 2, 34, '示珊没有儿子，只有女儿；示珊有一仆人，是埃及人，名叫耶哈。'),
('CNV', '历代志上', 13, 2, 35, '示珊把女儿嫁给仆人耶哈作妻子，她给耶哈生了亚太。'),
('CNV', '历代志上', 13, 2, 36, '亚太生拿单；拿单生撒拔。'),
('CNV', '历代志上', 13, 2, 37, '撒拔生以弗拉；以弗拉生俄备得。'),
('CNV', '历代志上', 13, 2, 38, '俄备得生耶户；耶户生亚撒利雅。'),
('CNV', '历代志上', 13, 2, 39, '亚撒利雅生希利斯；希利斯生以利亚萨。'),
('CNV', '历代志上', 13, 2, 40, '以利亚萨生西斯买；西斯买生沙龙。'),
('CNV', '历代志上', 13, 2, 41, '沙龙生耶加米雅；耶加米雅生以利沙玛。'),
('CNV', '历代志上', 13, 2, 42, '耶拉篾的兄弟迦勒的子孙如下：他的长子是米沙，是西弗的父亲；他的儿子是玛利沙，是希伯仑的父亲。'),
('CNV', '历代志上', 13, 2, 43, '希伯仑的儿子是可拉、他普亚、利肯和示玛。'),
('CNV', '历代志上', 13, 2, 44, '示玛生拉含，是约干的父亲；利肯生沙买。'),
('CNV', '历代志上', 13, 2, 45, '沙买的儿子是玛云；玛云是伯．夙的父亲。'),
('CNV', '历代志上', 13, 2, 46, '迦勒的妾以法生哈兰、摩撒和迦谢；哈兰生迦卸。'),
('CNV', '历代志上', 13, 2, 47, '雅代的儿子是利健、约坦、基珊、毗力、以法和沙亚弗。'),
('CNV', '历代志上', 13, 2, 48, '迦勒的妾玛迦生示别和特哈拿；'),
('CNV', '历代志上', 13, 2, 49, '又生麦玛拿的父亲沙亚弗、抹比拿的父亲和基比亚的父亲示法。迦勒的女儿是押撒。'),
('CNV', '历代志上', 13, 2, 50, '以上这些人是迦勒的子孙。以法他的长子户珥的儿子是基列．耶琳的父亲朔巴、'),
('CNV', '历代志上', 13, 2, 51, '伯利恒的父亲萨玛、伯迦得的父亲哈勒。'),
('CNV', '历代志上', 13, 2, 52, '基列．耶琳的父亲朔巴的子孙是哈罗以，以及半数米努．哈人。'),
('CNV', '历代志上', 13, 2, 53, '基列．耶琳的众家族是以帖人、布特人、舒玛人、密来人；从这些家族中又生出琐拉人和以实陶人。'),
('CNV', '历代志上', 13, 2, 54, '萨玛的子孙是伯利恒人、尼陀法人、亚他绿．伯．约押人、半数玛拿哈人、琐利人；'),
('CNV', '历代志上', 13, 2, 55, '住在雅比斯的经学家的众家族，有特拉人、示米押人和苏甲人。他们都是基尼人，是利甲家的祖先哈末的后代。'),
('CNV', '历代志上', 13, 3, 1, '大卫在希伯仑所生的儿子是：长子暗嫩，是耶斯列人亚希暖生的；次子但以利，是迦密人亚比该生的；'),
('CNV', '历代志上', 13, 3, 2, '三子押沙龙，是基述王达买的女儿玛迦生的；四子亚多尼雅，是哈及的儿子；'),
('CNV', '历代志上', 13, 3, 3, '五子示法提雅，是亚比他生的；六子以特念，是大卫的妻子以格拉生的。'),
('CNV', '历代志上', 13, 3, 4, '这六个儿子是大卫在希伯仑生的；大卫在希伯仑作王七年六个月；在耶路撒冷作王三十三年。'),
('CNV', '历代志上', 13, 3, 5, '大卫在耶路撒冷所生的儿子是：示米亚、朔罢、拿单、所罗门，这四个儿子是亚米利的女儿拔．书亚生的。'),
('CNV', '历代志上', 13, 3, 6, '还有益辖、以利沙玛、以利法列、'),
('CNV', '历代志上', 13, 3, 7, '挪迦、尼斐、雅非亚、'),
('CNV', '历代志上', 13, 3, 8, '以利沙玛、以利雅大、以利法列等九人。'),
('CNV', '历代志上', 13, 3, 9, '他们都是大卫的儿子，此外还有他们的妹妹他玛，以及妃嫔所生的儿子。'),
('CNV', '历代志上', 13, 3, 10, '所罗门的儿子是罗波安，罗波安的儿子是亚比雅，亚比雅的儿子是亚撒，亚撒的儿子是约沙法，'),
('CNV', '历代志上', 13, 3, 11, '约沙法的儿子是约兰，约兰的儿子是亚哈谢，亚哈谢的儿子是约阿施，'),
('CNV', '历代志上', 13, 3, 12, '约阿施的儿子是亚玛谢，亚玛谢的儿子是亚撒利雅，亚撒利雅的儿子是约坦，'),
('CNV', '历代志上', 13, 3, 13, '约坦的儿子是亚哈斯，亚哈斯的儿子是希西家，希西家的儿子是玛拿西，'),
('CNV', '历代志上', 13, 3, 14, '玛拿西的儿子是亚们，亚们的儿子是约西亚。'),
('CNV', '历代志上', 13, 3, 15, '约西亚的儿子是：长子约哈难、次子约雅敬、三子西底家、四子沙龙。'),
('CNV', '历代志上', 13, 3, 16, '约雅敬的儿子是耶哥尼雅和西底家。'),
('CNV', '历代志上', 13, 3, 17, '被掳的耶哥尼雅的儿子是撒拉铁、'),
('CNV', '历代志上', 13, 3, 18, '玛基兰、毗大雅、示拿萨、耶加米、何沙玛和尼大比雅。'),
('CNV', '历代志上', 13, 3, 19, '毗大雅的儿子是所罗巴伯和示每；所罗巴伯的儿子是米书兰和哈拿尼雅，还有他们的妹妹示罗密。'),
('CNV', '历代志上', 13, 3, 20, '又有哈舒巴、阿黑、比利家、哈撒底、于沙．希悉等五人。'),
('CNV', '历代志上', 13, 3, 21, '哈拿尼雅的儿子是毗拉提和耶筛亚；还有利法雅的众子、亚珥难的众子、俄巴底亚的众子和示迦尼的众子。'),
('CNV', '历代志上', 13, 3, 22, '示迦尼的子孙如下：示迦尼的儿子是示玛雅；示玛雅的儿子是哈突、以甲、巴利亚、尼利雅、沙法共六人。'),
('CNV', '历代志上', 13, 3, 23, '尼利雅的儿子是以利约乃、希西家、亚斯利干共三人。'),
('CNV', '历代志上', 13, 3, 24, '以利约乃的儿子是何大雅、以利雅实、毗莱雅、阿谷、约哈难、第来雅、阿拿尼共七人。'),
('CNV', '历代志上', 13, 4, 1, '犹大的儿子是法勒斯、希斯仑、迦米、户珥和朔巴。'),
('CNV', '历代志上', 13, 4, 2, '朔巴的儿子利亚雅生雅哈；雅哈生亚户买和拉哈。以上这些都是琐拉人的家族。'),
('CNV', '历代志上', 13, 4, 3, '以坦的儿子是：耶斯列、伊施玛、伊得巴；他们的妹妹名叫哈悉勒玻尼。'),
('CNV', '历代志上', 13, 4, 4, '基多的父亲是毗努伊勒；户沙的父亲是以谢珥；这些都是伯利恒的父亲以法他的长子户珥所生的。'),
('CNV', '历代志上', 13, 4, 5, '提哥亚的父亲亚施户有两个妻子，就是希拉和拿拉。'),
('CNV', '历代志上', 13, 4, 6, '拿拉给亚施户生了亚户撒、希弗、提米尼、哈辖斯他利；这些人都是拿拉的儿子。'),
('CNV', '历代志上', 13, 4, 7, '希拉的儿子是洗列、琐辖和伊提南。'),
('CNV', '历代志上', 13, 4, 8, '哥斯生亚诺、琐比巴和哈仑的儿子亚哈黑的众家族。'),
('CNV', '历代志上', 13, 4, 9, '雅比斯在众兄弟中最受人尊重，他母亲给他起名叫雅比斯，意思说：“我生产时十分痛苦。”'),
('CNV', '历代志上', 13, 4, 10, '雅比斯呼求以色列的神说：“深愿你大大地赐福给我，扩张我的境界，你的能力常与我同在，保护我免遭灾祸，不受痛苦。”神就应允了他所求的。'),
('CNV', '历代志上', 13, 4, 11, '书哈的兄弟基绿生米黑；米黑是伊施屯的父亲。'),
('CNV', '历代志上', 13, 4, 12, '伊施屯生伯拉巴、巴西亚和珥拿辖的父亲提欣拿；这些都是利迦人。'),
('CNV', '历代志上', 13, 4, 13, '基纳斯的儿子是俄陀聂和西莱雅；俄陀聂的儿子是哈塔和悯挪太。'),
('CNV', '历代志上', 13, 4, 14, '悯挪太生俄弗拉。西莱雅生革．夏纳欣人的祖先约押；他们原是匠人。'),
('CNV', '历代志上', 13, 4, 15, '耶孚尼的儿子是迦勒；迦勒的儿子是以路、以拉和拿安；以拉的儿子是基纳斯。'),
('CNV', '历代志上', 13, 4, 16, '耶哈利勒的儿子是西弗、西法、提利和亚撒列。')
on conflict (version, book, chapter, verse) do update set text = excluded.text;
